#!/usr/bin/env bash
set -euo pipefail
command -v node >/dev/null 2>&1 || { echo 'Node.js is required.' >&2; exit 1; }
node <<'AF_CLASSROOM_SIDEBAR_NODE'
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const files={"src/app/chemistry/nuclear/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useMemo, useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { EvidencePanel } from '@/components/chemistry/EvidencePanel';\nimport { NuclideChart } from '@/components/chemistry/NuclideChart';\nimport { DecayCurve } from '@/components/chemistry/DecayCurve';\nimport {\n  AVOGADRO, MODE_LABEL, MODE_SHORT, SEC, applyDecay, balance, decayConstant, fmtNum, fmtTime, followChain, hints, label,\n  lookup, nameOf, parseEquation, plainLabel, remainingFraction, sideText, symbolOf, timeToFraction,\n  type Mode, type TimeUnit,\n} from '@/lib/chemistry/nuclear';\nimport { ELEMENTS } from '@/lib/chemistry/elements';\n\nconst MODES: Mode[] = ['A', 'B-', 'B+', 'EC', 'P', 'N', 'G'];\nconst NUCLIDE_PRESETS: [string, number, number][] = [\n  ['U-238', 92, 238], ['C-14', 6, 14], ['K-40', 19, 40], ['Co-60', 27, 60], ['F-18', 9, 18], ['Rn-222', 86, 222], ['Cs-137', 55, 137], ['H-3', 1, 3], ['n', 0, 1],\n];\nconst EQ_EXAMPLES: [string, string][] = [\n  ['U-235 fission', 'U-235 + n -> Ba-141 + Kr-92 + 3 n'],\n  ['D–T fusion', 'H-2 + H-3 -> He-4 + n'],\n  ['α decay', 'U-238 -> Th-234 + alpha'],\n  ['β⁻ decay', 'C-14 -> N-14 + e- + anti-nu'],\n  ['β⁺ decay', 'Na-22 -> Ne-22 + e+ + nu'],\n  ['Electron capture', 'Be-7 + e- -> Li-7 + nu'],\n  ['Missing antineutrino', 'C-14 -> N-14 + e-'],\n];\nconst UNITS: TimeUnit[] = ['us', 'ms', 's', 'min', 'h', 'd', 'y'];\nconst UNIT_LABEL: Record<TimeUnit, string> = { us: 'µs', ms: 'ms', s: 's', min: 'min', h: 'h', d: 'days', y: 'years' };\n\nfunction bestUnit(sec: number): { value: number; unit: TimeUnit } {\n  for (const u of [...UNITS].reverse()) if (sec >= SEC[u]) return { value: Number((sec / SEC[u]).toPrecision(4)), unit: u };\n  return { value: Number((sec / SEC.us).toPrecision(4)), unit: 'us' };\n}\n\nconst Row = ({ k, v }: { k: string; v: React.ReactNode }) => (\n  <div className=\"flex justify-between gap-3 border-b border-gray-100 py-1.5 text-xs last:border-0\"><dt className=\"text-gray-500\">{k}</dt><dd className=\"text-right font-medium text-gray-900\">{v}</dd></div>\n);\nconst Card = ({ children, title }: { children: React.ReactNode; title?: string }) => (\n  <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">{title && <h2 className=\"mb-3 text-sm font-semibold text-gray-900\">{title}</h2>}{children}</div>\n);\n\nfunction BalanceTable({ bal }: { bal: ReturnType<typeof balance> }) {\n  const rows: [string, 'A' | 'Z' | 'L'][] = [['Nucleon number A', 'A'], ['Charge Z (in e)', 'Z'], ['Lepton number L', 'L']];\n  return (\n    <table className=\"w-full text-xs\">\n      <thead className=\"text-[10px] uppercase tracking-wide text-gray-400\"><tr><th className=\"py-1 text-left font-medium\">Conserved</th><th className=\"text-right font-medium\">Left</th><th className=\"text-right font-medium\">Right</th><th className=\"w-8\" /></tr></thead>\n      <tbody>\n        {rows.map(([name, k]) => (\n          <tr key={k} className=\"border-t border-gray-100\">\n            <td className=\"py-1.5 text-gray-600\">{name}</td>\n            <td className=\"text-right font-mono text-gray-900\">{bal.left[k]}</td>\n            <td className=\"text-right font-mono text-gray-900\">{bal.right[k]}</td>\n            <td className={`text-right font-semibold ${bal.ok[k] ? 'text-emerald-600' : 'text-red-600'}`} aria-label={bal.ok[k] ? 'conserved' : 'not conserved'}>{bal.ok[k] ? '✓' : '✗'}</td>\n          </tr>\n        ))}\n      </tbody>\n    </table>\n  );\n}\n\nexport default function NuclearPage() {\n  const [nuc, setNuc] = useState({ z: 92, a: 238 });\n  const [modeState, setModeState] = useState<{ key: string; mode: Mode } | null>(null);\n  const [custom, setCustom] = useState<{ key: string; value: number; unit: TimeUnit } | null>(null);\n  const [amountKind, setAmountKind] = useState<'mass' | 'atoms'>('mass');\n  const [amount, setAmount] = useState(1);\n  const [time, setTime] = useState(1);\n  const [timeUnit, setTimeUnit] = useState<TimeUnit>('y');\n  const [targetPct, setTargetPct] = useState(25);\n  const [eq, setEq] = useState(EQ_EXAMPLES[0][1]);\n\n  const { z, a } = nuc;\n  const key = `${z}-${a}`;\n  const ref = lookup(z, a);\n  const hint = hints(z, a);\n  const nameText = z === 0 ? 'Free neutron' : `${nameOf(z)}-${a}`;\n\n  const defaultMode: Mode = ref?.modes[0]?.mode ?? (hint.delta < -0.9 ? 'B-' : hint.delta > 0.9 ? 'B+' : z >= 83 ? 'A' : 'B-');\n  const mode = modeState?.key === key ? modeState.mode : defaultMode;\n  const decay = applyDecay(z, a, mode);\n  const chain = followChain(z, a);\n  const reported = ref?.modes.find(m => m.mode === mode);\n  const daughterRef = decay.daughter ? lookup(decay.daughter.z, decay.daughter.a) : undefined;\n\n  // Half-life lab\n  const refHL = ref?.t ?? null;\n  const refBest = refHL ? bestUnit(refHL) : null;\n  const hlValue = custom?.key === key ? custom.value : refBest?.value ?? 1;\n  const hlUnit = custom?.key === key ? custom.unit : refBest?.unit ?? 'y';\n  const T = custom?.key === key ? custom.value * SEC[custom.unit] : refHL;\n  const tSec = time * SEC[timeUnit];\n  const lab = (() => {\n    if (!T || T <= 0 || !(tSec >= 0)) return null;\n    const f = remainingFraction(tSec, T);\n    const n0 = amountKind === 'atoms' ? amount : (amount / a) * AVOGADRO; // molar mass ≈ A g/mol\n    const n = n0 * f;\n    const lambda = decayConstant(T);\n    const frac = Math.min(Math.max(targetPct / 100, 1e-12), 1);\n    return { f, n0, n, lambda, act0: lambda * n0, act: lambda * n, massLeft: (n / AVOGADRO) * a, tTarget: timeToFraction(frac, T), tHalf: tSec / T };\n  })();\n\n  const parsed = useMemo(() => parseEquation(eq), [eq]);\n  const eqBal = useMemo(() => (parsed.errors.length ? null : balance(parsed.left, parsed.right)), [parsed]);\n\n  const choose = (zz: number, aa: number) => setNuc({ z: zz, a: Math.max(aa, zz, 1) });\n  const setMode = (m: Mode) => setModeState({ key, mode: m });\n\n  useTopicPreset(\"chemistry-nuclear\", { \"targetPct\": setTargetPct }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <div className=\"mx-auto max-w-7xl px-4 py-6 sm:px-6\">\n          <Link href=\"/chemistry\" className=\"text-xs text-gray-400 transition hover:text-indigo-600\">← Chemistry</Link>\n          <h1 className=\"mt-1 text-xl font-semibold text-gray-900 sm:text-2xl\">Nuclear playground</h1>\n          <p className=\"mb-5 mt-1 text-sm text-gray-500\">Chemistry rearranges electrons; nuclear processes change the nucleus. Pick a nuclide, test decay modes against the conservation laws, and run the decay law. Balance tells you a process is <span className=\"font-medium text-gray-700\">allowed by the bookkeeping</span> — not that it happens.</p>\n\n          <SimulationStage className=\"grid grid-cols-1 gap-5 lg:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)]\">\n            <div data-stage-role=\"canvas\" className=\"min-w-0 space-y-5\">\n              <Card>\n                <NuclideChart selected={nuc} daughter={decay.daughter} onSelect={choose} />\n              </Card>\n\n              <Card title=\"Decay chain (bundled reference data)\">\n                <div className=\"flex flex-wrap items-center gap-1.5 text-xs\">\n                  {chain.steps.map((s, i) => (\n                    <span key={i} className=\"flex items-center gap-1.5\">\n                      <button type=\"button\" onClick={() => choose(s.z, s.a)} className={`rounded-md border px-2 py-1 ${s.z === z && s.a === a ? 'border-indigo-600 bg-indigo-50 text-indigo-800' : 'border-gray-200 text-gray-700 hover:border-indigo-300'}`}>\n                        <span className=\"font-semibold\">{label(s.z, s.a)}</span>\n                        {s.t !== null && <span className=\"ml-1 text-[10px] text-gray-400\">{fmtTime(s.t)}</span>}\n                      </button>\n                      {s.mode && <span className=\"text-[11px] text-gray-400\">{MODE_SHORT[s.mode]} →</span>}\n                    </span>\n                  ))}\n                </div>\n                <p className=\"mt-2 text-[11px] text-gray-500\">\n                  {chain.end === 'stable' && `Ends at a stable nuclide after ${chain.steps.length - 1} step${chain.steps.length === 2 ? '' : 's'}.`}\n                  {chain.end === 'unknown' && 'The chain stops where the bundled table has no entry — the nuclide may be stable or simply not listed here.'}\n                  {chain.end === 'invalid' && 'The chain stops because the next daughter would not be a valid nucleus.'}\n                  {chain.end === 'limit' && 'Stopped after 30 steps.'} Each step follows only the dominant reported mode; branching is ignored.\n                </p>\n              </Card>\n\n              <Card title=\"Nuclear equation checker\">\n                <div className=\"mb-2 flex flex-wrap gap-2\">\n                  {EQ_EXAMPLES.map(([t, v]) => <button key={t} type=\"button\" onClick={() => setEq(v)} className=\"rounded-full border border-gray-200 px-2.5 py-1 text-[11px] text-gray-700 hover:border-indigo-300 hover:text-indigo-700\">{t}</button>)}\n                </div>\n                <label className=\"sr-only\" htmlFor=\"eq\">Nuclear equation</label>\n                <input id=\"eq\" value={eq} onChange={e => setEq(e.target.value)} spellCheck={false} className=\"h-10 w-full rounded-lg border border-gray-200 px-3 font-mono text-sm\" placeholder=\"U-235 + n -> Ba-141 + Kr-92 + 3 n\" />\n                <p className=\"mt-1 text-[11px] text-gray-400\">Write nuclides as U-235, 235U or ²³⁵U; particles as n, p, alpha, e-, e+, nu, anti-nu, gamma, d, t.</p>\n                {parsed.errors.length > 0 ? (\n                  <ul className=\"mt-3 space-y-1 rounded-lg bg-amber-50 px-3 py-2 text-xs text-amber-900\">{parsed.errors.map(e => <li key={e}>{e}</li>)}</ul>\n                ) : eqBal && (\n                  <div className=\"mt-3\">\n                    <div className=\"rounded-lg bg-gray-50 px-3 py-2 text-center text-base text-gray-900\">{sideText(parsed.left)} → {sideText(parsed.right)}</div>\n                    <div className=\"mt-3\"><BalanceTable bal={eqBal} /></div>\n                    <p className={`mt-3 rounded-lg px-3 py-2 text-xs ${eqBal.balanced ? 'bg-emerald-50 text-emerald-900' : 'bg-red-50 text-red-800'}`}>\n                      {eqBal.balanced ? 'Balanced: nucleon number, charge and lepton number are all conserved. Energy (Q-value) is not checked.' : `Not balanced: ${[!eqBal.ok.A && 'nucleon number', !eqBal.ok.Z && 'charge', !eqBal.ok.L && 'lepton number'].filter(Boolean).join(', ')} not conserved.`}\n                    </p>\n                  </div>\n                )}\n              </Card>\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"min-w-0 space-y-5\">\n              <Card>\n                <div className=\"flex flex-wrap gap-2\">\n                  {NUCLIDE_PRESETS.map(([t, zz, aa]) => <button key={t} type=\"button\" onClick={() => choose(zz, aa)} className={`rounded-full border px-2.5 py-1 text-[11px] ${z === zz && a === aa ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 bg-white text-gray-700 hover:border-indigo-300'}`}>{t}</button>)}\n                </div>\n                <div className=\"mt-3 flex gap-2\">\n                  <label className=\"flex-1 text-[11px] text-gray-500\">Element\n                    <select value={z} onChange={e => choose(Number(e.target.value), a)} className=\"mt-1 h-8 w-full rounded-md border border-gray-200 bg-white px-2 text-sm\">\n                      <option value={0}>n — Neutron</option>\n                      {ELEMENTS.map(el => <option key={el.z} value={el.z}>{el.symbol} — {el.name} (Z={el.z})</option>)}\n                    </select>\n                  </label>\n                  <label className=\"w-24 text-[11px] text-gray-500\">Mass no. A\n                    <input type=\"number\" min={Math.max(1, z)} max={300} value={a} onChange={e => choose(z, Math.round(Number(e.target.value)) || 1)} className=\"mt-1 h-8 w-full rounded-md border border-gray-200 px-2 text-sm\" />\n                  </label>\n                </div>\n                <div className=\"mt-4 flex items-baseline gap-3\">\n                  <span className=\"text-4xl font-semibold text-gray-900\">{label(z, a)}</span>\n                  <span className=\"text-sm text-gray-500\">{nameText}</span>\n                </div>\n                <dl className=\"mt-2\">\n                  <Row k=\"Protons / neutrons\" v={`${z} / ${a - z}`} />\n                  <Row k=\"N/Z\" v={z ? (((a - z) / z)).toFixed(2) : '—'} />\n                  {ref ? <>\n                    <Row k=\"Half-life\" v={ref.t === null ? 'Stable (observationally)' : fmtTime(ref.t)} />\n                    <Row k=\"Reported decay\" v={ref.modes.length ? ref.modes.map(m => `${MODE_SHORT[m.mode]}${m.pct ? ` ${m.pct}%` : ''}`).join(', ') : '—'} />\n                  </> : <Row k=\"Reference data\" v=\"None bundled\" />}\n                </dl>\n                {ref?.note && <p className=\"mt-1 text-[11px] text-gray-500\">{ref.note}</p>}\n                {!ref && <p className=\"mt-2 rounded-lg bg-amber-50 px-3 py-2 text-[11px] text-amber-900\">No half-life or decay mode is bundled for {plainLabel(z, a)}. Look it up in NUBASE / ENSDF (e.g. NNDC NuDat or the IAEA Live Chart of Nuclides) before relying on any value. The rule-of-thumb hint below is not data.</p>}\n                <p className=\"mt-3 text-[11px] leading-relaxed text-gray-500\"><span className=\"font-medium text-gray-700\">Rule of thumb:</span> {hint.lines.join(' ')} <span className=\"text-gray-400\">(stability line at Z ≈ {hint.zs.toFixed(1)} for A = {a})</span></p>\n              </Card>\n\n              <Card title=\"Decay explorer\">\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {MODES.map(m => <button key={m} type=\"button\" onClick={() => setMode(m)} className={`rounded-md border px-2.5 py-1 text-xs ${mode === m ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 text-gray-700 hover:border-indigo-300'}`} title={MODE_LABEL[m]}>{MODE_SHORT[m]}</button>)}\n                </div>\n                <p className=\"mt-1 text-[11px] text-gray-400\">{MODE_LABEL[mode]}</p>\n                <div className=\"mt-3 rounded-lg bg-gray-50 px-3 py-3 text-center text-base text-gray-900\" aria-live=\"polite\">{sideText(decay.left)} → {sideText(decay.right)}</div>\n                {decay.issues.length > 0 && <ul className=\"mt-2 space-y-1 rounded-lg bg-red-50 px-3 py-2 text-xs text-red-800\">{decay.issues.map(i => <li key={i}>{i}</li>)}</ul>}\n                <div className=\"mt-3\"><BalanceTable bal={decay.bal} /></div>\n                <div className=\"mt-3 space-y-1.5 text-[11px] leading-relaxed\">\n                  <p className={`rounded-lg px-3 py-2 ${reported ? 'bg-emerald-50 text-emerald-900' : 'bg-gray-50 text-gray-700'}`}>\n                    {reported ? `${MODE_SHORT[mode]} is a reported decay mode of ${plainLabel(z, a)}${reported.pct ? ` (≈ ${reported.pct}% branch)` : ''}.`\n                      : ref ? (ref.t === null ? `${plainLabel(z, a)} is listed as stable, so this decay is not observed — it balances on paper only.` : `${MODE_SHORT[mode]} is not a reported mode for ${plainLabel(z, a)} in the bundled table.`)\n                      : 'No reference data for this nuclide, so there is nothing to compare this mode against.'}\n                  </p>\n                  <p className=\"px-1 text-gray-500\">Conservation laws are necessary, not sufficient: the decay must also release energy (Q &gt; 0), which is not computed here.</p>\n                </div>\n                {decay.daughter && (\n                  <button type=\"button\" onClick={() => choose(decay.daughter!.z, decay.daughter!.a)} className=\"mt-3 rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">\n                    Go to daughter {plainLabel(decay.daughter.z, decay.daughter.a)}{daughterRef ? (daughterRef.t === null ? ' (stable)' : ` (${fmtTime(daughterRef.t)})`) : ''} →\n                  </button>\n                )}\n              </Card>\n\n              <Card title=\"Half-life lab\">\n                <div className=\"grid grid-cols-2 gap-3 text-[11px] text-gray-500\">\n                  <div className=\"col-span-2\">Half-life\n                    <div className=\"mt-1 flex gap-2\">\n                      <input type=\"number\" min={0} step=\"any\" value={hlValue} onChange={e => setCustom({ key, value: Number(e.target.value), unit: hlUnit })} className=\"h-8 w-full rounded-md border border-gray-200 px-2 text-sm text-gray-900\" aria-label=\"Half-life value\" />\n                      <select value={hlUnit} onChange={e => setCustom({ key, value: hlValue, unit: e.target.value as TimeUnit })} className=\"h-8 rounded-md border border-gray-200 bg-white px-2 text-sm text-gray-900\" aria-label=\"Half-life unit\">{UNITS.map(u => <option key={u} value={u}>{UNIT_LABEL[u]}</option>)}</select>\n                    </div>\n                    <span className=\"mt-1 block text-gray-400\">{custom?.key === key ? 'Your value. ' : refHL ? 'From the bundled reference. ' : 'No bundled value — enter one. '}{custom?.key === key && refHL ? <button type=\"button\" className=\"text-indigo-600 hover:underline\" onClick={() => setCustom(null)}>Reset to reference</button> : null}</span>\n                  </div>\n                  <div>Initial amount\n                    <div className=\"mt-1 flex gap-1.5\">\n                      <input type=\"number\" min={0} step=\"any\" value={amount} onChange={e => setAmount(Number(e.target.value))} className=\"h-8 w-full rounded-md border border-gray-200 px-2 text-sm text-gray-900\" aria-label=\"Initial amount\" />\n                      <select value={amountKind} onChange={e => setAmountKind(e.target.value as 'mass' | 'atoms')} className=\"h-8 rounded-md border border-gray-200 bg-white px-1 text-sm text-gray-900\"><option value=\"mass\">g</option><option value=\"atoms\">atoms</option></select>\n                    </div>\n                  </div>\n                  <div>Elapsed time\n                    <div className=\"mt-1 flex gap-1.5\">\n                      <input type=\"number\" min={0} step=\"any\" value={time} onChange={e => setTime(Number(e.target.value))} className=\"h-8 w-full rounded-md border border-gray-200 px-2 text-sm text-gray-900\" aria-label=\"Elapsed time\" />\n                      <select value={timeUnit} onChange={e => setTimeUnit(e.target.value as TimeUnit)} className=\"h-8 rounded-md border border-gray-200 bg-white px-1 text-sm text-gray-900\">{UNITS.map(u => <option key={u} value={u}>{UNIT_LABEL[u]}</option>)}</select>\n                    </div>\n                  </div>\n                </div>\n\n                {!lab ? (\n                  <p className=\"mt-3 rounded-lg bg-amber-50 px-3 py-2 text-xs text-amber-900\">Enter a positive half-life and a non-negative time to run the decay law.</p>\n                ) : (\n                  <>\n                    <div className=\"mt-3\"><DecayCurve tHalf={lab.tHalf} /></div>\n                    <dl className=\"mt-3\">\n                      <Row k=\"Elapsed\" v={`${fmtNum(lab.tHalf, 4)} half-lives`} />\n                      <Row k=\"Fraction remaining N/N₀\" v={`${fmtNum(lab.f, 4)} (${fmtNum(lab.f * 100, 4)} %)`} />\n                      <Row k=\"Nuclei remaining\" v={fmtNum(lab.n, 4)} />\n                      <Row k=\"Mass remaining (≈ A g/mol)\" v={`${fmtNum(lab.massLeft, 4)} g`} />\n                      <Row k=\"Decay constant λ\" v={`${fmtNum(lab.lambda, 4)} s⁻¹`} />\n                      <Row k=\"Activity now / initially\" v={`${fmtNum(lab.act, 4)} / ${fmtNum(lab.act0, 4)} Bq`} />\n                    </dl>\n                    <div className=\"mt-3 flex flex-wrap items-center gap-2 text-xs text-gray-600\">\n                      Time until\n                      <input type=\"number\" min={0.0001} max={100} step=\"any\" value={targetPct} onChange={e => setTargetPct(Number(e.target.value))} className=\"h-7 w-20 rounded-md border border-gray-200 px-2 text-sm\" aria-label=\"Percent remaining\" />\n                      % remains:\n                      <span className=\"font-semibold text-gray-900\">{targetPct > 0 && targetPct <= 100 ? fmtTime(lab.tTarget) : '—'}</span>\n                    </div>\n                    <p className=\"mt-2 text-[11px] text-gray-400\">N = N₀·2^(−t/T½) for a single nuclide with no ingrowth from parents. Mass uses A g/mol as the molar mass.</p>\n                  </>\n                )}\n              </Card>\n\n              <EvidencePanel\n                candidate=\"You chose this nuclide, decay mode or equation. Writing a balanced equation does not mean the process is observed.\"\n                rule={{ label: `Conservation of nucleon number, charge and lepton number (${decay.bal.balanced ? 'balanced for the selected decay' : 'check the selected decay'}). Rule-of-thumb stability hints are not data.`, ok: decay.bal.balanced }}\n                database={{ state: ref ? 'warn' : 'no', text: ref ? 'Half-life and decay modes come from a small hand-bundled table of ~70 well-known nuclides, rounded. Verify against NUBASE / ENSDF before quoting.' : 'No bundled data for this nuclide. Check NUBASE / ENSDF (NNDC NuDat, IAEA Live Chart).' }}\n                calculated={{ state: 'no', text: 'No Q-values, binding energies or branching ratios are computed; only the decay law is evaluated.' }}\n              />\n              <p className=\"px-1 text-[10px] text-gray-400\">Symbol check: {symbolOf(z)} · units of the decay lab convert with 1 y = 365.25 d.</p>\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/chemistry/periodic-table/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { PeriodicTable } from '@/components/chemistry/PeriodicTable';\nimport { ElementDetails } from '@/components/chemistry/ElementDetails';\nimport { BY_SYMBOL, type Element } from '@/lib/chemistry/elements';\n\nexport default function PeriodicTablePage() {\n  const [sel, setSel] = useState<Element>(BY_SYMBOL['Na']);\n  const [sheet, setSheet] = useState(false);\n  const pick = (e: Element) => { setSel(e); if (!document.querySelector('[data-simulation-stage][data-expanded=\"true\"]')) setSheet(true); };\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <div className=\"mx-auto max-w-7xl px-4 py-6 sm:px-6\">\n          <Link href=\"/chemistry\" className=\"text-xs text-gray-400 transition hover:text-indigo-600\">← Chemistry</Link>\n          <h1 className=\"mt-1 text-xl font-semibold text-gray-900 sm:text-2xl\">Periodic table</h1>\n          <p className=\"mb-5 mt-1 text-sm text-gray-500\">Select an element to see its configuration and oxidation states.</p>\n          <SimulationStage className=\"grid grid-cols-1 gap-5 lg:grid-cols-[minmax(0,1fr)_320px]\">\n            <div data-stage-role=\"canvas\" className=\"min-w-0 rounded-2xl border border-gray-200 bg-white p-3 sm:p-4\"><PeriodicTable onPick={pick} selected={sel.symbol} listMaxHeight=\"calc(100vh - 21rem)\" /></div>\n            {/* Large screens: details beside the table */}\n            <div data-stage-role=\"parameters\" className=\"hidden min-w-0 lg:block\"><ElementDetails el={sel} /></div>\n          </SimulationStage>\n        </div>\n\n        {/* Small screens: details slide up as a sheet so they are never off-screen */}\n        {sheet && (\n          <div className=\"fixed inset-0 z-40 lg:hidden\" role=\"dialog\" aria-modal=\"true\" aria-label={`${sel.name} details`}>\n            <button type=\"button\" className=\"absolute inset-0 bg-black/30\" onClick={() => setSheet(false)} aria-label=\"Close details\" />\n            <div className=\"absolute inset-x-0 bottom-0 max-h-[78vh] overflow-y-auto rounded-t-3xl bg-white p-3 pb-6 shadow-2xl\" style={{ paddingBottom: 'max(1.5rem, env(safe-area-inset-bottom))' }}>\n              <div className=\"mx-auto mb-2 h-1 w-10 rounded-full bg-gray-300\" />\n              <ElementDetails el={sel} />\n              <button type=\"button\" onClick={() => setSheet(false)} className=\"mt-3 h-11 w-full rounded-xl border border-gray-200 text-sm font-medium text-gray-700\">Close</button>\n            </div>\n          </div>\n        )}\n      </main>\n    </>\n  );\n}\n", "src/app/chemistry/crystal-builder/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useMemo, useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { CrystalViewer, type SiteStyle } from '@/components/chemistry/CrystalViewer';\nimport { EvidencePanel } from '@/components/chemistry/EvidencePanel';\nimport { CandidatesPanel } from '@/components/chemistry/CandidatesPanel';\nimport { ELEMENTS, BY_SYMBOL } from '@/lib/chemistry/elements';\nimport { molarMass, reduce } from '@/lib/chemistry/compound';\nimport { withBoundaryImages, fmtCharge, type Site } from '@/lib/chemistry/perovskite';\nimport {\n  PROTOTYPES, PROTO_ORDER, analyseCrystal, cellAtoms, crystalCif, geometry, type ProtoId, type Role,\n} from '@/lib/chemistry/crystal';\nimport { saveCandidate, download, type Candidate } from '@/lib/chemistry/candidates';\n\nconst ROLE_COLOR: Record<Role, string> = { A: '#f59e0b', X: '#818cf8' };\ntype Els = Record<Role, string>;\n\ninterface Preset { label: string; proto: ProtoId; el: Els; a: number; note: string }\nconst PRESETS: Preset[] = [\n  { label: 'NaCl', proto: 'rocksalt', el: { A: 'Na', X: 'Cl' }, a: 5.64, note: 'The textbook rocksalt structure; note the computed density against the ≈ 2.16 g/cm³ usually quoted.' },\n  { label: 'MgO', proto: 'rocksalt', el: { A: 'Mg', X: 'O' }, a: 4.21, note: 'Rocksalt oxide.' },\n  { label: 'CsCl', proto: 'cscl', el: { A: 'Cs', X: 'Cl' }, a: 4.12, note: 'Eight-fold coordination: the large Cs⁺ ion gives a radius ratio near 0.92.' },\n  { label: 'ZnS', proto: 'zincblende', el: { A: 'Zn', X: 'S' }, a: 5.41, note: 'Zincblende (sphalerite) form of ZnS; ZnS also exists as hexagonal wurtzite, which this builder does not draw.' },\n  { label: 'GaAs', proto: 'zincblende', el: { A: 'Ga', X: 'As' }, a: 5.65, note: 'A covalent III–V semiconductor in the zincblende structure — the radius-ratio rule is for ionic solids, so ignore it here.' },\n  { label: 'CaF₂', proto: 'fluorite', el: { A: 'Ca', X: 'F' }, a: 5.46, note: 'Fluorite: Ca²⁺ is 8-coordinate, F⁻ 4-coordinate.' },\n  { label: 'Li₂O', proto: 'fluorite', el: { A: 'O', X: 'Li' }, a: 4.62, note: 'Antifluorite (roles swapped). A good example where the radius-ratio rule predicts octahedral Li⁺ but the real structure is tetrahedral.' },\n  { label: 'Cu', proto: 'fcc', el: { A: 'Cu', X: 'Cu' }, a: 3.61, note: 'Close-packed fcc metal.' },\n  { label: 'Fe (bcc)', proto: 'bcc', el: { A: 'Fe', X: 'Fe' }, a: 2.87, note: 'Room-temperature α-iron is bcc.' },\n  { label: 'Si', proto: 'diamond', el: { A: 'Si', X: 'Si' }, a: 5.43, note: 'Diamond cubic silicon.' },\n  { label: 'Po (sc)', proto: 'sc', el: { A: 'Po', X: 'Po' }, a: 3.35, note: 'α-polonium is the rare example of a simple cubic element.' },\n  { label: 'Cu₃Au', proto: 'cu3au', el: { A: 'Au', X: 'Cu' }, a: 3.75, note: 'An ordered fcc alloy at low temperature; it disorders on heating.' },\n];\n\nfunction ElementSelect({ label, color, value, onChange }: { label: string; color: string; value: string; onChange: (s: string) => void }) {\n  return (\n    <div className=\"min-w-0 rounded-xl border border-gray-200 p-3\">\n      <div className=\"flex items-center gap-1.5 text-[11px] font-medium text-gray-500\"><span className=\"inline-block h-2.5 w-2.5 rounded-full\" style={{ background: color }} />{label}</div>\n      <select value={value} onChange={e => onChange(e.target.value)} className=\"mt-2 h-9 w-full rounded-md border border-gray-200 bg-white px-2 text-sm\" aria-label={label}>\n        {ELEMENTS.filter(x => x.z <= 103).map(x => <option key={x.symbol} value={x.symbol}>{x.symbol} — {x.name}</option>)}\n      </select>\n    </div>\n  );\n}\n\nexport default function CrystalBuilderPage() {\n  const [pid, setPid] = useState<ProtoId>(PRESETS[0].proto);\n  const [el, setEl] = useState<Els>(PRESETS[0].el);\n  const [a, setA] = useState(PRESETS[0].a);\n  const [note, setNote] = useState<string | null>(PRESETS[0].note);\n  const [n, setN] = useState(1);\n  const [bonds, setBonds] = useState(true);\n  const [cell, setCell] = useState(true);\n  const [saved, setSaved] = useState(false);\n\n  const proto = PROTOTYPES[pid];\n  const binary = proto.roles.length === 2;\n  const effEl: Els = binary ? el : { A: el.A, X: el.A };\n  const geo = geometry(proto);\n  const rep = analyseCrystal(proto, effEl, a);\n\n  const atoms = useMemo(() => withBoundaryImages(cellAtoms(proto).map(x => ({ site: x.site, frac: x.frac })), n), [proto, n]);\n  const styles = (() => {\n    const out: Partial<Record<Site, SiteStyle>> = {};\n    proto.sublattices.forEach(s => {\n      const sym = effEl[s.role];\n      out[s.site] = { label: sym, color: ROLE_COLOR[s.role], radius: 0.075 + 0.012 * BY_SYMBOL[sym].period };\n    });\n    return out;\n  })();\n  const siteNames = Object.fromEntries(proto.sublattices.map(s => [s.site, s.name])) as Partial<Record<Site, string>>;\n\n  const loadPreset = (p: Preset) => { setPid(p.proto); setEl(p.el); setA(p.a); setNote(p.note); setSaved(false); };\n  const setRole = (r: Role, s: string) => { setEl(e => ({ ...e, [r]: s })); setNote(null); setSaved(false); };\n  const changeProto = (id: ProtoId) => { setPid(id); setNote(null); setSaved(false); };\n\n  const onSave = () => {\n    saveCandidate({\n      name: `${rep.formula} (${proto.label.split(' (')[0]})`, kind: 'crystal', formula: rep.formula, composition: reduce(rep.composition),\n      molarMass: molarMass(reduce(rep.composition)), chargeStatus: rep.charge?.status ?? 'single element',\n      crystal: { prototype: pid, elements: effEl, a, density: rep.density }, note: note ?? undefined,\n    });\n    setSaved(true);\n  };\n  const onLoad = (c: Candidate) => {\n    if (c.crystal) { setPid(c.crystal.prototype as ProtoId); setEl(c.crystal.elements as Els); setA(c.crystal.a); setNote(c.note ?? null); }\n  };\n\n  const groups = ['Elements', 'AX compounds', 'AX₂ compounds', 'Ordered alloys'] as const;\n  const rr = rep.radius;\n\n  useTopicPreset(\"chemistry-crystal-builder\", { \"a\": setA }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <div className=\"mx-auto max-w-7xl px-4 py-6 sm:px-6\">\n          <Link href=\"/chemistry\" className=\"text-xs text-gray-400 transition hover:text-indigo-600\">← Chemistry</Link>\n          <h1 className=\"mt-1 text-xl font-semibold text-gray-900 sm:text-2xl\">Crystal builder</h1>\n          <p className=\"mb-4 mt-1 text-sm text-gray-500\">Choose a cubic prototype, assign elements and a lattice parameter, and read off coordination, density and packing. These are <span className=\"font-medium text-gray-700\">computed from the geometry</span>; they don’t show that a material adopts that structure.</p>\n\n          <div className=\"mb-4 flex flex-wrap gap-2\">\n            {PRESETS.map(p => <button key={p.label} type=\"button\" onClick={() => loadPreset(p)} className=\"rounded-full border border-gray-200 bg-white px-3 py-1 text-xs text-gray-700 transition hover:border-indigo-300 hover:text-indigo-700\">{p.label}</button>)}\n          </div>\n          {note && <p className=\"mb-5 rounded-xl border border-indigo-100 bg-indigo-50 px-3 py-2 text-xs text-indigo-900\">{note} <span className=\"opacity-70\">Lattice parameters are approximate literature values — check the primary source before citing.</span></p>}\n\n          <SimulationStage className=\"grid grid-cols-1 gap-5 lg:grid-cols-[minmax(0,1.3fr)_minmax(0,1fr)]\">\n            <div data-stage-role=\"canvas\" className=\"min-w-0 space-y-5\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <CrystalViewer atoms={atoms} extent={n} styles={styles} siteNames={siteNames} bondDist={geo.nn} bondMode=\"nn\" sizeScale={0.85} sizeNote=\"atom size shows period only\" showBonds={bonds} showCell={cell} showA />\n                <div className=\"mt-3 flex flex-wrap items-center gap-x-4 gap-y-2 border-t border-gray-100 pt-3 text-xs text-gray-600\">\n                  <label className=\"flex items-center gap-1.5\"><input type=\"checkbox\" checked={bonds} onChange={e => setBonds(e.target.checked)} />Nearest-neighbour bonds</label>\n                  <label className=\"flex items-center gap-1.5\"><input type=\"checkbox\" checked={cell} onChange={e => setCell(e.target.checked)} />Cell edges</label>\n                  <span className=\"ml-auto flex items-center gap-1.5\">Cells\n                    {[1, 2].map(v => <button key={v} type=\"button\" onClick={() => setN(v)} className={`rounded-md border px-2 py-0.5 ${n === v ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 hover:border-indigo-300'}`}>{v}×{v}×{v}</button>)}\n                  </span>\n                </div>\n                <p className=\"mt-2 text-[11px] text-gray-400\">{proto.label} · {proto.spaceGroup}. {proto.note}</p>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                <h2 className=\"mb-3 text-sm font-semibold text-gray-900\">Compare the prototypes <span className=\"font-normal text-gray-400\">(computed from each geometry)</span></h2>\n                <div className=\"overflow-x-auto\">\n                  <table className=\"w-full min-w-[460px] text-left text-xs\">\n                    <thead className=\"text-[10px] uppercase tracking-wide text-gray-400\"><tr><th className=\"py-1 pr-2 font-medium\">Prototype</th><th className=\"pr-2 font-medium\">Atoms / cell</th><th className=\"pr-2 font-medium\">Type</th><th className=\"pr-2 font-medium\">Coordination</th><th className=\"font-medium\">NN dist.</th></tr></thead>\n                    <tbody>\n                      {PROTO_ORDER.map(id => {\n                        const g = geometry(PROTOTYPES[id]);\n                        return (\n                          <tr key={id} className={`border-t border-gray-100 ${id === pid ? 'bg-indigo-50/60' : ''}`}>\n                            <td className=\"py-1.5 pr-2\"><button type=\"button\" onClick={() => changeProto(id)} className=\"text-left font-medium text-gray-900 hover:text-indigo-700\">{PROTOTYPES[id].label}</button></td>\n                            <td className=\"pr-2 text-gray-700\">{g.atomsPerCell}</td>\n                            <td className=\"pr-2 text-gray-700\">{g.stoich}</td>\n                            <td className=\"pr-2 text-gray-700\">{g.coordination.map(c => `${c.role} ${c.total}`).join(' · ')}</td>\n                            <td className=\"text-gray-700\">{g.nn.toFixed(3)} a</td>\n                          </tr>\n                        );\n                      })}\n                    </tbody>\n                  </table>\n                </div>\n              </div>\n              <CandidatesPanel onLoad={onLoad} />\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"min-w-0 space-y-5\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                <label className=\"text-[11px] font-medium uppercase tracking-wide text-gray-400\" htmlFor=\"proto\">Prototype</label>\n                <select id=\"proto\" value={pid} onChange={e => changeProto(e.target.value as ProtoId)} className=\"mt-1 h-9 w-full rounded-md border border-gray-200 bg-white px-2 text-sm\">\n                  {groups.map(g => <optgroup key={g} label={g}>{PROTO_ORDER.filter(id => PROTOTYPES[id].group === g).map(id => <option key={id} value={id}>{PROTOTYPES[id].label}</option>)}</optgroup>)}\n                </select>\n\n                <div className=\"mt-3 grid gap-3 sm:grid-cols-2\">\n                  <ElementSelect label={binary ? 'A element' : 'Element'} color={ROLE_COLOR.A} value={el.A} onChange={s => setRole('A', s)} />\n                  {binary && <ElementSelect label=\"X element\" color={ROLE_COLOR.X} value={el.X} onChange={s => setRole('X', s)} />}\n                </div>\n\n                <div className=\"mt-4 text-[11px] font-medium uppercase tracking-wide text-gray-400\">Candidate</div>\n                <div className=\"text-3xl font-semibold text-gray-900\" aria-live=\"polite\">{rep.formula}</div>\n                <div className=\"text-xs text-gray-500\">{geo.atomsPerCell} atoms per cubic cell · {geo.stoich === 'A' ? 'one element' : `AX type ${geo.stoich}`}</div>\n\n                <div className=\"mt-3 flex items-center gap-2 text-xs\">\n                  <label htmlFor=\"a\" className=\"font-medium text-gray-500\">Lattice parameter a (Å)</label>\n                  <input id=\"a\" type=\"number\" step={0.01} min={1.5} max={12} value={a} onChange={e => { setA(Number(e.target.value) || 5); setSaved(false); }} className=\"h-8 w-24 rounded-md border border-gray-200 px-2 text-sm\" />\n                </div>\n                <p className=\"mt-1 text-[11px] text-gray-400\">Preset values are approximate literature numbers. For a new combination this is a placeholder you set — not a prediction.</p>\n\n                <dl className=\"mt-3 divide-y divide-gray-100 text-xs\">\n                  {geo.coordination.filter(c => binary || c.role === 'A').map(c => (\n                    <div key={c.role} className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Coordination of {binary ? `${effEl[c.role]} (${c.role})` : effEl.A}</dt><dd className=\"font-medium text-gray-900\">{c.total}{c.like > 0 && c.unlike > 0 ? ` (${c.unlike} unlike + ${c.like} like)` : ''}</dd></div>\n                  ))}\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Nearest-neighbour distance</dt><dd className=\"font-medium text-gray-900\">{rep.nnAngstrom.toFixed(3)} Å</dd></div>\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Density</dt><dd className=\"font-medium text-gray-900\">{rep.density.toFixed(3)} g/cm³</dd></div>\n                  {rep.packing != null && <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Packing fraction (ideal hard spheres)</dt><dd className=\"font-medium text-gray-900\">{rep.packing.toFixed(4)}</dd></div>}\n                </dl>\n\n                {rep.charge && (\n                  <div className={`mt-3 rounded-lg px-3 py-2 text-[11px] leading-relaxed ${rep.charge.status === 'balanced' ? 'bg-emerald-50 text-emerald-900' : 'bg-amber-50 text-amber-900'}`}>\n                    <span className=\"font-medium\">Charge balance.</span> {rep.charge.message}\n                    {rep.charge.solutions[0] && <span className=\"mt-0.5 block font-mono\">{Object.entries(rep.charge.solutions[0].states).map(([s, q]) => `${s}${fmtCharge(q)}`).join('  ')}</span>}\n                  </div>\n                )}\n                {rr && (\n                  <div className={`mt-2 rounded-lg px-3 py-2 text-[11px] leading-relaxed ${rr.consistent ? 'bg-emerald-50 text-emerald-900' : 'bg-amber-50 text-amber-900'}`}>\n                    <span className=\"font-medium\">Radius-ratio rule.</span> r(cation)/r(anion) = {rr.cationRadius.toFixed(2)}/{rr.anionRadius.toFixed(2)} = {rr.ratio.toFixed(3)}, which suggests {rr.expectedCN}-fold coordination ({rr.expectedText}); this prototype has {rr.actualCN}. {rr.consistent ? 'Consistent.' : 'Not consistent — the rule has many exceptions (covalent character, polarisation), so this does not rule the structure out.'}\n                  </div>\n                )}\n\n                <div className=\"mt-4 flex flex-wrap gap-2\">\n                  <button type=\"button\" onClick={onSave} className=\"rounded-lg bg-indigo-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-indigo-700\">{saved ? 'Saved ✓' : 'Save candidate'}</button>\n                  <button type=\"button\" onClick={() => download(`${rep.formula}-${pid}-proposed.cif`, crystalCif(proto, effEl, a, rep.formula), 'chemical/x-cif')} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">Download CIF (proposed)</button>\n                  <Link href={`/chemistry/compound-builder?c=${Object.entries(rep.composition).map(([s, c]) => `${s}:${c}`).join(',')}`} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">Open in builder →</Link>\n                </div>\n              </div>\n              <EvidencePanel\n                rule={{ label: rep.charge ? (rep.charge.status === 'balanced' ? 'Charges can balance' : rep.charge.message) + (rr ? `; radius ratio ${rr.ratio.toFixed(2)} ${rr.consistent ? 'matches' : 'does not match'} this prototype.` : '.') : 'Single element — no charge check; geometry only.', ok: rep.charge ? (rep.charge.status === 'balanced' && (rr ? rr.consistent : true)) : null }}\n                extra={proto.label}\n                calculated={{ state: 'warn', text: 'Only simple geometric quantities (coordination, density, packing) from the prototype and your lattice parameter. No energies or relaxation.' }}\n                database={{ state: 'no', text: 'Not checked. Compare with a structure database (e.g. ICSD, Crystallography Open Database, Materials Project) before saying a compound adopts this structure.' }}\n              />\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/chemistry/perovskite-lab/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useEffect, useMemo, useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { CrystalViewer, type SiteStyle } from '@/components/chemistry/CrystalViewer';\nimport { EvidencePanel } from '@/components/chemistry/EvidencePanel';\nimport { CandidatesPanel } from '@/components/chemistry/CandidatesPanel';\nimport { ELEMENTS, BY_SYMBOL } from '@/lib/chemistry/elements';\nimport { molarMass, formulaOf, formulaPlain } from '@/lib/chemistry/compound';\nimport {\n  MODELS, RADII_A_XII, RADII_B_VI, RADII_X_VI, analyseModel, availableStates, density, key,\n  toCif, withBoundaryImages, type ModelId, type Site, type ModelSites,\n} from '@/lib/chemistry/perovskite';\nimport { saveCandidate, download, type Candidate } from '@/lib/chemistry/candidates';\n\ntype SiteKey = 'A' | 'B' | 'B2' | 'X';\ntype Pick = { symbol: string; charge: number };\ntype Sites = Record<SiteKey, Pick>;\n\nconst TABLE: Record<SiteKey, Record<string, number>> = { A: RADII_A_XII, B: RADII_B_VI, B2: RADII_B_VI, X: RADII_X_VI };\nconst SITE_NAME: Record<SiteKey, string> = { A: 'A site (12-coordinate)', B: 'B site (octahedral)', B2: 'B′ site (octahedral)', X: 'X site (anion)' };\nconst COLORS: Record<SiteKey, string> = { A: '#f59e0b', B: '#818cf8', B2: '#2dd4bf', X: '#f87171' };\n\ninterface Preset { label: string; model: ModelId; sites: Sites; note: string }\nconst p = (symbol: string, charge: number): Pick => ({ symbol, charge });\nconst PRESETS: Preset[] = [\n  { label: 'NaMgBr₃', model: 'cubic', sites: { A: p('Na', 1), B: p('Mg', 2), B2: p('Ag', 1), X: p('Br', -1) },\n    note: 'Your research candidate. Assembling the formula asserts nothing about stability; the geometric factors below are only a first screen.' },\n  { label: 'CsPbBr₃', model: 'cubic', sites: { A: p('Cs', 1), B: p('Pb', 2), B2: p('Ag', 1), X: p('Br', -1) },\n    note: 'Well-studied halide perovskite; reported cubic only at elevated temperature, distorted (orthorhombic) at room temperature. Verify in the literature.' },\n  { label: 'CsSnI₃', model: 'cubic', sites: { A: p('Cs', 1), B: p('Sn', 2), B2: p('Ag', 1), X: p('I', -1) },\n    note: 'Reported perovskite with tin(II), which oxidises readily; distorted at room temperature. Verify in the literature.' },\n  { label: 'SrTiO₃', model: 'cubic', sites: { A: p('Sr', 2), B: p('Ti', 4), B2: p('Ag', 1), X: p('O', -2) },\n    note: 'The textbook cubic oxide perovskite at room temperature — a good sanity check for t ≈ 1.' },\n  { label: 'BaTiO₃', model: 'cubic', sites: { A: p('Ba', 2), B: p('Ti', 4), B2: p('Ag', 1), X: p('O', -2) },\n    note: 'Cubic only above its Curie temperature; ferroelectric and non-cubic at room temperature.' },\n  { label: 'CaTiO₃', model: 'cubic', sites: { A: p('Ca', 2), B: p('Ti', 4), B2: p('Ag', 1), X: p('O', -2) },\n    note: 'The mineral perovskite: a tilted orthorhombic structure, so the cubic model here is only the idealised parent.' },\n  { label: 'KMgF₃', model: 'cubic', sites: { A: p('K', 1), B: p('Mg', 2), B2: p('Ag', 1), X: p('F', -1) },\n    note: 'Fluoroperovskite reported with a cubic structure; a useful comparison for NaMgBr₃ (same B cation, different A and X).' },\n  { label: 'NaMgF₃', model: 'cubic', sites: { A: p('Na', 1), B: p('Mg', 2), B2: p('Ag', 1), X: p('F', -1) },\n    note: 'Reported as a tilted orthorhombic perovskite; compare its t with NaMgBr₃ to see the effect of swapping F for Br.' },\n  { label: 'Cs₂AgBiBr₆', model: 'double', sites: { A: p('Cs', 1), B: p('Ag', 1), B2: p('Bi', 3), X: p('Br', -1) },\n    note: 'Lead-free double perovskite reported in the literature, with rock-salt B/B′ ordering.' },\n];\n\nfunction fromQuery(): Partial<Sites> | null {\n  const q = new URLSearchParams(window.location.search);\n  const out: Partial<Sites> = {};\n  (['A', 'B', 'X'] as const).forEach(k => {\n    const sym = q.get(k);\n    if (sym && BY_SYMBOL[sym]) {\n      const tab = availableStates(sym, k);\n      const e = BY_SYMBOL[sym];\n      const fallback = k === 'X' ? e.common.find(v => v < 0) : e.common.find(v => v > 0);\n      out[k] = { symbol: sym, charge: tab[0] ?? fallback ?? (k === 'X' ? -1 : 1) };\n    }\n  });\n  return Object.keys(out).length ? out : null;\n}\n\nfunction SitePicker({ site, value, onChange }: { site: SiteKey; value: Pick; onChange: (v: Pick) => void }) {\n  const kind: 'A' | 'B' | 'X' = site === 'B2' ? 'B' : site;\n  const withData = ELEMENTS.filter(e => availableStates(e.symbol, kind).length > 0);\n  const others = ELEMENTS.filter(e => availableStates(e.symbol, kind).length === 0);\n  const el = BY_SYMBOL[value.symbol];\n  const wantNeg = kind === 'X';\n  const states = Array.from(new Set([\n    ...availableStates(value.symbol, kind),\n    ...[...el.common, ...el.other].filter(v => (wantNeg ? v < 0 : v > 0)),\n  ])).sort((a, b) => b - a);\n  const r = TABLE[site][key(value.symbol, value.charge)];\n  const pickEl = (sym: string) => {\n    const e = BY_SYMBOL[sym];\n    const tab = availableStates(sym, kind);\n    const fb = (wantNeg ? e.common.find(v => v < 0) : e.common.find(v => v > 0)) ?? (wantNeg ? -1 : 1);\n    onChange({ symbol: sym, charge: tab.includes(value.charge) ? value.charge : tab[0] ?? fb });\n  };\n  return (\n    <div className=\"rounded-xl border border-gray-200 p-3\">\n      <div className=\"flex items-center gap-1.5 text-[11px] font-medium text-gray-500\">\n        <span className=\"inline-block h-2.5 w-2.5 rounded-full\" style={{ background: COLORS[site] }} />{SITE_NAME[site]}\n      </div>\n      <div className=\"mt-2 flex gap-2\">\n        <select value={value.symbol} onChange={e => pickEl(e.target.value)} className=\"h-8 min-w-0 flex-1 rounded-md border border-gray-200 bg-white px-2 text-sm\" aria-label={`${SITE_NAME[site]} element`}>\n          <optgroup label=\"Radius data available\">\n            {withData.map(e => <option key={e.symbol} value={e.symbol}>{e.symbol} — {e.name}</option>)}\n          </optgroup>\n          <optgroup label=\"No radius data (factors unavailable)\">\n            {others.map(e => <option key={e.symbol} value={e.symbol}>{e.symbol} — {e.name}</option>)}\n          </optgroup>\n        </select>\n        <select value={value.charge} onChange={e => onChange({ ...value, charge: Number(e.target.value) })} className=\"h-8 w-20 rounded-md border border-gray-200 bg-white px-2 text-sm\" aria-label={`${SITE_NAME[site]} charge`}>\n          {(states.length ? states : [value.charge]).map(q => <option key={q} value={q}>{q > 0 ? '+' : '−'}{Math.abs(q)}</option>)}\n        </select>\n      </div>\n      <div className=\"mt-1.5 text-[11px] text-gray-400\">{r != null ? `Shannon radius ${r.toFixed(3)} Å` : 'No tabulated radius for this ion/site'}</div>\n    </div>\n  );\n}\n\nexport default function PerovskiteLabPage() {\n  const [model, setModel] = useState<ModelId>('cubic');\n  const [sites, setSites] = useState<Sites>(PRESETS[0].sites);\n  const [presetNote, setPresetNote] = useState<string | null>(PRESETS[0].note);\n  const [n, setN] = useState(1);\n  const [aMode, setAMode] = useState<'BX' | 'AX' | 'custom'>('BX');\n  const [aCustom, setACustom] = useState(5.0);\n  const [bonds, setBonds] = useState(true);\n  const [cell, setCell] = useState(true);\n  const [showA, setShowA] = useState(true);\n  const [saved, setSaved] = useState(false);\n\n  useEffect(() => {\n    const t = setTimeout(() => {\n      const q = fromQuery();\n      if (q) {\n        setSites(s => ({ ...s, ...q }));\n        setPresetNote('Pre-filled from the compound builder (A = most electropositive, X = most electronegative). Check the assignment and oxidation states.');\n      }\n    }, 0);\n    return () => clearTimeout(t);\n  }, []);\n\n  const double = model === 'double';\n  const modelDef = MODELS[model];\n  const modelSites: ModelSites = { A: sites.A, B: sites.B, B2: double ? sites.B2 : undefined, X: sites.X };\n  const report = useMemo(() => analyseModel(model, modelSites),\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [model, sites, double]);\n\n  const a = aMode === 'custom' ? aCustom : aMode === 'AX' ? report.aAX ?? aCustom : report.aBX ?? aCustom;\n  const elements: Record<Site, string | undefined> = { A: sites.A.symbol, B: sites.B.symbol, B2: double ? sites.B2.symbol : undefined, X: sites.X.symbol };\n  const dens = density(modelDef, a, elements);\n  const mass = molarMass(report.composition);\n  const chargeOk = Math.abs(report.chargeSum) < 1e-9;\n\n  const atoms = useMemo(() => withBoundaryImages(modelDef.atoms, n), [modelDef, n]);\n  const styles = useMemo(() => {\n    const edge = a * modelDef.cellFactor;\n    const mk = (k: SiteKey): SiteStyle => {\n      const r = TABLE[k][key(sites[k].symbol, sites[k].charge)] ?? 0.9;\n      return { label: sites[k].symbol, color: COLORS[k], radius: r / edge };\n    };\n    const out: Partial<Record<Site, SiteStyle>> = { A: mk('A'), B: mk('B'), X: mk('X') };\n    if (double) out.B2 = mk('B2');\n    return out;\n  }, [sites, a, modelDef, double]);\n\n  const setSite = (k: SiteKey, v: Pick) => { setSites(s => ({ ...s, [k]: v })); setSaved(false); setPresetNote(null); };\n  const loadPreset = (pr: Preset) => { setModel(pr.model); setSites(pr.sites); setPresetNote(pr.note); setSaved(false); };\n\n  const onSave = () => {\n    saveCandidate({\n      name: formulaPlain(report.composition) + (double ? ' (double)' : ''),\n      kind: 'perovskite', formula: formulaPlain(report.composition), composition: report.composition, molarMass: mass,\n      chargeStatus: chargeOk ? 'Charges sum to zero' : `Charge sum ${report.chargeSum > 0 ? '+' : ''}${report.chargeSum}`,\n      perovskite: { model, sites: { A: sites.A, B: sites.B, B2: double ? sites.B2 : undefined, X: sites.X }, a, tolerance: report.tolerance, octahedral: report.octahedral, density: dens },\n      note: presetNote ?? undefined,\n    });\n    setSaved(true);\n  };\n  const onLoad = (c: Candidate) => {\n    if (c.perovskite) {\n      setModel(c.perovskite.model);\n      setSites(s => ({ ...s, ...(c.perovskite!.sites as Partial<Sites>) }));\n      setAMode('custom'); setACustom(c.perovskite.a); setPresetNote(c.note ?? null);\n    }\n  };\n\n  const fmt = (v: number | null, d = 3) => (v == null ? '—' : v.toFixed(d));\n\n  useTopicPreset(\"chemistry-perovskite-lab\", { \"aCustom\": setACustom }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <div className=\"mx-auto max-w-7xl px-4 py-6 sm:px-6\">\n          <Link href=\"/chemistry\" className=\"text-xs text-gray-400 transition hover:text-indigo-600\">← Chemistry</Link>\n          <h1 className=\"mt-1 text-xl font-semibold text-gray-900 sm:text-2xl\">Perovskite lab</h1>\n          <p className=\"mb-4 mt-1 text-sm text-gray-500\">Assign A, B and X sites, check the geometry, and inspect an idealised model. Idealised models are proposals — not relaxed or confirmed structures.</p>\n\n          <div className=\"mb-5 flex flex-wrap gap-2\">\n            {PRESETS.map(pr => (\n              <button key={pr.label} type=\"button\" onClick={() => loadPreset(pr)} className=\"rounded-full border border-gray-200 bg-white px-3 py-1 text-xs text-gray-700 transition hover:border-indigo-300 hover:text-indigo-700\">{pr.label}</button>\n            ))}\n          </div>\n          {presetNote && <p className=\"mb-5 rounded-xl border border-indigo-100 bg-indigo-50 px-3 py-2 text-xs text-indigo-900\">{presetNote} <span className=\"opacity-70\">Reference notes are summaries — check the primary literature before citing.</span></p>}\n\n          <SimulationStage className=\"grid grid-cols-1 gap-5 lg:grid-cols-[minmax(0,1.3fr)_minmax(0,1fr)]\">\n            <div data-stage-role=\"canvas\" className=\"min-w-0 space-y-5\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <CrystalViewer atoms={atoms} extent={n} styles={styles} bondDist={0.5 / modelDef.cellFactor} sizeScale={0.36} showBonds={bonds} showCell={cell} showA={showA} />\n                <div className=\"mt-3 flex flex-wrap items-center gap-x-4 gap-y-2 border-t border-gray-100 pt-3 text-xs text-gray-600\">\n                  <label className=\"flex items-center gap-1.5\"><input type=\"checkbox\" checked={bonds} onChange={e => setBonds(e.target.checked)} />B–X bonds</label>\n                  <label className=\"flex items-center gap-1.5\"><input type=\"checkbox\" checked={cell} onChange={e => setCell(e.target.checked)} />Cell edges</label>\n                  <label className=\"flex items-center gap-1.5\"><input type=\"checkbox\" checked={showA} onChange={e => setShowA(e.target.checked)} />A atoms</label>\n                  <span className=\"ml-auto flex items-center gap-1.5\">Cells\n                    {[1, 2].map(v => <button key={v} type=\"button\" onClick={() => setN(v)} className={`rounded-md border px-2 py-0.5 ${n === v ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 hover:border-indigo-300'}`}>{v}×{v}×{v}</button>)}\n                  </span>\n                </div>\n                <p className=\"mt-2 text-[11px] text-gray-400\">{modelDef.label} · space group {modelDef.spaceGroup}. {modelDef.note}</p>\n              </div>\n              <CandidatesPanel onLoad={onLoad} />\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"min-w-0 space-y-5\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                <div className=\"flex gap-2\">\n                  {(Object.keys(MODELS) as ModelId[]).map(id => (\n                    <button key={id} type=\"button\" onClick={() => { setModel(id); setSaved(false); }} className={`flex-1 rounded-lg border px-2 py-1.5 text-xs font-medium ${model === id ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 text-gray-600 hover:border-indigo-300'}`}>{id === 'cubic' ? 'ABX₃' : 'A₂BB′X₆'}</button>\n                  ))}\n                </div>\n                <div className=\"mt-3 grid gap-3 sm:grid-cols-2\">\n                  {(['A', 'B', ...(double ? ['B2'] : []), 'X'] as SiteKey[]).map(k => <SitePicker key={k} site={k} value={sites[k]} onChange={v => setSite(k, v)} />)}\n                </div>\n\n                <div className=\"mt-4 text-[11px] font-medium uppercase tracking-wide text-gray-400\">Candidate</div>\n                <div className=\"text-3xl font-semibold text-gray-900\" aria-live=\"polite\">{formulaOf(report.composition)}</div>\n                <div className=\"text-xs text-gray-500\">{mass.toFixed(2)} g/mol per formula unit</div>\n\n                <dl className=\"mt-3 divide-y divide-gray-100 text-xs\">\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Charge sum</dt><dd className={`font-medium ${chargeOk ? 'text-emerald-700' : 'text-red-600'}`}>{chargeOk ? '0 (balanced)' : `${report.chargeSum > 0 ? '+' : ''}${report.chargeSum} — not balanced`}</dd></div>\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Tolerance factor t</dt><dd className=\"font-medium text-gray-900\">{fmt(report.tolerance)}</dd></div>\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Octahedral factor μ</dt><dd className=\"font-medium text-gray-900\">{fmt(report.octahedral)}</dd></div>\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Estimated a (B–X contact / A–X contact)</dt><dd className=\"font-medium text-gray-900\">{fmt(report.aBX, 2)} / {fmt(report.aAX, 2)} Å</dd></div>\n                </dl>\n                {report.missing.length > 0 && <p className=\"mt-2 rounded-lg bg-amber-50 px-3 py-2 text-[11px] text-amber-800\">No tabulated radius for {report.missing.join('; ')} — factors can’t be computed.</p>}\n                {report.tolerance != null && (\n                  <div className=\"mt-3 space-y-1.5 text-[11px] leading-relaxed text-gray-600\">\n                    <p><span className=\"font-medium text-gray-900\">t:</span> {report.toleranceVerdict}</p>\n                    <p><span className=\"font-medium text-gray-900\">μ:</span> {report.octahedralVerdict}</p>\n                  </div>\n                )}\n\n                <div className=\"mt-4 border-t border-gray-100 pt-3\">\n                  <div className=\"text-[11px] font-medium text-gray-500\">Lattice parameter a used for the model</div>\n                  <div className=\"mt-1.5 flex flex-wrap items-center gap-2 text-xs\">\n                    {([['BX', 'B–X contact'], ['AX', 'A–X contact'], ['custom', 'Custom']] as const).map(([id, lab]) => (\n                      <button key={id} type=\"button\" onClick={() => setAMode(id)} className={`rounded-md border px-2 py-1 ${aMode === id ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 text-gray-600 hover:border-indigo-300'}`}>{lab}</button>\n                    ))}\n                    {aMode === 'custom' && <input type=\"number\" step={0.01} min={2} max={12} value={aCustom} onChange={e => setACustom(Number(e.target.value) || 5)} className=\"h-7 w-20 rounded-md border border-gray-200 px-2\" aria-label=\"Custom lattice parameter in angstroms\" />}\n                    <span className=\"text-gray-500\">a = {a.toFixed(3)} Å{dens != null && ` · ρ ≈ ${dens.toFixed(2)} g/cm³`}</span>\n                  </div>\n                  <p className=\"mt-1 text-[11px] text-gray-400\">An ionic-radius estimate, not a relaxed value. If t ≠ 1 the two contact estimates disagree — that mismatch is why real structures tilt or distort.</p>\n                </div>\n\n                <div className=\"mt-4 flex flex-wrap gap-2\">\n                  <button type=\"button\" onClick={onSave} className=\"rounded-lg bg-indigo-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-indigo-700\">{saved ? 'Saved ✓' : 'Save candidate'}</button>\n                  <button type=\"button\" onClick={() => download(`${formulaPlain(report.composition)}-${model}-proposed.cif`, toCif({ title: formulaPlain(report.composition), a, model: modelDef, elements }), 'chemical/x-cif')} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">Download CIF (proposed)</button>\n                  <Link href={`/chemistry/compound-builder?c=${Object.entries(report.composition).map(([s, c]) => `${s}:${c}`).join(',')}`} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">Open in builder →</Link>\n                </div>\n              </div>\n              <EvidencePanel\n                rule={{ label: report.tolerance == null ? 'Geometric factors unavailable (missing radii).' : `Charge ${chargeOk ? 'balances' : 'does not balance'}; t = ${report.tolerance.toFixed(3)}, μ = ${report.octahedral!.toFixed(3)}. Heuristics only.`, ok: report.tolerance == null ? null : chargeOk && report.tolerance >= 0.8 && report.tolerance <= 1.06 && report.octahedral! >= 0.414 }}\n                extra={`${double ? 'double perovskite' : 'cubic'} model`}\n              />\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/chemistry/organic/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useEffect, useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { MoleculeEditor, H, type Tool } from '@/components/chemistry/MoleculeEditor';\nimport { EvidencePanel } from '@/components/chemistry/EvidencePanel';\nimport { CandidatesPanel } from '@/components/chemistry/CandidatesPanel';\nimport {\n  ISOMER_SETS, LIBRARY, PALETTE, components, dbe, formulaText, functionalGroups, identify, loadPreset, massOf, parseSmiles,\n  placeMol, toMolfile, toSmiles, valenceInfo, composition, type Mol,\n} from '@/lib/chemistry/organic';\nimport { saveCandidate, download, type Candidate } from '@/lib/chemistry/candidates';\n\nconst TOOLS: { id: Tool; label: string; hint: string }[] = [\n  { id: 'move', label: 'Move', hint: 'Drag atoms to rearrange the drawing.' },\n  { id: 'atom', label: 'Add atom', hint: 'Tap empty space to place the chosen element. With “auto-bond” on, each new atom bonds to the last selected one, so you can draw chains quickly. Tap an atom with a different element chosen to change it.' },\n  { id: 'bond', label: 'Bond', hint: 'Tap one atom, then another. Tap the same pair again to cycle single → double → triple → none.' },\n  { id: 'erase', label: 'Erase', hint: 'Tap an atom or a bond to delete it.' },\n];\nconst GROUPS = Array.from(new Set(LIBRARY.map(p => p.group)));\n\nexport default function OrganicPage() {\n  const [width, setWidth] = useState(640);\n  const [mol, setMol] = useState<Mol>(() => loadPreset('Ethanol') ?? { atoms: [], bonds: [] });\n  const [undo, setUndo] = useState<Mol[]>([]);\n  const [tool, setTool] = useState<Tool>('move');\n  const [element, setElement] = useState('C');\n  const [selected, setSelected] = useState<number | null>(null);\n  const [autoBond, setAutoBond] = useState(true);\n  const [skeletal, setSkeletal] = useState(false);\n  const [smiles, setSmiles] = useState('');\n  const [smilesError, setSmilesError] = useState<string | null>(null);\n  const [saved, setSaved] = useState(false);\n  const [copied, setCopied] = useState(false);\n\n  const pickTool = (t: Tool) => { setTool(t); setSelected(null); };\n  // Phones get a narrower drawing space so atoms and labels render at a readable size.\n  useEffect(() => {\n    const t = setTimeout(() => {\n      if (window.innerWidth < 640) { setWidth(360); setMol(m => placeMol(m, 360, H)); }\n    }, 0);\n    return () => clearTimeout(t);\n  }, []);\n  const push = () => setUndo(u => [...u.slice(-29), mol]);\n  const commit = (m: Mol) => { push(); setMol(m); setSaved(false); setCopied(false); };\n  const doUndo = () => { setUndo(u => { if (!u.length) return u; setMol(u[u.length - 1]); setSelected(null); return u.slice(0, -1); }); setSaved(false); };\n  const load = (m: Mol) => { push(); setMol(m); setSelected(null); setSmilesError(null); setSaved(false); setCopied(false); };\n  const loadByName = (name: string) => { const m = loadPreset(name, width, H); if (m) load(m); };\n\n  const n = mol.atoms.length;\n  const { h, bad } = valenceInfo(mol);\n  const totalH = h.reduce((s, x) => s + x, 0);\n  const formula = n ? formulaText(mol) : '—';\n  const mass = n ? massOf(mol) : 0;\n  const unsat = n ? dbe(mol) : null;\n  const groups = n ? functionalGroups(mol) : [];\n  const id = identify(mol);\n  const parts = components(mol);\n  const smilesOut = n ? toSmiles(mol) : '';\n  const valid = n > 0 && bad.length === 0 && parts === 1;\n\n  const drawSmiles = () => {\n    const r = parseSmiles(smiles);\n    if (r.error || !r.mol) { setSmilesError(r.error ?? 'Could not read that SMILES.'); return; }\n    load(placeMol(r.mol, width, H));\n  };\n  const onSave = () => {\n    if (!n) return;\n    saveCandidate({\n      name: id.same ?? formula, kind: 'organic', formula, composition: composition(mol), molarMass: mass,\n      chargeStatus: valid ? 'Valences satisfied' : 'Valence problem',\n      organic: { atoms: mol.atoms, bonds: mol.bonds, smiles: smilesOut },\n    });\n    setSaved(true);\n  };\n  const onLoadCandidate = (c: Candidate) => { if (c.organic) load({ atoms: c.organic.atoms, bonds: c.organic.bonds }); };\n  const tip = TOOLS.find(t => t.id === tool)!;\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <div className=\"mx-auto max-w-7xl px-4 py-6 sm:px-6\">\n          <Link href=\"/chemistry\" className=\"text-xs text-gray-400 transition hover:text-indigo-600\">← Chemistry</Link>\n          <h1 className=\"mt-1 text-xl font-semibold text-gray-900 sm:text-2xl\">Organic molecules</h1>\n          <p className=\"mb-4 mt-1 text-sm text-gray-500\">Draw atoms and bonds, or load a molecule. Hydrogens fill in automatically from valence. The tool reads the structure you drew — it tells you what the <span className=\"font-medium text-gray-700\">graph</span> contains, not whether the molecule is stable or easy to make.</p>\n\n          <SimulationStage className=\"grid grid-cols-1 gap-5 lg:grid-cols-[minmax(0,1.35fr)_minmax(0,1fr)]\">\n            <div data-stage-role=\"canvas\" className=\"min-w-0 space-y-5\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <div className=\"mb-3 flex flex-wrap items-center gap-2\">\n                  <div className=\"flex overflow-hidden rounded-lg border border-gray-200\" role=\"group\" aria-label=\"Drawing tool\">\n                    {TOOLS.map(t => <button key={t.id} type=\"button\" aria-pressed={tool === t.id} onClick={() => pickTool(t.id)} className={`px-3 py-1.5 text-xs font-medium ${tool === t.id ? 'bg-indigo-600 text-white' : 'bg-white text-gray-600 hover:bg-gray-50'}`}>{t.label}</button>)}\n                  </div>\n                  <button type=\"button\" onClick={doUndo} disabled={!undo.length} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-600 enabled:hover:border-indigo-300 disabled:opacity-40\">Undo</button>\n                  <button type=\"button\" onClick={() => { if (n) { push(); setMol({ atoms: [], bonds: [] }); setSelected(null); setSaved(false); } }} disabled={!n} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-600 enabled:hover:border-red-300 enabled:hover:text-red-600 disabled:opacity-40\">Clear</button>\n                </div>\n                {/* Always rendered (hidden when unused) so the canvas never jumps when the tool changes. */}\n                {(\n                  <div className={`mb-3 flex flex-wrap items-center gap-1.5 ${tool === 'atom' ? '' : 'invisible'}`} role=\"group\" aria-label=\"Element\" aria-hidden={tool !== 'atom'}>\n                    {PALETTE.map(el => <button key={el} type=\"button\" tabIndex={tool === 'atom' ? 0 : -1} aria-pressed={element === el} onClick={() => setElement(el)} className={`h-8 min-w-8 rounded-md border px-2 text-xs font-semibold ${element === el ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 text-gray-700 hover:border-indigo-300'}`}>{el}</button>)}\n                    <label className=\"ml-2 flex items-center gap-1.5 text-xs text-gray-600\"><input type=\"checkbox\" checked={autoBond} onChange={e => setAutoBond(e.target.checked)} />Auto-bond</label>\n                  </div>\n                )}\n                <MoleculeEditor mol={mol} tool={tool} element={element} selected={selected} autoBond={autoBond} skeletal={skeletal} width={width}\n                  onLive={setMol} onCommit={commit} onSelect={setSelected} onDragStart={push} />\n                <div className=\"mt-2 flex flex-wrap items-center gap-x-4 gap-y-1\">\n                  <p className=\"min-w-0 flex-1 text-[11px] text-gray-500\">{tip.hint}</p>\n                  <label className=\"flex items-center gap-1.5 text-xs text-gray-600\"><input type=\"checkbox\" checked={skeletal} onChange={e => setSkeletal(e.target.checked)} />Skeletal style</label>\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <h2 className=\"mb-2 text-sm font-semibold text-gray-900\">Load a molecule</h2>\n                <label className=\"sr-only\" htmlFor=\"lib\">Molecule library</label>\n                <select id=\"lib\" value=\"\" onChange={e => e.target.value && loadByName(e.target.value)} className=\"h-9 w-full rounded-md border border-gray-200 bg-white px-2 text-sm\">\n                  <option value=\"\">Choose from the library ({LIBRARY.length} molecules)…</option>\n                  {GROUPS.map(g => <optgroup key={g} label={g}>{LIBRARY.filter(p => p.group === g).map(p => <option key={p.name} value={p.name}>{p.name}</option>)}</optgroup>)}\n                </select>\n                <div className=\"mt-3 text-[11px] font-medium uppercase tracking-wide text-gray-400\">Isomer sets — same formula, different structure</div>\n                <div className=\"mt-1.5 space-y-1.5\">\n                  {ISOMER_SETS.map(s => (\n                    <div key={s.formula} className=\"flex flex-wrap items-center gap-1.5\">\n                      <span className=\"w-14 text-xs font-medium text-gray-500\">{s.formula}</span>\n                      {s.names.map(nm => <button key={nm} type=\"button\" onClick={() => loadByName(nm)} className=\"rounded-full border border-gray-200 px-2.5 py-1 text-[11px] text-gray-700 hover:border-indigo-300 hover:text-indigo-700\">{nm.replace(/ \\(.*\\)/, '')}</button>)}\n                    </div>\n                  ))}\n                </div>\n                <div className=\"mt-4 text-[11px] font-medium uppercase tracking-wide text-gray-400\">Or type a SMILES string</div>\n                <div className=\"mt-1.5 flex gap-2\">\n                  <label className=\"sr-only\" htmlFor=\"smiles\">SMILES</label>\n                  <input id=\"smiles\" value={smiles} onChange={e => { setSmiles(e.target.value); setSmilesError(null); }} onKeyDown={e => e.key === 'Enter' && drawSmiles()} spellCheck={false} autoCapitalize=\"off\" placeholder=\"e.g. CC(=O)O or c1ccccc1\" className=\"h-9 min-w-0 flex-1 rounded-md border border-gray-200 px-3 font-mono text-sm\" />\n                  <button type=\"button\" onClick={drawSmiles} className=\"h-9 rounded-md bg-indigo-600 px-3 text-xs font-medium text-white hover:bg-indigo-700\">Draw</button>\n                </div>\n                {smilesError && <p className=\"mt-1.5 rounded-lg bg-amber-50 px-3 py-2 text-xs text-amber-900\">{smilesError}</p>}\n                <p className=\"mt-1.5 text-[11px] text-gray-400\">Supports C N O S P F Cl Br I, aromatic c n o s, branches ( ), rings, and = # bonds. Charges and stereochemistry are not modelled.</p>\n              </div>\n              <CandidatesPanel onLoad={onLoadCandidate} />\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"min-w-0 space-y-5\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                <div className=\"text-[11px] font-medium uppercase tracking-wide text-gray-400\">Molecular formula</div>\n                <div className=\"text-3xl font-semibold text-gray-900\" aria-live=\"polite\">{formula}</div>\n                {n > 0 && (\n                  <div className={`mt-1 text-sm ${id.same ? 'text-emerald-700' : 'text-gray-500'}`}>\n                    {id.same ? `Matches ${id.same} in the library` : valid ? 'Not in the built-in library (that does not mean it doesn’t exist)' : ''}\n                  </div>\n                )}\n\n                {n > 0 && (bad.length > 0 || parts > 1) && (\n                  <ul className=\"mt-3 space-y-1 rounded-lg bg-red-50 px-3 py-2 text-xs text-red-800\">\n                    {bad.length > 0 && <li>{bad.length} atom{bad.length > 1 ? 's have' : ' has'} too many bonds for its valence (shown in red).</li>}\n                    {parts > 1 && <li>The drawing has {parts} separate pieces; the numbers below treat them as one species.</li>}\n                  </ul>\n                )}\n\n                <dl className=\"mt-3 divide-y divide-gray-100 text-xs\">\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Molar mass</dt><dd className=\"font-medium text-gray-900\">{n ? `${mass.toFixed(3)} g/mol` : '—'}</dd></div>\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Heavy atoms / bonds / H</dt><dd className=\"font-medium text-gray-900\">{n} / {mol.bonds.length} / {totalH}</dd></div>\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Degrees of unsaturation</dt><dd className=\"font-medium text-gray-900\">{n ? (unsat ?? '—') : '—'}</dd></div>\n                  <div className=\"flex justify-between gap-3 py-1.5\"><dt className=\"text-gray-500\">SMILES</dt><dd className=\"min-w-0 break-all text-right font-mono font-medium text-gray-900\">{smilesOut || '—'}</dd></div>\n                </dl>\n\n                <div className=\"mt-3\">\n                  <div className=\"text-[11px] font-medium uppercase tracking-wide text-gray-400\">Functional groups found</div>\n                  {groups.length ? (\n                    <div className=\"mt-1.5 flex flex-wrap gap-1.5\">{groups.map(g => <span key={g.label} className=\"rounded-full bg-indigo-50 px-2.5 py-1 text-[11px] font-medium text-indigo-800\">{g.label}{g.count > 1 ? ` ×${g.count}` : ''}</span>)}</div>\n                  ) : <p className=\"mt-1 text-xs text-gray-500\">{n ? 'None of the recognised groups (an alkane-type framework, or an unusual arrangement).' : 'Draw or load a molecule.'}</p>}\n                </div>\n\n                {id.isomers.length > 0 && (\n                  <div className=\"mt-4\">\n                    <div className=\"text-[11px] font-medium uppercase tracking-wide text-gray-400\">Library isomers of {formula}</div>\n                    <div className=\"mt-1.5 flex flex-wrap gap-1.5\">{id.isomers.map(nm => <button key={nm} type=\"button\" onClick={() => loadByName(nm)} className=\"rounded-full border border-gray-200 px-2.5 py-1 text-[11px] text-gray-700 hover:border-indigo-300 hover:text-indigo-700\">{nm}</button>)}</div>\n                    <p className=\"mt-1.5 text-[11px] text-gray-400\">Constitutional isomers: same atoms, connected differently. Their properties can differ a lot. Stereoisomers (cis/trans, mirror images) are not distinguished here.</p>\n                  </div>\n                )}\n\n                <div className=\"mt-4 flex flex-wrap gap-2\">\n                  <button type=\"button\" onClick={onSave} disabled={!n} className=\"rounded-lg bg-indigo-600 px-3 py-1.5 text-xs font-medium text-white enabled:hover:bg-indigo-700 disabled:opacity-40\">{saved ? 'Saved ✓' : 'Save candidate'}</button>\n                  <button type=\"button\" disabled={!n} onClick={async () => { try { await navigator.clipboard.writeText(smilesOut); setCopied(true); } catch { /* clipboard blocked */ } }} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 enabled:hover:border-indigo-300 disabled:opacity-40\">{copied ? 'Copied ✓' : 'Copy SMILES'}</button>\n                  <button type=\"button\" disabled={!n} onClick={() => download(`${(id.same ?? formula).replace(/[^A-Za-z0-9]+/g, '_')}.mol`, toMolfile(mol, id.same ?? formula), 'chemical/x-mdl-molfile')} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 enabled:hover:border-indigo-300 disabled:opacity-40\">Download .mol</button>\n                  {n > 0 && <Link href={`/chemistry/compound-builder?c=${Object.entries(composition(mol)).map(([s, c]) => `${s}:${c}`).join(',')}`} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">Open in builder →</Link>}\n                </div>\n              </div>\n\n              <EvidencePanel\n                candidate=\"You drew or loaded this structure. A valid-looking drawing does not mean the molecule is stable, isolable or easy to make.\"\n                rule={{ label: n ? `${bad.length ? 'Valence rules violated. ' : 'Valences satisfied. '}Groups come from fixed pattern rules on the bond graph.` : 'Draw or load a molecule to run the checks.', ok: n ? valid : null }}\n                database={{ state: id.same ? 'warn' : 'no', text: id.same ? `Matched to “${id.same}” in a small built-in library of ${LIBRARY.length} molecules — not a chemical database. Confirm identity in PubChem or similar.` : `Compared only against the built-in library of ${LIBRARY.length} molecules. Use PubChem, ChEBI or a similar database to look a structure up.` }}\n                calculated={{ state: 'no', text: 'None. The 2D layout is only a drawing: no 3D geometry, energies, charges, pKa or spectra are calculated.' }}\n              />\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/chemistry/compound-builder/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useEffect, useMemo, useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { PeriodicTable } from '@/components/chemistry/PeriodicTable';\nimport { EvidencePanel } from '@/components/chemistry/EvidencePanel';\nimport { CandidatesPanel } from '@/components/chemistry/CandidatesPanel';\nimport { BY_SYMBOL, type Element } from '@/lib/chemistry/elements';\nimport {\n  chargeBalance, cleanComposition, formulaOf, formulaPlain, massFractions, molarMass, orderedSymbols, reduce, type Composition,\n} from '@/lib/chemistry/compound';\nimport { fmtCharge } from '@/lib/chemistry/perovskite';\nimport { saveCandidate, type Candidate } from '@/lib/chemistry/candidates';\n\nconst PRESETS: { label: string; c: Composition }[] = [\n  { label: 'NaMgBr₃', c: { Na: 1, Mg: 1, Br: 3 } },\n  { label: 'NaCl', c: { Na: 1, Cl: 1 } },\n  { label: 'H₂O', c: { H: 2, O: 1 } },\n  { label: 'Fe₂O₃', c: { Fe: 2, O: 3 } },\n  { label: 'CsPbBr₃', c: { Cs: 1, Pb: 1, Br: 3 } },\n  { label: 'C₆H₁₂O₆', c: { C: 6, H: 12, O: 6 } },\n];\n\nfunction parseComp(s: string): Composition {\n  const out: Composition = {};\n  for (const part of s.split(',')) {\n    const [sym, n] = part.split(':');\n    if (BY_SYMBOL[sym]) out[sym] = Math.max(1, Math.min(999, parseInt(n ?? '1', 10) || 1));\n  }\n  return out;\n}\n\nexport default function CompoundBuilderPage() {\n  const [comp, setComp] = useState<Composition>({});\n  const [last, setLast] = useState<Element | null>(null);\n  const [saved, setSaved] = useState(false);\n  const [copied, setCopied] = useState(false);\n\n  // Accept ?add=Na (from the periodic table) or ?c=Na:1,Mg:1,Br:3.\n  useEffect(() => {\n    // Deferred one tick: the URL is an external system read after hydration.\n    const t = setTimeout(() => {\n      const q = new URLSearchParams(window.location.search);\n      const c = q.get('c'), add = q.get('add');\n      if (c) setComp(parseComp(c));\n      else if (add && BY_SYMBOL[add]) setComp({ [add]: 1 });\n    }, 0);\n    return () => clearTimeout(t);\n  }, []);\n\n  const clean = useMemo(() => cleanComposition(comp), [comp]);\n  const syms = orderedSymbols(clean);\n  const mass = molarMass(clean);\n  const reduced = reduce(clean);\n  const balance = useMemo(() => chargeBalance(clean), [clean]);\n  const fractions = massFractions(clean);\n  const empirical = formulaOf(reduced);\n  const touch = () => { setSaved(false); setCopied(false); };\n\n  const add = (el: Element) => { setLast(el); touch(); setComp(c => ({ ...c, [el.symbol]: Math.min(999, (c[el.symbol] ?? 0) + 1) })); };\n  const setCount = (s: string, n: number) => { touch(); setComp(c => { const next = { ...c }; if (n <= 0 || !Number.isFinite(n)) delete next[s]; else next[s] = Math.min(999, Math.round(n)); return next; }); };\n\n  const perovskiteLink = useMemo(() => {\n    if (syms.length !== 3) return null;\n    const byEn = [...syms].sort((a, b) => (BY_SYMBOL[a].en ?? 9) - (BY_SYMBOL[b].en ?? 9));\n    return `/chemistry/perovskite-lab?A=${byEn[0]}&B=${byEn[1]}&X=${byEn[2]}`;\n  }, [syms]);\n\n  const chargeLabel = balance.status === 'balanced' ? 'Balanced (rule of thumb)' : balance.status === 'unbalanced' ? 'No balance found' : balance.message;\n\n  const onSave = () => {\n    if (!syms.length) return;\n    saveCandidate({ name: formulaPlain(clean), kind: 'composition', formula: formulaPlain(clean), composition: clean, molarMass: mass, chargeStatus: chargeLabel });\n    setSaved(true);\n  };\n  const onLoad = (c: Candidate) => { setComp(c.composition); touch(); };\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50 pb-24 lg:pb-0\">\n        <div className=\"mx-auto max-w-7xl px-4 py-6 sm:px-6\">\n          <Link href=\"/chemistry\" className=\"text-xs text-gray-400 transition hover:text-indigo-600\">← Chemistry</Link>\n          <h1 className=\"mt-1 text-xl font-semibold text-gray-900 sm:text-2xl\">Compound builder</h1>\n          <p className=\"mb-5 mt-1 text-sm text-gray-500\">Click elements to add atoms. The result is a <span className=\"font-medium text-gray-700\">candidate composition</span>, not a claim that it exists.</p>\n\n          <SimulationStage className=\"grid grid-cols-1 gap-5 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]\">\n            <div data-stage-role=\"canvas\" className=\"min-w-0 space-y-5\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <PeriodicTable onPick={add} counts={clean} compact showLegend={false} />\n                {last && <p className=\"mt-2 text-[11px] text-gray-400\">Added {last.name} ({last.symbol}).</p>}\n              </div>\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <div className=\"text-[11px] font-medium uppercase tracking-wide text-gray-400\">Presets</div>\n                <div className=\"mt-2 flex flex-wrap gap-2\">\n                  {PRESETS.map(p => (\n                    <button key={p.label} type=\"button\" onClick={() => { touch(); setComp(p.c); }} className=\"rounded-full border border-gray-200 bg-white px-3 py-1 text-xs text-gray-700 transition hover:border-indigo-300 hover:text-indigo-700\">{p.label}</button>\n                  ))}\n                </div>\n              </div>\n              <CandidatesPanel onLoad={onLoad} />\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"min-w-0 space-y-5\">\n              <div id=\"composition-result\" className=\"scroll-mt-20 rounded-2xl border border-gray-200 bg-white p-5\">\n                <div className=\"flex items-start justify-between gap-3\">\n                  <div>\n                    <div className=\"text-[11px] font-medium uppercase tracking-wide text-gray-400\">Formula</div>\n                    <div className=\"mt-0.5 min-h-[2.5rem] text-3xl font-semibold text-gray-900\" aria-live=\"polite\">{syms.length ? formulaOf(clean) : '—'}</div>\n                  </div>\n                  {syms.length > 0 && <button type=\"button\" onClick={() => { touch(); setComp({}); }} className=\"text-xs text-gray-400 hover:text-red-600\">Clear</button>}\n                </div>\n\n                {syms.length === 0 ? (\n                  <p className=\"mt-3 text-xs text-gray-500\">Pick an element from the table to begin.</p>\n                ) : (\n                  <>\n                    <ul className=\"mt-3 divide-y divide-gray-100\">\n                      {syms.map(s => (\n                        <li key={s} className=\"flex items-center gap-2 py-2\">\n                          <span className=\"w-8 text-sm font-semibold text-gray-900\">{s}</span>\n                          <span className=\"flex-1 truncate text-xs text-gray-500\">{BY_SYMBOL[s].name}</span>\n                          <button type=\"button\" onClick={() => setCount(s, clean[s] - 1)} className=\"h-7 w-7 rounded-md border border-gray-200 text-gray-600 hover:border-indigo-300\" aria-label={`Remove one ${s}`}>−</button>\n                          <input type=\"number\" min={0} max={999} value={clean[s]} onChange={e => setCount(s, Number(e.target.value))} className=\"h-7 w-14 rounded-md border border-gray-200 text-center text-sm\" aria-label={`${s} atom count`} />\n                          <button type=\"button\" onClick={() => setCount(s, clean[s] + 1)} className=\"h-7 w-7 rounded-md border border-gray-200 text-gray-600 hover:border-indigo-300\" aria-label={`Add one ${s}`}>+</button>\n                        </li>\n                      ))}\n                    </ul>\n\n                    <dl className=\"mt-3 grid grid-cols-2 gap-3 text-xs\">\n                      <div><dt className=\"text-gray-400\">Molar mass</dt><dd className=\"text-base font-semibold text-gray-900\">{mass.toFixed(3)} g/mol</dd></div>\n                      <div><dt className=\"text-gray-400\">Empirical formula</dt><dd className=\"text-base font-semibold text-gray-900\">{empirical}</dd></div>\n                    </dl>\n\n                    <div className=\"mt-3\">\n                      <div className=\"mb-1 text-[11px] text-gray-400\">Mass percentage</div>\n                      <div className=\"flex h-2 overflow-hidden rounded-full bg-gray-100\">\n                        {fractions.map((f, i) => <div key={f.symbol} style={{ width: `${f.fraction * 100}%` }} className={['bg-indigo-500', 'bg-emerald-500', 'bg-amber-500', 'bg-rose-500', 'bg-sky-500', 'bg-violet-500'][i % 6]} title={`${f.symbol} ${(f.fraction * 100).toFixed(1)}%`} />)}\n                      </div>\n                      <div className=\"mt-1 flex flex-wrap gap-x-3 text-[11px] text-gray-600\">\n                        {fractions.map(f => <span key={f.symbol}>{f.symbol} {(f.fraction * 100).toFixed(2)}%</span>)}\n                      </div>\n                    </div>\n\n                    <div className={`mt-4 rounded-xl px-3 py-2.5 text-xs ${balance.status === 'balanced' ? 'bg-emerald-50 text-emerald-900' : 'bg-amber-50 text-amber-900'}`}>\n                      <div className=\"font-medium\">Charge balance: {chargeLabel}</div>\n                      <p className=\"mt-0.5 opacity-90\">{balance.message}</p>\n                      {balance.solutions.length > 0 && (\n                        <ul className=\"mt-1.5 space-y-0.5\">\n                          {balance.solutions.slice(0, 3).map((s, i) => (\n                            <li key={i} className=\"font-mono text-[11px]\">\n                              {Object.entries(s.states).map(([el, q]) => `${el}${fmtCharge(q)}`).join('  ')}\n                              {s.unusual > 0 && <span className=\"ml-2 font-sans text-amber-700\">(less-common state)</span>}\n                            </li>\n                          ))}\n                        </ul>\n                      )}\n                    </div>\n\n                    <div className=\"mt-4 flex flex-wrap gap-2\">\n                      <button type=\"button\" onClick={onSave} className=\"rounded-lg bg-indigo-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-indigo-700\">{saved ? 'Saved ✓' : 'Save candidate'}</button>\n                      <button type=\"button\" onClick={async () => { try { await navigator.clipboard.writeText(formulaPlain(clean)); setCopied(true); } catch { /* clipboard blocked */ } }} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">{copied ? 'Copied ✓' : 'Copy formula'}</button>\n                      {perovskiteLink && <Link href={perovskiteLink} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">Open in perovskite lab →</Link>}\n                    </div>\n                  </>\n                )}\n              </div>\n              {syms.length > 0 && <EvidencePanel rule={{ label: balance.status === 'balanced' ? 'Charge can balance with tabulated oxidation states.' : balance.message, ok: balance.status === 'balanced' ? true : balance.status === 'unbalanced' ? false : null }} />}\n            </div>\n          </SimulationStage>\n        </div>\n\n        {syms.length > 0 && (\n          <div className=\"fixed inset-x-0 bottom-0 z-30 border-t border-gray-200 bg-white/95 px-4 py-2.5 backdrop-blur lg:hidden\" style={{ paddingBottom: 'max(0.625rem, env(safe-area-inset-bottom))' }}>\n            <div className=\"mx-auto flex max-w-7xl items-center gap-3\">\n              <div className=\"min-w-0 flex-1\">\n                <div className=\"truncate text-lg font-semibold leading-tight text-gray-900\">{formulaOf(clean)}</div>\n                <div className=\"truncate text-[11px] text-gray-500\">{mass.toFixed(2)} g/mol · charge {balance.status === 'balanced' ? 'can balance' : balance.status === 'unbalanced' ? 'no balance found' : 'n/a'}</div>\n              </div>\n              <button type=\"button\" onClick={() => document.getElementById('composition-result')?.scrollIntoView({ behavior: 'smooth', block: 'start' })} className=\"h-10 shrink-0 rounded-xl bg-indigo-600 px-4 text-sm font-medium text-white\">Review</button>\n            </div>\n          </div>\n        )}\n      </main>\n    </>\n  );\n}\n", "src/app/chemistry/heusler/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useMemo, useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { CrystalViewer, type SiteStyle } from '@/components/chemistry/CrystalViewer';\nimport { EvidencePanel } from '@/components/chemistry/EvidencePanel';\nimport { CandidatesPanel } from '@/components/chemistry/CandidatesPanel';\nimport { ELEMENTS, BY_SYMBOL } from '@/lib/chemistry/elements';\nimport { molarMass } from '@/lib/chemistry/compound';\nimport { withBoundaryImages, type Site } from '@/lib/chemistry/perovskite';\nimport {\n  TEMPLATES, SUB_SITE, SUB_NAME, NN_DIST, analyseHeusler, heuslerAtoms, heuslerCif, heuslerDensity, roleCount,\n  type Role, type Sub, type TemplateId,\n} from '@/lib/chemistry/heusler';\nimport { saveCandidate, download, type Candidate } from '@/lib/chemistry/candidates';\n\nconst ROLE_COLOR: Record<Role, string> = { X: '#f59e0b', Y: '#818cf8', Z: '#2dd4bf' };\ntype Els = Record<Role, string>;\n\ninterface Preset { label: string; template: TemplateId; el: Els; a: number; note: string }\nconst PRESETS: Preset[] = [\n  { label: 'TiNiSn', template: 'half-Y4c', el: { X: 'Ti', Y: 'Ni', Z: 'Sn' }, a: 5.94,\n    note: 'Half-Heusler with 18 valence electrons — the standard example of a closed-shell, semiconducting count (thermoelectric studies).' },\n  { label: 'NiMnSb', template: 'half-X4c', el: { X: 'Ni', Y: 'Mn', Z: 'Sb' }, a: 5.92,\n    note: 'The classic half-metallic half-Heusler. N_v = 22 gives the Slater–Pauling moment of 4 μB, which matches what is reported.' },\n  { label: 'Co₂MnSi', template: 'full-L21', el: { X: 'Co', Y: 'Mn', Z: 'Si' }, a: 5.65,\n    note: 'Regular L2₁ full-Heusler studied for half-metallicity; N_v = 29 gives the reported 5 μB.' },\n  { label: 'Co₂FeSi', template: 'full-L21', el: { X: 'Co', Y: 'Fe', Z: 'Si' }, a: 5.64,\n    note: 'Regular L2₁ full-Heusler with N_v = 30, i.e. a Slater–Pauling moment of 6 μB.' },\n  { label: 'Fe₂VAl', template: 'full-L21', el: { X: 'Fe', Y: 'V', Z: 'Al' }, a: 5.76,\n    note: 'N_v = 24: the closed-shell count of a non-magnetic full-Heusler (semimetal/narrow-gap candidate).' },\n  { label: 'Ni₂MnGa', template: 'full-L21', el: { X: 'Ni', Y: 'Mn', Z: 'Ga' }, a: 5.83,\n    note: 'Magnetic shape-memory alloy; the cubic L2₁ phase here is the high-temperature austenite, and the real material transforms martensitically.' },\n  { label: 'Mn₂CoAl', template: 'full-inverse', el: { X: 'Mn', Y: 'Co', Z: 'Al' }, a: 5.80,\n    note: 'Inverse (XA) full-Heusler discussed as a spin-gapless / ferrimagnetic candidate; N_v = 26 gives 2 μB.' },\n];\n\nfunction ElementSelect({ role, value, onChange }: { role: Role; value: string; onChange: (s: string) => void }) {\n  const e = BY_SYMBOL[value];\n  return (\n    <div className=\"rounded-xl border border-gray-200 p-3\">\n      <div className=\"flex items-center gap-1.5 text-[11px] font-medium text-gray-500\">\n        <span className=\"inline-block h-2.5 w-2.5 rounded-full\" style={{ background: ROLE_COLOR[role] }} />{role} element\n      </div>\n      <select value={value} onChange={ev => onChange(ev.target.value)} className=\"mt-2 h-8 w-full rounded-md border border-gray-200 bg-white px-2 text-sm\" aria-label={`${role} element`}>\n        {ELEMENTS.filter(x => x.z <= 103).map(x => <option key={x.symbol} value={x.symbol}>{x.symbol} — {x.name}</option>)}\n      </select>\n      <div className=\"mt-1.5 text-[11px] text-gray-400\">Valence electrons counted: {e.group == null ? '3 (f-block, approx.)' : e.group <= 12 ? e.group : e.group - 10}</div>\n    </div>\n  );\n}\n\nexport default function HeuslerPage() {\n  const [tid, setTid] = useState<TemplateId>(PRESETS[0].template);\n  const [el, setEl] = useState<Els>(PRESETS[0].el);\n  const [a, setA] = useState(PRESETS[0].a);\n  const [note, setNote] = useState<string | null>(PRESETS[0].note);\n  const [n, setN] = useState(1);\n  const [bonds, setBonds] = useState(true);\n  const [cell, setCell] = useState(true);\n  const [saved, setSaved] = useState(false);\n\n  const t = TEMPLATES[tid];\n  const report = useMemo(() => analyseHeusler(t, el), [t, el]);\n  const atoms = useMemo(() => withBoundaryImages(heuslerAtoms(t), n), [t, n]);\n  const mass = molarMass(report.composition);\n  const dens = heuslerDensity(t, a, el);\n\n  const styles = useMemo(() => {\n    const out: Partial<Record<Site, SiteStyle>> = {};\n    (Object.keys(t.layout) as Sub[]).forEach(sub => {\n      const role = t.layout[sub];\n      if (!role) return;\n      out[SUB_SITE[sub]] = { label: el[role], color: ROLE_COLOR[role], radius: 0.075 + 0.012 * BY_SYMBOL[el[role]].period };\n    });\n    return out;\n  }, [t, el]);\n  const siteNames = useMemo(() => Object.fromEntries((Object.keys(SUB_NAME) as Sub[]).map(s => [SUB_SITE[s], SUB_NAME[s]])) as Partial<Record<Site, string>>, []);\n\n  const roles: Role[] = ['X', 'Y', 'Z'];\n  const loadPreset = (p: Preset) => { setTid(p.template); setEl(p.el); setA(p.a); setNote(p.note); setSaved(false); };\n  const setRole = (r: Role, s: string) => { setEl(e => ({ ...e, [r]: s })); setNote(null); setSaved(false); };\n\n  const onSave = () => {\n    saveCandidate({\n      name: `${report.formula} (${t.family === 'half' ? 'half' : 'full'}, ${t.id.split('-')[1]})`,\n      kind: 'heusler', formula: report.formula, composition: report.composition, molarMass: mass,\n      chargeStatus: `N_v = ${report.nv}`,\n      heusler: { template: t.id, elements: el, a, valenceElectrons: report.nv, slaterPauling: report.moment },\n      note: note ?? undefined,\n    });\n    setSaved(true);\n  };\n  const onLoad = (c: Candidate) => {\n    if (c.heusler) {\n      setTid(c.heusler.template as TemplateId);\n      setEl(c.heusler.elements as Els);\n      setA(c.heusler.a);\n      setNote(c.note ?? null);\n    }\n  };\n\n  const tone = { good: 'bg-emerald-50 text-emerald-900', info: 'bg-gray-50 text-gray-700', warn: 'bg-amber-50 text-amber-900' } as const;\n\n  useTopicPreset(\"chemistry-heusler\", { \"a\": setA }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <div className=\"mx-auto max-w-7xl px-4 py-6 sm:px-6\">\n          <Link href=\"/chemistry\" className=\"text-xs text-gray-400 transition hover:text-indigo-600\">← Chemistry</Link>\n          <h1 className=\"mt-1 text-xl font-semibold text-gray-900 sm:text-2xl\">Heusler alloys</h1>\n          <p className=\"mb-4 mt-1 text-sm text-gray-500\">Place X, Y and Z on the four fcc sublattices, compare site arrangements, and check valence-electron rules. The model is a <span className=\"font-medium text-gray-700\">proposed ordering</span>, not a relaxed or confirmed structure.</p>\n\n          <div className=\"mb-4 flex flex-wrap gap-2\">\n            {PRESETS.map(p => (\n              <button key={p.label} type=\"button\" onClick={() => loadPreset(p)} className=\"rounded-full border border-gray-200 bg-white px-3 py-1 text-xs text-gray-700 transition hover:border-indigo-300 hover:text-indigo-700\">{p.label}</button>\n            ))}\n          </div>\n          {note && <p className=\"mb-5 rounded-xl border border-indigo-100 bg-indigo-50 px-3 py-2 text-xs text-indigo-900\">{note} <span className=\"opacity-70\">Reference notes and lattice parameters are approximate summaries — check the primary literature before citing.</span></p>}\n\n          <SimulationStage className=\"grid grid-cols-1 gap-5 lg:grid-cols-[minmax(0,1.3fr)_minmax(0,1fr)]\">\n            <div data-stage-role=\"canvas\" className=\"min-w-0 space-y-5\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <CrystalViewer atoms={atoms} extent={n} styles={styles} siteNames={siteNames} bondDist={NN_DIST} bondMode=\"nn\" sizeScale={0.62} sizeNote=\"atom size shows period only\" showBonds={bonds} showCell={cell} showA />\n                <div className=\"mt-3 flex flex-wrap items-center gap-x-4 gap-y-2 border-t border-gray-100 pt-3 text-xs text-gray-600\">\n                  <label className=\"flex items-center gap-1.5\"><input type=\"checkbox\" checked={bonds} onChange={e => setBonds(e.target.checked)} />Nearest-neighbour bonds</label>\n                  <label className=\"flex items-center gap-1.5\"><input type=\"checkbox\" checked={cell} onChange={e => setCell(e.target.checked)} />Cell edges</label>\n                  <span className=\"ml-auto flex items-center gap-1.5\">Cells\n                    {[1, 2].map(v => <button key={v} type=\"button\" onClick={() => setN(v)} className={`rounded-md border px-2 py-0.5 ${n === v ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 hover:border-indigo-300'}`}>{v}×{v}×{v}</button>)}\n                  </span>\n                </div>\n                <p className=\"mt-2 text-[11px] text-gray-400\">{t.label} · {t.spaceGroup}. {t.note} Atom sizes show period only, not ionic or atomic radii.{t.family === 'half' && ' The 4d site is vacant.'}</p>\n              </div>\n              <CandidatesPanel onLoad={onLoad} />\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"min-w-0 space-y-5\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                <label className=\"text-[11px] font-medium uppercase tracking-wide text-gray-400\" htmlFor=\"template\">Template / arrangement</label>\n                <select id=\"template\" value={tid} onChange={e => { setTid(e.target.value as TemplateId); setSaved(false); }} className=\"mt-1 h-9 w-full rounded-md border border-gray-200 bg-white px-2 text-sm\">\n                  <optgroup label=\"Half-Heusler XYZ (three arrangements)\">\n                    {(['half-X4c', 'half-Y4c', 'half-Z4c'] as TemplateId[]).map(id => <option key={id} value={id}>{TEMPLATES[id].label}</option>)}\n                  </optgroup>\n                  <optgroup label=\"Full-Heusler X₂YZ\">\n                    {(['full-L21', 'full-inverse'] as TemplateId[]).map(id => <option key={id} value={id}>{TEMPLATES[id].label}</option>)}\n                  </optgroup>\n                </select>\n                <p className=\"mt-1 text-[11px] text-gray-400\">Labels (e.g. “Type I/II/III”) vary between papers, so arrangements are named here by site.</p>\n\n                <div className=\"mt-3 grid gap-3 sm:grid-cols-3\">\n                  {roles.filter(r => roleCount(t, r) > 0).map(r => <ElementSelect key={r} role={r} value={el[r]} onChange={s => setRole(r, s)} />)}\n                </div>\n\n                <div className=\"mt-4 text-[11px] font-medium uppercase tracking-wide text-gray-400\">Candidate</div>\n                <div className=\"text-3xl font-semibold text-gray-900\" aria-live=\"polite\">{report.display}</div>\n                <div className=\"text-xs text-gray-500\">{mass.toFixed(2)} g/mol per formula unit</div>\n\n                <dl className=\"mt-3 divide-y divide-gray-100 text-xs\">\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Valence electrons N_v</dt><dd className=\"font-medium text-gray-900\">{report.nv}{report.approx && ' (approx.)'}</dd></div>\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Slater–Pauling M = N_v − {t.family === 'half' ? 18 : 24}</dt><dd className=\"font-medium text-gray-900\">{report.moment == null ? '0 (closed shell)' : `${report.moment > 0 ? '+' : ''}${report.moment} μB / f.u.`}</dd></div>\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Nearest-neighbour distance</dt><dd className=\"font-medium text-gray-900\">{(a * NN_DIST).toFixed(3)} Å</dd></div>\n                  <div className=\"flex justify-between py-1.5\"><dt className=\"text-gray-500\">Density at this a</dt><dd className=\"font-medium text-gray-900\">{dens.toFixed(2)} g/cm³</dd></div>\n                </dl>\n\n                <div className=\"mt-3 space-y-1.5\">\n                  {report.checks.map(c => (\n                    <div key={c.label} className={`rounded-lg px-3 py-2 text-[11px] leading-relaxed ${tone[c.tone]}`}><span className=\"font-medium\">{c.label}.</span> {c.text}</div>\n                  ))}\n                </div>\n\n                <div className=\"mt-4 border-t border-gray-100 pt-3\">\n                  <label className=\"text-[11px] font-medium text-gray-500\" htmlFor=\"a\">Lattice parameter a (Å)</label>\n                  <div className=\"mt-1 flex items-center gap-2\">\n                    <input id=\"a\" type=\"number\" step={0.01} min={3} max={9} value={a} onChange={e => { setA(Number(e.target.value) || 5.8); setSaved(false); }} className=\"h-8 w-24 rounded-md border border-gray-200 px-2 text-sm\" />\n                    <span className=\"text-[11px] text-gray-400\">Preset values are approximate literature numbers; for new compositions this is a placeholder you should replace, not a prediction.</span>\n                  </div>\n                </div>\n\n                <div className=\"mt-4 flex flex-wrap gap-2\">\n                  <button type=\"button\" onClick={onSave} className=\"rounded-lg bg-indigo-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-indigo-700\">{saved ? 'Saved ✓' : 'Save candidate'}</button>\n                  <button type=\"button\" onClick={() => download(`${report.formula}-${t.id}-proposed.cif`, heuslerCif({ title: report.formula, a, t, el }), 'chemical/x-cif')} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">Download CIF (proposed)</button>\n                  <Link href={`/chemistry/compound-builder?c=${Object.entries(report.composition).map(([s, c]) => `${s}:${c}`).join(',')}`} className=\"rounded-lg border border-gray-200 px-3 py-1.5 text-xs text-gray-700 hover:border-indigo-300\">Open in builder →</Link>\n                </div>\n              </div>\n              <EvidencePanel\n                rule={{ label: `N_v = ${report.nv} against the ${t.family === 'half' ? '8/18' : '24'}-electron closed-shell counts, plus a Slater–Pauling estimate. Counting rules only.`, ok: report.nv === (t.family === 'half' ? 18 : 24) || (t.family === 'half' && report.nv === 8) ? true : null }}\n                extra={`${t.label}`}\n              />\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/embed/optics/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { OpticsCanvas, OpticsMode } from '@/components/simulation/OpticsCanvas';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction OpticsEmbedInner() {\n  const sp = useSearchParams();\n  const mode = ((): OpticsMode => (sp.get('mode') === 'lens' ? 'lens' : 'snell'))();\n  const showControls = sp.get('controls') !== '0';\n\n  const [n1, setN1] = useState(() => num(sp, 'n1', 1.0, 1, 2.5));\n  const [n2, setN2] = useState(() => num(sp, 'n2', 1.5, 1, 2.5));\n  const [theta1, setTheta1] = useState(() => num(sp, 'theta1', 35, 0, 89));\n  const [focal, setFocal] = useState(() => num(sp, 'focal', 15, 5, 40));\n  const [objectDist, setObjectDist] = useState(() => num(sp, 'u', 40, 5, 90));\n  const [converging, setConverging] = useState(() => sp.get('conv') !== '0');\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><OpticsCanvas mode={mode} n1={n1} n2={n2} theta1={theta1}\n        focal={focal} objectDist={objectDist} converging={converging}\n        width={660} height={320} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n          <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2\">\n            {mode === 'snell' && <>\n              <Slider label=\"Angle of incidence θ₁\" unit=\"°\" value={theta1} min={0} max={89} step={1} set={setTheta1} color=\"#6366f1\" />\n              <Slider label=\"n₁ (top)\" unit=\"\" value={n1} min={1} max={2.5} step={0.01} set={setN1} color=\"#f59e0b\" />\n              <Slider label=\"n₂ (bottom)\" unit=\"\" value={n2} min={1} max={2.5} step={0.01} set={setN2} color=\"#10b981\" />\n            </>}\n            {mode !== 'snell' && <>\n              <Slider label=\"Focal length |f|\" unit=\"cm\" value={focal} min={5} max={40} step={1} set={setFocal} color=\"#f59e0b\" />\n              <Slider label=\"Object distance u\" unit=\"cm\" value={objectDist} min={5} max={90} step={1} set={setObjectDist} color=\"#6366f1\" />\n              <div className=\"space-y-1\">\n                <span className=\"text-xs text-gray-500\">Type</span>\n                <div className=\"flex gap-2\">\n                  {([true, false] as const).map(c => (\n                    <button key={String(c)} onClick={() => setConverging(c)}\n                      className={`flex-1 rounded-lg border px-2 py-1.5 text-xs font-medium transition ${\n                        converging === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                      }`}>\n                      {c ? 'Converging' : 'Diverging'}\n                    </button>\n                  ))}\n                </div>\n              </div>\n            </>}\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function OpticsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <OpticsEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/coupled-oscillators/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { CoupledOscillatorsCanvas } from '@/components/simulation/CoupledOscillatorsCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { OscillatorParams } from '@/lib/physics/coupledOscillators';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input\n        type=\"range\"\n        min={min}\n        max={max}\n        step={step}\n        value={value}\n        onChange={e => set(Number(e.target.value))}\n        className=\"w-full h-6 py-2 cursor-pointer\"\n        style={{ accentColor: color }}\n      />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction CoupledOscillatorsEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [m1, setM1] = useState(() => num(sp, 'm1', 1, 0.1, 5));\n  const [m2, setM2] = useState(() => num(sp, 'm2', 1, 0.1, 5));\n  const [k1, setK1] = useState(() => num(sp, 'k1', 1, 0.1, 5));\n  const [k2, setK2] = useState(() => num(sp, 'k2', 0.2, 0, 5));\n  const [k3, setK3] = useState(() => num(sp, 'k3', 1, 0.1, 5));\n  const [x1, setX1] = useState(() => num(sp, 'x1', 0.1, -0.3, 0.3));\n  const [x2, setX2] = useState(() => num(sp, 'x2', 0.1, -0.3, 0.3));\n  const [v1, setV1] = useState(() => num(sp, 'v1', 0, -2, 2));\n  const [v2, setV2] = useState(() => num(sp, 'v2', 0, -2, 2));\n  const [damping1, setDamping1] = useState(() => num(sp, 'd1', 0, 0, 1));\n  const [damping2, setDamping2] = useState(() => num(sp, 'd2', 0, 0, 1));\n  const [trailLength, setTrailLength] = useState(() => Math.round(num(sp, 'trail', 300, 0, 800)));\n  const [showTrail, setShowTrail] = useState(true);\n  const [showEnergy, setShowEnergy] = useState(true);\n\n  const params: OscillatorParams = { m1, m2, k1, k2, k3, damping1, damping2 };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><CoupledOscillatorsCanvas\n        key={resetKey}\n        x1Init={x1}\n        v1Init={v1}\n        x2Init={x2}\n        v2Init={v2}\n        params={params}\n        isRunning={isRunning}\n        isPaused={isPaused}\n        showTrail={showTrail}\n        showEnergy={showEnergy}\n        trailLength={trailLength}\n        width={640}\n        height={400}\n      /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Mass m₁\" unit=\"kg\" value={m1} min={0.1} max={5} step={0.1} set={setM1} color=\"#6366f1\" />\n          <Slider label=\"Mass m₂\" unit=\"kg\" value={m2} min={0.1} max={5} step={0.1} set={setM2} color=\"#f59e0b\" />\n          <Slider label=\"Spring k₁\" unit=\"N/m\" value={k1} min={0.1} max={5} step={0.1} set={setK1} color=\"#818cf8\" />\n          <Slider label=\"Coupling k₂\" unit=\"N/m\" value={k2} min={0} max={5} step={0.05} set={setK2} color=\"#10b981\" />\n          <Slider label=\"Spring k₃\" unit=\"N/m\" value={k3} min={0.1} max={5} step={0.1} set={setK3} color=\"#fbbf24\" />\n          <Slider label=\"Damping c₁\" unit=\"\" value={damping1} min={0} max={1} step={0.01} set={setDamping1} color=\"#ef4444\" />\n          <Slider label=\"Damping c₂\" unit=\"\" value={damping2} min={0} max={1} step={0.01} set={setDamping2} color=\"#ef4444\" />\n          <Slider label=\"Trail\" unit=\"frames\" value={trailLength} min={0} max={800} step={10} set={setTrailLength} color=\"#f43f5e\" />\n          <div className=\"flex gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showTrail} onChange={e => setShowTrail(e.target.checked)} className=\"rounded\" />\n              Show trail\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showEnergy} onChange={e => setShowEnergy(e.target.checked)} className=\"rounded\" />\n              Show energy\n            </label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function CoupledOscillatorsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <CoupledOscillatorsEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/elasticity/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { ElasticityCanvas, ElasticityMode } from '@/components/simulation/ElasticityCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { WIRE_MATERIALS } from '@/lib/physics/elasticity';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction ElasticityEmbedInner() {\n  const sp = useSearchParams();\n  const mode = ((): ElasticityMode => (sp.get('mode') === 'wire' ? 'wire' : 'hooke'))();\n  const showControls = sp.get('controls') !== '0';\n\n  const [load, setLoad] = useState(() => num(sp, 'load', 8, 0, 30));\n  const [k, setK] = useState(() => num(sp, 'k', 200, 50, 500));\n  const [elasticLimitF, setElasticLimitF] = useState(() => num(sp, 'limit', 15, 5, 25));\n\n  const [matIdx, setMatIdx] = useState(() => Math.round(num(sp, 'mat', 0, 0, WIRE_MATERIALS.length - 1)));\n  const [wireLength, setWireLength] = useState(() => num(sp, 'L', 2, 0.5, 5));\n  const [wireDiamMm, setWireDiamMm] = useState(() => num(sp, 'd', 0.5, 0.1, 2));\n  const [wireLoad, setWireLoad] = useState(() => num(sp, 'F', 60, 5, 200));\n  const material = WIRE_MATERIALS[matIdx];\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [unloadKey, setUnloadKey] = useState(0);\n  const [settled, setSettled] = useState(false);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); setSettled(false);\n  }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, load, k, elasticLimitF, matIdx, wireLength, wireDiamMm, wireLoad, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><ElasticityCanvas key={resetKey} mode={mode}\n        load={mode === 'hooke' ? load : wireLoad} k={k} elasticLimitF={elasticLimitF}\n        wireLength={wireLength} wireDiamMm={wireDiamMm} youngE={material.E} materialName={material.name}\n        breakingStressMPa={material.breakingStressMPa}\n        isRunning={isRunning} isPaused={isPaused} unloadKey={unloadKey}\n        onSettled={() => setSettled(true)}\n        width={640} height={320} /></div>\n      <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n        <SimulationControls isRunning={isRunning} isPaused={isPaused}\n          onRun={() => { setIsRunning(true); setIsPaused(false); }}\n          onPause={() => setIsPaused(p => !p)} onReset={reset} />\n        {mode === 'hooke' && settled && (\n          <button onClick={() => { setUnloadKey(k => k + 1); setSettled(false); }}\n            className=\"rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-600 transition hover:bg-gray-50\">\n            Remove load\n          </button>\n        )}\n      </div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {mode === 'hooke' ? <>\n            <Slider label=\"Load\" unit=\"N\" value={load} min={0} max={30} step={0.5} set={setLoad} color=\"#6366f1\" />\n            <Slider label=\"Spring constant\" unit=\"N/m\" value={k} min={50} max={500} step={10} set={setK} color=\"#f59e0b\" />\n            <Slider label=\"Elastic limit\" unit=\"N\" value={elasticLimitF} min={5} max={25} step={1} set={setElasticLimitF} color=\"#ef4444\" />\n          </> : <>\n            <div className=\"flex flex-wrap gap-1.5\">\n              {WIRE_MATERIALS.map((m, i) => (\n                <button key={m.name} onClick={() => setMatIdx(i)}\n                  className={`rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n                    matIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{m.name}</button>\n              ))}\n            </div>\n            <Slider label=\"Load\" unit=\"N\" value={wireLoad} min={5} max={200} step={5} set={setWireLoad} color=\"#6366f1\" />\n            <Slider label=\"Length\" unit=\"m\" value={wireLength} min={0.5} max={5} step={0.1} set={setWireLength} color=\"#10b981\" />\n            <Slider label=\"Diameter\" unit=\"mm\" value={wireDiamMm} min={0.1} max={2} step={0.05} set={setWireDiamMm} color=\"#8b5cf6\" />\n          </>}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ElasticityEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ElasticityEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/electromagnetic-induction/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { InductionCanvas, InductionMode } from '@/components/simulation/InductionCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\ntype Topic = 'faraday-lenz' | 'ac-generator' | 'transformer';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction InductionEmbedInner() {\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'ac-generator' || t === 'transformer' ? t : 'faraday-lenz';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [turns, setTurns] = useState(() => num(sp, 'turns', 8, 2, 20));\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 2, 0.5, 5));\n  const [magnetPoleOut, setMagnetPoleOut] = useState(true);\n\n  const [genFieldB, setGenFieldB] = useState(0.3);\n  const [genArea] = useState(0.02);\n  const [genOmega, setGenOmega] = useState(3);\n\n  const [primaryTurns, setPrimaryTurns] = useState(500);\n  const [secondaryTurns, setSecondaryTurns] = useState(100);\n  const [primaryVoltage] = useState(240);\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, turns, speed, magnetPoleOut, genFieldB, genOmega, primaryTurns, secondaryTurns, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><InductionCanvas key={resetKey} mode={topic as InductionMode}\n        turns={turns} speed={speed} magnetPoleOut={magnetPoleOut}\n        fieldB={genFieldB} coilArea={genArea} omega={genOmega}\n        primaryTurns={primaryTurns} secondaryTurns={secondaryTurns} primaryVoltage={primaryVoltage}\n        isRunning={isRunning} isPaused={isPaused} width={640} height={300} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {topic === 'faraday-lenz' && <>\n            <Slider label=\"Coil turns\" unit=\"\" value={turns} min={2} max={20} step={1} set={setTurns} color=\"#6366f1\" />\n            <Slider label=\"Oscillation speed\" unit=\"rad/s\" value={speed} min={0.5} max={5} step={0.5} set={setSpeed} color=\"#f59e0b\" />\n            <div className=\"flex gap-2\">\n              {([true, false] as const).map(v => (\n                <button key={String(v)} onClick={() => setMagnetPoleOut(v)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                    magnetPoleOut === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{v ? 'N faces coil' : 'S faces coil'}</button>\n              ))}\n            </div>\n          </>}\n          {topic === 'ac-generator' && <>\n            <Slider label=\"Field strength\" unit=\"T\" value={genFieldB} min={0.1} max={1} step={0.05} set={setGenFieldB} color=\"#f59e0b\" />\n            <Slider label=\"Angular speed\" unit=\"rad/s\" value={genOmega} min={1} max={10} step={0.5} set={setGenOmega} color=\"#8b5cf6\" />\n          </>}\n          {topic === 'transformer' && <>\n            <Slider label=\"Primary turns\" unit=\"\" value={primaryTurns} min={50} max={1000} step={50} set={setPrimaryTurns} color=\"#6366f1\" />\n            <Slider label=\"Secondary turns\" unit=\"\" value={secondaryTurns} min={50} max={1000} step={50} set={setSecondaryTurns} color=\"#2563eb\" />\n          </>}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function InductionEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <InductionEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/atomic-models/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { AtomicModelsCanvas } from '@/components/simulation/AtomicModelsCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { AtomicParams, AtomicModel } from '@/lib/physics/atomicModels';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\nfunction bool(sp: URLSearchParams, key: string, fallback: boolean) {\n  const v = sp.get(key); return v !== null ? v === '1' : fallback;\n}\nfunction str<T extends string>(sp: URLSearchParams, key: string, fallback: T, allowed: T[]): T {\n  const v = sp.get(key) as T | null;\n  return v && allowed.includes(v) ? v : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number; step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction AtomicModelsEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [model, setModel] = useState<AtomicModel>(() => str(sp, 'model', 'thomson', ['thomson', 'rutherford', 'bohr', 'quantum']));\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 1, 0, 3));\n  const [zoom, setZoom] = useState(() => num(sp, 'zoom', 1, 0.3, 3));\n  const [showOrbits, setShowOrbits] = useState(() => bool(sp, 'orbits', true));\n  const [showNucleus, setShowNucleus] = useState(() => bool(sp, 'nucleus', true));\n  const [showElectrons, setShowElectrons] = useState(() => bool(sp, 'electrons', true));\n  const [showProbability, setShowProbability] = useState(() => bool(sp, 'prob', true));\n  const [showEnergyLevels, setShowEnergyLevels] = useState(() => bool(sp, 'levels', true));\n  const [showSpectrum, setShowSpectrum] = useState(() => bool(sp, 'spectrum', true));\n  const [showLabels, setShowLabels] = useState(() => bool(sp, 'labels', true));\n  const [showSpin, setShowSpin] = useState(() => bool(sp, 'spin', false));\n  const [showFineStructure, setShowFineStructure] = useState(() => bool(sp, 'fs', false));\n  const [showZeeman, setShowZeeman] = useState(() => bool(sp, 'zeeman', false));\n  const [magneticField, setMagneticField] = useState(() => num(sp, 'B', 0, 0, 5));\n  const [nQuantum, setNQuantum] = useState(() => num(sp, 'n', 1, 1, 4));\n  const [lQuantum, setLQuantum] = useState(() => num(sp, 'l', 0, 0, 3));\n  const [mQuantum, setMQuantum] = useState(() => num(sp, 'm', 0, -3, 3));\n  const [protonCount, setProtonCount] = useState(() => num(sp, 'Z', 1, 1, 92));\n  const [alphaEnergy, setAlphaEnergy] = useState(() => num(sp, 'alphaE', 5, 1, 10));\n\n  const params: AtomicParams = {\n    model, speed, zoom, showOrbits, showNucleus, showElectrons, showProbability,\n    showEnergyLevels, showSpectrum, showLabels, showSpin, showFineStructure, showZeeman,\n    magneticField, nQuantum, lQuantum, mQuantum, protonCount, neutronCount: 0,\n    electronCount: 1, alphaEnergy,\n  };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"parameters\" className=\"flex gap-1 overflow-x-auto pb-1\">\n        {(['thomson', 'rutherford', 'bohr', 'quantum'] as AtomicModel[]).map(m => {\n          const labels: Record<AtomicModel, string> = { thomson: 'Thomson', rutherford: 'Rutherford', bohr: 'Bohr', quantum: 'Quantum' };\n          return (\n            <button key={m} onClick={() => { setModel(m); setIsRunning(false); setResetKey(k => k + 1); }}\n              className={`shrink-0 rounded-lg border px-3 py-1.5 text-xs font-medium transition ${model === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'}`}>\n              {labels[m]}\n            </button>\n          );\n        })}\n      </div>\n\n      <div data-stage-role=\"canvas\"><AtomicModelsCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n          <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.3} max={3} step={0.1} set={setZoom} color=\"#10b981\" />\n          <Slider label=\"Protons Z\" unit=\"\" value={protonCount} min={1} max={92} step={1} set={setProtonCount} color=\"#fbbf24\" />\n          {model === 'rutherford' && <Slider label=\"α energy\" unit=\"MeV\" value={alphaEnergy} min={1} max={10} step={0.5} set={setAlphaEnergy} color=\"#f43f5e\" />}\n          {model === 'bohr' && showZeeman && <Slider label=\"B field\" unit=\"T\" value={magneticField} min={0} max={5} step={0.1} set={setMagneticField} color=\"#8b5cf6\" />}\n          {model === 'quantum' && (\n            <>\n              <Slider label=\"n\" unit=\"\" value={nQuantum} min={1} max={4} step={1} set={setNQuantum} color=\"#6366f1\" />\n              <Slider label=\"l\" unit=\"\" value={lQuantum} min={0} max={nQuantum - 1} step={1} set={setLQuantum} color=\"#ec4899\" />\n              <Slider label=\"m\" unit=\"\" value={mQuantum} min={-lQuantum} max={lQuantum} step={1} set={setMQuantum} color=\"#10b981\" />\n            </>\n          )}\n          <div className=\"flex flex-wrap gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showNucleus} onChange={e => setShowNucleus(e.target.checked)} className=\"rounded\" />Nucleus</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showElectrons} onChange={e => setShowElectrons(e.target.checked)} className=\"rounded\" />Electrons</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showProbability} onChange={e => setShowProbability(e.target.checked)} className=\"rounded\" />Probability</label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showLabels} onChange={e => setShowLabels(e.target.checked)} className=\"rounded\" />Labels</label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><p className=\"text-center text-[10px] text-gray-400\">Powered by <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">A-Factor STEM Studio</a></p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function AtomicModelsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <AtomicModelsEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/oscillations/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useRef, useEffect, useCallback } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { PendulumCanvas } from '@/components/simulation/PendulumCanvas';\nimport { SpringCanvas } from '@/components/simulation/SpringCanvas';\nimport { ConicalPendulumCanvas } from '@/components/simulation/ConicalPendulumCanvas';\nimport { PhysicalPendulumCanvas } from '@/components/simulation/PhysicalPendulumCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { SHMGraph } from '@/components/simulation/SHMGraph';\nimport { pendulumOmega, springOmega, physicalPendulumPeriod } from '@/lib/physics/shm';\n\ntype Topic = 'pendulum' | 'spring' | 'conical' | 'physical';\ntype GraphMode = 'displacement' | 'velocity' | 'acceleration' | 'energy' | 'phase';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction OscillationsEmbedInner() {\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'spring' || t === 'conical' || t === 'physical' ? t : 'pendulum';\n  })();\n  const showGraph = sp.get('graph') !== '0' && topic !== 'conical';\n  // Hide the parameter panel with &controls=0 for a locked, view-only embed.\n  const showControls = sp.get('controls') !== '0';\n  const initialGraphMode = ((): GraphMode => {\n    const gmode = sp.get('gmode');\n    return gmode === 'velocity' || gmode === 'acceleration' || gmode === 'energy' || gmode === 'phase'\n      ? gmode : 'displacement';\n  })();\n\n  // Query params seed the INITIAL values; the sliders make the embed fully\n  // interactive so viewers can explore, not just watch.\n  const [pendL, setPendL] = useState(() => num(sp, 'L', 1.0, 0.1, 3));\n  const [pendA, setPendA] = useState(() => num(sp, 'A', 15, 2, 30));\n  const [pendG, setPendG] = useState(() => num(sp, 'g', 9.81, 1.6, 25));\n  const [pendM, setPendM] = useState(() => num(sp, 'm', 0.5, 0.1, 2));\n  const [spK, setSpK] = useState(() => num(sp, 'k', 50, 5, 500));\n  const [spM, setSpM] = useState(() => num(sp, 'm', 1.0, 0.1, 5));\n  const [spA, setSpA] = useState(() => num(sp, 'A', 0.1, 0.01, 0.3));\n  const [conL, setConL] = useState(() => num(sp, 'L', 0.8, 0.2, 2));\n  const [conTheta, setConTheta] = useState(() => num(sp, 'theta', 30, 5, 75));\n  const [conM, setConM] = useState(() => num(sp, 'm', 0.3, 0.1, 1));\n  const [physL, setPhysL] = useState(() => num(sp, 'L', 1.0, 0.2, 2));\n  const [physM, setPhysM] = useState(() => num(sp, 'm', 0.5, 0.1, 2));\n  const [physPF, setPhysPF] = useState(() => num(sp, 'pf', 0, 0, 0.45));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [graphMode, setGraphMode] = useState<GraphMode>(initialGraphMode);\n  const [currentT, setCurrentT] = useState(0);\n\n  const lastTickRef = useRef(0);\n  const handleTick = (t: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current > 40) {\n      lastTickRef.current = now;\n      setCurrentT(t);\n    }\n  };\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1); setCurrentT(0);\n  }, []);\n\n  // Changing any parameter stops the current run and resets.\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [pendL, pendA, pendG, pendM, spK, spM, spA, conL, conTheta, conM, physL, physM, physPF, reset]);\n\n  // Graph omega/A must match what the canvas actually animates so the live\n  // dot on the curve tracks the bob/mass/rod exactly (see oscillations page).\n  const physD = Math.abs(physL / 2 - physPF * physL) < 0.001 ? 0.001 : Math.abs(physL / 2 - physPF * physL);\n  const physI = physM * physL * physL / 12 + physM * physD * physD;\n  const physT = physicalPendulumPeriod(physI, physM, physD);\n  const graphA = topic === 'pendulum' ? pendA * Math.PI / 180 * pendL :\n                 topic === 'spring' ? spA :\n                 topic === 'physical' ? 0.25 : 0.2;\n  const graphOmega = topic === 'pendulum' ? pendulumOmega(pendL, pendG) :\n                     topic === 'spring' ? springOmega(spK, spM) :\n                     topic === 'physical' ? 2 * Math.PI / physT : 2;\n  const graphM = topic === 'pendulum' ? pendM : topic === 'spring' ? spM :\n                 topic === 'physical' ? physM : 1;\n  const graphK = topic === 'pendulum' ? pendM * graphOmega * graphOmega :\n                 topic === 'spring' ? spK :\n                 graphM * graphOmega * graphOmega;\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n        {topic === 'pendulum' && (\n          <PendulumCanvas key={resetKey} length={pendL} amplitude={pendA} gravity={pendG} mass={pendM}\n            isRunning={isRunning} isPaused={isPaused} onTick={handleTick} width={380} height={280} />\n        )}\n        {topic === 'spring' && (\n          <SpringCanvas key={resetKey} k={spK} mass={spM} amplitude={spA}\n            isRunning={isRunning} isPaused={isPaused} onTick={handleTick} width={280} height={300} />\n        )}\n        {topic === 'conical' && (\n          <ConicalPendulumCanvas key={resetKey} length={conL} theta_deg={conTheta} mass={conM}\n            isRunning={isRunning} isPaused={isPaused} width={380} height={280} />\n        )}\n        {topic === 'physical' && (\n          <PhysicalPendulumCanvas key={resetKey} length={physL} mass={physM} pivotFraction={physPF}\n            isRunning={isRunning} isPaused={isPaused} onTick={handleTick} width={380} height={280} />\n        )}\n      </div>\n\n      <div data-stage-role=\"playback\"><SimulationControls\n        isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)}\n        onReset={reset}\n      /></div>\n\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n          <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2\">\n            {topic === 'pendulum' && <>\n              <Slider label=\"Length\" unit=\"m\" value={pendL} min={0.1} max={3} step={0.05} set={setPendL} color=\"#6366f1\" />\n              <Slider label=\"Amplitude\" unit=\"°\" value={pendA} min={2} max={30} step={1} set={setPendA} color=\"#f59e0b\" />\n              <Slider label=\"Mass\" unit=\"kg\" value={pendM} min={0.1} max={2} step={0.1} set={setPendM} color=\"#94a3b8\" />\n              <Slider label=\"Gravity\" unit=\"m/s²\" value={pendG} min={1.6} max={25} step={0.1} set={setPendG} color=\"#10b981\" />\n            </>}\n            {topic === 'spring' && <>\n              <Slider label=\"Spring constant k\" unit=\"N/m\" value={spK} min={5} max={500} step={5} set={setSpK} color=\"#6366f1\" />\n              <Slider label=\"Mass\" unit=\"kg\" value={spM} min={0.1} max={5} step={0.1} set={setSpM} color=\"#f59e0b\" />\n              <Slider label=\"Amplitude\" unit=\"m\" value={spA} min={0.01} max={0.3} step={0.01} set={setSpA} color=\"#10b981\" />\n            </>}\n            {topic === 'conical' && <>\n              <Slider label=\"String length\" unit=\"m\" value={conL} min={0.2} max={2} step={0.05} set={setConL} color=\"#6366f1\" />\n              <Slider label=\"Half-angle θ\" unit=\"°\" value={conTheta} min={5} max={75} step={1} set={setConTheta} color=\"#f59e0b\" />\n              <Slider label=\"Mass\" unit=\"kg\" value={conM} min={0.1} max={1} step={0.05} set={setConM} color=\"#10b981\" />\n            </>}\n            {topic === 'physical' && <>\n              <Slider label=\"Rod length\" unit=\"m\" value={physL} min={0.2} max={2} step={0.05} set={setPhysL} color=\"#6366f1\" />\n              <Slider label=\"Mass\" unit=\"kg\" value={physM} min={0.1} max={2} step={0.1} set={setPhysM} color=\"#f59e0b\" />\n              <Slider label=\"Pivot (fraction from top)\" unit=\"\" value={physPF} min={0} max={0.45} step={0.05} set={setPhysPF} color=\"#10b981\" />\n            </>}\n          </div>\n        </div>\n      )}</div>\n\n      <div data-stage-role=\"parameters\">{showGraph && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n          <div className=\"mb-2 flex gap-1 overflow-x-auto rounded-lg bg-gray-100 p-0.5\">\n            {(['displacement', 'velocity', 'acceleration', 'energy', 'phase'] as GraphMode[]).map(gm => (\n              <button key={gm} onClick={() => setGraphMode(gm)}\n                className={`shrink-0 rounded-md px-2.5 py-1 text-[10px] font-medium transition ${\n                  graphMode === gm ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500'\n                }`}>\n                {gm === 'displacement' ? 'x–t' : gm === 'velocity' ? 'v–t' : gm === 'acceleration' ? 'a–t' : gm === 'energy' ? 'Energy' : 'Phase'}\n              </button>\n            ))}\n          </div>\n          <SHMGraph A={graphA} omega={graphOmega} m={graphM} k={graphK} mode={graphMode} currentT={currentT} />\n        </div>\n      )}</div>\n\n      <div data-stage-role=\"extra\"><p className=\"text-center text-[10px] text-gray-400\">\n        Powered by{' '}\n        <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n          A-Factor STEM Studio\n        </a>\n      </p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function OscillationsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <OscillationsEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/xrays/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { XrayCanvas } from '@/components/simulation/XrayCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction XraysEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n  const [kV, setKV] = useState(() => num(sp, 'kV', 35, 5, 100));\n  const [current, setCurrent] = useState(() => num(sp, 'i', 5, 1, 10));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [kV, current, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><XrayCanvas kV={kV} current={current} isRunning={isRunning} isPaused={isPaused} width={640} height={300} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Tube voltage\" unit=\"kV\" value={kV} min={5} max={100} step={1} set={setKV} color=\"#6366f1\" />\n          <Slider label=\"Filament current\" unit=\"\" value={current} min={1} max={10} step={1} set={setCurrent} color=\"#f59e0b\" />\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function XraysEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <XraysEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/diffraction/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { DiffractionCanvas, DiffractionMode } from '@/components/simulation/DiffractionCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction DiffractionEmbedInner() {\n  const sp = useSearchParams();\n  const mode = ((): DiffractionMode => {\n    const m = sp.get('mode');\n    return m === 'grating' || m === 'double-slit' ? m : 'single-slit';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [wavelengthNm, setWavelengthNm] = useState(() => num(sp, 'wavelength', 550, 400, 700));\n  const [slitWidthNm, setSlitWidthNm] = useState(() => num(sp, 'width', 1000, 200, 3000));\n  const [slitSpacingNm, setSlitSpacingNm] = useState(() => num(sp, 'spacing', 2000, 500, 5000));\n  const [doubleSlitSepUm, setDoubleSlitSepUm] = useState(() => num(sp, 'sep', 500, 200, 1000));\n  const doubleSlitSepNm = doubleSlitSepUm * 1000;\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, wavelengthNm, slitWidthNm, slitSpacingNm, doubleSlitSepUm, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><DiffractionCanvas key={resetKey} mode={mode} wavelengthNm={wavelengthNm} slitWidthNm={slitWidthNm} slitSpacingNm={slitSpacingNm}\n        doubleSlitSepNm={doubleSlitSepNm}\n        isRunning={isRunning} isPaused={isPaused} width={640} height={280} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Wavelength\" unit=\"nm\" value={wavelengthNm} min={400} max={700} step={10} set={setWavelengthNm} color=\"#6366f1\" />\n          {mode === 'single-slit' && (\n            <Slider label=\"Slit width\" unit=\"nm\" value={slitWidthNm} min={200} max={3000} step={50} set={setSlitWidthNm} color=\"#f59e0b\" />\n          )}\n          {mode === 'grating' && (\n            <Slider label=\"Slit spacing\" unit=\"nm\" value={slitSpacingNm} min={500} max={5000} step={50} set={setSlitSpacingNm} color=\"#f59e0b\" />\n          )}\n          {mode === 'double-slit' && (\n            <Slider label=\"Slit separation\" unit=\"μm\" value={doubleSlitSepUm} min={200} max={1000} step={10} set={setDoubleSlitSepUm} color=\"#f59e0b\" />\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function DiffractionEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <DiffractionEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/bjt-transistor/page.tsx": "// src/app/embed/bjt-transistor/page.tsx\n'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\n\nimport React, { useState } from 'react';\nimport BjtCanvas from '@/components/simulation/BjtCanvas';\nimport { BjtParams, getPreset, PRESET_NAMES, PRESET_LABELS } from '@/lib/physics/bjtTransistor';\n\nexport default function BjtEmbedPage() {\n  const [params, setParams] = useState<BjtParams>(getPreset('cutoff'));\n  const [activePreset, setActivePreset] = useState('cutoff');\n\n  const applyPreset = (name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  };\n\n  return (\n    <div className=\"min-h-screen bg-slate-950 text-slate-100 p-4\">\n      <SimulationStage className=\"af-stage-dark max-w-5xl mx-auto\">\n        <div data-stage-role=\"canvas\"><BjtCanvas params={params} width={800} height={500} /></div>\n\n        <div data-stage-role=\"parameters\" className=\"mt-4 flex flex-wrap gap-2\">\n          {PRESET_NAMES.map(name => (\n            <button\n              key={name}\n              onClick={() => applyPreset(name)}\n              className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${\n                activePreset === name\n                  ? 'bg-blue-600 text-white'\n                  : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n              }`}\n            >\n              {PRESET_LABELS[name]}\n            </button>\n          ))}\n        </div>\n      </SimulationStage>\n    </div>\n  );\n}", "src/app/embed/vectors/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useRef, useState } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { VectorCanvas } from '@/components/simulation/VectorCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { type P3, type View, DEFAULT_VIEW, P, clampTo, fmt } from '@/lib/physics/space';\nimport { type VMode, add, angleBetween, compText, cross, dot, mag, minus, scale, sceneFor } from '@/lib/physics/vectors';\n\nconst MODES: VMode[] = ['components', 'add', 'scalar', 'dot', 'cross'];\n// \"x,y,z\" with every value clamped, so a hand-edited URL cannot break the simulation.\nconst vec = (raw: string | null, dim: '2d' | '3d', fallback: P3): P3 => {\n  if (!raw) return fallback;\n  const [x, y, z] = raw.split(',').map(Number);\n  const c = (n: number) => (Number.isFinite(n) ? clampTo(n, 40) : 0);\n  return P(c(x), c(y), dim === '3d' ? c(z) : 0);\n};\n\nfunction VectorsEmbedInner() {\n  const sp = useSearchParams();\n  const dim: '2d' | '3d' = sp.get('dim') === '3d' ? '3d' : '2d';\n  const m = sp.get('mode') as VMode | null;\n  const mode: VMode = m && MODES.includes(m) ? m : 'add';\n  const [A, setA] = useState<P3>(() => vec(sp.get('A'), dim, dim === '2d' ? P(3, 4) : P(3, 2, 1)));\n  const [B, setB] = useState<P3>(() => vec(sp.get('B'), dim, dim === '2d' ? P(-1, 2) : P(1, 3, 2)));\n  const k = Number.isFinite(Number(sp.get('k'))) ? clampTo(Number(sp.get('k')), 10) : 2;\n  const [view, setView] = useState<View>(DEFAULT_VIEW);\n  const boxRef = useRef<HTMLDivElement>(null);\n  const size = useResponsiveCanvasSize(boxRef, 640, dim === '3d' ? 420 : 400, 900);\n  const h = size.width < 560 ? Math.round(size.width) : size.height;\n  const scene = sceneFor(mode, dim, { A, B, C: P(), k, op: 'A+B', method: 'triangle', useC: false, showComponents: true, showUnit: false, showAngle: true });\n  const onHandle = (id: 'A' | 'B' | 'C', at: P3) => {\n    const hd = scene.handles.find(x => x.id === id); if (!hd) return;\n    const v = scale(minus(at, hd.base), hd.mul ?? 1);\n    if (id === 'A') setA(dim === '2d' ? P(v.x, v.y) : v); else if (id === 'B') setB(dim === '2d' ? P(v.x, v.y) : v);\n  };\n  const stat = (label: string, value: string) => <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">{label} </span><span className=\"font-semibold text-gray-900\">{value}</span></div>;\n  const ang = angleBetween(A, B);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-3xl p-3\">\n      <div data-stage-role=\"canvas\" ref={boxRef} className=\"overflow-hidden rounded-xl border border-gray-200 p-1\">\n        <VectorCanvas dim={dim} width={size.width} height={h} scene={scene} snap={1} view={view} onView={setView} dragAxis=\"floor\" showPlanes showGrid onHandle={onHandle}\n          ariaLabel=\"Vector diagram. Drag the coloured dots at the vector tips.\" />\n      </div>\n      <div data-stage-role=\"extra\" className=\"mt-2 grid gap-2 text-xs sm:grid-cols-2\">\n        {mode === 'components' && <>{stat('|A|', fmt(mag(A)))}{stat('A', compText(A, dim))}</>}\n        {mode === 'add' && <>{stat('A + B', compText(add(A, B), dim))}{stat('|A + B|', fmt(mag(add(A, B))))}</>}\n        {mode === 'scalar' && <>{stat(`${fmt(k)}A`, compText(scale(A, k), dim))}{stat(`|${fmt(k)}A|`, fmt(mag(scale(A, k))))}</>}\n        {mode === 'dot' && <>{stat('A·B', fmt(dot(A, B)))}{stat('Angle', ang === null ? 'undefined' : `${fmt(ang, 1)}°`)}</>}\n        {mode === 'cross' && <>{stat('A × B', compText(cross(A, B), '3d'))}{stat('|A × B|', fmt(mag(cross(A, B))))}</>}\n      </div>\n      <div data-stage-role=\"extra\"><p className=\"mt-1.5 text-[10px] text-gray-400\">{dim === '3d' ? 'Drag empty space to rotate. ' : ''}Drag a coloured dot to change a vector. A-Factor STEM Studio</p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function VectorsEmbedPage() {\n  return <Suspense fallback={<div className=\"p-6 text-sm text-gray-400\">Loading…</div>}><VectorsEmbedInner /></Suspense>;\n}\n", "src/app/embed/reflection/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { ReflectionCanvas, ReflectionMode } from '@/components/simulation/ReflectionCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction ReflectionEmbedInner() {\n  const sp = useSearchParams();\n  const mode = ((): ReflectionMode => {\n    const m = sp.get('mode');\n    return m === 'curved' || m === 'rotation' ? m : 'plane';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [incidenceAngle, setIncidenceAngle] = useState(() => num(sp, 'angle', 35, 5, 80));\n  const [focal, setFocal] = useState(() => num(sp, 'focal', 15, 5, 40));\n  const [objectDist, setObjectDist] = useState(() => num(sp, 'u', 40, 5, 90));\n  const [converging, setConverging] = useState(() => sp.get('conv') !== '0');\n  const [rotationAngle, setRotationAngle] = useState(() => num(sp, 'angle', 15, -35, 35));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, incidenceAngle, focal, objectDist, converging, rotationAngle, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><ReflectionCanvas key={resetKey} mode={mode} incidenceAngle={incidenceAngle}\n        focal={focal} objectDist={objectDist} converging={converging}\n        rotationAngle={rotationAngle} isRunning={isRunning} isPaused={isPaused}\n        width={660} height={320} /></div>\n      <div data-stage-role=\"playback\">{mode === 'rotation' && (\n        <SimulationControls isRunning={isRunning} isPaused={isPaused}\n          onRun={() => { setIsRunning(true); setIsPaused(false); }}\n          onPause={() => setIsPaused(p => !p)} onReset={reset} />\n      )}</div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n          <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2\">\n            {mode === 'plane' && (\n              <Slider label=\"Angle of incidence\" unit=\"°\" value={incidenceAngle} min={5} max={80} step={1} set={setIncidenceAngle} color=\"#6366f1\" />\n            )}\n            {mode === 'curved' && <>\n              <Slider label=\"Focal length |f|\" unit=\"cm\" value={focal} min={5} max={40} step={1} set={setFocal} color=\"#f59e0b\" />\n              <Slider label=\"Object distance u\" unit=\"cm\" value={objectDist} min={5} max={90} step={1} set={setObjectDist} color=\"#6366f1\" />\n              <div className=\"space-y-1\">\n                <span className=\"text-xs text-gray-500\">Type</span>\n                <div className=\"flex gap-2\">\n                  {([true, false] as const).map(c => (\n                    <button key={String(c)} onClick={() => setConverging(c)}\n                      className={`flex-1 rounded-lg border px-2 py-1.5 text-xs font-medium transition ${\n                        converging === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                      }`}>\n                      {c ? 'Concave' : 'Convex'}\n                    </button>\n                  ))}\n                </div>\n              </div>\n            </>}\n            {mode === 'rotation' && (\n              <Slider label=\"Mirror rotation θ\" unit=\"°\" value={rotationAngle} min={-35} max={35} step={1} set={setRotationAngle} color=\"#6366f1\" />\n            )}\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ReflectionEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ReflectionEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/friction/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { FrictionCanvas, FrictionMode } from '@/components/simulation/FrictionCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction ToggleChip({ label, active, onClick, color }: { label: string; active: boolean; onClick: () => void; color: string }) {\n  return (\n    <button onClick={onClick}\n      className={`flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-medium transition ${\n        active ? 'border-transparent text-white' : 'border-gray-200 bg-white text-gray-400'\n      }`}\n      style={active ? { backgroundColor: color } : undefined}>\n      <span className={`inline-block h-1.5 w-1.5 rounded-full ${active ? 'bg-white' : 'bg-gray-300'}`} />\n      {label}\n    </button>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction FrictionEmbedInner() {\n  const sp = useSearchParams();\n  const mode = ((): FrictionMode => (sp.get('mode') === 'incline' ? 'incline' : 'flat'))();\n  const showControls = sp.get('controls') !== '0';\n\n  const [mass, setMass] = useState(() => num(sp, 'mass', 5, 1, 20));\n  const [applied, setApplied] = useState(() => num(sp, 'applied', 25, 0, 80));\n  const [angle, setAngle] = useState(() => num(sp, 'angle', 35, 0, 60));\n  const [appliedIncline, setAppliedIncline] = useState(() => num(sp, 'push', 0, 0, 100));\n  const [muS, setMuS] = useState(() => num(sp, 'muS', 0.4, 0.05, 1));\n  const [muK, setMuK] = useState(() => num(sp, 'muK', 0.3, 0.05, 1));\n\n  const [showWeight, setShowWeight] = useState(true);\n  const [showComponents, setShowComponents] = useState(true);\n  const [showNormal, setShowNormal] = useState(true);\n  const [showFriction, setShowFriction] = useState(true);\n  const [showApplied, setShowApplied] = useState(true);\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [mass, applied, angle, appliedIncline, muS, muK, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><FrictionCanvas key={resetKey} mode={mode} mass={mass} applied={applied} angle={angle}\n        appliedIncline={appliedIncline} muS={muS} muK={muK} isRunning={isRunning} isPaused={isPaused} resetKey={resetKey}\n        showWeight={showWeight} showComponents={showComponents} showNormal={showNormal}\n        showFriction={showFriction} showApplied={showApplied}\n        width={640} height={300} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <>\n          <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n            <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Show forces</p>\n            <div className=\"flex flex-wrap gap-1.5\">\n              <ToggleChip label=\"Weight (mg)\" active={showWeight} onClick={() => setShowWeight(v => !v)} color=\"#8b5cf6\" />\n              {mode === 'incline' && (\n                <ToggleChip label=\"Components\" active={showComponents} onClick={() => setShowComponents(v => !v)} color=\"#a855f7\" />\n              )}\n              <ToggleChip label=\"Normal (N)\" active={showNormal} onClick={() => setShowNormal(v => !v)} color=\"#3b82f6\" />\n              <ToggleChip label=\"Friction (f)\" active={showFriction} onClick={() => setShowFriction(v => !v)} color=\"#ef4444\" />\n              <ToggleChip label=\"Applied (F)\" active={showApplied} onClick={() => setShowApplied(v => !v)} color=\"#059669\" />\n            </div>\n          </div>\n          <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n            <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n            <Slider label=\"Mass\" unit=\"kg\" value={mass} min={1} max={20} step={0.5} set={setMass} color=\"#6366f1\" />\n            {mode === 'flat'\n              ? <Slider label=\"Applied force\" unit=\"N\" value={applied} min={0} max={80} step={1} set={setApplied} color=\"#f59e0b\" />\n              : <>\n                  <Slider label=\"Incline angle\" unit=\"°\" value={angle} min={0} max={60} step={1} set={setAngle} color=\"#f59e0b\" />\n                  <Slider label=\"Push up-slope\" unit=\"N\" value={appliedIncline} min={0} max={100} step={1} set={setAppliedIncline} color=\"#059669\" />\n                </>}\n            <Slider label=\"Static μs\" unit=\"\" value={muS} min={0.05} max={1} step={0.01} set={v => setMuS(Math.max(v, muK))} color=\"#10b981\" />\n            <Slider label=\"Kinetic μk\" unit=\"\" value={muK} min={0.05} max={1} step={0.01} set={v => setMuK(Math.min(v, muS))} color=\"#8b5cf6\" />\n          </div>\n        </>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function FrictionEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <FrictionEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/unit-circle/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useRef, useCallback, useEffect } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { UnitCircleCanvas } from '@/components/simulation/UnitCircleCanvas';\nimport { UnitCircleGraph } from '@/components/simulation/UnitCircleGraph';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { deg2rad, quadrantOf } from '@/lib/physics/unitCircle';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\n// Supported query params:\n//   angleDeg=150   starting angle in degrees (0-360)\n//   unit=rad       show the readout in radians instead of degrees\n//   graph=0        hide the sin/cos graphs\n//   controls=0     lock the embed at the given angle (no dragging, slider or animate) —\n//                  handy for worksheets that need to show one specific angle\nfunction UnitCircleEmbedInner() {\n  const sp = useSearchParams();\n  const showGraph = sp.get('graph') !== '0';\n  const showControls = sp.get('controls') !== '0';\n\n  const [angleDeg, setAngleDeg] = useState(() => num(sp, 'angleDeg', 45, 0, 360));\n  const [unit, setUnit] = useState<'deg' | 'rad'>(sp.get('unit') === 'rad' ? 'rad' : 'deg');\n  const [animating, setAnimating] = useState(false);\n  const animRef = useRef<number>(0);\n  const lastTsRef = useRef<number | null>(null);\n\n  const boxRef = useRef<HTMLDivElement>(null);\n  const size = useResponsiveCanvasSize(boxRef, 420, 420, 420);\n\n  const toggleAnimate = useCallback(() => {\n    if (animating) {\n      cancelAnimationFrame(animRef.current);\n      setAnimating(false);\n      lastTsRef.current = null;\n      return;\n    }\n    setAnimating(true);\n    const step = (ts: number) => {\n      if (lastTsRef.current !== null) {\n        const dt = (ts - lastTsRef.current) / 1000;\n        setAngleDeg(prev => (prev + dt * 60) % 360);\n      }\n      lastTsRef.current = ts;\n      animRef.current = requestAnimationFrame(step);\n    };\n    animRef.current = requestAnimationFrame(step);\n  }, [animating]);\n\n  useEffect(() => () => cancelAnimationFrame(animRef.current), []);\n\n  const rad = deg2rad(angleDeg);\n  const sinVal = Math.sin(rad), cosVal = Math.cos(rad);\n  const quadrant = ['', 'I', 'II', 'III', 'IV'][quadrantOf(angleDeg)];\n  const thetaText = unit === 'deg' ? `${angleDeg.toFixed(1)}°` : `${rad.toFixed(3)} rad`;\n\n  return (\n    <SimulationStage className=\"p-3 flex flex-col md:flex-row gap-3\">\n      <div data-stage-role=\"canvas\" ref={boxRef} className=\"md:w-[420px] md:shrink-0 flex justify-center\">\n        <UnitCircleCanvas\n          angleDeg={angleDeg}\n          onAngleChange={showControls ? setAngleDeg : () => {}}\n          width={size.width}\n          height={size.height}\n        />\n      </div>\n\n      <div data-stage-role=\"parameters\" className=\"flex-1 min-w-0 space-y-3\">\n        <div className=\"grid grid-cols-2 gap-2 text-xs\">\n          {[\n            { l: 'θ', v: thetaText, c: 'text-indigo-600' },\n            { l: 'Quadrant', v: quadrant, c: 'text-gray-700' },\n            { l: 'sin θ', v: sinVal.toFixed(3), c: 'text-rose-600' },\n            { l: 'cos θ', v: cosVal.toFixed(3), c: 'text-amber-600' },\n          ].map(r => (\n            <div key={r.l} className=\"flex justify-between rounded-lg bg-gray-50 px-3 py-2\">\n              <span className=\"text-gray-500\">{r.l}</span>\n              <span className={`font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n            </div>\n          ))}\n        </div>\n\n        {showControls && (\n          <div className=\"flex flex-wrap items-center gap-2\">\n            <button onClick={toggleAnimate}\n              className=\"text-xs px-3 py-1.5 rounded-lg border border-gray-200 bg-white font-medium text-gray-600 hover:border-indigo-300 transition\">\n              {animating ? '⏸ Stop' : '▶ Animate'}\n            </button>\n            <div className=\"flex rounded-lg border border-gray-200 overflow-hidden text-xs\">\n              <button onClick={() => setUnit('deg')}\n                className={`px-3 py-1.5 font-medium transition ${unit === 'deg' ? 'bg-indigo-600 text-white' : 'bg-white text-gray-500'}`}>Degrees</button>\n              <button onClick={() => setUnit('rad')}\n                className={`px-3 py-1.5 font-medium transition ${unit === 'rad' ? 'bg-indigo-600 text-white' : 'bg-white text-gray-500'}`}>Radians</button>\n            </div>\n            <input type=\"range\" min={0} max={360} step={0.5} value={angleDeg}\n              onChange={e => setAngleDeg(Number(e.target.value))}\n              className=\"flex-1 min-w-[120px]\" style={{ accentColor: '#6366f1' }} aria-label=\"Angle\" />\n          </div>\n        )}\n\n        {showGraph && <UnitCircleGraph angleDeg={angleDeg} />}\n\n        <p className=\"text-[10px] text-gray-400\">A-Factor STEM Studio · Unit circle explorer</p>\n      </div>\n    </SimulationStage>\n  );\n}\n\nexport default function UnitCircleEmbedPage() {\n  // useSearchParams() needs a Suspense boundary in the App Router, or the\n  // build fails during static prerendering.\n  return (\n    <Suspense fallback={<div className=\"p-6 text-sm text-gray-400\">Loading…</div>}>\n      <UnitCircleEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/magnetic-effects/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { MagneticFieldCanvas, MagneticMode } from '@/components/simulation/MagneticFieldCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\ntype Topic = 'straight-wire' | 'solenoid' | 'motor-effect';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction MagneticEmbedInner() {\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'solenoid' || t === 'motor-effect' ? t : 'straight-wire';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [current, setCurrent] = useState(() => num(sp, 'current', 5, 1, 20));\n  const [currentOut, setCurrentOut] = useState(() => sp.get('out') !== '0');\n  const [turnsPerMetre, setTurnsPerMetre] = useState(() => num(sp, 'turns', 1000, 200, 3000));\n  const [fieldB, setFieldB] = useState(() => num(sp, 'field', 0.5, 0.1, 2));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, current, currentOut, turnsPerMetre, fieldB, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><MagneticFieldCanvas key={resetKey} mode={topic as MagneticMode} current={current} currentOut={currentOut}\n        turnsPerMetre={turnsPerMetre} fieldB={fieldB}\n        isRunning={isRunning} isPaused={isPaused} width={640} height={300} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Current\" unit=\"A\" value={current} min={1} max={20} step={1} set={setCurrent} color=\"#6366f1\" />\n          <div className=\"flex gap-2\">\n            {([true, false] as const).map(v => (\n              <button key={String(v)} onClick={() => setCurrentOut(v)}\n                className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                  currentOut === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                }`}>{v ? 'Out ⊙' : 'In ⊗'}</button>\n            ))}\n          </div>\n          {topic === 'solenoid' && (\n            <Slider label=\"Turns per metre\" unit=\"n/m\" value={turnsPerMetre} min={200} max={3000} step={100} set={setTurnsPerMetre} color=\"#f59e0b\" />\n          )}\n          {topic === 'motor-effect' && (\n            <Slider label=\"Field strength\" unit=\"T\" value={fieldB} min={0.1} max={2} step={0.1} set={setFieldB} color=\"#f59e0b\" />\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function MagneticEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <MagneticEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/decay/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { DecayCanvas, DecayGraph } from '@/components/simulation/DecayCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction DecayEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n  const showGraph = sp.get('graph') !== '0';\n\n  const [n0, setN0] = useState(() => num(sp, 'n0', 400, 50, 900));\n  const [halfLife, setHalfLife] = useState(() => num(sp, 'hl', 5, 1, 20));\n  const [live, setLive] = useState({ t: 0, n: 400 });\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1); setLive({ t: 0, n: n0 });\n  }, [n0]);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [n0, halfLife, reset]);\n\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((t: number, n: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current > 40) {\n      lastTickRef.current = now;\n      setLive({ t, n });\n    }\n  }, []);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><DecayCanvas n0={n0} halfLife={halfLife} resetKey={resetKey}\n        isRunning={isRunning} isPaused={isPaused} onTick={handleTick}\n        width={640} height={280} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"extra\">{showGraph && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n          <DecayGraph n0={n0} halfLife={halfLife} currentT={live.t} currentN={live.n} />\n        </div>\n      )}</div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n          <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2\">\n            <Slider label=\"Initial nuclei N₀\" unit=\"\" value={n0} min={50} max={900} step={50} set={setN0} color=\"#6366f1\" />\n            <Slider label=\"Half-life T½\" unit=\"s\" value={halfLife} min={1} max={20} step={0.5} set={setHalfLife} color=\"#f59e0b\" />\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function DecayEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <DecayEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/rectilinear-propagation/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { ShadowsCanvas } from '@/components/simulation/ShadowsCanvas';\nimport { EclipseCanvas, EclipseType } from '@/components/simulation/EclipseCanvas';\nimport { PinholeCanvas } from '@/components/simulation/PinholeCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\ntype Topic = 'shadows' | 'eclipse' | 'pinhole';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction RectilinearEmbedInner() {\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'eclipse' || t === 'pinhole' ? t : 'shadows';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [sourceType, setSourceType] = useState<'point' | 'extended'>(() => (sp.get('src') === 'point' ? 'point' : 'extended'));\n  const [sourceRadius, setSourceRadius] = useState(() => num(sp, 'sr', 35, 5, 60));\n  const [objectRadius, setObjectRadius] = useState(() => num(sp, 'or', 24, 8, 50));\n  const [objectDist, setObjectDist] = useState(() => num(sp, 'od', 160, 60, 300));\n  const [screenDist, setScreenDist] = useState(() => num(sp, 'sd', 420, 100, 560));\n\n  const [eclipseType, setEclipseType] = useState<EclipseType>(() => {\n    const v = sp.get('type');\n    return v === 'lunar' || v === 'annular' ? v : 'solar';\n  });\n  const [orbitAngleDeg, setOrbitAngleDeg] = useState(() => num(sp, 'angle', 180, 0, 359));\n\n  const [objectHeight, setObjectHeight] = useState(() => num(sp, 'h', 90, 30, 130));\n  const [pinholeObjectDist, setPinholeObjectDist] = useState(() => num(sp, 'u', 140, 60, 260));\n  const [pinholeScreenDist, setPinholeScreenDist] = useState(() => num(sp, 'v', 160, 40, 260));\n  const [pinholeRadius, setPinholeRadius] = useState(() => num(sp, 'r', 1, 0, 12));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, sourceType, sourceRadius, objectRadius, objectDist, screenDist, eclipseType, orbitAngleDeg, objectHeight, pinholeObjectDist, pinholeScreenDist, pinholeRadius, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\">{topic === 'shadows' && (\n        <ShadowsCanvas key={resetKey} sourceType={sourceType} sourceRadiusPx={sourceRadius} objectRadiusPx={objectRadius}\n          objectDistPx={objectDist} screenDistPx={screenDist}\n          isRunning={isRunning} isPaused={isPaused} width={640} height={280} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'eclipse' && (\n        <EclipseCanvas key={resetKey} eclipseType={eclipseType} orbitAngleDeg={orbitAngleDeg}\n          isRunning={isRunning} isPaused={isPaused} width={640} height={280} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'pinhole' && (\n        <PinholeCanvas objectHeightPx={objectHeight} objectDistPx={pinholeObjectDist} screenDistPx={pinholeScreenDist}\n          pinholeRadiusPx={pinholeRadius} width={640} height={280} />\n      )}</div>\n      <div data-stage-role=\"playback\">{topic !== 'pinhole' && (\n        <SimulationControls isRunning={isRunning} isPaused={isPaused}\n          onRun={() => { setIsRunning(true); setIsPaused(false); }}\n          onPause={() => setIsPaused(p => !p)} onReset={reset} />\n      )}</div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {topic === 'shadows' && <>\n            <div className=\"flex gap-2\">\n              {(['point', 'extended'] as const).map(t => (\n                <button key={t} onClick={() => setSourceType(t)}\n                  className={`flex-1 rounded-lg border px-2 py-1.5 text-xs font-medium capitalize transition ${\n                    sourceType === t ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{t}</button>\n              ))}\n            </div>\n            {sourceType === 'extended' && (\n              <Slider label=\"Source size\" unit=\"px\" value={sourceRadius} min={5} max={60} step={1} set={setSourceRadius} color=\"#fbbf24\" />\n            )}\n            <Slider label=\"Object size\" unit=\"px\" value={objectRadius} min={8} max={50} step={1} set={setObjectRadius} color=\"#64748b\" />\n            <Slider label=\"Object distance\" unit=\"px\" value={objectDist} min={60} max={300} step={5} set={setObjectDist} color=\"#6366f1\" />\n            <Slider label=\"Screen distance\" unit=\"px\" value={screenDist} min={objectDist + 40} max={560} step={5} set={setScreenDist} color=\"#8b5cf6\" />\n          </>}\n          {topic === 'eclipse' && <>\n            <div className=\"flex gap-2\">\n              {(['solar', 'annular', 'lunar'] as const).map(t => (\n                <button key={t} onClick={() => setEclipseType(t)}\n                  className={`flex-1 rounded-lg border px-2 py-1.5 text-xs font-medium capitalize transition ${\n                    eclipseType === t ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{t}</button>\n              ))}\n            </div>\n            <Slider label=\"Moon's orbital position\" unit=\"°\" value={orbitAngleDeg} min={0} max={359} step={1} set={setOrbitAngleDeg} color=\"#6366f1\" />\n          </>}\n          {topic === 'pinhole' && <>\n            <Slider label=\"Object height\" unit=\"px\" value={objectHeight} min={30} max={130} step={5} set={setObjectHeight} color=\"#0f172a\" />\n            <Slider label=\"Object distance (u)\" unit=\"px\" value={pinholeObjectDist} min={60} max={260} step={5} set={setPinholeObjectDist} color=\"#6366f1\" />\n            <Slider label=\"Screen distance (v)\" unit=\"px\" value={pinholeScreenDist} min={40} max={260} step={5} set={setPinholeScreenDist} color=\"#8b5cf6\" />\n            <Slider label=\"Pinhole size\" unit=\"px\" value={pinholeRadius} min={0} max={12} step={0.5} set={setPinholeRadius} color=\"#f59e0b\" />\n          </>}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function RectilinearEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <RectilinearEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/electrostatics-fields/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { CoulombsLawCanvas } from '@/components/simulation/CoulombsLawCanvas';\nimport { ElectricFieldCanvas, FieldConfiguration } from '@/components/simulation/ElectricFieldCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\ntype Topic = 'coulomb' | 'field';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction ElectrostaticsFieldsEmbedInner() {\n  const sp = useSearchParams();\n  const topic = ((): Topic => (sp.get('topic') === 'field' ? 'field' : 'coulomb'))();\n  const showControls = sp.get('controls') !== '0';\n\n  const [q1nC, setQ1nC] = useState(() => num(sp, 'q1', 20, -50, 50));\n  const [q2nC, setQ2nC] = useState(() => num(sp, 'q2', 20, -50, 50));\n  const [separationCm, setSeparationCm] = useState(() => num(sp, 'sep', 10, 5, 30));\n\n  const [fieldConfig, setFieldConfig] = useState<FieldConfiguration>(() => {\n    const c = sp.get('config');\n    return c === 'single-negative' || c === 'dipole' || c === 'like-charges' ? c : 'single-positive';\n  });\n  const [testX, setTestX] = useState(() => num(sp, 'testX', 0.75, 0.05, 0.95));\n  const [testY, setTestY] = useState(() => num(sp, 'testY', 0.3, 0.1, 0.9));\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 340, 1600);\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, q1nC, q2nC, separationCm, fieldConfig, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\" ref={canvasBoxRef}>\n      {topic === 'coulomb' && (\n        <CoulombsLawCanvas key={resetKey} q1nC={q1nC} q2nC={q2nC} initialSeparationCm={separationCm}\n          isRunning={isRunning} isPaused={isPaused} width={canvasSize.width} height={canvasSize.height} />\n      )}\n      {topic === 'field' && (\n        <ElectricFieldCanvas onTestPositionChange={(x, y) => { setTestX(x); setTestY(y); }} key={resetKey} configuration={fieldConfig} testX={testX} testY={testY}\n          isRunning={isRunning} isPaused={isPaused} width={canvasSize.width} height={canvasSize.height} />\n      )}\n      </div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {topic === 'coulomb' && <>\n            <Slider label=\"Charge Q1\" unit=\"nC\" value={q1nC} min={-50} max={50} step={5} set={setQ1nC} color=\"#dc2626\" />\n            <Slider label=\"Charge Q2\" unit=\"nC\" value={q2nC} min={-50} max={50} step={5} set={setQ2nC} color=\"#2563eb\" />\n            <Slider label=\"Initial separation\" unit=\"cm\" value={separationCm} min={5} max={30} step={1} set={setSeparationCm} color=\"#6366f1\" />\n          </>}\n          {topic === 'field' && <>\n            <p className=\"text-xs text-gray-700\">Tap or drag the test point on the canvas, or use these sliders.</p>\n            <Slider label=\"Test point horizontal\" unit=\"\" value={testX} min={0.05} max={0.95} step={0.01} set={setTestX} color=\"#f59e0b\" />\n            <Slider label=\"Test point vertical\" unit=\"\" value={testY} min={0.1} max={0.9} step={0.01} set={setTestY} color=\"#f59e0b\" />\n            <div className=\"grid grid-cols-2 gap-2\">\n              {([\n                ['single-positive', 'Single +'], ['single-negative', 'Single −'],\n                ['dipole', 'Dipole (+/−)'], ['like-charges', 'Like charges'],\n              ] as [FieldConfiguration, string][]).map(([cfg, label]) => (\n                <button key={cfg} onClick={() => setFieldConfig(cfg)}\n                  className={`rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                    fieldConfig === cfg ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{label}</button>\n              ))}\n            </div>\n          </>}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ElectrostaticsFieldsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ElectrostaticsFieldsEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/polarization/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { PolarizationCanvas, PolarizationMode } from '@/components/simulation/PolarizationCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction PolarizationEmbedInner() {\n  const sp = useSearchParams();\n  const mode = ((): PolarizationMode => (sp.get('mode') === 'malus' ? 'malus' : 'single'))();\n  const showControls = sp.get('controls') !== '0';\n\n  const [polarizerAngle, setPolarizerAngle] = useState(() => num(sp, 'angle', 30, 0, 180));\n  const [analyzerAngle, setAnalyzerAngle] = useState(() => num(sp, 'angle', 45, 0, 180));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, polarizerAngle, analyzerAngle, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><PolarizationCanvas key={resetKey} mode={mode} polarizerAngle={polarizerAngle} analyzerAngle={analyzerAngle}\n        isRunning={isRunning} isPaused={isPaused} width={640} height={240} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {mode === 'single'\n            ? <Slider label=\"Transmission axis\" unit=\"°\" value={polarizerAngle} min={0} max={180} step={5} set={setPolarizerAngle} color=\"#6366f1\" />\n            : <Slider label=\"Analyser angle\" unit=\"°\" value={analyzerAngle} min={0} max={180} step={1} set={setAnalyzerAngle} color=\"#6366f1\" />}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function PolarizationEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <PolarizationEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/electrostatics-potential/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { PotentialCanvas } from '@/components/simulation/PotentialCanvas';\nimport { EquipotentialCanvas, EquipotentialConfig } from '@/components/simulation/EquipotentialCanvas';\nimport { CapacitorCanvas } from '@/components/simulation/CapacitorCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\ntype Topic = 'potential' | 'equipotential' | 'capacitor';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction ElectrostaticsPotentialEmbedInner() {\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'equipotential' || t === 'capacitor' ? t : 'potential';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [q1nC, setQ1nC] = useState(() => num(sp, 'q1', 20, -50, 50));\n  const [q2nC, setQ2nC] = useState(() => num(sp, 'q2', -20, -50, 50));\n  const [separationCm, setSeparationCm] = useState(() => num(sp, 'sep', 10, 5, 25));\n\n  const [equipConfig, setEquipConfig] = useState<EquipotentialConfig>(() => {\n    const c = sp.get('config');\n    return c === 'single-negative' || c === 'dipole' || c === 'like-charges' ? c : 'single-positive';\n  });\n\n  const [voltageV, setVoltageV] = useState(() => num(sp, 'v', 9, 1, 20));\n  const [resistanceOhm, setResistanceOhm] = useState(() => num(sp, 'r', 2000, 500, 5000));\n  const [capacitanceUf, setCapacitanceUf] = useState(() => num(sp, 'c', 100, 50, 500));\n  const [dischargeKey, setDischargeKey] = useState(0);\n  const [liveCapacitor, setLiveCapacitor] = useState<{ phase: 'charging' | 'discharging' }>({ phase: 'charging' });\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); setDischargeKey(0); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, q1nC, q2nC, separationCm, equipConfig, voltageV, resistanceOhm, capacitanceUf, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\">{topic === 'potential' && (\n        <PotentialCanvas key={resetKey} q1nC={q1nC} q2nC={q2nC} initialSeparationCm={separationCm}\n          isRunning={isRunning} isPaused={isPaused} width={640} height={280} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'equipotential' && (\n        <EquipotentialCanvas configuration={equipConfig} width={640} height={300} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'capacitor' && (\n        <CapacitorCanvas key={resetKey} voltageV={voltageV} resistanceOhm={resistanceOhm} capacitanceUf={capacitanceUf}\n          isRunning={isRunning} isPaused={isPaused} dischargeKey={dischargeKey}\n          onTick={(_v, ph) => setLiveCapacitor({ phase: ph })} width={640} height={300} />\n      )}</div>\n      <div data-stage-role=\"playback\">{topic !== 'equipotential' && (\n        <div className=\"flex flex-wrap items-center gap-2\">\n          <SimulationControls isRunning={isRunning} isPaused={isPaused}\n            onRun={() => { setIsRunning(true); setIsPaused(false); }}\n            onPause={() => setIsPaused(p => !p)} onReset={reset} />\n          {topic === 'capacitor' && isRunning && liveCapacitor.phase === 'charging' && (\n            <button onClick={() => setDischargeKey(k => k + 1)}\n              className=\"rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-600 transition hover:bg-gray-50\">\n              Discharge\n            </button>\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {topic === 'potential' && <>\n            <Slider label=\"Charge Q1\" unit=\"nC\" value={q1nC} min={-50} max={50} step={5} set={setQ1nC} color=\"#dc2626\" />\n            <Slider label=\"Charge Q2\" unit=\"nC\" value={q2nC} min={-50} max={50} step={5} set={setQ2nC} color=\"#2563eb\" />\n            <Slider label=\"Initial separation\" unit=\"cm\" value={separationCm} min={5} max={25} step={1} set={setSeparationCm} color=\"#6366f1\" />\n          </>}\n          {topic === 'equipotential' && (\n            <div className=\"grid grid-cols-2 gap-2\">\n              {([\n                ['single-positive', 'Single +'], ['single-negative', 'Single −'],\n                ['dipole', 'Dipole (+/−)'], ['like-charges', 'Like charges'],\n              ] as [EquipotentialConfig, string][]).map(([cfg, label]) => (\n                <button key={cfg} onClick={() => setEquipConfig(cfg)}\n                  className={`rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                    equipConfig === cfg ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{label}</button>\n              ))}\n            </div>\n          )}\n          {topic === 'capacitor' && <>\n            <Slider label=\"Supply voltage\" unit=\"V\" value={voltageV} min={1} max={20} step={1} set={setVoltageV} color=\"#6366f1\" />\n            <Slider label=\"Resistance\" unit=\"Ω\" value={resistanceOhm} min={500} max={5000} step={100} set={setResistanceOhm} color=\"#f59e0b\" />\n            <Slider label=\"Capacitance\" unit=\"µF\" value={capacitanceUf} min={50} max={500} step={10} set={setCapacitanceUf} color=\"#8b5cf6\" />\n          </>}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ElectrostaticsPotentialEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ElectrostaticsPotentialEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/quantum-tunneling/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { QuantumTunnelingCanvas } from '@/components/simulation/QuantumTunnelingCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { TunnelingParams, PotentialType } from '@/lib/physics/quantumTunneling';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction bool(sp: URLSearchParams, key: string, fallback: boolean) {\n  const v = sp.get(key);\n  return v !== null ? v === '1' : fallback;\n}\n\nfunction str<T extends string>(sp: URLSearchParams, key: string, fallback: T, allowed: T[]): T {\n  const v = sp.get(key) as T | null;\n  return v && allowed.includes(v) ? v : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">\n          {value} <span className=\"font-normal text-gray-400\">{unit}</span>\n        </span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction QuantumTunnelingEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n  const [potentialType, setPotentialType] = useState<PotentialType>(() => str(sp, 'type', 'barrier', ['barrier', 'well', 'step', 'double', 'triangular'] as PotentialType[]));\n  const [particleEnergy, setParticleEnergy] = useState(() => num(sp, 'E', 1, 0.1, 10));\n  const [barrierHeight, setBarrierHeight] = useState(() => num(sp, 'V', 2, 0.5, 10));\n  const [barrierWidth, setBarrierWidth] = useState(() => num(sp, 'w', 2, 0.5, 10));\n  const [barrierPosition, setBarrierPosition] = useState(() => num(sp, 'pos', 25, 10, 45));\n  const [packetWidth, setPacketWidth] = useState(() => num(sp, 'sigma', 1.5, 0.5, 4));\n  const [particleMass, setParticleMass] = useState(() => num(sp, 'm', 1, 0.2, 20));\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 1, 0, 3));\n  const [showPotential, setShowPotential] = useState(() => bool(sp, 'pot', true));\n  const [showProbability, setShowProbability] = useState(() => bool(sp, 'prob', true));\n  const [showRealPart, setShowRealPart] = useState(() => bool(sp, 're', true));\n  const [showImaginaryPart, setShowImaginaryPart] = useState(() => bool(sp, 'im', false));\n  const [showPhase, setShowPhase] = useState(() => bool(sp, 'phase', false));\n  const [showClassical, setShowClassical] = useState(() => bool(sp, 'classical', false));\n  const [showEnergyLine, setShowEnergyLine] = useState(() => bool(sp, 'eline', true));\n  const [autoRestart, setAutoRestart] = useState(() => bool(sp, 'auto', true));\n\n  const params: TunnelingParams = {\n    potentialType, particleEnergy, barrierHeight, barrierWidth, barrierPosition,\n    packetWidth, particleMass, speed, zoom: 1,\n    showPotential, showProbability, showRealPart, showImaginaryPart,\n    showPhase, showClassical, showEnergyLine, autoRestart,\n  };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey((k) => k + 1); }, []);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"parameters\" className=\"flex gap-1 overflow-x-auto pb-1\">\n        {(['barrier', 'well', 'step', 'double', 'triangular'] as PotentialType[]).map((m) => {\n          const labels: Record<PotentialType, string> = { barrier: 'Barrier', well: 'Well', step: 'Step', double: 'Double', triangular: 'Triangular' };\n          return (\n            <button key={m} onClick={() => { setPotentialType(m); setIsRunning(false); setResetKey((k) => k + 1); }}\n              className={`shrink-0 rounded-lg border px-3 py-1.5 text-xs font-medium transition ${potentialType === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'}`}>\n              {labels[m]}\n            </button>\n          );\n        })}\n      </div>\n\n      <div data-stage-role=\"canvas\"><QuantumTunnelingCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} width={640} height={420} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused((p) => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Energy\" unit=\"eV\" value={particleEnergy} min={0.1} max={10} step={0.1} set={setParticleEnergy} color=\"#6366f1\" />\n          <Slider label=\"Barrier height\" unit=\"eV\" value={barrierHeight} min={0.5} max={10} step={0.1} set={setBarrierHeight} color=\"#fbbf24\" />\n          <Slider label=\"Barrier width\" unit=\"Å\" value={barrierWidth} min={0.5} max={10} step={0.1} set={setBarrierWidth} color=\"#f59e0b\" />\n          <Slider label=\"Mass\" unit=\"mₑ\" value={particleMass} min={0.2} max={20} step={0.1} set={setParticleMass} color=\"#10b981\" />\n          <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n          <div className=\"flex flex-wrap gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showPotential} onChange={(e) => setShowPotential(e.target.checked)} className=\"rounded\" />Potential\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showProbability} onChange={(e) => setShowProbability(e.target.checked)} className=\"rounded\" />|ψ|²\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showRealPart} onChange={(e) => setShowRealPart(e.target.checked)} className=\"rounded\" />Re(ψ)\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showEnergyLine} onChange={(e) => setShowEnergyLine(e.target.checked)} className=\"rounded\" />Energy line\n            </label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function QuantumTunnelingEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <QuantumTunnelingEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/electrostatics-charging/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { ChargingMethodsCanvas, ChargingMethod } from '@/components/simulation/ChargingMethodsCanvas';\nimport { ElectroscopeCanvas, ElectroscopeMode } from '@/components/simulation/ElectroscopeCanvas';\nimport { ElectrophorusCanvas } from '@/components/simulation/ElectrophorusCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\ntype Topic = 'production' | 'electroscope' | 'electrophorus';\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction ElectrostaticsChargingEmbedInner() {\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'electroscope' || t === 'electrophorus' ? t : 'production';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [method, setMethod] = useState<ChargingMethod>(() => {\n    const m = sp.get('method');\n    return m === 'conduction' || m === 'induction' ? m : 'friction';\n  });\n  const [electroscopeMode, setElectroscopeMode] = useState<ElectroscopeMode>(() => (sp.get('mode') === 'testing' ? 'testing' : 'charging'));\n  const [rodSign, setRodSign] = useState<1 | -1>(() => (sp.get('rod') === '-1' ? -1 : 1));\n  const [electroscopeSign, setElectroscopeSign] = useState<1 | -1>(() => (sp.get('es') === '1' ? 1 : -1));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [electrophorusCycle, setElectrophorusCycle] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); setElectrophorusCycle(0); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, method, electroscopeMode, rodSign, electroscopeSign, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\">{topic === 'production' && (\n        <ChargingMethodsCanvas key={resetKey} method={method} rodSign={rodSign} isRunning={isRunning} isPaused={isPaused} width={640} height={300} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'electroscope' && (\n        <ElectroscopeCanvas key={resetKey} mode={electroscopeMode} rodSign={rodSign} electroscopeSign={electroscopeSign}\n          isRunning={isRunning} isPaused={isPaused} width={640} height={300} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'electrophorus' && (\n        <ElectrophorusCanvas key={resetKey} isRunning={isRunning} isPaused={isPaused}\n          cycleCount={electrophorusCycle} onCycleComplete={() => setElectrophorusCycle(c => c + 1)} width={640} height={300} />\n      )}</div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {topic === 'production' && (\n            <div className=\"flex flex-col gap-2\">\n              {(['friction', 'conduction', 'induction'] as const).map(m => (\n                <button key={m} onClick={() => setMethod(m)}\n                  className={`rounded-lg border px-3 py-2 text-xs font-medium capitalize text-left transition ${\n                    method === m ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{m}</button>\n              ))}\n              {method !== 'friction' && (\n                <div className=\"flex gap-2 pt-1\">\n                  {([1, -1] as const).map(sgn => (\n                    <button key={sgn} onClick={() => setRodSign(sgn)}\n                      className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                        rodSign === sgn ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                      }`}>Rod: {sgn > 0 ? '+' : '−'}</button>\n                  ))}\n                </div>\n              )}\n            </div>\n          )}\n          {topic === 'electroscope' && <>\n            <div className=\"flex gap-2\">\n              {(['charging', 'testing'] as const).map(m => (\n                <button key={m} onClick={() => setElectroscopeMode(m)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                    electroscopeMode === m ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{m}</button>\n              ))}\n            </div>\n            {electroscopeMode === 'testing' && (\n              <div className=\"flex gap-2\">\n                {([1, -1] as const).map(sgn => (\n                  <button key={sgn} onClick={() => setElectroscopeSign(sgn)}\n                    className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                      electroscopeSign === sgn ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                    }`}>Electroscope: {sgn > 0 ? '+' : '−'}</button>\n                ))}\n              </div>\n            )}\n            <div className=\"flex gap-2\">\n              {([1, -1] as const).map(sgn => (\n                <button key={sgn} onClick={() => setRodSign(sgn)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                    rodSign === sgn ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>Rod: {sgn > 0 ? '+' : '−'}</button>\n              ))}\n            </div>\n          </>}\n          {topic === 'electrophorus' && (\n            <p className=\"text-xs text-gray-500\">Press Run to lower the disc, earth it, and lift it away.</p>\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ElectrostaticsChargingEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ElectrostaticsChargingEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/heat/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { HeatTransferCanvas, HeatMode } from '@/components/simulation/HeatTransferCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { MATERIALS } from '@/lib/physics/heat';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction HeatEmbedInner() {\n  const sp = useSearchParams();\n  const mode = ((): HeatMode => {\n    const m = sp.get('mode');\n    return m === 'convection' || m === 'radiation' ? m : 'conduction';\n  })();\n  const showControls = sp.get('controls') !== '0';\n  const [hotTemp, setHotTemp] = useState(() => num(sp, 'hot', 90, 30, 120));\n  const [coldTemp, setColdTemp] = useState(() => num(sp, 'cold', 20, 0, 40));\n  const [materialIdx, setMaterialIdx] = useState(() => {\n    const i = MATERIALS.findIndex(m => m.name === sp.get('material'));\n    return i >= 0 ? i : 0;\n  });\n  const material = MATERIALS[materialIdx];\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [mode, hotTemp, coldTemp, materialIdx, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><HeatTransferCanvas mode={mode} hotTemp={hotTemp} coldTemp={coldTemp} materialK={material.k}\n        isRunning={isRunning} isPaused={isPaused} width={640} height={300} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Hot temperature\" unit=\"°C\" value={hotTemp} min={30} max={120} step={5} set={setHotTemp} color=\"#ef4444\" />\n          <Slider label=\"Cold temperature\" unit=\"°C\" value={coldTemp} min={0} max={40} step={5} set={setColdTemp} color=\"#3b82f6\" />\n          {mode === 'conduction' && (\n            <div className=\"grid grid-cols-2 gap-1.5\">\n              {MATERIALS.map((m, i) => (\n                <button key={m.name} onClick={() => setMaterialIdx(i)}\n                  className={`rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                    materialIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{m.name}</button>\n              ))}\n            </div>\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function HeatEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <HeatEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/quantum-harmonic-oscillator/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useRef, useMemo } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { QuantumHarmonicOscillatorCanvas } from '@/components/simulation/QuantumHarmonicOscillatorCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { QHOParams, normalize } from '@/lib/physics/quantumHarmonicOscillator';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction bool(sp: URLSearchParams, key: string, fallback: boolean) {\n  const v = sp.get(key);\n  return v !== null ? v === '1' : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">\n          {value} <span className=\"font-normal text-gray-400\">{unit}</span>\n        </span>\n      </div>\n      <input\n        type=\"range\"\n        min={min}\n        max={max}\n        step={step}\n        value={value}\n        onChange={(e) => set(Number(e.target.value))}\n        className=\"w-full\"\n        style={{ accentColor: color }}\n      />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction QuantumHOEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [c0, setC0] = useState(() => num(sp, 'c0', 1, 0, 1));\n  const [c1, setC1] = useState(() => num(sp, 'c1', 0, 0, 1));\n  const [c2, setC2] = useState(() => num(sp, 'c2', 0, 0, 1));\n  const [c3, setC3] = useState(() => num(sp, 'c3', 0, 0, 1));\n  const [c4, setC4] = useState(() => num(sp, 'c4', 0, 0, 1));\n  const [c5, setC5] = useState(() => num(sp, 'c5', 0, 0, 1));\n\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 1, 0, 3));\n  const [xMax, setXMax] = useState(() => num(sp, 'xmax', 5, 3, 12));\n  const [eMax, setEMax] = useState(() => num(sp, 'emax', 4.5, 2, 8));\n  const [nMax, setNMax] = useState(() => num(sp, 'nmax', 5, 1, 8));\n\n  const [showPotential, setShowPotential] = useState(() => bool(sp, 'potential', true));\n  const [showEnergyLevels, setShowEnergyLevels] = useState(() => bool(sp, 'levels', true));\n  const [showProbability, setShowProbability] = useState(() => bool(sp, 'prob', true));\n  const [showReal, setShowReal] = useState(() => bool(sp, 'real', false));\n  const [showImaginary, setShowImaginary] = useState(() => bool(sp, 'imag', false));\n  const [showClassicalTurning, setShowClassicalTurning] = useState(() => bool(sp, 'turning', true));\n\n  const coeffs = useMemo(() => normalize([c0, c1, c2, c3, c4, c5]), [c0, c1, c2, c3, c4, c5]);\n\n  const params: QHOParams = {\n    speed,\n    xMax,\n    eMax,\n    nMax,\n    showPotential,\n    showEnergyLevels,\n    showProbability,\n    showReal,\n    showImaginary,\n    showClassicalTurning,\n  };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => {\n    setIsRunning(false);\n    setIsPaused(false);\n    setResetKey((k) => k + 1);\n  }, []);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><QuantumHarmonicOscillatorCanvas\n        key={resetKey}\n        coeffs={coeffs}\n        params={params}\n        isRunning={isRunning}\n        isPaused={isPaused}\n        width={640}\n        height={400}\n      /></div>\n      <div data-stage-role=\"playback\"><SimulationControls\n        isRunning={isRunning}\n        isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused((p) => !p)}\n        onReset={reset}\n      /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"c₀\" unit=\"\" value={c0} min={0} max={1} step={0.01} set={setC0} color=\"#6366f1\" />\n          <Slider label=\"c₁\" unit=\"\" value={c1} min={0} max={1} step={0.01} set={setC1} color=\"#8b5cf6\" />\n          <Slider label=\"c₂\" unit=\"\" value={c2} min={0} max={1} step={0.01} set={setC2} color=\"#ec4899\" />\n          <Slider label=\"c₃\" unit=\"\" value={c3} min={0} max={1} step={0.01} set={setC3} color=\"#f43f5e\" />\n          <Slider label=\"c₄\" unit=\"\" value={c4} min={0} max={1} step={0.01} set={setC4} color=\"#f59e0b\" />\n          <Slider label=\"c₅\" unit=\"\" value={c5} min={0} max={1} step={0.01} set={setC5} color=\"#10b981\" />\n          <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n          <Slider label=\"X-range\" unit=\"a\" value={xMax} min={3} max={12} step={0.5} set={setXMax} color=\"#10b981\" />\n          <Slider label=\"E-range\" unit=\"ℏω\" value={eMax} min={2} max={8} step={0.5} set={setEMax} color=\"#ef4444\" />\n          <div className=\"flex flex-wrap gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showPotential} onChange={(e) => setShowPotential(e.target.checked)} className=\"rounded\" />\n              Potential\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showEnergyLevels} onChange={(e) => setShowEnergyLevels(e.target.checked)} className=\"rounded\" />\n              Levels\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showProbability} onChange={(e) => setShowProbability(e.target.checked)} className=\"rounded\" />\n              |ψ|²\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showReal} onChange={(e) => setShowReal(e.target.checked)} className=\"rounded\" />\n              Re(ψ)\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showImaginary} onChange={(e) => setShowImaginary(e.target.checked)} className=\"rounded\" />\n              Im(ψ)\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showClassicalTurning} onChange={(e) => setShowClassicalTurning(e.target.checked)} className=\"rounded\" />\n              Turning pts\n            </label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function QuantumHOEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <QuantumHOEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/projectile/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useMemo, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { ProjectileModeCanvas, ProjectileMode } from '@/components/simulation/ProjectileModeCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport type {\n  StandardParams, HorizontalParams, VerticalParams, InclinedParams,\n} from '@/lib/physics/projectile-modes';\n\n// Reads a numeric query param with clamping so a hand-edited embed URL can't\n// produce a broken simulation.\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction ProjectileEmbedInner() {\n  const sp = useSearchParams();\n\n  const mode = ((): ProjectileMode => {\n    const m = sp.get('mode');\n    return m === 'horizontal' || m === 'vertical' || m === 'inclined' ? m : 'standard';\n  })();\n\n  // Hide the parameter panel with &controls=0 for a locked, view-only embed.\n  const showControls = sp.get('controls') !== '0';\n\n  // Query params seed the INITIAL values; the sliders below make the embed\n  // fully interactive so viewers can explore, not just watch.\n  const [g, setG] = useState(() => num(sp, 'g', 9.81, 1, 25));\n  const [v0, setV0] = useState(() => num(sp, 'v0', mode === 'standard' ? 25 : mode === 'horizontal' ? 20 : mode === 'vertical' ? 15 : 20, mode === 'vertical' ? -30 : 1, mode === 'inclined' ? 60 : mode === 'vertical' ? 50 : 100));\n  const [angle, setAngle] = useState(() => num(sp, 'angle', 45, 1, 89));\n  const [h0, setH0] = useState(() => num(sp, 'h0', 0, 0, 200));\n  const [hH, setHH] = useState(() => num(sp, 'h', 30, 1, 200));\n  const [iAlpha, setIAlpha] = useState(() => num(sp, 'alpha', 30, 1, 89));\n  const [iBeta, setIBeta] = useState(() => num(sp, 'beta', 30, 5, 60));\n  const [launchFrom, setLaunchFrom] = useState<'base' | 'top'>(() => (sp.get('launch') === 'top' ? 'top' : 'base'));\n\n  const std: StandardParams   = useMemo(() => ({ v0, angle, g, h0 }), [v0, angle, g, h0]);\n  const hrz: HorizontalParams = useMemo(() => ({ v0, h: hH, g }), [v0, hH, g]);\n  const vtc: VerticalParams   = useMemo(() => ({ v0, h0, g }), [v0, h0, g]);\n  const inc: InclinedParams   = useMemo(\n    () => ({ v0, alpha: iAlpha, beta: iBeta, g, launchFrom }),\n    [v0, iAlpha, iBeta, g, launchFrom]\n  );\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [isComplete, setIsComplete] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false); setIsComplete(false);\n    setResetKey(k => k + 1);\n  }, []);\n  const handleComplete = useCallback(() => { setIsComplete(true); setIsRunning(false); }, []);\n\n  // Changing any parameter stops the current run and resets — same behaviour\n  // as the full simulation page.\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [v0, angle, g, h0, hH, iAlpha, iBeta, launchFrom, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-3xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><ProjectileModeCanvas\n        key={resetKey}\n        mode={mode}\n        standard={std} horizontal={hrz} vertical={vtc} inclined={inc}\n        isRunning={isRunning} isPaused={isPaused}\n        onComplete={handleComplete}\n        width={720} height={340}\n      /></div>\n      <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n        <SimulationControls\n          isRunning={isRunning && !isComplete} isPaused={isPaused}\n          onRun={() => { setIsRunning(true); setIsPaused(false); setIsComplete(false); }}\n          onPause={() => setIsPaused(p => !p)}\n          onReset={reset}\n        />\n        {isComplete && <span className=\"text-xs font-medium text-emerald-600\">✓ Complete</span>}\n      </div>\n\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n          <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2\">\n            <Slider label=\"Gravity\" unit=\"m/s²\" value={g} min={1} max={25} step={0.1} set={setG} color=\"#10b981\" />\n            {mode === 'standard' && <>\n              <Slider label=\"Initial velocity\" unit=\"m/s\" value={v0} min={1} max={100} step={1} set={setV0} color=\"#6366f1\" />\n              <Slider label=\"Launch angle\" unit=\"°\" value={angle} min={1} max={89} step={1} set={setAngle} color=\"#f59e0b\" />\n              <Slider label=\"Platform height\" unit=\"m\" value={h0} min={0} max={120} step={1} set={setH0} color=\"#8b5cf6\" />\n            </>}\n            {mode === 'horizontal' && <>\n              <Slider label=\"Horizontal speed\" unit=\"m/s\" value={v0} min={1} max={100} step={1} set={setV0} color=\"#6366f1\" />\n              <Slider label=\"Launch height\" unit=\"m\" value={hH} min={1} max={200} step={1} set={setHH} color=\"#8b5cf6\" />\n            </>}\n            {mode === 'vertical' && <>\n              <Slider label=\"Initial velocity (↑ +)\" unit=\"m/s\" value={v0} min={-30} max={50} step={1} set={setV0} color=\"#6366f1\" />\n              <Slider label=\"Initial height\" unit=\"m\" value={h0} min={0} max={200} step={1} set={setH0} color=\"#8b5cf6\" />\n            </>}\n            {mode === 'inclined' && <>\n              <Slider label=\"Initial velocity\" unit=\"m/s\" value={v0} min={1} max={60} step={1} set={setV0} color=\"#6366f1\" />\n              <Slider label=\"α — angle above slope\" unit=\"°\" value={iAlpha} min={1} max={89} step={1} set={setIAlpha} color=\"#f59e0b\" />\n              <Slider label=\"β — slope angle\" unit=\"°\" value={iBeta} min={5} max={60} step={1} set={setIBeta} color=\"#ef4444\" />\n              <div className=\"space-y-1\">\n                <span className=\"text-xs text-gray-500\">Launched from</span>\n                <div className=\"flex gap-2\">\n                  {(['base', 'top'] as const).map(v => (\n                    <button key={v} onClick={() => setLaunchFrom(v)}\n                      className={`flex-1 rounded-lg border px-2 py-1.5 text-xs font-medium transition ${\n                        launchFrom === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                      }`}>\n                      {v === 'base' ? 'Base — up' : 'Top — down'}\n                    </button>\n                  ))}\n                </div>\n              </div>\n            </>}\n          </div>\n        </div>\n      )}</div>\n\n      <div data-stage-role=\"extra\"><p className=\"text-center text-[10px] text-gray-400\">\n        Powered by{' '}\n        <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n          A-Factor STEM Studio\n        </a>\n      </p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ProjectileEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ProjectileEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/double-pendulum/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { DoublePendulumCanvas } from '@/components/simulation/DoublePendulumCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { PendulumParams } from '@/lib/physics/doublePendulum';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction DoublePendulumEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [m1, setM1] = useState(() => num(sp, 'm1', 1, 0.1, 3));\n  const [m2, setM2] = useState(() => num(sp, 'm2', 1, 0.1, 3));\n  const [L1, setL1] = useState(() => num(sp, 'L1', 1, 0.3, 2));\n  const [L2, setL2] = useState(() => num(sp, 'L2', 1, 0.3, 2));\n  const [theta1Deg, setTheta1Deg] = useState(() => num(sp, 't1', 90, -180, 180));\n  const [theta2Deg, setTheta2Deg] = useState(() => num(sp, 't2', 90, -180, 180));\n  const [omega1, setOmega1] = useState(() => num(sp, 'w1', 0, -5, 5));\n  const [omega2, setOmega2] = useState(() => num(sp, 'w2', 0, -5, 5));\n  const [damping, setDamping] = useState(() => num(sp, 'damping', 0, 0, 0.5));\n  const [trailLength, setTrailLength] = useState(() => Math.round(num(sp, 'trail', 300, 0, 800)));\n  const [showTrail, setShowTrail] = useState(true);\n  const [showEnergy, setShowEnergy] = useState(true);\n\n  const params: PendulumParams = { m1, m2, L1, L2, g: 9.81, damping };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><DoublePendulumCanvas\n        key={resetKey}\n        theta1Deg={theta1Deg}\n        omega1Init={omega1}\n        theta2Deg={theta2Deg}\n        omega2Init={omega2}\n        params={params}\n        isRunning={isRunning}\n        isPaused={isPaused}\n        showTrail={showTrail}\n        showEnergy={showEnergy}\n        trailLength={trailLength}\n        width={640}\n        height={400}\n      /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Mass m₁\" unit=\"kg\" value={m1} min={0.1} max={3} step={0.1} set={setM1} color=\"#6366f1\" />\n          <Slider label=\"Mass m₂\" unit=\"kg\" value={m2} min={0.1} max={3} step={0.1} set={setM2} color=\"#f59e0b\" />\n          <Slider label=\"Length L₁\" unit=\"m\" value={L1} min={0.3} max={2} step={0.1} set={setL1} color=\"#818cf8\" />\n          <Slider label=\"Length L₂\" unit=\"m\" value={L2} min={0.3} max={2} step={0.1} set={setL2} color=\"#fbbf24\" />\n          <Slider label=\"Angle θ₁\" unit=\"°\" value={theta1Deg} min={-180} max={180} step={1} set={setTheta1Deg} color=\"#a78bfa\" />\n          <Slider label=\"Angle θ₂\" unit=\"°\" value={theta2Deg} min={-180} max={180} step={1} set={setTheta2Deg} color=\"#fcd34d\" />\n          <Slider label=\"Damping\" unit=\"\" value={damping} min={0} max={0.5} step={0.01} set={setDamping} color=\"#ef4444\" />\n          <Slider label=\"Trail\" unit=\"frames\" value={trailLength} min={0} max={800} step={10} set={setTrailLength} color=\"#f43f5e\" />\n          <div className=\"flex gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showTrail} onChange={e => setShowTrail(e.target.checked)} className=\"rounded\" />\n              Show trail\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showEnergy} onChange={e => setShowEnergy(e.target.checked)} className=\"rounded\" />\n              Show energy\n            </label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function DoublePendulumEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <DoublePendulumEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/ac-circuits/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { ACCircuitCanvas, ACMode } from '@/components/simulation/ACCircuitCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\ntype Topic = 'waveform' | 'reactance' | 'series-rlc' | 'parallel-rlc' | 'resonance';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction ACEmbedInner() {\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'reactance' || t === 'series-rlc' || t === 'parallel-rlc' || t === 'resonance' ? t : 'waveform';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [vPeak, setVPeak] = useState(() => num(sp, 'v', 20, 5, 50));\n  const [frequency, setFrequency] = useState(() => num(sp, 'f', 2, 0.5, 5));\n  const [resistance, setResistance] = useState(() => num(sp, 'r', 100, 10, 500));\n  const [component, setComponent] = useState<'inductor' | 'capacitor'>('inductor');\n  const [inductance] = useState(0.5);\n  const [capacitance] = useState(10);\n  const [rlcFrequency, setRlcFrequency] = useState(50);\n  const [parallelResistance, setParallelResistance] = useState(1000);\n  const [resonanceCircuit, setResonanceCircuit] = useState<'series' | 'parallel'>('series');\n\n  const [speedMultiplier, setSpeedMultiplier] = useState(1);\n  const [phasorZoom, setPhasorZoom] = useState(false);\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, vPeak, frequency, resistance, component, inductance, capacitance, rlcFrequency, parallelResistance, resonanceCircuit, reset]);\n\n  const isSeriesTopic = topic === 'series-rlc';\n  const isParallelTopic = topic === 'parallel-rlc';\n  const effFrequency = isSeriesTopic || isParallelTopic ? rlcFrequency : frequency;\n  const activeResistance = isParallelTopic ? parallelResistance : resistance;\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><ACCircuitCanvas key={resetKey} mode={topic as ACMode}\n        vPeak={vPeak} frequency={effFrequency} resistance={activeResistance}\n        component={component} inductance={inductance} capacitance={capacitance * 1e-6}\n        resonanceCircuit={resonanceCircuit} speedMultiplier={speedMultiplier} phasorZoom={phasorZoom}\n        isRunning={isRunning} isPaused={isPaused} width={640} height={320} /></div>\n      <div data-stage-role=\"playback\" className=\"flex items-center gap-2 flex-wrap\">\n        <SimulationControls isRunning={isRunning} isPaused={isPaused}\n          onRun={() => { setIsRunning(true); setIsPaused(false); }}\n          onPause={() => setIsPaused(p => !p)} onReset={reset} />\n        {topic !== 'resonance' && (\n          <button onClick={() => setPhasorZoom(z => !z)}\n            className={`rounded-lg border px-3 py-2 text-xs font-medium transition ${\n              phasorZoom ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-600'\n            }`}>{phasorZoom ? '🔍 Zoomed' : '🔍 Zoom'}</button>\n        )}\n      </div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Animation speed\" unit=\"×\" value={speedMultiplier} min={0.25} max={3} step={0.25} set={setSpeedMultiplier} color=\"#94a3b8\" />\n          <Slider label=\"Peak voltage\" unit=\"V\" value={vPeak} min={5} max={50} step={5} set={setVPeak} color=\"#6366f1\" />\n          {topic === 'waveform' && (\n            <Slider label=\"Resistance\" unit=\"Ω\" value={resistance} min={10} max={500} step={10} set={setResistance} color=\"#8b5cf6\" />\n          )}\n          {topic === 'reactance' && <>\n            <div className=\"flex gap-2\">\n              {(['inductor', 'capacitor'] as const).map(c => (\n                <button key={c} onClick={() => setComponent(c)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                    component === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{c}</button>\n              ))}\n            </div>\n            <Slider label=\"Frequency\" unit=\"Hz\" value={frequency} min={0.5} max={5} step={0.5} set={setFrequency} color=\"#f59e0b\" />\n          </>}\n          {topic === 'series-rlc' && <>\n            <Slider label=\"Frequency\" unit=\"Hz\" value={rlcFrequency} min={10} max={200} step={1} set={setRlcFrequency} color=\"#f59e0b\" />\n            <Slider label=\"Resistance\" unit=\"Ω\" value={resistance} min={10} max={300} step={10} set={setResistance} color=\"#059669\" />\n          </>}\n          {topic === 'parallel-rlc' && <>\n            <Slider label=\"Frequency\" unit=\"Hz\" value={rlcFrequency} min={10} max={200} step={1} set={setRlcFrequency} color=\"#f59e0b\" />\n            <Slider label=\"Resistance\" unit=\"Ω\" value={parallelResistance} min={100} max={3000} step={100} set={setParallelResistance} color=\"#059669\" />\n          </>}\n          {topic === 'resonance' && (\n            <div className=\"flex gap-2\">\n              {(['series', 'parallel'] as const).map(c => (\n                <button key={c} onClick={() => setResonanceCircuit(c)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                    resonanceCircuit === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{c}</button>\n              ))}\n            </div>\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function ACEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <ACEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/equilibrium/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useMemo, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { StaticDynamicCanvas } from '@/components/simulation/StaticDynamicCanvas';\nimport { ConcurrentForcesCanvas } from '@/components/simulation/ConcurrentForcesCanvas';\nimport { ParallelForcesCanvas } from '@/components/simulation/ParallelForcesCanvas';\nimport { FloatingBodyCanvas } from '@/components/simulation/FloatingBodyCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { LIQUIDS, Weight } from '@/lib/physics/equilibrium';\n\ntype Topic = 'static-dynamic' | 'concurrent' | 'parallel' | 'floating';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction EquilibriumEmbedInner() {\n  const sp = useSearchParams();\n  const topic = ((): Topic => {\n    const t = sp.get('topic');\n    return t === 'concurrent' || t === 'parallel' || t === 'floating' ? t : 'static-dynamic';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [scenario, setScenario] = useState<'static' | 'dynamic'>(() => (sp.get('scenario') === 'dynamic' ? 'dynamic' : 'static'));\n  const [sdF1, setSdF1] = useState(() => num(sp, 'f1', 15, 0, 30));\n  const [sdF2, setSdF2] = useState(() => num(sp, 'f2', 15, 0, 30));\n  const [sdMass, setSdMass] = useState(() => num(sp, 'mass', 5, 1, 20));\n\n  const [magA, setMagA] = useState(() => num(sp, 'magA', 10, 1, 20));\n  const [angleA, setAngleA] = useState(() => num(sp, 'angleA', 0, 0, 359));\n  const [magB, setMagB] = useState(() => num(sp, 'magB', 10, 1, 20));\n  const [angleB, setAngleB] = useState(() => num(sp, 'angleB', 90, 0, 359));\n\n  const [w1Force, setW1Force] = useState(() => num(sp, 'w1f', 20, 0, 50));\n  const [w1Pos, setW1Pos] = useState(() => num(sp, 'w1p', -0.3, -0.5, 0.5));\n  const [w2Force, setW2Force] = useState(() => num(sp, 'w2f', 20, 0, 50));\n  const [w2Pos, setW2Pos] = useState(() => num(sp, 'w2p', 0.3, -0.5, 0.5));\n  const weights: Weight[] = useMemo(() => [{ force: w1Force, position: w1Pos }, { force: w2Force, position: w2Pos }], [w1Force, w1Pos, w2Force, w2Pos]);\n\n  const [objDensity, setObjDensity] = useState(() => num(sp, 'density', 600, 100, 12000));\n  const [liqIdx, setLiqIdx] = useState(() => Math.round(num(sp, 'liquid', 0, 0, LIQUIDS.length - 1)));\n  const [blockHeight, setBlockHeight] = useState(() => num(sp, 'h', 0.2, 0.05, 0.4));\n  const liquid = LIQUIDS[liqIdx];\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, scenario, sdF1, sdF2, sdMass, magA, angleA, magB, angleB, w1Force, w1Pos, w2Force, w2Pos, objDensity, liqIdx, blockHeight, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\">{topic === 'static-dynamic' && (\n        <StaticDynamicCanvas key={resetKey} scenario={scenario} f1={sdF1} f2={sdF2} mass={sdMass}\n          isRunning={isRunning} isPaused={isPaused} width={640} height={240} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'concurrent' && (\n        <ConcurrentForcesCanvas key={resetKey} magA={magA} angleA={angleA} magB={magB} angleB={angleB}\n          isRunning={isRunning} isPaused={isPaused} width={640} height={280} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'parallel' && (\n        <ParallelForcesCanvas key={resetKey} weights={weights}\n          isRunning={isRunning} isPaused={isPaused} width={640} height={260} />\n      )}</div>\n      <div data-stage-role=\"canvas\">{topic === 'floating' && (\n        <FloatingBodyCanvas key={resetKey} objDensity={objDensity} liquidDensity={liquid.density}\n          liquidName={liquid.name} blockHeight={blockHeight}\n          isRunning={isRunning} isPaused={isPaused} width={640} height={280} />\n      )}</div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          {topic === 'static-dynamic' && <>\n            <div className=\"flex gap-2\">\n              {(['static', 'dynamic'] as const).map(sc => (\n                <button key={sc} onClick={() => setScenario(sc)}\n                  className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                    scenario === sc ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{sc}</button>\n              ))}\n            </div>\n            <Slider label=\"Force F1\" unit=\"N\" value={sdF1} min={0} max={30} step={0.5} set={setSdF1} color=\"#10b981\" />\n            <Slider label=\"Force F2\" unit=\"N\" value={sdF2} min={0} max={30} step={0.5} set={setSdF2} color=\"#ef4444\" />\n            <Slider label=\"Mass\" unit=\"kg\" value={sdMass} min={1} max={20} step={0.5} set={setSdMass} color=\"#6366f1\" />\n          </>}\n          {topic === 'concurrent' && <>\n            <Slider label=\"Force A\" unit=\"N\" value={magA} min={1} max={20} step={0.5} set={setMagA} color=\"#6366f1\" />\n            <Slider label=\"Angle A\" unit=\"°\" value={angleA} min={0} max={359} step={1} set={setAngleA} color=\"#818cf8\" />\n            <Slider label=\"Force B\" unit=\"N\" value={magB} min={1} max={20} step={0.5} set={setMagB} color=\"#10b981\" />\n            <Slider label=\"Angle B\" unit=\"°\" value={angleB} min={0} max={359} step={1} set={setAngleB} color=\"#34d399\" />\n          </>}\n          {topic === 'parallel' && <>\n            <Slider label=\"Weight 1\" unit=\"N\" value={w1Force} min={0} max={50} step={1} set={setW1Force} color=\"#6366f1\" />\n            <Slider label=\"Weight 1 ruler mark\" unit=\"cm\" value={Math.round((w1Pos + 0.5) * 100)} min={0} max={100} step={1} set={v => setW1Pos(v / 100 - 0.5)} color=\"#6366f1\" />\n            <Slider label=\"Weight 2\" unit=\"N\" value={w2Force} min={0} max={50} step={1} set={setW2Force} color=\"#10b981\" />\n            <Slider label=\"Weight 2 ruler mark\" unit=\"cm\" value={Math.round((w2Pos + 0.5) * 100)} min={0} max={100} step={1} set={v => setW2Pos(v / 100 - 0.5)} color=\"#6366f1\" />\n          </>}\n          {topic === 'floating' && <>\n            <div className=\"flex flex-wrap gap-1.5\">\n              {LIQUIDS.map((l, i) => (\n                <button key={l.name} onClick={() => setLiqIdx(i)}\n                  className={`rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n                    liqIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                  }`}>{l.name}</button>\n              ))}\n            </div>\n            <Slider label=\"Object density\" unit=\"kg/m³\" value={objDensity} min={100} max={12000} step={50} set={setObjDensity} color=\"#a78bfa\" />\n            <Slider label=\"Block height\" unit=\"m\" value={blockHeight} min={0.05} max={0.4} step={0.01} set={setBlockHeight} color=\"#f59e0b\" />\n          </>}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function EquilibriumEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <EquilibriumEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/band-theory/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useRef, useState, useCallback } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { BandTheoryCanvas } from '@/components/simulation/BandTheoryCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { BandTheoryParams, DopingType, MATERIALS } from '@/lib/physics/bandTheory';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction bool(sp: URLSearchParams, key: string, fallback: boolean) {\n  const v = sp.get(key);\n  return v !== null ? v === '1' : fallback;\n}\n\nfunction str<T extends string>(sp: URLSearchParams, key: string, fallback: T, allowed: T[]): T {\n  const v = sp.get(key) as T | null;\n  return v && allowed.includes(v) ? v : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">\n          {value} <span className=\"font-normal text-gray-400\">{unit}</span>\n        </span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction BandTheoryEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n\n  const [material, setMaterial] = useState(() => str(sp, 'mat', 'silicon', Object.keys(MATERIALS)));\n  const [temperature, setTemperature] = useState(() => num(sp, 'T', 300, 0, 1000));\n  const [dopingType, setDopingType] = useState<DopingType>(() => str(sp, 'dopant', 'intrinsic', ['intrinsic', 'n-type', 'p-type'] as DopingType[]));\n  const [dopingConcentration, setDopingConcentration] = useState(() => num(sp, 'conc', 10, 10, 20));\n  const [speed, setSpeed] = useState(() => num(sp, 'speed', 1, 0, 3));\n  const [showElectrons, setShowElectrons] = useState(() => bool(sp, 'e', true));\n  const [showHoles, setShowHoles] = useState(() => bool(sp, 'h', true));\n  const [showFermiLevel, setShowFermiLevel] = useState(() => bool(sp, 'ef', true));\n  const [showBandGap, setShowBandGap] = useState(() => bool(sp, 'eg', true));\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 540, 1600, 420);\n  const params: BandTheoryParams = {\n    material, temperature, dopingType, dopingConcentration,\n    speed, zoom: 1, showElectrons, showHoles, showFermiLevel,\n    showBandGap, showThermalEnergy: false, showDOS: true, animateCarriers: true,\n  };\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey((k) => k + 1); }, []);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"parameters\" className=\"flex gap-1 overflow-x-auto pb-1\">\n        {Object.entries(MATERIALS).map(([key, m]) => (\n          <button key={key} onClick={() => { setMaterial(key); setIsRunning(false); setResetKey((k) => k + 1); }}\n            className={`shrink-0 rounded-lg border px-3 py-1.5 text-xs font-medium transition ${material === key ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'}`}>\n            {m.symbol}\n          </button>\n        ))}\n      </div>\n\n      <div data-stage-role=\"canvas\" ref={canvasBoxRef}><BandTheoryCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} width={canvasSize.width} height={canvasSize.height} /></div>\n      <div data-stage-role=\"extra\"><p className=\"text-xs leading-6 text-gray-700\">Filled dots are electrons; hollow markers are unoccupied states. The row illustrates an electron filling a hole: the vacancy shifts the other way. Counts are amplified; low-temperature freeze-out and degenerate doping are outside this teaching approximation.</p></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused((p) => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <Slider label=\"Temperature\" unit=\"K\" value={temperature} min={0} max={1000} step={10} set={setTemperature} color=\"#f43f5e\" />\n          <Slider label=\"Doping\" unit=\"log₁₀(cm⁻³)\" value={dopingConcentration} min={10} max={20} step={0.5} set={setDopingConcentration} color=\"#8b5cf6\" />\n          <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n          <div className=\"flex flex-wrap gap-3\">\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showElectrons} onChange={(e) => setShowElectrons(e.target.checked)} className=\"rounded\" />Electrons\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showHoles} onChange={(e) => setShowHoles(e.target.checked)} className=\"rounded\" />Holes\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showFermiLevel} onChange={(e) => setShowFermiLevel(e.target.checked)} className=\"rounded\" />Fermi level\n            </label>\n            <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n              <input type=\"checkbox\" checked={showBandGap} onChange={(e) => setShowBandGap(e.target.checked)} className=\"rounded\" />Band gap\n            </label>\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function BandTheoryEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <BandTheoryEmbedInner />\n    </Suspense>\n  );\n}", "src/app/embed/mosfet/page.tsx": "// src/app/embed/mosfet/page.tsx\n'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\n\nimport React, { useState } from 'react';\nimport { MosfetCanvas } from '@/components/simulation/MosfetCanvas';\nimport { MosfetParams, getPreset, PRESET_NAMES, PRESET_LABELS } from '@/lib/physics/mosfet';\n\nexport default function MosfetEmbedPage() {\n  const [params, setParams] = useState<MosfetParams>(getPreset('cutoff'));\n  const [activePreset, setActivePreset] = useState('cutoff');\n\n  const applyPreset = (name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  };\n\n  return (\n    <div className=\"min-h-screen bg-slate-950 text-slate-100 p-4\">\n      <SimulationStage className=\"af-stage-dark max-w-5xl mx-auto\">\n        <div data-stage-role=\"canvas\"><MosfetCanvas\n          params={params}\n          activeTab=\"schematic\"\n          isRunning={true}\n          isPaused={false}\n          showElectrons={true}\n        /></div>\n\n        <div data-stage-role=\"parameters\" className=\"mt-4 flex flex-wrap gap-2\">\n          {PRESET_NAMES.map(name => (\n            <button\n              key={name}\n              onClick={() => applyPreset(name)}\n              className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${\n                activePreset === name\n                  ? 'bg-blue-600 text-white'\n                  : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n              }`}\n            >\n              {PRESET_LABELS[name]}\n            </button>\n          ))}\n\n        </div>\n      </SimulationStage>\n    </div>\n  );\n}\n", "src/app/embed/debroglie/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { DeBroglieCanvas } from '@/components/simulation/DeBroglieCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { PARTICLES } from '@/lib/physics/debroglie';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction DeBroglieEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n  const [pIdx, setPIdx] = useState(() => Math.round(num(sp, 'p', 0, 0, PARTICLES.length - 1)));\n  const particle = PARTICLES[pIdx];\n  const [velocity, setVelocity] = useState(() => num(sp, 'v', particle.vDefault, particle.vMin, particle.vMax));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [pIdx, velocity, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><DeBroglieCanvas mass={particle.mass} velocity={velocity} particleName={particle.name}\n        isRunning={isRunning} isPaused={isPaused} width={640} height={280} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"flex flex-wrap gap-1.5\">\n            {PARTICLES.map((p, i) => (\n              <button key={p.name} onClick={() => { setPIdx(i); setVelocity(p.vDefault); }}\n                className={`rounded-full border px-2.5 py-1 text-[11px] font-medium transition ${\n                  pIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                }`}>{p.emoji} {p.name}</button>\n            ))}\n          </div>\n          <Slider label=\"Speed\" unit=\"m/s\" value={velocity} min={particle.vMin} max={particle.vMax}\n            step={(particle.vMax - particle.vMin) / 200} set={setVelocity} color=\"#6366f1\" />\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function DeBroglieEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <DeBroglieEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/pn-junction/page.tsx": "// src/app/embed/pn-junction/page.tsx\n'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\n\nimport React, { useState } from 'react';\nimport PnJunctionCanvas from '@/components/simulation/PnJunctionCanvas';\nimport { MaterialParams, getPreset, PRESET_NAMES, PRESET_LABELS } from '@/lib/physics/pnJunction';\n\nexport default function PnJunctionEmbedPage() {\n  const [params, setParams] = useState<MaterialParams>(getPreset('equilibrium'));\n  const [activePreset, setActivePreset] = useState('equilibrium');\n\n  const applyPreset = (name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  };\n\n  return (\n    <div className=\"min-h-screen bg-slate-950 text-slate-100 p-4\">\n      <SimulationStage className=\"af-stage-dark max-w-5xl mx-auto\">\n        <div data-stage-role=\"canvas\"><PnJunctionCanvas params={params} width={800} height={480} /></div>\n\n        <div data-stage-role=\"parameters\" className=\"mt-4 flex flex-wrap gap-2\">\n          {PRESET_NAMES.map(name => (\n            <button\n              key={name}\n              onClick={() => applyPreset(name)}\n              className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${\n                activePreset === name\n                  ? 'bg-blue-600 text-white'\n                  : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n              }`}\n            >\n              {PRESET_LABELS[name]}\n            </button>\n          ))}\n        </div>\n      </SimulationStage>\n    </div>\n  );\n}", "src/app/embed/space/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useRef, useState } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { SpaceCanvas } from '@/components/simulation/SpaceCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { type Dim, type P3, type View, DEFAULT_VIEW, LABELS, P, RANGE, analyseJourney, clampDim, clampTo, coordText, fmt, len } from '@/lib/physics/space';\n\n// Parses \"x,y,z;x,y,z\" and clamps every value so a hand-edited URL can't break the simulation.\nfunction parsePoints(raw: string | null, dim: Dim): P3[] {\n  const r = RANGE[dim];\n  const pts = (raw ?? '').split(';').slice(0, 5).map(t => { const [x, y, z] = t.split(',').map(Number); return clampDim(P(clampTo(Number.isFinite(x) ? x : 0, r), clampTo(Number.isFinite(y) ? y : 0, r), clampTo(Number.isFinite(z) ? z : 0, r)), dim); });\n  return pts.length ? pts : [P(3, 2, 4)].map(p => clampDim(p, dim));\n}\n\nfunction SpaceEmbedInner() {\n  const sp = useSearchParams();\n  const dim: Dim = sp.get('dim') === '1d' ? '1d' : sp.get('dim') === '2d' ? '2d' : '3d';\n  const act = sp.get('act') === 'journey' ? 'journey' : 'locate';\n  const [pts, setPts] = useState<P3[]>(() => { const p = parsePoints(sp.get('pts'), dim); return act === 'journey' && p.length < 2 ? [P(0, 0, 0), ...p] : p; });\n  const [view, setView] = useState<View>(DEFAULT_VIEW);\n  const [sel, setSel] = useState(0);\n  const J = analyseJourney(pts, dim);\n  const boxRef = useRef<HTMLDivElement>(null);\n  const size = useResponsiveCanvasSize(boxRef, 640, dim === '3d' ? 420 : 380, 900);\n  const width = size.width, height = width < 560 ? Math.round(width * (dim === '1d' ? 0.62 : 1.0)) : size.height;\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-3xl p-3\">\n      <div data-stage-role=\"canvas\" ref={boxRef} className=\"overflow-hidden rounded-xl border border-gray-200 p-1\">\n        <SpaceCanvas dim={dim} activity={act} width={width} height={height} points={act === 'journey' ? pts : [pts[0]]} labels={act === 'journey' ? LABELS : ['P']}\n          selected={sel} onMove={(i, p) => setPts(s => s.map((q, k) => (k === i ? p : q)))} onSelect={setSel} snap={1} view={view} onView={setView} dragAxis=\"floor\"\n          showPlanes showGrid showGuides showComponents />\n      </div>\n      <div data-stage-role=\"extra\" className=\"mt-2 grid gap-2 text-xs sm:grid-cols-2\">\n        {act === 'locate' ? (\n          <>\n            <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">Position </span><span className=\"font-semibold text-red-600\">{coordText(pts[0], dim)}</span></div>\n            <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">Distance from O </span><span className=\"font-semibold text-indigo-600\">{fmt(len(pts[0]))}</span></div>\n          </>\n        ) : (\n          <>\n            <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">Distance </span><span className=\"font-semibold text-indigo-600\">{fmt(J.distance)}</span></div>\n            <div className=\"rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-gray-500\">|Displacement| </span><span className=\"font-semibold text-rose-600\">{fmt(J.magnitude)}</span></div>\n          </>\n        )}\n      </div>\n      <div data-stage-role=\"extra\"><p className=\"mt-1.5 text-[10px] text-gray-400\">{dim === '3d' ? 'Drag empty space to rotate. ' : ''}Drag a point to move it. A-Factor STEM Studio</p></div>\n    </SimulationStage>\n  );\n}\n\nexport default function SpaceEmbedPage() {\n  return <Suspense fallback={<div className=\"p-6 text-sm text-gray-400\">Loading…</div>}><SpaceEmbedInner /></Suspense>;\n}\n", "src/app/embed/waves/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { WaveCanvas, WaveMode } from '@/components/simulation/WaveCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction WavesEmbedInner() {\n  const sp = useSearchParams();\n  const mode = ((): WaveMode => {\n    const m = sp.get('mode');\n    return m === 'longitudinal' || m === 'superposition' || m === 'standing' ? m : 'transverse';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [A, setA] = useState(() => num(sp, 'A', 1, 0.2, 1.5));\n  const [f, setF] = useState(() => num(sp, 'f', 0.5, 0.1, 2));\n  const [lambda, setLambda] = useState(() => num(sp, 'lambda', 2, 0.5, 4));\n  const [A2, setA2] = useState(() => num(sp, 'A2', 0.7, 0.1, 1.5));\n  const [f2, setF2] = useState(() => num(sp, 'f2', 0.5, 0.1, 2));\n  const [phase2, setPhase2] = useState(() => num(sp, 'phase2', 0, 0, 360));\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [A, f, lambda, A2, f2, phase2, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><WaveCanvas key={resetKey} mode={mode}\n        amplitude={A} frequency={f} wavelength={lambda}\n        amplitude2={A2} frequency2={f2} phase2={phase2}\n        isRunning={isRunning} isPaused={isPaused} width={660} height={300} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n          <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2\">\n            <Slider label=\"Amplitude\" unit=\"m\" value={A} min={0.2} max={1.5} step={0.1} set={setA} color=\"#6366f1\" />\n            <Slider label=\"Frequency\" unit=\"Hz\" value={f} min={0.1} max={2} step={0.05} set={setF} color=\"#f59e0b\" />\n            <Slider label=\"Wavelength\" unit=\"m\" value={lambda} min={0.5} max={4} step={0.1} set={setLambda} color=\"#10b981\" />\n            {mode === 'superposition' && <>\n              <Slider label=\"Amplitude A₂\" unit=\"m\" value={A2} min={0.1} max={1.5} step={0.1} set={setA2} color=\"#8b5cf6\" />\n              <Slider label=\"Frequency f₂\" unit=\"Hz\" value={f2} min={0.1} max={2} step={0.05} set={setF2} color=\"#ef4444\" />\n              <Slider label=\"Phase difference\" unit=\"°\" value={phase2} min={0} max={360} step={5} set={setPhase2} color=\"#0ea5e9\" />\n            </>}\n          </div>\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function WavesEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <WavesEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/circuits/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { CircuitCanvas, CircuitMode, FlowDisplay } from '@/components/simulation/CircuitCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { NonOhmicDevice } from '@/lib/physics/circuits';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction CircuitsEmbedInner() {\n  const sp = useSearchParams();\n  const mode = ((): CircuitMode => {\n    const m = sp.get('mode');\n    return m === 'series' || m === 'parallel' || m === 'non-ohmic' ? m : 'ohm';\n  })();\n  const showControls = sp.get('controls') !== '0';\n\n  const [V, setV] = useState(() => num(sp, 'V', 12, 1, 24));\n  const [r1, setR1] = useState(() => num(sp, 'r1', 4, 1, 50));\n  const [r2, setR2] = useState(() => num(sp, 'r2', 6, 1, 50));\n  const [r3, setR3] = useState(() => num(sp, 'r3', 12, 1, 50));\n  const [nonOhmicDevice, setNonOhmicDevice] = useState<NonOhmicDevice>('filament');\n  const [flowDisplay, setFlowDisplay] = useState<FlowDisplay>('electron');\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [V, r1, r2, r3, nonOhmicDevice, flowDisplay, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><CircuitCanvas key={resetKey} mode={mode} voltage={V} r1={r1} r2={r2} r3={r3}\n        nonOhmicDevice={nonOhmicDevice} flowDisplay={flowDisplay}\n        isRunning={isRunning} isPaused={isPaused} width={640} height={300} /></div>\n      <div data-stage-role=\"playback\" className=\"flex items-center gap-2 flex-wrap\">\n        <SimulationControls isRunning={isRunning} isPaused={isPaused}\n          onRun={() => { setIsRunning(true); setIsPaused(false); }}\n          onPause={() => setIsPaused(p => !p)} onReset={reset} />\n        <div className=\"flex rounded-lg border border-gray-200 overflow-hidden\">\n          {(['electron', 'conventional'] as const).map(f => (\n            <button key={f} onClick={() => setFlowDisplay(f)}\n              className={`px-2 py-2 text-xs font-medium transition ${\n                flowDisplay === f ? 'bg-indigo-50 text-indigo-700' : 'bg-white text-gray-500'\n              }`}>{f === 'electron' ? '● Electron' : '▶ Conventional'}</button>\n          ))}\n        </div>\n      </div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n          <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2\">\n            <Slider label=\"Supply voltage\" unit=\"V\" value={V} min={1} max={24} step={0.5} set={setV} color=\"#6366f1\" />\n            {mode !== 'non-ohmic' && (\n              <Slider label={mode === 'ohm' ? 'Resistance R' : 'R₁'} unit=\"Ω\" value={r1} min={1} max={50} step={1} set={setR1} color=\"#f59e0b\" />\n            )}\n            {mode === 'non-ohmic' && (\n              <Slider label=\"Reference R\" unit=\"Ω\" value={r1} min={1} max={50} step={1} set={setR1} color=\"#f59e0b\" />\n            )}\n            {(mode === 'series' || mode === 'parallel') && <>\n              <Slider label=\"R₂\" unit=\"Ω\" value={r2} min={1} max={50} step={1} set={setR2} color=\"#10b981\" />\n              <Slider label=\"R₃\" unit=\"Ω\" value={r3} min={1} max={50} step={1} set={setR3} color=\"#8b5cf6\" />\n            </>}\n          </div>\n          {mode === 'non-ohmic' && (\n            <div className=\"flex gap-1 mt-3\">\n              {(['filament', 'thermistor', 'diode'] as const).map(d => (\n                <button key={d} onClick={() => setNonOhmicDevice(d)}\n                  className={`px-2 py-1 rounded-md text-[10px] font-medium capitalize transition ${\n                    nonOhmicDevice === d ? 'bg-indigo-100 text-indigo-700' : 'bg-gray-100 text-gray-500'\n                  }`}>{d}</button>\n              ))}\n            </div>\n          )}\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function CircuitsEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <CircuitsEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/embed/photoelectric/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { Suspense, useState, useCallback, useEffect, useRef } from 'react';\nimport { useSearchParams } from 'next/navigation';\nimport { PhotoelectricCanvas } from '@/components/simulation/PhotoelectricCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { METALS } from '@/lib/physics/photoelectric';\n\nfunction num(sp: URLSearchParams, key: string, fallback: number, min: number, max: number) {\n  const v = Number(sp.get(key));\n  return Number.isFinite(v) && sp.get(key) !== null ? Math.min(max, Math.max(min, v)) : fallback;\n}\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"font-normal text-gray-400\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction PoweredBy() {\n  return (\n    <p className=\"text-center text-[10px] text-gray-400\">\n      Powered by{' '}\n      <a href=\"/\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"font-medium text-indigo-500 hover:text-indigo-600\">\n        A-Factor STEM Studio\n      </a>\n    </p>\n  );\n}\n\nfunction PhotoelectricEmbedInner() {\n  const sp = useSearchParams();\n  const showControls = sp.get('controls') !== '0';\n  const [metalIdx, setMetalIdx] = useState(() => Math.round(num(sp, 'metal', 0, 0, METALS.length - 1)));\n  const [f14, setF14] = useState(() => num(sp, 'f', 6, 2, 14));\n  const [intensity, setIntensity] = useState(() => num(sp, 'i', 5, 1, 10));\n  const metal = METALS[metalIdx];\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [metalIdx, f14, intensity, reset]);\n\n  return (\n    <SimulationStage className=\"mx-auto max-w-2xl space-y-3 p-3 sm:p-4\">\n      <div data-stage-role=\"canvas\"><PhotoelectricCanvas f14={f14} intensity={intensity} phiEV={metal.phi} metalName={metal.name}\n        isRunning={isRunning} isPaused={isPaused} width={640} height={300} /></div>\n      <div data-stage-role=\"playback\"><SimulationControls isRunning={isRunning} isPaused={isPaused}\n        onRun={() => { setIsRunning(true); setIsPaused(false); }}\n        onPause={() => setIsPaused(p => !p)} onReset={reset} /></div>\n      <div data-stage-role=\"parameters\">{showControls && (\n        <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-3\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n          <div className=\"flex flex-wrap gap-1.5\">\n            {METALS.map((m, i) => (\n              <button key={m.name} onClick={() => setMetalIdx(i)}\n                className={`rounded-full border px-2.5 py-1 text-[11px] font-medium transition ${\n                  metalIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                }`}>{m.name}</button>\n            ))}\n          </div>\n          <Slider label=\"Frequency\" unit=\"×10¹⁴ Hz\" value={f14} min={2} max={14} step={0.1} set={setF14} color=\"#6366f1\" />\n          <Slider label=\"Intensity\" unit=\"\" value={intensity} min={1} max={10} step={1} set={setIntensity} color=\"#f59e0b\" />\n        </div>\n      )}</div>\n      <div data-stage-role=\"extra\"><PoweredBy /></div>\n    </SimulationStage>\n  );\n}\n\nexport default function PhotoelectricEmbedPage() {\n  return (\n    <Suspense fallback={<div className=\"p-8 text-center text-xs text-gray-400\">Loading simulation…</div>}>\n      <PhotoelectricEmbedInner />\n    </Suspense>\n  );\n}\n", "src/app/minitab/div-stokes/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { DivStokesCanvas } from '@/components/simulation/DivStokesCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { FIELDS, boundaryIntegrals, areaIntegrals } from '@/lib/physics/divStokes';\n\nconst TEACHER_NOTES = [\n  \"Chapter 3's divergence theorem and Chapter 4's Stokes'/Green's theorem both say the same kind of thing: a boundary measurement equals an interior sum.\",\n  'Flux (F·n̂ around the edge) always equals ∬(∇·F)dA (divergence summed over the disk) — move or resize the disk and both numbers stay locked together.',\n  'Circulation (F·dl around the edge) always equals ∬(∇×F)_z dA (curl summed over the disk) — same guarantee, independently verified here by direct numerical integration.',\n  'Try the \"Rotation\" field: circulation is large and flux is exactly zero — a pure rotation has no divergence anywhere.',\n  'Try the \"Source\" field: flux is large and circulation is exactly zero — pure radial outflow has no curl anywhere.',\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'For F=(x,y), find ∇·F.', a: '∇·F=∂x/∂x+∂y/∂y=1+1=2 (constant everywhere — matches the \"Source\" field always showing the same flux-per-area).' },\n  { q: 'For F=(−y,x), find ∇×F (the z-component).', a: '(∇×F)_z=∂x/∂x−∂(−y)/∂y=1−(−1)=2 (constant — matches \"Rotation\" always showing the same circulation-per-area).' },\n  { q: \"Explain why the disk's flux and ∬∇·F dA must always agree, using the 'tiling with tiny boxes' argument.\", a: 'Tiling the disk with a fine grid, each tiny box contributes flux (∇·F)×(its area); at every shared internal edge, outflow from one box exactly equals inflow to its neighbour, so those contributions cancel. Only the outer boundary survives — which is exactly the flux integral.' },\n  { q: 'For the \"Mixed\" field F=(x−y,x+y), find both ∇·F and (∇×F)_z.', a: '∇·F=1+1=2. (∇×F)_z=1−(−1)=2. Both are nonzero and equal here, matching what the live readout shows for this preset.' },\n  { q: 'Why does moving the disk to a different location not change the flux or circulation for the fields shown here?', a: 'All five preset fields have divergence and curl that are either constant or depend simply on position in a way that, combined with symmetric disk placement, gives the same total when integrated over any disk of the same radius — try it and check against the readout.' },\n];\n\nexport default function DivStokesPage() {\n  const [fieldIndex, setFieldIndex] = useState(0);\n  const [disk, setDisk] = useState({ cx: 0.5, cy: 0.3, r: 1.1 });\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 480, 480, 520);\n\n  const field = FIELDS[fieldIndex];\n  const { circulation, flux } = boundaryIntegrals(field, disk.cx, disk.cy, disk.r);\n  const { divIntegral, curlIntegral } = areaIntegrals(field, disk.cx, disk.cy, disk.r);\n\n  useTopicPreset(\"minitab-div-stokes\", { \"disk.r\": (value: number) => setDisk(current => ({ ...current, r: value })) }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapters 3–4</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Divergence &amp; Stokes&apos; Theorem Visualizer</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap gap-1.5\">\n            {FIELDS.map((f, i) => (\n              <button key={f.name} onClick={() => setFieldIndex(i)}\n                className={`text-xs px-3 py-2 rounded-lg border font-medium transition ${\n                  fieldIndex === i ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'\n                }`}>{f.name}</button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm flex justify-center\">\n                <DivStokesCanvas fieldIndex={fieldIndex} disk={disk} onDiskChange={setDisk} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n              <div data-stage-role=\"parameters\" className=\"flex items-center gap-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <span className=\"text-xs text-gray-500 shrink-0\">Disk radius r</span>\n                <input type=\"range\" min={0.4} max={2.2} step={0.05} value={disk.r}\n                  onChange={e => setDisk(d => ({ ...d, r: Number(e.target.value) }))}\n                  className=\"flex-1\" style={{ accentColor: '#2563eb' }} />\n                <span className=\"text-xs font-mono text-gray-500 w-14 text-right\">{disk.r.toFixed(2)}</span>\n              </div>\n              <div data-stage-role=\"extra\"><p className=\"text-[11px] text-gray-400 px-1\">Drag the disk directly on the canvas to move it.</p></div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                {[\n                  { l: 'Flux ∮F·n̂dl', v: flux.toFixed(3), c: 'text-blue-600' },\n                  { l: '∬(∇·F)dA', v: divIntegral.toFixed(3), c: 'text-blue-600' },\n                  { l: 'Circulation ∮F·dl', v: circulation.toFixed(3), c: 'text-emerald-600' },\n                  { l: '∬(∇×F)_z dA', v: curlIntegral.toFixed(3), c: 'text-emerald-600' },\n                ].map(r => (\n                  <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">{r.l}</span>\n                    <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                  </div>\n                ))}\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/minitab/fourier-transform/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { FourierTransformGraph } from '@/components/simulation/FourierTransformGraph';\nimport { PAIRS } from '@/lib/physics/fourierTransform';\n\nconst TEACHER_NOTES = [\n  \"Chapter 13 derives the shift, scaling, and derivative theorems algebraically — this shows what the scaling theorem actually looks like. Narrow f(x) and F(k) visibly spreads out; widen f(x) and F(k) narrows to a spike.\",\n  'You can never shrink both f(x) and F(k) at once — Δx·Δk stays roughly constant, the same mathematical statement behind Heisenberg\\u2019s uncertainty principle, since quantum mechanics represents momentum-space wavefunctions as the Fourier transform of position-space ones.',\n  'The rectangular pulse transforms to a sinc function — notice the oscillating \"ringing\" in F(k), a direct consequence of the sharp edges in f(x).',\n  'The Gaussian is the one function whose transform has exactly the same shape as itself — this special property is why Gaussian wave packets are the natural building block in quantum mechanics.',\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'For a rectangular pulse of half-width a=2, find F(0).', a: 'F(0)=2a=4 (the limit of 2sin(ka)/k as k→0).' },\n  { q: 'For a Gaussian with a=1, find F(0).', a: 'F(0)=a√(2π)=√(2π)≈2.507.' },\n  { q: 'For a decaying exponential with a=1, find F(0).', a: 'F(0)=2a/(1+0)=2a=2.' },\n  { q: 'Explain, using the widget, what happens to F(k) as the width parameter a of a Gaussian increases.', a: 'As a increases (f(x) gets wider), F(k) gets narrower — this is the scaling/uncertainty trade-off: F(k)=a√(2π)e^(−a²k²/2) has its width controlled by 1/a, inversely to f(x)\\u2019s width, which is controlled by a.' },\n  { q: 'Why does the rectangular pulse\\u2019s transform oscillate (the sinc function) while the Gaussian\\u2019s does not?', a: 'The rectangular pulse has sharp, discontinuous edges, which require high-frequency components to reproduce — these high frequencies interfere constructively and destructively as k varies, producing the sinc oscillation. The Gaussian is infinitely smooth with no sharp features, so its transform decays smoothly with no oscillation.' },\n];\n\nexport default function FourierTransformPage() {\n  const [pairIndex, setPairIndex] = useState(0);\n  const [a, setA] = useState(1);\n\n  const pair = PAIRS[pairIndex];\n\n  useTopicPreset(\"minitab-fourier-transform\", { \"a\": setA }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapter 13</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Fourier Transform Pairs</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap gap-1.5\">\n            {PAIRS.map((p, i) => (\n              <button key={p.name} onClick={() => setPairIndex(i)}\n                className={`text-xs px-3 py-2 rounded-lg border font-medium transition ${\n                  pairIndex === i ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'\n                }`}>{p.name}</button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <FourierTransformGraph pair={pair} a={a} />\n              </div>\n              <div data-stage-role=\"parameters\" className=\"flex items-center gap-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <span className=\"text-xs text-gray-500 shrink-0\">Width a</span>\n                <input type=\"range\" min={0.2} max={3} step={0.01} value={a}\n                  onChange={e => setA(Number(e.target.value))} className=\"flex-1\" style={{ accentColor: '#2563eb' }} />\n                <span className=\"text-xs font-mono text-gray-500 w-14 text-right\">{a.toFixed(2)}</span>\n              </div>\n              <div data-stage-role=\"extra\"><p className=\"text-[11px] font-mono text-gray-400 px-1\">{pair.formula}</p></div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                  <span className=\"text-xs text-gray-500\">Width parameter a</span>\n                  <span className=\"text-xs font-semibold tabular-nums text-gray-700\">{a.toFixed(2)}</span>\n                </div>\n                <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                  <span className=\"text-xs text-gray-500\">f(0)</span>\n                  <span className=\"text-xs font-semibold tabular-nums text-blue-600\">{pair.f(0.0001, a).toFixed(3)}</span>\n                </div>\n                <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                  <span className=\"text-xs text-gray-500\">F(0) = ∫f(x)dx</span>\n                  <span className=\"text-xs font-semibold tabular-nums text-emerald-600\">{pair.F(0.0001, a).toFixed(3)}</span>\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((note, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{note}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/minitab/eigenvector-explorer/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useRef, useEffect, useCallback } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { EigenvectorCanvas } from '@/components/simulation/EigenvectorCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { PRESETS, eigen, type Matrix2x2 } from '@/lib/physics/eigen';\n\nconst TEACHER_NOTES = [\n  'An eigenvector v satisfies Av=λv — A doesn\\u2019t change its direction, only stretches or shrinks it by λ. Every other direction gets rotated as well as scaled.',\n  'For the symmetric preset, watch the gold and purple eigenvector lines stay exactly perpendicular throughout the animation — this is the orthogonality result Chapter 6 proves for real symmetric matrices.',\n  'For the pure rotation preset, there are NO real eigenvectors — every direction genuinely turns, which is exactly what \"no fixed direction\" means for a rotation.',\n  'Vibrations and normal modes, quantum energy eigenstates (Hψ=Eψ), principal stresses in engineering, and stability of dynamical systems are all literally this same equation, Av=λv, applied to a physical operator instead of a 2×2 matrix.',\n  'Diagonalization (P⁻¹AP=D) is why this matters computationally: once you know the eigenvectors, Aⁿ becomes trivial — PDⁿP⁻¹ instead of n matrix multiplications.',\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'Find the eigenvalues of A=[3,0;0,5].', a: 'Diagonal matrix — eigenvalues are just the diagonal entries: λ=3, λ=5.' },\n  { q: 'Find the eigenvalues of A=[4,1;2,3] (characteristic equation).', a: 'det(A−λI)=(4−λ)(3−λ)−2=λ²−7λ+10=(λ−5)(λ−2)=0 → λ=5, λ=2.' },\n  { q: 'For A=[2,1;1,2] (symmetric), verify the eigenvectors (1,1) and (1,−1) are orthogonal.', a: '(1,1)·(1,−1)=1−1=0 — orthogonal, as guaranteed for a symmetric matrix.' },\n  { q: 'For A=[4,1;2,3], verify trace and determinant match the sum/product of eigenvalues (λ=5,2).', a: 'trace=4+3=7=5+2 ✓. det=4×3−1×2=10=5×2 ✓.' },\n  { q: 'Why does a pure rotation matrix have no real eigenvectors?', a: 'A rotation changes the direction of every single vector in the plane (except for the trivial zero vector) — there is no nonzero direction it leaves unchanged, which is exactly what having a real eigenvector would require.' },\n];\n\nexport default function EigenvectorExplorerPage() {\n  const [presetIndex, setPresetIndex] = useState(1);\n  const [matrix, setMatrix] = useState<Matrix2x2>(PRESETS[1].m);\n  const [t, setT] = useState(1);\n  const [animating, setAnimating] = useState(false);\n  const animRef = useRef<number>(0);\n  const startRef = useRef<number>(0);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 460, 460, 500);\n\n  const applyPreset = (i: number) => { setPresetIndex(i); setMatrix(PRESETS[i].m); };\n  const updateField = (key: keyof Matrix2x2) => (v: number) => {\n    setPresetIndex(-1);\n    setMatrix(prev => ({ ...prev, [key]: v }));\n  };\n\n  const toggleAnimate = useCallback(() => {\n    if (animating) { cancelAnimationFrame(animRef.current); setAnimating(false); return; }\n    setAnimating(true);\n    startRef.current = performance.now();\n    const step = (now: number) => {\n      const elapsed = (now - startRef.current) / 1400;\n      const phase = elapsed % 2;\n      setT(phase <= 1 ? phase : 2 - phase);\n      animRef.current = requestAnimationFrame(step);\n    };\n    animRef.current = requestAnimationFrame(step);\n  }, [animating]);\n\n  useEffect(() => () => cancelAnimationFrame(animRef.current), []);\n\n  const eig = eigen(matrix);\n\n  useTopicPreset(\"minitab-eigenvector-explorer\", { \"t\": setT }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapter 6</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Eigenvector Explorer</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm flex justify-center\">\n                <EigenvectorCanvas matrix={matrix} t={t} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n              <div data-stage-role=\"parameters\" className=\"flex items-center gap-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <input type=\"range\" min={0} max={1} step={0.01} value={t}\n                  onChange={e => setT(Number(e.target.value))} className=\"flex-1\" style={{ accentColor: '#10b981' }} />\n                <span className=\"text-xs font-mono text-gray-500 w-16 text-right\">t={t.toFixed(2)}</span>\n                <button onClick={toggleAnimate}\n                  className=\"text-xs px-3 py-2 rounded-lg border border-gray-200 bg-white font-medium text-gray-600 hover:border-emerald-300 transition\">\n                  {animating ? '⏸ Stop' : '▶ Animate'}\n                </button>\n              </div>\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-100 bg-white p-4 grid grid-cols-2 gap-2\">\n                {(['a', 'b', 'c', 'd'] as const).map(k => (\n                  <div key={k} className=\"space-y-1\">\n                    <span className=\"text-xs text-gray-400\">{k}</span>\n                    <input type=\"number\" step={0.1} value={matrix[k]}\n                      onChange={e => updateField(k)(Number(e.target.value))}\n                      className=\"w-full rounded-lg border border-gray-300 bg-white px-2 py-1.5 text-sm font-mono text-gray-900\" />\n                  </div>\n                ))}\n              </div>\n              <div data-stage-role=\"parameters\" className=\"flex flex-wrap gap-1.5\">\n                {PRESETS.map((p, i) => (\n                  <button key={p.name} onClick={() => applyPreset(i)}\n                    className={`text-xs px-3 py-2 rounded-lg border font-medium transition ${\n                      presetIndex === i ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'\n                    }`}>{p.name}</button>\n                ))}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                  <span className=\"text-xs text-gray-500\">trace(A)</span>\n                  <span className=\"text-xs font-semibold tabular-nums text-gray-700\">{eig.trace.toFixed(2)}</span>\n                </div>\n                <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                  <span className=\"text-xs text-gray-500\">det(A)</span>\n                  <span className=\"text-xs font-semibold tabular-nums text-gray-700\">{eig.det.toFixed(2)}</span>\n                </div>\n                {eig.complex ? (\n                  <p className=\"text-xs text-rose-600 leading-relaxed px-1 pt-1\">\n                    Complex eigenvalues — no real eigenvector exists. Every direction rotates.\n                  </p>\n                ) : (\n                  <>\n                    <div className=\"flex justify-between items-center rounded-lg bg-amber-50 px-3 py-2\">\n                      <span className=\"text-xs text-amber-700\">λ₁ (gold)</span>\n                      <span className=\"text-xs font-semibold tabular-nums text-amber-700\">{eig.l1?.toFixed(3)}</span>\n                    </div>\n                    <div className=\"flex justify-between items-center rounded-lg bg-purple-50 px-3 py-2\">\n                      <span className=\"text-xs text-purple-700\">λ₂ (purple)</span>\n                      <span className=\"text-xs font-semibold tabular-nums text-purple-700\">{eig.l2?.toFixed(3)}</span>\n                    </div>\n                  </>\n                )}\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/minitab/damped-oscillator/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useEffect } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { DampedOscillatorCanvas } from '@/components/simulation/DampedOscillatorCanvas';\nimport { DampedOscillatorGraph } from '@/components/simulation/DampedOscillatorGraph';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { dampingRegime, dampedSecondaryFreq } from '@/lib/physics/dampedOscillator';\n\nconst TEACHER_NOTES = [\n  \"y'' + 2γy' + ω₀²y = 0 models a car's suspension, a door closer, a voltmeter needle settling — anything that relaxes back to equilibrium after a disturbance, with some form of friction/resistance present.\",\n  \"Chapter 15's method: take ℒ of both sides, solve the resulting algebraic equation for Y(s), then invert. The differential equation becomes ordinary algebra.\",\n  \"The three regimes come from the sign of ω₀²−γ² inside the square root: positive → real oscillation frequency ω_d (underdamped); zero → critical damping; negative → real hyperbolic frequency ω_h (overdamped, no oscillation at all).\",\n  \"Critical damping (γ=ω₀) is the fastest possible return to equilibrium WITHOUT overshooting — this is why shock absorbers and galvanometers are deliberately designed to sit at (or just past) this exact point.\",\n  \"The dashed envelope curve is ±amplitude·e^(−γt) — every regime decays inside this envelope; only the underdamped case actually touches it periodically.\",\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  {\n    q: 'A system has γ=1, ω₀=3, y(0)=2, y′(0)=0. Find ω_d and classify the regime.',\n    a: 'ω₀²−γ²=9−1=8>0 → underdamped. ω_d=√8≈2.83 rad/s.',\n  },\n  {\n    q: 'Using the values above, write down y(t) in closed form (no need to evaluate numerically).',\n    a: \"y(t)=e^(−t)[2cos(2.83t) + ((0+1×2)/2.83)sin(2.83t)] = e^(−t)[2cos(2.83t) + 0.707sin(2.83t)]\",\n  },\n  {\n    q: 'For what value of γ (given ω₀=5) does the system become critically damped?',\n    a: 'γ=ω₀=5 exactly — this is the definition of critical damping.',\n  },\n  {\n    q: 'A system has γ=4, ω₀=2. Is it under-, critically, or overdamped? Find ω_h.',\n    a: 'γ>ω₀ → overdamped. ω_h=√(γ²−ω₀²)=√(16−4)=√12≈3.46.',\n  },\n  {\n    q: \"Explain, without solving the ODE, why the critically damped case can't be found by simply setting ω_d=0 in the underdamped formula.\",\n    a: \"Setting ω_d=0 makes the (b/ω_d)sin(ω_d t) term divide by zero. The critically-damped solution isn't a limiting case you can just plug into the underdamped formula — it comes from a genuinely different partial-fraction decomposition of Y(s), because (s+γ)²+ω_d² becomes a repeated root (s+γ)² when ω_d=0, which inverts to a t·e^(−γt) term instead of a sine.\",\n  },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nconst REGIME_META: Record<string, { label: string; color: string }> = {\n  underdamped: { label: 'Underdamped — oscillates', color: 'bg-indigo-100 text-indigo-700' },\n  critical: { label: 'Critically damped', color: 'bg-amber-100 text-amber-700' },\n  overdamped: { label: 'Overdamped — no oscillation', color: 'bg-rose-100 text-rose-700' },\n};\n\nexport default function DampedOscillatorPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [currentT, setCurrentT] = useState(0);\n\n  const [gamma, setGamma] = useState(0.8);\n  const [omega0, setOmega0] = useState(2.0);\n  const [y0, setY0] = useState(1.0);\n  const [yp0, setYp0] = useState(0.0);\n\n  const regime = dampingRegime(gamma, omega0);\n  const secondaryFreq = dampedSecondaryFreq(gamma, omega0);\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1); setCurrentT(0);\n  }, []);\n\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [gamma, omega0, y0, yp0, reset]);\n\n  // Throttled to ~25fps — see project conventions: updating React state every\n  // animation frame stutters the Recharts graph re-render.\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((t: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current > 40) {\n      lastTickRef.current = now;\n      setCurrentT(t);\n    }\n  }, []);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 380, 300, 500);\n\n  useTopicPreset(\"minitab-damped-oscillator\", { \"gamma\": setGamma,\n    \"omega0\": setOmega0,\n    \"y0\": setY0,\n    \"yp0\": setYp0 }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapters 14–15</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Damped Oscillator (Laplace Transform)</h1>\n              </div>\n              <span className={`text-xs px-3 py-1.5 rounded-full font-medium ${REGIME_META[regime].color}`}>\n                {REGIME_META[regime].label}\n              </span>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n\n          {/* Equation banner */}\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Governing equation</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">y&apos;&apos; + 2γy&apos; + ω₀²y = 0</span>\n            <span className=\"text-xs text-gray-400 ml-2\">\n              {regime === 'underdamped' && `ω_d = ${secondaryFreq.toFixed(3)} rad/s`}\n              {regime === 'overdamped' && `ω_h = ${secondaryFreq.toFixed(3)} rad/s`}\n              {regime === 'critical' && 'y(t) = e^(−γt)[y₀ + (y′₀+γy₀)t]'}\n            </span>\n          </div>\n\n          {/* Main grid */}\n          <SimulationStage className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n\n            <div data-stage-role=\"canvas\" className=\"space-y-3 min-w-0\">\n              {/* Canvas */}\n              <div ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <DampedOscillatorCanvas key={resetKey}\n                  gamma={gamma} omega0={omega0} y0={y0} yp0={yp0}\n                  isRunning={isRunning} isPaused={isPaused}\n                  onTick={handleTick}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              {/* Controls */}\n              <div className=\"flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <SimulationControls\n                  isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)}\n                  onReset={reset}\n                />\n                <EmbedButton\n                  path=\"/embed/damped-oscillator\"\n                  params={{ gamma, omega0, y0, yp0 }}\n                  title=\"Damped Oscillator (Laplace Transform)\"\n                />\n              </div>\n\n              {/* Graph */}\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-2\">y(t) vs time</p>\n                <DampedOscillatorGraph gamma={gamma} omega0={omega0} y0={y0} yp0={yp0} currentT={currentT} />\n              </div>\n            </div>\n\n            {/* Sliders + stats */}\n            <div data-stage-role=\"parameters\" className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-4\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Parameters</p>\n                <Slider label=\"Damping γ\" unit=\"1/s\" value={gamma} min={0} max={6} step={0.05}\n                  set={setGamma} color=\"#f59e0b\" note=\"Larger γ = more friction/resistance\" />\n                <Slider label=\"Natural frequency ω₀\" unit=\"rad/s\" value={omega0} min={0.5} max={6} step={0.05}\n                  set={setOmega0} color=\"#6366f1\" note=\"What it would oscillate at with zero damping\" />\n                <Slider label=\"Initial displacement y(0)\" unit=\"\" value={y0} min={-2} max={2} step={0.1}\n                  set={setY0} color=\"#10b981\" />\n                <Slider label=\"Initial velocity y'(0)\" unit=\"/s\" value={yp0} min={-4} max={4} step={0.1}\n                  set={setYp0} color=\"#ec4899\" />\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Calculated values</p>\n                {[\n                  { l: 'Regime', v: REGIME_META[regime].label, c: 'text-gray-700' },\n                  { l: regime === 'overdamped' ? 'ω_h' : 'ω_d', v: `${secondaryFreq.toFixed(3)} rad/s`, c: 'text-indigo-600' },\n                  { l: 'y at t=3s', v: '', c: 'text-emerald-600' },\n                ].filter(r => r.v).map(r => (\n                  <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">{r.l}</span>\n                    <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                  </div>\n                ))}\n              </div>\n            </div>\n\n            {/* Teacher notes + exercises */}\n            <div data-stage-role=\"parameters\" className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/minitab/hermite-laguerre-delta/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { HermiteLaguerreGraph, DiracDeltaGraph } from '@/components/simulation/HermiteLaguerreDeltaGraph';\nimport { deltaIntegrals, testFn } from '@/lib/physics/hermiteLaguerreDelta';\n\nconst TEACHER_NOTES = [\n  'Hermite polynomials, weighted by e⁻ˣ², are exactly the spatial part of the quantum harmonic oscillator\\u2019s energy eigenstates — Hₙ(x)e⁻ˣ²/² is (up to normalisation) the n-th excited-state wavefunction.',\n  'Laguerre polynomials, weighted by e⁻ˣ, are exactly the radial part of the hydrogen atom\\u2019s wavefunctions — different n give different electron shells.',\n  'Chapter 11 defines δ(x) by two properties — zero everywhere except x=0, total area 1 — rather than by a formula, because no ordinary function has both at once.',\n  'Drag ε down toward zero on the delta tab: the pulse gets taller and narrower, the area stays exactly 1 the whole time, and ∫f(x)δ_ε(x)dx converges to f(0) — the sifting property, made concrete.',\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'Using H₀=1, H₁=2x and the recurrence Hₙ₊₁=2xHₙ−2nHₙ₋₁, find H₂(x).', a: 'H₂=2xH₁−2(1)H₀=2x(2x)−2=4x²−2.' },\n  { q: 'Using L₀=1, L₁=1−x and the recurrence, find L₂(1).', a: '(n+1)Lₙ₊₁=(2n+1−x)Lₙ−nLₙ₋₁ with n=1,x=1: 2L₂=(3−1)(0)−1(1)=−1 → L₂(1)=−0.5.' },\n  { q: 'State the two defining properties of the Dirac delta function δ(x).', a: 'δ(x)=0 for all x≠0, and ∫₋∞^∞δ(x)dx=1 (all the \"mass\" concentrated at a single point).' },\n  { q: 'State the sifting property of δ(x).', a: '∫f(x)δ(x−a)dx=f(a) for any well-behaved f — the delta function \"picks out\" the value of f at the point where the delta spike sits.' },\n  { q: 'Why can no ordinary function satisfy both defining properties of δ(x) exactly?', a: 'A function that is zero everywhere except a single point has zero area under any reasonable (Riemann) integral, no matter how \"tall\" it is at that one point — so no ordinary function can have zero width AND nonzero total area. δ(x) is instead defined as the limit of a family of functions (like the narrowing Gaussian shown here), not as a function itself.' },\n];\n\nconst FN_OPTIONS = [\n  { value: 'quad', label: 'f(x) = x² · 0.15 + 1' },\n  { value: 'sin', label: 'f(x) = sin(x) · 0.8 + 2' },\n  { value: 'cube', label: 'f(x) = cubic' },\n];\n\nexport default function HermiteLaguerreDeltaPage() {\n  const [mode, setMode] = useState<'hermite' | 'laguerre' | 'delta'>('hermite');\n  const [shownH, setShownH] = useState([0, 1, 2, 3]);\n  const [shownL, setShownL] = useState([0, 1, 2, 3]);\n  const [epsExp, setEpsExp] = useState(0);\n  const [fname, setFname] = useState('quad');\n\n  const toggle = (arr: number[], set: (v: number[]) => void) => (i: number) =>\n    set(arr.includes(i) ? arr.filter(v => v !== i) : [...arr, i]);\n\n  const eps = Math.pow(10, epsExp);\n  const { area, sift } = mode === 'delta' ? deltaIntegrals(eps, fname) : { area: 0, sift: 0 };\n\n  useTopicPreset(\"minitab-hermite-laguerre-delta\", { \"epsExp\": setEpsExp }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapter 11</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Hermite, Laguerre &amp; the Dirac Delta</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1.5 flex-wrap\">\n            {(['hermite', 'laguerre', 'delta'] as const).map(m => (\n              <button key={m} onClick={() => setMode(m)}\n                className={`text-xs px-4 py-2 rounded-lg border font-medium capitalize transition ${mode === m ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200'}`}>\n                {m === 'delta' ? 'Dirac delta' : m}\n              </button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                {mode === 'hermite' && <HermiteLaguerreGraph mode=\"hermite\" shown={shownH} />}\n                {mode === 'laguerre' && <HermiteLaguerreGraph mode=\"laguerre\" shown={shownL} />}\n                {mode === 'delta' && <DiracDeltaGraph eps={eps} fname={fname} />}\n              </div>\n\n              <div data-stage-role=\"parameters\">{mode === 'hermite' && (\n                <div className=\"flex flex-wrap gap-1.5 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                  {Array.from({ length: 7 }, (_, i) => i).map(i => (\n                    <label key={i} className=\"flex items-center gap-1.5 text-xs px-2.5 py-1.5 rounded-lg border border-gray-100 cursor-pointer\">\n                      <input type=\"checkbox\" checked={shownH.includes(i)} onChange={() => toggle(shownH, setShownH)(i)} className=\"accent-indigo-600\" />H{i}\n                    </label>\n                  ))}\n                </div>\n              )}</div>\n              <div data-stage-role=\"parameters\">{mode === 'laguerre' && (\n                <div className=\"flex flex-wrap gap-1.5 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                  {Array.from({ length: 6 }, (_, i) => i).map(i => (\n                    <label key={i} className=\"flex items-center gap-1.5 text-xs px-2.5 py-1.5 rounded-lg border border-gray-100 cursor-pointer\">\n                      <input type=\"checkbox\" checked={shownL.includes(i)} onChange={() => toggle(shownL, setShownL)(i)} className=\"accent-indigo-600\" />L{i}\n                    </label>\n                  ))}\n                </div>\n              )}</div>\n              <div data-stage-role=\"parameters\">{mode === 'delta' && (\n                <div className=\"space-y-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                  <div className=\"flex items-center gap-3\">\n                    <span className=\"text-xs text-gray-500 shrink-0\">Narrow the pulse (ε)</span>\n                    <input type=\"range\" min={-2} max={0.3} step={0.02} value={epsExp} onChange={e => setEpsExp(Number(e.target.value))} className=\"flex-1\" style={{ accentColor: '#2563eb' }} />\n                    <span className=\"text-xs font-mono text-gray-500 w-16 text-right\">{eps.toFixed(3)}</span>\n                  </div>\n                  <select value={fname} onChange={e => setFname(e.target.value)} className=\"w-full rounded-lg border border-gray-300 bg-white px-2 py-1.5 text-xs text-gray-900\">\n                    {FN_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}\n                  </select>\n                </div>\n              )}</div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              {mode === 'delta' && (\n                <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                  <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                  {[\n                    { l: 'Total area ∫δ_ε dx', v: area.toFixed(4), c: 'text-indigo-600' },\n                    { l: '∫f(x)δ_ε(x)dx', v: sift.toFixed(4), c: 'text-emerald-600' },\n                    { l: 'f(0) (target)', v: testFn(fname, 0).toFixed(4), c: 'text-gray-700' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n                </div>\n              )}\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((note, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{note}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/minitab/fourier-series/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useRef, useCallback, useEffect } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { FourierSeriesGraph } from '@/components/simulation/FourierSeriesGraph';\nimport { TARGETS, peakOvershoot } from '@/lib/physics/fourierSeries';\n\nconst TEACHER_NOTES = [\n  \"Chapter 12 derives the coefficients aₙ, bₙ from orthogonality — this shows what those coefficients actually buy you. Each harmonic is a perfectly smooth sine or cosine; stacking enough of them reproduces a sharp corner or even a jump.\",\n  'Away from any discontinuity, the approximation converges beautifully as N grows. Right at a jump, the overshoot settles to a fixed ≈9% of the jump height — the Gibbs phenomenon — and stays there forever, however large N gets.',\n  'Compare N=5 and N=60 on the square wave: the overshoot spike gets narrower, not shorter. More terms squeeze it, never eliminate it.',\n  'The triangle wave has no jump discontinuity at all, so it has no Gibbs overshoot, and converges much faster (1/n² coefficients vs 1/n for the square wave and sawtooth).',\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'Write the first three nonzero terms of the square-wave series.', a: '(4/π)[sin(x) + (1/3)sin(3x) + (1/5)sin(5x)].' },\n  { q: 'Why does the square-wave series only contain odd harmonics?', a: 'A square wave with this symmetry (odd function, period 2π, antisymmetric about the half-period) has bₙ=0 for even n by the orthogonality integral — only odd sine terms survive.' },\n  { q: \"Estimate the Gibbs overshoot percentage for the square wave at large N, using the widget.\", a: 'Approximately 9% of the jump height (the jump here is 2, from −1 to +1), matching the theoretical Gibbs constant ≈8.95%.' },\n  { q: 'Why does the triangle wave series converge faster than the square wave series?', a: 'The triangle-wave coefficients fall off as 1/n², while the square wave and sawtooth fall off only as 1/n — faster-decaying coefficients mean each additional term contributes less, so fewer terms are needed for a good approximation.' },\n  { q: 'Write the first two nonzero terms of the sawtooth series.', a: '2[sin(x) − (1/2)sin(2x)].' },\n];\n\nexport default function FourierSeriesPage() {\n  const [targetIndex, setTargetIndex] = useState(0);\n  const [n, setN] = useState(1);\n  const [animating, setAnimating] = useState(false);\n  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);\n\n  const target = TARGETS[targetIndex];\n\n  const toggleAnimate = useCallback(() => {\n    if (animating) {\n      if (intervalRef.current) clearInterval(intervalRef.current);\n      setAnimating(false);\n      return;\n    }\n    setAnimating(true);\n    intervalRef.current = setInterval(() => {\n      setN(prev => (prev >= 60 ? 1 : prev + 1));\n    }, 180);\n  }, [animating]);\n\n  useEffect(() => () => { if (intervalRef.current) clearInterval(intervalRef.current); }, []);\n\n  const overshoot = peakOvershoot(target, n);\n\n  useTopicPreset(\"minitab-fourier-series\", { \"n\": setN }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapter 12</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Fourier Series Builder</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap gap-1.5\">\n            {TARGETS.map((t, i) => (\n              <button key={t.name} onClick={() => { setTargetIndex(i); setN(1); }}\n                className={`text-xs px-3 py-2 rounded-lg border font-medium transition ${\n                  targetIndex === i ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'\n                }`}>{t.name}</button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <FourierSeriesGraph target={target} n={n} />\n              </div>\n              <div data-stage-role=\"parameters\" className=\"flex items-center gap-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <input type=\"range\" min={1} max={60} step={1} value={n}\n                  onChange={e => setN(Number(e.target.value))} className=\"flex-1\" style={{ accentColor: '#059669' }} />\n                <span className=\"text-xs font-mono text-gray-500 w-16 text-right\">N={n}</span>\n                <button onClick={toggleAnimate}\n                  className=\"text-xs px-3 py-2 rounded-lg border border-gray-200 bg-white font-medium text-gray-600 hover:border-emerald-300 transition\">\n                  {animating ? '⏸ Stop' : '▶ Animate'}\n                </button>\n              </div>\n              <div data-stage-role=\"extra\"><p className=\"text-[11px] font-mono text-gray-400 px-1\">{target.formula}</p></div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                  <span className=\"text-xs text-gray-500\">Terms used</span>\n                  <span className=\"text-xs font-semibold tabular-nums text-gray-700\">N={n}</span>\n                </div>\n                <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                  <span className=\"text-xs text-gray-500\">Peak overshoot near jump</span>\n                  <span className=\"text-xs font-semibold tabular-nums text-amber-600\">{target.hasJump ? `${overshoot.toFixed(1)}%` : 'n/a'}</span>\n                </div>\n              </div>\n              {target.hasJump && n > 5 && (\n                <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-3\">\n                  <p className=\"text-[11px] text-amber-800 leading-relaxed\">\n                    Overshoot holds near 9% however large N gets — that&apos;s the Gibbs phenomenon.\n                  </p>\n                </div>\n              )}\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((note, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{note}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/minitab/gradient-explorer/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useState, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { GradientExplorerCanvas } from '@/components/simulation/GradientExplorerCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { FIELDS } from '@/lib/physics/gradientField';\n\nconst TEACHER_NOTES = [\n  \"D_â φ = ∇φ · â replaces Chapter 1's slow limit-definition calculation with a single dot product — find ∇φ once at a point, then any directional derivative there is just a dot product away.\",\n  \"∇φ always points in the direction of steepest increase of φ, and its magnitude |∇φ| IS the steepest rate of increase.\",\n  \"Drag the gold handle until it's perpendicular to the green gradient arrow — the readout drops to ≈0. That's exactly why level curves and ∇φ are always perpendicular: moving along a level curve means φ doesn't change at all.\",\n  \"Drag the gold handle to point the opposite way from ∇φ and watch D_âφ hit its most negative value −|∇φ| — steepest decrease.\",\n  \"Try the saddle field x²−y² at the origin: ∇φ=0 there (a stationary point), and every direction gives D_âφ=0 — the classic saddle-point signature.\",\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'For φ=x²+y², find ∇φ at (1,1) and its magnitude.', a: '∇φ=(2x,2y)=(2,2) at (1,1). |∇φ|=√(4+4)=√8≈2.83.' },\n  { q: 'Using the gradient from above, find D_âφ in direction â=(1/√2,1/√2).', a: 'D_âφ=∇φ·â=2(1/√2)+2(1/√2)=4/√2=2√2≈2.83 — matches |∇φ| exactly, since â is aligned with ∇φ here.' },\n  { q: 'For φ=xy, find ∇φ at (2,3) and the direction of steepest ascent.', a: '∇φ=(y,x)=(3,2) at (2,3). Direction: (3,2)/|(3,2)|=(3,2)/√13≈(0.83,0.55).' },\n  { q: 'At what points does ∇φ=0 for φ=x²−y²?', a: 'Only at the origin (0,0), where both 2x=0 and −2y=0 — the saddle point.' },\n  { q: 'Explain why moving along a level curve always gives D_âφ=0.', a: 'A level curve is defined by φ=constant, so by definition φ does not change as you move along it — and D_âφ measures exactly that rate of change, so it must be zero in that direction.' },\n];\n\nexport default function GradientExplorerPage() {\n  const [fieldIndex, setFieldIndex] = useState(0);\n  const [point, setPoint] = useState({ x: 1.3, y: 0.9 });\n  const [angleDeg, setAngleDeg] = useState(45);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 480, 480, 520);\n\n  const field = FIELDS[fieldIndex];\n  const gx = field.gx(point.x, point.y), gy = field.gy(point.x, point.y);\n  const gmag = Math.hypot(gx, gy);\n  const rad = (angleDeg * Math.PI) / 180;\n  const dirDeriv = gx * Math.cos(rad) + gy * Math.sin(rad);\n  const phi = field.f(point.x, point.y);\n\n  let interpretation = 'D_âφ = ∇φ·â = |∇φ|cosθ — rotate the handle and watch this hold exactly.';\n  const cosAngle = gmag > 1e-6 ? dirDeriv / gmag : 0;\n  if (gmag < 0.05) {\n    interpretation = '∇φ ≈ 0 here — a stationary point. Every direction gives D_âφ ≈ 0.';\n  } else if (Math.abs(cosAngle) > 0.97) {\n    interpretation = cosAngle > 0\n      ? 'â is aligned with ∇φ — steepest increase, D_âφ at its maximum |∇φ|.'\n      : 'â points opposite to ∇φ — steepest decrease, D_âφ at its minimum −|∇φ|.';\n  } else if (Math.abs(dirDeriv) < 0.05 * gmag) {\n    interpretation = \"â is perpendicular to ∇φ — you're moving along the level curve; φ barely changes.\";\n  }\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapters 1–2</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Gradient &amp; Directional Derivative Explorer</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div data-stage-role=\"parameters\" className=\"flex flex-wrap gap-1.5\">\n            {FIELDS.map((f, i) => (\n              <button key={f.name} onClick={() => setFieldIndex(i)}\n                className={`text-xs px-3 py-2 rounded-lg border font-medium transition ${\n                  fieldIndex === i ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-300'\n                }`}>{f.name}</button>\n            ))}\n          </div>\n\n          <SimulationStage className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <div data-stage-role=\"canvas\" className=\"space-y-3 min-w-0\">\n              <div ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm flex justify-center\">\n                <GradientExplorerCanvas\n                  fieldIndex={fieldIndex} point={point} angleDeg={angleDeg}\n                  onPointChange={setPoint} onAngleChange={setAngleDeg}\n                  width={canvasSize.width} height={canvasSize.height}\n                />\n              </div>\n              <div className=\"rounded-2xl border border-emerald-100 bg-emerald-50 p-4\">\n                <p className=\"text-xs text-emerald-900 leading-relaxed\">{interpretation}</p>\n              </div>\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-3\">\n              <label className=\"block text-sm text-gray-700\">Scalar field<select aria-label=\"Scalar field\" value={fieldIndex} onChange={e=>setFieldIndex(Number(e.target.value))} className=\"mt-1 w-full rounded-lg border border-gray-300 bg-white p-2\">{FIELDS.map((f,i)=><option key={f.name} value={i}>{f.name}</option>)}</select></label>\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                {[\n                  { l: 'Point (x,y)', v: `(${point.x.toFixed(2)}, ${point.y.toFixed(2)})`, c: 'text-gray-700' },\n                  { l: 'φ(x,y)', v: phi.toFixed(3), c: 'text-gray-700' },\n                  { l: '∇φ', v: `(${gx.toFixed(2)}, ${gy.toFixed(2)})`, c: 'text-emerald-600' },\n                  { l: '|∇φ|', v: gmag.toFixed(3), c: 'text-emerald-600' },\n                  { l: 'â direction', v: `${angleDeg.toFixed(0)}°`, c: 'text-amber-600' },\n                  { l: 'D_âφ = ∇φ·â', v: dirDeriv.toFixed(3), c: 'text-indigo-600' },\n                ].map(r => (\n                  <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">{r.l}</span>\n                    <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                  </div>\n                ))}\n              </div>\n              <p className=\"text-[11px] text-gray-400 px-1\">Drag the blue point to move; drag the gold arrowhead to change direction â.</p>\n            </div>\n\n            <div data-stage-role=\"extra\" className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/minitab/legendre-bessel/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { LegendreBesselGraph } from '@/components/simulation/LegendreBesselGraph';\nimport { legendreOrthogonality, besselJ } from '@/lib/physics/legendreBessel';\n\nconst TEACHER_NOTES = [\n  'Chapter 9 proves ∫₋₁¹PₘPₙdx=0 for m≠n and =2/(2n+1) for m=n. Pick any two orders below and the panel computes that integral directly by numerical quadrature — you should see essentially zero off the diagonal and an exact match to 2/(2n+1) on it.',\n  \"Chapter 10's recurrence Jₙ₋₁(x)+Jₙ₊₁(x)=(2n/x)Jₙ(x) links three different Bessel orders at the same point. Drag x and watch both sides — computed completely independently via the integral definition of Jₙ — stay equal.\",\n  'Bessel functions oscillate with slowly decreasing amplitude, unlike Legendre polynomials which are confined to [−1,1] — this reflects the very different boundary conditions each equation is solved under.',\n  'Legendre polynomials with even n are even functions, odd n are odd functions — visible directly in the P₀…P₆ overlay.',\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'State the value of Pₙ(1) for every n.', a: 'Pₙ(1)=1 for every n — visible in the graph as all curves passing through (1,1).' },\n  { q: 'Using the three-term recurrence (n+1)Pₙ₊₁=(2n+1)xPₙ−nPₙ₋₁ with P₀=1, P₁=x, find P₂(x).', a: '2P₂=3xP₁−1×P₀=3x²−1 → P₂(x)=(3x²−1)/2.' },\n  { q: 'What is ∫₋₁¹[P₃(x)]²dx, according to the normalisation formula?', a: '2/(2n+1) with n=3: 2/7≈0.2857.' },\n  { q: 'State the value of Jₙ(0) for n=0 and for n≥1.', a: 'J₀(0)=1; Jₙ(0)=0 for every n≥1 — visible in the graph as only J₀ starting at height 1.' },\n  { q: 'Using the recurrence, express J₃(x) in terms of J₂(x) and J₄(x) rearranged.', a: 'From J₂+J₄=(6/x)J₃ is not directly this form — instead use Jₙ₋₁+Jₙ₊₁=(2n/x)Jₙ with n=3: J₂(x)+J₄(x)=(6/x)J₃(x), so J₃(x)=[J₂(x)+J₄(x)]·x/6.' },\n];\n\nexport default function LegendreBesselPage() {\n  const [mode, setMode] = useState<'legendre' | 'bessel'>('legendre');\n  const [shown, setShown] = useState<number[]>([0, 1, 2, 3]);\n  const [m, setM] = useState(2);\n  const [n, setN] = useState(3);\n  const [besN, setBesN] = useState(2);\n  const [besX, setBesX] = useState(5);\n\n  const toggle = (i: number) => setShown(prev => prev.includes(i) ? prev.filter(v => v !== i) : [...prev, i]);\n\n  const orthIntegral = legendreOrthogonality(m, n);\n  const expected = m === n ? 2 / (2 * n + 1) : 0;\n\n  const Jn = besselJ(besN, besX), Jm1 = besselJ(besN - 1, besX), Jp1 = besselJ(besN + 1, besX);\n  const lhs = Jm1 + Jp1, rhs = (2 * besN / besX) * Jn;\n\n  useTopicPreset(\"minitab-legendre-bessel\", { \"besX\": setBesX }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapters 9–10</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Legendre &amp; Bessel Explorer</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1.5\">\n            <button onClick={() => setMode('legendre')}\n              className={`text-xs px-4 py-2 rounded-lg border font-medium transition ${mode === 'legendre' ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200'}`}>Legendre Pₙ(x)</button>\n            <button onClick={() => setMode('bessel')}\n              className={`text-xs px-4 py-2 rounded-lg border font-medium transition ${mode === 'bessel' ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200'}`}>Bessel Jₙ(x)</button>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <LegendreBesselGraph mode={mode} shown={shown} />\n              </div>\n              <div data-stage-role=\"parameters\" className=\"flex flex-wrap gap-1.5 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                {Array.from({ length: 7 }, (_, i) => i).map(i => (\n                  <label key={i} className=\"flex items-center gap-1.5 text-xs px-2.5 py-1.5 rounded-lg border border-gray-100 cursor-pointer hover:border-indigo-200\">\n                    <input type=\"checkbox\" checked={shown.includes(i)} onChange={() => toggle(i)} className=\"accent-indigo-600\" />\n                    {mode === 'legendre' ? 'P' : 'J'}{i}\n                  </label>\n                ))}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              {mode === 'legendre' ? (\n                <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-3\">\n                  <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Orthogonality check</p>\n                  <div className=\"flex gap-2 items-center\">\n                    <span className=\"text-xs text-gray-500\">m=</span>\n                    <select value={m} onChange={e => setM(Number(e.target.value))} className=\"rounded-lg border border-gray-300 bg-white px-2 py-1 text-xs text-gray-900\">\n                      {Array.from({ length: 7 }, (_, i) => i).map(i => <option key={i} value={i}>{i}</option>)}\n                    </select>\n                    <span className=\"text-xs text-gray-500\">n=</span>\n                    <select value={n} onChange={e => setN(Number(e.target.value))} className=\"rounded-lg border border-gray-300 bg-white px-2 py-1 text-xs text-gray-900\">\n                      {Array.from({ length: 7 }, (_, i) => i).map(i => <option key={i} value={i}>{i}</option>)}\n                    </select>\n                  </div>\n                  <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">∫₋₁¹PₘPₙdx</span>\n                    <span className=\"text-xs font-semibold tabular-nums text-indigo-600\">{orthIntegral.toFixed(5)}</span>\n                  </div>\n                  <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">Expected (theory)</span>\n                    <span className=\"text-xs font-semibold tabular-nums text-emerald-600\">{expected.toFixed(5)}</span>\n                  </div>\n                </div>\n              ) : (\n                <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-3\">\n                  <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Recurrence check</p>\n                  <div className=\"flex gap-2 items-center\">\n                    <span className=\"text-xs text-gray-500\">n=</span>\n                    <select value={besN} onChange={e => setBesN(Number(e.target.value))} className=\"rounded-lg border border-gray-300 bg-white px-2 py-1 text-xs text-gray-900\">\n                      {[1, 2, 3, 4, 5].map(i => <option key={i} value={i}>{i}</option>)}\n                    </select>\n                  </div>\n                  <input type=\"range\" min={0.5} max={14.5} step={0.1} value={besX} onChange={e => setBesX(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#059669' }} />\n                  <p className=\"text-xs text-gray-500 text-right\">x={besX.toFixed(2)}</p>\n                  <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">J_(n-1)+J_(n+1)</span>\n                    <span className=\"text-xs font-semibold tabular-nums text-indigo-600\">{lhs.toFixed(5)}</span>\n                  </div>\n                  <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">(2n/x)·Jₙ</span>\n                    <span className=\"text-xs font-semibold tabular-nums text-emerald-600\">{rhs.toFixed(5)}</span>\n                  </div>\n                </div>\n              )}\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((note, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{note}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/minitab/gamma-function/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useState } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { GammaGraph } from '@/components/simulation/GammaGraph';\nimport { gamma } from '@/lib/physics/gammaFunction';\n\nconst TEACHER_NOTES = [\n  'Γ(x+1)=xΓ(x), derived by integration by parts, explains everything on this graph: run it forward and Γ(n+1)=n! at every positive integer (green dots); run it backward and it forces Γ(x) to blow up at x=0,−1,−2,…',\n  'Try dragging x from 1 to 6 and watch Γ(x+1) computed two ways — directly, and via x·Γ(x) — always match exactly.',\n  'Γ(½)=√π is the one value that does NOT come from the recurrence — Chapter 8 derives it from the Gaussian integral instead. Every other half-integer value follows from it by the recurrence.',\n  'Toggle \"Show negative branches\" and drag just past x=0 or x=−1 — the value shoots toward ±∞, the poles predicted by the recurrence relation.',\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'Find Γ(5) using Γ(n+1)=n!.', a: 'Γ(5)=4!=24.' },\n  { q: 'Find Γ(7) using the recurrence Γ(x+1)=xΓ(x), starting from Γ(6)=120.', a: 'Γ(7)=6×Γ(6)=6×120=720=6!.' },\n  { q: 'Find Γ(3/2) using Γ(1/2)=√π and the recurrence.', a: 'Γ(3/2)=Γ(1/2+1)=(1/2)Γ(1/2)=√π/2≈0.8862.' },\n  { q: 'Explain, without calculating, why Γ(x) must be undefined at x=−3.', a: 'Rearranging the recurrence gives Γ(x)=Γ(x+1)/x, which blows up whenever the denominator hits an integer where Γ is finite and nonzero above it — chaining this down from Γ(1)=1 forces a pole at every non-positive integer, including x=−3.' },\n  { q: 'Find Γ(5/2) using Γ(3/2) from the previous question.', a: 'Γ(5/2)=(3/2)Γ(3/2)=(3/2)(√π/2)=3√π/4≈1.3293.' },\n];\n\nexport default function GammaExplorerPage() {\n  const [x, setX] = useState(1.5);\n  const [showNegative, setShowNegative] = useState(true);\n\n  const gx = gamma(x);\n  const isNearPole = Math.abs(x - Math.round(x)) < 0.01 && x <= 0;\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <p className=\"text-xs text-gray-400 mb-0.5\">PHY 403 — Chapter 8</p>\n            <h1 className=\"text-lg font-semibold text-gray-900\">Gamma Function Explorer</h1>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <GammaGraph x={x} showNegative={showNegative} />\n              </div>\n              <div data-stage-role=\"parameters\" className=\"flex flex-wrap items-center gap-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <span className=\"text-xs text-gray-500 shrink-0\">Evaluate at x</span>\n                <input type=\"range\" min={showNegative ? -4.5 : 0.05} max={6} step={0.01} value={x}\n                  onChange={e => setX(Number(e.target.value))} className=\"flex-1\" style={{ accentColor: '#10b981' }} />\n                <span className=\"text-xs font-mono text-gray-500 w-14 text-right\">{x.toFixed(2)}</span>\n              </div>\n              <div data-stage-role=\"parameters\"><label className=\"flex items-center gap-2 text-xs text-gray-600 px-1 cursor-pointer\">\n                <input type=\"checkbox\" checked={showNegative} onChange={e => setShowNegative(e.target.checked)} className=\"accent-indigo-600\" />\n                Show negative-x branches\n              </label></div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                {[\n                  { l: 'x', v: x.toFixed(2), c: 'text-gray-700' },\n                  { l: 'Γ(x)', v: isNearPole ? '±∞ (pole)' : isFinite(gx) ? gx.toFixed(4) : '±∞', c: 'text-indigo-600' },\n                  { l: 'Γ(x+1) = x·Γ(x)', v: isFinite(gx) ? (x * gx).toFixed(4) : '—', c: 'text-emerald-600' },\n                  { l: 'Γ(x+1) direct', v: isFinite(gamma(x + 1)) ? gamma(x + 1).toFixed(4) : '—', c: 'text-emerald-600' },\n                ].map(r => (\n                  <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">{r.l}</span>\n                    <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                  </div>\n                ))}\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <ExerciseList />\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n\nfunction ExerciseList() {\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n      <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n      <div className=\"space-y-2\">\n        {EXERCISES.map((ex, i) => (\n          <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n            <button onClick={() => setOpenEx(openEx === i ? null : i)}\n              className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n              <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n              <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n            </button>\n            {openEx === i && (\n              <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                <span className=\"font-medium\">Answer: </span>{ex.a}\n              </div>\n            )}\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n", "src/app/simulations/coupled-oscillators/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useEffect } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { CoupledOscillatorsCanvas } from '@/components/simulation/CoupledOscillatorsCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport {\n  OscillatorState, OscillatorParams, totalEnergy,\n  PRESETS, OscillatorPreset,\n} from '@/lib/physics/coupledOscillators';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TEACHER_NOTES = [\n  'Coupled oscillators are the linear counterpart to the double pendulum. Instead of chaos, we get superposition of normal modes.',\n  'The system has two normal modes: in-phase (both masses move together) and out-of-phase (they move oppositely). Any motion is a sum of these two modes.',\n  'When the coupling is weak and the two individual oscillators have nearly the same frequency, you see beats — periodic transfer of energy from one mass to the other.',\n  'The beat frequency is the difference between the two normal-mode frequencies: f_beat = |ω₂ − ω₁| / (2π).',\n  'Damping removes energy from the system. The Q-factor tells you how many oscillations occur before the energy drops significantly: Q ≈ 2π × (energy stored) / (energy lost per cycle).',\n  'In the damped case, the motion eventually settles into the slower normal mode because higher frequencies are damped more strongly.',\n];\n\nconst EXERCISES = [\n  {\n    q: 'Run the \"Beats\" preset and watch the strip chart. How many seconds does one complete beat cycle take?',\n    a: 'For the default parameters (k₁=k₃=1, k₂=0.1, m=1), the normal-mode frequencies are ω₁≈1.00 rad/s and ω₂≈1.10 rad/s. The beat period is 2π/|ω₂−ω₁| ≈ 63 s. You will see roughly one full exchange in about 60–65 seconds.',\n  },\n  {\n    q: 'Compare the \"In-phase\" and \"Out-of-phase\" presets. Which one has the higher frequency? Why?',\n    a: 'Out-of-phase has the higher frequency because the coupling spring is stretched and adds an effective restoring force. For symmetric springs, ω_out² = (k + 2k_c)/m  versus  ω_in² = k/m.',\n  },\n  {\n    q: 'Increase the coupling spring constant k₂ to 2.0 and run \"Beats\". What happens to the beat pattern?',\n    a: 'Strong coupling increases the frequency splitting, so the beat period becomes shorter and the energy transfer happens faster. If k₂ is very large, the two masses are forced to move almost as a single rigid body.',\n  },\n  {\n    q: 'Enable damping and observe the Q-factor. Does Q stay constant as the motion decays?',\n    a: 'For linear damping, Q should remain roughly constant if the frequency does not change much. However, numerical noise at very small amplitudes can make Q fluctuate at the end.',\n  },\n  {\n    q: 'Set m₂ = 5 kg and run \"Heavy second mass\". Why does the first mass oscillate while the second barely moves?',\n    a: 'The heavy mass has large inertia, so the coupling force barely accelerates it. It acts almost like a fixed wall, and m₁ oscillates with a frequency close to √( (k₁+k₂)/m₁ ).',\n  },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input\n        type=\"range\"\n        min={min}\n        max={max}\n        step={step}\n        value={value}\n        onChange={e => set(Number(e.target.value))}\n        className=\"w-full h-6 py-2 cursor-pointer\"\n        style={{ accentColor: color }}\n      />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nfunction DampingCurve({ history }: { history: Array<{ t: number; e: number }> }) {\n  if (history.length < 3) return (\n    <div className=\"rounded-lg bg-slate-900 border border-gray-700 h-24 flex items-center justify-center\">\n      <span className=\"text-[10px] text-gray-500\">Run simulation to see decay curve</span>\n    </div>\n  );\n  const logEs = history.map(h => Math.log(Math.max(h.e, 1e-6)));\n  const minE = Math.min(...logEs);\n  const maxE = Math.max(...logEs);\n  const rangeE = maxE - minE || 1;\n  const minT = history[0].t;\n  const maxT = history[history.length - 1].t;\n  const rangeT = maxT - minT || 1;\n\n  const pts = history.map((h, i) => {\n    const x = ((h.t - minT) / rangeT) * 100;\n    const y = 100 - ((logEs[i] - minE) / rangeE) * 100;\n    return `${x},${y}`;\n  }).join(' ');\n\n  return (\n    <div className=\"rounded-lg bg-slate-900 border border-gray-700 overflow-hidden\">\n      <svg viewBox=\"0 0 100 100\" preserveAspectRatio=\"none\" className=\"w-full h-24 block\">\n        <polyline\n          points={pts}\n          fill=\"none\"\n          stroke=\"#10b981\"\n          strokeWidth=\"1.5\"\n          strokeLinecap=\"round\"\n          strokeLinejoin=\"round\"\n          vectorEffect=\"non-scaling-stroke\"\n        />\n        <text x=\"4\" y=\"12\" fill=\"#94a3b8\" fontSize=\"8\" fontFamily=\"system-ui\">ln(E) vs time</text>\n        <line x1=\"0\" y1=\"100\" x2=\"100\" y2=\"100\" stroke=\"#334155\" strokeWidth=\"0.5\" />\n        <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"100\" stroke=\"#334155\" strokeWidth=\"0.5\" />\n      </svg>\n    </div>\n  );\n}\n\nexport default function CoupledOscillatorsPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB']);\n  const [showTrail, setShowTrail] = useState(true);\n  const [showEnergy, setShowEnergy] = useState(true);\n  const [trailLength, setTrailLength] = useState(300);\n  const [activePreset, setActivePreset] = useState<number | null>(null);\n\n  const [m1, setM1] = useState(1);\n  const [m2, setM2] = useState(1);\n  const [k1, setK1] = useState(1);\n  const [k2, setK2] = useState(0.2);\n  const [k3, setK3] = useState(1);\n  const [x1, setX1] = useState(0.1);\n  const [x2, setX2] = useState(0.1);\n  const [v1, setV1] = useState(0);\n  const [v2, setV2] = useState(0);\n  const [damping1, setDamping1] = useState(0);\n  const [damping2, setDamping2] = useState(0);\n\n  const [liveEnergy, setLiveEnergy] = useState({ ke: 0, pe: 0, total: 0 });\n  const [liveState, setLiveState] = useState({ x1: 0, x2: 0, v1: 0, v2: 0 });\n  const [liveMeta, setLiveMeta] = useState({ qFactor: 0, bandwidth: 0, decayRate: 0, valid: false });\n  const [chartHistory, setChartHistory] = useState<Array<{ t: number; e: number }>>([]);\n\n  const params: OscillatorParams = { m1, m2, k1, k2, k3, damping1, damping2 };\n\n  useEffect(() => {\n    const idx = PRESETS.findIndex(p =>\n      Math.abs(p.m1 - m1) < 0.05 && Math.abs(p.m2 - m2) < 0.05 &&\n      Math.abs(p.k1 - k1) < 0.05 && Math.abs(p.k2 - k2) < 0.05 && Math.abs(p.k3 - k3) < 0.05 &&\n      Math.abs(p.x1 - x1) < 0.005 && Math.abs(p.x2 - x2) < 0.005 &&\n      Math.abs(p.v1 - v1) < 0.05 && Math.abs(p.v2 - v2) < 0.05 &&\n      Math.abs(p.damping1 - damping1) < 0.005 && Math.abs(p.damping2 - damping2) < 0.005\n    );\n    setActivePreset(idx >= 0 ? idx : null);\n  }, [m1, m2, k1, k2, k3, x1, x2, v1, v2, damping1, damping2]);\n\n  const applyPreset = useCallback((preset: OscillatorPreset, index: number) => {\n    setM1(preset.m1); setM2(preset.m2); setK1(preset.k1); setK2(preset.k2); setK3(preset.k3);\n    setX1(preset.x1); setX2(preset.x2); setV1(preset.v1); setV2(preset.v2);\n    setDamping1(preset.damping1); setDamping2(preset.damping2);\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveEnergy({ ke: 0, pe: 0, total: 0 });\n    setLiveState({ x1: 0, x2: 0, v1: 0, v2: 0 });\n    setLiveMeta({ qFactor: 0, bandwidth: 0, decayRate: 0, valid: false });\n    setChartHistory([]);\n    setActivePreset(index);\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveEnergy({ ke: 0, pe: 0, total: 0 });\n    setLiveState({ x1: 0, x2: 0, v1: 0, v2: 0 });\n    setLiveMeta({ qFactor: 0, bandwidth: 0, decayRate: 0, valid: false });\n    setChartHistory([]);\n  }, []);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 420, 900);\n\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((state: OscillatorState, energy: { ke: number; pe: number; total: number }, meta: { qFactor: number; bandwidth: number; decayRate: number; valid: boolean; chartHistory: Array<{ t: number; e: number }> }) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveState({ x1: state.x1, x2: state.x2, v1: state.v1, v2: state.v2 });\n    setLiveEnergy(energy);\n    setLiveMeta({ qFactor: meta.qFactor, bandwidth: meta.bandwidth, decayRate: meta.decayRate, valid: meta.valid });\n    setChartHistory(meta.chartHistory);\n  }, []);\n\n  const initialState: OscillatorState = { x1, v1, x2, v2 };\n  const initialTotalEnergy = totalEnergy(initialState, params);\n\n  const qDisplay = !liveMeta.valid ? '—' :\n    liveMeta.qFactor === Infinity ? '∞ (undamped)' :\n    liveMeta.qFactor > 999 ? '> 999' :\n    liveMeta.qFactor.toFixed(1);\n\n  const bwDisplay = !liveMeta.valid ? '—' :\n    liveMeta.bandwidth < 0.001 ? '~0' :\n    liveMeta.bandwidth.toFixed(3);\n\n  useTopicPreset(\"simulations-coupled-oscillators\", { \"m1\": setM1,\n    \"k1\": setK1,\n    \"x1\": setX1,\n    \"v1\": setV1,\n    \"damping1\": setDamping1,\n    \"m2\": setM2,\n    \"k3\": setK3,\n    \"x2\": setX2,\n    \"v2\": setV2,\n    \"damping2\": setDamping2,\n    \"k2\": setK2,\n    \"trailLength\": setTrailLength }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Mechanics — Linear Systems</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Coupled oscillators</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Linear coupled oscillators — normal modes & beats</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">F = −kx − c v</span>\n          </div>\n\n          <div className=\"flex gap-2 overflow-x-auto pb-2 snap-x snap-mandatory scroll-smooth\">\n            {PRESETS.map((preset, i) => (\n              <button key={i} onClick={() => applyPreset(preset, i)}\n                className={`shrink-0 rounded-xl border px-3 py-2 text-left transition snap-start min-w-[180px] ${\n                  activePreset === i\n                    ? 'border-indigo-500 bg-indigo-50 shadow-sm ring-1 ring-indigo-300'\n                    : 'border-gray-200 bg-white hover:border-indigo-300 hover:shadow-sm'\n                }`}>\n                <p className=\"text-xs font-medium text-indigo-700\">{preset.name}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5 leading-relaxed\">{preset.description}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <CoupledOscillatorsCanvas\n                  key={resetKey}\n                  x1Init={x1}\n                  v1Init={v1}\n                  x2Init={x2}\n                  v2Init={v2}\n                  params={params}\n                  isRunning={isRunning}\n                  isPaused={isPaused}\n                  showTrail={showTrail}\n                  showEnergy={showEnergy}\n                  trailLength={trailLength}\n                  onTick={handleTick}\n                  width={canvasSize.width}\n                  height={canvasSize.height}\n                />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/coupled-oscillators\"\n                  title=\"Coupled Oscillators — A-Factor STEM Studio\"\n                  params={{ m1, m2, k1, k2, k3, x1, x2, v1, v2, d1: damping1, d2: damping2, trail: trailLength }}\n                />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">First mass</p>\n                    <Slider label=\"Mass m₁\" unit=\"kg\" value={m1} min={0.1} max={5} step={0.1} set={setM1} color=\"#6366f1\" />\n                    <Slider label=\"Spring k₁\" unit=\"N/m\" value={k1} min={0.1} max={5} step={0.1} set={setK1} color=\"#818cf8\" />\n                    <Slider label=\"Initial x₁\" unit=\"m\" value={x1} min={-0.3} max={0.3} step={0.01} set={setX1} color=\"#a78bfa\" />\n                    <Slider label=\"Initial v₁\" unit=\"m/s\" value={v1} min={-2} max={2} step={0.05} set={setV1} color=\"#c4b5fd\" />\n                    <Slider label=\"Damping c₁\" unit=\"\" value={damping1} min={0} max={1} step={0.01} set={setDamping1} color=\"#ef4444\" />\n                  </div>\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">Second mass</p>\n                    <Slider label=\"Mass m₂\" unit=\"kg\" value={m2} min={0.1} max={5} step={0.1} set={setM2} color=\"#f59e0b\" />\n                    <Slider label=\"Spring k₃\" unit=\"N/m\" value={k3} min={0.1} max={5} step={0.1} set={setK3} color=\"#fbbf24\" />\n                    <Slider label=\"Initial x₂\" unit=\"m\" value={x2} min={-0.3} max={0.3} step={0.01} set={setX2} color=\"#fcd34d\" />\n                    <Slider label=\"Initial v₂\" unit=\"m/s\" value={v2} min={-2} max={2} step={0.05} set={setV2} color=\"#fde68a\" />\n                    <Slider label=\"Damping c₂\" unit=\"\" value={damping2} min={0} max={1} step={0.01} set={setDamping2} color=\"#ef4444\" />\n                  </div>\n                </div>\n                <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                  <Slider label=\"Coupling k₂\" unit=\"N/m\" value={k2} min={0} max={5} step={0.05} set={setK2} color=\"#10b981\" note=\"Spring between the two masses\" />\n                  <Slider label=\"Trail length\" unit=\"frames\" value={trailLength} min={0} max={800} step={10} set={setTrailLength} color=\"#f43f5e\" />\n                  <div className=\"flex gap-3\">\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showTrail} onChange={e => setShowTrail(e.target.checked)} className=\"rounded\" />\n                      Show trail\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showEnergy} onChange={e => setShowEnergy(e.target.checked)} className=\"rounded\" />\n                      Show energy bar\n                    </label>\n                  </div>\n                </div>\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"Initial total E\" value={initialTotalEnergy.toFixed(4)} unit=\"J\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Live kinetic E\" value={liveEnergy.ke.toFixed(4)} unit=\"J\" color=\"text-rose-500\" />\n                  <StatRow label=\"Live potential E\" value={liveEnergy.pe.toFixed(4)} unit=\"J\" color=\"text-blue-500\" />\n                  <StatRow label=\"Live total E\" value={liveEnergy.total.toFixed(4)} unit=\"J\" color=\"text-emerald-600\" />\n                  <StatRow label=\"x₁\" value={liveState.x1.toFixed(3)} unit=\"m\" color=\"text-purple-600\" />\n                  <StatRow label=\"x₂\" value={liveState.x2.toFixed(3)} unit=\"m\" color=\"text-amber-600\" />\n                  <StatRow label=\"v₁\" value={liveState.v1.toFixed(2)} unit=\"m/s\" color=\"text-indigo-500\" />\n                  <StatRow label=\"v₂\" value={liveState.v2.toFixed(2)} unit=\"m/s\" color=\"text-amber-500\" />\n                  <StatRow label=\"Q factor\" value={qDisplay} unit=\"\" color=\"text-pink-600\" />\n                  <StatRow label=\"Bandwidth\" value={bwDisplay} unit=\"rad/s\" color=\"text-cyan-600\" />\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Damping curve</p>\n                <DampingCurve history={chartHistory} />\n                <p className=\"text-[10px] text-gray-400 mt-1.5 leading-relaxed\">\n                  Log-energy vs time. A straight line confirms exponential decay (linear damping).\n                </p>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/ohms-law/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef, useMemo } from 'react';\nimport { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Label, ReferenceDot, Legend } from 'recharts';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { CircuitCanvas, CircuitMode, FlowDisplay } from '@/components/simulation/CircuitCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport {\n  ohmCurrent, seriesAnalysis, parallelAnalysis, ivLine,\n  nonOhmicCalibration, nonOhmicIVLine, nonOhmicCurrent, NonOhmicDevice,\n} from '@/lib/physics/circuits';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<CircuitMode, { title: string; icon: string; sub: string; eq: string }> = {\n  ohm:        { title: \"Ohm's law\",      icon: '⚡', sub: 'Single resistor',            eq: 'V = IR' },\n  series:     { title: 'Series',         icon: '🔗', sub: 'Same current, voltages add', eq: 'R = R₁+R₂+R₃' },\n  parallel:   { title: 'Parallel',       icon: '🪜', sub: 'Same voltage, currents add', eq: '1/R = 1/R₁+1/R₂+1/R₃' },\n  'non-ohmic': { title: 'Non-ohmic',     icon: '📉', sub: 'V = IR does NOT hold',       eq: 'I ≠ kV' },\n};\n\nconst TEACHER_NOTES: Record<CircuitMode, string[]> = {\n  ohm: [\n    'V = IR only holds for OHMIC conductors — the I–V graph is a straight line through the origin whose slope is 1/R.',\n    'The carrier animation shows drift speed ∝ current: double the voltage, double the speed.',\n    'Conventional current flows + → −, but the electrons physically drift the opposite way — try the flow-direction toggle to see both.',\n    'Power dissipated P = VI = I²R = V²/R — a resistor converts electrical energy to heat.',\n    'Try the sliders on the I–V graph: the operating point always sits on the line for a fixed R.',\n  ],\n  series: [\n    'The SAME current flows through every component — there is only one path.',\n    'Voltages divide in proportion to resistance: V₁/V₂ = R₁/R₂ (the potential divider).',\n    'Total resistance is always LARGER than the largest single resistor.',\n    'One broken component breaks the whole circuit — why old fairy lights all went out together.',\n    'Check: the three voltage drops on the canvas always sum to the supply voltage.',\n  ],\n  parallel: [\n    'Every branch gets the FULL supply voltage; the currents divide instead.',\n    'The current divider: the SMALLEST resistance takes the LARGEST current, and the LARGEST resistance takes the smallest — watch both the electron speed AND how many dots are moving in each branch.',\n    'Total resistance is always SMALLER than the smallest single resistor.',\n    'House wiring is parallel: every appliance gets mains voltage, and one failing does not kill the rest.',\n    'Check: branch currents on the canvas always sum to the total from the battery.',\n  ],\n  'non-ohmic': [\n    'A NON-OHMIC conductor does NOT obey V = IR with a constant R — its I–V graph is curved, not a straight line, because its resistance itself changes as current flows.',\n    'Filament lamp: as current flows, the filament heats up and its resistance RISES — so current grows more SLOWLY than voltage at higher V (the curve bends toward the V-axis, concave down).',\n    'Thermistor (NTC — negative temperature coefficient): the opposite happens — resistance FALLS as it heats, so current grows FASTER than voltage at higher V (concave up).',\n    'Diode: current is essentially ZERO below a threshold voltage (~0.6-0.7V for silicon), then rises very steeply — a diode only conducts easily in ONE direction, which is exactly why it is used to convert AC to DC.',\n    'Undergraduate note: these curves are simplified, always-well-behaved teaching models chosen to show the correct QUALITATIVE shape (concave up/down, or a sharp threshold) rather than an exact material-specific derivation — a real filament\\u2019s resistance-vs-temperature relationship and a real diode\\u2019s reverse-bias behaviour are each their own, more detailed topics.',\n  ],\n};\n\nconst EXERCISES: Record<CircuitMode, { q: string; a: string }[]> = {\n  ohm: [\n    { q: 'A 12V battery drives a current of 3A through a resistor. Find R and the power dissipated.', a: 'R=V/I=12/3=4Ω. P=VI=12×3=36W.' },\n    { q: 'The I–V graph of a conductor is a straight line of slope 0.25 A/V. Find its resistance.', a: 'Slope = 1/R → R = 1/0.25 = 4Ω.' },\n    { q: 'An electric kettle rated 2000W runs on 230V mains. Find the current and its resistance.', a: 'I=P/V=2000/230≈8.7A. R=V/I=230/8.7≈26.4Ω.' },\n  ],\n  series: [\n    { q: 'R₁=2Ω, R₂=3Ω, R₃=5Ω in series with a 20V battery. Find the current and V across R₂.', a: 'R=10Ω. I=20/10=2A. V₂=IR₂=2×3=6V.' },\n    { q: 'Two resistors in series carry 0.5A. If V₁=3V and the supply is 9V, find R₂.', a: 'V₂=9−3=6V. R₂=V₂/I=6/0.5=12Ω.' },\n    { q: 'Why does adding a resistor in series always reduce the current?', a: 'Total R increases (R = ΣRᵢ), and I = V/R with fixed V, so I falls.' },\n  ],\n  parallel: [\n    { q: 'R₁=6Ω and R₂=3Ω in parallel across 12V. Find each branch current and the total.', a: 'I₁=12/6=2A, I₂=12/3=4A. Total I=6A (and R=2Ω checks: 12/2=6A).' },\n    { q: 'Find the combined resistance of 4Ω, 6Ω and 12Ω in parallel.', a: '1/R=1/4+1/6+1/12=3/12+2/12+1/12=6/12 → R=2Ω.' },\n    { q: 'Two equal resistors R in parallel — what is the combined resistance?', a: 'R/2. Equal resistors in parallel halve the resistance.' },\n  ],\n  'non-ohmic': [\n    { q: 'A filament lamp and a fixed resistor have the same resistance at their normal operating voltage. At a LOWER voltage, which passes more current?', a: 'The filament lamp — its resistance is lower when cold (not yet heated by the current), so at a lower voltage it briefly behaves like a smaller resistor than the fixed one it was compared to.' },\n    { q: 'A silicon diode has almost zero current until about 0.6V, then rises steeply. What circuit-level use does this threshold behaviour enable?', a: 'It lets the diode act as a one-way valve for current (rectification) and as a way to fix a nearly-constant voltage drop across it once conducting — both used throughout electronics, e.g. converting AC to DC.' },\n    { q: 'Why can\\u2019t a single fixed value of R describe a non-ohmic conductor across its whole I–V graph?', a: 'Because its resistance (V/I at each point) genuinely CHANGES as the operating point moves along the curve — R is only a true constant for a straight-line, ohmic I–V graph through the origin.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\n// I–V characteristic with the live operating point sitting ON the line.\nfunction IVGraph({ R, V }: { R: number; V: number }) {\n  const vMax = 24;\n  const data = useMemo(() => ivLine(R, vMax), [R]);\n  const I = ohmCurrent(V, R);\n  return (\n    <ResponsiveContainer width=\"100%\" height={190}>\n      <LineChart data={data} margin={{ top: 8, right: 16, left: 10, bottom: 28 }}>\n        <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n        <XAxis dataKey=\"v\" type=\"number\" tick={{ fontSize: 10 }} domain={[0, vMax]}>\n          <Label value=\"Voltage V (V)\" position=\"insideBottom\" offset={-16} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </XAxis>\n        <YAxis tick={{ fontSize: 10 }}>\n          <Label value=\"Current I (A)\" angle={-90} position=\"insideLeft\" offset={12} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </YAxis>\n        <Tooltip formatter={(v: unknown) => [Number(v).toFixed(3) + ' A']} labelFormatter={v => `V=${v}V`} />\n        <Line type=\"monotone\" dataKey=\"i\" stroke=\"#6366f1\" strokeWidth={2} dot={false} />\n        <ReferenceDot x={V} y={I} r={6} fill=\"#ef4444\" stroke=\"#fff\" strokeWidth={2} />\n      </LineChart>\n    </ResponsiveContainer>\n  );\n}\n\n// Non-ohmic comparison graph: the selected device's curve alongside a\n// straight ohmic reference line, so the curvature (or sharp threshold)\n// is immediately visible against a known-linear baseline.\nfunction NonOhmicGraph({ device, refR, V }: { device: NonOhmicDevice; refR: number; V: number }) {\n  const vMax = device === 'diode' ? 1 : 24;\n  const { cLamp, cTherm } = useMemo(() => nonOhmicCalibration(refR, 12), [refR]);\n  const ohmicData = useMemo(() => ivLine(refR, vMax), [refR, vMax]);\n  const deviceData = useMemo(() => nonOhmicIVLine(device, vMax, cLamp, cTherm), [device, vMax, cLamp, cTherm]);\n  const merged = ohmicData.map((d, i) => ({ v: d.v, ohmic: d.i, device: deviceData[i]?.i ?? 0 }));\n  const I = nonOhmicCurrent(device, Math.min(V, vMax), cLamp, cTherm);\n  const deviceLabel = device === 'filament' ? 'Filament lamp' : device === 'diode' ? 'Diode' : 'Thermistor';\n  return (\n    <ResponsiveContainer width=\"100%\" height={210}>\n      <LineChart data={merged} margin={{ top: 8, right: 16, left: 10, bottom: 28 }}>\n        <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n        <XAxis dataKey=\"v\" type=\"number\" tick={{ fontSize: 10 }} domain={[0, vMax]}>\n          <Label value=\"Voltage V (V)\" position=\"insideBottom\" offset={-16} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </XAxis>\n        <YAxis tick={{ fontSize: 10 }}>\n          <Label value=\"Current I (A)\" angle={-90} position=\"insideLeft\" offset={12} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </YAxis>\n        <Tooltip formatter={(v: unknown) => [Number(v).toFixed(4) + ' A']} labelFormatter={v => `V=${v}V`} />\n        <Legend wrapperStyle={{ fontSize: 10 }} />\n        <Line type=\"monotone\" dataKey=\"ohmic\" name=\"Ohmic (fixed R)\" stroke=\"#94a3b8\" strokeWidth={1.5} strokeDasharray=\"4 3\" dot={false} />\n        <Line type=\"monotone\" dataKey=\"device\" name={deviceLabel} stroke=\"#dc2626\" strokeWidth={2.2} dot={false} />\n        <ReferenceDot x={Math.min(V, vMax)} y={I} r={6} fill=\"#dc2626\" stroke=\"#fff\" strokeWidth={2} />\n      </LineChart>\n    </ResponsiveContainer>\n  );\n}\n\nexport default function OhmsLawPage() {\n  const [mode, setMode] = useState<CircuitMode>('ohm');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n  const [showParams, setShowParams] = useState(true);\n  const [showTeacherNotes, setShowTeacherNotes] = useState(false);\n\n  const [V, setV] = useState(12);\n  const [r1, setR1] = useState(4);\n  const [r2, setR2] = useState(6);\n  const [r3, setR3] = useState(12);\n  const [nonOhmicDevice, setNonOhmicDevice] = useState<NonOhmicDevice>('filament');\n  const [flowDisplay, setFlowDisplay] = useState<FlowDisplay>('electron');\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1);\n  }, []);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [mode, V, r1, r2, r3, nonOhmicDevice, flowDisplay, reset]);\n\n  const ser = seriesAnalysis(V, [r1, r2, r3]);\n  const par = parallelAnalysis(V, [r1, r2, r3]);\n  const I1 = ohmCurrent(V, r1);\n  const { cLamp, cTherm } = nonOhmicCalibration(r1, 12);\n  const Inon = nonOhmicCurrent(nonOhmicDevice, mode === 'non-ohmic' && nonOhmicDevice === 'diode' ? Math.min(V, 1) : V, cLamp, cTherm);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 300, 980);\n\n  useTopicPreset(\"simulations-ohms-law\", { \"V\": setV,\n    \"r1\": setR1,\n    \"r2\": setR2,\n    \"r3\": setR3 }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Electricity</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Ohm&apos;s law &amp; circuits</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as CircuitMode[]).map(m => (\n              <button key={m} onClick={() => { setMode(m); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span><span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{MODE_META[mode].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{MODE_META[mode].eq}</span>\n            {mode !== 'non-ohmic' && <span className=\"text-xs text-gray-400 ml-2\">P = VI = I²R = V²/R</span>}\n          </div>\n\n          <SimulationStage className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <div data-stage-role=\"canvas\" className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <CircuitCanvas key={resetKey} mode={mode} voltage={V} r1={r1} r2={r2} r3={r3}\n                  nonOhmicDevice={nonOhmicDevice} flowDisplay={flowDisplay}\n                  isRunning={isRunning} isPaused={isPaused} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <div className=\"flex items-center gap-2 flex-wrap\">\n                  <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                    onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                    onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                  <div className=\"flex rounded-lg border border-gray-200 overflow-hidden\">\n                    {(['electron', 'conventional'] as const).map(f => (\n                      <button key={f} onClick={() => setFlowDisplay(f)}\n                        className={`px-2.5 py-2 text-xs font-medium transition ${\n                          flowDisplay === f ? 'bg-indigo-50 text-indigo-700' : 'bg-white text-gray-500 hover:bg-gray-50'\n                        }`}>{f === 'electron' ? '● Electron flow' : '▶ Conventional I'}</button>\n                    ))}\n                  </div>\n                </div>\n                <EmbedButton path=\"/embed/circuits\"\n                  title={`${MODE_META[mode].title} — A-Factor STEM Studio`}\n                  params={{ mode, V, r1, r2, r3 }} />\n              </div>\n\n              <div data-stage-role=\"extra\">{mode === 'ohm' && (\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">I–V characteristic</p>\n                  <IVGraph R={r1} V={V} />\n                  <p className=\"text-[10px] text-gray-400 mt-2 text-center\">\n                    Straight line through the origin — the red dot is the current operating point (slope = 1/R)\n                  </p>\n                </div>\n              )}</div>\n\n              <div data-stage-role=\"parameters\">{mode === 'non-ohmic' && (\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <div className=\"flex items-center justify-between mb-2\">\n                    <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">I–V characteristic</p>\n                    <div className=\"flex gap-1\">\n                      {(['filament', 'thermistor', 'diode'] as const).map(d => (\n                        <button key={d} onClick={() => setNonOhmicDevice(d)}\n                          className={`px-2 py-1 rounded-md text-[10px] font-medium capitalize transition ${\n                            nonOhmicDevice === d ? 'bg-indigo-100 text-indigo-700' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'\n                          }`}>{d}</button>\n                      ))}\n                    </div>\n                  </div>\n                  <NonOhmicGraph device={nonOhmicDevice} refR={r1} V={V} />\n                  <p className=\"text-[10px] text-gray-400 mt-2 text-center\">\n                    Red curve = the non-ohmic device; grey dashed line = an ohmic resistor for comparison — same R at V=12V\n                  </p>\n                </div>\n              )}</div>\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {mode === 'ohm' && <>\n                    <StatRow label=\"Current I\" value={I1.toFixed(3)} unit=\"A\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Power P\" value={(V * I1).toFixed(2)} unit=\"W\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Charge in 60s\" value={(I1 * 60).toFixed(1)} unit=\"C\" color=\"text-amber-600\" />\n                    <StatRow label=\"Energy in 60s\" value={(V * I1 * 60).toFixed(0)} unit=\"J\" color=\"text-rose-500\" />\n                  </>}\n                  {mode === 'series' && <>\n                    <StatRow label=\"Total R\" value={ser.Rtotal.toFixed(1)} unit=\"Ω\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Current I\" value={ser.I.toFixed(3)} unit=\"A\" color=\"text-emerald-600\" />\n                    <StatRow label=\"V across R₁\" value={ser.drops[0].toFixed(2)} unit=\"V\" color=\"text-amber-600\" />\n                    <StatRow label=\"V across R₂\" value={ser.drops[1].toFixed(2)} unit=\"V\" color=\"text-rose-500\" />\n                    <StatRow label=\"V across R₃\" value={ser.drops[2].toFixed(2)} unit=\"V\" color=\"text-purple-600\" />\n                    <StatRow label=\"Total power\" value={ser.Ptotal.toFixed(2)} unit=\"W\" color=\"text-gray-600\" />\n                  </>}\n                  {mode === 'parallel' && <>\n                    <StatRow label=\"Total R\" value={par.Rtotal.toFixed(2)} unit=\"Ω\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Total current\" value={par.I.toFixed(3)} unit=\"A\" color=\"text-emerald-600\" />\n                    <StatRow label=\"I through R₁\" value={par.branches[0].toFixed(3)} unit=\"A\" color=\"text-amber-600\" />\n                    <StatRow label=\"I through R₂\" value={par.branches[1].toFixed(3)} unit=\"A\" color=\"text-rose-500\" />\n                    <StatRow label=\"I through R₃\" value={par.branches[2].toFixed(3)} unit=\"A\" color=\"text-purple-600\" />\n                    <StatRow label=\"Total power\" value={par.Ptotal.toFixed(2)} unit=\"W\" color=\"text-gray-600\" />\n                  </>}\n                  {mode === 'non-ohmic' && <>\n                    <StatRow label=\"Device\" value={nonOhmicDevice} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Current at this V\" value={(Inon * (nonOhmicDevice === 'diode' ? 1000 : 1)).toFixed(nonOhmicDevice === 'diode' ? 3 : 3)} unit={nonOhmicDevice === 'diode' ? 'mA' : 'A'} color=\"text-emerald-600\" />\n                    <StatRow label=\"Apparent R (V/I)\" value={Inon > 0.0001 ? (Math.min(V, nonOhmicDevice === 'diode' ? 1 : V) / Inon).toFixed(1) : '∞'} unit=\"Ω\" color=\"text-amber-600\" />\n                    <StatRow label=\"Obeys V=IR?\" value=\"NO\" unit=\"(R not constant)\" color=\"text-rose-500\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <div className=\"flex items-center justify-between\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                  <button onClick={() => setShowParams(p => !p)}\n                    className=\"text-xs font-medium text-indigo-600 hover:text-indigo-700 flex items-center gap-1\">\n                    {showParams ? 'Hide' : 'Show'}\n                    <span className={`transition-transform ${showParams ? 'rotate-180' : ''}`}>▾</span>\n                  </button>\n                </div>\n                {showParams && <>\n                  <Slider label=\"Supply voltage\" unit=\"V\" value={V} min={1} max={24} step={0.5} set={setV} color=\"#6366f1\" />\n                  {mode !== 'non-ohmic' && (\n                    <Slider label={mode === 'ohm' ? 'Resistance R' : 'R₁'} unit=\"Ω\" value={r1} min={1} max={50} step={1} set={setR1} color=\"#f59e0b\" />\n                  )}\n                  {mode === 'non-ohmic' && (\n                    <Slider label=\"Reference R (for comparison)\" unit=\"Ω\" value={r1} min={1} max={50} step={1} set={setR1} color=\"#f59e0b\" />\n                  )}\n                  {(mode === 'series' || mode === 'parallel') && <>\n                    <Slider label=\"R₂\" unit=\"Ω\" value={r2} min={1} max={50} step={1} set={setR2} color=\"#10b981\" />\n                    <Slider label=\"R₃\" unit=\"Ω\" value={r3} min={1} max={50} step={1} set={setR3} color=\"#8b5cf6\" />\n                  </>}\n                </>}\n              </div>\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <div className=\"flex items-center justify-between mb-3\">\n                  <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide\">📋 Teacher notes</p>\n                  <button onClick={() => setShowTeacherNotes(p => !p)}\n                    className=\"text-xs font-medium text-amber-700 hover:text-amber-800 flex items-center gap-1\">\n                    {showTeacherNotes ? 'Hide' : 'Show'}\n                    <span className={`transition-transform ${showTeacherNotes ? 'rotate-180' : ''}`}>▾</span>\n                  </button>\n                </div>\n                {showTeacherNotes && (\n                  <ul className=\"space-y-2\">\n                    {TEACHER_NOTES[mode].map((n, i) => (\n                      <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                        <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                      </li>\n                    ))}\n                  </ul>\n                )}\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/elasticity/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useMemo, useRef, useCallback, useEffect } from 'react';\nimport { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Label, ReferenceDot, ReferenceLine } from 'recharts';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { ElasticityCanvas, ElasticityMode } from '@/components/simulation/ElasticityCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { extension, springEnergy, forceExtensionCurve, wireExtension, stress, strain, youngModulus, WIRE_MATERIALS } from '@/lib/physics/elasticity';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<ElasticityMode, { title: string; icon: string; sub: string; eq: string }> = {\n  hooke: { title: \"Hooke's law\", icon: '🌀', sub: 'A loaded spring',       eq: 'F = ke' },\n  wire:  { title: 'Young modulus', icon: '🧵', sub: 'Stretching a wire', eq: 'E = σ/ε = FL/(Ae)' },\n};\n\nconst TEACHER_NOTES: Record<ElasticityMode, string[]> = {\n  hooke: [\n    \"Hooke's law: extension is directly proportional to the applied force, e ∝ F, i.e. F = ke — but only up to the ELASTIC LIMIT.\",\n    'Beyond the elastic limit the spring deforms PERMANENTLY: it will not return to its natural length when the load is removed, and F = ke no longer applies.',\n    'The spring constant k (N/m) measures stiffness: a bigger k means a stiffer spring that stretches less for the same force.',\n    'Energy stored in a stretched (or compressed) spring: E = ½Fe = ½ke² — the area under a force–extension graph, used in catapults, archery bows, and pogo sticks.',\n    'Springs in series share the load but each stretches independently (softer overall); springs in parallel share the extension (stiffer overall) — a nice follow-up demonstration.',\n  ],\n  wire: [\n    'Stress σ = F/A (force per unit cross-sectional area) and strain ε = e/L (extension per unit original length) — both are needed because a thick wire stretches less than a thin one under the same force.',\n    \"Young's modulus E = σ/ε is a property of the MATERIAL only — steel always has the same E, whatever the wire's length or thickness.\",\n    'Real wire extensions under normal loads are tiny (often fractions of a millimetre) — this simulation magnifies the extension so you can see it; the true value is always shown in the info card.',\n    'A stress–strain graph for a ductile material (like copper) shows a straight (Hookean) region, then plastic deformation, then a breaking point — steel and glass behave very differently here.',\n    'Practical use: engineers select materials by their E value — steel cables for bridges need high E (stiff, minimal sag) while rubber seals need low E (flexible).',\n  ],\n};\n\nconst EXERCISES: Record<ElasticityMode, { q: string; a: string }[]> = {\n  hooke: [\n    { q: 'A spring stretches 4cm under a 20N load. Find its spring constant k.', a: 'k = F/e = 20/0.04 = 500 N/m.' },\n    { q: 'A spring of k=250 N/m is stretched by 6cm. Find the elastic energy stored.', a: 'E = ½ke² = ½×250×0.06² = 0.45 J.' },\n    { q: 'A spring obeys Hooke\\'s law up to 30N, extending 10cm at that load. What extension would 45N (beyond the limit) roughly NOT follow, and why?', a: 'It would NOT simply extend to 15cm proportionally — beyond the elastic limit the material deforms plastically and extension grows faster than F for a given increase in load, and the deformation becomes permanent.' },\n  ],\n  wire: [\n    { q: 'A steel wire (E=200 GPa) of length 2m and cross-sectional area 1×10⁻⁶ m² carries a 100N load. Find its extension.', a: 'e = FL/(AE) = (100×2)/(1e-6×200e9) = 200/200000 = 1×10⁻³ m = 1mm.' },\n    { q: 'A wire of diameter 0.5mm stretches 0.8mm under a 50N load over 1.5m. Find the stress and strain.', a: 'A=π(0.00025)²≈1.96×10⁻⁷m². σ=F/A=50/1.96e-7≈2.55×10⁸ Pa. ε=e/L=0.0008/1.5≈5.33×10⁻⁴.' },\n    { q: 'Using the previous answer, find the Young\\'s modulus.', a: 'E=σ/ε=2.55×10⁸/5.33×10⁻⁴≈4.78×10¹¹ Pa ≈ 478 GPa.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nfunction ForceExtensionGraph({ k, elasticLimitF, load }: { k: number; elasticLimitF: number; load: number }) {\n  const fMax = elasticLimitF * 2.2;\n  const data = useMemo(() => forceExtensionCurve(k, elasticLimitF, fMax), [k, elasticLimitF, fMax]);\n  const e = extension(Math.min(load, elasticLimitF), k) * 100;\n  const eLimitCm = (elasticLimitF / k) * 100;\n  return (\n    <ResponsiveContainer width=\"100%\" height={190}>\n      <LineChart data={data} margin={{ top: 8, right: 16, left: 10, bottom: 28 }}>\n        <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n        <XAxis dataKey=\"e\" type=\"number\" tick={{ fontSize: 10 }}>\n          <Label value=\"Extension e (cm)\" position=\"insideBottom\" offset={-16} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </XAxis>\n        <YAxis dataKey=\"F\" tick={{ fontSize: 10 }}>\n          <Label value=\"Force F (N)\" angle={-90} position=\"insideLeft\" offset={12} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </YAxis>\n        <Tooltip formatter={(v: unknown) => [Number(v).toFixed(2) + ' N', 'F']} labelFormatter={e => `e=${Number(e).toFixed(2)}cm`} />\n        <Line type=\"linear\" dataKey=\"F\" stroke=\"#6366f1\" strokeWidth={2} dot={false} isAnimationActive={false} />\n        <ReferenceLine x={eLimitCm} stroke=\"#f59e0b\" strokeDasharray=\"4 4\"\n          label={{ value: 'elastic limit', position: 'top', fontSize: 9, fill: '#d97706' }} />\n        <ReferenceDot x={e} y={Math.min(load, elasticLimitF)} r={6} fill=\"#ef4444\" stroke=\"#fff\" strokeWidth={2} />\n      </LineChart>\n    </ResponsiveContainer>\n  );\n}\n\nexport default function ElasticityPage() {\n  const [mode, setMode] = useState<ElasticityMode>('hooke');\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [load, setLoad] = useState(8);\n  const [k, setK] = useState(200);\n  const [elasticLimitF, setElasticLimitF] = useState(15);\n\n  const [wireLength, setWireLength] = useState(2);\n  const [wireDiamMm, setWireDiamMm] = useState(0.5);\n  const [matIdx, setMatIdx] = useState(0);\n  const [wireLoad, setWireLoad] = useState(60);\n  const material = WIRE_MATERIALS[matIdx];\n\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [unloadKey, setUnloadKey] = useState(0);\n  const [settled, setSettled] = useState(false);\n  const [broken, setBroken] = useState(false);\n\n  const A = Math.PI * Math.pow((wireDiamMm / 1000) / 2, 2);\n  const e = wireExtension(wireLoad, wireLength, A, material.E);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setSettled(false); setBroken(false);\n  }, []);\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, load, k, elasticLimitF, wireLength, wireDiamMm, matIdx, wireLoad, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 320, 980);\n\n  useTopicPreset(\"simulations-elasticity\", { \"load\": setLoad,\n    \"k\": setK,\n    \"elasticLimitF\": setElasticLimitF,\n    \"wireLoad\": setWireLoad,\n    \"wireLength\": setWireLength,\n    \"wireDiamMm\": setWireDiamMm }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Mechanics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Elasticity</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as ElasticityMode[]).map(m => (\n              <button key={m} onClick={() => { setMode(m); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span><span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{MODE_META[mode].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{MODE_META[mode].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <ElasticityCanvas key={resetKey} mode={mode}\n                  load={mode === 'hooke' ? load : wireLoad} k={k} elasticLimitF={elasticLimitF}\n                  wireLength={wireLength} wireDiamMm={wireDiamMm} youngE={material.E} materialName={material.name}\n                  breakingStressMPa={material.breakingStressMPa}\n                  isRunning={isRunning} isPaused={isPaused} unloadKey={unloadKey}\n                  onSettled={() => setSettled(true)} onBroken={() => setBroken(true)}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                {mode === 'hooke' && settled && (\n                  <button onClick={() => { setUnloadKey(k => k + 1); setSettled(false); }}\n                    className=\"rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-600 transition hover:bg-gray-50\">\n                    Remove load\n                  </button>\n                )}\n                {mode === 'wire' && broken && (\n                  <span className=\"text-xs font-medium text-red-600\">💥 Snapped — Reset to try again</span>\n                )}\n              </div>\n\n              <div data-stage-role=\"extra\" className=\"flex justify-end\">\n                <EmbedButton path=\"/embed/elasticity\"\n                  title={`${MODE_META[mode].title} — A-Factor STEM Studio`}\n                  params={mode === 'hooke' ? { mode, load, k, limit: elasticLimitF } : { mode, mat: matIdx, L: wireLength, d: wireDiamMm, F: wireLoad }} />\n              </div>\n\n              <div data-stage-role=\"extra\">{mode === 'hooke' && (\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Force–extension graph</p>\n                  <ForceExtensionGraph k={k} elasticLimitF={elasticLimitF} load={load} />\n                  <p className=\"text-[10px] text-gray-400 mt-2 text-center\">\n                    Linear (Hooke) region, then plastic deformation beyond the elastic limit\n                  </p>\n                </div>\n              )}</div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                {mode === 'hooke' && <>\n                  <Slider label=\"Load F\" unit=\"N\" value={load} min={0} max={30} step={0.5} set={setLoad} color=\"#6366f1\" />\n                  <Slider label=\"Spring constant k\" unit=\"N/m\" value={k} min={50} max={500} step={10} set={setK} color=\"#f59e0b\" />\n                  <Slider label=\"Elastic limit\" unit=\"N\" value={elasticLimitF} min={5} max={25} step={1} set={setElasticLimitF} color=\"#ef4444\" />\n                </>}\n                {mode === 'wire' && <>\n                  <div className=\"flex flex-wrap gap-1.5\">\n                    {WIRE_MATERIALS.map((m, i) => (\n                      <button key={m.name} onClick={() => setMatIdx(i)}\n                        className={`rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n                          matIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'\n                        }`}>{m.name}</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Load F\" unit=\"N\" value={wireLoad} min={5} max={200} step={5} set={setWireLoad} color=\"#6366f1\" />\n                  <Slider label=\"Wire length L\" unit=\"m\" value={wireLength} min={0.5} max={5} step={0.1} set={setWireLength} color=\"#10b981\" />\n                  <Slider label=\"Wire diameter\" unit=\"mm\" value={wireDiamMm} min={0.1} max={2} step={0.05} set={setWireDiamMm} color=\"#8b5cf6\" />\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {mode === 'hooke' && <>\n                    <StatRow label=\"Extension e\" value={(extension(Math.min(load, elasticLimitF), k) * 100).toFixed(2)} unit=\"cm\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Energy stored\" value={springEnergy(k, extension(Math.min(load, elasticLimitF), k)).toFixed(3)} unit=\"J\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Within limit?\" value={load <= elasticLimitF ? 'yes' : 'NO — plastic'} unit=\"\" color=\"text-amber-600\" />\n                  </>}\n                  {mode === 'wire' && <>\n                    <StatRow label=\"Cross-section A\" value={(A * 1e6).toFixed(4)} unit=\"mm²\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Stress σ\" value={(stress(wireLoad, A) / 1e6).toFixed(1)} unit=\"MPa\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Strain ε\" value={strain(e, wireLength).toExponential(2)} unit=\"\" color=\"text-amber-600\" />\n                    <StatRow label=\"Extension e\" value={(e * 1000).toFixed(3)} unit=\"mm\" color=\"text-rose-500\" />\n                    <StatRow label=\"Young modulus\" value={(youngModulus(wireLoad, A, e, wireLength) / 1e9).toFixed(0)} unit=\"GPa\" color=\"text-purple-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[mode].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/electromagnetic-induction/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { InductionCanvas, InductionMode } from '@/components/simulation/InductionCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { generatorPeakEmf, rmsFromPeak, transformerSecondaryVoltage, transformerSecondaryCurrent } from '@/lib/physics/electromagnetism';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\ntype Topic = 'faraday-lenz' | 'ac-generator' | 'transformer';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB', 'Undergraduate'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700', Undergraduate: 'bg-slate-200 text-slate-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; eq: string }> = {\n  'faraday-lenz': { title: \"Faraday's & Lenz's Law\", icon: '🧲', sub: 'Moving magnet induces EMF', eq: 'EMF = -N dΦ/dt' },\n  'ac-generator': { title: 'AC Generator',            icon: '🔄', sub: 'Rotating coil in a field',  eq: 'e = NBAω sin(ωt)' },\n  transformer:    { title: 'Transformer',              icon: '🔌', sub: 'Changing flux, linked coils', eq: 'Vs/Vp = Ns/Np' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  'faraday-lenz': [\n    \"Faraday's law: an EMF is induced in a circuit whenever the magnetic flux linking it CHANGES — no change, no EMF, even if the field itself is strong.\",\n    'The size of the induced EMF depends on the RATE of change of flux — move the magnet faster, or use more turns, and the galvanometer deflects further.',\n    \"Lenz's law gives the DIRECTION: the induced current always flows to OPPOSE the change that created it. An approaching magnet induces a current that makes the coil repel it; a receding magnet induces a current that makes the coil attract it back.\",\n    \"Lenz's law is really a statement of energy conservation — if the induced current instead ASSISTED the motion, you'd get free energy from nothing, which is impossible. The opposing force is exactly why you feel resistance pushing a magnet into a coil.\",\n    'Undergraduate note: EMF = -N dΦ/dt is Faraday\\u2019s law in its general (integral) form; the minus sign IS Lenz\\u2019s law, encoded directly into the equation rather than argued separately.',\n  ],\n  'ac-generator': [\n    'An AC generator converts mechanical rotation into electrical energy by rotating a coil inside a magnetic field (or, equivalently, rotating the magnet around a fixed coil).',\n    'The output is sinusoidal: e = e₀sin(ωt), because the RATE at which the coil cuts field lines varies smoothly as it turns — fastest when the coil plane is parallel to the field, zero for an instant when it is perpendicular.',\n    'Peak EMF e₀ = NBAω — more turns, a stronger field, a bigger coil, or spinning faster all increase the output.',\n    'Slip rings (continuous contact) let an AC generator deliver alternating current to an external circuit; a DC generator instead uses a split-ring commutator to reverse the connections every half turn, converting the output to a bumpy one-directional DC.',\n    'Undergraduate note: RMS values (used for practical AC ratings, e.g. \"230V mains\") are e₀/√2 — the DC-equivalent value that would deliver the same average power, since a sine wave\\u2019s average power is half its peak power.',\n  ],\n  transformer: [\n    'A transformer uses electromagnetic induction to change AC voltage: an alternating current in the primary coil creates a constantly CHANGING flux in the shared iron core, which induces an EMF in the secondary coil.',\n    'Ideal transformer equation: Vs/Vp = Ns/Np — more turns on the secondary than the primary steps the voltage UP; fewer turns steps it DOWN.',\n    'A transformer only works on AC — a steady DC current produces a constant (non-changing) flux, so no EMF is induced in the secondary at all.',\n    'Power is conserved in an ideal transformer (VpIp = VsIs), so stepping voltage UP necessarily steps current DOWN by the same factor, and vice versa — a transformer cannot create extra power.',\n    'Undergraduate note: real transformers lose some energy to resistive heating in the windings and to hysteresis/eddy-current losses in the core — laminating the core (thin insulated sheets instead of one solid block) is specifically to reduce eddy-current losses.',\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  'faraday-lenz': [\n    { q: 'A magnet is pushed INTO a coil, north pole first. What pole does the coil face present toward the magnet, and why?', a: 'By Lenz\\u2019s law, the coil opposes the increasing flux by presenting a NORTH pole toward the approaching magnet — like poles repel, resisting the push.' },\n    { q: 'The same magnet is now pulled OUT of the coil. How does the induced current direction compare to when it was pushed in?', a: 'It reverses — the coil now presents a SOUTH pole to attract the receding magnet and oppose its departure, meaning the current flows in the opposite direction around the coil.' },\n    { q: 'Why is there no induced EMF when the magnet is held stationary inside the coil?', a: 'Flux is only changing while there is RELATIVE MOTION between the magnet and coil — a stationary magnet produces a constant flux, and dΦ/dt = 0 means no induced EMF.' },\n  ],\n  'ac-generator': [\n    { q: 'A generator coil of 200 turns, area 0.03m², spins at 60 rad/s in a 0.4T field. Find the peak EMF.', a: 'e₀ = NBAω = 200×0.4×0.03×60 = 144 V.' },\n    { q: 'At what point in the rotation is the induced EMF exactly zero, and why?', a: 'When the coil plane is perpendicular to the field (the coil face pointing directly along the field lines) — at that instant the coil sides are momentarily moving PARALLEL to the field, cutting no field lines at all.' },\n    { q: 'A generator\\u2019s peak EMF is 340V. Find the RMS voltage (the value you would measure with a standard AC voltmeter).', a: 'RMS = peak/√2 = 340/1.414 ≈ 240V — very close to the UK/Nigeria mains RMS voltage.' },\n  ],\n  transformer: [\n    { q: 'A step-down transformer has 1000 turns on the primary and 50 on the secondary, with 240V AC input. Find the output voltage.', a: 'Vs = Vp×(Ns/Np) = 240×(50/1000) = 12 V.' },\n    { q: 'The same transformer draws a primary current of 0.5A. Find the secondary current (assume 100% efficiency).', a: 'Power is conserved: VpIp = VsIs, so Is = VpIp/Vs = (240×0.5)/12 = 10 A.' },\n    { q: 'Why won\\u2019t a transformer work if you connect its primary to a battery (DC) instead of AC?', a: 'A steady DC current produces a constant magnetic flux in the core. Since Faraday\\u2019s law requires a CHANGING flux to induce an EMF, a constant flux induces nothing in the secondary — except for the brief instants the DC is switched on or off.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function ElectromagneticInductionPage() {\n  const [topic, setTopic] = useState<Topic>('faraday-lenz');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [turns, setTurns] = useState(8);\n  const [speed, setSpeed] = useState(2);\n  const [magnetPoleOut, setMagnetPoleOut] = useState(true);\n\n  const [genTurns, setGenTurns] = useState(50);\n  const [genFieldB, setGenFieldB] = useState(0.3);\n  const [genArea, setGenArea] = useState(0.02);\n  const [genOmega, setGenOmega] = useState(3);\n\n  const [primaryTurns, setPrimaryTurns] = useState(500);\n  const [secondaryTurns, setSecondaryTurns] = useState(100);\n  const [primaryVoltage, setPrimaryVoltage] = useState(240);\n\n  const [liveValue, setLiveValue] = useState(0);\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, turns, speed, magnetPoleOut, genTurns, genFieldB, genArea, genOmega, primaryTurns, secondaryTurns, primaryVoltage, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 320, 980);\n\n  const peakEmf = generatorPeakEmf(genTurns, genFieldB, genArea, genOmega);\n  const vs = transformerSecondaryVoltage(primaryVoltage, primaryTurns, secondaryTurns);\n  const isPer1A = transformerSecondaryCurrent(1, primaryTurns, secondaryTurns);\n\n  useTopicPreset(\"simulations-electromagnetic-induction\", { \"turns\": setTurns,\n    \"speed\": setSpeed,\n    \"genTurns\": setGenTurns,\n    \"genFieldB\": setGenFieldB,\n    \"genArea\": setGenArea,\n    \"genOmega\": setGenOmega,\n    \"primaryVoltage\": setPrimaryVoltage,\n    \"primaryTurns\": setPrimaryTurns,\n    \"secondaryTurns\": setSecondaryTurns }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Electricity · Electromagnetism</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Electromagnetic Induction</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span><span>{TOPIC_META[t].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <InductionCanvas key={resetKey} mode={topic as InductionMode}\n                  turns={turns} speed={speed} magnetPoleOut={magnetPoleOut}\n                  fieldB={genFieldB} coilArea={genArea} omega={genOmega}\n                  primaryTurns={primaryTurns} secondaryTurns={secondaryTurns} primaryVoltage={primaryVoltage}\n                  isRunning={isRunning} isPaused={isPaused} onTick={setLiveValue}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/electromagnetic-induction\"\n                  title={`${TOPIC_META[topic].title} — A-Factor STEM Studio`}\n                  params={{ topic }} />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {topic === 'faraday-lenz' && <>\n                  <Slider label=\"Coil turns\" unit=\"\" value={turns} min={2} max={20} step={1} set={setTurns} color=\"#6366f1\" />\n                  <Slider label=\"Oscillation speed\" unit=\"rad/s\" value={speed} min={0.5} max={5} step={0.5} set={setSpeed} color=\"#f59e0b\" />\n                  <div className=\"flex gap-2\">\n                    {([true, false] as const).map(v => (\n                      <button key={String(v)} onClick={() => setMagnetPoleOut(v)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                          magnetPoleOut === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{v ? 'N faces coil' : 'S faces coil'}</button>\n                    ))}\n                  </div>\n                </>}\n\n                {topic === 'ac-generator' && <>\n                  <Slider label=\"Coil turns\" unit=\"\" value={genTurns} min={10} max={200} step={10} set={setGenTurns} color=\"#6366f1\" />\n                  <Slider label=\"Field strength\" unit=\"T\" value={genFieldB} min={0.1} max={1} step={0.05} set={setGenFieldB} color=\"#f59e0b\" />\n                  <Slider label=\"Coil area\" unit=\"m²\" value={genArea} min={0.005} max={0.05} step={0.005} set={setGenArea} color=\"#8b5cf6\" />\n                  <Slider label=\"Angular speed ω\" unit=\"rad/s\" value={genOmega} min={1} max={10} step={0.5} set={setGenOmega} color=\"#8b5cf6\" />\n                </>}\n\n                {topic === 'transformer' && <>\n                  <Slider label=\"Primary voltage (peak)\" unit=\"V\" value={primaryVoltage} min={12} max={240} step={12} set={setPrimaryVoltage} color=\"#dc2626\" />\n                  <Slider label=\"Primary turns\" unit=\"\" value={primaryTurns} min={50} max={1000} step={50} set={setPrimaryTurns} color=\"#6366f1\" />\n                  <Slider label=\"Secondary turns\" unit=\"\" value={secondaryTurns} min={50} max={1000} step={50} set={setSecondaryTurns} color=\"#2563eb\" />\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {topic === 'faraday-lenz' && <>\n                    <StatRow label=\"Live EMF\" value={liveValue.toFixed(2)} unit=\"(arb. units)\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Lenz's law\" value=\"opposes the change\" unit=\"always\" color=\"text-emerald-600\" />\n                  </>}\n                  {topic === 'ac-generator' && <>\n                    <StatRow label=\"Peak EMF e₀\" value={peakEmf.toFixed(1)} unit=\"V\" color=\"text-indigo-600\" />\n                    <StatRow label=\"RMS EMF\" value={rmsFromPeak(peakEmf).toFixed(1)} unit=\"V\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Frequency\" value={(genOmega / (2 * Math.PI)).toFixed(2)} unit=\"Hz\" color=\"text-amber-600\" />\n                  </>}\n                  {topic === 'transformer' && <>\n                    <StatRow label=\"Secondary voltage\" value={vs.toFixed(1)} unit=\"V\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Turns ratio Ns/Np\" value={(secondaryTurns / primaryTurns).toFixed(2)} unit=\"\" color=\"text-amber-600\" />\n                    <StatRow label=\"Is per 1A primary\" value={isPer1A.toFixed(2)} unit=\"A\" color=\"text-purple-600\" />\n                    <StatRow label=\"Type\" value={secondaryTurns > primaryTurns ? 'step-up' : secondaryTurns < primaryTurns ? 'step-down' : 'isolation'} unit=\"\" color=\"text-emerald-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[topic].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/atomic-models/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useMemo, useEffect } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { AtomicModelsCanvas } from '@/components/simulation/AtomicModelsCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport {\n  ATOMIC_PRESETS, AtomicParams, AtomicModel,\n  generateHydrogenSpectrum,\n  bohrEnergy, bohrRadius, bohrVelocity,\n  validQuantumNumbers, possibleLValues, possibleMValues,\n  getShellCapacity,\n} from '@/lib/physics/atomicModels';\n\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700',\n  NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700',\n  SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n  'A-Level': 'bg-cyan-100 text-cyan-700',\n};\n\nconst TEACHER_NOTES = [\n  'The atomic model evolved over 120 years. Each model corrected fatal flaws in the previous.',\n  'Thomson (1897): Discovered the electron. Proposed the \"plum pudding\" model.',\n  'Rutherford (1911): Gold foil experiment proved atom is mostly empty space with a tiny nucleus.',\n  'Bohr (1913): Stationary states, quantized angular momentum L = nℏ, photon emission ΔE = hν.',\n  'Schrödinger (1926): Wavefunction Ψ gives probability amplitudes. |Ψ|² is probability density.',\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number; step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function AtomicModelsPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB', 'A-Level']);\n  const [mobileControlsOpen, setMobileControlsOpen] = useState(false);\n\n  const [model, setModel] = useState<AtomicModel>('thomson');\n  const [speed, setSpeed] = useState(1);\n  const [zoom, setZoom] = useState(1);\n  const [showOrbits, setShowOrbits] = useState(true);\n  const [showNucleus, setShowNucleus] = useState(true);\n  const [showElectrons, setShowElectrons] = useState(true);\n  const [showProbability, setShowProbability] = useState(true);\n  const [showEnergyLevels, setShowEnergyLevels] = useState(true);\n  const [showSpectrum, setShowSpectrum] = useState(true);\n  const [showLabels, setShowLabels] = useState(true);\n  const [showSpin, setShowSpin] = useState(false);\n  const [showFineStructure, setShowFineStructure] = useState(false);\n  const [showZeeman, setShowZeeman] = useState(false);\n  const [magneticField, setMagneticField] = useState(0);\n  const [nQuantum, setNQuantum] = useState(1);\n  const [lQuantum, setLQuantum] = useState(0);\n  const [mQuantum, setMQuantum] = useState(0);\n  const [protonCount, setProtonCount] = useState(1);\n  const [neutronCount, setNeutronCount] = useState(0);\n  const [electronCount, setElectronCount] = useState(1);\n  const [alphaEnergy, setAlphaEnergy] = useState(5);\n\n  const params: AtomicParams = {\n    model, speed, zoom, showOrbits, showNucleus, showElectrons, showProbability,\n    showEnergyLevels, showSpectrum, showLabels, showSpin, showFineStructure,\n    showZeeman, magneticField, nQuantum, lQuantum, mQuantum,\n    protonCount, neutronCount, electronCount, alphaEnergy,\n  };\n\n  const [liveStats, setLiveStats] = useState({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((stats: typeof liveStats) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveStats(stats);\n  }, []);\n\n  const applyPreset = useCallback((presetIdx: number) => {\n    const preset = ATOMIC_PRESETS[presetIdx];\n    if (!preset) return;\n    setModel(preset.model);\n    const pp = preset.params;\n    if (pp.speed !== undefined) setSpeed(pp.speed);\n    if (pp.zoom !== undefined) setZoom(pp.zoom);\n    if (pp.showOrbits !== undefined) setShowOrbits(pp.showOrbits);\n    if (pp.showNucleus !== undefined) setShowNucleus(pp.showNucleus);\n    if (pp.showElectrons !== undefined) setShowElectrons(pp.showElectrons);\n    if (pp.showProbability !== undefined) setShowProbability(pp.showProbability);\n    if (pp.showEnergyLevels !== undefined) setShowEnergyLevels(pp.showEnergyLevels);\n    if (pp.showSpectrum !== undefined) setShowSpectrum(pp.showSpectrum);\n    if (pp.showLabels !== undefined) setShowLabels(pp.showLabels);\n    if (pp.showSpin !== undefined) setShowSpin(pp.showSpin);\n    if (pp.showFineStructure !== undefined) setShowFineStructure(pp.showFineStructure);\n    if (pp.showZeeman !== undefined) setShowZeeman(pp.showZeeman);\n    if (pp.magneticField !== undefined) setMagneticField(pp.magneticField);\n    if (pp.nQuantum !== undefined) setNQuantum(pp.nQuantum);\n    if (pp.lQuantum !== undefined) setLQuantum(pp.lQuantum);\n    if (pp.mQuantum !== undefined) setMQuantum(pp.mQuantum);\n    if (pp.protonCount !== undefined) setProtonCount(pp.protonCount);\n    if (pp.neutronCount !== undefined) setNeutronCount(pp.neutronCount);\n    if (pp.electronCount !== undefined) setElectronCount(pp.electronCount);\n    if (pp.alphaEnergy !== undefined) setAlphaEnergy(pp.alphaEnergy);\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveStats({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveStats({ energy: 0, radius: 0, velocity: 0, n: 1, wavelength: 0, shellConfig: '' });\n  }, []);\n\n  useEffect(() => {\n    if (!validQuantumNumbers(nQuantum, lQuantum, mQuantum)) {\n      const validL = possibleLValues(nQuantum);\n      if (!validL.includes(lQuantum)) { setLQuantum(validL[0]); setMQuantum(0); }\n    }\n  }, [nQuantum]);\n\n  useEffect(() => {\n    const validM = possibleMValues(lQuantum);\n    if (!validM.includes(mQuantum)) setMQuantum(validM[0]);\n  }, [lQuantum]);\n\n  const spectrum = useMemo(() => generateHydrogenSpectrum(7), []);\n  const modelLabels: Record<AtomicModel, string> = { thomson: 'Thomson (1897)', rutherford: 'Rutherford (1911)', bohr: 'Bohr (1913)', quantum: 'Quantum (1926)' };\n\n  useTopicPreset(\"simulations-atomic-models\", { \"speed\": setSpeed,\n    \"zoom\": setZoom,\n    \"protonCount\": setProtonCount,\n    \"neutronCount\": setNeutronCount,\n    \"alphaEnergy\": setAlphaEnergy,\n    \"magneticField\": setMagneticField,\n    \"nQuantum\": setNQuantum }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Atomic Physics — From Plum Pudding to Quantum Field Theory</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Atomic Models</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {Object.keys(CC).map(c => (\n                  <button key={c} onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'}`}>\n                    {c}\n                  </button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Thomson → Rutherford → Bohr → Schrödinger</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">Eₙ = -13.6 Z²/n² eV</span>\n          </div>\n\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {(['thomson', 'rutherford', 'bohr', 'quantum'] as AtomicModel[]).map(m => (\n              <button key={m} onClick={() => { setModel(m); setIsRunning(false); setResetKey(k => k + 1); }}\n                className={`shrink-0 rounded-xl border px-4 py-2 text-left hover:shadow-sm transition min-w-[140px] ${model === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-600 hover:border-indigo-200'}`}>\n                <p className=\"text-xs font-medium\">{modelLabels[m]}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {ATOMIC_PRESETS.map((preset, i) => (\n              <button key={i} onClick={() => applyPreset(i)}\n                className=\"shrink-0 rounded-xl border border-gray-200 bg-white px-3 py-2 text-left hover:border-indigo-300 hover:shadow-sm transition min-w-[200px]\">\n                <p className=\"text-xs font-medium text-indigo-700\">{preset.name}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5 leading-relaxed\">{preset.description}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_240px] xl:grid-cols-[minmax(0,1fr)_240px_280px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <AtomicModelsCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} onTick={handleTick} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/atomic-models\" title=\"Atomic Models\"\n                  params={{ model, speed, zoom, orbits: showOrbits ? 1 : 0, nucleus: showNucleus ? 1 : 0, electrons: showElectrons ? 1 : 0, prob: showProbability ? 1 : 0, levels: showEnergyLevels ? 1 : 0, spectrum: showSpectrum ? 1 : 0, labels: showLabels ? 1 : 0, spin: showSpin ? 1 : 0, fs: showFineStructure ? 1 : 0, zeeman: showZeeman ? 1 : 0, B: magneticField, n: nQuantum, l: lQuantum, m: mQuantum, Z: protonCount, N: neutronCount, e: electronCount, alphaE: alphaEnergy }} />\n              </div>\n\n              {/* Mobile controls toggle */}\n              <div data-stage-role=\"parameters\"><button onClick={() => setMobileControlsOpen(o => !o)} className=\"lg:hidden w-full py-2.5 text-sm font-medium rounded-xl border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 transition\">\n                {mobileControlsOpen ? 'Hide controls ▲' : 'Show controls ▼'}\n              </button></div>\n\n              <div data-stage-role=\"parameters\" className={`rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4 ${mobileControlsOpen ? '' : 'hidden lg:block'}`}>\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">Display</p>\n                    <Slider label=\"Animation speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" note=\"Time evolution speed\" />\n                    <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.3} max={3} step={0.1} set={setZoom} color=\"#10b981\" note=\"Canvas zoom level\" />\n                  </div>\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">Nucleus</p>\n                    <Slider label=\"Protons Z\" unit=\"\" value={protonCount} min={1} max={92} step={1} set={setProtonCount} color=\"#fbbf24\" note=\"Atomic number\" />\n                    <Slider label=\"Neutrons N\" unit=\"\" value={neutronCount} min={0} max={150} step={1} set={setNeutronCount} color=\"#a78bfa\" note=\"Neutron number\" />\n                  </div>\n                </div>\n\n                {model === 'rutherford' && (\n                  <div className=\"border-t border-gray-100 pt-3\">\n                    <Slider label=\"α-particle energy\" unit=\"MeV\" value={alphaEnergy} min={1} max={10} step={0.5} set={setAlphaEnergy} color=\"#f43f5e\" note=\"Kinetic energy of incoming α particles\" />\n                  </div>\n                )}\n\n                {model === 'bohr' && (\n                  <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                    <p className=\"text-[10px] font-medium text-emerald-600 uppercase tracking-wide\">Bohr Model Options</p>\n                    <div className=\"flex flex-wrap gap-3\">\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showOrbits} onChange={e => setShowOrbits(e.target.checked)} className=\"rounded\" /> Show orbits</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showEnergyLevels} onChange={e => setShowEnergyLevels(e.target.checked)} className=\"rounded\" /> Energy levels</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showSpectrum} onChange={e => setShowSpectrum(e.target.checked)} className=\"rounded\" /> Spectrum bar</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showSpin} onChange={e => setShowSpin(e.target.checked)} className=\"rounded\" /> Show spin (↑)</label>\n                    </div>\n                    <div className=\"flex flex-wrap gap-3\">\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showFineStructure} onChange={e => setShowFineStructure(e.target.checked)} className=\"rounded\" /> Fine structure (j = l ± ½)</label>\n                      <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showZeeman} onChange={e => setShowZeeman(e.target.checked)} className=\"rounded\" /> Zeeman effect</label>\n                    </div>\n                    {showZeeman && <Slider label=\"Magnetic field B\" unit=\"T\" value={magneticField} min={0} max={5} step={0.1} set={setMagneticField} color=\"#8b5cf6\" note=\"Tesla — splits degenerate levels\" />}\n                  </div>\n                )}\n\n                {model === 'quantum' && (\n                  <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                    <p className=\"text-[10px] font-medium text-purple-600 uppercase tracking-wide\">Quantum Numbers</p>\n                    <div className=\"grid grid-cols-3 gap-3\">\n                      <Slider label=\"n\" unit=\"\" value={nQuantum} min={1} max={4} step={1} set={setNQuantum} color=\"#6366f1\" note=\"Principal quantum number\" />\n                      <Slider label=\"l\" unit=\"\" value={lQuantum} min={0} max={nQuantum - 1} step={1} set={setLQuantum} color=\"#ec4899\" note=\"Angular momentum (0=s,1=p,2=d,3=f)\" />\n                      <Slider label=\"m\" unit=\"\" value={mQuantum} min={-lQuantum} max={lQuantum} step={1} set={setMQuantum} color=\"#10b981\" note=\"Magnetic quantum number\" />\n                    </div>\n                    <p className=\"text-[10px] text-gray-400\">Orbital: <span className=\"font-medium text-indigo-600\">{nQuantum}{['s','p','d','f'][lQuantum] || '?'}</span> — <span className=\"text-gray-500\">{lQuantum === 0 ? 'spherical, no angular nodes' : lQuantum === 1 ? 'dumbbell, 1 angular node' : lQuantum === 2 ? 'cloverleaf, 2 angular nodes' : lQuantum === 3 ? 'complex 8-lobed, 3 angular nodes' : 'higher orbital'}</span></p>\n                  </div>\n                )}\n\n                <div className=\"border-t border-gray-100 pt-3\">\n                  <p className=\"text-[10px] font-medium text-gray-500 uppercase tracking-wide mb-2\">Visibility</p>\n                  <div className=\"flex flex-wrap gap-3\">\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showNucleus} onChange={e => setShowNucleus(e.target.checked)} className=\"rounded\" /> Nucleus</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showElectrons} onChange={e => setShowElectrons(e.target.checked)} className=\"rounded\" /> Electrons</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showProbability} onChange={e => setShowProbability(e.target.checked)} className=\"rounded\" /> Probability cloud</label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\"><input type=\"checkbox\" checked={showLabels} onChange={e => setShowLabels(e.target.checked)} className=\"rounded\" /> Info labels</label>\n                  </div>\n                </div>\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {model === 'bohr' && (\n                    <>\n                      <StatRow label=\"Energy Eₙ\" value={liveStats.energy.toFixed(2)} unit=\"eV\" color=\"text-indigo-600\" />\n                      <StatRow label=\"Radius rₙ\" value={liveStats.radius.toFixed(2)} unit=\"a₀\" color=\"text-rose-500\" />\n                      <StatRow label=\"Velocity vₙ\" value={liveStats.velocity.toFixed(4)} unit=\"c·α\" color=\"text-emerald-600\" />\n                      <StatRow label=\"Quantum n\" value={liveStats.n.toString()} unit=\"\" color=\"text-blue-500\" />\n                      {liveStats.wavelength > 0 && <StatRow label=\"λ (transition)\" value={liveStats.wavelength.toFixed(1)} unit=\"nm\" color=\"text-amber-600\" />}\n                      {showFineStructure && <StatRow label=\"Fine split\" value=\"~10⁻⁴\" unit=\"eV\" color=\"text-purple-600\" />}\n                      {showZeeman && magneticField > 0 && <StatRow label=\"Zeeman ΔE\" value={(magneticField * 5.788e-5 * 1e6).toFixed(2)} unit=\"μeV\" color=\"text-pink-500\" />}\n                    </>\n                  )}\n                  {model === 'quantum' && (\n                    <>\n                      <StatRow label=\"Energy Eₙ\" value={bohrEnergy(nQuantum, protonCount).toFixed(2)} unit=\"eV\" color=\"text-indigo-600\" />\n                      <StatRow label=\"Bohr radius\" value={bohrRadius(nQuantum, protonCount).toFixed(2)} unit=\"a₀\" color=\"text-rose-500\" />\n                      <StatRow label=\"Degeneracy\" value={(nQuantum * nQuantum).toString()} unit=\"states\" color=\"text-purple-600\" />\n                      <StatRow label=\"Orbital\" value={`${nQuantum}${['s','p','d','f'][lQuantum] || '?'}`} unit=\"\" color=\"text-emerald-600\" />\n                      <StatRow label=\"Angular nodes\" value={lQuantum.toString()} unit=\"\" color=\"text-amber-600\" />\n                      <StatRow label=\"Radial nodes\" value={(nQuantum - lQuantum - 1).toString()} unit=\"\" color=\"text-blue-500\" />\n                    </>\n                  )}\n                  {model === 'thomson' && (\n                    <>\n                      <StatRow label=\"Electrons\" value={electronCount.toString()} unit=\"\" color=\"text-blue-500\" />\n                      <StatRow label=\"Protons\" value={protonCount.toString()} unit=\"\" color=\"text-amber-600\" />\n                      <StatRow label=\"Net charge\" value=\"0\" unit=\"e\" color=\"text-emerald-600\" />\n                    </>\n                  )}\n                  {model === 'rutherford' && (\n                    <>\n                      <StatRow label=\"Nucleus Z\" value={protonCount.toString()} unit=\"\" color=\"text-amber-600\" />\n                      <StatRow label=\"Mass number A\" value={(protonCount + neutronCount).toString()} unit=\"\" color=\"text-rose-500\" />\n                      <StatRow label=\"α energy\" value={alphaEnergy.toFixed(1)} unit=\"MeV\" color=\"text-rose-500\" />\n                      <StatRow label=\"Nuclear radius\" value={(1.2 * Math.pow(protonCount + neutronCount, 1/3)).toFixed(2)} unit=\"fm\" color=\"text-purple-600\" />\n                    </>\n                  )}\n                </div>\n              </div>\n\n              {model === 'bohr' && (\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Hydrogen Spectrum</p>\n                  <div className=\"space-y-1\">\n                    {spectrum.slice(0, 10).map((line, i) => (\n                      <div key={i} className=\"flex items-center gap-2 text-[10px]\">\n                        <div className=\"w-3 h-3 rounded-full shrink-0\" style={{ backgroundColor: line.color }} />\n                        <span className=\"text-gray-500 w-16\">{line.series}</span>\n                        <span className=\"font-mono text-gray-700\">{line.wavelength.toFixed(0)} nm</span>\n                        <span className=\"text-gray-400\">({line.fromN}→{line.toN})</span>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n              )}\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {Object.keys(CC).map(c => <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'}`}>{c}</span>)}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\"><span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}</li>\n                  ))}\n                </ul>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/oscillations/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useEffect } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { PendulumCanvas } from '@/components/simulation/PendulumCanvas';\nimport { SpringCanvas } from '@/components/simulation/SpringCanvas';\nimport { ConicalPendulumCanvas } from '@/components/simulation/ConicalPendulumCanvas';\nimport { PhysicalPendulumCanvas } from '@/components/simulation/PhysicalPendulumCanvas';\nimport { BifilarCanvas } from '@/components/simulation/BifilarCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { SHMGraph } from '@/components/simulation/SHMGraph';\nimport {\n  pendulumOmega, pendulumPeriod,\n  springOmega, springPeriod, springStaticExtension,\n  conicalPendulumOmega, conicalPendulumPeriod, conicalPendulumTension, conicalPendulumSpeed,\n  physicalPendulumPeriod, rodPendulumPeriod,\n  bifilarPeriodSimple, cantileverStiffness, cantileverDeflection, cantileverPeriod,\n} from '@/lib/physics/shm';\n\ntype Topic = 'pendulum' | 'spring' | 'conical' | 'physical' | 'bifilar';\ntype GraphMode = 'displacement' | 'velocity' | 'acceleration' | 'energy' | 'phase';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; eq: string }> = {\n  pendulum: { title: 'Simple pendulum',       icon: '⏱️', sub: 'SHM for small angles', eq: 'T = 2π√(L/g)' },\n  spring:   { title: 'Loaded spring',         icon: '🌀', sub: 'Mass-spring system',    eq: 'T = 2π√(m/k)' },\n  conical:  { title: 'Conical pendulum',      icon: '🔄', sub: 'Circular motion + tension', eq: 'ω² = g/(L cosθ)' },\n  physical: { title: 'Physical pendulum',     icon: '📏', sub: 'Extended rigid body',   eq: 'T = 2π√(I/mgd)' },\n  bifilar:  { title: 'Bifilar / Cantilever',  icon: '🏗️', sub: 'Torsion & beam flexure', eq: 'T = 2π√(Il/mgd²)' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  pendulum: [\n    \"Period T = 2π√(L/g) is INDEPENDENT of mass and amplitude (for small angles < 15°).\",\n    \"This independence of mass is why a pendulum makes a good clock — it keeps time regardless of the bob.\",\n    \"For large amplitudes, the period increases — the small-angle approximation (sinθ ≈ θ) breaks down.\",\n    \"On the Moon (g=1.6 m/s²), the same pendulum runs ~2.5× slower. The gravity slider demonstrates this.\",\n    \"A seconds pendulum (T=2s) has length L = g/π² ≈ 0.993m — almost exactly 1 metre.\",\n  ],\n  spring: [\n    \"T = 2π√(m/k): period increases with mass, decreases with spring stiffness. Mass affects it; length does not.\",\n    \"The static extension x₀ = mg/k gives the equilibrium position. SHM occurs about this point.\",\n    \"Hooke's Law F = kx and SHM are directly linked: F = −kx gives a = −(k/m)x → ω² = k/m.\",\n    \"Energy: at equilibrium (x=0) all energy is KE. At amplitude (x=A) all energy is PE. Total E = ½mω²A² always.\",\n    \"The phase space graph (v vs x) is an ellipse — a perfect circle if axes are scaled to same range.\",\n  ],\n  conical: [\n    \"The bob moves in a horizontal circle — this is NOT SHM, but links circular motion to pendulums.\",\n    \"Key equations: T cosθ = mg (vertical), T sinθ = mω²r (horizontal). Dividing: tanθ = ω²r/g.\",\n    \"As ω increases, θ increases (bob rises). As θ → 90°, r → L and ω → ∞ (impossible in practice).\",\n    \"Period decreases as angle increases: T = 2π√(L cosθ / g). Faster spin = shorter period.\",\n    \"Good link to centripetal force: the horizontal component of tension provides centripetal force.\",\n  ],\n  physical: [\n    \"A physical pendulum uses the full rigid-body rotation: T = 2π√(I/mgd) where I is about the pivot.\",\n    \"For a uniform rod pivoted at the end: I = mL²/3, d = L/2 → T = 2π√(2L/3g). Compare to simple T = 2π√(L/g).\",\n    \"The physical pendulum always has a longer period than the simple pendulum of the same length.\",\n    \"There are two pivot points that give the same period — the 'centre of oscillation' concept used in precision timing.\",\n    \"The equivalent simple pendulum length L_eq = I/(md). This is what IGCSE/JUPEB exam questions test.\",\n  ],\n  bifilar: [\n    \"Bifilar suspension: a rod hung by two parallel wires undergoes TORSIONAL oscillation (twisting).\",\n    \"T = (2π/d)√(Il/mg) where d = half wire separation, l = wire length, I = moment of inertia.\",\n    \"Used to measure moment of inertia experimentally: measure T, know l and d, solve for I.\",\n    \"Cantilever beam: one end fixed, free end deflects under load. Stiffness k = 3EI/L³.\",\n    \"Cantilever vibration period T = 2π√(m_eff/k). The effective mass ≈ 0.24 × beam mass + tip mass.\",\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  pendulum: [\n    { q: \"A pendulum has period 2s on Earth (g=9.81 m/s²). Find its length.\", a: \"T=2π√(L/g) → L=g(T/2π)²=9.81×(2/2π)²=9.81×0.1013=0.993m ≈ 1m\" },\n    { q: \"A 2m pendulum is taken to a planet where g=4 m/s². Find the new period.\", a: \"T=2π√(L/g)=2π√(2/4)=2π×0.707=4.44s\" },\n    { q: \"Why does doubling the mass of a pendulum bob not change its period?\", a: \"Both restoring force and inertia scale with mass, so they cancel in the period equation T=2π√(L/g) — mass doesn't appear.\" },\n  ],\n  spring: [\n    { q: \"A 0.5kg mass on a spring of k=200 N/m. Find period and frequency.\", a: \"T=2π√(m/k)=2π√(0.5/200)=2π×0.05=0.314s. f=1/T=3.18Hz\" },\n    { q: \"A spring extends 0.05m under a 2kg load (g=10 m/s²). Find k and the SHM period.\", a: \"k=F/x=mg/x=20/0.05=400 N/m. T=2π√(2/400)=2π×0.0707=0.444s\" },\n    { q: \"A spring-mass system has total energy 0.4J and amplitude 0.1m. Find the spring constant k.\", a: \"E=½kA² → k=2E/A²=2×0.4/0.01=80 N/m\" },\n  ],\n  conical: [\n    { q: \"A conical pendulum of length 0.5m makes angle 30° with vertical. Find ω and period. (g=10)\", a: \"ω=√(g/Lcosθ)=√(10/0.5×cos30°)=√(10/0.433)=√23.1=4.81 rad/s. T=2π/ω=1.31s\" },\n    { q: \"Find the tension in the string of a 0.2kg bob at θ=45°. (g=10)\", a: \"T=mg/cosθ=0.2×10/cos45°=2/0.707=2.83N\" },\n    { q: \"As the angular velocity of a conical pendulum increases, what happens to the angle θ?\", a: \"θ increases — the bob rises outward. Since ω²=g/(Lcosθ), larger ω requires smaller cosθ, meaning larger θ.\" },\n  ],\n  physical: [\n    { q: \"A uniform rod of length 1.2m and mass 0.5kg is pivoted at one end. Find the period. (g=9.81)\", a: \"I=mL²/3=0.5×1.44/3=0.24 kg·m². d=L/2=0.6m. T=2π√(I/mgd)=2π√(0.24/0.5×9.81×0.6)=2π×0.285=1.79s\" },\n    { q: \"Compare this to a simple pendulum of the same length.\", a: \"T_simple=2π√(1.2/9.81)=2π×0.350=2.20s. The physical pendulum (1.79s) is FASTER — its effective length is 2L/3=0.8m, shorter than L.\" },\n    { q: \"What is the equivalent simple pendulum length for a uniform rod pivoted at one end?\", a: \"L_eq=I/(md)=(mL²/3)/(m×L/2)=2L/3. For L=1.2m: L_eq=0.8m.\" },\n  ],\n  bifilar: [\n    { q: \"A 2kg rod (L=0.6m) hangs on wires of length 1m, separation 0.4m. Find the period.\", a: \"I=mL²/12=2×0.36/12=0.06 kg·m². T=2π√(Il/mgd²)=2π√(0.06×1/2×9.81×0.04)=2π√(0.0765)=2π×0.277=1.74s\" },\n    { q: \"A cantilever beam: E=200GPa, b=30mm, h=5mm, L=0.5m. Find stiffness k.\", a: \"I_beam=bh³/12=0.03×(0.005)³/12=3.125×10⁻¹⁰m⁴. k=3EI/L³=3×200×10⁹×3.125×10⁻¹⁰/0.125=1500 N/m\" },\n    { q: \"Why is bifilar suspension used to measure moment of inertia experimentally?\", a: \"The period T=(2π/d)√(Il/mg) can be rearranged to I=mgd²T²/(4π²l). By measuring T and knowing all other quantities, I is found without needing to integrate over the shape.\" },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nexport default function OscillationsPage() {\n  const [topic, setTopic] = useState<Topic>('pendulum');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'JUPEB']);\n  const [graphMode, setGraphMode] = useState<GraphMode>('displacement');\n  const [currentT, setCurrentT] = useState(0);\n\n  // Pendulum params\n  const [pendL, setPendL] = useState(1.0);\n  const [pendA, setPendA] = useState(15);\n  const [pendG, setPendG] = useState(9.81);\n  const [pendM, setPendM] = useState(0.5);\n\n  // Spring params\n  const [spK, setSpK] = useState(50);\n  const [spM, setSpM] = useState(1.0);\n  const [spA, setSpA] = useState(0.1);\n\n  // Conical params\n  const [conL, setConL] = useState(0.8);\n  const [conTheta, setConTheta] = useState(30);\n  const [conM, setConM] = useState(0.3);\n\n  // Physical pendulum params\n  const [physL, setPhysL] = useState(1.0);\n  const [physM, setPhysM] = useState(0.5);\n  const [physPF, setPhysPF] = useState(0); // pivot fraction from top (0=top end, 0.5=centre)\n\n  // Bifilar/Cantilever params\n  const [bifMode, setBifMode] = useState<'bifilar' | 'cantilever'>('bifilar');\n  const [bifM, setBifM] = useState(2);\n  const [bifL, setBifL] = useState(0.6);\n  const [bifWire, setBifWire] = useState(1.0);\n  const [bifSep, setBifSep] = useState(0.3);\n  const [cantL, setCantL] = useState(0.5);\n  const [cantH, setCantH] = useState(10); // mm\n  const [cantLoad, setCantLoad] = useState(5);\n\n  // Derived analytics\n  const pendOmega = pendulumOmega(pendL, pendG);\n  const pendT = pendulumPeriod(pendL, pendG);\n  const spOmega = springOmega(spK, spM);\n  const spT = springPeriod(spK, spM);\n  const spStaticX = springStaticExtension(spM, spK);\n  const conOmega = conicalPendulumOmega(conL, conTheta * Math.PI / 180);\n  const conT = conicalPendulumPeriod(conL, conTheta * Math.PI / 180);\n  const conTens = conicalPendulumTension(conM, conTheta * Math.PI / 180);\n  const conSpeed = conicalPendulumSpeed(conL, conTheta * Math.PI / 180);\n  // Pivot-dependent — must mirror PhysicalPendulumCanvas exactly, otherwise\n  // the graph's ω differs from the canvas's ω whenever the pivot slider moves\n  // and the live dot drifts off the rod's motion.\n  const physD = Math.max(Math.abs(physL / 2 - physPF * physL), 0.001);\n  const physI = physM * physL * physL / 12 + physM * physD * physD;\n  const physT_actual = physicalPendulumPeriod(physI, physM, physD);\n  const physT_simple = rodPendulumPeriod(physL);\n  const bifT = bifilarPeriodSimple(bifM, bifL, bifWire, bifSep / 2);\n  const cantK = cantileverStiffness(200e9, 0.03, cantH / 1000, cantL);\n  const cantDef = cantileverDeflection(cantLoad, 200e9, 0.03, cantH / 1000, cantL);\n  const cantT = cantileverPeriod(1, 200e9, 0.03, cantH / 1000, cantL);\n\n  // Graph data — omega/A must match what the canvas actually animates so the\n  // live dot on the curve tracks the mass/bob/rod exactly.\n  const bifOmega = bifMode === 'bifilar' ? 2 * Math.PI / bifT : 2 * Math.PI / cantT;\n  const graphA = topic === 'pendulum' ? pendA * Math.PI / 180 * pendL :\n                 topic === 'spring' ? spA :\n                 topic === 'physical' ? 0.25 :          // rad — canvas uses A_rad = 0.25\n                 bifMode === 'bifilar' ? 0.3 :           // rad — bifilar canvas uses 0.3\n                 0.3 * cantDef;                          // m — cantilever tip oscillates ±0.3·δ\n  const graphOmega = topic === 'pendulum' ? pendOmega :\n                     topic === 'spring' ? spOmega :\n                     topic === 'physical' ? 2 * Math.PI / physT_actual :\n                     bifOmega;\n  const graphM = topic === 'pendulum' ? pendM : topic === 'spring' ? spM :\n                 topic === 'physical' ? physM : bifM;\n  const graphK = topic === 'pendulum' ? pendM * pendOmega * pendOmega :\n                 topic === 'spring' ? spK :\n                 graphM * graphOmega * graphOmega;\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1); setCurrentT(0);\n  }, []);\n\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, pendL, pendA, pendG, pendM, spK, spM, spA, conL, conTheta, conM, physL, physM, physPF, bifM, bifL, bifWire, bifSep, cantL, cantH, cantLoad, bifMode, reset]);\n\n  // Throttle marker updates to ~12fps. Updating React state on every\n  // animation frame re-rendered the whole page (and the Recharts graph)\n  // 60+ times a second — the graph would visibly stutter and lag behind\n  // the canvas. The canvas itself animates via its own rAF loop and is\n  // unaffected by this throttle.\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((t: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current > 40) {\n      lastTickRef.current = now;\n      setCurrentT(t);\n    }\n  }, []);\n\n  // Each topic was tuned with its own aspect ratio (spring is a tall,\n  // portrait-ish demo; the others are wider) — pick the matching base\n  // before scaling it up to fill the available width.\n  const oscBase = topic === 'spring' ? { w: 280, h: 320 }\n    : topic === 'bifilar' ? { w: 380, h: 280 }\n    : { w: 380, h: 300 };\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, oscBase.w, oscBase.h, 650);\n\n  useTopicPreset(\"simulations-oscillations\", { \"pendL\": setPendL,\n    \"pendA\": setPendA,\n    \"pendM\": setPendM,\n    \"pendG\": setPendG,\n    \"spK\": setSpK,\n    \"spM\": setSpM,\n    \"spA\": setSpA,\n    \"conL\": setConL,\n    \"conTheta\": setConTheta,\n    \"conM\": setConM,\n    \"physL\": setPhysL,\n    \"physM\": setPhysM,\n    \"physPF\": setPhysPF,\n    \"bifM\": setBifM,\n    \"bifL\": setBifL,\n    \"bifWire\": setBifWire,\n    \"bifSep\": setBifSep,\n    \"cantL\": setCantL,\n    \"cantH\": setCantH,\n    \"cantLoad\": setCantLoad }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Mechanics — Oscillations</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Simple Harmonic Motion</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n\n          {/* Topic tabs */}\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); setGraphMode('displacement'); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span>\n                <span className=\"hidden sm:inline\">{TOPIC_META[t].title}</span>\n                <span className=\"sm:hidden\">{TOPIC_META[t].icon}</span>\n              </button>\n            ))}\n          </div>\n\n          {/* Equation banner */}\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].eq}</span>\n            {topic !== 'conical' && (\n              <span className=\"text-xs text-gray-400 ml-2\">a = −ω²x &nbsp;|&nbsp; x = A cos(ωt)</span>\n            )}\n          </div>\n\n          {/* Main grid */}\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n\n            {/* Canvas + graph + controls + sliders */}\n            <SimulationStage className=\"space-y-3 min-w-0\">\n\n              {/* Canvas */}\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                {topic === 'pendulum' && (\n                  <PendulumCanvas key={resetKey} length={pendL} amplitude={pendA}\n                    gravity={pendG} mass={pendM}\n                    isRunning={isRunning} isPaused={isPaused}\n                    onTick={(t) => handleTick(t)}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'spring' && (\n                  <SpringCanvas key={resetKey} k={spK} mass={spM} amplitude={spA}\n                    isRunning={isRunning} isPaused={isPaused}\n                    onTick={(t) => handleTick(t)}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'conical' && (\n                  <ConicalPendulumCanvas key={resetKey} length={conL} theta_deg={conTheta}\n                    mass={conM} isRunning={isRunning} isPaused={isPaused}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'physical' && (\n                  <PhysicalPendulumCanvas key={resetKey} length={physL} mass={physM}\n                    pivotFraction={physPF} isRunning={isRunning} isPaused={isPaused}\n                    onTick={(t) => handleTick(t)}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'bifilar' && (\n                  <div className=\"space-y-2\">\n                    <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl w-fit\">\n                      {(['bifilar', 'cantilever'] as const).map(m => (\n                        <button key={m} onClick={() => setBifMode(m)}\n                          className={`px-4 py-2 rounded-lg text-xs font-medium transition capitalize ${\n                            bifMode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500'\n                          }`}>{m}</button>\n                      ))}\n                    </div>\n                    <BifilarCanvas key={`${resetKey}-${bifMode}`}\n                      mode={bifMode} mass={bifM} rodLength={bifL}\n                      wireLength={bifWire} separation={bifSep}\n                      beamLength={cantL} beamWidth={30} beamHeight={cantH}\n                      youngModulus={200} load={cantLoad}\n                      isRunning={isRunning} isPaused={isPaused}\n                      onTick={(t) => handleTick(t)}\n                      width={canvasSize.width} height={canvasSize.height} />\n                  </div>\n                )}\n              </div>\n\n              {/* Controls */}\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls\n                  isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)}\n                  onReset={reset}\n                />\n                {topic !== 'bifilar' && (\n                  <EmbedButton\n                    path=\"/embed/oscillations\"\n                    title={`${TOPIC_META[topic].title} — A-Factor STEM Studio`}\n                    params={\n                      topic === 'pendulum' ? { topic, L: pendL, A: pendA, g: pendG, m: pendM } :\n                      topic === 'spring'   ? { topic, k: spK, m: spM, A: spA } :\n                      topic === 'conical'  ? { topic, L: conL, theta: conTheta, m: conM } :\n                      { topic, L: physL, m: physM, pf: physPF }\n                    }\n                  />\n                )}\n              </div>\n\n              {/* Graph */}\n              <div data-stage-role=\"parameters\">{topic !== 'conical' && (\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <div className=\"flex items-center justify-between mb-3 flex-wrap gap-2\">\n                    <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Graph</p>\n                    <div className=\"flex gap-1 bg-gray-100 p-0.5 rounded-lg overflow-x-auto\">\n                      {(['displacement', 'velocity', 'acceleration', 'energy', 'phase'] as GraphMode[]).map(gm => (\n                        <button key={gm} onClick={() => setGraphMode(gm)}\n                          className={`shrink-0 px-2.5 py-2 rounded-md text-[10px] font-medium transition ${\n                            graphMode === gm ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500'\n                          }`}>\n                          {gm === 'displacement' ? 'x–t' : gm === 'velocity' ? 'v–t' : gm === 'acceleration' ? 'a–t' : gm === 'energy' ? 'Energy' : 'Phase (v–x)'}\n                        </button>\n                      ))}\n                    </div>\n                  </div>\n                  <SHMGraph A={graphA} omega={graphOmega} m={graphM} k={graphK}\n                    mode={graphMode} currentT={currentT} />\n                  <p className=\"text-[10px] text-gray-400 mt-2 text-center\">\n                    {graphMode === 'displacement' && 'Cosine wave — starts at +A, returns to +A each period T'}\n                    {graphMode === 'velocity' && 'Sine wave — 90° ahead of displacement. Maximum at x=0'}\n                    {graphMode === 'acceleration' && 'Cosine wave — always opposite to displacement (a = −ω²x)'}\n                    {graphMode === 'energy' && 'KE and PE exchange; total energy E = ½mω²A² = constant (dashed)'}\n                    {graphMode === 'phase' && 'Ellipse in phase space — SHM traces a closed orbit'}\n                  </p>\n                </div>\n              )}</div>\n\n              {/* Sliders */}\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {topic === 'pendulum' && <>\n                  <Slider label=\"Length\" unit=\"m\" value={pendL} min={0.1} max={3} step={0.05} set={setPendL} color=\"#6366f1\" />\n                  <Slider label=\"Amplitude\" unit=\"°\" value={pendA} min={2} max={30} step={1} set={setPendA} color=\"#f59e0b\" note=\"Keep < 15° for accurate SHM\" />\n                  <Slider label=\"Mass\" unit=\"kg\" value={pendM} min={0.1} max={2} step={0.1} set={setPendM} color=\"#94a3b8\" note=\"Does not affect period\" />\n                  <Slider label=\"Gravity\" unit=\"m/s²\" value={pendG} min={1.6} max={25} step={0.1} set={setPendG} color=\"#10b981\" note=\"Moon=1.6  Earth=9.81  Jupiter=24.8\" />\n                </>}\n\n                {topic === 'spring' && <>\n                  <Slider label=\"Spring constant k\" unit=\"N/m\" value={spK} min={5} max={500} step={5} set={setSpK} color=\"#6366f1\" />\n                  <Slider label=\"Mass\" unit=\"kg\" value={spM} min={0.1} max={5} step={0.1} set={setSpM} color=\"#f59e0b\" />\n                  <Slider label=\"Amplitude\" unit=\"m\" value={spA} min={0.01} max={0.3} step={0.01} set={setSpA} color=\"#10b981\" note=\"Must be less than static extension\" />\n                </>}\n\n                {topic === 'conical' && <>\n                  <Slider label=\"String length\" unit=\"m\" value={conL} min={0.2} max={2} step={0.05} set={setConL} color=\"#6366f1\" />\n                  <Slider label=\"Half-angle θ\" unit=\"°\" value={conTheta} min={5} max={75} step={1} set={setConTheta} color=\"#f59e0b\" />\n                  <Slider label=\"Mass\" unit=\"kg\" value={conM} min={0.1} max={1} step={0.05} set={setConM} color=\"#10b981\" />\n                </>}\n\n                {topic === 'physical' && <>\n                  <Slider label=\"Rod length\" unit=\"m\" value={physL} min={0.2} max={2} step={0.05} set={setPhysL} color=\"#6366f1\" />\n                  <Slider label=\"Mass\" unit=\"kg\" value={physM} min={0.1} max={2} step={0.1} set={setPhysM} color=\"#f59e0b\" />\n                  <Slider label=\"Pivot position (fraction from top)\" unit=\"\" value={physPF} min={0} max={0.45} step={0.05} set={setPhysPF} color=\"#10b981\" note=\"0 = top end, 0.5 = centre (infinite period)\" />\n                </>}\n\n                {topic === 'bifilar' && bifMode === 'bifilar' && <>\n                  <Slider label=\"Rod mass\" unit=\"kg\" value={bifM} min={0.5} max={5} step={0.1} set={setBifM} color=\"#6366f1\" />\n                  <Slider label=\"Rod length\" unit=\"m\" value={bifL} min={0.2} max={1.5} step={0.05} set={setBifL} color=\"#f59e0b\" />\n                  <Slider label=\"Wire length\" unit=\"m\" value={bifWire} min={0.3} max={2} step={0.05} set={setBifWire} color=\"#10b981\" />\n                  <Slider label=\"Wire separation (2d)\" unit=\"m\" value={bifSep} min={0.1} max={0.8} step={0.02} set={setBifSep} color=\"#8b5cf6\" />\n                </>}\n\n                {topic === 'bifilar' && bifMode === 'cantilever' && <>\n                  <Slider label=\"Beam length\" unit=\"m\" value={cantL} min={0.1} max={1} step={0.05} set={setCantL} color=\"#6366f1\" />\n                  <Slider label=\"Beam height (thickness)\" unit=\"mm\" value={cantH} min={2} max={20} step={1} set={setCantH} color=\"#f59e0b\" />\n                  <Slider label=\"End load\" unit=\"N\" value={cantLoad} min={0} max={50} step={1} set={setCantLoad} color=\"#ef4444\" />\n                </>}\n              </div>\n            </SimulationStage>\n\n            {/* Analytics */}\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {topic === 'pendulum' && [\n                    { l: 'Angular freq ω', v: `${pendOmega.toFixed(3)} rad/s`, c: 'text-indigo-600' },\n                    { l: 'Period T', v: `${pendT.toFixed(3)} s`, c: 'text-emerald-600' },\n                    { l: 'Frequency f', v: `${(1/pendT).toFixed(3)} Hz`, c: 'text-amber-600' },\n                    { l: 'Max velocity', v: `${(pendA * Math.PI/180 * pendL * pendOmega).toFixed(3)} m/s`, c: 'text-rose-500' },\n                    { l: 'Max acceleration', v: `${(pendA * Math.PI/180 * pendL * pendOmega**2).toFixed(3)} m/s²`, c: 'text-purple-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {topic === 'spring' && [\n                    { l: 'Angular freq ω', v: `${spOmega.toFixed(3)} rad/s`, c: 'text-indigo-600' },\n                    { l: 'Period T', v: `${spT.toFixed(3)} s`, c: 'text-emerald-600' },\n                    { l: 'Static extension', v: `${spStaticX.toFixed(3)} m`, c: 'text-amber-600' },\n                    { l: 'Max velocity', v: `${(spA * spOmega).toFixed(3)} m/s`, c: 'text-rose-500' },\n                    { l: 'Total energy', v: `${(0.5 * spK * spA * spA).toFixed(4)} J`, c: 'text-purple-600' },\n                    { l: 'Max KE = Max PE', v: `${(0.5 * spK * spA * spA).toFixed(4)} J`, c: 'text-gray-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {topic === 'conical' && [\n                    { l: 'Angular velocity ω', v: `${conOmega.toFixed(3)} rad/s`, c: 'text-indigo-600' },\n                    { l: 'Period T', v: `${conT.toFixed(3)} s`, c: 'text-emerald-600' },\n                    { l: 'Orbital radius r', v: `${(conL * Math.sin(conTheta*Math.PI/180)).toFixed(3)} m`, c: 'text-amber-600' },\n                    { l: 'String tension T', v: `${conTens.toFixed(3)} N`, c: 'text-rose-500' },\n                    { l: 'Orbital speed v', v: `${conSpeed.toFixed(3)} m/s`, c: 'text-purple-600' },\n                    { l: 'Vertical height', v: `${(conL * Math.cos(conTheta*Math.PI/180)).toFixed(3)} m`, c: 'text-gray-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {topic === 'physical' && [\n                    { l: 'I (about pivot)', v: `${physI.toFixed(4)} kg·m²`, c: 'text-indigo-600' },\n                    { l: 'Period (physical)', v: `${physT_actual.toFixed(3)} s`, c: 'text-emerald-600' },\n                    { l: 'Period (simple, same L)', v: `${physT_simple.toFixed(3)} s`, c: 'text-amber-600' },\n                    { l: 'Equiv. simple length', v: `${(physI/(physM*physD)).toFixed(3)} m`, c: 'text-rose-500' },\n                    { l: 'Ratio T_phys/T_simple', v: `${(physT_actual/physT_simple).toFixed(3)}`, c: 'text-purple-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {topic === 'bifilar' && bifMode === 'bifilar' && [\n                    { l: 'I (rod)', v: `${(bifM*bifL**2/12).toFixed(4)} kg·m²`, c: 'text-indigo-600' },\n                    { l: 'Period T', v: `${bifT.toFixed(3)} s`, c: 'text-emerald-600' },\n                    { l: 'Frequency f', v: `${(1/bifT).toFixed(3)} Hz`, c: 'text-amber-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {topic === 'bifilar' && bifMode === 'cantilever' && [\n                    { l: 'Stiffness k', v: `${cantK.toFixed(0)} N/m`, c: 'text-indigo-600' },\n                    { l: 'Deflection δ', v: `${(cantDef*1000).toFixed(2)} mm`, c: 'text-emerald-600' },\n                    { l: 'Nat. frequency', v: `${(1/cantT).toFixed(2)} Hz`, c: 'text-amber-600' },\n                    { l: 'Period T', v: `${cantT.toFixed(3)} s`, c: 'text-rose-500' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n                </div>\n              </div>\n\n              {/* Curriculum */}\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            {/* Teacher notes + exercises */}\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[topic].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i+1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/refraction/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { OpticsCanvas, OpticsMode } from '@/components/simulation/OpticsCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { snellTheta2, criticalAngle, thinLensImage, lensPower } from '@/lib/physics/optics';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<OpticsMode, { title: string; icon: string; sub: string; eq: string }> = {\n  snell:  { title: 'Refraction', icon: '💠', sub: 'Light crossing a boundary', eq: 'n₁ sinθ₁ = n₂ sinθ₂' },\n  lens:   { title: 'Lenses',     icon: '🔍', sub: 'Convex & concave',          eq: '1/f = 1/u + 1/v' },\n};\n\nconst PRESETS = [\n  { label: 'Air → Glass', n1: 1.0, n2: 1.5 },\n  { label: 'Air → Water', n1: 1.0, n2: 1.33 },\n  { label: 'Glass → Air', n1: 1.5, n2: 1.0 },\n  { label: 'Water → Air', n1: 1.33, n2: 1.0 },\n  { label: 'Diamond → Air', n1: 2.42, n2: 1.0 },\n];\n\nconst TEACHER_NOTES: Record<OpticsMode, string[]> = {\n  snell: [\n    'Into a DENSER medium (n₂ > n₁): light bends TOWARDS the normal. Into a less dense medium: away from it.',\n    'The critical angle only exists going dense → less dense; sinθc = n₂/n₁.',\n    'Beyond θc, ALL light reflects: total internal reflection — the basis of optical fibres and diamond sparkle.',\n    'Refractive index n = c/v = sinθ₁/sinθ₂ = real depth / apparent depth (three exam definitions of the same thing).',\n    'Diamond → air: θc ≈ 24.4° — tiny, which is why diamonds trap and bounce light so much.',\n  ],\n  lens: [\n    'Real-is-positive convention: f > 0 for converging (convex), f < 0 for diverging (concave). WAEC/IGCSE mark schemes use this.',\n    'Convex lens: object beyond 2F → diminished real image; between F and 2F → magnified real image; inside F → magnified virtual (magnifying glass).',\n    'A concave lens ALWAYS gives a virtual, upright, diminished image regardless of object position.',\n    'Two principal rays fix the image: parallel-to-axis (bends through F) and through the optical centre (undeviated).',\n    'Lens power P = 1/f (f in metres), unit dioptre — opticians add powers of lenses in contact.',\n  ],\n};\n\nconst EXERCISES: Record<OpticsMode, { q: string; a: string }[]> = {\n  snell: [\n    { q: 'Light passes from air into glass (n=1.5) at 45°. Find the angle of refraction.', a: 'sinθ₂ = sin45°/1.5 = 0.707/1.5 = 0.471 → θ₂ = 28.1°.' },\n    { q: 'Find the critical angle for water (n=1.33) to air.', a: 'sinθc = 1/1.33 = 0.752 → θc = 48.8°.' },\n    { q: 'Light travels at 3×10⁸ m/s in air. Find its speed in glass of n=1.5.', a: 'v = c/n = 3×10⁸/1.5 = 2×10⁸ m/s.' },\n  ],\n  lens: [\n    { q: 'An object 30cm from a convex lens of f=20cm. Find the image position and magnification.', a: '1/v = 1/20 − 1/30 = 1/60 → v = 60cm (real). m = v/u = 2 (magnified, inverted).' },\n    { q: 'An object 10cm from a convex lens of f=15cm. Describe the image.', a: '1/v = 1/15 − 1/10 = −1/30 → v = −30cm: virtual, upright, m=3 — a magnifying glass.' },\n    { q: 'Find the power of a converging lens with f = 25cm.', a: 'P = 1/f = 1/0.25 = +4 dioptres.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function RefractionPage() {\n  const [mode, setMode] = useState<OpticsMode>('snell');\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [n1, setN1] = useState(1.0);\n  const [n2, setN2] = useState(1.5);\n  const [theta1, setTheta1] = useState(35);\n  const [focal, setFocal] = useState(15);\n  const [objectDist, setObjectDist] = useState(40);\n  const [converging, setConverging] = useState(true);\n\n  const t2 = snellTheta2(n1, n2, theta1);\n  const critAng = criticalAngle(n1, n2);\n  const f = converging ? focal : -focal;\n  const img = thinLensImage(objectDist, f);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 320, 980);\n\n  useTopicPreset(\"simulations-refraction\", { \"theta1\": setTheta1,\n    \"n1\": setN1,\n    \"n2\": setN2,\n    \"focal\": setFocal,\n    \"objectDist\": setObjectDist }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Optics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Refraction &amp; lenses</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as OpticsMode[]).map(m => (\n              <button key={m} onClick={() => { setMode(m); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span><span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{MODE_META[mode].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{MODE_META[mode].eq}</span>\n            {mode !== 'snell' && <span className=\"text-xs text-gray-400 ml-2\">m = v/u · real is positive</span>}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <OpticsCanvas mode={mode} n1={n1} n2={n2} theta1={theta1}\n                  focal={focal} objectDist={objectDist} converging={converging}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"extra\" className=\"flex flex-wrap items-center justify-end gap-2\">\n                <EmbedButton path=\"/embed/optics\"\n                  title={`${MODE_META[mode].title} — A-Factor STEM Studio`}\n                  params={{ mode, n1, n2, theta1, focal, u: objectDist, conv: converging ? 1 : 0 }} />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {mode === 'snell' && <>\n                  <div className=\"flex flex-wrap gap-1.5\">\n                    {PRESETS.map(p => (\n                      <button key={p.label} onClick={() => { setN1(p.n1); setN2(p.n2); }}\n                        className={`rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n                          n1 === p.n1 && n2 === p.n2\n                            ? 'border-indigo-300 bg-indigo-50 text-indigo-700'\n                            : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'\n                        }`}>{p.label}</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Angle of incidence θ₁\" unit=\"°\" value={theta1} min={0} max={89} step={1} set={setTheta1} color=\"#6366f1\"\n                    note={critAng !== null ? `Critical angle θc = ${critAng.toFixed(1)}° — push θ₁ past it for TIR` : undefined} />\n                  <Slider label=\"n₁ (top medium)\" unit=\"\" value={n1} min={1} max={2.5} step={0.01} set={setN1} color=\"#f59e0b\" />\n                  <Slider label=\"n₂ (bottom medium)\" unit=\"\" value={n2} min={1} max={2.5} step={0.01} set={setN2} color=\"#10b981\" />\n                </>}\n\n                {mode !== 'snell' && <>\n                  <div className=\"space-y-1.5\">\n                    <span className=\"text-xs text-gray-500\">Type</span>\n                    <div className=\"flex gap-2\">\n                      {([true, false] as const).map(c => (\n                        <button key={String(c)} onClick={() => setConverging(c)}\n                          className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                            converging === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                          }`}>\n                          {c ? 'Convex (converging)' : 'Concave (diverging)'}\n                        </button>\n                      ))}\n                    </div>\n                  </div>\n                  <Slider label=\"Focal length |f|\" unit=\"cm\" value={focal} min={5} max={40} step={1} set={setFocal} color=\"#f59e0b\" />\n                  <Slider label=\"Object distance u\" unit=\"cm\" value={objectDist} min={5} max={90} step={1} set={setObjectDist} color=\"#6366f1\"\n                    note=\"Slide the object through 2F, F and inside F — watch the image flip\" />\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {mode === 'snell' && <>\n                    <StatRow label=\"Angle of refraction θ₂\" value={t2 === null ? 'TIR' : t2.toFixed(1)} unit={t2 === null ? '' : '°'} color=\"text-indigo-600\" />\n                    <StatRow label=\"Critical angle θc\" value={critAng === null ? '—' : critAng.toFixed(1)} unit={critAng === null ? '' : '°'} color=\"text-emerald-600\" />\n                    <StatRow label=\"n₂/n₁ ratio\" value={(n2 / n1).toFixed(3)} unit=\"\" color=\"text-amber-600\" />\n                    <StatRow label=\"Bends\" value={t2 === null ? 'reflects fully' : n2 > n1 ? 'towards normal' : 'away from normal'} unit=\"\" color=\"text-rose-500\" />\n                  </>}\n                  {mode !== 'snell' && <>\n                    <StatRow label=\"Image distance v\" value={img.atInfinity ? '∞' : Math.abs(img.v).toFixed(1)} unit={img.atInfinity ? '' : 'cm'} color=\"text-indigo-600\" />\n                    <StatRow label=\"Magnification m\" value={img.atInfinity ? '∞' : img.m.toFixed(2)} unit=\"×\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Nature\" value={img.atInfinity ? 'at infinity' : img.real ? 'real' : 'virtual'} unit=\"\" color=\"text-amber-600\" />\n                    <StatRow label=\"Orientation\" value={img.atInfinity ? '—' : img.inverted ? 'inverted' : 'upright'} unit=\"\" color=\"text-rose-500\" />\n                    {mode === 'lens' && (\n                      <StatRow label=\"Power\" value={lensPower(f / 100).toFixed(2)} unit=\"D\" color=\"text-purple-600\" />\n                    )}\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[mode].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/diffraction/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { DiffractionCanvas, DiffractionMode } from '@/components/simulation/DiffractionCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { firstMinimumAngle, spreadFraction, maxGratingOrder, fringeSpacing, maxFringeOrder } from '@/lib/physics/diffraction';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<DiffractionMode, { title: string; icon: string; sub: string; eq: string }> = {\n  'single-slit': { title: 'Single slit', icon: '🌊', sub: 'Spreading through a gap', eq: 'sinθ = λ/a' },\n  grating:       { title: 'Diffraction grating', icon: '🎨', sub: 'Multiple slits — spectral orders', eq: 'd sinθ = nλ' },\n  'double-slit': { title: \"Young's double slit\", icon: '〰️', sub: 'Interference — bright & dark fringes', eq: 'Δy = λD/d' },\n};\n\nconst TEACHER_NOTES: Record<DiffractionMode, string[]> = {\n  'single-slit': [\n    'Diffraction is the spreading of a wave as it passes through a gap or around an edge — it happens to ALL waves (sound, water, light), not just light.',\n    'The amount of spreading depends on the ratio λ/a (wavelength ÷ gap width). When the gap is comparable to or smaller than the wavelength, spreading is dramatic; when the gap is much bigger than the wavelength, the wave carries on mostly straight through.',\n    'This is why you can hear someone through an open doorway even when you can\\u2019t see them — sound wavelengths (metres) are comparable to doorway widths, so sound diffracts strongly, while light wavelengths (hundreds of nanometres) are far too small to diffract noticeably at that gap.',\n    'The first minimum either side of the central bright band occurs at sinθ = λ/a — this is the standard single-slit diffraction formula at this level.',\n    'Diffraction is direct evidence that light behaves as a WAVE — a stream of simple particles travelling in straight lines would never spread out behind a gap.',\n  ],\n  grating: [\n    'A diffraction grating is many equally-spaced slits close together. Light from every slit interferes, producing sharp, bright fringes only at specific angles — far sharper than a single or double slit.',\n    'Grating equation: d·sinθ = nλ, where d is the spacing between adjacent slits and n is the \"order\" (0, ±1, ±2, …).',\n    'The n=0 order is undeviated (straight through, θ=0°) for ANY wavelength — this is why the central fringe of white light through a grating is white, not spread into a spectrum.',\n    'Because sinθ depends on λ, different colours diffract to different angles for the same order — this is how gratings are used to split light into a spectrum in a spectrometer.',\n    'Gratings with more lines per millimetre have a SMALLER slit spacing d, which — from the grating equation — spreads the orders out to LARGER angles.',\n  ],\n  'double-slit': [\n    'Young\\u2019s double-slit experiment (1801) was the first strong evidence that light behaves as a wave — only overlapping waves can interfere, and interference is exactly what the alternating bright/dark fringes show.',\n    'Two coherent slits (same frequency, constant phase relationship) illuminated by a single source act as two synchronised wave sources. Where a crest meets a crest (or trough meets trough), the waves add — constructive interference, a bright fringe. Where a crest meets a trough, they cancel — destructive interference, a dark fringe.',\n    'Fringe spacing formula: Δy = λD/d, where D is the slit-to-screen distance and d is the slit separation — every bright band sits this far from its neighbour, regardless of order.',\n    'A SMALLER slit separation d gives WIDER-spaced fringes (easier to see individually); a LARGER d packs the fringes closer together.',\n    'This is genuinely the same physics as the diffraction grating (many slits) — a grating just uses many more slits, which sharpens the bright fringes into much narrower, more precisely-located lines.',\n  ],\n};\n\nconst EXERCISES: Record<DiffractionMode, { q: string; a: string }[]> = {\n  'single-slit': [\n    { q: 'Light of wavelength 600nm passes through a slit of width 1200nm. Find the angle to the first minimum.', a: 'sinθ = λ/a = 600/1200 = 0.5 → θ = 30°.' },\n    { q: 'Explain why radio waves diffract strongly around hills but light does not.', a: 'Radio wavelengths can be metres to kilometres long — comparable to or bigger than a hill — so they diffract strongly. Light wavelengths (~500nm) are millions of times smaller than a hill, so diffraction around it is negligible.' },\n    { q: 'A slit is made narrower while the wavelength stays the same. What happens to the diffraction pattern?', a: 'The λ/a ratio increases, so the central maximum and the angle to the first minimum both get WIDER — more spreading.' },\n  ],\n  grating: [\n    { q: 'A grating has 400 lines per millimetre. Find the slit spacing d in nanometres.', a: 'd = 1mm/400 = 1/400 mm = 2500nm.' },\n    { q: 'Using d=2000nm and λ=500nm, find the angle of the first-order (n=1) maximum.', a: 'sinθ = nλ/d = 500/2000 = 0.25 → θ = 14.5°.' },\n    { q: 'Why does white light passed through a grating produce a spectrum at each order (except n=0)?', a: 'Each wavelength satisfies d sinθ = nλ at a different angle θ (since λ differs), so red, green, blue etc. all diffract to slightly different angles for the same order, spreading white light into its component colours — except at n=0, where sinθ=0 works for every λ, so all colours overlap and stay white.' },\n  ],\n  'double-slit': [\n    { q: 'In a double-slit experiment, λ=600nm, the slits are 0.5mm apart, and the screen is 1.2m away. Find the fringe spacing.', a: 'Δy = λD/d = (600×10⁻⁹ × 1.2) / (0.5×10⁻³) = 1.44×10⁻³ m = 1.44mm.' },\n    { q: 'The slit separation in a double-slit experiment is halved, with everything else unchanged. What happens to the fringe spacing?', a: 'Δy = λD/d, so halving d DOUBLES the fringe spacing — the bright and dark bands spread further apart.' },\n    { q: 'Explain, in terms of path difference, why a bright fringe forms at a point equidistant from both slits.', a: 'At that point the path difference is zero, so light from both slits arrives exactly in phase (crest meets crest) — constructive interference, giving the bright central fringe.' },\n    { q: 'Why must the two slits be illuminated by light from the SAME single source, rather than two separate identical lamps?', a: 'Interference needs a constant, unchanging phase relationship between the two waves (coherence). Two separate lamps emit light with random, constantly-shifting phase relative to each other, so any interference pattern would wash out instantly rather than staying fixed and visible.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function DiffractionPage() {\n  const [mode, setMode] = useState<DiffractionMode>('single-slit');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [wavelengthNm, setWavelengthNm] = useState(550);\n  const [slitWidthNm, setSlitWidthNm] = useState(1000);\n  const [slitSpacingNm, setSlitSpacingNm] = useState(2000);\n  const [doubleSlitSepUm, setDoubleSlitSepUm] = useState(500); // micrometres — realistic double-slit scale (0.2-1mm)\n  const doubleSlitSepNm = doubleSlitSepUm * 1000;\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, wavelengthNm, slitWidthNm, slitSpacingNm, doubleSlitSepUm, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 300, 980);\n\n  const minAngle = firstMinimumAngle(wavelengthNm, slitWidthNm);\n  const spread = spreadFraction(wavelengthNm, slitWidthNm);\n  const maxOrder = maxGratingOrder(wavelengthNm, slitSpacingNm);\n  const maxFringeN = maxFringeOrder(wavelengthNm, doubleSlitSepNm);\n\n  useTopicPreset(\"simulations-diffraction\", { \"wavelengthNm\": setWavelengthNm,\n    \"slitWidthNm\": setSlitWidthNm,\n    \"slitSpacingNm\": setSlitSpacingNm,\n    \"doubleSlitSepUm\": setDoubleSlitSepUm }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Waves</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Diffraction</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as DiffractionMode[]).map(m => (\n              <button key={m} onClick={() => { setMode(m); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span><span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{MODE_META[mode].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{MODE_META[mode].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <DiffractionCanvas key={resetKey} mode={mode} wavelengthNm={wavelengthNm} slitWidthNm={slitWidthNm} slitSpacingNm={slitSpacingNm}\n                  doubleSlitSepNm={doubleSlitSepNm}\n                  isRunning={isRunning} isPaused={isPaused}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/diffraction\"\n                  title={`${MODE_META[mode].title} — A-Factor STEM Studio`}\n                  params={{ mode, wavelength: wavelengthNm, width: slitWidthNm, spacing: slitSpacingNm, sep: doubleSlitSepNm }} />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <Slider label=\"Wavelength\" unit=\"nm\" value={wavelengthNm} min={400} max={700} step={10} set={setWavelengthNm} color=\"#6366f1\" note=\"Visible light range\" />\n                {mode === 'single-slit' && (\n                  <Slider label=\"Slit width (a)\" unit=\"nm\" value={slitWidthNm} min={200} max={3000} step={50} set={setSlitWidthNm} color=\"#f59e0b\"\n                    note=\"Narrower slit (or longer wavelength) → more spreading\" />\n                )}\n                {mode === 'grating' && (\n                  <Slider label=\"Slit spacing (d)\" unit=\"nm\" value={slitSpacingNm} min={500} max={5000} step={50} set={setSlitSpacingNm} color=\"#f59e0b\"\n                    note=\"Smaller spacing → orders spread to wider angles\" />\n                )}\n                {mode === 'double-slit' && (\n                  <Slider label=\"Slit separation (d)\" unit=\"μm\" value={doubleSlitSepUm} min={200} max={1000} step={10} set={setDoubleSlitSepUm} color=\"#f59e0b\"\n                    note=\"Smaller separation → wider-spaced fringes\" />\n                )}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {mode === 'single-slit' && <>\n                    <StatRow label=\"λ/a ratio\" value={(wavelengthNm / slitWidthNm).toFixed(3)} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"First minimum\" value={minAngle === null ? 'none (λ>a)' : minAngle.toFixed(1)} unit={minAngle === null ? '' : '°'} color=\"text-emerald-600\" />\n                    <StatRow label=\"Spread fraction\" value={(spread * 100).toFixed(0)} unit=\"%\" color=\"text-amber-600\" />\n                  </>}\n                  {mode === 'grating' && <>\n                    <StatRow label=\"Max order visible\" value={`±${maxOrder}`} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"n=1 angle\" value={maxOrder >= 1 ? (Math.asin(wavelengthNm / slitSpacingNm) * 180 / Math.PI).toFixed(1) : '—'} unit={maxOrder >= 1 ? '°' : ''} color=\"text-emerald-600\" />\n                    <StatRow label=\"Lines per mm\" value={(1e6 / slitSpacingNm).toFixed(0)} unit=\"\" color=\"text-purple-600\" />\n                  </>}\n                  {mode === 'double-slit' && <>\n                    <StatRow label=\"Fringe spacing (D=1m)\" value={(fringeSpacing(wavelengthNm * 1e-9, doubleSlitSepNm * 1e-9, 1) * 1000).toFixed(2)} unit=\"mm\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Max order (this scale)\" value={`±${maxFringeN}`} unit=\"\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Nature\" value=\"constructive/destructive interference\" unit=\"\" color=\"text-purple-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[mode].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/projectile-motion/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef, useMemo } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { PromptBar } from '@/components/ai/PromptBar';\nimport { ProjectileModeCanvas, ProjectileMode } from '@/components/simulation/ProjectileModeCanvas';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport type { AIPromptResponse } from '@/types/ai';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport {\n  standardAnalytics, horizontalAnalytics, verticalAnalytics, inclinedAnalytics,\n  StandardParams, HorizontalParams, VerticalParams, InclinedParams,\n} from '@/lib/physics/projectile-modes';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<ProjectileMode, { title: string; icon: string; sub: string; eqs: string[] }> = {\n  standard:   { title: 'Standard', icon: '🎯', sub: 'Angle θ, optional height h', eqs: ['R = vₓ × T', 'H = h + vy₀²/2g'] },\n  horizontal: { title: 'Horizontal', icon: '🏗️', sub: 'Launched horizontally from height', eqs: ['t = √(2h/g)', 'R = v₀t'] },\n  vertical:   { title: 'Vertical', icon: '⬆️', sub: 'Thrown up/down or dropped', eqs: ['H_max = h₀ + v₀²/2g', 't = v₀/g'] },\n  inclined:   { title: 'Inclined', icon: '📐', sub: 'Launched along a slope β', eqs: ['t = 2v₀sinα/gcosβ'] },\n};\n\nconst TEACHER_NOTES: Record<ProjectileMode, string[]> = {\n  standard: [\n    'vx is constant throughout — no horizontal force acts on the projectile.',\n    'When h₀ > 0, the optimal angle for max range drops below 45°.',\n    'Complementary angles give equal range only when launched from ground level.',\n    'Platform height slider — drag it up to simulate a cliff or tall building.',\n    'Use the gravity slider to explore projectile behaviour on the Moon (1.6 m/s²) or Mars (3.7 m/s²).',\n  ],\n  horizontal: [\n    'Horizontal projection: initial vertical velocity is ZERO. Only horizontal speed is given at launch.',\n    'Time of flight depends only on height — t = √(2h/g). Horizontal speed does not affect fall time.',\n    'The landing velocity always has a downward component: v_land = √(v₀² + (gt)²).',\n    'Classic exam scenario: stone thrown from a cliff, ball rolling off a table, bomb from a horizontal aircraft.',\n    'The path curves — it starts horizontal and steepens continuously until landing.',\n  ],\n  vertical: [\n    'Pure vertical motion — no horizontal displacement at all.',\n    'At maximum height, vy = 0. Time to reach max = v₀/g.',\n    'Symmetry: time rising = time falling (when returning to same height).',\n    'Set v₀ = 0 and h₀ > 0 for free fall. Set v₀ negative for a downward throw.',\n    'Landing speed: v = √(v₀² + 2gh₀) — same regardless of direction of initial throw from same height.',\n  ],\n  inclined: [\n    'Key insight: resolve gravity into components along the slope (g sinβ) and perpendicular (g cosβ).',\n    'The effective gravity perpendicular to slope is g cosβ — less than g, so flight time is longer than on flat ground.',\n    'Optimal launch angle for max range along slope = 45° − β/2, not 45°.',\n    'Range along slope ≠ horizontal range — understand which the exam question is asking for.',\n    'This is one of the hardest WAEC/IGCSE topics: always set up axes along and perpendicular to the slope.',\n    'Down-the-slope launch: same flight time t = 2v₀sinα/(g cosβ), but g sinβ now ACCELERATES the motion, so the range along the slope is longer than the same launch going up.',\n  ],\n};\n\nconst EXERCISES: Record<ProjectileMode, { q: string; a: string }[]> = {\n  standard: [\n    { q: 'A ball is thrown at 25 m/s at 37° from a 20m building. Find the range. (g = 10 m/s², sin37°=0.6, cos37°=0.8)', a: 'vx=20, vy₀=15. Solve 20+15t−5t²=0 → t≈3+, R=20×3.56=71.2m' },\n    { q: 'Complementary angles 30° and 60° give the same range. Does this still hold when launched from a height?', a: 'No — when h₀ > 0 the symmetry breaks. The ball launched at the shallower angle has more horizontal time and travels farther.' },\n    { q: 'Find the angle for max range when v₀=20 m/s from a 15m platform. (g=10 m/s²)', a: 'The optimal angle is less than 45° and requires calculus or numerical methods. Try angles around 38°–42° in the simulator.' },\n  ],\n  horizontal: [\n    { q: 'A stone is thrown horizontally at 12 m/s from a 45m cliff. Find range and landing speed. (g=10 m/s²)', a: 't=√(2×45/10)=3s. R=12×3=36m. vy=gt=30m/s. v=√(144+900)=√1044≈32.3m/s' },\n    { q: 'A ball rolls off a 1.25m table and lands 2m away. Find its speed at the table edge. (g=10 m/s²)', a: 't=√(2×1.25/10)=0.5s. v₀=R/t=2/0.5=4m/s' },\n    { q: 'Why does doubling the horizontal speed double the range but not the time of flight?', a: 'Time depends only on height (t=√(2h/g)) which is unchanged. With double speed, the ball covers twice the horizontal distance in the same time.' },\n  ],\n  vertical: [\n    { q: 'A ball is thrown upward at 30 m/s from the ground. Find max height and total flight time. (g=10 m/s²)', a: 'H=v²/2g=900/20=45m. t_up=30/10=3s. Total=6s.' },\n    { q: 'A ball is dropped from 80m. Find speed at impact. (g=10 m/s²)', a: 'v=√(2gh)=√(2×10×80)=√1600=40 m/s' },\n    { q: 'A ball thrown upward at 20 m/s from a 30m tower. Find max height above ground. (g=10 m/s²)', a: 'H_above_launch=v²/2g=400/20=20m. Max above ground=30+20=50m.' },\n  ],\n  inclined: [\n    { q: 'v₀=20 m/s, α=30° above slope, β=30° slope. Find time of flight. (g=10 m/s²)', a: 't=2v₀sinα/(gcosβ)=2×20×0.5/(10×0.866)=20/8.66≈2.31s' },\n    { q: 'At what α is range along slope maximised when β=30°?', a: 'Optimal α = 45° − β/2 = 45° − 15° = 30° above the slope surface.' },\n    { q: 'Why is range along slope different from horizontal range?', a: 'The landing point is on the slope, higher than the foot of the incline. Slope range = distance along the surface; horizontal range = horizontal distance only.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))}\n        className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: number | string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-sm font-semibold tabular-nums ${color}`}>\n        {typeof value === 'number' ? value.toFixed(2) : value}\n        <span className=\"text-xs font-normal text-gray-400 ml-1\">{unit}</span>\n      </span>\n    </div>\n  );\n}\n\nexport default function ProjectileMotionPage() {\n  const [mode, setMode] = useState<ProjectileMode>('standard');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [isComplete, setIsComplete] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n  const [livePos, setLivePos] = useState({ t: 0, x: 0, y: 0 });\n\n  // Params\n  const [v0, setV0] = useState(25); const [angle, setAngle] = useState(45);\n  const [g, setG] = useState(9.81); const [h0, setH0] = useState(0);\n  const [hV0, setHV0] = useState(20); const [hH, setHH] = useState(30);\n  const [vV0, setVV0] = useState(15); const [vH0, setVH0] = useState(0);\n  const [iV0, setIV0] = useState(20); const [iAlpha, setIAlpha] = useState(30); const [iBeta, setIBeta] = useState(30);\n  const [iLaunchFrom, setILaunchFrom] = useState<'base' | 'top'>('base');\n\n  // Memoized so these keep a stable object identity across renders that don't\n  // actually change their values (e.g. the per-frame re-render from handleTick\n  // updating livePos). Without this, ProjectileModeCanvas sees a \"new\" params\n  // object on every animation frame and resets itself mid-flight.\n  const std: StandardParams   = useMemo(() => ({ v0, angle, g, h0 }), [v0, angle, g, h0]);\n  const hrz: HorizontalParams = useMemo(() => ({ v0: hV0, h: hH, g }), [hV0, hH, g]);\n  const vtc: VerticalParams   = useMemo(() => ({ v0: vV0, h0: vH0, g }), [vV0, vH0, g]);\n  const inc: InclinedParams   = useMemo(\n    () => ({ v0: iV0, alpha: iAlpha, beta: iBeta, g, launchFrom: iLaunchFrom }),\n    [iV0, iAlpha, iBeta, g, iLaunchFrom]\n  );\n\n  const stdA = standardAnalytics(std);\n  const hrzA = horizontalAnalytics(hrz);\n  const vtcA = verticalAnalytics(vtc);\n  const incA = inclinedAnalytics(inc);\n\n  // Debounced reset on param change\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setIsComplete(false); setResetKey(k => k + 1);\n    setLivePos({ t: 0, x: 0, y: 0 });\n  }, []);\n\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [mode, v0, angle, g, h0, hV0, hH, vV0, vH0, iV0, iAlpha, iBeta, iLaunchFrom, reset]);\n\n  const handleTick = useCallback((t: number, x: number, y: number) => setLivePos({ t, x, y }), []);\n  const handleComplete = useCallback(() => { setIsComplete(true); setIsRunning(false); }, []);\n  const handleAIResult = useCallback((r: AIPromptResponse) => {\n    if (r.simulationType === 'projectile_motion') {\n      const p = r.params as Record<string, number>;\n      if (p.initialVelocity) setV0(p.initialVelocity);\n      if (p.angle) setAngle(p.angle);\n      if (p.gravity) setG(p.gravity);\n      if (p.h0) setH0(p.h0);\n      setMode('standard');\n    }\n    setTimeout(reset, 100);\n  }, [reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 290, 980);\n\n  useTopicPreset(\"simulations-projectile-motion\", { \"g\": setG,\n    \"v0\": setV0,\n    \"angle\": setAngle,\n    \"h0\": setH0,\n    \"hV0\": setHV0,\n    \"hH\": setHH,\n    \"vV0\": setVV0,\n    \"vH0\": setVH0,\n    \"iV0\": setIV0,\n    \"iAlpha\": setIAlpha,\n    \"iBeta\": setIBeta }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n\n        {/* Page header */}\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Mechanics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Projectile motion</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n\n          {/* AI prompt */}\n          <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n            <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">AI prompt</p>\n            <PromptBar onResult={handleAIResult} />\n          </div>\n\n          {/* Mode tabs */}\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as ProjectileMode[]).map(m => (\n              <button key={m} onClick={() => setMode(m)}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span>\n                <span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          {/* Sub + equations */}\n          <div className=\"flex flex-wrap items-center gap-2\">\n            <span className=\"text-xs text-gray-500\">{MODE_META[mode].sub}</span>\n            {MODE_META[mode].eqs.map(eq => (\n              <span key={eq} className=\"rounded-lg border border-gray-200 bg-white px-2.5 py-2 text-xs font-mono text-gray-700\">{eq}</span>\n            ))}\n          </div>\n\n          {/* ── MOBILE: stack everything; DESKTOP: 3-col ── */}\n          <SimulationStage className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n\n            {/* Col 1: canvas + controls */}\n            <div data-stage-role=\"canvas\" className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <ProjectileModeCanvas\n                  key={resetKey}\n                  mode={mode}\n                  standard={std} horizontal={hrz} vertical={vtc} inclined={inc}\n                  isRunning={isRunning} isPaused={isPaused}\n                  onTick={handleTick} onComplete={handleComplete}\n                  width={canvasSize.width} height={canvasSize.height}\n                />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls\n                  isRunning={isRunning && !isComplete} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); setIsComplete(false); }}\n                  onPause={() => setIsPaused(p => !p)}\n                  onReset={reset}\n                />\n                <div className=\"flex items-center gap-2\">\n                  {isComplete && <span className=\"text-xs font-medium text-emerald-600\">✓ Complete — Reset to go again</span>}\n                  <EmbedButton\n                    path=\"/embed/projectile\"\n                    title={`Projectile motion (${mode}) — A-Factor STEM Studio`}\n                    params={\n                      mode === 'standard'   ? { mode, v0, angle, g, h0 } :\n                      mode === 'horizontal' ? { mode, v0: hV0, h: hH, g } :\n                      mode === 'vertical'   ? { mode, v0: vV0, h0: vH0, g } :\n                      { mode, v0: iV0, alpha: iAlpha, beta: iBeta, g, launch: iLaunchFrom }\n                    }\n                  />\n                </div>\n              </div>\n            </div>\n\n            {/* Col 2: parameters + analytics */}\n            <div data-stage-role=\"parameters\" className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <Slider label=\"Gravity\" unit=\"m/s²\" value={g} min={1} max={25} step={0.1} set={setG} color=\"#10b981\" />\n\n                {mode === 'standard' && <>\n                  <Slider label=\"Initial velocity\" unit=\"m/s\" value={v0} min={1} max={100} step={1} set={setV0} color=\"#6366f1\" />\n                  <Slider label=\"Launch angle\" unit=\"°\" value={angle} min={1} max={89} step={1} set={setAngle} color=\"#f59e0b\" />\n                  <Slider label=\"Platform height\" unit=\"m\" value={h0} min={0} max={120} step={1} set={setH0} color=\"#8b5cf6\" note=\"0 = ground level\" />\n                </>}\n\n                {mode === 'horizontal' && <>\n                  <Slider label=\"Horizontal speed\" unit=\"m/s\" value={hV0} min={1} max={100} step={1} set={setHV0} color=\"#6366f1\" />\n                  <Slider label=\"Launch height\" unit=\"m\" value={hH} min={1} max={200} step={1} set={setHH} color=\"#8b5cf6\" />\n                </>}\n\n                {mode === 'vertical' && <>\n                  <Slider label=\"Initial velocity (↑ positive)\" unit=\"m/s\" value={vV0} min={-30} max={50} step={1} set={setVV0} color=\"#6366f1\" note=\"Negative = thrown downward\" />\n                  <Slider label=\"Initial height\" unit=\"m\" value={vH0} min={0} max={200} step={1} set={setVH0} color=\"#8b5cf6\" />\n                </>}\n\n                {mode === 'inclined' && <>\n                  <div className=\"space-y-1.5\">\n                    <span className=\"text-xs text-gray-500\">Launched from</span>\n                    <div className=\"flex gap-2\">\n                      {(['base', 'top'] as const).map(v => (\n                        <button key={v} onClick={() => setILaunchFrom(v)}\n                          className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                            iLaunchFrom === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                          }`}>\n                          {v === 'base' ? 'Base — up the slope' : 'Top — down the slope'}\n                        </button>\n                      ))}\n                    </div>\n                    <p className=\"text-[10px] text-gray-400\">\n                      {iLaunchFrom === 'base'\n                        ? 'Launched up the slope at α above the surface — lands back on the incline. Gravity component g sinβ decelerates it along the slope.'\n                        : 'Launched down the slope at α above the surface — lands at the base of the incline. Gravity component g sinβ accelerates it along the slope, so it travels farther than the same launch going up.'}\n                    </p>\n                  </div>\n                  <Slider label=\"Initial velocity\" unit=\"m/s\" value={iV0} min={1} max={60} step={1} set={setIV0} color=\"#6366f1\" />\n                  <Slider label=\"α — angle above slope\" unit=\"°\" value={iAlpha} min={1} max={89} step={1} set={setIAlpha} color=\"#f59e0b\" />\n                  <Slider label=\"β — slope angle\" unit=\"°\" value={iBeta} min={5} max={60} step={1} set={setIBeta} color=\"#ef4444\" />\n                </>}\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {mode === 'standard' && <>\n                    <StatRow label=\"Time of flight\" value={stdA.tFlight} unit=\"s\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Max range\" value={stdA.range} unit=\"m\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Max height\" value={stdA.maxHeight} unit=\"m\" color=\"text-amber-600\" />\n                    <StatRow label=\"vx\" value={stdA.vx} unit=\"m/s\" color=\"text-gray-600\" />\n                    <StatRow label=\"vy₀\" value={stdA.vy0} unit=\"m/s\" color=\"text-rose-500\" />\n                  </>}\n                  {mode === 'horizontal' && <>\n                    <StatRow label=\"Time of flight\" value={hrzA.tFlight} unit=\"s\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Range\" value={hrzA.range} unit=\"m\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Landing speed\" value={hrzA.vLand} unit=\"m/s\" color=\"text-amber-600\" />\n                    <StatRow label=\"Landing angle\" value={hrzA.angleLand} unit=\"°↓\" color=\"text-rose-500\" />\n                  </>}\n                  {mode === 'vertical' && <>\n                    <StatRow label=\"Max height\" value={vtcA.maxHeight} unit=\"m\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Time to peak\" value={vtcA.timeToMax} unit=\"s\" color=\"text-amber-600\" />\n                    <StatRow label=\"Flight time\" value={vtcA.tFlight} unit=\"s\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Landing speed\" value={vtcA.vLand} unit=\"m/s\" color=\"text-rose-500\" />\n                  </>}\n                  {mode === 'inclined' && <>\n                    <StatRow label=\"Flight time\" value={incA.tFlight} unit=\"s\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Range along slope\" value={incA.rangeAlongIncline} unit=\"m\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Horizontal range\" value={incA.rangeHorizontal} unit=\"m\" color=\"text-amber-600\" />\n                    <StatRow label=\"Max height ⊥ slope\" value={incA.maxHeightAboveIncline} unit=\"m\" color=\"text-rose-500\" />\n                    <StatRow\n                      label={iLaunchFrom === 'top' ? 'Vertical drop' : 'Vertical rise'}\n                      value={incA.verticalDrop} unit=\"m\" color=\"text-purple-600\" />\n                  </>}\n                </div>\n              </div>\n\n              {livePos.t > 0 && (\n                <div className=\"rounded-2xl border border-indigo-100 bg-indigo-50 p-4\">\n                  <p className=\"text-xs font-medium text-indigo-400 uppercase tracking-wide mb-2\">Live</p>\n                  <div className=\"space-y-1.5\">\n                    {[\n                      { l: 't', v: livePos.t.toFixed(2), u: 's' },\n                      ...(mode !== 'vertical' ? [{ l: 'x', v: livePos.x.toFixed(1), u: 'm' }] : []),\n                      { l: 'y', v: livePos.y.toFixed(1), u: 'm' },\n                    ].map(r => (\n                      <div key={r.l} className=\"flex justify-between rounded-lg bg-white/70 px-3 py-2\">\n                        <span className=\"text-xs text-indigo-400 font-mono\">{r.l}</span>\n                        <span className=\"text-xs font-semibold text-indigo-700 tabular-nums\">{r.v} <span className=\"font-normal text-indigo-300\">{r.u}</span></span>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n              )}\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            {/* Col 3: teacher notes + exercises — full width on mobile, col on xl */}\n            <div data-stage-role=\"parameters\" className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[mode].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i+1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/bjt-transistor/page.tsx": "// src/app/simulations/bjt-transistor/page.tsx\n'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { TopicContext } from '@/components/explorer/TopicContext';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\n\nimport React, { useState, useCallback } from 'react';\nimport Link from 'next/link';\nimport BjtCanvas from '@/components/simulation/BjtCanvas';\nimport { BjtParams, getPreset, PRESET_NAMES, PRESET_LABELS, REGION_DESCRIPTIONS, TOPOLOGY_DESCRIPTIONS } from '@/lib/physics/bjtTransistor';\n\nexport default function BjtTransistorPage() {\n  const [params, setParams] = useState<BjtParams>(getPreset('ce-active'));\n  const [activePreset, setActivePreset] = useState('ce-active');\n\n  const applyPreset = useCallback((name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  }, []);\n\n  const updateParam = useCallback(<K extends keyof BjtParams>(key: K, value: BjtParams[K]) => {\n    setParams(prev => ({ ...prev, [key]: value }));\n    setActivePreset('custom');\n  }, []);\n\n  const region = params.Vbe < (params.material === 'Si' ? 0.5 : 0.2) ? 'cutoff' : params.Vbe - params.Vce < 0.3 ? 'active' : 'saturation';\n\n  useTopicPreset(\"simulations-bjt-transistor\", { \"params.Vcc\": (value: number) => setParams(current => ({ ...current, Vcc: value })),\n    \"params.Vbe\": (value: number) => setParams(current => ({ ...current, Vbe: value })),\n    \"params.Vce\": (value: number) => setParams(current => ({ ...current, Vce: value })),\n    \"params.Rb\": (value: number) => setParams(current => ({ ...current, Rb: value })),\n    \"params.Rc\": (value: number) => setParams(current => ({ ...current, Rc: value })),\n    \"params.Re\": (value: number) => setParams(current => ({ ...current, Re: value })),\n    \"params.Rload\": (value: number) => setParams(current => ({ ...current, Rload: value })),\n    \"params.beta\": (value: number) => setParams(current => ({ ...current, beta: value })),\n    \"params.temperature\": (value: number) => setParams(current => ({ ...current, temperature: value })) }, {  });\n  return (\n    <div className=\"af-device min-h-screen bg-slate-950 text-slate-100 flex flex-col\">\n      <header className=\"border-b border-slate-800 bg-slate-950/80 backdrop-blur-md sticky top-0 z-50\">\n        <div className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between\">\n          <div className=\"flex items-center gap-4\">\n            <Link href=\"/simulations\" className=\"text-slate-400 hover:text-slate-200 transition-colors text-sm font-medium\">← Simulations</Link>\n            <span className=\"text-slate-600\">|</span>\n            <h1 className=\"text-lg font-semibold text-slate-100\">BJT Transistor — Circuit Analysis</h1>\n          </div>\n          <div className=\"flex items-center gap-3\">\n            <span className=\"text-xs px-2 py-1 rounded-full bg-blue-500/10 text-blue-400 border border-blue-500/20\">Semiconductor Devices</span>\n            <span className=\"text-xs px-2 py-1 rounded-full bg-emerald-500/10 text-emerald-400 border border-emerald-500/20\">Live</span>\n          </div>\n        </div>\n      </header>\n      <TopicContext />\n\n      <main className=\"flex-1 p-6\">\n        <div className=\"max-w-6xl mx-auto\">\n          <p className=\"text-slate-400 mb-6\">\n            Explore BJT operating regions with real circuit topologies. Analyze Common-Emitter, Common-Collector, \n            and Common-Base amplifiers with load lines, gain calculations, and animated current flow.\n          </p>\n\n          <SimulationStage className=\"af-stage-dark grid grid-cols-1 lg:grid-cols-3 gap-6\">\n            <div data-stage-role=\"canvas\" className=\"lg:col-span-2\">\n              <BjtCanvas params={params} width={900} height={640} />\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-4\">\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold mb-3 text-sm uppercase tracking-wide text-slate-400\">Circuit Topology</h3>\n                <div className=\"grid grid-cols-3 gap-2\">\n                  {(['common-emitter', 'common-collector', 'common-base'] as const).map(top => (\n                    <button\n                      key={top}\n                      onClick={() => updateParam('topology', top)}\n                      className={`px-2 py-2 rounded text-xs font-medium transition-colors ${\n                        params.topology === top ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n                      }`}\n                    >\n                      {top === 'common-emitter' ? 'CE' : top === 'common-collector' ? 'CC' : 'CB'}\n                    </button>\n                  ))}\n                </div>\n                <p className=\"text-xs text-slate-500 mt-2\">{TOPOLOGY_DESCRIPTIONS[params.topology]}</p>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold mb-3 text-sm uppercase tracking-wide text-slate-400\">Presets</h3>\n                <div className=\"grid grid-cols-2 gap-2\">\n                  {PRESET_NAMES.map(name => (\n                    <button\n                      key={name}\n                      onClick={() => applyPreset(name)}\n                      className={`px-3 py-2 rounded text-sm font-medium transition-colors ${\n                        activePreset === name ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n                      }`}\n                    >\n                      {PRESET_LABELS[name]}\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700 space-y-4\">\n                <h3 className=\"font-semibold text-sm uppercase tracking-wide text-slate-400\">Parameters</h3>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Material</label>\n                  <select value={params.material} onChange={e => updateParam('material', e.target.value as BjtParams['material'])}\n                    className=\"w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-sm\">\n                    <option value=\"Si\">Silicon (Vbe ≈ 0.7V)</option>\n                    <option value=\"Ge\">Germanium (Vbe ≈ 0.3V)</option>\n                  </select>\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Supply Voltage (Vcc): {params.Vcc} V</label>\n                  <input type=\"range\" min=\"3\" max=\"20\" step=\"0.5\" value={params.Vcc}\n                    onChange={e => updateParam('Vcc', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Base-Emitter Voltage (Vbe): {params.Vbe.toFixed(2)} V</label>\n                  <input type=\"range\" min=\"0\" max=\"1.0\" step=\"0.01\" value={params.Vbe}\n                    onChange={e => updateParam('Vbe', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Collector-Emitter Voltage (Vce): {params.Vce.toFixed(1)} V</label>\n                  <input type=\"range\" min=\"0\" max=\"15\" step=\"0.1\" value={params.Vce}\n                    onChange={e => updateParam('Vce', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Base Resistor (Rb): {params.Rb} kΩ</label>\n                  <input type=\"range\" min=\"10\" max=\"500\" step=\"10\" value={params.Rb}\n                    onChange={e => updateParam('Rb', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Collector Resistor (Rc): {params.Rc} kΩ</label>\n                  <input type=\"range\" min=\"0.1\" max=\"10\" step=\"0.1\" value={params.Rc}\n                    onChange={e => updateParam('Rc', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Emitter Resistor (Re): {params.Re} kΩ</label>\n                  <input type=\"range\" min=\"0\" max=\"5\" step=\"0.1\" value={params.Re}\n                    onChange={e => updateParam('Re', parseFloat(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Load Resistor (Rload): {params.Rload} kΩ</label>\n                  <input type=\"range\" min=\"1\" max=\"50\" step=\"1\" value={params.Rload}\n                    onChange={e => updateParam('Rload', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Current Gain (β): {params.beta}</label>\n                  <input type=\"range\" min=\"20\" max=\"500\" step=\"10\" value={params.beta}\n                    onChange={e => updateParam('beta', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Temperature: {params.temperature} K</label>\n                  <input type=\"range\" min=\"200\" max=\"500\" step=\"10\" value={params.temperature}\n                    onChange={e => updateParam('temperature', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold text-sm uppercase tracking-wide text-slate-400 mb-2\">Teacher Notes</h3>\n                <div className=\"text-sm text-slate-300 space-y-2\">\n                  <p className=\"text-green-400 font-medium\">Region: {region.toUpperCase()}</p>\n                  <p>{REGION_DESCRIPTIONS[region]}</p>\n                  <p className=\"text-blue-400 font-medium text-xs uppercase mt-2\">{params.topology.replace(/-/g, ' ').toUpperCase()} Topology</p>\n                  <p className=\"text-xs\">{TOPOLOGY_DESCRIPTIONS[params.topology]}</p>\n                  \n                  <div className=\"mt-3 p-2 bg-slate-800 rounded border border-slate-700\">\n                    <p className=\"text-yellow-400 font-medium text-xs uppercase mb-1\">Practice Problem</p>\n                    {params.topology === 'common-emitter' && (\n                      <>\n                        <p className=\"text-xs\">A CE amplifier has Vcc = 12V, Rc = 2kΩ, Re = 0.5kΩ, β = 100, Vbe = 0.7V. The Q-point is set at Vce = 6V.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Find: (a) Ib, (b) Ic, (c) Rb needed, (d) Voltage gain with Rload = 10kΩ</p>\n                        <p className=\"text-xs text-slate-400 mt-1\">Answers: (a) 28.6μA, (b) 2.86mA, (c) 395kΩ, (d) Av ≈ -238</p>\n                      </>\n                    )}\n                    {params.topology === 'common-collector' && (\n                      <>\n                        <p className=\"text-xs\">An emitter follower has Vcc = 10V, Re = 2kΩ, β = 100, Vbe = 0.7V. Calculate the output voltage when Vin = 5V.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Find: (a) Ve, (b) Ie, (c) Voltage gain, (d) Why is this called a \"buffer\"?</p>\n                        <p className=\"text-xs text-slate-400 mt-1\">Answers: (a) 4.3V, (b) 2.15mA, (c) Av ≈ 0.99, (d) High Zin, low Zout — isolates stages</p>\n                      </>\n                    )}\n                    {params.topology === 'common-base' && (\n                      <>\n                        <p className=\"text-xs\">A CB amplifier has Ie = 2mA, Rc = 3kΩ, α = 0.99. The input resistance is 12.5Ω.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Find: (a) Ic, (b) Voltage gain, (c) Current gain, (d) Why is input Z so low?</p>\n                        <p className=\"text-xs text-slate-400 mt-1\">Answers: (a) 1.98mA, (b) Av ≈ 297, (c) Ai ≈ 0.99, (d) Input at emitter: re = VT/Ie ≈ 12.5Ω</p>\n                      </>\n                    )}\n                  </div>\n                  \n                  {params.beta > 200 && (\n                    <p className=\"text-xs\">High β means small base current controls large collector current — excellent for amplification but watch for thermal runaway.</p>\n                  )}\n                  {params.material === 'Ge' && (\n                    <p className=\"text-xs\">Germanium has lower Vbe (~0.3V) but higher leakage current (Ico doubles every 10°C vs every 6°C for Si).</p>\n                  )}\n                </div>\n              </div>\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n\n      <footer className=\"border-t border-slate-800 bg-slate-950 py-6\">\n        <div className=\"max-w-6xl mx-auto px-6 flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <p className=\"text-sm text-slate-500\">BJT Transistor Simulation — Circuit Analysis Engine</p>\n          <div className=\"flex items-center gap-4 text-sm text-slate-500\">\n            <Link href=\"/simulations\" className=\"hover:text-slate-300 transition-colors\">All Simulations</Link>\n            <Link href=\"/simulations/pn-junction\" className=\"hover:text-slate-300 transition-colors\">← PN Junction</Link>\n            <Link href=\"/simulations/mosfet\" className=\"hover:text-slate-300 transition-colors\">MOSFET →</Link>\n          </div>\n        </div>\n      </footer>\n    </div>\n  );\n}", "src/app/simulations/heat-transfer/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { HeatTransferCanvas, HeatMode } from '@/components/simulation/HeatTransferCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { celsiusToKelvin, radiatedPower, netRadiation, conductionRate, MATERIALS } from '@/lib/physics/heat';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<HeatMode, { title: string; icon: string; sub: string; eq: string }> = {\n  conduction: { title: 'Conduction', icon: '🔗', sub: 'Solids — particle to particle', eq: 'Q/t = kAΔT/L' },\n  convection: { title: 'Convection', icon: '🌀', sub: 'Fluids — bulk movement',        eq: 'warm rises, cool sinks' },\n  radiation:  { title: 'Radiation',  icon: '☀️', sub: 'EM waves — needs no medium',    eq: 'P = εσAT⁴' },\n};\n\nconst TEACHER_NOTES: Record<HeatMode, string[]> = {\n  conduction: [\n    'Particles do NOT travel down the rod — they vibrate in place and pass energy to their neighbours, like a row of people jiggling a rope.',\n    'Metals conduct well because free (delocalised) electrons carry energy quickly through the lattice; non-metals lack these free electrons.',\n    'Rate of heat flow: Q/t = kAΔT/L — bigger area or ΔT speeds it up, a thicker (longer) barrier slows it down. This is exactly why we use thick walls and small windows to keep buildings warm.',\n    'Compare copper (k≈385) with glass (k≈0.8): copper conducts about 480 times faster — try both in the material list.',\n    'Trapped air (double glazing, wool, fur) is a poor conductor and makes an excellent insulator, precisely because it has such a low k.',\n  ],\n  convection: [\n    'Unlike conduction, the medium ITSELF moves in convection — warm fluid expands, becomes less dense, and rises; cooler, denser fluid sinks to replace it, setting up a convection current.',\n    'This only happens in fluids (liquids and gases) — solids cannot flow, so they never convect.',\n    'Real examples: sea breezes (land heats faster than sea by day), the radiator in a room (warms air rises, circulates the whole room), boiling water in a pot.',\n    'Convection needs gravity (or an equivalent force) to drive the density difference — it does not work in free-fall / microgravity.',\n    'The hotter the source, the faster and more vigorous the circulation — watch the particle loop speed up as you raise the temperature.',\n  ],\n  radiation: [\n    'Radiation is the only mode of heat transfer that needs NO medium — infrared electromagnetic waves cross the vacuum of space, which is how the Sun warms the Earth.',\n    'Stefan–Boltzmann law: P = εσAT⁴ — power radiated depends on the FOURTH power of absolute temperature, so a small temperature rise causes a huge jump in radiated power.',\n    'Dull, black (matte) surfaces are good absorbers AND good emitters (high emissivity ε); shiny, silvered surfaces are poor absorbers/emitters — why vacuum flasks are silvered and radiators are painted matte black.',\n    'All objects above 0 K radiate; the object also absorbs radiation from its surroundings, so the NET transfer depends on the temperature difference (T⁴ − T₀⁴).',\n    'Applications: thermal imaging cameras detect the infrared radiated by warm bodies; a car left in the sun heats up mainly by absorbed solar radiation.',\n  ],\n};\n\nconst EXERCISES: Record<HeatMode, { q: string; a: string }[]> = {\n  conduction: [\n    { q: 'A copper bar (k=385 W/mK) of area 0.002m² and length 0.5m has a 60°C temperature difference across it. Find the rate of heat flow.', a: 'Q/t = kAΔT/L = 385×0.002×60/0.5 = 92.4 W.' },\n    { q: 'Why do metal spoons feel colder to touch than wooden ones at the same room temperature?', a: 'Metal has much higher thermal conductivity, so it conducts heat away from your hand much faster than wood, feeling colder even though both are at the same temperature.' },\n    { q: 'A wall has half the thickness of another identical wall. How does the rate of heat conduction compare?', a: 'Q/t ∝ 1/L, so halving the thickness DOUBLES the rate of heat loss.' },\n  ],\n  convection: [\n    { q: 'Explain, using convection, why a radiator is placed near the floor rather than the ceiling.', a: 'Air warmed by the radiator becomes less dense and rises, setting up a convection current that circulates warm air throughout the whole room from the bottom up.' },\n    { q: 'Why does a hot air balloon rise?', a: 'The burner heats the air inside, making it less dense than the surrounding cooler air, so the balloon experiences a net upward (buoyant) force — exactly like a convection current.' },\n    { q: 'Why can convection not occur in a solid?', a: 'Convection requires bulk movement of particles; particles in a solid are fixed in place and cannot flow to create a circulation current.' },\n  ],\n  radiation: [\n    { q: 'A black surface of area 0.01m² at 500K radiates into surroundings at 300K. Find the net power radiated. (σ = 5.67×10⁻⁸ W/m²K⁴, ε=1)', a: 'P = εσA(T⁴−T₀⁴) = 5.67e-8×0.01×(500⁴−300⁴) = 5.67e-10×(6.25e10−8.1e9) ≈ 30.7 W.' },\n    { q: 'Why are the pipes of a solar water heater usually painted matte black?', a: 'Matte black surfaces are excellent absorbers of radiation, maximising the energy absorbed from sunlight to heat the water.' },\n    { q: 'A star doubles in absolute temperature. By what factor does its radiated power increase?', a: 'P ∝ T⁴, so doubling T increases power by 2⁴ = 16 times.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function HeatTransferPage() {\n  const [mode, setMode] = useState<HeatMode>('conduction');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [hotTemp, setHotTemp] = useState(90);\n  const [coldTemp, setColdTemp] = useState(20);\n  const [materialIdx, setMaterialIdx] = useState(0); // Copper by default\n  const [areaCm2, setAreaCm2] = useState(20);\n  const [lengthCm, setLengthCm] = useState(50);\n  const material = MATERIALS[materialIdx];\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [mode, hotTemp, coldTemp, materialIdx, areaCm2, lengthCm, reset]);\n\n  const Thot = celsiusToKelvin(hotTemp), Tcold = celsiusToKelvin(coldTemp);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 300, 980);\n\n  useTopicPreset(\"simulations-heat-transfer\", { \"hotTemp\": setHotTemp,\n    \"coldTemp\": setColdTemp,\n    \"areaCm2\": setAreaCm2,\n    \"lengthCm\": setLengthCm }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Thermal physics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Modes of heat transfer</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as HeatMode[]).map(m => (\n              <button key={m} onClick={() => { setMode(m); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span><span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{MODE_META[mode].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{MODE_META[mode].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <HeatTransferCanvas mode={mode} hotTemp={hotTemp} coldTemp={coldTemp} materialK={material.k}\n                  isRunning={isRunning} isPaused={isPaused} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/heat\"\n                  title={`${MODE_META[mode].title} — A-Factor STEM Studio`}\n                  params={{ mode, hot: hotTemp, cold: coldTemp }} />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <Slider label=\"Hot temperature\" unit=\"°C\" value={hotTemp} min={30} max={120} step={5} set={setHotTemp} color=\"#ef4444\" />\n                <Slider label=\"Cold / surroundings temperature\" unit=\"°C\" value={coldTemp} min={0} max={40} step={5} set={setColdTemp} color=\"#3b82f6\" />\n                {mode === 'conduction' && <>\n                  <div className=\"pt-2 border-t border-gray-100 space-y-1.5\">\n                    <span className=\"text-xs text-gray-500\">Material</span>\n                    <div className=\"grid grid-cols-2 gap-1.5\">\n                      {MATERIALS.map((m, i) => (\n                        <button key={m.name} onClick={() => setMaterialIdx(i)}\n                          className={`rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                            materialIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                          }`}>{m.name}</button>\n                      ))}\n                    </div>\n                    <p className=\"text-[10px] text-gray-400\">k = {material.k} W/mK</p>\n                  </div>\n                  <Slider label=\"Cross-sectional area\" unit=\"cm²\" value={areaCm2} min={1} max={100} step={1} set={setAreaCm2} color=\"#8b5cf6\" />\n                  <Slider label=\"Rod length\" unit=\"cm\" value={lengthCm} min={5} max={150} step={5} set={setLengthCm} color=\"#8b5cf6\" />\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"ΔT\" value={(hotTemp - coldTemp).toFixed(0)} unit=\"°C\" color=\"text-indigo-600\" />\n                  {mode === 'conduction' && <>\n                    <StatRow label=\"Rate Q/t = kAΔT/L\" value={conductionRate(material.k, areaCm2 / 1e4, hotTemp - coldTemp, lengthCm / 100).toFixed(2)} unit=\"W\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Material\" value={material.name} unit=\"\" color=\"text-purple-600\" />\n                    <StatRow label=\"Direction\" value=\"hot → cold\" unit=\"always\" color=\"text-amber-600\" />\n                  </>}\n                  {mode === 'radiation' && <>\n                    <StatRow label=\"Hot object radiates\" value={radiatedPower(1, 0.01, Thot).toFixed(2)} unit=\"W\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Net transfer\" value={netRadiation(1, 0.01, Thot, Tcold).toFixed(2)} unit=\"W\" color=\"text-amber-600\" />\n                    <StatRow label=\"T⁴ ratio\" value={Math.pow(Thot / Tcold, 4).toFixed(1)} unit=\"×\" color=\"text-rose-500\" />\n                  </>}\n                  {mode === 'convection' && (\n                    <StatRow label=\"Direction\" value=\"hot → cold\" unit=\"always\" color=\"text-emerald-600\" />\n                  )}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[mode].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/x-rays/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef, useMemo } from 'react';\nimport { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Label, ReferenceLine } from 'recharts';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { XrayCanvas } from '@/components/simulation/XrayCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { lambdaMinNm, maxPhotonEnergyKeV, xraySpectrum, MO_K_ALPHA_NM, MO_K_BETA_NM, MO_EXCITATION_KV } from '@/lib/physics/xrays';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TEACHER_NOTES = [\n  'X-ray production is the photoelectric effect in REVERSE: fast electrons in, photons out. Electrons accelerated through kV strike a metal target; ~99% of their energy becomes heat, ~1% becomes X-rays (which is why anodes are cooled or rotated).',\n  'The continuous (bremsstrahlung = \"braking radiation\") spectrum has a sharp cutoff λmin = hc/eV — the Duane–Hunt limit. An electron cannot give a photon more than its whole kinetic energy eV.',\n  'Raise the tube voltage: λmin slides LEFT (shorter, more penetrating \"harder\" X-rays). Raise the filament current: MORE X-rays (taller spectrum), same λmin.',\n  'The sharp Kα/Kβ characteristic lines appear only when electrons can knock out inner-shell electrons of the target (Mo: above ~20 kV). Their wavelengths identify the target element — the basis of X-ray spectroscopy.',\n  'Properties for exams: travel in straight lines, not deflected by electric/magnetic fields (uncharged), ionise gases, penetrate matter (absorbed by dense material like bone/lead), affect photographic film.',\n];\n\nconst EXERCISES = [\n  { q: 'An X-ray tube runs at 50 kV. Find the minimum wavelength produced. (h = 6.63×10⁻³⁴ Js, c = 3×10⁸ m/s, e = 1.6×10⁻¹⁹ C)', a: 'λmin = hc/eV = (6.63e-34 × 3e8)/(1.6e-19 × 5e4) = 2.49×10⁻¹¹ m ≈ 0.025 nm.' },\n  { q: 'What is the maximum photon energy (in keV) from a 80 kV tube, and why is it a maximum?', a: '80 keV — a photon cannot carry more than the full kinetic energy eV of one electron; most electrons give up their energy in stages (heat + softer photons).' },\n  { q: 'Doubling the filament current does what to (a) the spectrum height, (b) λmin?', a: '(a) Doubles the intensity everywhere — twice as many electrons. (b) λmin unchanged: it depends only on the tube voltage.' },\n  { q: 'Why do the Kα and Kβ lines disappear when the tube voltage drops below 20 kV (Mo target)?', a: 'Below 20 kV the electrons lack the energy to eject a K-shell electron from molybdenum, so no inner-shell vacancies form and no characteristic photons are emitted.' },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nfunction SpectrumGraph({ kV, current }: { kV: number; current: number }) {\n  const data = useMemo(() => xraySpectrum(kV, current), [kV, current]);\n  const lMin = lambdaMinNm(kV);\n  return (\n    <ResponsiveContainer width=\"100%\" height={210}>\n      <LineChart data={data} margin={{ top: 8, right: 16, left: 10, bottom: 28 }}>\n        <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n        <XAxis dataKey=\"lambda\" type=\"number\" tick={{ fontSize: 10 }} domain={[0, 0.14]}>\n          <Label value=\"Wavelength λ (nm)\" position=\"insideBottom\" offset={-16} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </XAxis>\n        <YAxis tick={{ fontSize: 10 }}>\n          <Label value=\"Intensity\" angle={-90} position=\"insideLeft\" offset={12} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </YAxis>\n        <Tooltip formatter={(v: unknown) => [Number(v).toFixed(2), 'I']} labelFormatter={l => `λ=${Number(l).toFixed(3)}nm`} />\n        <Line type=\"linear\" dataKey=\"i\" stroke=\"#8b5cf6\" strokeWidth={2} dot={false} isAnimationActive={false} />\n        <ReferenceLine x={lMin} stroke=\"#ef4444\" strokeDasharray=\"4 4\"\n          label={{ value: 'λmin', position: 'top', fontSize: 10, fill: '#dc2626' }} />\n        {kV >= MO_EXCITATION_KV && <>\n          <ReferenceLine x={MO_K_ALPHA_NM} stroke=\"#e2e8f0\"\n            label={{ value: 'Kα', position: 'top', fontSize: 9, fill: '#94a3b8' }} />\n          <ReferenceLine x={MO_K_BETA_NM} stroke=\"#e2e8f0\"\n            label={{ value: 'Kβ', position: 'top', fontSize: 9, fill: '#94a3b8' }} />\n        </>}\n      </LineChart>\n    </ResponsiveContainer>\n  );\n}\n\nexport default function XraysPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'JUPEB']);\n\n  const [kV, setKV] = useState(35);\n  const [current, setCurrent] = useState(5);\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [kV, current, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 300, 980);\n\n  useTopicPreset(\"simulations-x-rays\", { \"kV\": setKV,\n    \"current\": setCurrent }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Modern physics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">X-rays</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Duane–Hunt limit</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">λmin = hc/eV</span>\n            <span className=\"text-xs text-gray-400 ml-2\">max photon energy = eV</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <XrayCanvas kV={kV} current={current}\n                  isRunning={isRunning} isPaused={isPaused} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/xrays\"\n                  title=\"X-ray tube — A-Factor STEM Studio\"\n                  params={{ kV, i: current }} />\n              </div>\n\n              <div data-stage-role=\"extra\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">X-ray spectrum (Mo target)</p>\n                <SpectrumGraph kV={kV} current={current} />\n                <p className=\"text-[10px] text-gray-400 mt-2 text-center\">\n                  Continuous bremsstrahlung with sharp cutoff at λmin — Kα/Kβ characteristic lines above {MO_EXCITATION_KV} kV\n                </p>\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <Slider label=\"Tube voltage\" unit=\"kV\" value={kV} min={5} max={100} step={1} set={setKV} color=\"#6366f1\"\n                  note=\"Higher V → shorter λmin → harder, more penetrating X-rays\" />\n                <Slider label=\"Filament current\" unit=\"\" value={current} min={1} max={10} step={1} set={setCurrent} color=\"#f59e0b\"\n                  note=\"More electrons → more X-rays, but λmin does not move\" />\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"λmin\" value={lambdaMinNm(kV).toFixed(4)} unit=\"nm\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Max photon energy\" value={maxPhotonEnergyKeV(kV).toFixed(0)} unit=\"keV\" color=\"text-emerald-600\" />\n                  <StatRow label=\"Electron KE\" value={kV.toFixed(0)} unit=\"keV\" color=\"text-amber-600\" />\n                  <StatRow label=\"K lines\" value={kV >= MO_EXCITATION_KV ? 'visible' : 'absent'} unit=\"\" color=\"text-rose-500\" />\n                  <StatRow label=\"Energy → heat\" value=\"~99\" unit=\"%\" color=\"text-purple-600\" />\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/vectors/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useRef, useState } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { VectorCanvas } from '@/components/simulation/VectorCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { type P3, type View, DEFAULT_VIEW, P, clampTo, describeDirection, fmt } from '@/lib/physics/space';\nimport {\n  type Context, type Method, type Op, type PracticeKind, type Problem, type Scene, type VMode, type VState, CONTEXTS, COL, PRACTICE_KINDS,\n  add, angleBetween, checkProblem, compText, cross, dot, fromPolar, ijk, isZero, mag, minus, neg, projScalar, projVector, scale, sceneFor, sum, toPolar,\n  randomProblem, unit, withUnit, workAdd, workComponentsFromPolar, workCross, workDirection, workDot, workMagnitude, workScalar,\n} from '@/lib/physics/vectors';\n\ntype D = '2d' | '3d';\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = { WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700', IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700', JUPEB: 'bg-purple-100 text-purple-700' };\nconst MODES: { id: VMode; title: string }[] = [\n  { id: 'components', title: 'Components' }, { id: 'add', title: 'Add & subtract' }, { id: 'scalar', title: 'Scalar multiple' },\n  { id: 'dot', title: 'Dot product' }, { id: 'cross', title: 'Cross product' }, { id: 'practice', title: '🎯 Practice' },\n];\nconst KIND_LABEL: Record<PracticeKind, string> = { resultant: 'A + B', difference: 'A − B', magnitude: 'Magnitude', direction: 'Direction', scalar: 'Scalar multiple', dot: 'Dot product', angle: 'Angle between', cross: 'Cross product', projection: 'Projection' };\n\nconst NOTES: Record<VMode, string[]> = {\n  components: [\n    'A vector has a magnitude (size) and a direction. Its components are its shadows on the axes: Ax = |A| cos θ and Ay = |A| sin θ.',\n    'From components back to the vector: |A| = √(Ax² + Ay² [+ Az²]). The direction is θ = tan⁻¹(Ay/Ax), but always check the quadrant from the signs of Ax and Ay.',\n    'The unit vector Â = A/|A| has magnitude 1 and carries only the direction, so A = |A| Â. The unit vectors along the axes are i, j and k.',\n    'A free vector is defined by magnitude and direction only: it is the same vector wherever you draw it.',\n  ],\n  add: [\n    'Triangle (tip-to-tail): draw B starting at the tip of A. The resultant goes from the tail of A to the tip of B. Parallelogram: draw both from the same point; the resultant is the diagonal from that point.',\n    'In components: R = (Ax + Bx, Ay + By). Subtraction is addition of the reverse: A − B = A + (−B), and A − B is the vector from the tip of B to the tip of A.',\n    'Order does not matter (A + B = B + A) and neither does grouping. If vectors drawn tip-to-tail close into a polygon, the resultant is zero: for forces, that means equilibrium.',\n    '|A + B| is never more than |A| + |B|; they are equal only when A and B point the same way.',\n  ],\n  scalar: [\n    'Multiplying by a scalar k multiplies every component: kA = (kAx, kAy). The magnitude becomes |k||A|.',\n    'If k > 0 the direction is unchanged; if k < 0 the vector reverses; if k = 0 you get the zero vector.',\n    'Two vectors are parallel exactly when one is a scalar multiple of the other. The unit vector is (1/|A|)A.',\n    'Distributive laws: k(A + B) = kA + kB and (k + m)A = kA + mA.',\n  ],\n  dot: [\n    'The dot (scalar) product A·B = AxBx + AyBy [+ AzBz] = |A||B| cos θ is a number, not a vector.',\n    'Its sign tells you about the angle: positive means acute, zero means perpendicular, negative means obtuse. A·B = 0 is the test for perpendicular vectors.',\n    'The component of A along B is A·B/|B| (the scalar projection). Physics uses: work W = F·d and power P = F·v.',\n    'A·B = B·A, and A·A = |A|².',\n  ],\n  cross: [\n    'The cross (vector) product A × B is a vector perpendicular to both A and B. Its magnitude |A||B| sin θ equals the area of the parallelogram they span.',\n    'Direction: right-hand rule. Point your fingers along A, curl them towards B, and your thumb gives A × B.',\n    'It is not commutative: B × A = −(A × B). Parallel vectors have a zero cross product.',\n    'Used for torque τ = r × F, the magnetic force F = q v × B and angular momentum L = r × p.',\n  ],\n  practice: [\n    'Work out the answer on paper first, then type it in. Use the \"working\" shown after Reveal to find where a step went wrong.',\n    'Check signs: most mistakes in vector problems are sign errors in negative components.',\n    'Magnitudes and angles are marked correct within a small rounding tolerance (0.01 for lengths, 0.15° for angles).',\n  ],\n};\nconst EXERCISES: Record<VMode, { q: string; a: string }[]> = {\n  components: [\n    { q: 'A force of 50 N acts at 36.9° above the +x axis. Find its components.', a: 'Fx = 50 cos 36.9° ≈ 40 N and Fy = 50 sin 36.9° ≈ 30 N.' },\n    { q: 'A = (−6, 8). Find |A| and its direction measured from +x.', a: '|A| = √(36 + 64) = 10. The reference angle is tan⁻¹(8/6) = 53.1°, and A is in quadrant II, so θ = 180° − 53.1° = 126.9°.' },\n    { q: 'A vector has |A| = 13 and Ax = 5, pointing upwards (Ay > 0). Find Ay and the unit vector Â.', a: 'Ay = √(13² − 5²) = 12. Â = (5/13, 12/13) = (0.385, 0.923).' },\n  ],\n  add: [\n    { q: 'A = (3, 4) and B = (−1, 2). Find A + B, its magnitude and direction, and A − B.', a: 'A + B = (2, 6), |A + B| = √40 ≈ 6.32, θ = tan⁻¹(6/2) = 71.6°. A − B = (4, 2).' },\n    { q: 'A student walks 5 m east then 12 m north. Find the distance walked and the displacement.', a: 'Distance = 17 m. Displacement = (5, 12): magnitude 13 m at tan⁻¹(12/5) = 67.4° north of east.' },\n    { q: 'Forces F₁ = (3, 4) N and F₂ = (−5, 1) N act on a body in equilibrium together with F₃. Find F₃.', a: 'F₁ + F₂ + F₃ = 0, so F₃ = −(F₁ + F₂) = −(−2, 5) = (2, −5) N.' },\n  ],\n  scalar: [\n    { q: 'A = (2, −3). Find 3A, −A and 0.5A.', a: '3A = (6, −9); −A = (−2, 3); 0.5A = (1, −1.5).' },\n    { q: 'Is (6, −9) parallel to (2, −3)?', a: 'Yes: (6, −9) = 3 × (2, −3), so they are parallel and point the same way.' },\n    { q: 'Find the unit vector in the direction of (3, 4), and a vector of magnitude 10 in that direction.', a: 'Unit vector = (3/5, 4/5) = (0.6, 0.8). A vector of magnitude 10 is 10 × (0.6, 0.8) = (6, 8).' },\n  ],\n  dot: [\n    { q: 'A = (2, 3) and B = (4, −1). Find A·B and the angle between them.', a: 'A·B = 8 − 3 = 5. |A| = √13, |B| = √17, so cos θ = 5/√221 = 0.336 and θ = 70.3°.' },\n    { q: 'A force F = (10, 0) N moves a body through d = (3, 4) m. Find the work done.', a: 'W = F·d = (10)(3) + (0)(4) = 30 J.' },\n    { q: 'For which value of k are (3, 4) and (k, 6) perpendicular?', a: 'Perpendicular means the dot product is 0: 3k + 24 = 0, so k = −8.' },\n  ],\n  cross: [\n    { q: 'A = (1, 2, 3) and B = (4, 5, 6). Find A × B and its magnitude.', a: 'A × B = (2·6 − 3·5, 3·4 − 1·6, 1·5 − 2·4) = (−3, 6, −3). Magnitude = √(9 + 36 + 9) = √54 ≈ 7.35.' },\n    { q: 'A wrench arm r = (2, 0, 0) m has a force F = (0, 3, 0) N applied. Find the torque r × F.', a: 'τ = (0·0 − 0·3, 0·0 − 2·0, 2·3 − 0·0) = (0, 0, 6) N·m: magnitude 6 N·m, along +z.' },\n    { q: 'Find the area of the parallelogram with sides (3, 0) and (1, 2).', a: 'Area = |Ax By − Ay Bx| = |3·2 − 0·1| = 6.' },\n  ],\n  practice: [\n    { q: 'Tip: unsure how to start? Return to the mode for that operation, set the same vectors, and compare your working with the steps shown.', a: 'Each mode shows the working for exactly the numbers on screen.' },\n  ],\n};\n\nconst DEFAULTS: Record<D, { A: P3; B: P3; C: P3 }> = {\n  '2d': { A: P(3, 4), B: P(-1, 2), C: P(-2, -5) },\n  '3d': { A: P(3, 2, 1), B: P(1, 3, 2), C: P(-2, 1, -1) },\n};\n\nfunction NumField({ label, value, onCommit, min, max, color, step }: { label: string; value: number; onCommit: (v: number) => void; min: number; max: number; color?: string; step?: string }) {\n  const [text, setText] = useState<string | null>(null);\n  return (\n    <label className=\"flex min-w-0 flex-1 items-center gap-1.5 text-xs\">\n      <span className=\"font-semibold\" style={{ color }}>{label}</span>\n      <input type=\"number\" inputMode=\"decimal\" step={step ?? 'any'} min={min} max={max} aria-label={label} value={text ?? String(Number(value.toFixed(2)))}\n        onChange={e => { setText(e.target.value); const v = Number(e.target.value); if (e.target.value !== '' && e.target.value !== '-' && Number.isFinite(v)) onCommit(clampTo(v, max)); }}\n        onBlur={() => setText(null)} className=\"h-8 w-full min-w-0 rounded-md border border-gray-200 bg-white px-2 text-sm tabular-nums\" />\n    </label>\n  );\n}\nconst Stat = ({ k, v, c = 'text-gray-900' }: { k: string; v: React.ReactNode; c?: string }) => (\n  <div className=\"flex items-center justify-between gap-3 rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-xs text-gray-500\">{k}</span><span className={`text-right text-sm font-semibold tabular-nums ${c}`}>{v}</span></div>\n);\nconst Toggle = ({ label, on, set }: { label: string; on: boolean; set: (v: boolean) => void }) => (\n  <label className=\"flex items-center gap-1.5 text-xs text-gray-600\"><input type=\"checkbox\" checked={on} onChange={e => set(e.target.checked)} />{label}</label>\n);\nconst Seg = <T extends string>({ value, options, set, label }: { value: T; options: { id: T; label: string }[]; set: (v: T) => void; label: string }) => (\n  <div className=\"flex overflow-hidden rounded-md border border-gray-200\" role=\"group\" aria-label={label}>\n    {options.map(o => <button key={o.id} type=\"button\" aria-pressed={value === o.id} onClick={() => set(o.id)} className={`px-2.5 py-1.5 text-xs ${value === o.id ? 'bg-indigo-600 text-white' : 'bg-white text-gray-600 hover:bg-gray-50'}`}>{o.label}</button>)}\n  </div>\n);\n\nexport default function VectorsPage() {\n  const [dim, setDim] = useState<D>('2d');\n  const [mode, setMode] = useState<VMode>('components');\n  const [ctx, setCtx] = useState<Context>('generic');\n  const [vecs, setVecs] = useState(DEFAULTS);\n  const [k, setK] = useState(2);\n  const [op, setOp] = useState<Op>('A+B');\n  const [method, setMethod] = useState<Method>('triangle');\n  const [useC, setUseC] = useState(false);\n  const [showComponents, setShowComponents] = useState(true);\n  const [showUnit, setShowUnit] = useState(false);\n  const [showAngle, setShowAngle] = useState(true);\n  const [snap, setSnap] = useState(1);\n  const [view, setView] = useState<View>(DEFAULT_VIEW);\n  const [dragAxis, setDragAxis] = useState<'floor' | 'height'>('floor');\n  const [planes, setPlanes] = useState(true); const [grid, setGrid] = useState(true);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [curr, setCurr] = useState(['WAEC', 'IGCSE', 'SAT']);\n  // practice\n  const [kind, setKind] = useState<PracticeKind | 'mixed'>('mixed');\n  const [problem, setProblem] = useState<Problem | null>(null);\n  const [typed, setTyped] = useState<string[]>(['', '', '']);\n  const [result, setResult] = useState<{ correct: boolean; wrong: number[]; revealed?: boolean } | null>(null);\n  const [score, setScore] = useState({ right: 0, tries: 0 });\n\n  const boxRef = useRef<HTMLDivElement>(null);\n  const size = useResponsiveCanvasSize(boxRef, 660, dim === '3d' ? 500 : 520, 900);\n  const compact = size.width < 560;\n  const canvasH = compact ? Math.round(size.width * 1.0) : size.height;\n\n  const { A, B, C } = vecs[dim];\n  const state: VState = { A, B, C, k, op, method, useC, showComponents, showUnit, showAngle };\n  const practicing = mode === 'practice';\n\n  const newProblem = (kk: PracticeKind | 'mixed' = kind, d: D = dim) => { setProblem(randomProblem(kk, d)); setTyped(['', '', '']); setResult(null); };\n  const changeMode = (m: VMode) => { setMode(m); setResult(null); if (m === 'practice' && !problem) newProblem(kind, dim); };\n  const changeDim = (d: D) => { setDim(d); setResult(null); if (practicing) newProblem(kind, d); };\n\n  const practiceScene = (p: Problem): Scene => {\n    const sc: Scene = { arrows: [{ from: P(), to: p.A, color: COL.A, width: 3.2, label: 'A', labelAt: 0.55 }], polys: [], arcs: [], handles: [], marks: [] };\n    if (!['magnitude', 'direction', 'scalar'].includes(p.kind)) sc.arrows.push({ from: P(), to: p.B, color: COL.B, width: 3.2, label: 'B', labelAt: 0.55 });\n    return sc;\n  };\n  const scene: Scene = practicing ? (problem ? practiceScene(problem) : { arrows: [], polys: [], arcs: [], handles: [], marks: [] }) : sceneFor(mode, dim, state, ctx);\n\n  const setVec = (id: 'A' | 'B' | 'C', v: P3) => setVecs(s => ({ ...s, [dim]: { ...s[dim], [id]: dim === '2d' ? P(v.x, v.y, 0) : v } }));\n  const onHandle = (id: 'A' | 'B' | 'C', at: P3) => {\n    const h = scene.handles.find(x => x.id === id); if (!h) return;\n    setVec(id, scale(minus(at, h.base), h.mul ?? 1));\n  };\n\n  // derived values\n  const R = op === 'B−A' ? minus(B, A) : op === 'A−B' ? minus(A, B) : add(A, B);\n  const Rtot = useC ? add(R, C) : R;\n  const kA = scale(A, k);\n  const ang = angleBetween(A, B);\n  const X = cross(A, B);\n  const dirText = (v: P3) => describeDirection(v, dim);\n  const active: ('A' | 'B' | 'C')[] = mode === 'components' || mode === 'scalar' ? ['A'] : mode === 'add' ? (useC ? ['A', 'B', 'C'] : ['A', 'B']) : mode === 'dot' || mode === 'cross' ? ['A', 'B'] : [];\n  const col = { A: COL.A, B: COL.B, C: COL.C };\n  const comp: ('x' | 'y' | 'z')[] = dim === '2d' ? ['x', 'y'] : ['x', 'y', 'z'];\n  const rg = 12;\n\n  const check = () => {\n    if (!problem) return;\n    const given = problem.answer.map((_, i) => (typed[i].trim() === '' ? NaN : Number(typed[i])));\n    if (given.some(g => !Number.isFinite(g))) { setResult({ correct: false, wrong: [], revealed: false }); return; }\n    const r = checkProblem(problem, given); setResult(r); setScore(s => ({ right: s.right + (r.correct ? 1 : 0), tries: s.tries + 1 }));\n  };\n\n  const working: string[] = [];\n  if (!practicing) {\n    if (mode === 'components') {\n      working.push(workMagnitude(A, dim));\n      if (dim === '2d') working.push(workDirection(A)); else { const dd = dirText(A); working.push(`Direction: ${dd.text}`); }\n      if (dim === '2d' && !isZero(A)) { const p = toPolar(A); workComponentsFromPolar(p.r, p.theta).forEach(l => working.push(l)); }\n    }\n    if (mode === 'add') {\n      const first = op === 'B−A' ? B : A, second = op === 'B−A' ? A : B, n1 = op === 'B−A' ? 'B' : 'A', n2 = op === 'B−A' ? 'A' : 'B';\n      workAdd(first, second, dim, op === 'A+B' ? '+' : '−', n1, n2, 'R').forEach(l => working.push(l));\n      working.push(workMagnitude(R, dim, 'R'));\n      if (dim === '2d') working.push(workDirection(R));\n      if (useC) { workAdd(R, C, dim, '+', 'R', 'C', 'R′').forEach(l => working.push(l)); }\n    }\n    if (mode === 'scalar') { workScalar(A, k, dim).forEach(l => working.push(l)); working.push(`|kA| = |k||A| = ${fmt(Math.abs(k))} × ${fmt(mag(A))} = ${fmt(mag(kA))}`); }\n    if (mode === 'dot') workDot(A, B, dim).forEach(l => working.push(l));\n    if (mode === 'cross') { if (dim === '3d') workCross(A, B).forEach(l => working.push(l)); else working.push(`(A×B)z = AxBy − AyBx = (${fmt(A.x)})(${fmt(B.y)}) − (${fmt(A.y)})(${fmt(B.x)}) = ${fmt(X.z)}`); working.push(`|A×B| = ${fmt(mag(X))}`); }\n  }\n\n  const unitA = unit(A);\n\n  useTopicPreset(\"simulations-vectors\", { \"k\": setK }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 py-4 sm:px-6\">\n            <div className=\"flex flex-col justify-between gap-3 sm:flex-row sm:items-center\">\n              <div><p className=\"mb-0.5 text-xs text-gray-400\">Space and time</p><h1 className=\"text-lg font-semibold text-gray-900\">Vectors: components, addition &amp; products</h1></div>\n              <div className=\"flex flex-wrap gap-1.5\">{CURRICULA.map(c => <button key={c} onClick={() => setCurr(s => (s.includes(c) ? s.filter(x => x !== c) : [...s, c]))} className={`rounded-full border px-2.5 py-2 text-xs font-medium transition ${curr.includes(c) ? CC[c] + ' border-transparent' : 'border-gray-200 bg-white text-gray-400'}`}>{c}</button>)}</div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] space-y-4 px-4 py-4 sm:px-6\">\n          <div className=\"flex flex-wrap items-center gap-3\">\n            <div className=\"flex gap-1 rounded-xl bg-gray-100 p-1\" role=\"tablist\" aria-label=\"Dimensions\">\n              {(['2d', '3d'] as D[]).map(d => <button key={d} role=\"tab\" aria-selected={dim === d} onClick={() => changeDim(d)} className={`rounded-lg px-4 py-2 text-xs font-medium transition ${dim === d ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{d === '2d' ? '2D · Plane' : '3D · Space'}</button>)}\n            </div>\n            <label className=\"flex items-center gap-1.5 text-xs text-gray-600\">Think of the vectors as\n              <select value={ctx} onChange={e => setCtx(e.target.value as Context)} className=\"h-8 rounded-md border border-gray-200 bg-white px-2 text-xs\">{(Object.keys(CONTEXTS) as Context[]).map(c => <option key={c} value={c}>{CONTEXTS[c].label}{CONTEXTS[c].unit ? ` (${CONTEXTS[c].unit})` : ''}</option>)}</select>\n            </label>\n          </div>\n          <div className=\"flex gap-1 overflow-x-auto\" role=\"tablist\" aria-label=\"Topic\">\n            {MODES.map(m => <button key={m.id} role=\"tab\" aria-selected={mode === m.id} onClick={() => changeMode(m.id)} className={`shrink-0 rounded-full border px-3.5 py-1.5 text-xs font-medium transition ${mode === m.id ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 bg-white text-gray-600 hover:border-indigo-300'}`}>{m.title}</button>)}\n          </div>\n\n          <div className=\"grid grid-cols-1 gap-4 lg:grid-cols-[minmax(0,1fr)_320px] xl:grid-cols-[minmax(0,1fr)_320px_280px]\">\n            <SimulationStage className=\"min-w-0 space-y-3\">\n              <div data-stage-role=\"canvas\" ref={boxRef} className=\"overflow-hidden rounded-2xl border border-gray-200 bg-white p-2 shadow-sm\">\n                <VectorCanvas dim={dim} width={size.width} height={canvasH} scene={scene} snap={snap} view={view} onView={setView} dragAxis={dragAxis} showPlanes={planes} showGrid={grid}\n                  readOnly={practicing} onHandle={onHandle}\n                  ariaLabel={`${dim === '2d' ? '2D' : '3D'} vector diagram. ${practicing ? 'The vectors for the current problem are drawn from the origin.' : 'Drag the coloured handles at the tips of the vectors, or focus the diagram and use the arrow keys.'}`} />\n              </div>\n              <div data-stage-role=\"parameters\" className=\"flex flex-wrap items-center gap-x-4 gap-y-2 rounded-xl border border-gray-200 bg-white px-3 py-2.5\">\n                <label className=\"flex items-center gap-1.5 text-xs text-gray-600\">Snap\n                  <select value={snap} onChange={e => setSnap(Number(e.target.value))} className=\"h-7 rounded-md border border-gray-200 bg-white px-1.5 text-xs\"><option value={1}>whole numbers</option><option value={0.5}>0.5</option><option value={0}>0.1 (free)</option></select>\n                </label>\n                {!practicing && (mode === 'components' || mode === 'scalar') && <Toggle label=\"Unit vector Â\" on={showUnit} set={setShowUnit} />}\n                {!practicing && mode === 'components' && <Toggle label=\"Components\" on={showComponents} set={setShowComponents} />}\n                {!practicing && mode !== 'scalar' && (dim === '2d' || mode !== 'components') && <Toggle label=\"Angle\" on={showAngle} set={setShowAngle} />}\n                {dim === '3d' && <>\n                  <div className=\"flex items-center gap-1.5 text-xs text-gray-600\">Drag tip <Seg value={dragAxis} set={setDragAxis} label=\"Drag direction\" options={[{ id: 'floor', label: 'across floor' }, { id: 'height', label: 'up / down' }]} /></div>\n                  <Toggle label=\"Planes\" on={planes} set={setPlanes} />\n                </>}\n                <Toggle label=\"Grid\" on={grid} set={setGrid} />\n                <div className=\"ml-auto\"><EmbedButton path=\"/embed/vectors\" title=\"Vectors — A-Factor STEM Studio\" params={{ dim, mode: practicing ? 'add' : mode, A: `${A.x},${A.y},${A.z}`, B: `${B.x},${B.y},${B.z}`, k: String(k) }} /></div>\n              </div>\n              <div data-stage-role=\"extra\"><p className=\"text-[11px] text-gray-400\">{practicing ? 'Practice: the problem’s vectors are drawn from the origin on the grid.' : `Drag the coloured dots at the vector tips${dim === '3d' ? ', drag empty space to rotate' : ''}; or click the diagram and use the arrow keys${dim === '3d' ? ' (Page Up/Down for z)' : ''}.`}</p></div>\n            </SimulationStage>\n\n            <div className=\"min-w-0 space-y-3\">\n              {!practicing && (\n                <div className=\"space-y-3 rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">{active.length > 1 ? 'Vectors' : 'Vector A'}</p>\n                  {active.map(id => {\n                    const v = vecs[dim][id], p = toPolar(v);\n                    return (\n                      <div key={id} className=\"space-y-1.5 rounded-xl border border-gray-100 p-2\">\n                        <div className=\"text-xs font-semibold\" style={{ color: col[id] }}>{id} = {compText(v, dim, 2)} = {ijk(v, dim)}</div>\n                        <div className=\"flex gap-1.5\">{comp.map(c => <NumField key={c} label={`${id}${c}`} value={v[c]} min={-rg * 4} max={rg * 4} color={col[id]} onCommit={n => setVec(id, { ...v, [c]: n })} />)}</div>\n                        {dim === '2d' && <div className=\"flex gap-1.5\"><NumField label={`|${id}|`} value={p.r} min={0} max={rg * 6} color={col[id]} onCommit={n => setVec(id, fromPolar(n, p.theta))} /><NumField label=\"θ°\" value={p.theta} min={0} max={360} color={col[id]} onCommit={n => setVec(id, fromPolar(p.r, n))} /></div>}\n                      </div>\n                    );\n                  })}\n                  {mode === 'scalar' && (\n                    <div className=\"space-y-1.5\"><div className=\"flex items-center gap-2\"><NumField label=\"k\" value={k} min={-10} max={10} color={COL.R} onCommit={setK} /></div><input type=\"range\" min={-3} max={3} step={0.5} value={Math.max(-3, Math.min(3, k))} onChange={e => setK(Number(e.target.value))} aria-label=\"k slider\" className=\"w-full\" style={{ accentColor: COL.R }} /></div>\n                  )}\n                  {mode === 'add' && (\n                    <div className=\"space-y-2\">\n                      <div className=\"flex flex-wrap items-center gap-2\"><span className=\"text-xs text-gray-500\">Operation</span><Seg value={op} set={setOp} label=\"Operation\" options={[{ id: 'A+B', label: 'A + B' }, { id: 'A−B', label: 'A − B' }, { id: 'B−A', label: 'B − A' }]} /></div>\n                      <div className=\"flex flex-wrap items-center gap-2\"><span className=\"text-xs text-gray-500\">Method</span><Seg value={method} set={setMethod} label=\"Method\" options={[{ id: 'triangle', label: 'Tip-to-tail' }, { id: 'parallelogram', label: 'Parallelogram' }, { id: 'both', label: 'Both' }]} /></div>\n                      {op === 'A+B' && <Toggle label=\"Add a third vector C (polygon rule)\" on={useC} set={setUseC} />}\n                    </div>\n                  )}\n                  <div className=\"flex flex-wrap gap-1.5\">\n                    <button onClick={() => setVecs(s => ({ ...s, [dim]: DEFAULTS[dim] }))} className=\"rounded-md border border-gray-200 px-2.5 py-1 text-[11px] text-gray-600 hover:border-indigo-300\">Reset</button>\n                    {mode === 'dot' && dim === '2d' && <button onClick={() => setVecs(s => ({ ...s, '2d': { ...s['2d'], B: P(-s['2d'].A.y, s['2d'].A.x) } }))} className=\"rounded-md border border-gray-200 px-2.5 py-1 text-[11px] text-gray-600 hover:border-indigo-300\">Make B ⟂ A</button>}\n                    {mode === 'add' && <button onClick={() => { if (!useC) setUseC(true); setVec('C', neg(add(A, B))); }} className=\"rounded-md border border-gray-200 px-2.5 py-1 text-[11px] text-gray-600 hover:border-indigo-300\">Balance with C</button>}\n                  </div>\n                </div>\n              )}\n\n              {!practicing && (\n                <div className=\"space-y-2 rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Results</p>\n                  {mode === 'components' && (<>\n                    <Stat k=\"Magnitude |A|\" v={withUnit(fmt(mag(A)), ctx)} c=\"text-indigo-600\" />\n                    <Stat k=\"Components\" v={compText(A, dim)} />\n                    {unitA && <Stat k=\"Unit vector Â\" v={compText(unitA, dim, 3)} />}\n                    <div className=\"rounded-lg bg-gray-50 px-3 py-2 text-xs leading-relaxed text-gray-700\"><span className=\"font-medium\">Direction: </span>{isZero(A) ? 'The zero vector has no direction.' : dirText(A).text}{dim === '2d' && !isZero(A) && dirText(A).bearing !== undefined ? ` · bearing ${fmt(dirText(A).bearing!, 1)}°` : ''}</div>\n                    {dim === '3d' && !isZero(A) && <div className=\"rounded-lg bg-gray-50 px-3 py-2 text-xs leading-relaxed text-gray-700\">Angles with the axes: x {fmt(dirText(A).axisAngles!.x, 1)}°, y {fmt(dirText(A).axisAngles!.y, 1)}°, z {fmt(dirText(A).axisAngles!.z, 1)}°</div>}\n                  </>)}\n                  {mode === 'add' && (<>\n                    <Stat k={`${op === 'A+B' ? (useC ? 'A + B + C' : 'A + B') : op === 'A−B' ? 'A − B' : 'B − A'} (${CONTEXTS[ctx].resultant.toLowerCase()})`} v={compText(Rtot, dim)} c=\"text-rose-600\" />\n                    <Stat k=\"Magnitude\" v={withUnit(fmt(mag(Rtot)), ctx)} c=\"text-rose-600\" />\n                    <div className=\"rounded-lg bg-rose-50 px-3 py-2 text-xs leading-relaxed text-rose-900\"><span className=\"font-medium\">Direction: </span>{isZero(Rtot) ? 'Zero vector.' : dirText(Rtot).text}</div>\n                    {ang !== null && <Stat k=\"Angle between A and B\" v={`${fmt(ang, 1)}°`} />}\n                    <div className=\"rounded-lg bg-gray-50 px-3 py-2 text-xs leading-relaxed text-gray-700\">\n                      {isZero(Rtot) ? <span className=\"font-medium text-emerald-700\">The resultant is zero: the vectors close into a polygon. For forces this means the body is in equilibrium.</span>\n                        : op === 'A+B' && !useC ? <>Order does not matter: B + A = {compText(add(B, A), dim)} = A + B. Also |A + B| = {fmt(mag(R))} ≤ |A| + |B| = {fmt(mag(A) + mag(B))}.</>\n                        : <>Check: {op === 'A−B' ? 'A − B is the vector from the tip of B to the tip of A.' : op === 'B−A' ? 'B − A is the vector from the tip of A to the tip of B, the opposite of A − B.' : `A + B + C = ${compText(sum([A, B, C]), dim)}.`}</>}\n                    </div>\n                  </>)}\n                  {mode === 'scalar' && (<>\n                    <Stat k={`kA with k = ${fmt(k)}`} v={compText(kA, dim)} c=\"text-rose-600\" />\n                    <Stat k=\"Magnitude |kA|\" v={withUnit(fmt(mag(kA)), ctx)} c=\"text-rose-600\" />\n                    <div className=\"rounded-lg bg-gray-50 px-3 py-2 text-xs leading-relaxed text-gray-700\">{k === 0 ? 'k = 0 gives the zero vector.' : k > 0 ? `k > 0: same direction as A, ${k > 1 ? 'stretched' : k < 1 ? 'shrunk' : 'unchanged'}.` : `k < 0: opposite direction to A, ${Math.abs(k) > 1 ? 'stretched' : Math.abs(k) < 1 ? 'shrunk' : 'same length'}.`}</div>\n                    {unitA && <Stat k=\"Unit vector Â\" v={compText(unitA, dim, 3)} />}\n                  </>)}\n                  {mode === 'dot' && (<>\n                    <Stat k=\"A·B\" v={fmt(dot(A, B))} c=\"text-indigo-600\" />\n                    <Stat k=\"Angle θ\" v={ang === null ? 'undefined' : `${fmt(ang, 1)}°`} />\n                    <Stat k=\"Scalar projection of A on B\" v={projScalar(A, B) === null ? '—' : fmt(projScalar(A, B)!)} c=\"text-cyan-700\" />\n                    <Stat k=\"Vector projection\" v={projVector(A, B) ? compText(projVector(A, B)!, dim) : '—'} />\n                    <div className={`rounded-lg px-3 py-2 text-xs leading-relaxed ${Math.abs(dot(A, B)) < 1e-9 ? 'bg-emerald-50 text-emerald-900' : 'bg-gray-50 text-gray-700'}`}>{Math.abs(dot(A, B)) < 1e-9 ? 'A·B = 0: the vectors are perpendicular (or one is zero).' : dot(A, B) > 0 ? 'A·B > 0: the angle is acute (less than 90°).' : 'A·B < 0: the angle is obtuse (more than 90°).'} Example: a force A (N) moving a body through B (m) does work W = A·B joules.</div>\n                  </>)}\n                  {mode === 'cross' && (<>\n                    {dim === '3d' ? <Stat k=\"A × B (drawn shortened if long)\" v={compText(X, dim)} c=\"text-violet-700\" /> : <Stat k=\"A × B (along z)\" v={`(0, 0, ${fmt(X.z)})`} c=\"text-violet-700\" />}\n                    <Stat k=\"|A × B| = parallelogram area\" v={fmt(mag(X))} c=\"text-violet-700\" />\n                    <Stat k=\"Check |A||B| sin θ\" v={ang === null ? '—' : fmt(mag(A) * mag(B) * Math.sin((ang * Math.PI) / 180))} />\n                    <div className=\"rounded-lg bg-gray-50 px-3 py-2 text-xs leading-relaxed text-gray-700\">\n                      {isZero(X) ? 'A × B = 0: the vectors are parallel (or one is zero), so the parallelogram has no area.' : dim === '3d' ? <>Right-hand rule: fingers along A, curl towards B, thumb along A × B. Check: (A×B)·A = {fmt(dot(X, A))} and (A×B)·B = {fmt(dot(X, B))}, both zero because A × B is perpendicular to each. B × A = {compText(neg(X), dim)}.</> : <>In 2D the cross product points along the z-axis, {X.z > 0 ? 'out of the page (B is counter-clockwise from A)' : 'into the page (B is clockwise from A)'}. <button className=\"font-medium text-indigo-600 hover:underline\" onClick={() => changeDim('3d')}>Switch to 3D to see it.</button></>}\n                    </div>\n                  </>)}\n                </div>\n              )}\n\n              {!practicing && working.length > 0 && (\n                <details open className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <summary className=\"cursor-pointer text-xs font-medium uppercase tracking-wide text-gray-400\">Working</summary>\n                  <div className=\"mt-2 space-y-1.5\">{working.map((l, i) => <p key={i} className=\"font-mono text-[11px] leading-relaxed text-gray-700\">{l}</p>)}</div>\n                </details>\n              )}\n\n              {practicing && (\n                <div className=\"space-y-3 rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <div className=\"flex items-center justify-between\"><p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Practice</p><span className=\"rounded-full bg-gray-100 px-2.5 py-1 text-[11px] font-medium text-gray-600\">Score {score.right} / {score.tries}</span></div>\n                  <label className=\"flex items-center gap-2 text-xs text-gray-600\">Topic\n                    <select value={kind} onChange={e => { const v = e.target.value as PracticeKind | 'mixed'; setKind(v); newProblem(v); }} className=\"h-8 flex-1 rounded-md border border-gray-200 bg-white px-2 text-xs\">\n                      <option value=\"mixed\">Mixed</option>{PRACTICE_KINDS[dim].map(kk => <option key={kk} value={kk}>{KIND_LABEL[kk]}</option>)}\n                    </select>\n                  </label>\n                  {problem && (<>\n                    <p className=\"rounded-lg bg-indigo-50 px-3 py-2 text-sm leading-relaxed text-indigo-900\">{problem.prompt}</p>\n                    <div className=\"flex gap-2\">{problem.inputs.map((lab, i) => (\n                      <label key={i} className=\"flex min-w-0 flex-1 flex-col gap-1 text-[11px] text-gray-500\">{lab}\n                        <input type=\"number\" inputMode=\"decimal\" step=\"any\" value={typed[i]} aria-label={lab} onChange={e => { setTyped(t => t.map((x, j) => (j === i ? e.target.value : x))); setResult(null); }} className={`h-8 w-full min-w-0 rounded-md border px-2 text-sm ${result && result.wrong.includes(i) ? 'border-red-300 bg-red-50' : 'border-gray-200'}`} />\n                      </label>))}</div>\n                    <div className=\"flex flex-wrap gap-2\">\n                      <button onClick={check} className=\"rounded-lg bg-indigo-600 px-4 py-2 text-xs font-medium text-white hover:bg-indigo-700\">Check</button>\n                      <button onClick={() => newProblem()} className=\"rounded-lg border border-gray-200 bg-white px-4 py-2 text-xs text-gray-700 hover:border-indigo-300\">New problem</button>\n                      <button onClick={() => setResult({ correct: false, wrong: [], revealed: true })} className=\"rounded-lg border border-gray-200 bg-white px-3 py-2 text-xs text-gray-500\">Reveal</button>\n                    </div>\n                    {result && (\n                      <div aria-live=\"polite\" className={`rounded-lg px-3 py-2 text-xs leading-relaxed ${result.correct ? 'bg-emerald-50 text-emerald-900' : 'bg-amber-50 text-amber-900'}`}>\n                        {result.correct ? '✓ Correct!' : result.revealed ? <>Answer: <span className=\"font-semibold\">{problem.answer.map(a => fmt(a, 2)).join(', ')}</span>{problem.unit ? ` ${problem.unit}` : ''}. <span className=\"font-mono\">{problem.explain}</span></> : result.wrong.length ? `Not quite: check ${result.wrong.map(i => problem.inputs[i]).join(' and ')}.` : 'Fill in every box first.'}\n                      </div>\n                    )}\n                  </>)}\n                </div>\n              )}\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-amber-700\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">{NOTES[mode].map((n, i) => <li key={i} className=\"flex gap-2 text-xs leading-relaxed text-amber-900\"><span className=\"mt-0.5 shrink-0 text-amber-400\">•</span>{n}</li>)}</ul>\n              </div>\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-500\">✏️ Exercises</p>\n                <div className=\"space-y-2\">{EXERCISES[mode].map((ex, i) => (\n                  <div key={`${mode}-${i}`} className=\"overflow-hidden rounded-xl border border-gray-100\">\n                    <button onClick={() => setOpenEx(openEx === i ? null : i)} aria-expanded={openEx === i} className=\"flex w-full justify-between gap-2 px-3 py-2.5 text-left text-xs leading-relaxed text-gray-700 transition hover:bg-gray-50\"><span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span><span className=\"shrink-0 text-sm text-gray-300\">{openEx === i ? '▲' : '▼'}</span></button>\n                    {openEx === i && <div className=\"border-t border-gray-100 bg-emerald-50 px-3 py-2.5 text-xs leading-relaxed text-emerald-800\"><span className=\"font-medium\">Answer: </span>{ex.a}</div>}\n                  </div>))}</div>\n              </div>\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\"><p className=\"mb-2 text-xs text-gray-400\">Curriculum</p><div className=\"flex flex-wrap gap-1.5\">{CURRICULA.map(c => <span key={c} className={`rounded-full px-2 py-0.5 text-xs font-medium ${curr.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'}`}>{c}</span>)}</div></div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/equilibrium-of-forces/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useMemo, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { StaticDynamicCanvas } from '@/components/simulation/StaticDynamicCanvas';\nimport { ConcurrentForcesCanvas } from '@/components/simulation/ConcurrentForcesCanvas';\nimport { ParallelForcesCanvas } from '@/components/simulation/ParallelForcesCanvas';\nimport { FloatingBodyCanvas, BLOCK_WIDTH_M } from '@/components/simulation/FloatingBodyCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport {\n  checkBalance, forceComponents, resultant, equilibrant, vecMagnitude, vecAngleDeg,\n  netMoment, isBalanced, relativeDensity, submergedFraction, willFloat, upthrust,\n  LIQUIDS, Weight,\n} from '@/lib/physics/equilibrium';\n\ntype Topic = 'static-dynamic' | 'concurrent' | 'parallel' | 'floating';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; eq: string }> = {\n  'static-dynamic': { title: 'Static & dynamic', icon: '⚖️', sub: 'Equilibrium at rest vs at constant velocity', eq: 'ΣF = 0' },\n  concurrent:       { title: 'Concurrent forces', icon: '📐', sub: 'Non-parallel coplanar forces on a point', eq: 'ΣFx = 0, ΣFy = 0' },\n  parallel:         { title: 'Parallel forces',   icon: '⚡', sub: 'Moments — the principle of moments', eq: 'Σ(clockwise M) = Σ(anticlockwise M)' },\n  floating:         { title: 'Floating bodies',   icon: '🛟', sub: 'Density, relative density, upthrust', eq: 'Upthrust = weight of fluid displaced' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  'static-dynamic': [\n    'Equilibrium means the resultant (net) force is zero — it does NOT mean the object is at rest. A common exam trap.',\n    'STATIC equilibrium: net force = 0 AND the object is at rest (stays at rest).',\n    'DYNAMIC equilibrium: net force = 0 but the object is already moving — it continues at constant velocity (Newton\\u2019s 1st law).',\n    'If the forces are unbalanced, the object accelerates — it does not matter whether it started at rest or already moving.',\n    'Real examples of dynamic equilibrium: a car at cruising speed (driving force = resistive forces), a skydiver at terminal velocity (weight = air resistance).',\n  ],\n  concurrent: [\n    'Concurrent forces act through the SAME point. For equilibrium, they must form a CLOSED polygon when drawn tip-to-tail — if there\\u2019s a gap, that gap IS the resultant.',\n    'Equivalently: resolve every force into x and y components — for equilibrium, ΣFx = 0 AND ΣFy = 0 separately.',\n    'The equilibrant is the single extra force that would balance the others — equal in magnitude, exactly opposite in direction to the resultant.',\n    'For just TWO forces in equilibrium: they must be equal in magnitude and exactly opposite in direction (180° apart) — the simplest case of the polygon rule.',\n    'For THREE concurrent forces in equilibrium, a very common WAEC technique is Lami\\u2019s theorem: each force is proportional to the sine of the angle between the other two.',\n  ],\n  parallel: [\n    'The principle of moments: for equilibrium, the sum of clockwise moments about any point equals the sum of anticlockwise moments about that same point.',\n    'Moment (torque) = force × perpendicular distance from the pivot. Bigger force OR bigger distance both increase the turning effect — this is why a spanner with a longer handle needs less force.',\n    'A see-saw balances when W1×d1 = W2×d2 — a heavier person must sit closer to the pivot to balance a lighter person farther away.',\n    'For a beam to be in COMPLETE equilibrium, moments must balance AND the total upward force (from the pivot/supports) must equal the total downward force (the weights) — two separate conditions.',\n    'Choosing WHICH point to take moments about is a free choice in the maths — but choosing the pivot (or an unknown force\\u2019s point of application) often eliminates an unknown and simplifies the equation.',\n  ],\n  floating: [\n    'Archimedes\\u2019 principle: the upthrust on a body in a fluid equals the weight of the fluid it displaces.',\n    'A floating object displaces EXACTLY its own weight of fluid — that\\u2019s why upthrust = weight for a floating body, giving zero net force (equilibrium).',\n    'Relative density = density of a substance ÷ density of water. It has no units, and is numerically identical to density measured in g/cm³.',\n    'An object floats if its density is LESS than the liquid\\u2019s density, and sinks if its density is GREATER — equal densities give neutral buoyancy (stays wherever placed, fully submerged).',\n    'Ships made of steel float because their overall SHAPE (hollow hull) gives them a low average density, even though steel itself is far denser than water — density of the whole object matters, not the material alone.',\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  'static-dynamic': [\n    { q: 'A car travels at a constant 60 km/h on a straight, flat road. What can you say about the resultant force on it?', a: 'It is zero — constant velocity means the car is in dynamic equilibrium, so the driving force exactly equals the total resistive forces (friction + air resistance).' },\n    { q: 'A book rests on a table. Name the two forces in equilibrium and state their relationship.', a: 'Weight (down) and the normal reaction from the table (up). They are equal in magnitude and opposite in direction, giving a zero resultant — static equilibrium.' },\n    { q: 'Explain why \"equilibrium\" and \"at rest\" are not the same thing, using an example.', a: 'Equilibrium only requires zero resultant force. A parachutist falling at terminal velocity is in equilibrium (weight = air resistance) but is clearly not at rest — this is dynamic equilibrium.' },\n  ],\n  concurrent: [\n    { q: 'Two forces of 6N and 8N act at right angles to each other at a point. Find their resultant.', a: 'R = √(6²+8²) = √(36+64) = √100 = 10N (a 3-4-5 triangle scaled up).' },\n    { q: 'A force of 10N acts at 0° and a second force of 10N acts at 180°. Are they in equilibrium? Explain.', a: 'Yes — equal magnitude, exactly opposite direction, so their resultant is zero. This is the equilibrium condition for two concurrent forces.' },\n    { q: 'Three forces of equal magnitude act on a point, all in equilibrium. What must be true about the angles between them?', a: 'They must be arranged symmetrically at 120° to each other (like the letter Y) — this is the only way three equal forces can form a closed triangle.' },\n  ],\n  parallel: [\n    { q: 'A 40N weight sits 0.6m from a pivot on one side of a beam. Find the weight needed 0.8m from the pivot on the other side to balance it.', a: 'Principle of moments: 40×0.6 = W×0.8. W = 24/0.8 = 30N.' },\n    { q: 'A spanner has a handle 0.25m long. What force is needed to produce a moment of 15N·m on a bolt?', a: 'M = F×d, so F = M/d = 15/0.25 = 60N.' },\n    { q: 'Two children sit on a see-saw: a 300N child 1.5m from the pivot, and a 450N child on the other side. How far from the pivot must the second child sit to balance?', a: '300×1.5 = 450×d. d = 450/450 = 1m.' },\n  ],\n  floating: [\n    { q: 'A block of density 800 kg/m³ floats in water (1000 kg/m³). What fraction of its volume is submerged?', a: 'Fraction submerged = ρ_object/ρ_liquid = 800/1000 = 0.8 = 80%.' },\n    { q: 'An object has a relative density of 2.7. What is its actual density?', a: 'Relative density = density/density of water, so density = 2.7×1000 = 2700 kg/m³ (this is aluminium).' },\n    { q: 'A 500 cm³ block of wood (density 600 kg/m³) floats in water. Find the upthrust acting on it.', a: 'At equilibrium, upthrust = weight = mg = (0.6 kg/m³ × 0.0005 m³ shortcut: mass=600×0.0005=0.3kg) × 9.81 ≈ 2.94N.' },\n    { q: 'Explain, using density, why a steel ship floats but a solid steel block sinks.', a: 'The ship\\u2019s hollow hull encloses a large volume of air, giving the ship as a whole a much lower AVERAGE density than solid steel — low enough to be less than water\\u2019s density, so it floats. A solid steel block has no such air space, so its density (about 7800 kg/m³) stays far above water\\u2019s and it sinks.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function EquilibriumOfForcesPage() {\n  const [topic, setTopic] = useState<Topic>('static-dynamic');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  // Static / dynamic\n  const [scenario, setScenario] = useState<'static' | 'dynamic'>('static');\n  const [sdF1, setSdF1] = useState(15);\n  const [sdF2, setSdF2] = useState(15);\n  const [sdMass, setSdMass] = useState(5);\n  const [liveSd, setLiveSd] = useState({ v: 0 });\n\n  // Concurrent\n  const [magA, setMagA] = useState(10);\n  const [angleA, setAngleA] = useState(0);\n  const [magB, setMagB] = useState(10);\n  const [angleB, setAngleB] = useState(90);\n\n  // Parallel / moments\n  const [w1Force, setW1Force] = useState(20);\n  const [w1Pos, setW1Pos] = useState(-0.3);\n  const [w2Force, setW2Force] = useState(20);\n  const [w2Pos, setW2Pos] = useState(0.3);\n  const weights: Weight[] = useMemo(() => [{ force: w1Force, position: w1Pos }, { force: w2Force, position: w2Pos }], [w1Force, w1Pos, w2Force, w2Pos]);\n  const [liveTilt, setLiveTilt] = useState(0);\n\n  // Floating\n  const [objDensity, setObjDensity] = useState(600);\n  const [liqIdx, setLiqIdx] = useState(0);\n  const [blockHeight, setBlockHeight] = useState(0.2);\n  const liquid = LIQUIDS[liqIdx];\n  const [liveSubmerged, setLiveSubmerged] = useState(0);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1);\n    setLiveSd({ v: 0 }); setLiveTilt(0); setLiveSubmerged(0);\n  }, []);\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, scenario, sdF1, sdF2, sdMass, magA, angleA, magB, angleB, w1Force, w1Pos, w2Force, w2Pos, objDensity, liqIdx, blockHeight, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, topic === 'floating' ? 300 : topic === 'concurrent' ? 300 : topic === 'parallel' ? 380 : 260, 1100, topic === 'parallel' ? 340 : 0);\n\n  const lastTickRef = useRef(0);\n  const handleSdTick = useCallback((v: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 60) return;\n    lastTickRef.current = now;\n    setLiveSd({ v });\n  }, []);\n  const handleTiltTick = useCallback((angleDeg: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 60) return;\n    lastTickRef.current = now;\n    setLiveTilt(angleDeg);\n  }, []);\n  const handleFloatTick = useCallback((frac: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 60) return;\n    lastTickRef.current = now;\n    setLiveSubmerged(frac);\n  }, []);\n\n  const sdBal = checkBalance(sdF1, sdF2);\n  const A = forceComponents(magA, angleA);\n  const B = forceComponents(magB, angleB);\n  const R = resultant([A, B]);\n  const Eq = equilibrant([A, B]);\n  const netM = netMoment(weights);\n  const balanced = isBalanced(weights);\n\n  useTopicPreset(\"simulations-equilibrium-of-forces\", { \"sdF1\": setSdF1,\n    \"sdF2\": setSdF2,\n    \"sdMass\": setSdMass,\n    \"magA\": setMagA,\n    \"angleA\": setAngleA,\n    \"magB\": setMagB,\n    \"angleB\": setAngleB,\n    \"w1Force\": setW1Force,\n    \"w1Pos\": v => setW1Pos(Math.max(-0.5, Math.min(0.5, v))),\n    \"w2Force\": setW2Force,\n    \"w2Pos\": v => setW2Pos(Math.max(-0.5, Math.min(0.5, v))),\n    \"objDensity\": setObjDensity,\n    \"blockHeight\": setBlockHeight }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Mechanics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Equilibrium of forces</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span><span>{TOPIC_META[t].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                {topic === 'static-dynamic' && (\n                  <StaticDynamicCanvas key={resetKey} scenario={scenario} f1={sdF1} f2={sdF2} mass={sdMass}\n                    isRunning={isRunning} isPaused={isPaused} onTick={handleSdTick}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'concurrent' && (\n                  <ConcurrentForcesCanvas key={resetKey} magA={magA} angleA={angleA} magB={magB} angleB={angleB}\n                    isRunning={isRunning} isPaused={isPaused}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'parallel' && (\n                  <ParallelForcesCanvas key={resetKey} weights={weights}\n                    isRunning={isRunning} isPaused={isPaused} onTick={handleTiltTick}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'floating' && (\n                  <FloatingBodyCanvas key={resetKey} objDensity={objDensity} liquidDensity={liquid.density}\n                    liquidName={liquid.name} blockHeight={blockHeight}\n                    isRunning={isRunning} isPaused={isPaused} onTick={handleFloatTick}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/equilibrium\"\n                  title={`${TOPIC_META[topic].title} — A-Factor STEM Studio`}\n                  params={\n                    topic === 'static-dynamic' ? { topic, scenario, f1: sdF1, f2: sdF2, mass: sdMass }\n                    : topic === 'concurrent' ? { topic, magA, angleA, magB, angleB }\n                    : topic === 'parallel' ? { topic, w1f: w1Force, w1p: w1Pos, w2f: w2Force, w2p: w2Pos }\n                    : { topic, density: objDensity, liquid: liqIdx, h: blockHeight }\n                  } />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {topic === 'static-dynamic' && <>\n                  <div className=\"flex gap-2\">\n                    {(['static', 'dynamic'] as const).map(sc => (\n                      <button key={sc} onClick={() => setScenario(sc)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                          scenario === sc ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{sc}</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Force F₁ (right-pulling)\" unit=\"N\" value={sdF1} min={0} max={30} step={0.5} set={setSdF1} color=\"#10b981\" />\n                  <Slider label=\"Force F₂ (left-pulling)\" unit=\"N\" value={sdF2} min={0} max={30} step={0.5} set={setSdF2} color=\"#ef4444\" />\n                  <Slider label=\"Mass\" unit=\"kg\" value={sdMass} min={1} max={20} step={0.5} set={setSdMass} color=\"#6366f1\" />\n                </>}\n\n                {topic === 'concurrent' && <>\n                  <Slider label=\"Force A\" unit=\"N\" value={magA} min={1} max={20} step={0.5} set={setMagA} color=\"#6366f1\" />\n                  <Slider label=\"Angle A\" unit=\"°\" value={angleA} min={0} max={359} step={1} set={setAngleA} color=\"#818cf8\" />\n                  <Slider label=\"Force B\" unit=\"N\" value={magB} min={1} max={20} step={0.5} set={setMagB} color=\"#10b981\" />\n                  <Slider label=\"Angle B\" unit=\"°\" value={angleB} min={0} max={359} step={1} set={setAngleB} color=\"#34d399\" note=\"0° = along +x axis, measured anticlockwise\" />\n                </>}\n\n                {topic === 'parallel' && <>\n                  <Slider label=\"Weight 1\" unit=\"N\" value={w1Force} min={0} max={50} step={1} set={setW1Force} color=\"#6366f1\" />\n                  <Slider label=\"Weight 1 ruler mark\" unit=\"cm\" value={Math.round((w1Pos + 0.5) * 100)} min={0} max={100} step={1} set={v => setW1Pos(v / 100 - 0.5)} color=\"#818cf8\" note=\"Moment arm = distance from the 50 cm pivot, converted to metres.\" />\n                  <Slider label=\"Weight 2\" unit=\"N\" value={w2Force} min={0} max={50} step={1} set={setW2Force} color=\"#10b981\" />\n                  <Slider label=\"Weight 2 ruler mark\" unit=\"cm\" value={Math.round((w2Pos + 0.5) * 100)} min={0} max={100} step={1} set={v => setW2Pos(v / 100 - 0.5)} color=\"#34d399\" note=\"Moment arm = distance from the 50 cm pivot, converted to metres.\" />\n                </>}\n\n                {topic === 'floating' && <>\n                  <div className=\"flex flex-wrap gap-1.5\">\n                    {LIQUIDS.map((l, i) => (\n                      <button key={l.name} onClick={() => setLiqIdx(i)}\n                        className={`rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n                          liqIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'\n                        }`}>{l.name} ({l.density})</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Object density\" unit=\"kg/m³\" value={objDensity} min={100} max={12000} step={50} set={setObjDensity} color=\"#a78bfa\" />\n                  <Slider label=\"Block height\" unit=\"m\" value={blockHeight} min={0.05} max={0.4} step={0.01} set={setBlockHeight} color=\"#f59e0b\" />\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {topic === 'static-dynamic' && <>\n                    <StatRow label=\"Net force\" value={sdBal.netForce.toFixed(1)} unit=\"N\" color=\"text-indigo-600\" />\n                    <StatRow label=\"State\" value={sdBal.equilibrium ? 'equilibrium' : 'unbalanced'} unit=\"\" color={sdBal.equilibrium ? 'text-emerald-600' : 'text-amber-600'} />\n                    <StatRow label=\"Acceleration\" value={(sdBal.netForce / sdMass).toFixed(2)} unit=\"m/s²\" color=\"text-rose-500\" />\n                    <StatRow label=\"Live speed\" value={liveSd.v.toFixed(2)} unit=\"m/s\" color=\"text-purple-600\" />\n                  </>}\n                  {topic === 'concurrent' && <>\n                    <StatRow label=\"Resultant |R|\" value={vecMagnitude(R).toFixed(2)} unit=\"N\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Resultant angle\" value={vecAngleDeg(R).toFixed(1)} unit=\"°\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Equilibrant |E|\" value={vecMagnitude(Eq).toFixed(2)} unit=\"N\" color=\"text-rose-500\" />\n                    <StatRow label=\"Equilibrant angle\" value={vecAngleDeg(Eq).toFixed(1)} unit=\"°\" color=\"text-purple-600\" />\n                  </>}\n                  {topic === 'parallel' && <>\n                    <StatRow label=\"Net moment\" value={netM.toFixed(2)} unit=\"N·m\" color=\"text-indigo-600\" />\n                    <StatRow label=\"State\" value={balanced ? 'balanced' : 'unbalanced'} unit=\"\" color={balanced ? 'text-emerald-600' : 'text-amber-600'} />\n                    <StatRow label=\"Live tilt\" value={liveTilt.toFixed(1)} unit=\"°\" color=\"text-purple-600\" />\n                  </>}\n                  {topic === 'floating' && <>\n                    <StatRow label=\"Relative density\" value={relativeDensity(objDensity).toFixed(2)} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Will it float?\" value={willFloat(objDensity, liquid.density) ? 'yes' : 'no — sinks'} unit=\"\" color={willFloat(objDensity, liquid.density) ? 'text-emerald-600' : 'text-red-500'} />\n                    <StatRow label=\"Submerged fraction\" value={(submergedFraction(objDensity, liquid.density) * 100).toFixed(0)} unit=\"%\" color=\"text-purple-600\" />\n                    <StatRow label=\"Live submerged\" value={(liveSubmerged * 100).toFixed(0)} unit=\"%\" color=\"text-amber-600\" />\n                    <StatRow label=\"Upthrust (floating)\" value={upthrust(liquid.density, BLOCK_WIDTH_M * blockHeight * submergedFraction(objDensity, liquid.density)).toFixed(1)} unit=\"N\" color=\"text-rose-500\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[topic].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/reflection/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { ReflectionCanvas, ReflectionMode } from '@/components/simulation/ReflectionCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { thinLensImage } from '@/lib/physics/optics';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<ReflectionMode, { title: string; icon: string; sub: string; eq: string }> = {\n  plane:    { title: 'Plane mirror',  icon: '🪞', sub: 'The law of reflection',    eq: '∠i = ∠r' },\n  curved:   { title: 'Curved mirror', icon: '🛰️', sub: 'Concave & convex',        eq: '1/f = 1/u + 1/v' },\n  rotation: { title: 'Rotating mirror', icon: '🔄', sub: 'Fixed source, rotating mirror', eq: 'reflected ray turns through 2θ' },\n};\n\nconst TEACHER_NOTES: Record<ReflectionMode, string[]> = {\n  plane: [\n    'The law of reflection: the angle of incidence equals the angle of reflection (∠i = ∠r), both measured from the NORMAL — never from the mirror surface itself.',\n    'The incident ray, the reflected ray, and the normal all lie in the SAME plane — a detail examiners sometimes ask for directly.',\n    'A plane mirror image is: the same size as the object, the same distance behind the mirror as the object is in front, upright, and VIRTUAL (light doesn\\u2019t actually pass through it — it only appears to come from there).',\n    'Lateral inversion: left and right are swapped (not up and down) — why text held up to a mirror reads backwards, and why an ambulance often has \"AMBULANCE\" printed mirror-reversed on the front so drivers read it correctly in their rear-view mirror.',\n    'A plane mirror image cannot be captured on a screen (it\\u2019s virtual) — this is the standard way exams distinguish a real image from a virtual one.',\n  ],\n  curved: [\n    'Concave mirror (converging, f > 0): real images form on the SAME side as the object — the front, reflecting side.',\n    'Convex mirror (diverging, f < 0): always virtual, upright, diminished — that\\u2019s why it\\u2019s used for car wing mirrors and shop security (\"objects are closer than they appear\").',\n    'Focal length f = R/2, where R is the radius of curvature of the mirror.',\n    'Uses of concave mirrors: shaving/makeup mirrors (object inside F → magnified upright virtual image), torch and headlamp reflectors (bulb placed at F → parallel reflected beam).',\n    'A mirror only has ONE reflecting side — unlike a lens, its focal point and centre of curvature only exist on the object\\u2019s side, never \"behind\" it.',\n  ],\n  rotation: [\n    'The core result: if the incident ray is kept fixed and the mirror is rotated through an angle θ, the reflected ray turns through 2θ — TWICE the mirror\\u2019s rotation, in the same direction.',\n    'Why: rotating the mirror by θ rotates its normal by θ too (the normal is rigidly attached to the mirror surface). Since the angle of incidence is measured from the normal, it also changes by θ — and by the law of reflection, the angle of reflection changes by the same θ. The reflected ray\\u2019s total swing is the sum of both these θ shifts either side of the original ray, giving 2θ overall.',\n    'This is one of the most frequently recurring JAMB/UTME physics questions — usually phrased as \"a plane mirror is rotated through angle θ while the incident ray is kept fixed; through what angle does the reflected ray turn?\" with 2θ as the correct option among distractors like θ/2, θ, and 3θ.',\n    'The image size never changes when a plane mirror rotates — only the image POSITION changes, since a plane mirror always produces a same-size, upright, virtual image regardless of its orientation.',\n    'Real application: this principle is used in rotating-mirror devices for measuring the speed of light (Foucault\\u2019s and Michelson\\u2019s methods), in optical levers and galvanometers (a tiny needle rotation is amplified into a much larger, easily-read beam deflection), and in laser scanning/steering mirrors.',\n  ],\n};\n\nconst EXERCISES: Record<ReflectionMode, { q: string; a: string }[]> = {\n  plane: [\n    { q: 'A ray of light strikes a plane mirror at 30° to the mirror surface. Find the angle of reflection.', a: 'Angles are measured from the NORMAL, not the surface: angle of incidence = 90°−30° = 60°. By the law of reflection, angle of reflection = 60° too.' },\n    { q: 'An object stands 1.2m in front of a plane mirror. How far is its image from the object itself?', a: 'The image forms 1.2m behind the mirror, so it is 1.2+1.2 = 2.4m from the object.' },\n    { q: 'Explain why an ambulance often has its name printed backwards on the front of the vehicle.', a: 'A driver ahead sees it via their rear-view mirror, which laterally inverts it — printing it backwards means it reads correctly (forwards) once reflected.' },\n  ],\n  curved: [\n    { q: 'An object 40cm from a concave mirror of f=15cm. Find the image.', a: '1/v = 1/15 − 1/40 = 5/120 → v = 24cm: real, inverted, m = 0.6 (diminished).' },\n    { q: 'Why are convex mirrors used as driving/security mirrors?', a: 'They always give an upright, diminished, virtual image with a much wider field of view than a plane mirror of the same size.' },\n    { q: 'A concave mirror has radius of curvature 60cm. Where must a bulb be placed for the reflected beam to emerge parallel?', a: 'f = R/2 = 30cm. Placing the bulb at the focal point sends all reflected rays out parallel to the axis — the principle behind torches and headlamps.' },\n  ],\n  rotation: [\n    { q: 'A ray of light is incident on a plane mirror. If the mirror is rotated through an angle θ while the incident ray is kept fixed, through what angle is the reflected ray rotated? (A) θ/2 (B) θ (C) 2θ (D) 3θ', a: '(C) 2θ. This exact question — in this exact multiple-choice form — is one of the most frequently recurring physics questions in JAMB/UTME past papers.' },\n    { q: 'A ray of light strikes a plane mirror, making an angle of incidence of 25°. The mirror is then rotated through 12°, with the incident ray kept fixed. Find the new angle of incidence, and the angle through which the reflected ray has turned.', a: 'The angle of incidence changes by the same amount the mirror rotates: new i = 25°+12° = 37°. The reflected ray turns through 2×12° = 24°.' },\n    { q: 'A plane mirror is spun at a steady angular speed of 8 revolutions per second about an axis in its own plane, while a fixed laser beam strikes it continuously. At what angular speed does the reflected beam sweep around?', a: 'The reflected ray always rotates at exactly twice the mirror\\u2019s angular speed: 2×8 = 16 revolutions per second.' },\n    { q: 'Explain why the SIZE of the image in a plane mirror does not change as the mirror is rotated, even though its position does.', a: 'A plane mirror always forms a virtual image the same distance behind the mirror as the object is in front, and the same size as the object — this holds at every mirror orientation, since it follows purely from the law of reflection applied to a flat surface. Rotating the mirror changes WHERE that image appears (as the reflected ray direction shifts by 2θ), but not the image\\u2019s size.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function ReflectionPage() {\n  const [mode, setMode] = useState<ReflectionMode>('plane');\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [incidenceAngle, setIncidenceAngle] = useState(35);\n  const [focal, setFocal] = useState(15);\n  const [objectDist, setObjectDist] = useState(40);\n  const [converging, setConverging] = useState(true);\n\n  const [rotationAngle, setRotationAngle] = useState(15);\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [liveAngles, setLiveAngles] = useState({ mirror: 0, reflected: 0 });\n\n  const f = converging ? focal : -focal;\n  const img = thinLensImage(objectDist, f);\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, incidenceAngle, focal, objectDist, converging, rotationAngle, reset]);\n\n  const lastTickRef = useRef(0);\n  const handleRotationTick = useCallback((mirrorDeg: number, reflectedDeg: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 60) return;\n    lastTickRef.current = now;\n    setLiveAngles({ mirror: mirrorDeg, reflected: reflectedDeg });\n  }, []);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 320, 980);\n\n  useTopicPreset(\"simulations-reflection\", { \"incidenceAngle\": setIncidenceAngle,\n    \"focal\": setFocal,\n    \"objectDist\": setObjectDist,\n    \"rotationAngle\": setRotationAngle }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Optics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Reflection</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as ReflectionMode[]).map(m => (\n              <button key={m} onClick={() => { setMode(m); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span><span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{MODE_META[mode].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{MODE_META[mode].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <ReflectionCanvas key={resetKey} mode={mode} incidenceAngle={incidenceAngle}\n                  focal={focal} objectDist={objectDist} converging={converging}\n                  rotationAngle={rotationAngle} isRunning={isRunning} isPaused={isPaused}\n                  onTick={handleRotationTick}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                {mode === 'rotation' ? (\n                  <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                    onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                    onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                ) : <span />}\n                <EmbedButton path=\"/embed/reflection\"\n                  title={`${MODE_META[mode].title} — A-Factor STEM Studio`}\n                  params={\n                    mode === 'plane' ? { mode, angle: incidenceAngle }\n                    : mode === 'rotation' ? { mode, angle: rotationAngle }\n                    : { mode, focal, u: objectDist, conv: converging ? 1 : 0 }\n                  } />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {mode === 'plane' && (\n                  <Slider label=\"Angle of incidence\" unit=\"°\" value={incidenceAngle} min={5} max={80} step={1} set={setIncidenceAngle} color=\"#6366f1\"\n                    note=\"Measured from the normal, not the mirror surface\" />\n                )}\n\n                {mode === 'curved' && <>\n                  <div className=\"space-y-1.5\">\n                    <span className=\"text-xs text-gray-500\">Type</span>\n                    <div className=\"flex gap-2\">\n                      {([true, false] as const).map(c => (\n                        <button key={String(c)} onClick={() => setConverging(c)}\n                          className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                            converging === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                          }`}>\n                          {c ? 'Concave (converging)' : 'Convex (diverging)'}\n                        </button>\n                      ))}\n                    </div>\n                  </div>\n                  <Slider label=\"Focal length |f|\" unit=\"cm\" value={focal} min={5} max={40} step={1} set={setFocal} color=\"#f59e0b\" />\n                  <Slider label=\"Object distance u\" unit=\"cm\" value={objectDist} min={5} max={90} step={1} set={setObjectDist} color=\"#6366f1\"\n                    note=\"Slide the object through 2F, F and inside F — watch the image flip\" />\n                </>}\n\n                {mode === 'rotation' && (\n                  <Slider label=\"Mirror rotation θ\" unit=\"°\" value={rotationAngle} min={-35} max={35} step={1} set={setRotationAngle} color=\"#6366f1\"\n                    note=\"Press Run to sweep automatically, or set a fixed angle here while paused/reset\" />\n                )}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {mode === 'plane' && <>\n                    <StatRow label=\"Angle of reflection\" value={incidenceAngle.toFixed(0)} unit=\"°\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Image distance\" value=\"= object distance\" unit=\"\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Nature\" value=\"virtual, upright\" unit=\"\" color=\"text-purple-600\" />\n                    <StatRow label=\"Orientation\" value=\"laterally inverted\" unit=\"\" color=\"text-rose-500\" />\n                  </>}\n                  {mode === 'curved' && <>\n                    <StatRow label=\"Image distance v\" value={img.atInfinity ? '∞' : Math.abs(img.v).toFixed(1)} unit={img.atInfinity ? '' : 'cm'} color=\"text-indigo-600\" />\n                    <StatRow label=\"Magnification m\" value={img.atInfinity ? '∞' : img.m.toFixed(2)} unit=\"×\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Nature\" value={img.atInfinity ? 'at infinity' : img.real ? 'real' : 'virtual'} unit=\"\" color=\"text-amber-600\" />\n                    <StatRow label=\"Orientation\" value={img.atInfinity ? '—' : img.inverted ? 'inverted' : 'upright'} unit=\"\" color=\"text-rose-500\" />\n                    <StatRow label=\"Radius R = 2f\" value={(2 * focal).toFixed(0)} unit=\"cm\" color=\"text-purple-600\" />\n                  </>}\n                  {mode === 'rotation' && <>\n                    <StatRow label=\"Mirror rotation θ\" value={rotationAngle.toFixed(0)} unit=\"°\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Expected reflected-ray rotation\" value={(2 * rotationAngle).toFixed(0)} unit=\"°\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Live mirror angle\" value={liveAngles.mirror.toFixed(1)} unit=\"°\" color=\"text-amber-600\" />\n                    <StatRow label=\"Live reflected-ray angle\" value={liveAngles.reflected.toFixed(1)} unit=\"°\" color=\"text-rose-500\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[mode].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/friction/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef, useMemo } from 'react';\nimport { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Label, ReferenceDot, ReferenceLine } from 'recharts';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { FrictionCanvas, FrictionMode } from '@/components/simulation/FrictionCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { flatFriction, inclineDynamics, frictionCurve } from '@/lib/physics/friction';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<FrictionMode, { title: string; icon: string; sub: string; eq: string }> = {\n  flat:    { title: 'Flat surface', icon: '➡️', sub: 'Push a block along the ground', eq: 'f ≤ μsN,  f = μkN once sliding' },\n  incline: { title: 'Inclined plane', icon: '⛰️', sub: 'A block on a slope',           eq: 'tanθr = μs' },\n};\n\nconst TEACHER_NOTES: Record<FrictionMode, string[]> = {\n  flat: [\n    'Static friction is NOT fixed — it exactly matches the applied force, up to a maximum of μsN. Push harder within that limit and friction grows to match; nothing moves.',\n    'Once the applied force exceeds μsN, the block breaks free and KINETIC friction takes over — μk is always a little LESS than μs, which is why things \"jerk\" into motion.',\n    'Friction is independent of the contact area and (to a good approximation) of speed — but always proportional to the normal reaction N.',\n    'N = mg only holds here because the surface is flat and the push is horizontal — on a slope, or with an angled push, N changes.',\n    'Real applications: brake pads (want HIGH μ), ice skates and ball bearings (want LOW μ), why worn tyres skid more easily.',\n  ],\n  incline: [\n    'The angle at which a block JUST starts to slide is the angle of repose θr, where tanθr = μs — a clean way to measure friction experimentally.',\n    'On the slope, the FULL weight mg acts straight down — resolve it into two components relative to the incline: mg sinθ (down the slope, drives sliding) and mg cosθ (into the slope, balanced by the normal reaction N).',\n    'Below θr the block is static and friction exactly balances mg sinθ. Above it, friction is capped at μkN and the block slides down: a = g(sinθ − μk cosθ).',\n    'Pushing a block UP the slope needs the applied force to overcome BOTH mg sinθ and friction — and once moving, friction switches to act DOWN the slope, opposing the upward push, so more force is needed to keep it moving up than to just hold it in place.',\n    'This is literally how a plumb-line/tilt-table experiment measures μs for sand, wood, or rubber in a school lab.',\n    'A steeper slope always needs a HIGHER μ to prevent sliding — this is why steep roofs need rougher tiles.',\n  ],\n};\n\nconst EXERCISES: Record<FrictionMode, { q: string; a: string }[]> = {\n  flat: [\n    { q: 'A 10kg block has μs=0.4. What is the maximum static friction force before it starts to slide?', a: 'N=mg=10×9.81=98.1N. F_s,max=μsN=0.4×98.1=39.2N.' },\n    { q: 'A 5kg box needs 20N to start moving and 15N to keep it moving at constant velocity. Find μs and μk.', a: 'N=5×9.81=49.05N. μs=20/49.05=0.41. μk=15/49.05=0.31.' },\n    { q: 'A 2kg block slides with μk=0.25 under a 15N push. Find its acceleration.', a: 'f=μkN=0.25×2×9.81=4.9N. Net=15−4.9=10.1N. a=10.1/2=5.05 m/s².' },\n  ],\n  incline: [\n    { q: 'A block just begins to slide on a slope at 22°. Find μs.', a: 'μs = tan22° ≈ 0.40.' },\n    { q: 'A 4kg block sits on a 35° slope with μs=0.5. Does it slide? Show your working.', a: 'mg sinθ = 4×9.81×sin35° ≈ 22.5N. μs·mg cosθ = 0.5×4×9.81×cos35° ≈ 16.1N. Since 22.5N > 16.1N, YES it slides.' },\n    { q: 'A block slides down a 40° slope with μk=0.2. Find its acceleration.', a: 'a = g(sinθ − μk cosθ) = 9.81(sin40° − 0.2cos40°) ≈ 9.81(0.643−0.153) ≈ 4.81 m/s².' },\n    { q: 'A 5kg block on a 30° slope (μs=0.4, μk=0.3) is pushed with a 60N force up the slope. Find the acceleration.', a: 'mg sinθ=5×9.81×sin30°=24.5N. N=5×9.81×cos30°=42.5N. Kinetic friction=0.3×42.5=12.7N (acts down-slope, opposing the push). Net=60−24.5−12.7=22.8N. a=22.8/5≈4.56 m/s² up the slope.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nfunction ToggleChip({ label, active, onClick, color }: { label: string; active: boolean; onClick: () => void; color: string }) {\n  return (\n    <button onClick={onClick}\n      className={`flex items-center gap-1.5 rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n        active ? 'border-transparent text-white' : 'border-gray-200 bg-white text-gray-400'\n      }`}\n      style={active ? { backgroundColor: color } : undefined}>\n      <span className={`inline-block h-1.5 w-1.5 rounded-full ${active ? 'bg-white' : 'bg-gray-300'}`} />\n      {label}\n    </button>\n  );\n}\n\nfunction FrictionGraph({ mass, muS, muK, applied }: { mass: number; muS: number; muK: number; applied: number }) {\n  const fMax = mass * 9.81 * muS * 2.2;\n  const data = useMemo(() => frictionCurve(mass, muS, muK, fMax), [mass, muS, muK, fMax]);\n  const r = flatFriction(mass, applied, muS, muK);\n  const staticLimit = muS * mass * 9.81;\n  return (\n    <ResponsiveContainer width=\"100%\" height={190}>\n      <LineChart data={data} margin={{ top: 8, right: 16, left: 10, bottom: 28 }}>\n        <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n        <XAxis dataKey=\"F\" type=\"number\" tick={{ fontSize: 10 }} domain={[0, fMax]}>\n          <Label value=\"Applied force F (N)\" position=\"insideBottom\" offset={-16} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </XAxis>\n        <YAxis tick={{ fontSize: 10 }}>\n          <Label value=\"Friction f (N)\" angle={-90} position=\"insideLeft\" offset={12} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </YAxis>\n        <Tooltip formatter={(v: unknown) => [Number(v).toFixed(2) + ' N', 'f']} labelFormatter={f => `F=${Number(f).toFixed(1)}N`} />\n        <Line type=\"linear\" dataKey=\"f\" stroke=\"#6366f1\" strokeWidth={2} dot={false} isAnimationActive={false} />\n        <ReferenceLine x={staticLimit} stroke=\"#f59e0b\" strokeDasharray=\"4 4\"\n          label={{ value: 'μsN', position: 'top', fontSize: 9, fill: '#d97706' }} />\n        <ReferenceDot x={Math.min(applied, fMax)} y={r.friction} r={6} fill=\"#ef4444\" stroke=\"#fff\" strokeWidth={2} />\n      </LineChart>\n    </ResponsiveContainer>\n  );\n}\n\nexport default function FrictionPage() {\n  const [mode, setMode] = useState<FrictionMode>('flat');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [mass, setMass] = useState(5);\n  const [applied, setApplied] = useState(25);\n  const [angle, setAngle] = useState(35);\n  const [appliedIncline, setAppliedIncline] = useState(0); // 0 = gravity only (slides down if steep enough)\n  const [muS, setMuS] = useState(0.4);\n  const [muK, setMuK] = useState(0.3);\n\n  // Force-arrow visibility — purely cosmetic, shared across both modes so a\n  // preference carries over when switching tabs.\n  const [showWeight, setShowWeight] = useState(true);\n  const [showComponents, setShowComponents] = useState(true);\n  const [showNormal, setShowNormal] = useState(true);\n  const [showFriction, setShowFriction] = useState(true);\n  const [showApplied, setShowApplied] = useState(true);\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [mode, mass, applied, angle, appliedIncline, muS, muK, reset]);\n\n  const flat = flatFriction(mass, applied, muS, muK);\n  const inc = inclineDynamics(mass, angle, muS, muK, appliedIncline, 0);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 440, 1100, 360);\n\n  useTopicPreset(\"simulations-friction\", { \"mass\": setMass,\n    \"applied\": setApplied,\n    \"angle\": setAngle,\n    \"appliedIncline\": setAppliedIncline,\n    \"muS\": setMuS,\n    \"muK\": setMuK }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Mechanics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Friction</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as FrictionMode[]).map(m => (\n              <button key={m} onClick={() => { setMode(m); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span><span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{MODE_META[mode].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{MODE_META[mode].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <FrictionCanvas key={resetKey} mode={mode} mass={mass} applied={applied} angle={angle}\n                  appliedIncline={appliedIncline} muS={muS} muK={muK} isRunning={isRunning} isPaused={isPaused} resetKey={resetKey}\n                  showWeight={showWeight} showComponents={showComponents} showNormal={showNormal}\n                  showFriction={showFriction} showApplied={showApplied}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/friction\"\n                  title={`${MODE_META[mode].title} friction — A-Factor STEM Studio`}\n                  params={{ mode, mass, applied, angle, appliedIncline, muS, muK }} />\n              </div>\n\n              <div data-stage-role=\"extra\">{mode === 'flat' && (\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Friction vs applied force</p>\n                  <FrictionGraph mass={mass} muS={muS} muK={muK} applied={applied} />\n                  <p className=\"text-[10px] text-gray-400 mt-2 text-center\">\n                    Friction RISES to match F (static), then plateaus at μkN once sliding\n                  </p>\n                </div>\n              )}</div>\n\n              <div data-stage-role=\"extra\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Show forces</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  <ToggleChip label=\"Weight (mg)\" active={showWeight} onClick={() => setShowWeight(v => !v)} color=\"#8b5cf6\" />\n                  {mode === 'incline' && (\n                    <ToggleChip label=\"Components (∥ & ⊥)\" active={showComponents} onClick={() => setShowComponents(v => !v)} color=\"#a855f7\" />\n                  )}\n                  <ToggleChip label=\"Normal (N)\" active={showNormal} onClick={() => setShowNormal(v => !v)} color=\"#3b82f6\" />\n                  <ToggleChip label=\"Friction (f)\" active={showFriction} onClick={() => setShowFriction(v => !v)} color=\"#ef4444\" />\n                  <ToggleChip label=\"Applied (F)\" active={showApplied} onClick={() => setShowApplied(v => !v)} color=\"#059669\" />\n                </div>\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <Slider label=\"Mass\" unit=\"kg\" value={mass} min={1} max={20} step={0.5} set={setMass} color=\"#6366f1\" />\n                {mode === 'flat' && (\n                  <Slider label=\"Applied force\" unit=\"N\" value={applied} min={0} max={80} step={1} set={setApplied} color=\"#f59e0b\" />\n                )}\n                {mode === 'incline' && (\n                  <>\n                    <Slider label=\"Incline angle\" unit=\"°\" value={angle} min={0} max={60} step={1} set={setAngle} color=\"#f59e0b\" />\n                    <Slider label=\"Applied push (up-slope)\" unit=\"N\" value={appliedIncline} min={0} max={100} step={1} set={setAppliedIncline} color=\"#059669\"\n                      note=\"0 = gravity only. Push past mg sinθ + friction to send the block UP the slope.\" />\n                  </>\n                )}\n                <Slider label=\"Static μs\" unit=\"\" value={muS} min={0.05} max={1} step={0.01} set={v => setMuS(Math.max(v, muK))} color=\"#10b981\" />\n                <Slider label=\"Kinetic μk\" unit=\"\" value={muK} min={0.05} max={1} step={0.01} set={v => setMuK(Math.min(v, muS))} color=\"#8b5cf6\" note=\"μk is kept ≤ μs, as it always is physically\" />\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {mode === 'flat' && <>\n                    <StatRow label=\"Normal reaction N\" value={flat.N.toFixed(1)} unit=\"N\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Max static friction\" value={flat.staticMax.toFixed(1)} unit=\"N\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Current friction\" value={flat.friction.toFixed(1)} unit=\"N\" color=\"text-amber-600\" />\n                    <StatRow label=\"State\" value={flat.moving ? 'sliding' : 'static'} unit=\"\" color=\"text-rose-500\" />\n                    <StatRow label=\"Acceleration\" value={flat.acceleration.toFixed(2)} unit=\"m/s²\" color=\"text-purple-600\" />\n                  </>}\n                  {mode === 'incline' && <>\n                    <StatRow label=\"Weight (mg)\" value={inc.weight.toFixed(1)} unit=\"N\" color=\"text-violet-600\" />\n                    <StatRow label=\"Normal reaction N\" value={inc.N.toFixed(1)} unit=\"N\" color=\"text-indigo-600\" />\n                    <StatRow label=\"mg sinθ (∥ to slope)\" value={inc.gravityAlong.toFixed(1)} unit=\"N\" color=\"text-emerald-600\" />\n                    <StatRow label=\"mg cosθ (⊥ to slope)\" value={inc.gravityPerp.toFixed(1)} unit=\"N\" color=\"text-amber-600\" />\n                    <StatRow label=\"Max static friction\" value={inc.staticMax.toFixed(1)} unit=\"N\" color=\"text-rose-500\" />\n                    <StatRow label=\"Angle of repose\" value={inc.reposeAngle.toFixed(1)} unit=\"°\" color=\"text-purple-600\" />\n                    <StatRow label=\"At rest, would…\" value={inc.direction === 'static' ? 'stay still' : inc.direction === 'up' ? 'move up' : 'slide down'} unit=\"\" color=\"text-gray-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[mode].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/magnetic-effects/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { MagneticFieldCanvas, MagneticMode } from '@/components/simulation/MagneticFieldCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { fieldStraightWire, fieldSolenoid, forceOnConductor, forcePerLengthParallelWires } from '@/lib/physics/electromagnetism';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\ntype Topic = 'straight-wire' | 'solenoid' | 'motor-effect';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB', 'Undergraduate'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700', Undergraduate: 'bg-slate-200 text-slate-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; eq: string }> = {\n  'straight-wire': { title: 'Field of a straight wire', icon: '⚡', sub: \"Right-hand grip rule\",     eq: 'B = μ₀I/2πr' },\n  solenoid:        { title: 'Field of a solenoid',       icon: '🌀', sub: \"Coil acts like a magnet\", eq: 'B = μ₀nI' },\n  'motor-effect':  { title: 'Force on a conductor',      icon: '🧲', sub: \"Fleming's left-hand rule\", eq: 'F = BIL sinθ' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  'straight-wire': [\n    'A current-carrying wire is always surrounded by a magnetic field — the field lines form CONCENTRIC CIRCLES centred on the wire, in a plane perpendicular to it.',\n    'Right-hand GRIP rule: point your right thumb in the direction of conventional current flow; your curled fingers show the direction of the field.',\n    'Field strength B = μ₀I/2πr decreases with distance from the wire — double the distance, half the field.',\n    'μ₀ = 4π×10⁻⁷ T·m/A is the permeability of free space — it sets how strongly current produces a magnetic field in a vacuum (or air, to a very good approximation).',\n    'Undergraduate note: this is the direct result of Ampère\\u2019s circuital law, ∮B·dl = μ₀I_enc, applied to a circular path around the wire — the field magnitude is constant on that path by symmetry, which is exactly why it simplifies to B(2πr) = μ₀I.',\n  ],\n  solenoid: [\n    'A solenoid (a long coil of wire) produces a field just like a bar magnet: strong and uniform INSIDE, weaker and looping round from one end to the other OUTSIDE.',\n    'Right-hand rule for a solenoid: curl the fingers of your right hand in the direction the current flows around the loops — your thumb points toward the NORTH pole.',\n    'Field strength inside: B = μ₀nI, where n is the number of turns per metre (N/length) — more turns per metre, or more current, means a stronger field.',\n    'This is the working principle of an electromagnet: unlike a permanent magnet, its strength (and even its polarity) can be controlled just by adjusting the current.',\n    'Undergraduate note: B = μ₀nI is the IDEAL (infinitely long) solenoid result from Ampère\\u2019s law; a real, finite solenoid has a somewhat weaker field near its ends — about half the central value right at the opening.',\n  ],\n  'motor-effect': [\n    'A current-carrying conductor placed in an external magnetic field experiences a force — this is the MOTOR EFFECT, the basis of every electric motor and loudspeaker.',\n    \"Fleming's LEFT-hand rule (for force, distinct from the right-hand rules used for field direction): thu​Mb = Motion (force), First finger = Field, seCond finger = Current.\",\n    'Force magnitude: F = BIL sinθ, where θ is the angle between the current and the field — force is greatest (F=BIL) when the wire is perpendicular to the field, and zero when parallel to it.',\n    'Reversing EITHER the current OR the field reverses the force direction; reversing BOTH leaves it unchanged.',\n    'Undergraduate note: this is the magnetic part of the Lorentz force, F = qv×B, integrated over all the moving charges in the wire — for a straight wire this reduces exactly to F = IL×B, with the direction given by the vector cross product (equivalent to Fleming\\u2019s rule).',\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  'straight-wire': [\n    { q: 'Find the magnetic field strength 5cm from a straight wire carrying 8A. (μ₀ = 4π×10⁻⁷ T·m/A)', a: 'B = μ₀I/2πr = (4π×10⁻⁷×8)/(2π×0.05) = (2×10⁻⁷×8)/0.05 = 3.2×10⁻⁵ T = 32 µT.' },\n    { q: 'A compass is placed above a wire carrying current from south to north. If the current is reversed, what happens to the compass needle?', a: 'The needle swings to point in the opposite direction — reversing the current reverses the magnetic field direction at every point around the wire.' },\n    { q: 'The distance from a wire is tripled. By what factor does the field strength change?', a: 'B ∝ 1/r, so tripling the distance reduces the field to one third of its original value.' },\n  ],\n  solenoid: [\n    { q: 'A solenoid of length 0.4m has 800 turns and carries 3A. Find the field strength inside.', a: 'n = N/length = 800/0.4 = 2000 turns/m. B = μ₀nI = 4π×10⁻⁷×2000×3 ≈ 7.54×10⁻³ T = 7.54 mT.' },\n    { q: 'How could you increase the strength of an electromagnet without changing the current?', a: 'Add more turns per metre (wind the coil more tightly or use more loops), or insert a soft-iron core, which greatly increases the field for the same current.' },\n    { q: 'Why is soft iron (not steel) normally used as the core of an electromagnet?', a: 'Soft iron magnetises strongly when current flows but loses its magnetism almost immediately when the current stops — exactly the temporary, on/off magnetism an electromagnet needs. Steel would stay magnetised (retain the field) even after the current is switched off.' },\n  ],\n  'motor-effect': [\n    { q: 'A wire of length 0.3m carries a current of 4A perpendicular to a magnetic field of 0.6T. Find the force on it.', a: 'F = BIL sinθ = 0.6×4×0.3×sin90° = 0.72 N.' },\n    { q: 'A wire carries current parallel to a magnetic field. What force does it experience, and why?', a: 'Zero force — F = BIL sinθ, and sin(0°) = 0. A current parallel to the field has no component of current perpendicular to the field, so there is no motor-effect force.' },\n    { q: 'In a simple DC motor, why does the coil keep spinning in the same direction instead of oscillating back and forth?', a: 'The commutator reverses the current in the coil every half-turn, which reverses the force direction on each side at exactly the right moment to keep the torque acting the same rotational way, sustaining continuous rotation instead of the coil settling into equilibrium.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function MagneticEffectsPage() {\n  const [topic, setTopic] = useState<Topic>('straight-wire');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [current, setCurrent] = useState(5);\n  const [currentOut, setCurrentOut] = useState(true);\n  const [testDistanceCm, setTestDistanceCm] = useState(4);\n\n  const [turnsPerMetre, setTurnsPerMetre] = useState(1000);\n\n  const [fieldB, setFieldB] = useState(0.5);\n  const [wireLengthCm, setWireLengthCm] = useState(10);\n\n  const [liveField, setLiveField] = useState(0);\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, current, currentOut, turnsPerMetre, fieldB, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 320, 980);\n\n  const asMode: MagneticMode = topic;\n  const testFieldStatic = fieldStraightWire(current, testDistanceCm / 100);\n  const solenoidFieldStatic = fieldSolenoid(current, turnsPerMetre);\n  const forceStatic = forceOnConductor(fieldB, current, wireLengthCm / 100, 90);\n\n  useTopicPreset(\"simulations-magnetic-effects\", { \"current\": setCurrent,\n    \"testDistanceCm\": setTestDistanceCm,\n    \"turnsPerMetre\": setTurnsPerMetre,\n    \"fieldB\": setFieldB,\n    \"wireLengthCm\": setWireLengthCm }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Electricity · Electromagnetism</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Magnetic Effects of Current</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span><span>{TOPIC_META[t].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <MagneticFieldCanvas key={resetKey} mode={asMode} current={current} currentOut={currentOut}\n                  turnsPerMetre={turnsPerMetre} fieldB={fieldB}\n                  isRunning={isRunning} isPaused={isPaused} onTick={setLiveField}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/magnetic-effects\"\n                  title={`${TOPIC_META[topic].title} — A-Factor STEM Studio`}\n                  params={{ topic, current, out: currentOut ? 1 : 0, turns: turnsPerMetre, field: fieldB }} />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {topic === 'straight-wire' && <>\n                  <Slider label=\"Current\" unit=\"A\" value={current} min={1} max={20} step={1} set={setCurrent} color=\"#6366f1\" />\n                  <div className=\"flex gap-2\">\n                    {([true, false] as const).map(v => (\n                      <button key={String(v)} onClick={() => setCurrentOut(v)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                          currentOut === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{v ? 'Out of page ⊙' : 'Into page ⊗'}</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Test point distance\" unit=\"cm\" value={testDistanceCm} min={2} max={8} step={0.5} set={setTestDistanceCm} color=\"#f59e0b\" />\n                </>}\n\n                {topic === 'solenoid' && <>\n                  <Slider label=\"Current\" unit=\"A\" value={current} min={1} max={20} step={1} set={setCurrent} color=\"#6366f1\" />\n                  <div className=\"flex gap-2\">\n                    {([true, false] as const).map(v => (\n                      <button key={String(v)} onClick={() => setCurrentOut(v)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                          currentOut === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{v ? 'Top: out ⊙' : 'Top: in ⊗'}</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Turns per metre\" unit=\"n/m\" value={turnsPerMetre} min={200} max={3000} step={100} set={setTurnsPerMetre} color=\"#f59e0b\" />\n                </>}\n\n                {topic === 'motor-effect' && <>\n                  <Slider label=\"Current\" unit=\"A\" value={current} min={1} max={20} step={1} set={setCurrent} color=\"#6366f1\" />\n                  <Slider label=\"Field strength B\" unit=\"T\" value={fieldB} min={0.1} max={2} step={0.1} set={setFieldB} color=\"#f59e0b\" />\n                  <Slider label=\"Wire length\" unit=\"cm\" value={wireLengthCm} min={5} max={30} step={1} set={setWireLengthCm} color=\"#8b5cf6\" />\n                  <div className=\"flex gap-2\">\n                    {([true, false] as const).map(v => (\n                      <button key={String(v)} onClick={() => setCurrentOut(v)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                          currentOut === v ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{v ? 'Out of page ⊙' : 'Into page ⊗'}</button>\n                    ))}\n                  </div>\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {topic === 'straight-wire' && <>\n                    <StatRow label=\"B at test point\" value={(testFieldStatic * 1e6).toFixed(1)} unit=\"µT\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Live B (canvas)\" value={(liveField * 1e6).toFixed(1)} unit=\"µT\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Field direction\" value={currentOut ? 'counterclockwise' : 'clockwise'} unit=\"\" color=\"text-amber-600\" />\n                  </>}\n                  {topic === 'solenoid' && <>\n                    <StatRow label=\"B inside (centre)\" value={(solenoidFieldStatic * 1000).toFixed(2)} unit=\"mT\" color=\"text-indigo-600\" />\n                    <StatRow label=\"N pole\" value={currentOut ? 'right end' : 'left end'} unit=\"\" color=\"text-red-600\" />\n                  </>}\n                  {topic === 'motor-effect' && <>\n                    <StatRow label=\"Force F = BIL\" value={forceStatic.toFixed(3)} unit=\"N\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Direction\" value={currentOut ? 'upward' : 'downward'} unit=\"\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Parallel-wires check\" value={forcePerLengthParallelWires(current, current, 0.05).toFixed(4)} unit=\"N/m\" color=\"text-purple-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[topic].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/rectilinear-propagation/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { ShadowsCanvas } from '@/components/simulation/ShadowsCanvas';\nimport { EclipseCanvas, EclipseType } from '@/components/simulation/EclipseCanvas';\nimport { PinholeCanvas } from '@/components/simulation/PinholeCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { umbraLength, pinholeImageHeight, pinholeMagnification, SUN_ANGULAR_DIAMETER_DEG, MOON_ANGULAR_DIAMETER_DEG } from '@/lib/physics/rectilinear';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\ntype Topic = 'shadows' | 'eclipse' | 'pinhole';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; eq: string }> = {\n  shadows: { title: 'Shadows',        icon: '🌑', sub: 'Umbra & penumbra',              eq: 'light travels in straight lines' },\n  eclipse: { title: 'Eclipses',       icon: '🌘', sub: 'Solar & lunar',                  eq: 'a shadow, cast across space' },\n  pinhole: { title: 'Pinhole camera', icon: '📷', sub: 'A laboratory consequence',       eq: 'hI/v = hO/u' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  shadows: [\n    'Sources of light are LUMINOUS (produce their own light — the Sun, a candle, a bulb) or NON-LUMINOUS (only visible because they reflect light from elsewhere — the Moon, this page, a person).',\n    'A shadow forms because light travels in straight lines (rectilinear propagation) and cannot bend around an opaque object.',\n    'A POINT source produces a shadow with a sharp edge — only an umbra, no penumbra — because every ray from the single point is blocked in exactly the same way.',\n    'An EXTENDED source produces a shadow with two regions: the UMBRA (completely dark — no part of the source is visible from there) and the PENUMBRA (partially lit — only part of the source is visible from there, so some light still reaches it).',\n    'Moving the object closer to an extended source makes the penumbra relatively LARGER compared to the umbra; moving it closer to the screen makes the shadow\\u2019s edges sharper.',\n  ],\n  eclipse: [\n    'A solar eclipse happens when the Moon passes directly between the Sun and Earth, casting its shadow onto Earth\\u2019s surface — people in the umbra see a total eclipse, people in the penumbra see a partial one.',\n    'The Moon\\u2019s umbra on Earth\\u2019s surface is genuinely small — typically only 100-270km wide (the \"path of totality\") — while Earth itself is nearly 12,750km across. Only a narrow strip of Earth ever sees a total eclipse at once; a much wider (but still limited) surrounding region sees a partial eclipse, and everywhere else sees none at all.',\n    'A lunar eclipse happens when Earth passes directly between the Sun and the Moon, and the Moon passes through Earth\\u2019s shadow.',\n    'Eclipses don\\u2019t happen every month because the Moon\\u2019s orbit is tilted about 5° relative to Earth\\u2019s orbit around the Sun — most months, the Moon\\u2019s shadow (or Earth\\u2019s shadow) simply misses, passing above or below the target body.',\n    'A remarkable coincidence: the Sun is about 400 times wider than the Moon, but also about 400 times farther away — so they have almost the same apparent size in our sky, which is why the Moon can only just barely cover the Sun during a total solar eclipse.',\n    'The Moon\\u2019s orbit is slightly elliptical, so its distance from Earth (and therefore its apparent size) varies. If a solar eclipse happens while the Moon is near the farthest point of its orbit, it looks slightly smaller than the Sun and can\\u2019t fully cover it — even at perfect alignment, a bright ring of sunlight remains visible around the Moon\\u2019s edge. This is an ANNULAR eclipse (from \"annulus\", meaning ring), a genuinely different outcome from a total eclipse, not just a partial one.',\n    'This whole topic is a direct, large-scale consequence of the same rectilinear-propagation geometry used for a tabletop shadow demo — only the distances and sizes change.',\n  ],\n  pinhole: [\n    'A pinhole camera has no lens — a single small hole lets through only one straight-line ray per point on the object, which is exactly why the image forms upside down (inverted): rays from the top of the object cross the hole and land at the BOTTOM of the screen, and vice versa.',\n    'The image is always REAL (it lands on an actual screen/film) — this is a direct laboratory demonstration of rectilinear propagation, needing no lens or mirror at all.',\n    'Image height formula (similar triangles): hI/v = hO/u, where u = object-to-hole distance, v = hole-to-screen distance.',\n    'A SMALLER hole gives a sharper image (closer to one ray per object point) but a DIMMER one (less light gets through) — a genuine trade-off, and why real pinhole cameras need long exposure times.',\n    'Making the hole too large lets a whole BUNDLE of rays through each object point, and those bundles overlap on the screen — this is what blurs the image, not some separate effect, but the same straight-line geometry applied to a hole with actual size.',\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  shadows: [\n    { q: 'A point source of light is placed 20cm from an opaque disc of radius 5cm. Explain what kind of shadow forms and why.', a: 'A sharp shadow with only an umbra, no penumbra — every ray from a single point is blocked identically at the disc\\u2019s edge, so there is no region that receives partial light.' },\n    { q: 'State the two regions formed in the shadow of an extended light source, and define each.', a: 'Umbra: the region that receives no light at all from the source (completely dark). Penumbra: the region that receives light from only part of the source (partially lit).' },\n    { q: 'Why can you sometimes see a fuzzy-edged shadow under a fluorescent tube light, but a sharp-edged shadow under a small torch bulb?', a: 'A fluorescent tube is an extended source, producing a penumbra (fuzzy edge) around the umbra. A small torch bulb behaves close to a point source, giving a mostly sharp-edged shadow.' },\n  ],\n  eclipse: [\n    { q: 'Distinguish between a solar eclipse and a lunar eclipse in terms of the positions of the Sun, Earth, and Moon.', a: 'Solar eclipse: Moon is between the Sun and Earth, and the Moon\\u2019s shadow falls on Earth. Lunar eclipse: Earth is between the Sun and the Moon, and the Moon passes through Earth\\u2019s shadow.' },\n    { q: 'Explain why we do not see a solar and a lunar eclipse every single month, even though the Moon orbits Earth roughly every month.', a: 'The Moon\\u2019s orbital plane is tilted about 5° relative to Earth\\u2019s orbital plane around the Sun. Most months, this tilt carries the Moon\\u2019s shadow (or its path through Earth\\u2019s shadow) above or below the target body, so no eclipse occurs — only when the alignment is nearly exact does the shadow actually land.' },\n    { q: 'A person standing in the umbra of the Moon\\u2019s shadow during a solar eclipse sees a total eclipse. What would a person standing in the penumbra see instead?', a: 'A partial eclipse — from the penumbra, only part of the Sun\\u2019s disc is covered by the Moon, since part of the Sun is still visible from that position.' },\n    { q: 'Explain, in terms of distance, why some solar eclipses are annular rather than total.', a: 'The Moon\\u2019s orbit is slightly elliptical, so its distance from Earth varies. If the eclipse happens while the Moon is near the farthest point of its orbit, its apparent size in the sky is smaller than the Sun\\u2019s — so even at perfect alignment, the Moon\\u2019s silhouette cannot fully cover the Sun\\u2019s disc, leaving a bright ring (the annulus) visible around its edge.' },\n  ],\n  pinhole: [\n    { q: 'An object 1.6m tall stands 4m from a pinhole camera. The screen is 20cm behind the pinhole. Find the height of the image.', a: 'hI = hO×(v/u) = 1.6×(0.2/4) = 0.08m = 8cm.' },\n    { q: 'Explain, using a ray diagram argument, why the image in a pinhole camera is always inverted.', a: 'A ray from the TOP of the object must travel in a straight line through the single pinhole — since the hole is below the top of the object, that ray continues downward past the hole and lands near the BOTTOM of the screen. Likewise, a ray from the bottom of the object lands near the top. Top-to-bottom and bottom-to-top swap, so the image is upside down.' },\n    { q: 'A student makes the pinhole bigger to let in more light. What happens to the sharpness of the image, and why?', a: 'The image becomes blurrier. A larger hole allows a whole bundle of rays (not just one) from each point on the object to pass through, and these bundles land on overlapping regions of the screen instead of a single sharp point, smearing the image out.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function RectilinearPropagationPage() {\n  const [topic, setTopic] = useState<Topic>('shadows');\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n\n  const [sourceType, setSourceType] = useState<'point' | 'extended'>('extended');\n  const [sourceRadius, setSourceRadius] = useState(35);\n  const [objectRadius, setObjectRadius] = useState(24);\n  const [objectDist, setObjectDist] = useState(160);\n  const [screenDist, setScreenDist] = useState(420);\n\n  const [eclipseType, setEclipseType] = useState<EclipseType>('solar');\n  const [liveEclipseState, setLiveEclipseState] = useState<'none' | 'partial' | 'total'>('none');\n  const [orbitAngleDeg, setOrbitAngleDeg] = useState(180);\n\n  const [objectHeight, setObjectHeight] = useState(90);\n  const [pinholeObjectDist, setPinholeObjectDist] = useState(140);\n  const [pinholeScreenDist, setPinholeScreenDist] = useState(160);\n  const [pinholeRadius, setPinholeRadius] = useState(1);\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, sourceType, sourceRadius, objectRadius, objectDist, screenDist, eclipseType, orbitAngleDeg, objectHeight, pinholeObjectDist, pinholeScreenDist, pinholeRadius, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 300, 980);\n\n  const uLen = umbraLength(sourceRadius, objectRadius, objectDist);\n  const imgH = pinholeImageHeight(objectHeight, pinholeObjectDist, pinholeScreenDist);\n  const mag = pinholeMagnification(pinholeObjectDist, pinholeScreenDist);\n\n  useTopicPreset(\"simulations-rectilinear-propagation\", { \"sourceRadius\": setSourceRadius,\n    \"objectRadius\": setObjectRadius,\n    \"objectDist\": setObjectDist,\n    \"orbitAngleDeg\": setOrbitAngleDeg,\n    \"objectHeight\": setObjectHeight,\n    \"pinholeObjectDist\": setPinholeObjectDist,\n    \"pinholeScreenDist\": setPinholeScreenDist,\n    \"pinholeRadius\": setPinholeRadius }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Optics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Sources of Light & Rectilinear Propagation</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span><span>{TOPIC_META[t].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                {topic === 'shadows' && (\n                  <ShadowsCanvas key={resetKey} sourceType={sourceType} sourceRadiusPx={sourceRadius} objectRadiusPx={objectRadius}\n                    objectDistPx={objectDist} screenDistPx={screenDist}\n                    isRunning={isRunning} isPaused={isPaused}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'eclipse' && (\n                  <EclipseCanvas key={resetKey} eclipseType={eclipseType} orbitAngleDeg={orbitAngleDeg}\n                    isRunning={isRunning} isPaused={isPaused} onTick={(_a, state) => setLiveEclipseState(state)}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'pinhole' && (\n                  <PinholeCanvas objectHeightPx={objectHeight} objectDistPx={pinholeObjectDist} screenDistPx={pinholeScreenDist}\n                    pinholeRadiusPx={pinholeRadius}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                {topic !== 'pinhole' ? (\n                  <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                    onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                    onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                ) : <span />}\n                <EmbedButton path=\"/embed/rectilinear-propagation\"\n                  title={`${TOPIC_META[topic].title} — A-Factor STEM Studio`}\n                  params={\n                    topic === 'shadows' ? { topic, src: sourceType, sr: sourceRadius, or: objectRadius, od: objectDist, sd: screenDist }\n                    : topic === 'eclipse' ? { topic, type: eclipseType, angle: orbitAngleDeg }\n                    : { topic, h: objectHeight, u: pinholeObjectDist, v: pinholeScreenDist, r: pinholeRadius }\n                  } />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {topic === 'shadows' && <>\n                  <div className=\"flex gap-2\">\n                    {(['point', 'extended'] as const).map(t => (\n                      <button key={t} onClick={() => setSourceType(t)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                          sourceType === t ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{t} source</button>\n                    ))}\n                  </div>\n                  {sourceType === 'extended' && (\n                    <Slider label=\"Source size\" unit=\"px\" value={sourceRadius} min={5} max={60} step={1} set={setSourceRadius} color=\"#fbbf24\" />\n                  )}\n                  <Slider label=\"Object size\" unit=\"px\" value={objectRadius} min={8} max={50} step={1} set={setObjectRadius} color=\"#64748b\" />\n                  <Slider label=\"Object distance\" unit=\"px\" value={objectDist} min={60} max={300} step={5} set={setObjectDist} color=\"#6366f1\" />\n                  <Slider label=\"Screen distance\" unit=\"px\" value={screenDist} min={objectDist + 40} max={560} step={5} set={setScreenDist} color=\"#8b5cf6\" />\n                </>}\n\n                {topic === 'eclipse' && <>\n                  <div className=\"flex gap-2\">\n                    {(['solar', 'annular', 'lunar'] as const).map(t => (\n                      <button key={t} onClick={() => setEclipseType(t)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                          eclipseType === t ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{t}</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Moon's position in orbit\" unit=\"°\" value={orbitAngleDeg} min={0} max={359} step={1} set={setOrbitAngleDeg} color=\"#6366f1\"\n                    note=\"180° = between Sun and Earth (solar/annular node). 0°/360° = opposite side (lunar node). Press Run to orbit continuously.\" />\n                </>}\n\n                {topic === 'pinhole' && <>\n                  <Slider label=\"Object height\" unit=\"px\" value={objectHeight} min={30} max={130} step={5} set={setObjectHeight} color=\"#0f172a\" />\n                  <Slider label=\"Object distance (u)\" unit=\"px\" value={pinholeObjectDist} min={60} max={260} step={5} set={setPinholeObjectDist} color=\"#6366f1\" />\n                  <Slider label=\"Screen distance (v)\" unit=\"px\" value={pinholeScreenDist} min={40} max={260} step={5} set={setPinholeScreenDist} color=\"#8b5cf6\" />\n                  <Slider label=\"Pinhole size\" unit=\"px\" value={pinholeRadius} min={0} max={12} step={0.5} set={setPinholeRadius} color=\"#f59e0b\"\n                    note=\"0 = ideal sharp point. Larger → visibly blurs the image.\" />\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {topic === 'shadows' && <>\n                    <StatRow label=\"Shadow type\" value={sourceType === 'point' ? 'sharp (no penumbra)' : 'umbra + penumbra'} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Umbra converges at\" value={uLen === null ? 'never (source ≤ object)' : uLen.toFixed(0)} unit={uLen === null ? '' : 'px beyond object'} color=\"text-emerald-600\" />\n                  </>}\n                  {topic === 'eclipse' && <>\n                    <StatRow label=\"Current state\" value={liveEclipseState === 'total' ? 'TOTAL' : liveEclipseState === 'partial' ? 'PARTIAL' : 'none'} unit=\"\" color={liveEclipseState === 'total' ? 'text-red-600' : liveEclipseState === 'partial' ? 'text-amber-600' : 'text-gray-400'} />\n                    <StatRow label=\"Sun angular diameter\" value={SUN_ANGULAR_DIAMETER_DEG.toFixed(3)} unit=\"°\" color=\"text-amber-600\" />\n                    <StatRow label=\"Moon angular diameter\" value={MOON_ANGULAR_DIAMETER_DEG.toFixed(3)} unit=\"°\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Ratio\" value={(SUN_ANGULAR_DIAMETER_DEG / MOON_ANGULAR_DIAMETER_DEG).toFixed(3)} unit=\"\" color=\"text-purple-600\" />\n                  </>}\n                  {topic === 'pinhole' && <>\n                    <StatRow label=\"Image height\" value={imgH.toFixed(1)} unit=\"px\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Magnification v/u\" value={mag.toFixed(3)} unit=\"×\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Orientation\" value=\"inverted\" unit=\"\" color=\"text-rose-500\" />\n                    <StatRow label=\"Nature\" value=\"real\" unit=\"\" color=\"text-purple-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[topic].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/consequences-of-motion/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useEffect, useMemo } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { ElevatorCanvas } from '@/components/simulation/ElevatorCanvas';\nimport { WeightlessnessCanvas } from '@/components/simulation/WeightlessnessCanvas';\nimport { WalkingCanvas } from '@/components/simulation/WalkingCanvas';\nimport { PropulsionCanvas } from '@/components/simulation/PropulsionCanvas';\nimport { CollisionCanvas } from '@/components/simulation/CollisionCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport {\n  apparentWeight, solveCollision, rocketAnalytics, rocketStateAt,\n  ElevatorState, CollisionParams, g,\n} from '@/lib/physics/consequences';\n\ntype Topic = 'elevator' | 'weightlessness' | 'walking' | 'propulsion' | 'collision';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; law: string }> = {\n  elevator:       { title: 'Elevator / Lift',      icon: '🛗', sub: 'Apparent weight and Newton\\'s 2nd Law', law: 'R = m(g + a)' },\n  weightlessness: { title: 'Weightlessness',        icon: '🚀', sub: 'Zero apparent weight in free fall and orbit', law: 'W_app = 0 when a = −g' },\n  walking:        { title: 'Walking',               icon: '🚶', sub: 'Newton\\'s 3rd Law — action and reaction', law: 'F_foot = −F_ground' },\n  propulsion:     { title: 'Propulsion',            icon: '🛸', sub: 'Rockets, jets — momentum conservation', law: 'Thrust = v_e × ṁ' },\n  collision:      { title: 'Collision & Impact',    icon: '💥', sub: 'Elastic vs inelastic — impulse-momentum', law: 'J = Δp = FΔt' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  elevator: [\n    \"Apparent weight = R = m(g + a). When a > 0 (accelerating up), R > mg — person feels heavier.\",\n    \"When a < 0 (accelerating down), R < mg — person feels lighter. When a = −g (free fall), R = 0.\",\n    \"The scale reads apparent weight, not true weight. This is what WAEC/IGCSE questions actually ask for.\",\n    \"Common exam trap: during constant speed (a=0), the person feels exactly their true weight regardless of how fast they're going.\",\n    \"Deceleration at the top of an upward journey = acceleration downward → lighter feeling, not heavier.\",\n  ],\n  weightlessness: [\n    \"True weightlessness only exists at infinite distance from all masses. Everything else is apparent weightlessness.\",\n    \"Astronauts in the ISS aren't weightless — they're in constant free fall (orbiting). g ≈ 8.8 m/s² at ISS altitude.\",\n    \"An object in free fall experiences zero apparent weight because both the person and the scale accelerate at g.\",\n    \"Apparent weightlessness can be experienced in a falling lift, a parabolic flight path, or orbital trajectory.\",\n    \"JUPEB/IGCSE: distinguish carefully between 'gravitational field strength', 'weight', and 'apparent weight'.\",\n  ],\n  walking: [\n    \"Walking is entirely powered by Newton's 3rd Law. Your foot pushes backward on the ground; ground pushes you forward.\",\n    \"Without friction, there is no reaction force and you cannot walk — demonstrated by trying to walk on ice.\",\n    \"The forward force on a person is the ground's reaction — it's an external force that accelerates the person.\",\n    \"Common misconception: students think the push from the foot makes you move. It's the ground's reaction that moves you.\",\n    \"Swimming: hand/foot pushes water backward (action), water pushes swimmer forward (reaction). Same principle.\",\n  ],\n  propulsion: [\n    \"Rocket thrust = exhaust speed × mass flow rate (T = v_e × ṁ). Nothing to 'push against' — momentum conservation.\",\n    \"As fuel burns, rocket mass decreases → same thrust gives increasing acceleration (a = T/m, m decreasing).\",\n    \"Jet engines work in atmosphere (air provides reaction mass). Rockets carry their own oxidiser — work in vacuum.\",\n    \"Specific impulse: efficiency measure for rockets. Higher exhaust velocity = more efficient propulsion.\",\n    \"Conservation of momentum: before = 0 (at rest). After = rocket momentum + exhaust momentum. Always sums to 0.\",\n  ],\n  collision: [\n    \"Momentum is always conserved in collisions (no external forces). Kinetic energy may or may not be conserved.\",\n    \"Elastic collision: KE conserved (e=1). Inelastic: KE lost (e<1). Perfectly inelastic: objects stick together (e=0).\",\n    \"Impulse = change in momentum = FΔt. Increasing contact time (crumple zones, airbags) reduces peak force.\",\n    \"The impulse-momentum theorem is why cars have airbags — same Δp, longer Δt, smaller F on passenger.\",\n    \"WAEC exam: most collision questions just apply p_before = p_after. Check if KE is asked separately.\",\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  elevator: [\n    { q: \"A 60kg person stands in a lift accelerating upward at 2 m/s². Find their apparent weight. (g=10)\", a: \"R = m(g+a) = 60×(10+2) = 60×12 = 720 N. True weight = 600 N.\" },\n    { q: \"A 70kg person is in a lift decelerating at 3 m/s² while moving upward. Find apparent weight. (g=10)\", a: \"Decelerating upward means a = −3 m/s². R = 70×(10−3) = 70×7 = 490 N.\" },\n    { q: \"A scale reads 0 N for a 50kg person in a lift. What is happening?\", a: \"The lift is in free fall (a = −g = −10 m/s²). R = m(g + a) = 50×(10−10) = 0 N. Apparent weightlessness.\" },\n  ],\n  weightlessness: [\n    { q: \"Why do astronauts in the ISS float, even though gravity still acts on them?\", a: \"The ISS is in continuous free fall (orbiting). Both astronauts and station fall toward Earth at the same rate, so there's no normal force between them — apparent weightlessness.\" },\n    { q: \"A 80kg person is in a freely falling lift. What does a scale beneath them read?\", a: \"0 N — both person and scale fall at g, so no contact force exists between them.\" },\n    { q: \"Is there gravity on the Moon? Explain apparent weightlessness vs true weightlessness.\", a: \"Yes — g_moon ≈ 1.6 m/s². Astronauts have weight on the Moon but feel about 1/6 of Earth weight. True weightlessness only exists at infinite distance from all masses.\" },\n  ],\n  walking: [\n    { q: \"Explain why you cannot walk on a perfectly frictionless surface using Newton's Laws.\", a: \"When you push your foot backward, the ground needs friction to push back. Without friction, no reaction force acts forward on you, so by Newton's 1st Law, you don't move.\" },\n    { q: \"A 70kg person accelerates from rest to 2 m/s in 1s while walking. Find the average forward friction force.\", a: \"F = ma = 70 × (2/1) = 140 N forward (provided by ground friction as reaction to foot's push).\" },\n    { q: \"Swimming: identify the action and reaction forces when a swimmer pushes off a wall.\", a: \"Action: swimmer pushes wall backward with force F. Reaction: wall pushes swimmer forward with equal force F. Swimmer accelerates; wall (attached to Earth) doesn't noticeably move.\" },\n  ],\n  propulsion: [\n    { q: \"A rocket of mass 5000 kg ejects gas at 2000 m/s at a rate of 10 kg/s. Find thrust and initial acceleration.\", a: \"Thrust = v_e × ṁ = 2000 × 10 = 20,000 N. a = F/m = 20000/5000 = 4 m/s².\" },\n    { q: \"Why do rockets work in the vacuum of space but car engines don't?\", a: \"Rockets carry their own fuel AND oxidiser, ejecting exhaust backward. Cars need atmospheric oxygen to combust fuel. In vacuum, no air = no combustion for a car engine.\" },\n    { q: \"A 2 kg toy rocket is at rest. It ejects 0.5 kg of gas at 40 m/s. Find the rocket's speed after.\", a: \"Momentum conservation: 0 = 1.5 × v_rocket − 0.5 × 40. v_rocket = 20/1.5 ≈ 13.3 m/s.\" },\n  ],\n  collision: [\n    { q: \"A 3kg ball at 6 m/s hits a stationary 1kg ball. They stick together. Find their common velocity.\", a: \"Perfectly inelastic: (3×6 + 1×0) = (3+1)×v. v = 18/4 = 4.5 m/s.\" },\n    { q: \"A 0.1kg bullet at 400 m/s embeds in a 4.9kg block at rest. Find the block's velocity after.\", a: \"(0.1×400) = (0.1+4.9)×v. v = 40/5 = 8 m/s.\" },\n    { q: \"An airbag increases impact time from 0.01s to 0.1s for a 70kg person decelerating from 15 m/s to 0. Compare forces.\", a: \"Impulse = Δp = 70×15 = 1050 N·s. Without bag: F = 1050/0.01 = 105,000 N. With bag: F = 1050/0.1 = 10,500 N — 10× less force.\" },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nexport default function ConsequencesPage() {\n  const [topic, setTopic] = useState<Topic>('elevator');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [isComplete, setIsComplete] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  // Elevator params\n  const [elevMass, setElevMass] = useState(60);\n  const [elevState, setElevState] = useState<ElevatorState>('rest');\n  const [elevAccel, setElevAccel] = useState(3);\n\n  // Weightlessness\n  const [wlHeight, setWlHeight] = useState(400); // km orbit\n\n  // Walking\n  const [frictionEnabled, setFrictionEnabled] = useState(true);\n  const [walkingSpeed, setWalkingSpeed] = useState(1);\n\n  // Propulsion\n  const [rocketMass, setRocketMass] = useState(5000);\n  const [exhaustSpeed, setExhaustSpeed] = useState(2000);\n  const [massFlowRate, setMassFlowRate] = useState(10);\n  const [fuelFraction, setFuelFraction] = useState(0.6);\n  const [liveRocket, setLiveRocket] = useState({ t: 0, v: 0, burnedOut: false });\n\n  // Weightlessness — live readout from the falling chamber\n  const [liveFall, setLiveFall] = useState({ t: 0, distance: 0 });\n\n  // Collision\n  const [collM1, setCollM1] = useState(3);\n  const [collM2, setCollM2] = useState(2);\n  const [collU1, setCollU1] = useState(6);\n  const [collU2, setCollU2] = useState(0);\n  const [collType, setCollType] = useState<CollisionParams['type']>('perfectly-inelastic');\n  const [collE, setCollE] = useState(0.6);\n  const [collResult, setCollResult] = useState<ReturnType<typeof solveCollision> | null>(null);\n\n  // Stable object identity: without this, the instant the collision finishes\n  // (onComplete calling setCollResult/setIsComplete/setIsRunning) the page\n  // re-renders and recreates this object with a new reference. Since\n  // CollisionCanvas's phase-reset effect depends on [params], that new\n  // reference retriggers it at the exact moment impact transitions to\n  // \"after\" — resetting the whole sequence right when it should be showing\n  // the post-collision result. Same root cause as the earlier Newton's 2nd\n  // law \"vibrating block\" bug.\n  const collParams: CollisionParams = useMemo(\n    () => ({ m1: collM1, m2: collM2, u1: collU1, u2: collU2, type: collType, e: collE }),\n    [collM1, collM2, collU1, collU2, collType, collE]\n  );\n  const rocketA = rocketAnalytics(rocketMass, exhaustSpeed, massFlowRate);\n  const rocketDryMass = rocketMass * (1 - fuelFraction);\n  const rocketFuelMass = rocketMass * fuelFraction;\n  const rocketBurnout = rocketStateAt(1e9, rocketDryMass, rocketFuelMass, exhaustSpeed, massFlowRate); // final state after full burn\n  const elevAppW = apparentWeight(elevMass, elevState === 'freefall' ? -g : elevState.includes('up') ? (elevState.includes('accel') ? elevAccel : elevState.includes('decel') ? -elevAccel : 0) : elevState.includes('down') ? (elevState.includes('accel') ? -elevAccel : elevState.includes('decel') ? elevAccel : 0) : 0);\n  const collRes = solveCollision(collParams);\n\n  // Orbit g\n  const orbitG = g * Math.pow(6371 / (6371 + wlHeight), 2);\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setIsComplete(false); setResetKey(k => k + 1);\n    setCollResult(null);\n    setLiveRocket({ t: 0, v: 0, burnedOut: false });\n    setLiveFall({ t: 0, distance: 0 });\n  }, []);\n\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, elevMass, elevState, elevAccel, frictionEnabled, rocketMass, exhaustSpeed, massFlowRate, fuelFraction, wlHeight, collM1, collM2, collU1, collU2, collType, collE, reset]);\n\n  // Elevator is a tall, portrait-ish shaft; walking/collision are wide\n  // and short — pick the matching base aspect before scaling up.\n  const consBase = topic === 'elevator' ? { w: 500, h: 320 } : { w: 660, h: 200 };\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, consBase.w, consBase.h, 900);\n\n  const lastTickRef = useRef(0);\n  const handleRocketTick = useCallback((t: number, v: number, burnedOut: boolean) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 60) return;\n    lastTickRef.current = now;\n    setLiveRocket({ t, v, burnedOut });\n  }, []);\n  const handleFallTick = useCallback((t: number, distance: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 60) return;\n    lastTickRef.current = now;\n    setLiveFall({ t, distance });\n  }, []);\n\n  useTopicPreset(\"simulations-consequences-of-motion\", { \"elevMass\": setElevMass,\n    \"elevAccel\": setElevAccel,\n    \"wlHeight\": setWlHeight,\n    \"rocketMass\": setRocketMass,\n    \"fuelFraction\": setFuelFraction,\n    \"exhaustSpeed\": setExhaustSpeed,\n    \"massFlowRate\": setMassFlowRate,\n    \"collM1\": setCollM1,\n    \"collU1\": setCollU1,\n    \"collM2\": setCollM2,\n    \"collU2\": setCollU2,\n    \"collE\": setCollE }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Applications of Newton&apos;s Laws</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Consequences of motion</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n\n          {/* Topic tabs — scrollable on mobile */}\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span>\n                <span className=\"hidden sm:inline\">{TOPIC_META[t].title}</span>\n                <span className=\"sm:hidden\">{TOPIC_META[t].icon}</span>\n              </button>\n            ))}\n          </div>\n\n          {/* Equation banner */}\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].law}</span>\n          </div>\n\n          {/* Main grid */}\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n\n            {/* Canvas + controls + params */}\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n\n                {topic === 'elevator' && (\n                  <ElevatorCanvas key={resetKey} mass={elevMass} elevState={elevState}\n                    manualAccel={elevAccel} isRunning={isRunning} isPaused={isPaused}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n\n                {topic === 'weightlessness' && (\n                  <WeightlessnessCanvas key={resetKey} mass={elevMass} gValue={orbitG}\n                    isRunning={isRunning} isPaused={isPaused} onTick={handleFallTick}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n\n                {topic === 'walking' && (\n                  <WalkingCanvas speed={walkingSpeed} key={resetKey} isRunning={isRunning} isPaused={isPaused}\n                    frictionEnabled={frictionEnabled} surfaceMass={70}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n\n                {topic === 'propulsion' && (\n                  <PropulsionCanvas key={resetKey} rocketMass={rocketMass} fuelFraction={fuelFraction}\n                    exhaustSpeed={exhaustSpeed} massFlowRate={massFlowRate}\n                    isRunning={isRunning} isPaused={isPaused} onTick={handleRocketTick}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n\n                {topic === 'collision' && (\n                  <CollisionCanvas key={resetKey} params={collParams}\n                    isRunning={isRunning} isPaused={isPaused}\n                    onComplete={r => { setCollResult(r); setIsComplete(true); setIsRunning(false); }}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n              </div>\n\n              {/* Supplementary content: kept as extra explanatory context\n                  alongside the real animated canvas above, not a substitute\n                  for it. */}\n              <div data-stage-role=\"parameters\">{topic === 'weightlessness' && (\n                <div className=\"space-y-3\">\n                  <div className=\"grid grid-cols-1 sm:grid-cols-3 gap-3\">\n                    {[\n                      { label: 'On Earth surface', gv: 9.81, color: 'bg-red-50 border-red-200', textColor: 'text-red-700', icon: '🌍' },\n                      { label: `At ${wlHeight}km orbit`, gv: orbitG, color: 'bg-blue-50 border-blue-200', textColor: 'text-blue-700', icon: '🛸' },\n                      { label: 'Deep space', gv: 0, color: 'bg-purple-50 border-purple-200', textColor: 'text-purple-700', icon: '🪐' },\n                    ].map(s => (\n                      <div key={s.label} className={`rounded-xl border ${s.color} p-4 text-center`}>\n                        <span className=\"text-2xl block mb-2\">{s.icon}</span>\n                        <p className=\"text-xs text-gray-500 mb-1\">{s.label}</p>\n                        <p className={`text-lg font-bold ${s.textColor}`}>{s.gv.toFixed(2)} m/s²</p>\n                        <p className=\"text-xs font-medium mt-2 text-gray-600\">\n                          {s.gv < 0.1 ? '✓ No gravity to fall under' : s.gv < 5 ? 'Weaker gravity' : 'Full gravity — still weightless if falling'}\n                        </p>\n                      </div>\n                    ))}\n                  </div>\n                  <div className=\"rounded-xl border border-indigo-100 bg-indigo-50 p-4 text-center\">\n                    <p className=\"text-xs text-indigo-500 mb-1\">Key insight</p>\n                    <p className=\"text-sm text-indigo-800 leading-relaxed\">\n                      At {wlHeight}km altitude, g = {orbitG.toFixed(2)} m/s² — gravity is still {(orbitG / 9.81 * 100).toFixed(0)}% of Earth surface gravity.\n                      The falling chamber above reads 0N the instant it starts moving, at every altitude — astronauts float not because gravity is absent, but because they (and their station) are in continuous free fall.\n                    </p>\n                  </div>\n                  <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-3 text-center\">\n                    {[\n                      { label: 'ISS orbit', h: 400 }, { label: 'GPS orbit', h: 20200 },\n                      { label: 'GEO orbit', h: 35786 }, { label: 'Moon orbit', h: 384400 },\n                    ].map(o => (\n                      <button key={o.label} onClick={() => setWlHeight(o.h)}\n                        className={`rounded-xl border p-3 transition text-xs ${wlHeight === o.h ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white border-gray-200 text-gray-600 hover:border-gray-300'}`}>\n                        <p className=\"font-medium\">{o.label}</p>\n                        <p className=\"opacity-70\">{o.h < 1000 ? `${o.h}km` : `${(o.h / 1000).toFixed(0)}k km`}</p>\n                      </button>\n                    ))}\n                  </div>\n                </div>\n              )}</div>\n\n              <div data-stage-role=\"extra\">{topic === 'propulsion' && (\n                <div className=\"rounded-xl border border-indigo-100 bg-indigo-50 p-3 text-xs text-indigo-800\">\n                  <p className=\"font-medium mb-1\">Momentum conservation</p>\n                  <p>Before launch: total momentum = 0. Ejecting exhaust backward at {exhaustSpeed} m/s gives the rocket equal momentum forward — no external force needed, which is why rockets (unlike jets) work in a vacuum. Thrust stays constant, but as fuel burns the rocket&apos;s mass falls, so acceleration a = thrust/mass keeps climbing through the burn.</p>\n                </div>\n              )}</div>\n\n              {/* Controls */}\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls\n                  isRunning={isRunning && !isComplete} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); setIsComplete(false); }}\n                  onPause={() => setIsPaused(p => !p)}\n                  onReset={reset}\n                />\n                {isComplete && <span className=\"text-xs font-medium text-emerald-600\">✓ Complete — Reset to go again</span>}\n                {topic === 'propulsion' && liveRocket.burnedOut && (\n                  <span className=\"text-xs font-medium text-amber-600\">🔥 Engine cutoff — coasting</span>\n                )}\n              </div>\n\n              {/* Params */}\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {topic === 'elevator' && (\n                  <>\n                    <Slider label=\"Mass\" unit=\"kg\" value={elevMass} min={10} max={150} step={5} set={setElevMass} color=\"#6366f1\" />\n                    <Slider label=\"Acceleration magnitude\" unit=\"m/s²\" value={elevAccel} min={0.5} max={9.8} step={0.1} set={setElevAccel} color=\"#f59e0b\" />\n                    <div>\n                      <p className=\"text-xs text-gray-500 mb-2\">Elevator state</p>\n                      <div className=\"grid grid-cols-2 gap-1.5\">\n                        {([\n                          ['rest', 'At rest'], ['accel-up', 'Accelerating ↑'],\n                          ['constant-up', 'Constant speed ↑'], ['decel-up', 'Decelerating ↑'],\n                          ['accel-down', 'Accelerating ↓'], ['constant-down', 'Constant speed ↓'],\n                          ['decel-down', 'Decelerating ↓'], ['freefall', '🆘 Free fall'],\n                        ] as [ElevatorState, string][]).map(([s, l]) => (\n                          <button key={s} onClick={() => setElevState(s)}\n                            className={`px-2 py-2 rounded-lg text-xs font-medium border transition ${\n                              elevState === s\n                                ? s === 'freefall' ? 'bg-red-500 text-white border-red-500' : 'bg-indigo-600 text-white border-indigo-600'\n                                : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300'\n                            }`}>{l}</button>\n                        ))}\n                      </div>\n                    </div>\n                  </>\n                )}\n\n                {topic === 'weightlessness' && (\n                  <>\n                    <Slider label=\"Person mass\" unit=\"kg\" value={elevMass} min={40} max={120} step={5} set={setElevMass} color=\"#6366f1\" />\n                    <Slider label=\"Orbit altitude\" unit=\"km\" value={wlHeight} min={200} max={400000} step={100} set={setWlHeight} color=\"#8b5cf6\" />\n                  </>\n                )}\n\n                {topic === 'walking' && <Slider label=\"Walking animation speed\" unit=\"×\" value={walkingSpeed} min={0} max={3} step={0.1} set={setWalkingSpeed} color=\"#6366f1\" note=\"Changes demonstration speed, not force or mass.\" />}\n                {topic === 'walking' && (\n                  <div className=\"flex items-center justify-between rounded-xl border border-gray-100 bg-gray-50 px-4 py-3\">\n                    <div>\n                      <p className=\"text-xs font-medium text-gray-700\">Ground friction</p>\n                      <p className=\"text-[10px] text-gray-400\">{frictionEnabled ? 'Normal ground — walking works' : 'Frictionless ice — cannot walk'}</p>\n                    </div>\n                    <button onClick={() => setFrictionEnabled(f => !f)}\n                      className={`relative w-11 h-6 rounded-full transition ${frictionEnabled ? 'bg-indigo-600' : 'bg-gray-200'}`}>\n                      <span className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white shadow transition-transform ${frictionEnabled ? 'translate-x-5' : ''}`} />\n                    </button>\n                  </div>\n                )}\n\n                {topic === 'propulsion' && (\n                  <>\n                    <Slider label=\"Rocket mass (total)\" unit=\"kg\" value={rocketMass} min={500} max={50000} step={500} set={setRocketMass} color=\"#6366f1\" />\n                    <Slider label=\"Fuel fraction\" unit=\"\" value={fuelFraction} min={0.2} max={0.9} step={0.05} set={setFuelFraction} color=\"#8b5cf6\" note={`${rocketFuelMass.toFixed(0)}kg fuel, ${rocketDryMass.toFixed(0)}kg dry mass`} />\n                    <Slider label=\"Exhaust speed\" unit=\"m/s\" value={exhaustSpeed} min={200} max={5000} step={100} set={setExhaustSpeed} color=\"#f59e0b\" />\n                    <Slider label=\"Mass flow rate\" unit=\"kg/s\" value={massFlowRate} min={1} max={100} step={1} set={setMassFlowRate} color=\"#10b981\" />\n                  </>\n                )}\n\n                {topic === 'collision' && (\n                  <>\n                    <div className=\"grid grid-cols-3 gap-1 bg-gray-100 p-1 rounded-xl\">\n                      {(['elastic', 'inelastic', 'perfectly-inelastic'] as CollisionParams['type'][]).map(t => (\n                        <button key={t} onClick={() => setCollType(t)}\n                          className={`py-2 rounded-lg text-[10px] font-medium transition ${\n                            collType === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500'\n                          }`}>{t === 'perfectly-inelastic' ? 'Stick together' : t.charAt(0).toUpperCase() + t.slice(1)}</button>\n                      ))}\n                    </div>\n                    <Slider label=\"Mass 1 (blue)\" unit=\"kg\" value={collM1} min={0.5} max={10} step={0.5} set={setCollM1} color=\"#6366f1\" />\n                    <Slider label=\"Velocity 1\" unit=\"m/s\" value={collU1} min={-10} max={20} step={0.5} set={setCollU1} color=\"#6366f1\" />\n                    <Slider label=\"Mass 2 (green)\" unit=\"kg\" value={collM2} min={0.5} max={10} step={0.5} set={setCollM2} color=\"#10b981\" />\n                    <Slider label=\"Velocity 2\" unit=\"m/s\" value={collU2} min={-10} max={10} step={0.5} set={setCollU2} color=\"#10b981\" note=\"Negative = moving left\" />\n                    {collType === 'inelastic' && (\n                      <Slider label=\"Coefficient of restitution (e)\" unit=\"\" value={collE} min={0.01} max={0.99} step={0.01} set={setCollE} color=\"#f59e0b\" note=\"0 = stick together, 1 = elastic\" />\n                    )}\n                  </>\n                )}\n              </div>\n            </SimulationStage>\n\n            {/* Analytics */}\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Results</p>\n                <div className=\"space-y-2\">\n                  {topic === 'elevator' && [\n                    { l: 'True weight', v: `${(elevMass * g).toFixed(1)} N`, c: 'text-gray-600' },\n                    { l: 'Apparent weight', v: `${elevAppW.toFixed(1)} N`, c: elevAppW > elevMass * g ? 'text-emerald-600' : elevAppW < elevMass * g ? 'text-red-500' : 'text-indigo-600' },\n                    { l: 'Difference', v: `${(elevAppW - elevMass * g).toFixed(1)} N`, c: 'text-amber-600' },\n                    { l: 'Scale reads', v: `${(elevAppW / g).toFixed(2)} kg`, c: 'text-purple-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-sm font-semibold ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {topic === 'weightlessness' && [\n                    { l: 'True weight (Earth)', v: `${(elevMass * 9.81).toFixed(0)} N`, c: 'text-gray-600' },\n                    { l: `g at ${wlHeight}km`, v: `${orbitG.toFixed(2)} m/s²`, c: 'text-indigo-600' },\n                    { l: 'Weight at altitude', v: `${(elevMass * orbitG).toFixed(0)} N`, c: 'text-amber-600' },\n                    { l: 'Apparent (falling)', v: '0 N (free fall)', c: 'text-red-500' },\n                    { l: 'Fall time (live)', v: `${liveFall.t.toFixed(1)} s`, c: 'text-gray-600' },\n                    { l: 'Fallen (live)', v: `${liveFall.distance.toFixed(1)} m`, c: 'text-purple-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-sm font-semibold ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {topic === 'walking' && [\n                    { l: 'Reaction force', v: frictionEnabled ? 'Present ✓' : 'None ✗', c: frictionEnabled ? 'text-emerald-600' : 'text-red-500' },\n                    { l: 'Locomotion', v: frictionEnabled ? 'Possible ✓' : 'Impossible ✗', c: frictionEnabled ? 'text-emerald-600' : 'text-red-500' },\n                    { l: 'Action', v: 'Foot pushes back', c: 'text-gray-600' },\n                    { l: 'Reaction', v: frictionEnabled ? 'Ground pushes forward' : 'No reaction', c: frictionEnabled ? 'text-emerald-600' : 'text-red-500' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-sm font-semibold ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {topic === 'propulsion' && [\n                    { l: 'Thrust (at launch)', v: `${rocketA.thrust.toFixed(0)} N`, c: 'text-amber-600' },\n                    { l: 'Acceleration (at launch)', v: `${rocketA.acceleration.toFixed(3)} m/s²`, c: 'text-indigo-600' },\n                    { l: 'T = v_e × ṁ', v: `${exhaustSpeed}×${massFlowRate}=${rocketA.thrust.toFixed(0)}`, c: 'text-gray-600' },\n                    { l: 'Burnout speed', v: `${rocketBurnout.v.toFixed(0)} m/s`, c: 'text-purple-600' },\n                    { l: 'Live speed', v: `${liveRocket.v.toFixed(0)} m/s`, c: 'text-emerald-600' },\n                    { l: 'Live status', v: liveRocket.burnedOut ? 'Coasting (Newton 1st)' : liveRocket.t > 0 ? 'Burning' : 'Ready', c: liveRocket.burnedOut ? 'text-amber-600' : 'text-gray-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-sm font-semibold ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {topic === 'collision' && [\n                    { l: 'v₁ after', v: `${collRes.v1.toFixed(2)} m/s`, c: 'text-indigo-600' },\n                    { l: 'v₂ after', v: `${collRes.v2.toFixed(2)} m/s`, c: 'text-emerald-600' },\n                    { l: 'p before', v: `${collRes.momentumBefore.toFixed(2)} kg·m/s`, c: 'text-gray-600' },\n                    { l: 'p after', v: `${collRes.momentumAfter.toFixed(2)} kg·m/s`, c: 'text-gray-600' },\n                    { l: 'KE lost', v: `${collRes.keLost.toFixed(2)} J`, c: collRes.keLost < 0.01 ? 'text-emerald-600' : 'text-red-500' },\n                    { l: 'Impulse', v: `${collRes.impulse.toFixed(2)} N·s`, c: 'text-amber-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-sm font-semibold ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            {/* Teacher notes + exercises */}\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[topic].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i+1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/electrostatics-fields/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { CoulombsLawCanvas } from '@/components/simulation/CoulombsLawCanvas';\nimport { ElectricFieldCanvas, FieldConfiguration } from '@/components/simulation/ElectricFieldCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { coulombForceSigned } from '@/lib/physics/electrostatics';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\ntype Topic = 'coulomb' | 'field';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; eq: string }> = {\n  coulomb: { title: \"Coulomb's law\", icon: '🧲', sub: 'Force between two point charges', eq: 'F = kQ₁Q₂/r²' },\n  field:   { title: 'Electric field', icon: '🌐', sub: 'Field lines & field strength',     eq: 'E = kQ/r² = F/q' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  coulomb: [\n    \"Coulomb's law: F = kQ₁Q₂/r², where k ≈ 8.99×10⁹ N·m²/C² (often written 1/4πε₀).\",\n    'Like charges REPEL (positive force by the sign convention here), unlike charges ATTRACT — the direction follows automatically from the signs of Q₁ and Q₂ in the formula.',\n    'The force obeys an INVERSE-SQUARE law: doubling the separation cuts the force to a quarter, not a half — a very commonly tested numeric trap.',\n    \"Coulomb's law has the same mathematical FORM as Newton's law of gravitation (F=Gm₁m₂/r²) — both are inverse-square laws — but electric forces can be attractive OR repulsive, while gravity is always attractive.\",\n    'The released charges shown here accelerate because force causes acceleration (F=ma) — as they separate, the force (and so the acceleration) drops rapidly, which is why the motion visibly slows down even though the charges keep moving apart.',\n  ],\n  field: [\n    'Electric field strength E at a point is the force per unit positive charge placed there: E = F/q. It is a vector — it has both magnitude and direction.',\n    'For a point charge, E = kQ/r² — the same inverse-square dependence as Coulomb\\u2019s law, since E is just the force ONE unit of charge would feel.',\n    'Field line rules: they point in the direction a small POSITIVE test charge would move; they start on positive charges (or infinity) and end on negative charges (or infinity); they never cross; closer lines mean a stronger field.',\n    'Around a single charge, field lines are straight and radial — outward from a positive charge, inward toward a negative one.',\n    'Between two EQUAL like charges, there is a NULL POINT exactly at the midpoint where the two fields cancel exactly to zero — a test charge placed there feels no net force at all.',\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  coulomb: [\n    { q: 'Two point charges of +3μC and +5μC are 0.2m apart. Find the force between them.', a: 'F = kQ₁Q₂/r² = (8.99×10⁹ × 3×10⁻⁶ × 5×10⁻⁶) / (0.2)² = 134.9/0.04 = 3.37N (repulsive, since both charges are positive).' },\n    { q: 'The distance between two charges is tripled. By what factor does the force between them change?', a: 'F ∝ 1/r², so tripling r reduces F by a factor of 1/3² = 1/9 — the new force is one-ninth of the original.' },\n    { q: 'A +2μC charge and a −4μC charge are 0.1m apart. Find the magnitude and nature of the force between them.', a: 'F = kQ₁Q₂/r² = (8.99×10⁹ × 2×10⁻⁶ × 4×10⁻⁶) / (0.1)² = 71.9/0.01 = 7.19N. Since the charges have opposite signs, the force is attractive.' },\n  ],\n  field: [\n    { q: 'Find the electric field strength at a point 0.3m from a +6μC charge.', a: 'E = kQ/r² = (8.99×10⁹ × 6×10⁻⁶) / (0.3)² = 53940/0.09 = 599,333 N/C (directed away from the charge, since it is positive).' },\n    { q: 'A charge of +2μC placed at a point experiences a force of 0.5N. Find the electric field strength at that point.', a: 'E = F/q = 0.5 / (2×10⁻⁶) = 250,000 N/C.' },\n    { q: 'Explain why field lines can never cross one another.', a: 'The field at any point has one definite direction. If two field lines crossed, the field at that crossing point would have two different directions at once, which is impossible — so field lines never cross.' },\n    { q: 'Two equal positive point charges sit 10cm apart. Describe the field at the point exactly midway between them.', a: 'The field is zero at that midpoint — a null point. Each charge pushes a test charge there with equal magnitude but exactly opposite direction (both charges repel a positive test charge away from themselves, i.e. toward the other charge and away from itself simultaneously), so the two contributions cancel exactly.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function ElectrostaticsFieldsPage() {\n  const [topic, setTopic] = useState<Topic>('coulomb');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [q1nC, setQ1nC] = useState(20);\n  const [q2nC, setQ2nC] = useState(20);\n  const [separationCm, setSeparationCm] = useState(10);\n  const [liveCoulomb, setLiveCoulomb] = useState({ sep: 10, force: 0 });\n\n  const [fieldConfig, setFieldConfig] = useState<FieldConfiguration>('single-positive');\n  const [testX, setTestX] = useState(0.75);\n  const [testY, setTestY] = useState(0.3);\n  const [liveField, setLiveField] = useState(0);\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, q1nC, q2nC, separationCm, fieldConfig, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 340, 1100, 300);\n\n  const staticForceN = coulombForceSigned(q1nC * 1e-9, q2nC * 1e-9, separationCm / 100);\n\n  useTopicPreset(\"simulations-electrostatics-fields\", { \"q1nC\": setQ1nC,\n    \"q2nC\": setQ2nC,\n    \"separationCm\": setSeparationCm,\n    \"testX\": setTestX,\n    \"testY\": setTestY }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Electricity · Electrostatics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Coulomb&apos;s Law &amp; Electric Fields</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span><span>{TOPIC_META[t].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                {topic === 'coulomb' && (\n                  <CoulombsLawCanvas key={resetKey} q1nC={q1nC} q2nC={q2nC} initialSeparationCm={separationCm}\n                    isRunning={isRunning} isPaused={isPaused} onTick={(sep, force) => setLiveCoulomb({ sep, force })}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'field' && (\n                  <ElectricFieldCanvas onTestPositionChange={(x, y) => { setTestX(x); setTestY(y); }} key={resetKey} configuration={fieldConfig} testX={testX} testY={testY}\n                    isRunning={isRunning} isPaused={isPaused} onTick={setLiveField}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/electrostatics-fields\"\n                  title={`${TOPIC_META[topic].title} — A-Factor STEM Studio`}\n                  params={\n                    topic === 'coulomb' ? { topic, q1: q1nC, q2: q2nC, sep: separationCm }\n                    : { topic, config: fieldConfig }\n                  } />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {topic === 'coulomb' && <>\n                  <Slider label=\"Charge Q₁\" unit=\"nC\" value={q1nC} min={-50} max={50} step={5} set={setQ1nC} color=\"#dc2626\" note=\"Negative = negative charge\" />\n                  <Slider label=\"Charge Q₂\" unit=\"nC\" value={q2nC} min={-50} max={50} step={5} set={setQ2nC} color=\"#2563eb\" />\n                  <Slider label=\"Initial separation\" unit=\"cm\" value={separationCm} min={5} max={30} step={1} set={setSeparationCm} color=\"#6366f1\"\n                    note=\"Press Run to release the charges and watch them respond to the force\" />\n                </>}\n\n                {topic === 'field' && <>\n                  <div className=\"grid grid-cols-2 gap-2\">\n                    {([\n                      ['single-positive', 'Single +'], ['single-negative', 'Single −'],\n                      ['dipole', 'Dipole (+/−)'], ['like-charges', 'Like charges (+/+)'],\n                    ] as [FieldConfiguration, string][]).map(([cfg, label]) => (\n                      <button key={cfg} onClick={() => setFieldConfig(cfg)}\n                        className={`rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                          fieldConfig === cfg ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{label}</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Test point — horizontal\" unit=\"\" value={testX} min={0.05} max={0.95} step={0.01} set={setTestX} color=\"#f59e0b\" />\n                  <Slider label=\"Test point — vertical\" unit=\"\" value={testY} min={0.1} max={0.9} step={0.01} set={setTestY} color=\"#f59e0b\"\n                    note=\"Drag to explore the field strength and direction at different points\" />\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {topic === 'coulomb' && <>\n                    <StatRow label=\"Force (at slider r)\" value={Math.abs(staticForceN) < 1e-3 ? (Math.abs(staticForceN) * 1e6).toFixed(2) : (Math.abs(staticForceN) * 1e3).toFixed(3)} unit={Math.abs(staticForceN) < 1e-3 ? 'µN' : 'mN'} color=\"text-indigo-600\" />\n                    <StatRow label=\"Nature\" value={staticForceN > 0 ? 'repulsive' : staticForceN < 0 ? 'attractive' : 'none'} unit=\"\" color={staticForceN > 0 ? 'text-amber-600' : 'text-emerald-600'} />\n                    <StatRow label=\"Live separation\" value={liveCoulomb.sep.toFixed(1)} unit=\"cm\" color=\"text-purple-600\" />\n                    <StatRow label=\"Live force\" value={Math.abs(liveCoulomb.force) < 1e-3 ? (Math.abs(liveCoulomb.force) * 1e6).toFixed(2) : (Math.abs(liveCoulomb.force) * 1e3).toFixed(3)} unit={Math.abs(liveCoulomb.force) < 1e-3 ? 'µN' : 'mN'} color=\"text-rose-500\" />\n                  </>}\n                  {topic === 'field' && <>\n                    <StatRow label=\"Configuration\" value={fieldConfig.replace('-', ' ')} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Relative field at test point\" value={liveField.toFixed(4)} unit=\"\" color=\"text-amber-600\" />\n                    <StatRow label=\"Field direction\" value=\"shown by the amber arrow\" unit=\"\" color=\"text-emerald-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[topic].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/newtons-laws/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useMemo, useRef, useEffect } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { NewtonsFirstCanvas } from '@/components/simulation/NewtonsFirstCanvas';\nimport { NewtonsSecondCanvas } from '@/components/simulation/NewtonsSecondCanvas';\nimport { NewtonsThirdCanvas } from '@/components/simulation/NewtonsThirdCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { NewtonsGraph } from '@/components/simulation/NewtonsGraph';\nimport { ThirdLawGraph } from '@/components/simulation/ThirdLawGraph';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport {\n  secondLawAnalytics, thirdLawAnalytics, firstLawTrajectory, secondLawTrajectory, thirdLawTrajectory,\n  firstLawAcceleration, ROCKET_GRAPH_DURATION, FirstLawState, SecondLawState,\n} from '@/lib/physics/newtons-laws';\n\ntype Law = '1st' | '2nd' | '3rd';\ntype GraphType = 'v' | 'a' | 'x';\ntype Scenario3 = 'push' | 'rocket' | 'collision';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst LAW_META = {\n  '1st': { title: \"Newton's 1st law\", sub: 'Law of inertia', eq: 'ΣF = 0 → v = constant', color: '#6366f1' },\n  '2nd': { title: \"Newton's 2nd law\", sub: 'Law of acceleration', eq: 'F = ma', color: '#10b981' },\n  '3rd': { title: \"Newton's 3rd law\", sub: 'Law of action & reaction', eq: 'F₁₂ = −F₂₁', color: '#f59e0b' },\n};\n\nconst TEACHER_NOTES: Record<Law, string[]> = {\n  '1st': [\n    \"An object stays at rest or moves at constant velocity unless a net external force acts on it.\",\n    \"Inertia is the resistance to change in motion — heavier objects have more inertia.\",\n    \"On a frictionless surface (μ=0), a moving block never stops. On Earth, friction provides the net force.\",\n    \"Common misconception: students think a moving object needs a continuous force to keep moving. It doesn't — only to accelerate it.\",\n    \"Demonstrate: set initial velocity, then toggle friction on/off mid-animation to show inertia.\",\n  ],\n  '2nd': [\n    \"F = ma: net force equals mass times acceleration. Doubling force doubles acceleration; doubling mass halves it.\",\n    \"Net force, not applied force, causes acceleration. Subtract friction: F_net = F_applied − μmg.\",\n    \"The F-a relationship is linear — the graph of a vs F (constant m) is a straight line through the origin.\",\n    \"Unit check: 1 Newton = 1 kg·m/s². If m=2kg and a=3m/s², F_net=6N.\",\n    \"Show students: with enough friction, a block won't move even with applied force (static friction ≥ F_applied).\",\n  ],\n  '3rd': [\n    \"For every action there is an equal and opposite reaction — the forces act on DIFFERENT objects.\",\n    \"Common exam trap: students cancel action-reaction pairs. They can't — they act on different bodies.\",\n    \"Rocket propulsion: hot gas is pushed backward (action), rocket is pushed forward (reaction).\",\n    \"The forces are always equal in magnitude — but accelerations differ because masses differ (a = F/m).\",\n    \"Walking: you push the ground backward (action), the ground pushes you forward (reaction).\",\n  ],\n};\n\nconst EXERCISES: Record<Law, { q: string; a: string }[]> = {\n  '1st': [\n    { q: \"A 5kg block moves at 10 m/s on a frictionless surface. What net force is needed to maintain this speed?\", a: \"Zero — by Newton's 1st law, no net force is needed to maintain constant velocity. ΣF = 0.\" },\n    { q: \"A 10kg block is pushed at 4 m/s and then released on a surface with μ = 0.3. Find the deceleration. (g=10 m/s²)\", a: \"Friction = μmg = 0.3×10×10 = 30N. a = F/m = 30/10 = 3 m/s² deceleration.\" },\n    { q: \"Why do passengers lurch forward when a bus brakes suddenly?\", a: \"Passengers tend to continue moving at the bus's original speed (inertia) while the bus decelerates. The seat provides no forward force, so they lurch forward relative to the bus.\" },\n  ],\n  '2nd': [\n    { q: \"A 4kg block is pushed with 20N on a surface with μ = 0.25. Find the acceleration. (g=10 m/s²)\", a: \"Friction = 0.25×4×10 = 10N. F_net = 20−10 = 10N. a = 10/4 = 2.5 m/s²\" },\n    { q: \"A force of 30N gives a 6kg object an acceleration of 4 m/s². Find the frictional force.\", a: \"F_net = ma = 6×4 = 24N. Friction = F_applied − F_net = 30−24 = 6N\" },\n    { q: \"How long does it take a 3kg block to reach 12 m/s if pushed with 15N on a frictionless surface?\", a: \"a = F/m = 15/3 = 5 m/s². t = v/a = 12/5 = 2.4s\" },\n  ],\n  '3rd': [\n    { q: \"A 70kg person stands on a 500kg boat and pushes the boat with 100N. Find both accelerations.\", a: \"Both experience 100N. Person: a=100/70=1.43 m/s² backward. Boat: a=100/500=0.2 m/s² forward.\" },\n    { q: \"A rocket of mass 2000kg expels gas producing 40,000N thrust. Find the rocket's acceleration.\", a: \"a = F/m = 40000/2000 = 20 m/s². (Ignoring gravity and changing mass for simplicity.)\" },\n    { q: \"Why does a gun recoil when fired? Use Newton's 3rd Law.\", a: \"The gun exerts force on bullet (action, bullet moves forward). Bullet exerts equal and opposite force on gun (reaction, gun recoils backward). Forces equal, but gun's larger mass means smaller acceleration.\" },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nexport default function NewtonsLawsPage() {\n  const [law, setLaw] = useState<Law>('1st');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [isComplete, setIsComplete] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n  const [graphType, setGraphType] = useState<GraphType>('v');\n  // Live marker position only — the curve itself is precomputed up front\n  // (see the ghost-trajectory useMemos below) and shown in full immediately,\n  // so this just tracks \"where on that curve are we right now\".\n  const [live1st, setLive1st] = useState({ t: 0, v: 0, a: 0, x: 0 });\n  const [live2nd, setLive2nd] = useState({ t: 0, v: 0, a: 0, x: 0 });\n  const [live3rd, setLive3rd] = useState({ t: 0, v1: 0, v2: 0 });\n\n  // 1st law params\n  const [mass1, setMass1] = useState(5);\n  const [friction1, setFriction1] = useState(0);\n  const [initV, setInitV] = useState(5);\n  const [forceOn, setForceOn] = useState(false);\n  const [force1, setForce1] = useState(10);\n\n  // 2nd law params\n  const [mass2, setMass2] = useState(5);\n  const [applied, setApplied] = useState(30);\n  const [friction2, setFriction2] = useState(0.2);\n\n  // 3rd law params\n  const [mass3a, setMass3a] = useState(5);\n  const [mass3b, setMass3b] = useState(10);\n  const [force3, setForce3] = useState(20);\n  const [scenario3, setScenario3] = useState<Scenario3>('push');\n\n  const secAnalytics = secondLawAnalytics({ mass: mass2, appliedForce: applied, friction: friction2 });\n  const thdAnalytics = thirdLawAnalytics({ type: scenario3, mass1: mass3a, mass2: mass3b, force: force3 });\n\n  // Stable object identity: without this, every graph tick (setGraphData)\n  // re-renders the page and recreates this object as a new reference, which\n  // re-triggers NewtonsSecondCanvas's reset effect on every single frame —\n  // snapping the block back to the start each tick (\"vibrating on the\n  // spot\") and collapsing the graph's time axis back near 0 repeatedly.\n  const secondLawParams = useMemo(\n    () => ({ mass: mass2, appliedForce: applied, friction: friction2 }),\n    [mass2, applied, friction2]\n  );\n\n  // Precomputed \"ghost\" curves — the whole predicted picture, available the\n  // instant a slider changes, before Run is ever pressed.\n  const firstLawGhost = useMemo(\n    () => firstLawTrajectory(mass1, friction1, initV, forceOn, force1),\n    [mass1, friction1, initV, forceOn, force1]\n  );\n  const secondLawGhost = useMemo(() => secondLawTrajectory(secondLawParams), [secondLawParams]);\n  const thirdLawGhost = useMemo(\n    () => thirdLawTrajectory(scenario3, mass3a, mass3b, force3),\n    [scenario3, mass3a, mass3b, force3]\n  );\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const lastTickRef = useRef(0);\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setIsComplete(false); setResetKey(k => k + 1);\n    setLive1st({ t: 0, v: 0, a: 0, x: 0 });\n    setLive2nd({ t: 0, v: 0, a: 0, x: 0 });\n    setLive3rd({ t: 0, v1: 0, v2: 0 });\n    lastTickRef.current = 0;\n  }, []);\n\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [law, mass1, friction1, initV, force1, mass2, applied, friction2, mass3a, mass3b, force3, scenario3, reset]);\n\n  const handle1stTick = useCallback((s: FirstLawState) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 40) return;\n    lastTickRef.current = now;\n    const a = firstLawAcceleration(s.v, mass1, friction1, forceOn ? force1 : 0);\n    setLive1st({ t: s.time, v: s.v, a, x: s.x });\n  }, [mass1, friction1, forceOn, force1]);\n\n  const handle2ndTick = useCallback((s: SecondLawState) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 40) return;\n    lastTickRef.current = now;\n    setLive2nd({ t: s.time, v: s.v, a: s.a, x: s.x });\n  }, []);\n\n  const handle3rdTick = useCallback((t: number, v1: number, v2: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 40) return;\n    lastTickRef.current = now;\n    setLive3rd({ t, v1, v2 });\n  }, []);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 210, 980);\n\n  useTopicPreset(\"simulations-newtons-laws\", { \"mass1\": setMass1,\n    \"initV\": setInitV,\n    \"friction1\": setFriction1,\n    \"force1\": setForce1,\n    \"mass2\": setMass2,\n    \"applied\": setApplied,\n    \"friction2\": setFriction2,\n    \"mass3a\": setMass3a,\n    \"mass3b\": setMass3b,\n    \"force3\": setForce3 }, { \"law\": (value: string) => setLaw(value as typeof law) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Mechanics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Newton&apos;s laws of motion</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n\n          {/* Law tabs */}\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(['1st', '2nd', '3rd'] as Law[]).map(l => (\n              <button key={l} onClick={() => { setLaw(l); setOpenEx(null); }}\n                className={`shrink-0 px-4 py-2 rounded-lg text-xs font-medium transition ${\n                  law === l ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                {LAW_META[l].title}\n              </button>\n            ))}\n          </div>\n\n          {/* Equation banner */}\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{LAW_META[law].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{LAW_META[law].eq}</span>\n          </div>\n\n          {/* Main layout */}\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n\n            {/* Col 1: Canvas + controls + sliders */}\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                {law === '1st' && (\n                  <NewtonsFirstCanvas\n                    key={resetKey} mass={mass1} friction={friction1}\n                    initialVelocity={initV} forceOn={forceOn} appliedForce={force1}\n                    isRunning={isRunning} isPaused={isPaused} onTick={handle1stTick}\n                    width={canvasSize.width} height={canvasSize.height}\n                  />\n                )}\n                {law === '2nd' && (\n                  <NewtonsSecondCanvas\n                    key={resetKey} params={secondLawParams}\n                    isRunning={isRunning} isPaused={isPaused} onTick={handle2ndTick}\n                    onComplete={() => { setIsComplete(true); setIsRunning(false); }}\n                    width={canvasSize.width} height={canvasSize.height}\n                  />\n                )}\n                {law === '3rd' && (\n                  <NewtonsThirdCanvas\n                    key={resetKey} mass1={mass3a} mass2={mass3b} force={force3}\n                    scenario={scenario3} isRunning={isRunning} isPaused={isPaused}\n                    onTick={handle3rdTick}\n                    width={canvasSize.width} height={canvasSize.height}\n                  />\n                )}\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls\n                  isRunning={isRunning && !isComplete} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); setIsComplete(false); }}\n                  onPause={() => setIsPaused(p => !p)}\n                  onReset={reset}\n                />\n                {isComplete && <span className=\"text-xs font-medium text-emerald-600\">✓ Complete — Reset to go again</span>}\n              </div>\n\n              {/* Live graph — full predicted curve shown immediately, with a\n                  live marker riding along it as the animation plays. */}\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <div className=\"flex items-center justify-between mb-3\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">\n                    {law === '3rd' ? 'Velocity graph' : 'Live graph'}\n                  </p>\n                  {law !== '3rd' && (\n                    <div className=\"flex gap-1 bg-gray-100 p-0.5 rounded-lg\">\n                      {(['v', 'a', 'x'] as GraphType[]).map(g => (\n                        <button key={g} onClick={() => setGraphType(g)}\n                          className={`px-3 py-2 rounded-md text-xs font-medium transition ${\n                            graphType === g ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500'\n                          }`}>{g === 'v' ? 'Velocity' : g === 'a' ? 'Acceleration' : 'Displacement'}</button>\n                      ))}\n                    </div>\n                  )}\n                </div>\n                {law === '1st' && (\n                  <NewtonsGraph data={firstLawGhost} show={graphType} liveT={live1st.t} liveValue={live1st[graphType]} />\n                )}\n                {law === '2nd' && (\n                  <NewtonsGraph data={secondLawGhost} show={graphType} liveT={live2nd.t} liveValue={live2nd[graphType]} />\n                )}\n                {law === '3rd' && (() => {\n                  const rocketA = force3 / mass3a;\n                  const wrappedT = scenario3 === 'rocket' ? live3rd.t % ROCKET_GRAPH_DURATION : live3rd.t;\n                  const wrappedV1 = scenario3 === 'rocket' ? rocketA * wrappedT : live3rd.v1;\n                  return (\n                    <ThirdLawGraph data={thirdLawGhost} scenario={scenario3}\n                      liveT={wrappedT} liveV1={wrappedV1} liveV2={live3rd.v2} />\n                  );\n                })()}\n              </div>\n\n              <div data-stage-role=\"extra\">{law === '3rd' && (\n                <p className=\"text-[10px] text-gray-400 -mt-2 px-1\">\n                  {scenario3 === 'rocket'\n                    ? 'Rocket velocity keeps climbing as fuel burns — this graph loops to show the same constant-acceleration shape each cycle.'\n                    : 'Same force, different acceleration: the lighter object always reaches a larger speed by the time contact ends.'}\n                </p>\n              )}</div>\n\n              {/* Sliders */}\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {law === '1st' && (\n                  <>\n                    <Slider label=\"Mass\" unit=\"kg\" value={mass1} min={1} max={20} step={0.5} set={setMass1} color=\"#6366f1\" />\n                    <Slider label=\"Initial velocity\" unit=\"m/s\" value={initV} min={0} max={20} step={0.5} set={setInitV} color=\"#f59e0b\" />\n                    <Slider label=\"Friction coefficient μ\" unit=\"\" value={friction1} min={0} max={0.8} step={0.01} set={setFriction1} color=\"#ef4444\" note=\"0 = frictionless surface\" />\n                    <div className=\"flex items-center justify-between rounded-xl border border-gray-100 bg-gray-50 px-4 py-3\">\n                      <div>\n                        <p className=\"text-xs font-medium text-gray-700\">Applied force</p>\n                        <p className=\"text-[10px] text-gray-400\">Toggle to show Newton&apos;s 1st law</p>\n                      </div>\n                      <button onClick={() => setForceOn(f => !f)}\n                        className={`relative w-11 h-6 rounded-full transition ${forceOn ? 'bg-indigo-600' : 'bg-gray-200'}`}>\n                        <span className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white shadow transition-transform ${forceOn ? 'translate-x-5' : ''}`} />\n                      </button>\n                    </div>\n                    {forceOn && (\n                      <Slider label=\"Force\" unit=\"N\" value={force1} min={1} max={50} step={1} set={setForce1} color=\"#10b981\" />\n                    )}\n                  </>\n                )}\n\n                {law === '2nd' && (\n                  <>\n                    <Slider label=\"Mass\" unit=\"kg\" value={mass2} min={1} max={20} step={0.5} set={setMass2} color=\"#6366f1\" />\n                    <Slider label=\"Applied force\" unit=\"N\" value={applied} min={1} max={100} step={1} set={setApplied} color=\"#10b981\" />\n                    <Slider label=\"Friction coefficient μ\" unit=\"\" value={friction2} min={0} max={0.8} step={0.01} set={setFriction2} color=\"#ef4444\" note=\"0 = frictionless\" />\n                  </>\n                )}\n\n                {law === '3rd' && (\n                  <>\n                    <div className=\"grid grid-cols-3 gap-1 bg-gray-100 p-1 rounded-xl\">\n                      {(['push', 'rocket', 'collision'] as Scenario3[]).map(s => (\n                        <button key={s} onClick={() => setScenario3(s)}\n                          className={`py-2 rounded-lg text-xs font-medium capitalize transition ${\n                            scenario3 === s ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500'\n                          }`}>{s}</button>\n                      ))}\n                    </div>\n                    <Slider label=\"Object 1 mass\" unit=\"kg\" value={mass3a} min={1} max={50} step={1} set={setMass3a} color=\"#6366f1\" />\n                    <Slider label=\"Object 2 mass\" unit=\"kg\" value={mass3b} min={1} max={50} step={1} set={setMass3b} color=\"#10b981\" />\n                    <Slider label=\"Interaction force\" unit=\"N\" value={force3} min={5} max={100} step={5} set={setForce3} color=\"#f59e0b\" />\n                  </>\n                )}\n              </div>\n            </SimulationStage>\n\n            {/* Col 2: Analytics */}\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {law === '1st' && [\n                    { l: 'Mass', v: `${mass1} kg`, c: 'text-indigo-600' },\n                    { l: 'Initial velocity', v: `${initV} m/s`, c: 'text-amber-600' },\n                    { l: 'Friction (μ)', v: friction1.toFixed(2), c: 'text-red-500' },\n                    { l: 'Friction force', v: `${(friction1 * mass1 * 9.81).toFixed(1)} N`, c: 'text-red-400' },\n                    { l: 'Net force', v: forceOn ? `${(force1 - friction1 * mass1 * 9.81).toFixed(1)} N` : `${(friction1 * mass1 * 9.81 * -1).toFixed(1)} N`, c: 'text-gray-700' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-sm font-semibold ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {law === '2nd' && [\n                    { l: 'Applied force', v: `${applied} N`, c: 'text-emerald-600' },\n                    { l: 'Friction force', v: `${secAnalytics.frictionForce} N`, c: 'text-red-500' },\n                    { l: 'Net force', v: `${secAnalytics.netForce} N`, c: 'text-indigo-600' },\n                    { l: 'Acceleration', v: `${secAnalytics.acceleration} m/s²`, c: 'text-amber-600' },\n                    { l: 'F = ma check', v: `${secAnalytics.netForce} = ${mass2}×${secAnalytics.acceleration}`, c: 'text-gray-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-sm font-semibold ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n\n                  {law === '3rd' && [\n                    { l: 'Action force', v: `${force3} N`, c: 'text-emerald-600' },\n                    { l: 'Reaction force', v: `−${force3} N`, c: 'text-red-500' },\n                    { l: `a₁ (${mass3a}kg)`, v: `${thdAnalytics.a1.toFixed(2)} m/s²`, c: 'text-indigo-600' },\n                    { l: `a₂ (${mass3b}kg)`, v: `${thdAnalytics.a2.toFixed(2)} m/s²`, c: 'text-amber-600' },\n                    { l: 'Force equal?', v: 'Yes — always', c: 'text-emerald-600' },\n                  ].map(r => (\n                    <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                      <span className=\"text-xs text-gray-500\">{r.l}</span>\n                      <span className={`text-sm font-semibold ${r.c}`}>{r.v}</span>\n                    </div>\n                  ))}\n                </div>\n              </div>\n\n              {/* Curriculum */}\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            {/* Col 3: Teacher notes + exercises */}\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[law].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[law].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i+1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/polarization/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef, useMemo } from 'react';\nimport { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Label, ReferenceDot } from 'recharts';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { PolarizationCanvas, PolarizationMode } from '@/components/simulation/PolarizationCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { malusIntensity, malusCurve } from '@/lib/physics/polarization';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<PolarizationMode, { title: string; icon: string; sub: string; eq: string }> = {\n  single: { title: 'A single polarizer', icon: '🕶️', sub: 'Unpolarized → plane-polarized', eq: 'transmits one plane of vibration' },\n  malus:  { title: \"Malus's law\",        icon: '📐', sub: 'Two polarizers at an angle',     eq: 'I = I₀cos²θ' },\n};\n\nconst TEACHER_NOTES: Record<PolarizationMode, string[]> = {\n  single: [\n    'Light is a TRANSVERSE wave — it vibrates perpendicular to its direction of travel. \"Unpolarized\" light vibrates in every possible perpendicular direction at once.',\n    'A polarizer has a transmission axis — it only lets through the component of vibration ALONG that axis, blocking the rest.',\n    'Only transverse waves can be polarized. Sound is a LONGITUDINAL wave (vibrates along its direction of travel) and cannot be polarized — a useful way to distinguish the two in an exam.',\n    'Polarizing sunglasses reduce glare because reflected light off water or glass becomes partially polarized (mostly horizontal) — a vertically-oriented lens blocks much of that reflected glare.',\n    'LCD screens work by controlling the polarization of light passing through liquid crystals sandwiched between two polarizing filters.',\n  ],\n  malus: [\n    \"Malus's law applies to ALREADY plane-polarized light passing through a second polarizer (the \\\"analyser\\\"): I = I₀cos²θ, where θ is the angle between the two transmission axes.\",\n    'At θ=0° (parallel axes): cos²0°=1, full transmission. At θ=90° (crossed axes): cos²90°=0, no light gets through at all.',\n    'At θ=45°, exactly HALF the intensity is transmitted (cos²45°=0.5) — a commonly tested value.',\n    'Two crossed polarizers block all light — but inserting a THIRD polarizer at 45° between them actually lets some light back through. This surprising result is a classic demonstration and exam favourite.',\n    'Malus\\u2019s law only describes the SECOND polarizer onward. The first polarizer, acting on unpolarized light, always transmits exactly half the original intensity, regardless of its axis orientation (there\\u2019s no \"angle\" to measure against yet).',\n  ],\n};\n\nconst EXERCISES: Record<PolarizationMode, { q: string; a: string }[]> = {\n  single: [\n    { q: 'Explain why sound waves cannot be polarized but light waves can.', a: 'Polarization only applies to transverse waves, where the vibration direction can be restricted to one plane. Sound is longitudinal (vibrates along its direction of travel), so there is no perpendicular direction to restrict.' },\n    { q: 'Unpolarized light of intensity 40 W/m² passes through a single ideal polarizer. Find the transmitted intensity.', a: 'A single polarizer transmits exactly half of unpolarized light: 40/2 = 20 W/m².' },\n    { q: 'State one practical use of polarizing filters.', a: 'Any of: polarizing sunglasses (reduce glare from reflected light), LCD screens, photography filters (reduce reflections/enhance sky contrast), stress analysis in transparent plastics.' },\n  ],\n  malus: [\n    { q: 'Polarized light of intensity 60 W/m² passes through an analyser at 30° to its plane of polarization. Find the transmitted intensity.', a: 'I = I₀cos²θ = 60×cos²30° = 60×0.75 = 45 W/m².' },\n    { q: 'At what angle between two polarizers is the transmitted intensity exactly half the incoming polarized intensity?', a: 'cos²θ=0.5 → cosθ=1/√2 → θ=45°.' },\n    { q: 'Two polarizers are crossed (90° apart) so no light passes. Explain what happens if a third polarizer is inserted between them at 45° to both.', a: 'The first polarizer transmits light polarized at 0°. The middle (45°) polarizer transmits cos²45°=50% of that, now polarized at 45°. The final (90°) polarizer then transmits cos²45°=50% of THAT (since it is 45° from the middle one\\u2019s output) — so some light gets through overall, even though the outer two alone would block everything.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nfunction MalusGraph({ analyzerAngle }: { analyzerAngle: number }) {\n  const data = useMemo(() => malusCurve(100), []);\n  const I = malusIntensity(100, analyzerAngle);\n  return (\n    <ResponsiveContainer width=\"100%\" height={190}>\n      <LineChart data={data} margin={{ top: 8, right: 16, left: 10, bottom: 28 }}>\n        <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n        <XAxis dataKey=\"angle\" type=\"number\" domain={[0, 180]} tick={{ fontSize: 10 }}>\n          <Label value=\"θ between polarizers (°)\" position=\"insideBottom\" offset={-16} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </XAxis>\n        <YAxis tick={{ fontSize: 10 }}>\n          <Label value=\"Transmitted I (% of I₀)\" angle={-90} position=\"insideLeft\" offset={12} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </YAxis>\n        <Tooltip formatter={(v: unknown) => [Number(v).toFixed(1) + '%', 'I']} labelFormatter={a => `θ=${a}°`} />\n        <Line type=\"monotone\" dataKey=\"I\" stroke=\"#6366f1\" strokeWidth={2} dot={false} isAnimationActive={false} />\n        <ReferenceDot x={analyzerAngle} y={I} r={6} fill=\"#ef4444\" stroke=\"#fff\" strokeWidth={2} />\n      </LineChart>\n    </ResponsiveContainer>\n  );\n}\n\nexport default function PolarizationPage() {\n  const [mode, setMode] = useState<PolarizationMode>('single');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [polarizerAngle, setPolarizerAngle] = useState(30);\n  const [analyzerAngle, setAnalyzerAngle] = useState(45);\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [mode, polarizerAngle, analyzerAngle, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 260, 980);\n\n  const transmitted = malusIntensity(100, analyzerAngle);\n\n  useTopicPreset(\"simulations-polarization\", { \"polarizerAngle\": setPolarizerAngle,\n    \"analyzerAngle\": setAnalyzerAngle }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Waves</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Polarization</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as PolarizationMode[]).map(m => (\n              <button key={m} onClick={() => { setMode(m); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span><span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{MODE_META[mode].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{MODE_META[mode].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <PolarizationCanvas key={resetKey} mode={mode} polarizerAngle={polarizerAngle} analyzerAngle={analyzerAngle}\n                  isRunning={isRunning} isPaused={isPaused}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/polarization\"\n                  title={`${MODE_META[mode].title} — A-Factor STEM Studio`}\n                  params={mode === 'single' ? { mode, angle: polarizerAngle } : { mode, angle: analyzerAngle }} />\n              </div>\n\n              <div data-stage-role=\"extra\">{mode === 'malus' && (\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Transmitted intensity vs angle</p>\n                  <MalusGraph analyzerAngle={analyzerAngle} />\n                  <p className=\"text-[10px] text-gray-400 mt-2 text-center\">I = I₀cos²θ — full transmission at 0°, zero at 90° (crossed)</p>\n                </div>\n              )}</div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                {mode === 'single' && (\n                  <Slider label=\"Transmission axis\" unit=\"°\" value={polarizerAngle} min={0} max={180} step={5} set={setPolarizerAngle} color=\"#6366f1\" note=\"Measured from vertical\" />\n                )}\n                {mode === 'malus' && (\n                  <Slider label=\"Analyser angle θ\" unit=\"°\" value={analyzerAngle} min={0} max={180} step={1} set={setAnalyzerAngle} color=\"#6366f1\" note=\"Angle between the two polarizers\" />\n                )}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {mode === 'single' && <>\n                    <StatRow label=\"Transmission axis\" value={polarizerAngle.toString()} unit=\"°\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Through 1 polarizer\" value=\"50\" unit=\"% of I₀\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Result\" value=\"plane-polarized\" unit=\"\" color=\"text-purple-600\" />\n                  </>}\n                  {mode === 'malus' && <>\n                    <StatRow label=\"Angle θ\" value={analyzerAngle.toString()} unit=\"°\" color=\"text-indigo-600\" />\n                    <StatRow label=\"cos²θ\" value={Math.pow(Math.cos(analyzerAngle * Math.PI / 180), 2).toFixed(3)} unit=\"\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Transmitted I\" value={transmitted.toFixed(1)} unit=\"% of I₀\" color=\"text-amber-600\" />\n                    <StatRow label=\"State\" value={analyzerAngle < 5 ? 'aligned — max' : analyzerAngle > 85 && analyzerAngle < 95 ? 'crossed — zero' : 'partial'} unit=\"\" color=\"text-rose-500\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[mode].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/electrostatics-potential/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { PotentialCanvas } from '@/components/simulation/PotentialCanvas';\nimport { EquipotentialCanvas, EquipotentialConfig } from '@/components/simulation/EquipotentialCanvas';\nimport { CapacitorCanvas } from '@/components/simulation/CapacitorCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { electricPotentialEnergy, parallelPlateCapacitance, capacitorCharge, capacitorEnergy } from '@/lib/physics/electrostatics';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\ntype Topic = 'potential' | 'equipotential' | 'capacitor';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; eq: string }> = {\n  potential:     { title: 'Potential & potential energy', icon: '🔺', sub: 'Work done moving charge', eq: 'V = kQ/r,  U = kQ₁Q₂/r' },\n  equipotential: { title: 'Equipotential surfaces',        icon: '🗺️', sub: 'Field ⊥ equipotentials', eq: 'no work done moving along a surface' },\n  capacitor:     { title: 'Capacitors',                    icon: '🔋', sub: 'Charging & discharging',  eq: 'Q = CV,  E = ½CV²' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  potential: [\n    'Electric potential V at a point is the potential energy per unit positive charge placed there: V = kQ/r for a point charge, defining V = 0 at infinity.',\n    'Electric potential ENERGY U of a pair of charges is U = kQ₁Q₂/r — this is the energy of the SYSTEM, not of either charge alone.',\n    'For unlike charges (attractive), U is NEGATIVE — the system loses potential energy as the charges get closer, and that lost PE becomes kinetic energy, exactly like a ball falling under gravity.',\n    'For like charges (repulsive), U is POSITIVE — pushing them together stores energy, which is released as kinetic energy if they are let go and fly apart.',\n    'Work done moving a charge q through a potential difference V is W = qV — this is the same principle used to define the volt (1V = 1 joule per coulomb) and underlies how batteries and circuits are analysed.',\n  ],\n  equipotential: [\n    'An equipotential surface is a surface on which every point has the SAME electric potential — for a single point charge, these are concentric spheres (circles in a 2D cross-section) centred on the charge.',\n    'NO work is done moving a charge along an equipotential surface, since W = qΔV and ΔV = 0 by definition on that surface.',\n    'Electric field lines are always PERPENDICULAR to equipotential surfaces at every point they cross — this is a direct mathematical consequence of E being the (negative) gradient of V, not a coincidence.',\n    'Equipotentials are closely spaced where the field is strong (near a charge) and widely spaced where the field is weak (far from a charge) — exactly mirroring how contour lines on a map are closer together on steep terrain.',\n    'The surface of any charged CONDUCTOR is always an equipotential surface in electrostatic equilibrium — if it weren\\u2019t, charge would keep flowing along the surface until it became one.',\n  ],\n  capacitor: [\n    'A capacitor stores charge (and therefore energy) on two separated conductors — commonly two parallel plates. Charge Q on a capacitor is proportional to the voltage across it: Q = CV, where C is the capacitance (in farads).',\n    'Parallel-plate capacitance: C = ε₀A/d, where A is the plate area and d is the separation — bigger plates or a smaller gap both increase capacitance.',\n    'When charging through a resistor, the voltage does NOT rise instantly — it follows an exponential curve, reaching about 63% of the final voltage after one time constant τ = RC, and is considered \"fully\" charged after about 5τ.',\n    'Energy stored in a charged capacitor: E = ½CV² = ½QV — this is genuinely stored energy, which is why a charged capacitor can still deliver a shock even after being disconnected from its charging source.',\n    'Discharging follows the mirror-image exponential decay, falling to about 37% of its starting voltage after one time constant.',\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  potential: [\n    { q: 'Find the electric potential at a point 0.2m from a +4μC charge.', a: 'V = kQ/r = (8.99×10⁹ × 4×10⁻⁶) / 0.2 = 179,800 V.' },\n    { q: 'Two point charges, +3μC and −5μC, are 0.15m apart. Find the potential energy of the system.', a: 'U = kQ₁Q₂/r = (8.99×10⁹ × 3×10⁻⁶ × −5×10⁻⁶) / 0.15 = −8.99N (negative, since the charges attract).' },\n    { q: 'How much work is done moving a +2μC charge through a potential difference of 500V?', a: 'W = qV = 2×10⁻⁶ × 500 = 1×10⁻³ J = 1mJ.' },\n  ],\n  equipotential: [\n    { q: 'Explain why no work is done moving a charge along an equipotential surface.', a: 'Work done is W = qΔV. Since every point on an equipotential surface has the same potential, ΔV = 0 between any two points on it, so W = 0 regardless of the path taken along the surface.' },\n    { q: 'State the relationship between the direction of electric field lines and equipotential surfaces.', a: 'Electric field lines are always perpendicular to equipotential surfaces at every point.' },\n    { q: 'Explain why the surface of a charged conductor must be an equipotential surface.', a: 'If two points on the surface had different potentials, the potential difference would drive charge to flow between them until the difference disappeared — so in electrostatic equilibrium (no charge flowing), every point on the surface must already be at the same potential.' },\n  ],\n  capacitor: [\n    { q: 'A parallel-plate capacitor has plates of area 0.02m² separated by 0.5mm of air. Find its capacitance.', a: 'C = ε₀A/d = (8.85×10⁻¹² × 0.02) / 0.0005 = 3.54×10⁻¹⁰ F = 354pF.' },\n    { q: 'A 100μF capacitor is charged to 12V. Find the charge stored and the energy stored.', a: 'Q = CV = 100×10⁻⁶ × 12 = 1.2×10⁻³ C = 1.2mC. Energy = ½CV² = 0.5 × 100×10⁻⁶ × 12² = 7.2×10⁻³ J = 7.2mJ.' },\n    { q: 'A capacitor charges through a 2000Ω resistor with a time constant of 0.4s. Find its capacitance.', a: 'τ = RC, so C = τ/R = 0.4/2000 = 2×10⁻⁴ F = 200μF.' },\n    { q: 'Explain why a capacitor never reaches its full charge in a finite time when charging through a resistor, even though it gets very close.', a: 'The charging voltage follows V(t) = V₀(1 − e^(−t/τ)), an exponential approach to V₀. Since e^(−t/τ) only reaches exactly zero as t → ∞, the capacitor mathematically only approaches full charge asymptotically — in practice it is considered fully charged after about 5 time constants, when it is over 99% charged.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function ElectrostaticsPotentialPage() {\n  const [topic, setTopic] = useState<Topic>('potential');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [q1nC, setQ1nC] = useState(20);\n  const [q2nC, setQ2nC] = useState(-20);\n  const [separationCm, setSeparationCm] = useState(10);\n  const [liveEnergy, setLiveEnergy] = useState({ KE: 0, PE: 0, sep: 10 });\n\n  const [equipConfig, setEquipConfig] = useState<EquipotentialConfig>('single-positive');\n\n  const [voltageV, setVoltageV] = useState(9);\n  const [resistanceOhm, setResistanceOhm] = useState(2000);\n  const [capacitanceUf, setCapacitanceUf] = useState(100);\n  const [dischargeKey, setDischargeKey] = useState(0);\n  const [liveCapacitor, setLiveCapacitor] = useState({ v: 0, phase: 'charging' as 'charging' | 'discharging' });\n\n  // Parallel-plate geometric calculator (independent of the RC animation sliders)\n  const [plateAreaCm2, setPlateAreaCm2] = useState(200);\n  const [plateSepMm, setPlateSepMm] = useState(1);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); setDischargeKey(0);\n  }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, q1nC, q2nC, separationCm, equipConfig, voltageV, resistanceOhm, capacitanceUf, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 300, 980);\n\n  const staticPE = electricPotentialEnergy(q1nC * 1e-9, q2nC * 1e-9, separationCm / 100);\n  const plateCapacitanceF = parallelPlateCapacitance((plateAreaCm2 / 1e4), plateSepMm / 1000);\n\n  useTopicPreset(\"simulations-electrostatics-potential\", { \"q1nC\": setQ1nC,\n    \"q2nC\": setQ2nC,\n    \"separationCm\": setSeparationCm,\n    \"voltageV\": setVoltageV,\n    \"resistanceOhm\": setResistanceOhm,\n    \"capacitanceUf\": setCapacitanceUf,\n    \"plateAreaCm2\": setPlateAreaCm2,\n    \"plateSepMm\": setPlateSepMm }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Electricity · Electrostatics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Potential, Equipotentials &amp; Capacitors</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span><span>{TOPIC_META[t].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                {topic === 'potential' && (\n                  <PotentialCanvas key={resetKey} q1nC={q1nC} q2nC={q2nC} initialSeparationCm={separationCm}\n                    isRunning={isRunning} isPaused={isPaused}\n                    onTick={(KE, PE, sep) => setLiveEnergy({ KE, PE, sep })}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'equipotential' && (\n                  <EquipotentialCanvas configuration={equipConfig}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'capacitor' && (\n                  <CapacitorCanvas key={resetKey} voltageV={voltageV} resistanceOhm={resistanceOhm} capacitanceUf={capacitanceUf}\n                    isRunning={isRunning} isPaused={isPaused} dischargeKey={dischargeKey}\n                    onTick={(v, ph) => setLiveCapacitor({ v, phase: ph })}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                {topic !== 'equipotential' ? (\n                  <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                    onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                    onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                ) : <span />}\n                {topic === 'capacitor' && isRunning && liveCapacitor.phase === 'charging' && (\n                  <button onClick={() => setDischargeKey(k => k + 1)}\n                    className=\"rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-medium text-gray-600 transition hover:bg-gray-50\">\n                    Discharge\n                  </button>\n                )}\n                <EmbedButton path=\"/embed/electrostatics-potential\"\n                  title={`${TOPIC_META[topic].title} — A-Factor STEM Studio`}\n                  params={\n                    topic === 'potential' ? { topic, q1: q1nC, q2: q2nC, sep: separationCm }\n                    : topic === 'equipotential' ? { topic, config: equipConfig }\n                    : { topic, v: voltageV, r: resistanceOhm, c: capacitanceUf }\n                  } />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {topic === 'potential' && <>\n                  <Slider label=\"Charge Q₁\" unit=\"nC\" value={q1nC} min={-50} max={50} step={5} set={setQ1nC} color=\"#dc2626\" />\n                  <Slider label=\"Charge Q₂\" unit=\"nC\" value={q2nC} min={-50} max={50} step={5} set={setQ2nC} color=\"#2563eb\" />\n                  <Slider label=\"Initial separation\" unit=\"cm\" value={separationCm} min={5} max={25} step={1} set={setSeparationCm} color=\"#6366f1\" />\n                </>}\n\n                {topic === 'equipotential' && (\n                  <div className=\"grid grid-cols-2 gap-2\">\n                    {([\n                      ['single-positive', 'Single +'], ['single-negative', 'Single −'],\n                      ['dipole', 'Dipole (+/−)'], ['like-charges', 'Like charges (+/+)'],\n                    ] as [EquipotentialConfig, string][]).map(([cfg, label]) => (\n                      <button key={cfg} onClick={() => setEquipConfig(cfg)}\n                        className={`rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                          equipConfig === cfg ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{label}</button>\n                    ))}\n                  </div>\n                )}\n\n                {topic === 'capacitor' && <>\n                  <Slider label=\"Supply voltage\" unit=\"V\" value={voltageV} min={1} max={20} step={1} set={setVoltageV} color=\"#6366f1\" />\n                  <Slider label=\"Resistance\" unit=\"Ω\" value={resistanceOhm} min={500} max={5000} step={100} set={setResistanceOhm} color=\"#f59e0b\" />\n                  <Slider label=\"Capacitance\" unit=\"µF\" value={capacitanceUf} min={50} max={500} step={10} set={setCapacitanceUf} color=\"#8b5cf6\"\n                    note=\"τ = RC — larger R or C makes charging slower\" />\n                  <div className=\"pt-2 border-t border-gray-100 space-y-3\">\n                    <p className=\"text-[10px] font-medium uppercase tracking-wide text-gray-400\">Parallel-plate calculator</p>\n                    <Slider label=\"Plate area\" unit=\"cm²\" value={plateAreaCm2} min={20} max={500} step={10} set={setPlateAreaCm2} color=\"#10b981\" />\n                    <Slider label=\"Plate separation\" unit=\"mm\" value={plateSepMm} min={0.2} max={5} step={0.1} set={setPlateSepMm} color=\"#10b981\" />\n                  </div>\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {topic === 'potential' && <>\n                    <StatRow label=\"Initial PE\" value={(staticPE * 1e6).toFixed(2)} unit=\"µJ\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Live KE\" value={(liveEnergy.KE * 1e6).toFixed(2)} unit=\"µJ\" color=\"text-amber-600\" />\n                    <StatRow label=\"Live PE\" value={(liveEnergy.PE * 1e6).toFixed(2)} unit=\"µJ\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Live separation\" value={liveEnergy.sep.toFixed(1)} unit=\"cm\" color=\"text-purple-600\" />\n                  </>}\n                  {topic === 'equipotential' && <>\n                    <StatRow label=\"Configuration\" value={equipConfig.replace('-', ' ')} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Field vs equipotential\" value=\"always perpendicular\" unit=\"\" color=\"text-emerald-600\" />\n                  </>}\n                  {topic === 'capacitor' && <>\n                    <StatRow label=\"Time constant τ=RC\" value={(resistanceOhm * capacitanceUf * 1e-6).toFixed(3)} unit=\"s\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Live voltage\" value={liveCapacitor.v.toFixed(2)} unit=\"V\" color=\"text-amber-600\" />\n                    <StatRow label=\"Live charge Q=CV\" value={(capacitorCharge(capacitanceUf * 1e-6, liveCapacitor.v) * 1e6).toFixed(2)} unit=\"µC\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Live energy\" value={(capacitorEnergy(capacitanceUf * 1e-6, liveCapacitor.v) * 1e6).toFixed(2)} unit=\"µJ\" color=\"text-purple-600\" />\n                    <StatRow label=\"Parallel-plate C\" value={(plateCapacitanceF * 1e12).toFixed(1)} unit=\"pF\" color=\"text-rose-500\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[topic].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/quantum-tunneling/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useMemo, useEffect } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { QuantumTunnelingCanvas } from '@/components/simulation/QuantumTunnelingCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport {\n  TUNNELING_PRESETS, TunnelingParams, PotentialType,\n  analyticalTransmission, getDecayConstant, getWavelength,\n  type TunnelingStats,\n} from '@/lib/physics/quantumTunneling';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB', 'A-Level', 'Undergrad'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700',\n  NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700',\n  SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n  'A-Level': 'bg-cyan-100 text-cyan-700',\n  Undergrad: 'bg-rose-100 text-rose-700',\n};\n\nconst TEACHER_NOTES = [\n  'Quantum tunneling is the phenomenon where a particle passes through a potential energy barrier that it classically cannot surmount. It arises from the wave nature of matter encoded in the Schrödinger equation.',\n  'The wavefunction ψ(x,t) is not zero inside the barrier even when E < V₀. It decays exponentially as ψ ∼ exp(−κx), where κ = √(2m(V₀−E))/ℏ. This evanescent wave carries no probability current, yet it connects to a non-zero transmitted wave on the far side.',\n  'Transmission probability for a thick rectangular barrier: T ≈ 16(E/V₀)(1−E/V₀) exp(−2κw). The exponential dependence on width w and height V₀ makes tunneling extremely sensitive to atomic-scale geometry.',\n  'Classically, a particle with E < V₀ is always reflected. The classical turning point is where E = V(x). Quantum mechanics permits non-zero |ψ|² beyond this point because the particle does not have a definite position — only a probability amplitude.',\n  'When E > V₀, transmission is not 100%. The wave partially reflects from the barrier boundaries due to impedance mismatch (change in wavelength), creating interference oscillations in T(E). This is purely a wave phenomenon.',\n  'Resonant tunneling occurs in double-barrier structures. Quasi-bound states in the quantum well between barriers allow T ≈ 1 even when each barrier individually would give T ≪ 1. This is the basis of resonant tunneling diodes (RTDs) and flash memory.',\n  'The scanning tunneling microscope (STM) relies on vacuum tunneling. The tunneling current I ∝ exp(−2κd), where d is tip-sample distance. A 1 Å change in d changes current by an order of magnitude, giving atomic resolution.',\n  'Alpha decay (Gamow 1928) is tunneling of an α-particle through the nuclear Coulomb barrier. The Geiger-Nuttall law relates half-life to decay energy: log τ ∝ 1/√E. Higher-energy α particles tunnel faster — dramatically so.',\n  'In fusion (e.g., the Sun), protons tunnel through the Coulomb repulsion barrier at temperatures where classical thermodynamics predicts essentially zero fusion. Without tunneling, stars would not shine.',\n  'The WKB approximation generalizes tunneling to arbitrary barriers: T ≈ exp(−2 ∫√(2m(V(x)−E)) dx / ℏ). It works when V(x) varies slowly compared to the de Broglie wavelength.',\n  'Heisenberg uncertainty explains tunneling qualitatively: borrowing energy ΔE for a time Δt ∼ ℏ/ΔE allows the particle to temporarily surmount the barrier. This is a hand-waving picture but useful for intuition.',\n  'Heavy particles tunnel less. The exponent 2κw scales as √m, so a proton tunnels far more readily than a macroscopic object. This explains why we do not observe people tunneling through walls.',\n  'In the classical limit (m → ∞ or ℏ → 0), κ → ∞ and T → 0. Tunneling is a purely quantum effect that vanishes in the correspondence limit, consistent with the Ehrenfest theorem.',\n  'Superconducting Josephson junctions and quantum computing qubits exploit controlled tunneling between states. The ability to tune barrier transparency with voltage or magnetic flux is central to quantum technology.',\n];\n\nconst EXERCISES = [\n  {\n    q: 'Set E = 1 eV, V₀ = 2 eV, w = 2 Å. Launch the packet. What happens to the classical particle vs the quantum wave? Calculate κ and estimate T.',\n    a: 'The classical particle (amber dot) hits the barrier and reflects. The quantum wave splits: most reflects, but an exponentially decaying tail penetrates the barrier, and a small transmitted packet (~10–20%) emerges. κ = 0.512√(2−1) ≈ 0.51 Å⁻¹. T ≈ 16(0.5)(0.5)exp(−2·0.51·2) ≈ 4 exp(−2.04) ≈ 0.15 or 15%.',\n  },\n  {\n    q: 'Double the barrier width to 4 Å (keep E=1, V₀=2). How does T change? Verify the exponential dependence.',\n    a: 'T drops to ≈ 4 exp(−4.08) ≈ 0.02 or 2%. Doubling width squares the transmission (in the thick-barrier limit). This exponential sensitivity is why tunneling only matters at nanometer scales.',\n  },\n  {\n    q: 'Increase particle energy to E = 3 eV (above V₀ = 2 eV). Why is T not 100%? What classical prediction does this violate?',\n    a: 'Classically, any particle with E > V₀ should transmit with 100% probability. Quantum mechanically, the wave partially reflects at each boundary where the wavelength changes (impedance mismatch), causing interference. T oscillates between 1 and T_min as E increases.',\n  },\n  {\n    q: 'Switch to the Double Barrier preset. Slowly tune the particle energy between 0.5 and 1.5 eV. Where does T peak? What causes this resonance?',\n    a: 'T peaks when the energy matches a quasi-bound state in the quantum well between the two barriers. At resonance, the wave constructively interferes in the well, giving T ≈ 1 even though each barrier alone would block most of the wave. This is resonant tunneling.',\n  },\n  {\n    q: 'Select the Quantum Well. Set E = 1 eV and V = −3 eV (well depth 3 eV). Why does the well partially reflect the particle even though it is attractive?',\n    a: 'An attractive well changes the wavelength (λ increases inside because kinetic energy E−V is larger). The sudden change in λ at the boundaries causes partial reflection — just like light reflecting at a change in refractive index. Only at specific resonance energies does the well become perfectly transparent.',\n  },\n  {\n    q: 'Enable \"Show Phase\" and run the simulation. What does the color variation inside the packet represent? Why does the phase change faster inside the barrier when E < V₀?',\n    a: 'Color represents the complex phase arg(ψ). In free space, phase advances as exp(ikx) with k = √(2mE)/ℏ. Inside the barrier (E < V₀), the wave becomes evanescent with imaginary momentum iκ, so the phase advances as exp(−κx) — actually, the phase is constant and the amplitude decays. Wait: in the evanescent region, the wave is real (or pure imaginary), so the phase is locked. The phase variation you see is actually the oscillation of the Re/Im components relative to the decaying envelope.',\n  },\n  {\n    q: 'Set mass to 10 mₑ (Heavy Particle preset). How does the de Broglie wavelength change? Why does the packet behave more classically?',\n    a: 'λ = h/p = 2π/(0.512√(mE)) shrinks by √10 ≈ 3.2×. A shorter wavelength means the wave packet is more localized and follows the classical trajectory more closely. The decay constant κ also increases, suppressing tunneling exponentially. This is the quantum-classical correspondence.',\n  },\n  {\n    q: 'Use the Triangular barrier (STM preset). The WKB integral replaces the simple rectangular formula. Why is a triangular barrier more realistic for field emission?',\n    a: 'In field emission, an electric field F tilts the vacuum barrier from a rectangle into a triangle: V(x) = V₀ − eFx. The barrier width at energy E is w = (V₀−E)/eF. The WKB integral gives T ≈ exp(−4√(2m) (V₀−E)^(3/2) / 3ℏeF), the Fowler-Nordheim formula. This explains why sharp tips (high F) and small work functions (low V₀) enhance tunneling.',\n  },\n  {\n    q: 'Graduate: For alpha decay, the nuclear potential is a Coulomb barrier V(r) = 2(Z−2)e²/(4πε₀r) for r > R. Derive the Gamow factor and explain why small changes in E cause huge changes in half-life.',\n    a: 'The Gamow factor is the WKB integral from the nuclear radius R to the classical turning point r_t = 2(Z−2)e²/(4πε₀E). Integrating √(2m(V(r)−E)) dr gives G = 2π(Z−2)e²/(ℏv) − 4√(2m(Z−2)e²R/4πε₀)/ℏ, where v = √(2E/m). Since T ∝ exp(−G) and decay rate λ = fT (with f ∼ 10²¹ Hz), the half-life τ = ln2/λ varies by orders of magnitude when G changes by a few units. A small increase in E reduces G linearly, exponentially increasing T and reducing τ.',\n  },\n  {\n    q: 'Graduate: The split-step Fourier method is used here. Why is it superior to finite-difference methods for the time-dependent Schrödinger equation?',\n    a: 'The split-step method is unconditionally stable (no Courant limit on dt), unitary (conserves total probability exactly), and spectrally accurate in space (errors decay exponentially with grid resolution). Finite-difference methods require very small dt for stability and accumulate phase errors. The FFT handles the kinetic energy operator exactly in momentum space, while pointwise multiplication handles the potential in position space.',\n  },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">\n          {value} <span className=\"text-gray-400 font-normal\">{unit}</span>\n        </span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string; }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function QuantumTunnelingPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB', 'A-Level', 'Undergrad']);\n\n  const [potentialType, setPotentialType] = useState<PotentialType>('barrier');\n  const [particleEnergy, setParticleEnergy] = useState(1);\n  const [barrierHeight, setBarrierHeight] = useState(2);\n  const [barrierWidth, setBarrierWidth] = useState(2);\n  const [barrierPosition, setBarrierPosition] = useState(25);\n  const [packetWidth, setPacketWidth] = useState(1.5);\n  const [particleMass, setParticleMass] = useState(1);\n  const [speed, setSpeed] = useState(1);\n  const [zoom, setZoom] = useState(1);\n  const [showPotential, setShowPotential] = useState(true);\n  const [showProbability, setShowProbability] = useState(true);\n  const [showRealPart, setShowRealPart] = useState(true);\n  const [showImaginaryPart, setShowImaginaryPart] = useState(false);\n  const [showPhase, setShowPhase] = useState(false);\n  const [showClassical, setShowClassical] = useState(false);\n  const [showEnergyLine, setShowEnergyLine] = useState(true);\n  const [autoRestart, setAutoRestart] = useState(true);\n\n  const params: TunnelingParams = {\n    potentialType, particleEnergy, barrierHeight, barrierWidth, barrierPosition,\n    packetWidth, particleMass, speed, zoom,\n    showPotential, showProbability, showRealPart, showImaginaryPart,\n    showPhase, showClassical, showEnergyLine, autoRestart,\n  };\n\n  const [liveStats, setLiveStats] = useState<TunnelingStats>({\n    energy: 1, momentum: 0.512, barrierHeight: 2, barrierWidth: 2,\n    theoreticalT: 0, measuredT: 0, measuredR: 0, wavelength: 12.27, decayConstant: 0.512, time: 0,\n  });\n\n  const applyPreset = useCallback((presetIdx: number) => {\n    const preset = TUNNELING_PRESETS[presetIdx];\n    if (!preset) return;\n    const pp = preset.params;\n    if (pp.potentialType) setPotentialType(pp.potentialType);\n    if (pp.particleEnergy !== undefined) setParticleEnergy(pp.particleEnergy);\n    if (pp.barrierHeight !== undefined) setBarrierHeight(pp.barrierHeight);\n    if (pp.barrierWidth !== undefined) setBarrierWidth(pp.barrierWidth);\n    if (pp.barrierPosition !== undefined) setBarrierPosition(pp.barrierPosition);\n    if (pp.packetWidth !== undefined) setPacketWidth(pp.packetWidth);\n    if (pp.particleMass !== undefined) setParticleMass(pp.particleMass);\n    if (pp.speed !== undefined) setSpeed(pp.speed);\n    if (pp.showPotential !== undefined) setShowPotential(pp.showPotential);\n    if (pp.showProbability !== undefined) setShowProbability(pp.showProbability);\n    if (pp.showRealPart !== undefined) setShowRealPart(pp.showRealPart);\n    if (pp.showImaginaryPart !== undefined) setShowImaginaryPart(pp.showImaginaryPart);\n    if (pp.showEnergyLine !== undefined) setShowEnergyLine(pp.showEnergyLine);\n    if (pp.showClassical !== undefined) setShowClassical(pp.showClassical);\n    setIsRunning(false); setIsPaused(false);\n    setResetKey((k) => k + 1);\n    setLiveStats({ energy: pp.particleEnergy ?? 1, momentum: 0.512, barrierHeight: pp.barrierHeight ?? 2, barrierWidth: pp.barrierWidth ?? 2, theoreticalT: 0, measuredT: 0, measuredR: 0, wavelength: 12.27, decayConstant: 0.512, time: 0 });\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey((k) => k + 1);\n  }, []);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 720, 500, 900);\n\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((stats: TunnelingStats) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveStats(stats);\n  }, []);\n\n  const theoTDisplay = useMemo(() => {\n    if (potentialType === 'barrier' || potentialType === 'well') {\n      return analyticalTransmission(particleEnergy, Math.abs(barrierHeight), barrierWidth, particleMass);\n    }\n    return liveStats.theoreticalT;\n  }, [potentialType, particleEnergy, barrierHeight, barrierWidth, particleMass, liveStats.theoreticalT]);\n\n  useTopicPreset(\"simulations-quantum-tunneling\", { \"particleEnergy\": setParticleEnergy,\n    \"packetWidth\": setPacketWidth,\n    \"particleMass\": setParticleMass,\n    \"barrierHeight\": setBarrierHeight,\n    \"barrierWidth\": setBarrierWidth,\n    \"barrierPosition\": setBarrierPosition,\n    \"speed\": setSpeed,\n    \"zoom\": setZoom }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Quantum Mechanics — Wave Mechanics & Scattering</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">1D Quantum Tunneling</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map((c) => (\n                  <button key={c} onClick={() => setActiveCurricula((p) => p.includes(c) ? p.filter((x) => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'}`}>\n                    {c}\n                  </button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Schrödinger → Scattering → Tunneling → WKB → QED</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">T ≈ exp(−2κw)</span>\n          </div>\n\n          {/* Scenario selector */}\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {(['barrier', 'well', 'step', 'double', 'triangular'] as PotentialType[]).map((m) => {\n              const labels: Record<PotentialType, string> = {\n                barrier: 'Barrier', well: 'Quantum Well', step: 'Step', double: 'Double Barrier', triangular: 'Triangular',\n              };\n              const desc: Record<PotentialType, string> = {\n                barrier: 'Rectangular potential wall',\n                well: 'Attractive potential trough',\n                step: 'Semi-infinite step',\n                double: 'Two barriers with gap',\n                triangular: 'Linear ramp (STM/field emission)',\n              };\n              return (\n                <button key={m} onClick={() => { setPotentialType(m); setIsRunning(false); setResetKey((k) => k + 1); }}\n                  className={`shrink-0 rounded-xl border px-4 py-2 text-left hover:shadow-sm transition min-w-[150px] ${potentialType === m ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-600 hover:border-indigo-200'}`}>\n                  <p className=\"text-xs font-medium\">{labels[m]}</p>\n                  <p className=\"text-[10px] text-gray-400 mt-0.5\">{desc[m]}</p>\n                </button>\n              );\n            })}\n          </div>\n\n          {/* Presets */}\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {TUNNELING_PRESETS.map((preset, i) => (\n              <button key={i} onClick={() => applyPreset(i)}\n                className=\"shrink-0 rounded-xl border border-gray-200 bg-white px-3 py-2 text-left hover:border-indigo-300 hover:shadow-sm transition min-w-[200px]\">\n                <p className=\"text-xs font-medium text-indigo-700\">{preset.name}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5 leading-relaxed\">{preset.description}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_240px] xl:grid-cols-[minmax(0,1fr)_240px_280px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <QuantumTunnelingCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} onTick={handleTick} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused((p) => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/quantum-tunneling\" title=\"Quantum Tunneling — A-Factor STEM Studio\"\n                  params={{ type: potentialType, E: particleEnergy, V: barrierHeight, w: barrierWidth, pos: barrierPosition, sigma: packetWidth, m: particleMass, speed, pot: showPotential ? 1 : 0, prob: showProbability ? 1 : 0, re: showRealPart ? 1 : 0, im: showImaginaryPart ? 1 : 0, phase: showPhase ? 1 : 0, classical: showClassical ? 1 : 0, eline: showEnergyLine ? 1 : 0, auto: autoRestart ? 1 : 0 }} />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">Wave Packet</p>\n                    <Slider label=\"Energy E\" unit=\"eV\" value={particleEnergy} min={0.1} max={10} step={0.1} set={setParticleEnergy} color=\"#6366f1\" note=\"Kinetic energy of incident particle\" />\n                    <Slider label=\"Packet width σ\" unit=\"Å\" value={packetWidth} min={0.5} max={4} step={0.1} set={setPacketWidth} color=\"#3b82f6\" note=\"Spatial spread of Gaussian (uncertainty)\" />\n                    <Slider label=\"Mass\" unit=\"mₑ\" value={particleMass} min={0.2} max={20} step={0.1} set={setParticleMass} color=\"#10b981\" note=\"In units of electron mass\" />\n                  </div>\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">Potential</p>\n                    <Slider label=\"Height |V₀|\" unit=\"eV\" value={barrierHeight} min={0.5} max={10} step={0.1} set={setBarrierHeight} color=\"#fbbf24\" note=\"Barrier height (well depth for Well)\" />\n                    <Slider label=\"Width w\" unit=\"Å\" value={barrierWidth} min={0.5} max={10} step={0.1} set={setBarrierWidth} color=\"#f59e0b\" note=\"Barrier thickness\" />\n                    <Slider label=\"Position\" unit=\"Å\" value={barrierPosition} min={10} max={45} step={1} set={setBarrierPosition} color=\"#d97706\" note=\"Distance from left edge\" />\n                  </div>\n                </div>\n\n                <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                  <p className=\"text-[10px] font-medium text-emerald-600 uppercase tracking-wide\">Animation</p>\n                  <div className=\"grid grid-cols-2 gap-3\">\n                    <Slider label=\"Speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n                    <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.5} max={2} step={0.1} set={setZoom} color=\"#10b981\" />\n                  </div>\n                  <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                    <input type=\"checkbox\" checked={autoRestart} onChange={(e) => setAutoRestart(e.target.checked)} className=\"rounded\" />\n                    Auto-restart when packet settles\n                  </label>\n                </div>\n\n                <div className=\"border-t border-gray-100 pt-3\">\n                  <p className=\"text-[10px] font-medium text-gray-500 uppercase tracking-wide mb-2\">Visibility</p>\n                  <div className=\"flex flex-wrap gap-3\">\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showPotential} onChange={(e) => setShowPotential(e.target.checked)} className=\"rounded\" />Potential\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showProbability} onChange={(e) => setShowProbability(e.target.checked)} className=\"rounded\" />|ψ|²\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showRealPart} onChange={(e) => setShowRealPart(e.target.checked)} className=\"rounded\" />Re(ψ)\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showImaginaryPart} onChange={(e) => setShowImaginaryPart(e.target.checked)} className=\"rounded\" />Im(ψ)\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showPhase} onChange={(e) => setShowPhase(e.target.checked)} className=\"rounded\" />Phase color\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showClassical} onChange={(e) => setShowClassical(e.target.checked)} className=\"rounded\" />Classical particle\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showEnergyLine} onChange={(e) => setShowEnergyLine(e.target.checked)} className=\"rounded\" />Energy line\n                    </label>\n                  </div>\n                </div>\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"Energy E\" value={liveStats.energy.toFixed(2)} unit=\"eV\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Momentum p\" value={liveStats.momentum.toFixed(3)} unit=\"Å⁻¹\" color=\"text-blue-500\" />\n                  <StatRow label=\"Wavelength λ\" value={liveStats.wavelength.toFixed(2)} unit=\"Å\" color=\"text-emerald-600\" />\n                  <StatRow label=\"Barrier V₀\" value={liveStats.barrierHeight.toFixed(2)} unit=\"eV\" color=\"text-amber-600\" />\n                  <StatRow label=\"Width w\" value={liveStats.barrierWidth.toFixed(1)} unit=\"Å\" color=\"text-orange-500\" />\n                  <StatRow label=\"Decay κ\" value={liveStats.decayConstant.toFixed(3)} unit=\"Å⁻¹\" color=\"text-purple-600\" />\n                  <div className=\"border-t border-gray-100 my-1\" />\n                  <StatRow label=\"Theoretical T\" value={(theoTDisplay * 100).toFixed(2)} unit=\"%\" color=\"text-rose-500\" />\n                  <StatRow label=\"Measured T\" value={(liveStats.measuredT * 100).toFixed(1)} unit=\"%\" color=\"text-pink-500\" />\n                  <StatRow label=\"Measured R\" value={(liveStats.measuredR * 100).toFixed(1)} unit=\"%\" color=\"text-cyan-600\" />\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Formulas</p>\n                <div className=\"space-y-2 text-[10px] text-gray-600 font-mono leading-relaxed\">\n                  <p>κ = √(2m(V₀−E))/ℏ</p>\n                  <p>κ = {liveStats.decayConstant.toFixed(3)} Å⁻¹</p>\n                  <p className=\"text-gray-400\">———————</p>\n                  <p>T ≈ 16(E/V₀)(1−E/V₀)e^(−2κw)</p>\n                  <p>T ≈ {(16 * (liveStats.energy/Math.max(liveStats.barrierHeight,0.01)) * (1 - liveStats.energy/Math.max(liveStats.barrierHeight,0.01)) * Math.exp(-2*liveStats.decayConstant*liveStats.barrierWidth)).toExponential(2)}</p>\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map((c) => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'}`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/electrostatics-charging/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { ChargingMethodsCanvas, ChargingMethod } from '@/components/simulation/ChargingMethodsCanvas';\nimport { ElectroscopeCanvas, ElectroscopeMode } from '@/components/simulation/ElectroscopeCanvas';\nimport { ElectrophorusCanvas } from '@/components/simulation/ElectrophorusCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\ntype Topic = 'production' | 'electroscope' | 'electrophorus';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; eq: string }> = {\n  production:    { title: 'Production of charges', icon: '⚡', sub: 'Friction, conduction, induction', eq: 'like charges repel, unlike attract' },\n  electroscope:  { title: 'Gold-leaf electroscope', icon: '🍂', sub: 'Detecting & testing charge',      eq: 'divergence ∝ charge' },\n  electrophorus: { title: 'Electrophorus',          icon: '🔌', sub: 'Repeatable charging by induction', eq: 'induced charge is opposite the slab' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  production: [\n    'In ALL of these methods, only ELECTRONS ever move. Protons are locked inside the nucleus and never transfer between objects — every \"positive charge\" you see is really a region that has LOST electrons, not one that gained protons.',\n    'Charging by FRICTION: rubbing two different insulators transfers electrons from one to the other. Whichever material holds electrons less strongly ends up positive (lost electrons); the other ends up negative (gained electrons) — equal and opposite charges.',\n    'Charging by CONDUCTION (contact): the rod and the body must actually TOUCH — this is real physical contact, not just closeness. A negative rod has excess electrons that spread onto the neutral body it touches. A positive rod is short of electrons, so it instead pulls electrons OFF the body it touches. Either way, the body ends up the SAME sign as the rod, and the rod\\u2019s own charge is reduced.',\n    'Charging by INDUCTION: the rod comes very close to the conductor — close enough for its field to act — but must NOT touch it, unlike friction and conduction. A negative rod repels the conductor\\u2019s free electrons to the far side; a positive rod attracts them to the near side. Earthing while the rod is still present lets electrons escape (negative rod) or draws extra electrons in (positive rod). Once the earth connection and then the rod are removed (in that order), the conductor is left with a net charge OPPOSITE the inducing rod.',\n    'A key exam distinction: conduction leaves the object with the SAME sign of charge as the charging body; induction leaves it with the OPPOSITE sign — and induction never involves contact at all.',\n    'The order of steps matters for induction: the earth connection must be broken BEFORE the charged rod is taken away — if the rod is removed first, the separated charges simply recombine and no net charge is left behind.',\n  ],\n  electroscope: [\n    'A gold-leaf electroscope detects and estimates charge: charge spreads down the cap, rod, and onto the two thin leaves, which — carrying the same sign — repel each other and diverge.',\n    'As always, only ELECTRONS move here — never protons. Charging the electroscope with a negative rod pushes electrons IN (rod → cap → leaves). Charging it with a positive rod pulls the electroscope\\u2019s own electrons OUT (leaves → cap → rod), leaving it short of electrons and therefore positive — the rod never \"gives\" it positive charge directly.',\n    'Charging BY CONTACT: touch a charged rod to the cap; electrons transfer, spread through the instrument, and the leaves diverge and STAY diverged once the rod is removed.',\n    'TESTING the sign of an unknown charge: bring it near the cap of an already-charged electroscope (no contact). If the leaves diverge FURTHER, the unknown charge has the SAME sign as the electroscope. If the leaves diverge LESS, it has the OPPOSITE sign.',\n    'This works by induction at the cap: a like charge repels the electroscope\\u2019s own charge further down toward the leaves (more divergence); an unlike charge attracts it back up toward the cap (less divergence).',\n    'An electroscope can also be charged BY INDUCTION (earthing the case while a charged rod is held near the cap, then removing the earth before the rod) — giving it a charge opposite to the rod, the same principle as the electrophorus.',\n  ],\n  electrophorus: [\n    'An electrophorus is a device for producing charge repeatedly from a SINGLE charging of an insulating slab — the slab itself is charged once (by friction) and never touched again.',\n    'As with all induction, only ELECTRONS move here. The slab\\u2019s negative charge repels the disc\\u2019s free electrons to its top surface — the underside is simply short of electrons, not visited by positive charge.',\n    'Sequence: place the metal disc on the charged slab (induction separates its charges) → touch the disc briefly to earth it (the repelled electrons escape) → lift the disc by its INSULATING handle.',\n    'The disc lifts away carrying a net charge OPPOSITE to the slab\\u2019s charge — if the slab is negative, the disc becomes positive (short of electrons).',\n    'Because the slab\\u2019s own charge is never used up (only induction happens, no charge transfers to or from the slab), this process can be repeated many times from a single rubbing of the slab.',\n    'The insulating handle is essential — touching the metal disc directly (instead of through the handle) would earth it through your hand at the wrong moment and prevent it from carrying charge away.',\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  production: [\n    { q: 'An ebonite rod is rubbed with fur and becomes negatively charged. What happens to the fur, and why?', a: 'The fur becomes positively charged. Rubbing transfers electrons from the fur to the rod (since the rod holds electrons more strongly here), leaving the fur short of electrons — positively charged — while the rod gains the electrons and becomes negative.' },\n    { q: 'A positively charged rod touches a neutral metal sphere on an insulating stand. State the sign of charge left on the sphere.', a: 'Positive — the same sign as the charging rod, since conduction transfers charge of the same sign onto the object touched.' },\n    { q: 'Describe how to charge a metal sphere negatively using a POSITIVELY charged rod, without ever touching the rod to the sphere.', a: 'Bring the positive rod close to the sphere (inducing separation of charge — the near side becomes negative, the far side positive). Earth the sphere while the rod is still near, letting the repelled positive charge flow to earth. Disconnect the earth first, THEN remove the rod. The sphere is left with a net negative charge — opposite to the rod.' },\n  ],\n  electroscope: [\n    { q: 'A charged electroscope has its leaves diverged. An unknown charged rod is brought near the cap and the leaves diverge further. What can you conclude about the rod\\u2019s charge?', a: 'The rod carries the SAME sign of charge as the electroscope — a like charge repels the electroscope\\u2019s charge further down onto the leaves, increasing the divergence.' },\n    { q: 'Explain why the leaves of an electroscope diverge when it is charged.', a: 'Charge spreads through the cap, rod, and onto both leaves. Since both leaves carry the same sign, they repel each other and swing apart.' },\n    { q: 'A student touches a charged rod to the cap of a neutral electroscope, then removes the rod. Describe and explain what is observed.', a: 'The leaves diverge as the rod touches (charge spreading onto them) and REMAIN diverged after the rod is removed, since the electroscope has now genuinely been charged by contact and retains that charge.' },\n  ],\n  electrophorus: [\n    { q: 'Explain why the metal disc of an electrophorus becomes charged even though it never touches the (already charged) slab with a bare conducting path carrying charge from the slab.', a: 'The disc becomes charged by INDUCTION, not by charge transfer from the slab. The slab\\u2019s fixed charge polarises the disc (separates its own charges); earthing the disc lets the repelled charge escape, leaving the disc with an induced charge of its own once the earth and then the slab contact are removed.' },\n    { q: 'Why can an electrophorus be used repeatedly without re-charging the insulating slab?', a: 'The slab\\u2019s charge is never transferred away — it only induces a redistribution of charge on the disc each time. Since the slab\\u2019s own charge is untouched, the same slab can induce a fresh charge on the disc again and again.' },\n    { q: 'State the correct order of steps for using an electrophorus, and explain why the order matters.', a: 'Lower the disc onto the slab → earth the disc (e.g., touch it) → remove the earth connection → THEN lift the disc away. If the disc were lifted before removing the earth connection, charge would simply flow back from earth as it left, and the disc would end up uncharged.' },\n  ],\n};\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function ElectrostaticsChargingPage() {\n  const [topic, setTopic] = useState<Topic>('production');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [method, setMethod] = useState<ChargingMethod>('friction');\n  const [chargingPhaseLabel, setChargingPhaseLabel] = useState('');\n\n  const [electroscopeMode, setElectroscopeMode] = useState<ElectroscopeMode>('charging');\n  const [rodSign, setRodSign] = useState<1 | -1>(-1);\n  const [electroscopeSign, setElectroscopeSign] = useState<1 | -1>(-1);\n  const [liveDivergence, setLiveDivergence] = useState(0);\n\n  const [electrophorusCycle, setElectrophorusCycle] = useState(0);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1);\n    setElectrophorusCycle(0);\n  }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, method, electroscopeMode, rodSign, electroscopeSign, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 320, 980);\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Electricity · Electrostatics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Charging Objects</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span><span>{TOPIC_META[t].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].eq}</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                {topic === 'production' && (\n                  <ChargingMethodsCanvas key={resetKey} method={method} rodSign={rodSign}\n                    isRunning={isRunning} isPaused={isPaused} onPhaseChange={setChargingPhaseLabel}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'electroscope' && (\n                  <ElectroscopeCanvas key={resetKey} mode={electroscopeMode} rodSign={rodSign} electroscopeSign={electroscopeSign}\n                    isRunning={isRunning} isPaused={isPaused} onTick={setLiveDivergence}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n                {topic === 'electrophorus' && (\n                  <ElectrophorusCanvas key={resetKey} isRunning={isRunning} isPaused={isPaused}\n                    cycleCount={electrophorusCycle} onCycleComplete={() => setElectrophorusCycle(c => c + 1)}\n                    width={canvasSize.width} height={canvasSize.height} />\n                )}\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/electrostatics-charging\"\n                  title={`${TOPIC_META[topic].title} — A-Factor STEM Studio`}\n                  params={\n                    topic === 'production' ? { topic, method }\n                    : topic === 'electroscope' ? { topic, mode: electroscopeMode, rod: rodSign, es: electroscopeSign }\n                    : { topic }\n                  } />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                {topic === 'production' && (\n                  <div className=\"flex flex-col gap-2\">\n                    {(['friction', 'conduction', 'induction'] as const).map(m => (\n                      <button key={m} onClick={() => setMethod(m)}\n                        className={`rounded-lg border px-3 py-2 text-xs font-medium capitalize text-left transition ${\n                          method === m ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{m}</button>\n                    ))}\n                    {method !== 'friction' && (\n                      <div className=\"pt-2 border-t border-gray-100 space-y-1.5\">\n                        <span className=\"text-xs text-gray-500\">Rod&apos;s charge</span>\n                        <div className=\"flex gap-2\">\n                          {([1, -1] as const).map(sgn => (\n                            <button key={sgn} onClick={() => setRodSign(sgn)}\n                              className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                                rodSign === sgn ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                              }`}>{sgn > 0 ? 'Positive (+)' : 'Negative (−)'}</button>\n                          ))}\n                        </div>\n                      </div>\n                    )}\n                  </div>\n                )}\n\n                {topic === 'electroscope' && <>\n                  <div className=\"flex gap-2\">\n                    {(['charging', 'testing'] as const).map(m => (\n                      <button key={m} onClick={() => setElectroscopeMode(m)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                          electroscopeMode === m ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{m}</button>\n                    ))}\n                  </div>\n                  {electroscopeMode === 'testing' && (\n                    <div className=\"space-y-1.5\">\n                      <span className=\"text-xs text-gray-500\">Electroscope&apos;s existing charge</span>\n                      <div className=\"flex gap-2\">\n                        {([1, -1] as const).map(sgn => (\n                          <button key={sgn} onClick={() => setElectroscopeSign(sgn)}\n                            className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                              electroscopeSign === sgn ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                            }`}>{sgn > 0 ? 'Positive (+)' : 'Negative (−)'}</button>\n                        ))}\n                      </div>\n                    </div>\n                  )}\n                  <div className=\"space-y-1.5\">\n                    <span className=\"text-xs text-gray-500\">{electroscopeMode === 'charging' ? 'Charging rod' : 'Test rod'}</span>\n                    <div className=\"flex gap-2\">\n                      {([1, -1] as const).map(sgn => (\n                        <button key={sgn} onClick={() => setRodSign(sgn)}\n                          className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium transition ${\n                            rodSign === sgn ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                          }`}>{sgn > 0 ? 'Positive (+)' : 'Negative (−)'}</button>\n                      ))}\n                    </div>\n                  </div>\n                </>}\n\n                {topic === 'electrophorus' && (\n                  <p className=\"text-xs text-gray-500 leading-relaxed\">Press Run to lower the disc, earth it, and lift it away. Press Run again afterwards to repeat the cycle from the same charged slab.</p>\n                )}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {topic === 'production' && <>\n                    <StatRow label=\"Method\" value={method} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Current phase\" value={chargingPhaseLabel || '—'} unit=\"\" color=\"text-emerald-600\" />\n                  </>}\n                  {topic === 'electroscope' && <>\n                    <StatRow label=\"Mode\" value={electroscopeMode} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Live divergence\" value={liveDivergence.toFixed(0)} unit=\"°\" color=\"text-emerald-600\" />\n                    {electroscopeMode === 'testing' && (\n                      <StatRow label=\"Relationship\" value={rodSign === electroscopeSign ? 'same sign → more' : 'opposite sign → less'} unit=\"\" color=\"text-amber-600\" />\n                    )}\n                  </>}\n                  {topic === 'electrophorus' && <>\n                    <StatRow label=\"Cycles completed\" value={electrophorusCycle.toString()} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Slab charge used\" value=\"none — reusable\" unit=\"\" color=\"text-emerald-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[topic].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/quantum-harmonic-oscillator/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useMemo } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { QuantumHarmonicOscillatorCanvas } from '@/components/simulation/QuantumHarmonicOscillatorCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { PRESETS, QHOPreset, normalize, QHOParams } from '@/lib/physics/quantumHarmonicOscillator';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700',\n  NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700',\n  SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TEACHER_NOTES = [\n  'The quantum harmonic oscillator is the most important exactly solvable model in quantum mechanics. Its energy spectrum and wavefunctions appear in every sub-field, from molecular vibrations to quantum field theory.',\n  'Energy levels are equally spaced: E_n = ℏω(n + ½). The ground-state energy ℏω/2 is called zero-point energy — a purely quantum effect with no classical analogue.',\n  'Wavefunctions are Hermite polynomials multiplied by a Gaussian envelope. The number of nodes equals the quantum number n.',\n  'Stationary states (pure n) have time-independent probability densities |ψ_n|². Only superpositions of different n produce time-dependent \"motion\".',\n  'A coherent state is a special superposition that mimics classical oscillation: a Gaussian wave packet that swings back and forth without spreading. It is the quantum state closest to a classical particle.',\n  'The classical turning points mark where a classical particle with the same energy would reverse direction. In quantum mechanics, there is non-zero probability of finding the particle beyond these points — quantum tunnelling.',\n  'The expectation value ⟨x⟩ (white dot) shows the \"average position\". For a stationary state it is zero; for superpositions it oscillates, tracking the classical motion.',\n];\n\nconst EXERCISES = [\n  {\n    q: 'Run the Ground state preset. Where is the particle most likely to be found? How does this differ from a classical particle at the same energy?',\n    a: 'The probability peaks at the centre (x=0). A classical particle with E=½ℏω would be at rest at the bottom of the potential well, but a quantum particle has zero-point energy and is delocalised in a Gaussian packet.',\n  },\n  {\n    q: 'Switch to the First excited state. Why is the probability zero at x=0?',\n    a: 'The n=1 wavefunction is odd: ψ_1(x) ∝ x·e^{-x²/2}. It must pass through zero at the origin to maintain odd symmetry, so |ψ|² = 0 there.',\n  },\n  {\n    q: 'Run the 0+1 superposition and enable Re(ψ) and Im(ψ). What happens to the probability density over time? Why?',\n    a: 'The probability \"sloshes\" left and right. The two stationary states have different energies, so they accumulate a relative phase e^{-i(E_1-E_0)t/ℏ} = e^{-iωt}. This interference creates a time-dependent beating pattern.',\n  },\n  {\n    q: 'Compare the 0+1 superposition with the Coherent state (α=2). Both oscillate, but what is the key visual difference?',\n    a: 'The 0+1 superposition is a simple two-state interference that distorts as it moves. The coherent state contains many n states weighted just right so the Gaussian shape is preserved — it truly mimics a classical pendulum.',\n  },\n  {\n    q: 'Enable classical turning points and compare the Ground state (n=0) with the Coherent state (α=3). How does the region of significant probability compare to the classical allowed region?',\n    a: 'For n=0, the Gaussian tail extends noticeably beyond the turning points — quantum tunnelling is significant. For the large coherent state (α=3), the wave packet stays mostly inside the classical region, matching classical expectations.',\n  },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">\n          {value} <span className=\"text-gray-400 font-normal\">{unit}</span>\n        </span>\n      </div>\n      <input\n        type=\"range\"\n        min={min}\n        max={max}\n        step={step}\n        value={value}\n        onChange={(e) => set(Number(e.target.value))}\n        className=\"w-full\"\n        style={{ accentColor: color }}\n      />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: {\n  label: string; value: string; unit: string; color: string;\n}) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>\n        {value} <span className=\"text-gray-400 font-normal\">{unit}</span>\n      </span>\n    </div>\n  );\n}\n\nexport default function QuantumHarmonicOscillatorPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [selectedPreset, setSelectedPreset] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB']);\n\n  // Coefficients for n = 0..5\n  const [c0, setC0] = useState(1);\n  const [c1, setC1] = useState(0);\n  const [c2, setC2] = useState(0);\n  const [c3, setC3] = useState(0);\n  const [c4, setC4] = useState(0);\n  const [c5, setC5] = useState(0);\n\n  const coeffs = useMemo(() => normalize([c0, c1, c2, c3, c4, c5]), [c0, c1, c2, c3, c4, c5]);\n\n  const [speed, setSpeed] = useState(1);\n  const [xMax, setXMax] = useState(5);\n  const [eMax, setEMax] = useState(4.5);\n  const [nMax, setNMax] = useState(5);\n  const [showPotential, setShowPotential] = useState(true);\n  const [showEnergyLevels, setShowEnergyLevels] = useState(true);\n  const [showProbability, setShowProbability] = useState(true);\n  const [showReal, setShowReal] = useState(false);\n  const [showImaginary, setShowImaginary] = useState(false);\n  const [showClassicalTurning, setShowClassicalTurning] = useState(true);\n\n  const params: QHOParams = {\n    speed,\n    xMax,\n    eMax,\n    nMax,\n    showPotential,\n    showEnergyLevels,\n    showProbability,\n    showReal,\n    showImaginary,\n    showClassicalTurning,\n  };\n\n  const [liveStats, setLiveStats] = useState({\n    energy: 0,\n    x: 0,\n    x2: 0,\n    p: 0,\n    p2: 0,\n    leftTurn: 0,\n    rightTurn: 0,\n    maxProb: 0,\n  });\n\n  const applyPreset = useCallback((preset: QHOPreset, index: number) => {\n    const [nc0, nc1, nc2, nc3, nc4, nc5] = preset.coeffs;\n    setC0(nc0); setC1(nc1); setC2(nc2); setC3(nc3); setC4(nc4); setC5(nc5);\n    setSpeed(preset.speed);\n    setXMax(preset.xMax);\n    setEMax(preset.eMax);\n    setNMax(preset.nMax);\n    setShowPotential(preset.showPotential);\n    setShowEnergyLevels(preset.showEnergyLevels);\n    setShowProbability(preset.showProbability);\n    setShowReal(preset.showReal);\n    setShowImaginary(preset.showImaginary);\n    setShowClassicalTurning(preset.showClassicalTurning);\n    setIsRunning(false);\n    setIsPaused(false);\n    setResetKey((k) => k + 1);\n    setSelectedPreset(null);\n    setLiveStats({\n      energy: 0, x: 0, x2: 0, p: 0, p2: 0,\n      leftTurn: 0, rightTurn: 0, maxProb: 0,\n    });\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false);\n    setIsPaused(false);\n    setResetKey((k) => k + 1);\n    setLiveStats({\n      energy: 0, x: 0, x2: 0, p: 0, p2: 0,\n      leftTurn: 0, rightTurn: 0, maxProb: 0,\n    });\n  }, []);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 420, 900);\n\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((stats: typeof liveStats) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveStats(stats);\n  }, []);\n\n  const deltaX = Math.sqrt(Math.max(0, liveStats.x2 - liveStats.x * liveStats.x));\n  const deltaP = Math.sqrt(Math.max(0, liveStats.p2 - liveStats.p * liveStats.p));\n\n  useTopicPreset(\"simulations-quantum-harmonic-oscillator\", { \"c0\": setC0,\n    \"c1\": setC1,\n    \"c2\": setC2,\n    \"c3\": setC3,\n    \"c4\": setC4,\n    \"c5\": setC5,\n    \"speed\": setSpeed,\n    \"xMax\": setXMax,\n    \"eMax\": setEMax,\n    \"nMax\": setNMax }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Quantum Mechanics — Exactly Solvable Models</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Quantum Harmonic Oscillator</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map((c) => (\n                  <button\n                    key={c}\n                    onClick={() =>\n                      setActiveCurricula((p) =>\n                        p.includes(c) ? p.filter((x) => x !== c) : [...p, c]\n                      )\n                    }\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c)\n                        ? CC[c] + ' border-transparent'\n                        : 'bg-white text-gray-400 border-gray-200'\n                    }`}\n                  >\n                    {c}\n                  </button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">1-D potential well — Hermite polynomials — coherent states</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">Ĥ = p̂²/2m + ½mω²x̂²</span>\n          </div>\n\n          {/* Presets */}\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {PRESETS.map((preset, i) => {\n              const isActive = selectedPreset === i;\n              return (\n                <button\n                  key={i}\n                  onClick={() => applyPreset(preset, i)}\n                  className={`shrink-0 rounded-xl border-2 px-3 py-2.5 text-left transition min-w-[200px] ${\n                    isActive\n                      ? 'bg-indigo-600 border-white text-white shadow-lg'\n                      : 'bg-white border-gray-200 text-gray-900 hover:border-indigo-300 hover:shadow-sm'\n                  }`}\n                >\n                  <div className=\"flex items-center justify-between\">\n                    <p className={`text-xs font-bold ${isActive ? 'text-white' : 'text-indigo-700'}`}>\n                      {preset.name}\n                    </p>\n                    {isActive && <span className=\"text-xs font-bold ml-2\">✓</span>}\n                  </div>\n                  <p className={`text-[10px] mt-1 leading-relaxed ${isActive ? 'text-indigo-100' : 'text-gray-500'}`}>\n                    {preset.description}\n                  </p>\n                </button>\n              );\n            })}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <QuantumHarmonicOscillatorCanvas\n                  key={resetKey}\n                  coeffs={coeffs}\n                  params={params}\n                  isRunning={isRunning}\n                  isPaused={isPaused}\n                  onTick={handleTick}\n                  width={canvasSize.width}\n                  height={canvasSize.height}\n                />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls\n                  isRunning={isRunning}\n                  isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused((p) => !p)}\n                  onReset={reset}\n                />\n                <EmbedButton\n                  path=\"/embed/quantum-harmonic-oscillator\"\n                  title=\"Quantum Harmonic Oscillator — A-Factor STEM Studio\"\n                  params={{\n                    c0, c1, c2, c3, c4, c5,\n                    speed, xmax: xMax, emax: eMax,\n                    potential: showPotential ? 1 : 0,\n                    levels: showEnergyLevels ? 1 : 0,\n                    prob: showProbability ? 1 : 0,\n                    real: showReal ? 1 : 0,\n                    imag: showImaginary ? 1 : 0,\n                    turning: showClassicalTurning ? 1 : 0,\n                  }}\n                />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">State coefficients</p>\n                    <Slider label=\"c₀ (n=0)\" unit=\"\" value={c0} min={0} max={1} step={0.01} set={setC0} color=\"#6366f1\" />\n                    <Slider label=\"c₁ (n=1)\" unit=\"\" value={c1} min={0} max={1} step={0.01} set={setC1} color=\"#8b5cf6\" />\n                    <Slider label=\"c₂ (n=2)\" unit=\"\" value={c2} min={0} max={1} step={0.01} set={setC2} color=\"#ec4899\" />\n                  </div>\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">State coefficients</p>\n                    <Slider label=\"c₃ (n=3)\" unit=\"\" value={c3} min={0} max={1} step={0.01} set={setC3} color=\"#f43f5e\" />\n                    <Slider label=\"c₄ (n=4)\" unit=\"\" value={c4} min={0} max={1} step={0.01} set={setC4} color=\"#f59e0b\" />\n                    <Slider label=\"c₅ (n=5)\" unit=\"\" value={c5} min={0} max={1} step={0.01} set={setC5} color=\"#10b981\" />\n                  </div>\n                </div>\n\n                <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                  <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                    <Slider label=\"Time speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" note=\"Animation speed factor\" />\n                    <Slider label=\"X-range\" unit=\"a\" value={xMax} min={3} max={12} step={0.5} set={setXMax} color=\"#10b981\" note=\"Horizontal axis limit (× characteristic length)\" />\n                    <Slider label=\"E-range\" unit=\"ℏω\" value={eMax} min={2} max={8} step={0.5} set={setEMax} color=\"#ef4444\" note=\"Energy axis limit\" />\n                    <Slider label=\"Levels shown\" unit=\"\" value={nMax} min={1} max={8} step={1} set={setNMax} color=\"#818cf8\" note=\"Number of energy level lines\" />\n                  </div>\n\n                  <div className=\"flex flex-wrap gap-3\">\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showPotential} onChange={(e) => setShowPotential(e.target.checked)} className=\"rounded\" />\n                      Potential V(x)\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showEnergyLevels} onChange={(e) => setShowEnergyLevels(e.target.checked)} className=\"rounded\" />\n                      Energy levels\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showProbability} onChange={(e) => setShowProbability(e.target.checked)} className=\"rounded\" />\n                      |ψ|²\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showReal} onChange={(e) => setShowReal(e.target.checked)} className=\"rounded\" />\n                      Re(ψ)\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showImaginary} onChange={(e) => setShowImaginary(e.target.checked)} className=\"rounded\" />\n                      Im(ψ)\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showClassicalTurning} onChange={(e) => setShowClassicalTurning(e.target.checked)} className=\"rounded\" />\n                      Classical turning points\n                    </label>\n                  </div>\n                </div>\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"⟨E⟩\" value={liveStats.energy.toFixed(3)} unit=\"ℏω\" color=\"text-indigo-600\" />\n                  <StatRow label=\"⟨x⟩\" value={liveStats.x.toFixed(3)} unit=\"a\" color=\"text-rose-500\" />\n                  <StatRow label=\"Δx\" value={deltaX.toFixed(3)} unit=\"a\" color=\"text-blue-500\" />\n                  <StatRow label=\"⟨p⟩\" value={liveStats.p.toFixed(3)} unit=\"ℏ/a\" color=\"text-emerald-600\" />\n                  <StatRow label=\"Δp\" value={deltaP.toFixed(3)} unit=\"ℏ/a\" color=\"text-purple-600\" />\n                  <StatRow label=\"Δx·Δp\" value={(deltaX * deltaP).toFixed(3)} unit=\"ℏ\" color=\"text-amber-600\" />\n                  <StatRow label=\"x_turn (left)\" value={liveStats.leftTurn.toFixed(2)} unit=\"a\" color=\"text-indigo-500\" />\n                  <StatRow label=\"x_turn (right)\" value={liveStats.rightTurn.toFixed(2)} unit=\"a\" color=\"text-amber-500\" />\n                  <StatRow label=\"max |ψ|²\" value={liveStats.maxProb.toFixed(3)} unit=\"\" color=\"text-pink-500\" />\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map((c) => (\n                    <span\n                      key={c}\n                      className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                        activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                      }`}\n                    >\n                      {c}\n                    </span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>\n                      {n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button\n                        onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\"\n                      >\n                        <span>\n                          <span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}\n                        </span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>\n                          {ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/double-pendulum/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useEffect } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { DoublePendulumCanvas } from '@/components/simulation/DoublePendulumCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport {\n  PendulumState, PendulumParams, totalEnergy,\n  PRESETS, Preset,\n} from '@/lib/physics/doublePendulum';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TEACHER_NOTES = [\n  'The double pendulum is one of the simplest systems that exhibits deterministic chaos — the motion is governed by exact equations, yet long-term behaviour is effectively unpredictable.',\n  'Chaos arises from the nonlinearity of the equations, NOT from randomness or noise. Given the same initial conditions, the trajectory is perfectly repeatable.',\n  'The system is extremely sensitive to initial conditions: a change of 0.01° in starting angle produces a completely different trajectory after just a few seconds — the \"butterfly effect\".',\n  'Energy is conserved in the ideal (frictionless) case. The red/blue energy bar shows kinetic and potential energy trading back and forth. With damping, total energy slowly decreases.',\n  'For small angles (θ < 15°), the motion is approximately regular and periodic — the linearised equations decouple into two normal modes.',\n  'The trail of the second bob (orange) is the most vivid visual signature of chaos: ordered motion produces smooth, repeating curves; chaotic motion fills an irregular, tangled region of space.',\n  'In real experiments, friction and air resistance eventually damp the motion. The \"Damped motion\" preset shows how chaos gives way to regular decay as energy dissipates.',\n  'Q-factor and bandwidth are extracted live from the energy envelope. Q = ω/γ  where γ is the exponential decay constant of total energy.',\n];\n\nconst EXERCISES = [\n  {\n    q: 'Run the \"Chaos demo\" preset for 10 seconds, then reset and run it again. Are the two trajectories identical? What does this tell you about the system?',\n    a: 'Yes, they are identical — the double pendulum is deterministic. The same initial conditions always produce the same trajectory. Chaos does NOT mean randomness.',\n  },\n  {\n    q: 'Compare the \"Small oscillations\" and \"Chaos demo\" presets. Why does one look regular and the other chaotic?',\n    a: 'Small angles allow the sine terms in the equations to be approximated as sin(θ) ≈ θ, making the equations linear and solvable as two independent harmonic oscillators. Large angles keep the full nonlinearity, which couples the two pendulums and produces chaos.',\n  },\n  {\n    q: 'Set both masses to 3kg and both lengths to 1.5m. Start at θ₁=90°, θ₂=90°. Is the motion more or less chaotic than the default 1kg/1m case? Explain.',\n    a: 'The motion is similar in character — chaos depends primarily on the angles and the geometry (length ratio), not the absolute scale. However, larger masses mean more inertia, so the motion is slower but still chaotic.',\n  },\n  {\n    q: 'Enable the energy monitor and run the frictionless case. What do you observe about total energy? Then add damping and observe again.',\n    a: 'Without damping, total energy stays nearly constant (tiny variations are integration error). With damping, energy decreases monotonically as work is done against the resistive force — the pendulum eventually comes to rest.',\n  },\n  {\n    q: 'The \"Butterfly effect\" preset starts with θ₂ = 90.1° instead of 90°. Run it alongside the \"Chaos demo\" (90°). How long before the two orange trails look completely different?',\n    a: 'Usually within 3–5 seconds the trails diverge visibly. After 10 seconds they are completely uncorrelated — this is the hallmark of sensitive dependence on initial conditions.',\n  },\n  {\n    q: 'With damping enabled, watch the Q-factor readout. Why does Q drop as the motion progresses?',\n    a: 'Q = ω/γ. As energy decays, the amplitude shrinks and the system may settle into a lower-frequency regime. More importantly, once the motion becomes very small, numerical noise in the energy envelope makes the regression less stable, causing Q to fluctuate.',\n  },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input\n        type=\"range\"\n        min={min}\n        max={max}\n        step={step}\n        value={value}\n        onChange={e => set(Number(e.target.value))}\n        className=\"w-full h-6 py-2 cursor-pointer\"\n        style={{ accentColor: color }}\n      />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nfunction DampingCurve({ history }: { history: Array<{ t: number; e: number }> }) {\n  if (history.length < 3) return (\n    <div className=\"rounded-lg bg-slate-900 border border-gray-700 h-24 flex items-center justify-center\">\n      <span className=\"text-[10px] text-gray-500\">Run simulation to see decay curve</span>\n    </div>\n  );\n  const logEs = history.map(h => Math.log(Math.max(h.e, 1e-6)));\n  const minE = Math.min(...logEs);\n  const maxE = Math.max(...logEs);\n  const rangeE = maxE - minE || 1;\n  const minT = history[0].t;\n  const maxT = history[history.length - 1].t;\n  const rangeT = maxT - minT || 1;\n\n  const pts = history.map((h, i) => {\n    const x = ((h.t - minT) / rangeT) * 100;\n    const y = 100 - ((logEs[i] - minE) / rangeE) * 100;\n    return `${x},${y}`;\n  }).join(' ');\n\n  return (\n    <div className=\"rounded-lg bg-slate-900 border border-gray-700 overflow-hidden\">\n      <svg viewBox=\"0 0 100 100\" preserveAspectRatio=\"none\" className=\"w-full h-24 block\">\n        <polyline\n          points={pts}\n          fill=\"none\"\n          stroke=\"#10b981\"\n          strokeWidth=\"1.5\"\n          strokeLinecap=\"round\"\n          strokeLinejoin=\"round\"\n          vectorEffect=\"non-scaling-stroke\"\n        />\n        <text x=\"4\" y=\"12\" fill=\"#94a3b8\" fontSize=\"8\" fontFamily=\"system-ui\">ln(E) vs time</text>\n        <line x1=\"0\" y1=\"100\" x2=\"100\" y2=\"100\" stroke=\"#334155\" strokeWidth=\"0.5\" />\n        <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"100\" stroke=\"#334155\" strokeWidth=\"0.5\" />\n      </svg>\n    </div>\n  );\n}\n\nexport default function DoublePendulumPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB']);\n  const [showTrail, setShowTrail] = useState(true);\n  const [showEnergy, setShowEnergy] = useState(true);\n  const [trailLength, setTrailLength] = useState(300);\n  const [activePreset, setActivePreset] = useState<number | null>(null);\n\n  const [m1, setM1] = useState(1);\n  const [m2, setM2] = useState(1);\n  const [L1, setL1] = useState(1);\n  const [L2, setL2] = useState(1);\n  const [theta1Deg, setTheta1Deg] = useState(90);\n  const [theta2Deg, setTheta2Deg] = useState(90);\n  const [omega1, setOmega1] = useState(0);\n  const [omega2, setOmega2] = useState(0);\n  const [damping, setDamping] = useState(0);\n\n  const [liveEnergy, setLiveEnergy] = useState({ ke: 0, pe: 0, total: 0 });\n  const [liveState, setLiveState] = useState({ theta1: 0, theta2: 0, omega1: 0, omega2: 0 });\n  const [liveMeta, setLiveMeta] = useState({ qFactor: 0, bandwidth: 0, decayRate: 0, valid: false });\n  const [chartHistory, setChartHistory] = useState<Array<{ t: number; e: number }>>([]);\n\n  const params: PendulumParams = { m1, m2, L1, L2, g: 9.81, damping };\n\n  useEffect(() => {\n    const idx = PRESETS.findIndex(p =>\n      Math.abs(p.m1 - m1) < 0.05 && Math.abs(p.m2 - m2) < 0.05 &&\n      Math.abs(p.L1 - L1) < 0.05 && Math.abs(p.L2 - L2) < 0.05 &&\n      Math.abs(p.theta1Deg - theta1Deg) < 0.5 && Math.abs(p.theta2Deg - theta2Deg) < 0.5 &&\n      Math.abs(p.omega1 - omega1) < 0.05 && Math.abs(p.omega2 - omega2) < 0.05 &&\n      Math.abs(p.damping - damping) < 0.005\n    );\n    setActivePreset(idx >= 0 ? idx : null);\n  }, [m1, m2, L1, L2, theta1Deg, theta2Deg, omega1, omega2, damping]);\n\n  const applyPreset = useCallback((preset: Preset, index: number) => {\n    setM1(preset.m1); setM2(preset.m2); setL1(preset.L1); setL2(preset.L2);\n    setTheta1Deg(preset.theta1Deg); setTheta2Deg(preset.theta2Deg);\n    setOmega1(preset.omega1); setOmega2(preset.omega2); setDamping(preset.damping);\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveEnergy({ ke: 0, pe: 0, total: 0 });\n    setLiveState({ theta1: 0, theta2: 0, omega1: 0, omega2: 0 });\n    setLiveMeta({ qFactor: 0, bandwidth: 0, decayRate: 0, valid: false });\n    setChartHistory([]);\n    setActivePreset(index);\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1);\n    setLiveEnergy({ ke: 0, pe: 0, total: 0 });\n    setLiveState({ theta1: 0, theta2: 0, omega1: 0, omega2: 0 });\n    setLiveMeta({ qFactor: 0, bandwidth: 0, decayRate: 0, valid: false });\n    setChartHistory([]);\n  }, []);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 420, 900);\n\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((state: PendulumState, energy: { ke: number; pe: number; total: number }, meta: { qFactor: number; bandwidth: number; decayRate: number; valid: boolean; chartHistory: Array<{ t: number; e: number }> }) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveState({\n      theta1: state.theta1,\n      theta2: state.theta2,\n      omega1: state.omega1,\n      omega2: state.omega2,\n    });\n    setLiveEnergy(energy);\n    setLiveMeta({ qFactor: meta.qFactor, bandwidth: meta.bandwidth, decayRate: meta.decayRate, valid: meta.valid });\n    setChartHistory(meta.chartHistory);\n  }, []);\n\n  const initialState: PendulumState = {\n    theta1: (theta1Deg * Math.PI) / 180,\n    omega1,\n    theta2: (theta2Deg * Math.PI) / 180,\n    omega2,\n  };\n  const initialTotalEnergy = totalEnergy(initialState, params);\n\n  const qDisplay = !liveMeta.valid ? '—' :\n    liveMeta.qFactor === Infinity ? '∞ (undamped)' :\n    liveMeta.qFactor > 999 ? '> 999' :\n    liveMeta.qFactor.toFixed(1);\n\n  const bwDisplay = !liveMeta.valid ? '—' :\n    liveMeta.bandwidth < 0.001 ? '~0' :\n    liveMeta.bandwidth.toFixed(3);\n\n  useTopicPreset(\"simulations-double-pendulum\", { \"m1\": setM1,\n    \"L1\": setL1,\n    \"theta1Deg\": setTheta1Deg,\n    \"omega1\": setOmega1,\n    \"m2\": setM2,\n    \"L2\": setL2,\n    \"theta2Deg\": setTheta2Deg,\n    \"omega2\": setOmega2,\n    \"damping\": setDamping,\n    \"trailLength\": setTrailLength }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Mechanics — Advanced</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Double pendulum</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Nonlinear coupled oscillators — deterministic chaos</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">L = T − V</span>\n          </div>\n\n          {/* Presets — snap-scroll for mobile */}\n          <div className=\"flex gap-2 overflow-x-auto pb-2 snap-x snap-mandatory scroll-smooth\">\n            {PRESETS.map((preset, i) => (\n              <button key={i} onClick={() => applyPreset(preset, i)}\n                className={`shrink-0 rounded-xl border px-3 py-2 text-left transition snap-start min-w-[180px] ${\n                  activePreset === i\n                    ? 'border-indigo-500 bg-indigo-50 shadow-sm ring-1 ring-indigo-300'\n                    : 'border-gray-200 bg-white hover:border-indigo-300 hover:shadow-sm'\n                }`}>\n                <p className=\"text-xs font-medium text-indigo-700\">{preset.name}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5 leading-relaxed\">{preset.description}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <DoublePendulumCanvas\n                  key={resetKey}\n                  theta1Deg={theta1Deg}\n                  omega1Init={omega1}\n                  theta2Deg={theta2Deg}\n                  omega2Init={omega2}\n                  params={params}\n                  isRunning={isRunning}\n                  isPaused={isPaused}\n                  showTrail={showTrail}\n                  showEnergy={showEnergy}\n                  trailLength={trailLength}\n                  onTick={handleTick}\n                  width={canvasSize.width}\n                  height={canvasSize.height}\n                />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/double-pendulum\"\n                  title=\"Double Pendulum — A-Factor STEM Studio\"\n                  params={{ m1, m2, L1, L2, t1: theta1Deg, t2: theta2Deg, w1: omega1, w2: omega2, damping, trail: trailLength }}\n                />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">First pendulum</p>\n                    <Slider label=\"Mass m₁\" unit=\"kg\" value={m1} min={0.1} max={3} step={0.1} set={setM1} color=\"#6366f1\" />\n                    <Slider label=\"Length L₁\" unit=\"m\" value={L1} min={0.3} max={2} step={0.1} set={setL1} color=\"#818cf8\" />\n                    <Slider label=\"Initial angle θ₁\" unit=\"°\" value={theta1Deg} min={-180} max={180} step={1} set={setTheta1Deg} color=\"#a78bfa\" />\n                    <Slider label=\"Initial ω₁\" unit=\"rad/s\" value={omega1} min={-5} max={5} step={0.1} set={setOmega1} color=\"#c4b5fd\" note=\"Initial angular velocity\" />\n                  </div>\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">Second pendulum</p>\n                    <Slider label=\"Mass m₂\" unit=\"kg\" value={m2} min={0.1} max={3} step={0.1} set={setM2} color=\"#f59e0b\" />\n                    <Slider label=\"Length L₂\" unit=\"m\" value={L2} min={0.3} max={2} step={0.1} set={setL2} color=\"#fbbf24\" />\n                    <Slider label=\"Initial angle θ₂\" unit=\"°\" value={theta2Deg} min={-180} max={180} step={1} set={setTheta2Deg} color=\"#fcd34d\" />\n                    <Slider label=\"Initial ω₂\" unit=\"rad/s\" value={omega2} min={-5} max={5} step={0.1} set={setOmega2} color=\"#fde68a\" note=\"Initial angular velocity\" />\n                  </div>\n                </div>\n                <div className=\"border-t border-gray-100 pt-3 space-y-3\">\n                  <Slider label=\"Damping\" unit=\"\" value={damping} min={0} max={0.5} step={0.01} set={setDamping} color=\"#ef4444\" note=\"0 = frictionless (energy conserved), higher = more air resistance\" />\n                  <Slider label=\"Trail length\" unit=\"frames\" value={trailLength} min={0} max={800} step={10} set={setTrailLength} color=\"#f43f5e\" />\n                  <div className=\"flex gap-3\">\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showTrail} onChange={e => setShowTrail(e.target.checked)} className=\"rounded\" />\n                      Show trail\n                    </label>\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showEnergy} onChange={e => setShowEnergy(e.target.checked)} className=\"rounded\" />\n                      Show energy bar\n                    </label>\n                  </div>\n                </div>\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"Initial total E\" value={initialTotalEnergy.toFixed(3)} unit=\"J\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Live kinetic E\" value={liveEnergy.ke.toFixed(3)} unit=\"J\" color=\"text-rose-500\" />\n                  <StatRow label=\"Live potential E\" value={liveEnergy.pe.toFixed(3)} unit=\"J\" color=\"text-blue-500\" />\n                  <StatRow label=\"Live total E\" value={liveEnergy.total.toFixed(3)} unit=\"J\" color=\"text-emerald-600\" />\n                  <StatRow label=\"θ₁\" value={(liveState.theta1 * 180 / Math.PI).toFixed(1)} unit=\"°\" color=\"text-purple-600\" />\n                  <StatRow label=\"θ₂\" value={(liveState.theta2 * 180 / Math.PI).toFixed(1)} unit=\"°\" color=\"text-amber-600\" />\n                  <StatRow label=\"ω₁\" value={liveState.omega1.toFixed(2)} unit=\"rad/s\" color=\"text-indigo-500\" />\n                  <StatRow label=\"ω₂\" value={liveState.omega2.toFixed(2)} unit=\"rad/s\" color=\"text-amber-500\" />\n                  <StatRow label=\"Q factor\" value={qDisplay} unit=\"\" color=\"text-pink-600\" />\n                  <StatRow label=\"Bandwidth\" value={bwDisplay} unit=\"rad/s\" color=\"text-cyan-600\" />\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Damping curve</p>\n                <DampingCurve history={chartHistory} />\n                <p className=\"text-[10px] text-gray-400 mt-1.5 leading-relaxed\">\n                  Log-energy vs time. A straight line confirms exponential decay (linear damping).\n                </p>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/ac-circuits/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { ACCircuitCanvas, ACMode } from '@/components/simulation/ACCircuitCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport {\n  angularFrequency, rmsFromPeak, inductiveReactance, capacitiveReactance,\n  seriesRLCImpedance, seriesRLCPhaseAngleDeg, resonantAngularFrequency,\n  parallelRLCImpedance, parallelRLCTotalCurrent, parallelRLCPhaseAngleDeg,\n  qFactorSeries, qFactorParallel, bandwidthHz,\n} from '@/lib/physics/electromagnetism';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\ntype Topic = 'waveform' | 'reactance' | 'series-rlc' | 'parallel-rlc' | 'resonance';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB', 'Undergraduate'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700', Undergraduate: 'bg-slate-200 text-slate-700',\n};\n\nconst TOPIC_META: Record<Topic, { title: string; icon: string; sub: string; eq: string }> = {\n  waveform:       { title: 'AC Waveform & RMS',      icon: '〰️', sub: 'Peak vs RMS values',        eq: 'Vrms = Vpeak/√2' },\n  reactance:      { title: 'Inductive & Capacitive Reactance', icon: '⏱️', sub: \"'ELI the ICE man'\", eq: 'XL=ωL, XC=1/ωC' },\n  'series-rlc':   { title: 'Series RLC Circuit',      icon: '📈', sub: 'Impedance & resonance',      eq: 'Z=√(R²+(XL-XC)²)' },\n  'parallel-rlc': { title: 'Parallel RLC Circuit',    icon: '🔀', sub: 'Branch currents & resonance', eq: 'I=√(IR²+(IC-IL)²)' },\n  resonance:      { title: 'Q-Factor & Bandwidth',    icon: '🎯', sub: 'How sharp is the tuning?',   eq: 'Q=f₀/BW' },\n};\n\nconst TEACHER_NOTES: Record<Topic, string[]> = {\n  waveform: [\n    'Alternating current (AC) reverses direction periodically, unlike DC which flows one way — mains supply is AC specifically because transformers (which only work on AC) make it far more efficient to transmit over long distances.',\n    'PEAK value is the maximum instantaneous value the wave reaches; RMS (root-mean-square) is the \"effective\" DC-equivalent value — the steady value that would deliver the same average power to a resistor.',\n    'For a sine wave, RMS = peak/√2 ≈ 0.707 × peak — this factor comes directly from averaging sin²(θ) over a full cycle, which works out to exactly 1/2.',\n    'When electricians or exam questions say \"230V mains\" or \"240V mains\", that is the RMS value — the actual peak voltage reaches roughly 325-340V.',\n    'Undergraduate note: average power in a resistor is P = Irms²R = Vrms²/R — using RMS values lets you apply the familiar DC power formulas directly to AC circuits without needing to integrate over a cycle each time.',\n  ],\n  reactance: [\n    'Reactance is the AC equivalent of resistance for inductors and capacitors — it opposes current flow, measured in ohms, but (unlike resistance) it depends on frequency.',\n    \"Mnemonic 'ELI the ICE man': in an inductor (L), EMF (voltage) Leads Current — ELI. In a capacitor (C), Current leads EMF (voltage) — ICE.\",\n    'Inductive reactance XL = ωL INCREASES with frequency — an inductor increasingly opposes fast-changing current (that\\u2019s exactly why it opposes the sudden current changes that create the back-EMF).',\n    'Capacitive reactance XC = 1/ωC DECREASES with frequency — a capacitor charges and discharges more freely as the current reverses faster, offering less opposition.',\n    'Undergraduate note: reactance doesn\\u2019t dissipate energy the way resistance does — a pure inductor or capacitor stores and returns energy every half-cycle rather than converting it to heat, which is why reactance and resistance combine as a right-angled (vector) sum rather than a simple addition.',\n  ],\n  'series-rlc': [\n    'A series RLC circuit combines a resistor, inductor, and capacitor in one loop, carrying a SINGLE shared current — their opposition to that current (R, XL, XC) combines as impedance Z = √(R² + (XL-XC)²), not a simple sum, because XL and XC act in OPPOSITE directions.',\n    'The phasor diagram shows why: VR is in phase with the current (reference direction), VL leads by 90°, VC lags by 90° — so VL and VC directly cancel each other, and only their DIFFERENCE combines with VR.',\n    'RESONANCE occurs when XL = XC (they cancel completely) — at this frequency, impedance is at its MINIMUM (Z = R exactly), current is at its MAXIMUM, and the circuit behaves as if it were purely resistive (phase angle = 0°).',\n    'Resonant angular frequency ω₀ = 1/√(LC) — this is the exact frequency an RLC circuit \"prefers\", the basis of tuning a radio receiver to a specific station by adjusting L or C.',\n    'Undergraduate note: away from resonance, the phase angle φ = arctan((XL-XC)/R) tells you whether the circuit is net inductive (current lags, φ>0) or net capacitive (current leads, φ<0) — and the power factor cos(φ) determines how much of VrmsIrms is actually real (usable) power versus reactive power that sloshes back and forth without doing net work.',\n  ],\n  'parallel-rlc': [\n    'In a PARALLEL RLC circuit, R, L, and C all share the same voltage (since they\\u2019re connected across the same two nodes) — each branch draws its own current, and the branch currents add as phasors: I = √(IR² + (IC-IL)²).',\n    \"The same 90° phase relationships apply per branch: IR is in phase with V, IL lags V by 90°, IC leads V by 90° — so IL and IC directly cancel in the phasor sum, exactly mirroring how VL and VC cancel in the series case.\",\n    'RESONANCE still occurs when XL = XC — but the behaviour is the OPPOSITE of series resonance: IL and IC cancel completely, leaving only IR, so the TOTAL LINE CURRENT is at its MINIMUM and the impedance seen by the source is at its MAXIMUM (equal to R).',\n    'This is why parallel resonant circuits are sometimes called \"rejector\" circuits (they reject/minimise current at resonance) while series resonant circuits are called \"acceptor\" circuits (they accept/maximise current at resonance) — the same LC combination, wired differently, does the opposite job.',\n    'Undergraduate note: the resonant frequency formula ω₀ = 1/√(LC) is the SAME for both series and parallel ideal RLC circuits — what differs between them is which quantity (current for series, impedance for parallel) peaks there, and how R affects the sharpness of that peak.',\n  ],\n  resonance: [\n    'The QUALITY FACTOR (Q) measures how \"sharp\" or selective a resonant circuit is — a high-Q circuit responds strongly only to a narrow band of frequencies near resonance; a low-Q circuit responds broadly across a wide range.',\n    'Series RLC: Q = (1/R)√(L/C) — LOWER resistance gives a HIGHER, sharper Q (less energy lost to R each cycle, so the resonance \"rings\" more before dying out).',\n    'Parallel RLC: Q = R√(C/L) — here it is the OPPOSITE dependence: HIGHER resistance gives a HIGHER Q, because in parallel, resistance provides a leak path for current that damps the resonance; more resistance means less of that damping path.',\n    'BANDWIDTH is the range of frequencies (in Hz) between the two \"half-power points\" either side of resonance — the frequencies where the power delivered has dropped to half its peak value. Bandwidth = f₀/Q: a sharper (higher-Q) resonance has a NARROWER bandwidth.',\n    'This is exactly how a radio tuner works: a high-Q circuit lets you pick out one station\\u2019s narrow frequency band while rejecting neighbouring stations; a low-Q circuit would let several stations through at once, overlapping and unusable.',\n    'Undergraduate note: the \"half-power\" points are where the response has fallen to 1/√2 (≈70.7%) of its peak — power depends on the square of voltage or current, so a 1/√2 drop in amplitude corresponds to exactly a 1/2 drop in power, which is where the name comes from. Bandwidth=f₀/Q is the standard high-Q approximation, increasingly exact as Q grows — for a low-Q circuit (broad, gentle peak) it is only approximate.',\n  ],\n};\n\nconst EXERCISES: Record<Topic, { q: string; a: string }[]> = {\n  waveform: [\n    { q: 'A UK-style AC supply has an RMS voltage of 230V. Find the peak voltage.', a: 'Vpeak = Vrms×√2 = 230×1.414 ≈ 325 V.' },\n    { q: 'A sinusoidal current has a peak value of 5A. Find the RMS value and the average power delivered to a 10Ω resistor.', a: 'Irms = 5/√2 ≈ 3.54A. Average power P = Irms²R = 3.54²×10 ≈ 125 W.' },\n    { q: 'Why can\\u2019t you just average the instantaneous values of a sine wave to find its \"effective\" value?', a: 'A sine wave is positive for exactly half the cycle and negative for the other half, so the simple average is always zero — RMS instead averages the SQUARE of the values (always positive) before taking the square root, giving a meaningful non-zero effective value.' },\n  ],\n  reactance: [\n    { q: 'Find the reactance of a 200mH inductor at a frequency of 50Hz.', a: 'XL = ωL = 2π×50×0.2 ≈ 62.8 Ω.' },\n    { q: 'Find the reactance of a 20µF capacitor at 50Hz.', a: 'XC = 1/(ωC) = 1/(2π×50×20×10⁻⁶) ≈ 159.2 Ω.' },\n    { q: 'As frequency increases, what happens to XL and XC, and how does that explain why a capacitor \"blocks DC but passes AC\"?', a: 'XL increases and XC decreases with frequency. At f=0 (DC), XC = 1/(0) → infinite — a capacitor completely blocks steady current. At high frequency, XC → 0, offering almost no opposition, so a capacitor lets rapidly alternating current pass relatively freely.' },\n  ],\n  'series-rlc': [\n    { q: 'A series RLC circuit has R=50Ω, XL=120Ω, XC=40Ω. Find the impedance.', a: 'Z = √(R² + (XL-XC)²) = √(50² + 80²) = √(2500+6400) = √8900 ≈ 94.3 Ω.' },\n    { q: 'For the same circuit, find the phase angle and state whether current leads or lags voltage.', a: 'φ = arctan((XL-XC)/R) = arctan(80/50) ≈ 58°. Since XL>XC, the circuit is net inductive, so CURRENT LAGS voltage by about 58°.' },\n    { q: 'A series circuit has L=0.2H and C=50µF. Find the resonant frequency.', a: 'ω₀ = 1/√(LC) = 1/√(0.2×50×10⁻⁶) = 1/√(1×10⁻⁵) ≈ 316.2 rad/s. f₀ = ω₀/2π ≈ 50.3 Hz.' },\n  ],\n  'parallel-rlc': [\n    { q: 'A parallel RLC circuit has IR=2A, IL=5A, IC=1.5A (all peak). Find the total line current.', a: 'I = √(IR² + (IC-IL)²) = √(2² + (1.5-5)²) = √(4+12.25) = √16.25 ≈ 4.03A.' },\n    { q: 'In the same circuit, is the total current more or less than IR alone, and what does that tell you about the phase?', a: 'More (4.03A > 2A) — since IL and IC do not cancel, there is a net reactive current, so the total current does not simply equal IR; it leads or lags voltage depending on whether IC or IL dominates (here IL>IC, so the circuit is net inductive and the line current lags voltage).' },\n    { q: 'Why does total line current DROP to a minimum at resonance in a parallel RLC circuit, when current in a series circuit RISES to a maximum?', a: 'At resonance IL=IC in both cases, so they cancel. In series, that cancellation leaves only R limiting current, so impedance is minimum and current is maximum. In parallel, cancelling IL and IC leaves only the small IR branch contributing to the LINE current, so the total current drawn from the source is minimum — even though current is still circulating between L and C internally.' },\n  ],\n  resonance: [\n    { q: 'A series RLC circuit has f₀=1000Hz and Q=50. Find the bandwidth and the two half-power frequencies.', a: 'BW = f₀/Q = 1000/50 = 20Hz. Half-power points ≈ f₀ ± BW/2 = 990Hz and 1010Hz.' },\n    { q: 'Two series RLC circuits have the same L and C but different R. Which one has the higher Q, and why?', a: 'The circuit with the SMALLER R has the higher Q, since Q=(1/R)√(L/C) — less resistance means less energy dissipated each cycle, so the resonance is sharper and rings longer.' },\n    { q: 'A radio tuner needs to separate two stations broadcasting just 10kHz apart, centred near 100MHz. Would a high-Q or low-Q circuit be more suitable, and why?', a: 'A HIGH-Q circuit — it produces a narrow bandwidth, letting through only a thin slice of frequencies around the tuned station while strongly rejecting a neighbouring station only 10kHz away. A low-Q (broad) circuit would let both stations through at once, overlapping and unusable.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function ACCircuitsPage() {\n  const [topic, setTopic] = useState<Topic>('waveform');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [vPeak, setVPeak] = useState(20);\n  const [frequency, setFrequency] = useState(2);\n  const [resistance, setResistance] = useState(100);\n\n  const [component, setComponent] = useState<'inductor' | 'capacitor'>('inductor');\n  const [inductance, setInductance] = useState(0.5);\n  const [capacitance, setCapacitance] = useState(10); // µF\n\n  const [rlcFrequency, setRlcFrequency] = useState(50);\n  const [parallelResistance, setParallelResistance] = useState(1000);\n\n  const [resonanceCircuit, setResonanceCircuit] = useState<'series' | 'parallel'>('series');\n  const [resR, setResR] = useState(100);\n  const [resL, setResL] = useState(0.5);\n  const [resC, setResC] = useState(10);\n\n  const [liveValue, setLiveValue] = useState(0);\n  const [speedMultiplier, setSpeedMultiplier] = useState(1);\n  const [showParams, setShowParams] = useState(true);\n  const [showTeacherNotes, setShowTeacherNotes] = useState(false);\n  const [phasorZoom, setPhasorZoom] = useState(false);\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 100);\n  }, [topic, vPeak, frequency, resistance, component, inductance, capacitance, rlcFrequency, parallelResistance, resonanceCircuit, resR, resL, resC, reset]);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 340, 980);\n\n  const capF = capacitance * 1e-6;\n  const isSeriesTopic = topic === 'series-rlc';\n  const isParallelTopic = topic === 'parallel-rlc';\n  const effFrequency = isSeriesTopic || isParallelTopic ? rlcFrequency : topic === 'resonance' ? 0 : frequency;\n  const omega = angularFrequency(isSeriesTopic || isParallelTopic ? rlcFrequency : frequency);\n  const XL = inductiveReactance(omega, inductance);\n  const XC = capacitiveReactance(omega, capF);\n  const Z = seriesRLCImpedance(resistance, XL, XC);\n  const phaseDeg = seriesRLCPhaseAngleDeg(resistance, XL, XC);\n  const omegaRes = resonantAngularFrequency(inductance, capF);\n  const fRes = omegaRes / (2 * Math.PI);\n  const reactanceX = component === 'inductor' ? XL : XC;\n\n  const parZ = parallelRLCImpedance(vPeak, parallelResistance, XL, XC);\n  const parI = parallelRLCTotalCurrent(vPeak, parallelResistance, XL, XC);\n  const parPhase = parallelRLCPhaseAngleDeg(parallelResistance, XL, XC);\n\n  const resCapF = resC * 1e-6;\n  const resOmega0 = resonantAngularFrequency(resL, resCapF);\n  const resF0 = resOmega0 / (2 * Math.PI);\n  const resQ = resonanceCircuit === 'series' ? qFactorSeries(resR, resL, resCapF) : qFactorParallel(resR, resL, resCapF);\n  const resBW = bandwidthHz(resF0, resQ);\n\n  useTopicPreset(\"simulations-ac-circuits\", { \"speedMultiplier\": setSpeedMultiplier,\n    \"vPeak\": setVPeak,\n    \"frequency\": setFrequency,\n    \"resistance\": setResistance,\n    \"inductance\": setInductance,\n    \"capacitance\": setCapacitance,\n    \"rlcFrequency\": setRlcFrequency,\n    \"parallelResistance\": setParallelResistance,\n    \"resL\": setResL,\n    \"resC\": setResC }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Electricity · Electromagnetism</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Simple AC Circuits</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(TOPIC_META) as Topic[]).map(t => (\n              <button key={t} onClick={() => { setTopic(t); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  topic === t ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{TOPIC_META[t].icon}</span><span>{TOPIC_META[t].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{TOPIC_META[topic].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{TOPIC_META[topic].eq}</span>\n          </div>\n\n          <SimulationStage className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <div data-stage-role=\"canvas\" className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <ACCircuitCanvas key={resetKey} mode={topic as ACMode}\n                  vPeak={vPeak} frequency={topic === 'resonance' ? resF0 : effFrequency}\n                  resistance={isParallelTopic ? parallelResistance : topic === 'resonance' ? resR : resistance}\n                  component={component}\n                  inductance={topic === 'resonance' ? resL : inductance}\n                  capacitance={topic === 'resonance' ? resCapF : capF}\n                  resonanceCircuit={resonanceCircuit} speedMultiplier={speedMultiplier} phasorZoom={phasorZoom}\n                  isRunning={isRunning} isPaused={isPaused} onTick={setLiveValue}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <div className=\"flex items-center gap-2 flex-wrap\">\n                  <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                    onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                    onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                  {topic !== 'resonance' && (\n                    <button onClick={() => setPhasorZoom(z => !z)}\n                      className={`rounded-lg border px-3 py-2 text-xs font-medium transition flex items-center gap-1 ${\n                        phasorZoom ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-600 hover:bg-gray-50'\n                      }`}>\n                      {phasorZoom ? '🔍 Zoomed — click to restore' : '🔍 Zoom phasor'}\n                    </button>\n                  )}\n                </div>\n                <EmbedButton path=\"/embed/ac-circuits\"\n                  title={`${TOPIC_META[topic].title} — A-Factor STEM Studio`}\n                  params={{ topic }} />\n              </div>\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <div className=\"flex items-center justify-between\">\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                  <button onClick={() => setShowParams(p => !p)}\n                    className=\"text-xs font-medium text-indigo-600 hover:text-indigo-700 flex items-center gap-1\">\n                    {showParams ? 'Hide' : 'Show'}\n                    <span className={`transition-transform ${showParams ? 'rotate-180' : ''}`}>▾</span>\n                  </button>\n                </div>\n\n                {showParams && <>\n                <Slider label=\"Animation speed\" unit=\"×\" value={speedMultiplier} min={0.25} max={3} step={0.25} set={setSpeedMultiplier} color=\"#94a3b8\" />\n\n                {topic === 'waveform' && <>\n                  <Slider label=\"Peak voltage\" unit=\"V\" value={vPeak} min={5} max={50} step={5} set={setVPeak} color=\"#6366f1\" />\n                  <Slider label=\"Frequency\" unit=\"Hz\" value={frequency} min={0.5} max={5} step={0.5} set={setFrequency} color=\"#f59e0b\" />\n                  <Slider label=\"Resistance\" unit=\"Ω\" value={resistance} min={10} max={500} step={10} set={setResistance} color=\"#8b5cf6\" />\n                </>}\n\n                {topic === 'reactance' && <>\n                  <div className=\"flex gap-2\">\n                    {(['inductor', 'capacitor'] as const).map(c => (\n                      <button key={c} onClick={() => setComponent(c)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                          component === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{c}</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Peak voltage\" unit=\"V\" value={vPeak} min={5} max={50} step={5} set={setVPeak} color=\"#6366f1\" />\n                  <Slider label=\"Frequency\" unit=\"Hz\" value={frequency} min={0.5} max={5} step={0.5} set={setFrequency} color=\"#f59e0b\" />\n                  {component === 'inductor'\n                    ? <Slider label=\"Inductance\" unit=\"H\" value={inductance} min={0.1} max={2} step={0.1} set={setInductance} color=\"#8b5cf6\" />\n                    : <Slider label=\"Capacitance\" unit=\"µF\" value={capacitance} min={1} max={50} step={1} set={setCapacitance} color=\"#8b5cf6\" />}\n                </>}\n\n                {topic === 'series-rlc' && <>\n                  <Slider label=\"Peak voltage\" unit=\"V\" value={vPeak} min={5} max={50} step={5} set={setVPeak} color=\"#6366f1\" />\n                  <Slider label=\"Frequency\" unit=\"Hz\" value={rlcFrequency} min={10} max={200} step={1} set={setRlcFrequency} color=\"#f59e0b\"\n                    note={`Resonance at ≈ ${fRes.toFixed(1)} Hz`} />\n                  <Slider label=\"Resistance\" unit=\"Ω\" value={resistance} min={10} max={300} step={10} set={setResistance} color=\"#059669\" />\n                  <Slider label=\"Inductance\" unit=\"H\" value={inductance} min={0.1} max={2} step={0.1} set={setInductance} color=\"#dc2626\" />\n                  <Slider label=\"Capacitance\" unit=\"µF\" value={capacitance} min={1} max={50} step={1} set={setCapacitance} color=\"#2563eb\" />\n                </>}\n\n                {topic === 'parallel-rlc' && <>\n                  <Slider label=\"Peak voltage\" unit=\"V\" value={vPeak} min={5} max={50} step={5} set={setVPeak} color=\"#6366f1\" />\n                  <Slider label=\"Frequency\" unit=\"Hz\" value={rlcFrequency} min={10} max={200} step={1} set={setRlcFrequency} color=\"#f59e0b\"\n                    note={`Resonance at ≈ ${fRes.toFixed(1)} Hz`} />\n                  <Slider label=\"Resistance\" unit=\"Ω\" value={parallelResistance} min={100} max={3000} step={100} set={setParallelResistance} color=\"#059669\" />\n                  <Slider label=\"Inductance\" unit=\"H\" value={inductance} min={0.1} max={2} step={0.1} set={setInductance} color=\"#dc2626\" />\n                  <Slider label=\"Capacitance\" unit=\"µF\" value={capacitance} min={1} max={50} step={1} set={setCapacitance} color=\"#2563eb\" />\n                </>}\n\n                {topic === 'resonance' && <>\n                  <div className=\"flex gap-2\">\n                    {(['series', 'parallel'] as const).map(c => (\n                      <button key={c} onClick={() => setResonanceCircuit(c)}\n                        className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium capitalize transition ${\n                          resonanceCircuit === c ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500'\n                        }`}>{c}</button>\n                    ))}\n                  </div>\n                  <Slider label=\"Peak voltage\" unit=\"V\" value={vPeak} min={5} max={50} step={5} set={setVPeak} color=\"#6366f1\" />\n                  <Slider label=\"Resistance\" unit=\"Ω\" value={resR} min={resonanceCircuit === 'series' ? 5 : 200} max={resonanceCircuit === 'series' ? 200 : 3000}\n                    step={resonanceCircuit === 'series' ? 5 : 100} set={setResR} color=\"#059669\"\n                    note={resonanceCircuit === 'series' ? 'Lower R → sharper (higher Q) peak' : 'Higher R → sharper (higher Q) peak'} />\n                  <Slider label=\"Inductance\" unit=\"H\" value={resL} min={0.1} max={2} step={0.1} set={setResL} color=\"#dc2626\" />\n                  <Slider label=\"Capacitance\" unit=\"µF\" value={resC} min={1} max={50} step={1} set={setResC} color=\"#2563eb\" />\n                </>}\n                </>}\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  {topic === 'waveform' && <>\n                    <StatRow label=\"Vrms\" value={rmsFromPeak(vPeak).toFixed(1)} unit=\"V\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Irms\" value={rmsFromPeak(vPeak / resistance).toFixed(2)} unit=\"A\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Average power\" value={((rmsFromPeak(vPeak) ** 2) / resistance).toFixed(2)} unit=\"W\" color=\"text-amber-600\" />\n                    <StatRow label=\"v(t) now\" value={liveValue.toFixed(1)} unit=\"V\" color=\"text-gray-500\" />\n                  </>}\n                  {topic === 'reactance' && <>\n                    <StatRow label={component === 'inductor' ? 'XL' : 'XC'} value={reactanceX.toFixed(1)} unit=\"Ω\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Peak current\" value={(vPeak / reactanceX).toFixed(3)} unit=\"A\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Phase\" value={component === 'inductor' ? 'I lags V by 90°' : 'I leads V by 90°'} unit=\"\" color=\"text-amber-600\" />\n                  </>}\n                  {topic === 'series-rlc' && <>\n                    <StatRow label=\"XL\" value={XL.toFixed(1)} unit=\"Ω\" color=\"text-red-600\" />\n                    <StatRow label=\"XC\" value={XC.toFixed(1)} unit=\"Ω\" color=\"text-fuchsia-600\" />\n                    <StatRow label=\"Impedance Z\" value={Z.toFixed(1)} unit=\"Ω\" color=\"text-teal-600\" />\n                    <StatRow label=\"Phase angle\" value={phaseDeg.toFixed(1)} unit=\"°\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Resonant f₀\" value={fRes.toFixed(1)} unit=\"Hz\" color=\"text-purple-600\" />\n                  </>}\n                  {topic === 'parallel-rlc' && <>\n                    <StatRow label=\"XL\" value={XL.toFixed(1)} unit=\"Ω\" color=\"text-red-600\" />\n                    <StatRow label=\"XC\" value={XC.toFixed(1)} unit=\"Ω\" color=\"text-fuchsia-600\" />\n                    <StatRow label=\"Impedance Z\" value={parZ.toFixed(0)} unit=\"Ω\" color=\"text-teal-600\" />\n                    <StatRow label=\"Line current\" value={parI.toFixed(3)} unit=\"A\" color=\"text-emerald-600\" />\n                    <StatRow label=\"Phase angle\" value={parPhase.toFixed(1)} unit=\"°\" color=\"text-amber-600\" />\n                    <StatRow label=\"Resonant f₀\" value={fRes.toFixed(1)} unit=\"Hz\" color=\"text-purple-600\" />\n                  </>}\n                  {topic === 'resonance' && <>\n                    <StatRow label=\"Resonant f₀\" value={resF0.toFixed(1)} unit=\"Hz\" color=\"text-purple-600\" />\n                    <StatRow label=\"Q factor\" value={resQ.toFixed(2)} unit=\"\" color=\"text-indigo-600\" />\n                    <StatRow label=\"Bandwidth\" value={resBW.toFixed(1)} unit=\"Hz\" color=\"text-emerald-600\" />\n                    <StatRow label=\"f₁ (lower)\" value={(resF0 - resBW / 2).toFixed(1)} unit=\"Hz\" color=\"text-amber-600\" />\n                    <StatRow label=\"f₂ (upper)\" value={(resF0 + resBW / 2).toFixed(1)} unit=\"Hz\" color=\"text-amber-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <div className=\"flex items-center justify-between mb-3\">\n                  <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide\">📋 Teacher notes</p>\n                  <button onClick={() => setShowTeacherNotes(p => !p)}\n                    className=\"text-xs font-medium text-amber-700 hover:text-amber-800 flex items-center gap-1\">\n                    {showTeacherNotes ? 'Hide' : 'Show'}\n                    <span className={`transition-transform ${showTeacherNotes ? 'rotate-180' : ''}`}>▾</span>\n                  </button>\n                </div>\n                {showTeacherNotes && (\n                  <ul className=\"space-y-2\">\n                    {TEACHER_NOTES[topic].map((n, i) => (\n                      <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                        <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                      </li>\n                    ))}\n                  </ul>\n                )}\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[topic].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/de-broglie/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { DeBroglieCanvas } from '@/components/simulation/DeBroglieCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { PARTICLES, deBroglieLambda, momentum, formatLambda, lambdaFromVoltage } from '@/lib/physics/debroglie';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TEACHER_NOTES = [\n  'De Broglie (1924): if light waves can behave as particles (photons), then particles should behave as waves — λ = h/mv. Confirmed by Davisson–Germer electron diffraction in 1927.',\n  'The key comparison: an electron at 2×10⁶ m/s has λ ≈ 0.36 nm (atom-sized → diffracts off crystals) while a cricket ball has λ ≈ 10⁻³⁴ m — unimaginably smaller than a nucleus, so we never see cricket balls diffract.',\n  'Larger momentum → shorter wavelength. Switch particles and watch λ collapse: mass in the denominator is why wave behaviour is invisible for everyday objects.',\n  'Electron microscopes exploit this: electrons accelerated through kilovolts get λ far below visible light (400–700 nm), resolving individual atoms.',\n  'For an electron accelerated through voltage V: λ = h/√(2meV) ≈ 1.23/√V nm — a favourite exam derivation (KE = eV = p²/2m).',\n];\n\nconst EXERCISES = [\n  { q: 'Find the de Broglie wavelength of an electron (m = 9.11×10⁻³¹ kg) moving at 2×10⁶ m/s.', a: 'λ = h/mv = 6.63e-34 / (9.11e-31 × 2e6) = 3.6×10⁻¹⁰ m = 0.36 nm.' },\n  { q: 'A 0.16 kg cricket ball travels at 30 m/s. Find λ and explain why we never observe its wave nature.', a: 'λ = 6.63e-34/(0.16×30) ≈ 1.4×10⁻³⁴ m — about 10¹⁹ times smaller than a nucleus, far too small for any slit or detector.' },\n  { q: 'An electron is accelerated from rest through 100 V. Find its de Broglie wavelength.', a: 'λ = h/√(2meV) = 6.63e-34/√(2×9.11e-31×1.6e-19×100) ≈ 1.23×10⁻¹⁰ m ≈ 0.123 nm.' },\n  { q: 'A proton and an electron have the SAME speed. Which has the longer wavelength and by what factor?', a: 'λ ∝ 1/m at fixed v, so the electron: longer by mp/me ≈ 1836 times.' },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value.toExponential(2)} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function DeBrogliePage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'JUPEB']);\n\n  const [pIdx, setPIdx] = useState(0);\n  const particle = PARTICLES[pIdx];\n  const [velocity, setVelocity] = useState(particle.vDefault);\n  const [accelV, setAccelV] = useState(100);\n\n  const selectParticle = (i: number) => { setPIdx(i); setVelocity(PARTICLES[i].vDefault); };\n\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [pIdx, velocity, reset]);\n\n  const lambda = deBroglieLambda(particle.mass, velocity);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 280, 980);\n\n  useTopicPreset(\"simulations-de-broglie\", { \"accelV\": setAccelV }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Modern physics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">De Broglie hypothesis</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Matter waves</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">λ = h/mv = h/p</span>\n            <span className=\"text-xs text-gray-400 ml-2\">accelerated electron: λ = h/√(2meV)</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <DeBroglieCanvas mass={particle.mass} velocity={velocity} particleName={particle.name}\n                  isRunning={isRunning} isPaused={isPaused} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/debroglie\"\n                  title=\"De Broglie wavelength — A-Factor STEM Studio\"\n                  params={{ p: pIdx, v: velocity }} />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {PARTICLES.map((p, i) => (\n                    <button key={p.name} onClick={() => selectParticle(i)}\n                      className={`rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n                        pIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'\n                      }`}>{p.emoji} {p.name}</button>\n                  ))}\n                </div>\n                <Slider label=\"Speed v\" unit=\"m/s\" value={velocity} min={particle.vMin} max={particle.vMax}\n                  step={(particle.vMax - particle.vMin) / 200} set={setVelocity} color=\"#6366f1\"\n                  note=\"Faster → more momentum → SHORTER wavelength\" />\n                <div className=\"rounded-xl bg-indigo-50 border border-indigo-100 p-3 space-y-2\">\n                  <p className=\"text-[11px] font-medium text-indigo-700\">Electron gun calculator: λ = h/√(2meV)</p>\n                  <Slider label=\"Accelerating voltage\" unit=\"V\" value={accelV} min={10} max={10000} step={10} set={setAccelV} color=\"#8b5cf6\" />\n                  <p className=\"text-xs text-indigo-800 font-mono\">\n                    V = {accelV} V → λ = {formatLambda(lambdaFromVoltage(accelV))}\n                  </p>\n                </div>\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"Mass m\" value={particle.mass.toExponential(2)} unit=\"kg\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Momentum p\" value={momentum(particle.mass, velocity).toExponential(2)} unit=\"kg·m/s\" color=\"text-emerald-600\" />\n                  <StatRow label=\"Wavelength λ\" value={formatLambda(lambda)} unit=\"\" color=\"text-amber-600\" />\n                  <StatRow label=\"vs atom (0.1nm)\" value={(lambda / 1e-10).toExponential(1)} unit=\"×\" color=\"text-rose-500\" />\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/band-theory/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useMemo } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { BandTheoryCanvas } from '@/components/simulation/BandTheoryCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport {\n  BAND_PRESETS, BandTheoryParams, MaterialType, DopingType,\n  MATERIALS, kT_eV, intrinsicConcentration, dopedFermiLevel,\n  materialTypeLabel, getConductivityDescription,\n  type BandTheoryStats,\n} from '@/lib/physics/bandTheory';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB', 'A-Level', 'Undergrad'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700',\n  NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700',\n  SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n  'A-Level': 'bg-cyan-100 text-cyan-700',\n  Undergrad: 'bg-rose-100 text-rose-700',\n};\n\nconst SCENARIO_NOTES: Record<MaterialType, { title: string; bullets: string[] }> = {\n  insulator: {\n    title: 'Insulators — Forbidden Gap Blocks All Conduction',\n    bullets: [\n      'The band gap Eg > 3 eV is so large that thermal energy at room temperature (kT ≈ 0.025 eV) cannot excite electrons from the valence band to the conduction band.',\n      'At T = 0 K, the valence band is completely full and the conduction band completely empty. The Fermi level sits near the middle of the gap.',\n      'Even at 1000 K, kT ≈ 0.086 eV is still far smaller than Eg for diamond (5.5 eV). Insulators remain non-conductive across all practical temperatures.',\n      'The filled valence band cannot carry current because for every electron moving right, another moves left — net current is zero. No empty states exist for acceleration.',\n      'Applications: electrical isolation, substrate materials, optical windows (transparent because photons with E < Eg cannot be absorbed).',\n    ],\n  },\n  semiconductor: {\n    title: 'Semiconductors — The Tunable Middle Ground',\n    bullets: [\n      'The band gap Eg ≈ 0.5–2 eV is small enough that thermal excitation creates a measurable number of electron-hole pairs at room temperature, but large enough that conductivity is controllable.',\n      'Intrinsic semiconductors: ni = √(NcNv) exp(−Eg/2kT). For Si at 300 K, ni is of order 10¹⁰ cm⁻³ — tiny compared to metals (~10²² cm⁻³), but enough for electronics.',\n      'Doping introduces donor (n-type) or acceptor (p-type) impurities at ~10¹⁵–10¹⁹ cm⁻³, overwhelming intrinsic carriers and shifting the Fermi level toward Ec or Ev.',\n      'The Fermi level is the energy at which the probability of occupation is 50%. In n-type material it rises toward Ec; in p-type it falls toward Ev.',\n      'Temperature dependence: at low T, carriers freeze out onto dopants. At moderate T, extrinsic conduction dominates. At high T, intrinsic carriers dominate again — this limits device operating temperatures.',\n    ],\n  },\n  conductor: {\n    title: 'Conductors — Overlapping Bands Create Free Electrons',\n    bullets: [\n      'In metals, the valence and conduction bands overlap (Eg = 0). There is no forbidden gap — electrons are always free to move and accelerate under an electric field.',\n      'The Fermi level lies inside the conduction band. Even at absolute zero, states above Ef are available for conduction. This is why metals conduct at all temperatures.',\n      'Electron concentration is enormous: ~10²² cm⁻³, roughly one free electron per atom. This is 10¹² times higher than intrinsic silicon.',\n      'Resistance in metals arises from electron-phonon and electron-impurity scattering, not from a lack of carriers. As T increases, phonon scattering increases → resistance rises.',\n      'The Drude model (classical) and Sommerfeld model (quantum) both explain metallic conduction, but only the quantum model correctly predicts specific heat and the Wiedemann-Franz law.',\n    ],\n  },\n};\n\nconst GENERAL_NOTES = [\n  'Energy bands arise from the periodic potential of the crystal lattice. The Schrödinger equation in a periodic potential (Kronig-Penney model) produces allowed energy bands separated by forbidden gaps.',\n  'The Pauli exclusion principle prevents electrons from occupying the same quantum state. A filled band cannot conduct because there are no adjacent empty states for electrons to move into.',\n  'The Fermi-Dirac distribution f(E) = 1/(exp((E−Ef)/kT) + 1) gives the probability that a state at energy E is occupied. At T = 0, it is a step function; at T > 0, the step smooths over ~kT.',\n  'Direct bandgap (GaAs): the conduction band minimum and valence band maximum occur at the same k-point. An electron can drop directly, emitting a photon — ideal for LEDs and lasers.',\n  'Indirect bandgap (Si, Ge): the band edges occur at different k-points. Recombination requires a phonon to conserve momentum, making photon emission far less efficient.',\n  'The density of states g(E) ∝ √(E−Ec) in the conduction band and ∝ √(Ev−E) in the valence band. This parabolic shape arises from the free-electron-like dispersion near band edges.',\n];\n\nconst EXERCISES = [\n  {\n    q: 'Set material to Diamond (insulator) at 300 K. How many electrons do you see in the conduction band? Why? Calculate the approximate number per cm³.',\n    a: 'Virtually zero electrons in the conduction band. For Eg = 5.5 eV and kT = 0.025 eV, ni ≈ √(NcNv) exp(−5.5/0.05) ≈ 10¹⁹ × exp(−110) ≈ 10⁻²⁹ cm⁻³. Essentially none. The probability of thermal excitation across the gap is astronomically small.',\n  },\n  {\n    q: 'Switch to Silicon (semiconductor). Increase temperature from 300 K to 600 K. What happens to the number of conduction electrons? By what factor does ni increase?',\n    a: 'ni doubles roughly every 10 K for Si near room temperature, but the exact factor from 300→600 K is ~10⁶ (from ~10¹⁰ to ~10¹⁶ cm⁻³). The exponential term exp(−Eg/2kT) dominates. At 600 K, silicon becomes significantly conductive — this is why high-temperature electronics use wide-bandgap materials like SiC.',\n  },\n  {\n    q: 'Set Silicon to n-type with doping 10¹⁶ cm⁻³. Where does the Fermi level move? What happens to electron and hole concentrations?',\n    a: 'The Fermi level shifts up toward the conduction band: Ef ≈ Ec − kT ln(Nc/Nd) ≈ 1.12 − 0.025 ln(2.8×10¹⁹/10¹⁶) ≈ 1.12 − 0.21 ≈ 0.91 eV above the valence band. Electron concentration ≈ Nd = 10¹⁶ cm⁻³. Hole concentration drops to p ≈ ni²/Nd ≈ (1.5×10¹⁰)²/10¹⁶ ≈ 2.25×10⁴ cm⁻³ — minority carriers are suppressed.',\n  },\n  {\n    q: 'Compare Silicon and Germanium at the same temperature (300 K). Which has more intrinsic carriers? Why does this make Ge less suitable for high-temperature devices?',\n    a: 'Ge has Eg = 0.67 eV vs Si 1.12 eV. The exponential gives ni(Ge) ≈ ni(Si) × exp((1.12−0.67)/(2×0.025)) ≈ 2×10¹³ cm⁻³, about 1000× higher. At elevated temperatures, Ge becomes too conductive intrinsically, making it hard to control with doping. Si remains extrinsic up to ~150°C.',\n  },\n  {\n    q: 'Select Copper (conductor). Why are there electrons in the \"conduction band\" even at 0 K? What would happen to resistance as temperature increases?',\n    a: 'Copper has overlapping valence and conduction bands — no gap exists. The Fermi level sits inside the conduction band, so states are always available. At 0 K, electrons fill up to Ef but states above remain empty. As T increases, phonon scattering increases, so resistance rises (unlike semiconductors, where resistance falls because more carriers are generated).',\n  },\n  {\n    q: 'Graduate: Explain why the Fermi level in an intrinsic semiconductor sits very close to the middle of the band gap, but not exactly at the midpoint.',\n    a: 'Charge neutrality requires n = p. Using n = Nc exp(−(Ec−Ef)/kT) and p = Nv exp(−(Ef−Ev)/kT), setting n = p gives Ef = (Ec+Ev)/2 + (3kT/4) ln(mh*/me*). The second term shifts Ef slightly because the effective densities of states Nc and Nv depend on the effective masses of electrons and holes. For Si, mh* > me*, so Ef is slightly above midgap.',\n  },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">\n          {value} <span className=\"text-gray-400 font-normal\">{unit}</span>\n        </span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string; }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nfunction CollapsiblePanel({\n  title, children, defaultOpen = true, badge,\n}: {\n  title: string; children: React.ReactNode; defaultOpen?: boolean; badge?: string;\n}) {\n  const [open, setOpen] = useState(defaultOpen);\n  return (\n    <div className=\"rounded-2xl border border-gray-200 bg-white shadow-sm overflow-hidden\">\n      <button onClick={() => setOpen((o) => !o)} className=\"w-full flex items-center justify-between px-4 py-3 hover:bg-gray-50 transition\">\n        <div className=\"flex items-center gap-2\">\n          <span className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">{title}</span>\n          {badge && <span className=\"text-[10px] px-1.5 py-0.5 rounded-full bg-indigo-50 text-indigo-600 font-medium\">{badge}</span>}\n        </div>\n        <span className=\"text-gray-400 text-xs\">{open ? '▲ Hide' : '▼ Show'}</span>\n      </button>\n      {open && <div className=\"px-4 pb-4\">{children}</div>}\n    </div>\n  );\n}\n\nexport default function BandTheoryPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB', 'A-Level', 'Undergrad']);\n\n  const [material, setMaterial] = useState('silicon');\n  const [temperature, setTemperature] = useState(300);\n  const [dopingType, setDopingType] = useState<DopingType>('intrinsic');\n  const [dopingConcentration, setDopingConcentration] = useState(10);\n  const [speed, setSpeed] = useState(1);\n  const [zoom, setZoom] = useState(1);\n  const [showElectrons, setShowElectrons] = useState(true);\n  const [showHoles, setShowHoles] = useState(true);\n  const [showFermiLevel, setShowFermiLevel] = useState(true);\n  const [showBandGap, setShowBandGap] = useState(true);\n  const [showThermalEnergy, setShowThermalEnergy] = useState(false);\n  const [showDOS, setShowDOS] = useState(true);\n  const [animateCarriers, setAnimateCarriers] = useState(true);\n\n  const params: BandTheoryParams = {\n    material, temperature, dopingType, dopingConcentration,\n    speed, zoom, showElectrons, showHoles, showFermiLevel,\n    showBandGap, showThermalEnergy, showDOS, animateCarriers,\n  };\n\n  const [liveStats, setLiveStats] = useState<BandTheoryStats>({\n    bandGap: 1.12, temperature: 300, kT: 0.0259, fermiLevel: 0.56,\n    intrinsicConc: 1.5e10, electronConc: 1.5e10, holeConc: 1.5e10, conductivity: 'Moderate',\n  });\n\n  const mat = MATERIALS[material];\n  const matType = mat?.type || 'semiconductor';\n\n  const applyPreset = useCallback((presetIdx: number) => {\n    const preset = BAND_PRESETS[presetIdx];\n    if (!preset) return;\n    const pp = preset.params;\n    if (pp.material) setMaterial(pp.material);\n    if (pp.temperature !== undefined) setTemperature(pp.temperature);\n    if (pp.dopingType) setDopingType(pp.dopingType);\n    if (pp.dopingConcentration !== undefined) setDopingConcentration(pp.dopingConcentration);\n    if (pp.showElectrons !== undefined) setShowElectrons(pp.showElectrons);\n    if (pp.showHoles !== undefined) setShowHoles(pp.showHoles);\n    if (pp.showFermiLevel !== undefined) setShowFermiLevel(pp.showFermiLevel);\n    if (pp.showBandGap !== undefined) setShowBandGap(pp.showBandGap);\n    if (pp.showThermalEnergy !== undefined) setShowThermalEnergy(pp.showThermalEnergy);\n    setIsRunning(false); setIsPaused(false);\n    setResetKey((k) => k + 1);\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey((k) => k + 1);\n  }, []);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 720, 600, 1100, 420);\n\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((stats: BandTheoryStats) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveStats(stats);\n  }, []);\n\n  const scenarioNote = SCENARIO_NOTES[matType];\n  const dopingLabel = dopingType === 'intrinsic' ? 'Intrinsic' : dopingType === 'n-type' ? 'n-type' : 'p-type';\n\n  useTopicPreset(\"simulations-band-theory\", { \"temperature\": setTemperature,\n    \"dopingConcentration\": setDopingConcentration,\n    \"speed\": setSpeed,\n    \"zoom\": setZoom }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Solid State Physics — Electronic Properties of Materials</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Energy Band Theory</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map((c) => (\n                  <button key={c} onClick={() => setActiveCurricula((p) => p.includes(c) ? p.filter((x) => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'}`}>\n                    {c}\n                  </button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Atomic Orbitals → Crystal Bands → Gap → Doping → Devices</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">ni = √(NcNv) e^(−Eg/2kT)</span>\n          </div>\n\n          {/* Material type cards */}\n          <div className=\"grid grid-cols-3 lg:grid-cols-6 gap-1.5 sm:gap-2\">\n            {Object.entries(MATERIALS).map(([key, m]) => {\n              const active = material === key;\n              return (\n                <button key={key} onClick={() => { setMaterial(key); setIsRunning(false); setResetKey((k) => k + 1); }}\n                  className={`relative rounded-xl border px-2 py-2 sm:px-3 sm:py-3 text-left hover:shadow-md transition min-w-0\n                    ${active ? 'border-indigo-400 bg-indigo-50 text-indigo-800 ring-1 ring-indigo-200' : 'border-gray-200 bg-white text-gray-600 hover:border-indigo-200'}`}>\n                  <div className=\"flex items-center justify-between mb-0.5 sm:mb-1\">\n                    <p className={`text-[10px] sm:text-xs font-semibold ${active ? 'text-indigo-700' : 'text-gray-700'}`}>{m.symbol}</p>\n                    {active && <span className=\"w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full bg-indigo-500 animate-pulse\" />}\n                  </div>\n                  <p className=\"text-[9px] sm:text-[10px] text-gray-400 leading-relaxed\">{m.name}</p>\n                  <p className=\"text-[9px] text-gray-400 mt-0.5\">{m.bandGap > 0 ? `Eg=${m.bandGap}eV` : 'No gap'}</p>\n                  {active && <div className=\"absolute bottom-0 left-0 right-0 h-0.5 bg-indigo-400 rounded-b-xl\" />}\n                </button>\n              );\n            })}\n          </div>\n\n          {/* Presets */}\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {BAND_PRESETS.map((preset, i) => (\n              <button key={i} onClick={() => applyPreset(i)}\n                className=\"shrink-0 rounded-xl border border-gray-200 bg-white px-3 py-2 text-left hover:border-indigo-300 hover:shadow-sm transition min-w-[200px]\">\n                <p className=\"text-xs font-medium text-indigo-700\">{preset.name}</p>\n                <p className=\"text-[10px] text-gray-400 mt-0.5 leading-relaxed\">{preset.description}</p>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_280px] xl:grid-cols-[minmax(0,1fr)_280px_300px] gap-4 items-start\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <BandTheoryCanvas key={resetKey} params={params} isRunning={isRunning} isPaused={isPaused} onTick={handleTick} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused((p) => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/band-theory\" title=\"Energy Band Theory — A-Factor STEM Studio\"\n                  params={{ mat: material, T: temperature, dopant: dopingType, conc: dopingConcentration, speed, zoom, e: showElectrons ? 1 : 0, h: showHoles ? 1 : 0, ef: showFermiLevel ? 1 : 0, eg: showBandGap ? 1 : 0, kt: showThermalEnergy ? 1 : 0, dos: showDOS ? 1 : 0, anim: animateCarriers ? 1 : 0 }} />\n              </div>\n\n              <div data-stage-role=\"extra\" className=\"rounded-xl border border-indigo-200 bg-indigo-50 p-4 text-sm leading-6 text-indigo-950\">\n                <p><strong>What moves?</strong> Electrons occupy allowed states. A hole is an unoccupied valence-band state, not a separate positive particle. When a neighbouring electron fills it, the vacancy shifts in the opposite direction. The row below the bands demonstrates this process.</p>\n                <p className=\"mt-2\">Filled blue dots are electrons; hollow pink markers show vacancies. Without an applied field, thermal motion gives no net drift. The f(E) curve shows occupation probability, not the number of states.</p>\n                <p className=\"mt-2 text-xs\">Teaching model: complete dopant ionisation and non-degenerate statistics; counts are amplified for visibility. Freeze-out at low temperature and very heavy doping are outside its quantitative accuracy. The gap is held constant. <a className=\"underline\" href=\"https://openstax.org/books/university-physics-volume-3/pages/9-6-semiconductors-and-doping\" target=\"_blank\" rel=\"noreferrer\">Read about electrons and holes</a>.</p>\n              </div>\n\n              {/* Parameters — sticky bottom on desktop, right after controls on mobile */}\n              <div data-stage-role=\"parameters\" className=\"relative z-10\">\n                <CollapsiblePanel title=\"Parameters\" badge=\"Interactive\" defaultOpen={true}>\n                  <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-6 gap-y-4\">\n                    <div className=\"space-y-3\">\n                      <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">Material</p>\n                      <Slider label=\"Temperature\" unit=\"K\" value={temperature} min={0} max={1000} step={10} set={setTemperature} color=\"#f43f5e\" note={`Thermal energy kT = ${kT_eV(temperature).toFixed(3)} eV`} />\n                      <Slider label=\"Doping conc.\" unit=\"log₁₀(cm⁻³)\" value={dopingConcentration} min={10} max={20} step={0.5} set={setDopingConcentration} color=\"#8b5cf6\" note={`Actual: ${Math.pow(10, dopingConcentration).toExponential(0)} cm⁻³`} />\n                    </div>\n                    <div className=\"space-y-3\">\n                      <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">Doping</p>\n                      <div className=\"flex gap-2\">\n                        {(['intrinsic', 'n-type', 'p-type'] as DopingType[]).map((d) => (\n                          <button key={d} onClick={() => setDopingType(d)}\n                            className={`text-xs px-3 py-1.5 rounded-lg border transition ${dopingType === d ? 'border-indigo-400 bg-indigo-50 text-indigo-700 font-medium' : 'border-gray-200 text-gray-500 hover:border-indigo-200'}`}>\n                            {d}\n                          </button>\n                        ))}\n                      </div>\n                      <Slider label=\"Animation speed\" unit=\"×\" value={speed} min={0} max={3} step={0.1} set={setSpeed} color=\"#3b82f6\" />\n                      <Slider label=\"Zoom\" unit=\"×\" value={zoom} min={0.5} max={2} step={0.1} set={setZoom} color=\"#10b981\" />\n                    </div>\n                    <div className=\"space-y-3\">\n                      <p className=\"text-[10px] font-medium text-emerald-600 uppercase tracking-wide\">Display</p>\n                      <div className=\"flex flex-wrap gap-2\">\n                        {[\n                          { label: 'Electrons', checked: showElectrons, set: setShowElectrons },\n                          { label: 'Holes', checked: showHoles, set: setShowHoles },\n                          { label: 'Fermi level', checked: showFermiLevel, set: setShowFermiLevel },\n                          { label: 'Band gap', checked: showBandGap, set: setShowBandGap },\n                          { label: 'kT indicator', checked: showThermalEnergy, set: setShowThermalEnergy },\n                          { label: 'Occupation f(E)', checked: showDOS, set: setShowDOS },\n                          { label: 'Animate', checked: animateCarriers, set: setAnimateCarriers },\n                        ].map((item) => (\n                          <label key={item.label} className=\"flex items-center gap-1.5 text-[11px] text-gray-600 cursor-pointer bg-gray-50 px-2 py-1 rounded-md border border-gray-100 hover:border-indigo-200 transition\">\n                            <input type=\"checkbox\" checked={item.checked} onChange={(e) => item.set(e.target.checked)} className=\"rounded\" />\n                            {item.label}\n                          </label>\n                        ))}\n                      </div>\n                    </div>\n                  </div>\n                </CollapsiblePanel>\n              </div>\n            </SimulationStage>\n\n            {/* Stats sidebar */}\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"Material\" value={mat?.symbol || 'Si'} unit=\"\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Band gap Eg\" value={liveStats.bandGap.toFixed(2)} unit=\"eV\" color=\"text-amber-600\" />\n                  <StatRow label=\"Temperature\" value={liveStats.temperature.toString()} unit=\"K\" color=\"text-rose-500\" />\n                  <StatRow label=\"Thermal kT\" value={liveStats.kT.toFixed(4)} unit=\"eV\" color=\"text-pink-500\" />\n                  <StatRow label=\"Fermi level\" value={liveStats.fermiLevel.toFixed(2)} unit=\"eV\" color=\"text-slate-700\" />\n                  <div className=\"border-t border-gray-100 my-1\" />\n                  <StatRow label=\"ni (intrinsic)\" value={liveStats.intrinsicConc.toExponential(1)} unit=\"cm⁻³\" color=\"text-emerald-600\" />\n                  <StatRow label=\"Electrons n\" value={liveStats.electronConc.toExponential(1)} unit=\"cm⁻³\" color=\"text-blue-500\" />\n                  <StatRow label=\"Holes p\" value={liveStats.holeConc.toExponential(1)} unit=\"cm⁻³\" color=\"text-purple-600\" />\n                  <StatRow label=\"Conductivity\" value={liveStats.conductivity} unit=\"\" color=\"text-cyan-600\" />\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Key Formula</p>\n                <div className=\"space-y-2 text-[10px] text-gray-600 font-mono leading-relaxed\">\n                  <p>ni = √(NcNv) · exp(−Eg/2kT)</p>\n                  <p>ni ≈ {liveStats.intrinsicConc.toExponential(1)} cm⁻³</p>\n                  <p className=\"text-gray-400\">———————</p>\n                  <p>n · p = ni²</p>\n                  <p>n = {liveStats.electronConc.toExponential(1)}</p>\n                  <p>p = {liveStats.holeConc.toExponential(1)}</p>\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map((c) => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'}`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            {/* Teacher Notes + Exercises */}\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <CollapsiblePanel title=\"Teacher Notes\" badge={materialTypeLabel(matType)} defaultOpen={true}>\n                <div className=\"space-y-3\">\n                  <div className=\"rounded-lg bg-amber-50 border border-amber-100 p-3\">\n                    <p className=\"text-xs font-semibold text-amber-800 mb-1.5\">{scenarioNote.title}</p>\n                    <ul className=\"space-y-1.5\">\n                      {scenarioNote.bullets.map((b, i) => (\n                        <li key={i} className=\"text-[11px] text-amber-900 leading-relaxed flex gap-2\">\n                          <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{b}\n                        </li>\n                      ))}\n                    </ul>\n                  </div>\n                  <div>\n                    <p className=\"text-[10px] font-medium text-gray-400 uppercase tracking-wide mb-2\">General Principles</p>\n                    <ul className=\"space-y-2\">\n                      {GENERAL_NOTES.map((n, i) => (\n                        <li key={i} className=\"text-xs text-gray-600 leading-relaxed flex gap-2\">\n                          <span className=\"text-gray-300 shrink-0 mt-0.5\">•</span>{n}\n                        </li>\n                      ))}\n                    </ul>\n                  </div>\n                </div>\n              </CollapsiblePanel>\n\n              <CollapsiblePanel title=\"Exercises\" defaultOpen={false}>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </CollapsiblePanel>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}", "src/app/simulations/mosfet/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useRef, useMemo } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { MosfetCanvas } from '@/components/simulation/MosfetCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport {\n  MosfetParams, MosfetTopology, MosfetRegion,\n  computeMosfetState,\n  getPreset,\n  PRESET_NAMES,\n  PRESET_LABELS,\n  REGION_COLORS,\n  REGION_DESCRIPTIONS,\n  TOPOLOGY_DESCRIPTIONS,\n  PRACTICE_PROBLEMS,\n} from '@/lib/physics/mosfet';\n\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700',\n  NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700',\n  SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n  'A-Level': 'bg-cyan-100 text-cyan-700',\n};\n\nconst TEACHER_NOTES = [\n  'The MOSFET is the workhorse of modern electronics — billions exist in every smartphone.',\n  'Common-Source: High voltage gain (Av = -gm·Rd), 180° phase shift. Most common amplifier topology.',\n  'Common-Drain (Source Follower): Gain ≈ 1, very high Zin, low Zout. Used as voltage buffer.',\n  'Common-Gate: Low Zin (1/gm), high gain, no Miller effect. Used in RF and high-frequency circuits.',\n  'Cutoff: Vgs < Vth — transistor is OFF. Triode: Vds < Vov — acts as voltage-controlled resistor. Saturation: Vds > Vov — used for amplification.',\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number; step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value} onChange={(e) => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function MosfetPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [activeCurricula, setActiveCurricula] = useState(['IGCSE', 'SAT', 'JUPEB', 'A-Level']);\n  const [mobileControlsOpen, setMobileControlsOpen] = useState(false);\n\n  const [activeTab, setActiveTab] = useState<'schematic' | 'cross-section' | 'characteristics' | 'analysis'>('schematic');\n  const [showElectrons, setShowElectrons] = useState(true);\n\n  const [Vgs, setVgs] = useState(2.0);\n  const [Vds, setVds] = useState(5.0);\n  const [Vth, setVth] = useState(0.7);\n  const [temperature, setTemperature] = useState(300);\n  const [type, setType] = useState<'nmos' | 'pmos'>('nmos');\n  const [W, setW] = useState(10);\n  const [L, setL] = useState(1);\n  const [tox, setTox] = useState(10);\n  const [topology, setTopology] = useState<MosfetTopology>('common-source');\n  const [Vdd, setVdd] = useState(10);\n  const [Rd, setRd] = useState(2);\n  const [Rs, setRs] = useState(0.5);\n  const [Rg, setRg] = useState(1);\n  const [Rload, setRload] = useState(10);\n\n  const params: MosfetParams = useMemo(() => ({\n    Vgs, Vds, Vth, temperature, type, W, L, tox, topology, Vdd, Rd, Rs, Rg, Rload,\n  }), [Vgs, Vds, Vth, temperature, type, W, L, tox, topology, Vdd, Rd, Rs, Rg, Rload]);\n\n  const [liveStats, setLiveStats] = useState({\n    region: 'cutoff' as MosfetRegion,\n    Id: 0, Vgs: 0, Vds: 0, Vov: 0, gm: 0, Av: 0, Zin: 0, Zout: 0, Pdiss: 0,\n  });\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((stats: typeof liveStats) => {\n    const now = performance.now();\n    if (now - lastTickRef.current < 80) return;\n    lastTickRef.current = now;\n    setLiveStats(stats);\n  }, []);\n\n  const applyPreset = useCallback((name: string) => {\n    const preset = getPreset(name);\n    setVgs(preset.Vgs);\n    setVds(preset.Vds);\n    setVth(preset.Vth);\n    setTemperature(preset.temperature);\n    setType(preset.type);\n    setW(preset.W);\n    setL(preset.L);\n    setTox(preset.tox);\n    setTopology(preset.topology);\n    setVdd(preset.Vdd);\n    setRd(preset.Rd);\n    setRs(preset.Rs);\n    setRg(preset.Rg);\n    setRload(preset.Rload);\n    setIsRunning(false);\n    setIsPaused(false);\n    setResetKey(k => k + 1);\n  }, []);\n\n  const reset = useCallback(() => {\n    setIsRunning(false);\n    setIsPaused(false);\n    setResetKey(k => k + 1);\n  }, []);\n\n  const computed = useMemo(() => computeMosfetState(params), [params]);\n\n  const topologyLabels: Record<MosfetTopology, string> = {\n    'common-source': 'Common Source',\n    'common-drain': 'Common Drain',\n    'common-gate': 'Common Gate',\n  };\n\n  useTopicPreset(\"simulations-mosfet\", { \"Vgs\": setVgs,\n    \"Vds\": setVds,\n    \"Vth\": setVth,\n    \"Vdd\": setVdd,\n    \"Rd\": setRd,\n    \"Rs\": setRs,\n    \"Rg\": setRg,\n    \"Rload\": setRload,\n    \"W\": setW,\n    \"L\": setL,\n    \"tox\": setTox,\n    \"temperature\": setTemperature }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Semiconductor Devices — MOSFET Amplifier Topologies</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">MOSFET Transistor</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {Object.keys(CC).map(c => (\n                  <button key={c} onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'}`}>\n                    {c}\n                  </button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">NMOS / PMOS — Cutoff → Triode → Saturation</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">I_d = ½·k'·(W/L)·V_ov²</span>\n          </div>\n\n          {/* Topology selector */}\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {(['common-source', 'common-drain', 'common-gate'] as MosfetTopology[]).map(t => (\n              <button key={t} onClick={() => { setTopology(t); setIsRunning(false); setResetKey(k => k + 1); }}\n                className={`shrink-0 rounded-xl border px-4 py-2 text-left hover:shadow-sm transition min-w-[140px] ${topology === t ? 'border-indigo-400 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-600 hover:border-indigo-200'}`}>\n                <p className=\"text-xs font-medium\">{topologyLabels[t]}</p>\n              </button>\n            ))}\n          </div>\n\n          {/* Presets */}\n          <div className=\"flex gap-2 overflow-x-auto pb-1\">\n            {PRESET_NAMES.map((name) => (\n              <button key={name} onClick={() => applyPreset(name)}\n                className=\"shrink-0 rounded-xl border border-gray-200 bg-white px-3 py-2 text-left hover:border-indigo-300 hover:shadow-sm transition min-w-[200px]\">\n                <p className=\"text-xs font-medium text-indigo-700\">{PRESET_LABELS[name]}</p>\n              </button>\n            ))}\n          </div>\n\n          {/* Canvas + Controls + Stats grid */}\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_240px] xl:grid-cols-[minmax(0,1fr)_240px_280px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <MosfetCanvas\n                  key={resetKey}\n                  params={params}\n                  activeTab={activeTab}\n                  isRunning={isRunning}\n                  isPaused={isPaused}\n                  showElectrons={showElectrons}\n                  onTick={handleTick}\n                />\n              </div>\n\n              {/* Tab bar */}\n              <div data-stage-role=\"parameters\" className=\"flex gap-1 rounded-lg bg-gray-100 p-1\">\n                {(['schematic', 'cross-section', 'characteristics', 'analysis'] as const).map((tab) => (\n                  <button\n                    key={tab}\n                    onClick={() => setActiveTab(tab)}\n                    className={`flex-1 rounded-md px-3 py-2 text-xs font-medium capitalize transition ${activeTab === tab ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>\n                    {tab.replace('-', ' ')}\n                  </button>\n                ))}\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls\n                  isRunning={isRunning}\n                  isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)}\n                  onReset={reset}\n                />\n                <EmbedButton\n                  path=\"/embed/mosfet\"\n                  title=\"MOSFET Transistor\"\n                  params={{\n                    Vgs, Vds, Vth, temp: temperature, type, W, L, tox, topology, Vdd, Rd, Rs, Rg, Rload,\n                    tab: activeTab, electrons: showElectrons ? 1 : 0,\n                  }}\n                />\n              </div>\n\n              {/* Mobile controls toggle */}\n              <div data-stage-role=\"parameters\"><button onClick={() => setMobileControlsOpen(o => !o)} className=\"lg:hidden w-full py-2.5 text-sm font-medium rounded-xl border border-gray-200 bg-white text-gray-700 hover:bg-gray-50 transition\">\n                {mobileControlsOpen ? 'Hide controls ▲' : 'Show controls ▼'}\n              </button></div>\n\n              <div data-stage-role=\"parameters\" className={`rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4 ${mobileControlsOpen ? '' : 'hidden lg:block'}`}>\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-indigo-600 uppercase tracking-wide\">DC Bias</p>\n                    <Slider label=\"Vgs\" unit=\"V\" value={Vgs} min={-5} max={5} step={0.1} set={setVgs} color=\"#6366f1\" note=\"Gate-source voltage\" />\n                    <Slider label=\"Vds\" unit=\"V\" value={Vds} min={-10} max={10} step={0.1} set={setVds} color=\"#ec4899\" note=\"Drain-source voltage\" />\n                    <Slider label=\"Vth\" unit=\"V\" value={Vth} min={-2} max={2} step={0.05} set={setVth} color=\"#fbbf24\" note=\"Threshold voltage\" />\n                    <Slider label=\"Vdd\" unit=\"V\" value={Vdd} min={1} max={20} step={0.5} set={setVdd} color=\"#ef4444\" note=\"Supply voltage\" />\n                  </div>\n                  <div className=\"space-y-3\">\n                    <p className=\"text-[10px] font-medium text-amber-600 uppercase tracking-wide\">Circuit</p>\n                    <Slider label=\"Rd\" unit=\"kΩ\" value={Rd} min={0.1} max={10} step={0.1} set={setRd} color=\"#f43f5e\" note=\"Drain resistor\" />\n                    <Slider label=\"Rs\" unit=\"kΩ\" value={Rs} min={0} max={5} step={0.1} set={setRs} color=\"#a78bfa\" note=\"Source resistor\" />\n                    <Slider label=\"Rg\" unit=\"MΩ\" value={Rg} min={0.01} max={10} step={0.1} set={setRg} color=\"#10b981\" note=\"Gate resistor\" />\n                    <Slider label=\"Rload\" unit=\"kΩ\" value={Rload} min={0.1} max={50} step={0.5} set={setRload} color=\"#3b82f6\" note=\"Load resistor\" />\n                  </div>\n                </div>\n\n                <div className=\"border-t border-gray-100 pt-3\">\n                  <p className=\"text-[10px] font-medium text-emerald-600 uppercase tracking-wide mb-2\">Device</p>\n                  <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                    <Slider label=\"W\" unit=\"μm\" value={W} min={0.1} max={100} step={0.5} set={setW} color=\"#10b981\" note=\"Channel width\" />\n                    <Slider label=\"L\" unit=\"μm\" value={L} min={0.05} max={10} step={0.05} set={setL} color=\"#f59e0b\" note=\"Channel length\" />\n                    <Slider label=\"tox\" unit=\"nm\" value={tox} min={1} max={50} step={0.5} set={setTox} color=\"#8b5cf6\" note=\"Oxide thickness\" />\n                    <Slider label=\"Temp\" unit=\"K\" value={temperature} min={200} max={400} step={5} set={setTemperature} color=\"#f97316\" note=\"Temperature\" />\n                  </div>\n                </div>\n\n                <div className=\"border-t border-gray-100 pt-3\">\n                  <p className=\"text-[10px] font-medium text-gray-500 uppercase tracking-wide mb-2\">Options</p>\n                  <div className=\"flex flex-wrap gap-3\">\n                    <label className=\"flex items-center gap-2 text-xs text-gray-600 cursor-pointer\">\n                      <input type=\"checkbox\" checked={showElectrons} onChange={e => setShowElectrons(e.target.checked)} className=\"rounded\" /> Show carriers\n                    </label>\n                    <div className=\"flex items-center gap-2\">\n                      <span className=\"text-xs text-gray-400\">Type:</span>\n                      <select value={type} onChange={e => setType(e.target.value as 'nmos' | 'pmos')} className=\"rounded-lg border border-gray-200 bg-white px-2 py-1 text-xs text-gray-700\">\n                        <option value=\"nmos\">NMOS</option>\n                        <option value=\"pmos\">PMOS</option>\n                      </select>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </SimulationStage>\n\n            {/* Stats panel */}\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"Region\" value={liveStats.region.toUpperCase()} unit=\"\" color={REGION_COLORS[liveStats.region].replace('#', 'text-[#') + ']'} />\n                  <StatRow label=\"Id\" value={liveStats.Id.toFixed(2)} unit=\"mA\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Vgs\" value={liveStats.Vgs.toFixed(2)} unit=\"V\" color=\"text-rose-500\" />\n                  <StatRow label=\"Vds\" value={liveStats.Vds.toFixed(2)} unit=\"V\" color=\"text-emerald-600\" />\n                  <StatRow label=\"Vov\" value={liveStats.Vov.toFixed(2)} unit=\"V\" color=\"text-amber-600\" />\n                  <StatRow label=\"gm\" value={liveStats.gm.toFixed(3)} unit=\"mS\" color=\"text-blue-500\" />\n                  <StatRow label=\"Av\" value={liveStats.Av.toFixed(2)} unit=\"V/V\" color=\"text-pink-500\" />\n                  <StatRow label=\"Zin\" value={liveStats.Zin >= 1 ? liveStats.Zin.toFixed(1) : (liveStats.Zin * 1000).toFixed(1)} unit={liveStats.Zin >= 1 ? 'MΩ' : 'kΩ'} color=\"text-purple-600\" />\n                  <StatRow label=\"Zout\" value={liveStats.Zout >= 1 ? liveStats.Zout.toFixed(1) : liveStats.Zout.toFixed(1)} unit={liveStats.Zout >= 1 ? 'kΩ' : 'Ω'} color=\"text-cyan-600\" />\n                  <StatRow label=\"Pdiss\" value={liveStats.Pdiss.toFixed(2)} unit=\"mW\" color=\"text-orange-500\" />\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Operating Regions</p>\n                <div className=\"space-y-2\">\n                  {(['cutoff', 'triode', 'saturation'] as MosfetRegion[]).map(r => (\n                    <div key={r} className=\"flex items-start gap-2\">\n                      <span className=\"mt-1 h-2 w-2 rounded-full shrink-0\" style={{ backgroundColor: REGION_COLORS[r] }} />\n                      <div>\n                        <p className=\"text-[10px] font-bold uppercase text-gray-700\">{r}</p>\n                        <p className=\"text-[10px] text-gray-400 leading-relaxed\">{REGION_DESCRIPTIONS[r]}</p>\n                      </div>\n                    </div>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Topology</p>\n                <p className=\"text-[10px] text-gray-600 leading-relaxed\">{TOPOLOGY_DESCRIPTIONS[topology]}</p>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {Object.keys(CC).map(c => <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'}`}>{c}</span>)}\n                </div>\n              </div>\n            </div>\n\n            {/* Teacher notes + Practice problems */}\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\"><span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}</li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Practice Problems</p>\n                <div className=\"space-y-2\">\n                  {PRACTICE_PROBLEMS.slice(0, 3).map((problem) => (\n                    <div key={problem.id} className=\"rounded-lg border border-gray-100 bg-gray-50 p-3\">\n                      <p className=\"text-[10px] font-bold uppercase text-indigo-600 mb-1\">{problem.topology.replace('-', ' ')}</p>\n                      <p className=\"text-xs text-gray-700 mb-1\">{problem.question}</p>\n                      <p className=\"text-[10px] text-gray-500\">{problem.find}</p>\n                      <p className=\"text-[10px] font-mono text-emerald-600 mt-1\">Ans: {problem.answer}</p>\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}", "src/app/simulations/pn-junction/page.tsx": "// src/app/simulations/pn-junction/page.tsx\n'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { TopicContext } from '@/components/explorer/TopicContext';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\n\nimport React, { useState, useCallback } from 'react';\nimport Link from 'next/link';\nimport PnJunctionCanvas from '@/components/simulation/PnJunctionCanvas';\nimport { MaterialParams, getPreset, PRESET_NAMES, PRESET_LABELS } from '@/lib/physics/pnJunction';\n\nexport default function PnJunctionPage() {\n  const [params, setParams] = useState<MaterialParams>(getPreset('equilibrium'));\n  const [activePreset, setActivePreset] = useState('equilibrium');\n\n  const applyPreset = useCallback((name: string) => {\n    setParams(getPreset(name));\n    setActivePreset(name);\n  }, []);\n\n  const updateParam = useCallback(<K extends keyof MaterialParams>(key: K, value: MaterialParams[K]) => {\n    setParams(prev => ({ ...prev, [key]: value }));\n    setActivePreset('custom');\n  }, []);\n\n  const isRectifier = params.circuitMode !== 'diode';\n\n  useTopicPreset(\"simulations-pn-junction\", { \"params.appliedBias\": (value: number) => setParams(current => ({ ...current, appliedBias: value })),\n    \"params.Vin\": (value: number) => setParams(current => ({ ...current, Vin: value })),\n    \"params.Rload\": (value: number) => setParams(current => ({ ...current, Rload: value })),\n    \"params.freq\": (value: number) => setParams(current => ({ ...current, freq: value })),\n    \"params.temperature\": (value: number) => setParams(current => ({ ...current, temperature: value })) }, {  });\n  return (\n    <div className=\"af-device min-h-screen bg-slate-950 text-slate-100 flex flex-col\">\n      <header className=\"border-b border-slate-800 bg-slate-950/80 backdrop-blur-md sticky top-0 z-50\">\n        <div className=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between\">\n          <div className=\"flex items-center gap-4\">\n            <Link href=\"/simulations\" className=\"text-slate-400 hover:text-slate-200 transition-colors text-sm font-medium\">\n              ← Simulations\n            </Link>\n            <span className=\"text-slate-600\">|</span>\n            <h1 className=\"text-lg font-semibold text-slate-100\">PN Junction & Rectification</h1>\n          </div>\n          <div className=\"flex items-center gap-3\">\n            <span className=\"text-xs px-2 py-1 rounded-full bg-blue-500/10 text-blue-400 border border-blue-500/20\">Semiconductor Devices</span>\n            <span className=\"text-xs px-2 py-1 rounded-full bg-emerald-500/10 text-emerald-400 border border-emerald-500/20\">Live</span>\n          </div>\n        </div>\n      </header>\n      <TopicContext />\n\n      <main className=\"flex-1 p-6\">\n        <div className=\"max-w-6xl mx-auto\">\n          <p className=\"text-slate-400 mb-6\">\n            Explore depletion regions, built-in potential, and rectification. Switch between diode analysis \n            and real rectifier circuits with animated AC/DC conversion, current flow, and power calculations.\n          </p>\n\n          <SimulationStage className=\"af-stage-dark grid grid-cols-1 lg:grid-cols-3 gap-6\">\n            <div data-stage-role=\"canvas\" className=\"lg:col-span-2\">\n              <PnJunctionCanvas params={params} width={900} height={600} />\n            </div>\n\n            <div data-stage-role=\"parameters\" className=\"space-y-4\">\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold mb-3 text-sm uppercase tracking-wide text-slate-400\">Circuit Mode</h3>\n                <div className=\"grid grid-cols-3 gap-2\">\n                  {(['diode', 'half-wave', 'full-wave'] as const).map(mode => (\n                    <button\n                      key={mode}\n                      onClick={() => updateParam('circuitMode', mode)}\n                      className={`px-2 py-2 rounded text-xs font-medium transition-colors ${\n                        params.circuitMode === mode\n                          ? 'bg-blue-600 text-white'\n                          : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n                      }`}\n                    >\n                      {mode === 'diode' ? 'Diode' : mode === 'half-wave' ? 'Half-Wave' : 'Full-Wave'}\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold mb-3 text-sm uppercase tracking-wide text-slate-400\">Presets</h3>\n                <div className=\"grid grid-cols-2 gap-2\">\n                  {PRESET_NAMES.map(name => (\n                    <button\n                      key={name}\n                      onClick={() => applyPreset(name)}\n                      className={`px-3 py-2 rounded text-sm font-medium transition-colors ${\n                        activePreset === name ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'\n                      }`}\n                    >\n                      {PRESET_LABELS[name]}\n                    </button>\n                  ))}\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700 space-y-4\">\n                <h3 className=\"font-semibold text-sm uppercase tracking-wide text-slate-400\">Parameters</h3>\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">Material</label>\n                  <select\n                    value={params.material}\n                    onChange={e => updateParam('material', e.target.value as MaterialParams['material'])}\n                    className=\"w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-sm\"\n                  >\n                    <option value=\"Si\">Silicon (Si) — Vf ≈ 0.7V</option>\n                    <option value=\"Ge\">Germanium (Ge) — Vf ≈ 0.3V</option>\n                    <option value=\"GaAs\">GaAs — Vf ≈ 1.2V</option>\n                  </select>\n                </div>\n\n                {!isRectifier && (\n                  <>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        P-side Doping (Na): {params.Na.toExponential(1)} cm⁻³\n                      </label>\n                      <input type=\"range\" min=\"14\" max=\"19\" step=\"0.5\"\n                        value={Math.log10(params.Na)}\n                        onChange={e => updateParam('Na', Math.pow(10, parseFloat(e.target.value)))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        N-side Doping (Nd): {params.Nd.toExponential(1)} cm⁻³\n                      </label>\n                      <input type=\"range\" min=\"14\" max=\"19\" step=\"0.5\"\n                        value={Math.log10(params.Nd)}\n                        onChange={e => updateParam('Nd', Math.pow(10, parseFloat(e.target.value)))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        Applied Bias: {params.appliedBias >= 0 ? '+' : ''}{params.appliedBias.toFixed(2)} V\n                      </label>\n                      <input type=\"range\" min=\"-10\" max=\"1\" step=\"0.05\"\n                        value={params.appliedBias}\n                        onChange={e => updateParam('appliedBias', parseFloat(e.target.value))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                  </>\n                )}\n\n                {isRectifier && (\n                  <>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        AC Input (Vpeak): {params.Vin} V\n                      </label>\n                      <input type=\"range\" min=\"2\" max=\"20\" step=\"0.5\"\n                        value={params.Vin}\n                        onChange={e => updateParam('Vin', parseFloat(e.target.value))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        Load Resistance: {params.Rload} Ω\n                      </label>\n                      <input type=\"range\" min=\"100\" max=\"10000\" step=\"100\"\n                        value={params.Rload}\n                        onChange={e => updateParam('Rload', parseInt(e.target.value))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                    <div>\n                      <label className=\"block text-sm text-slate-400 mb-1\">\n                        Frequency: {params.freq} Hz\n                      </label>\n                      <input type=\"range\" min=\"10\" max=\"100\" step=\"5\"\n                        value={params.freq}\n                        onChange={e => updateParam('freq', parseInt(e.target.value))}\n                        className=\"w-full accent-blue-500\" />\n                    </div>\n                  </>\n                )}\n\n                <div>\n                  <label className=\"block text-sm text-slate-400 mb-1\">\n                    Temperature: {params.temperature} K\n                  </label>\n                  <input type=\"range\" min=\"100\" max=\"600\" step=\"10\"\n                    value={params.temperature}\n                    onChange={e => updateParam('temperature', parseInt(e.target.value))}\n                    className=\"w-full accent-blue-500\" />\n                </div>\n              </div>\n\n              <div className=\"bg-slate-900 rounded-lg p-4 border border-slate-700\">\n                <h3 className=\"font-semibold text-sm uppercase tracking-wide text-slate-400 mb-2\">Teacher Notes</h3>\n                <div className=\"text-sm text-slate-300 space-y-2\">\n                  {!isRectifier && params.appliedBias === 0 && (\n                    <p><strong>Equilibrium:</strong> At zero bias, diffusion and drift currents balance. The depletion region forms as ionized donors/acceptors create a space charge. Built-in potential Vbi = (kT/q) ln(Na·Nd/ni²).</p>\n                  )}\n                  {!isRectifier && params.appliedBias > 0 && (\n                    <p><strong>Forward Bias:</strong> Reducing the barrier allows majority carriers to diffuse. Current follows Shockley: I = Is(e^(V/nVT) - 1). For Si, significant current flows above ~0.7V.</p>\n                  )}\n                  {!isRectifier && params.appliedBias < 0 && (\n                    <p><strong>Reverse Bias:</strong> Barrier increases, depletion widens. Only minority carriers contribute — tiny saturation current until avalanche breakdown at high reverse voltage.</p>\n                  )}\n                  {params.circuitMode === 'half-wave' && (\n                    <>\n                      <p><strong>Half-Wave Rectifier:</strong> Only positive half-cycles pass. One diode + load resistor. Vdc = (Vpeak - Vf)/π. Efficiency ≈ 40.6%. High ripple (121%).</p>\n                      <div className=\"mt-2 p-2 bg-slate-800 rounded border border-slate-700\">\n                        <p className=\"text-yellow-400 font-medium text-xs uppercase mb-1\">Practice Problem</p>\n                        <p className=\"text-xs\">A half-wave rectifier has Vpeak = 10V, Rload = 1kΩ, Si diode. Calculate: (a) DC output voltage, (b) DC load current, (c) PIV rating needed.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Answers: (a) 2.96V, (b) 2.96mA, (c) 10V</p>\n                      </div>\n                    </>\n                  )}\n                  {params.circuitMode === 'full-wave' && (\n                    <>\n                      <p><strong>Full-Wave Bridge:</strong> 4 diodes conduct both half-cycles. Vdc = 2(Vpeak - Vf)/π. Efficiency ≈ 81.2%. Lower ripple (48%). No center-tapped transformer needed.</p>\n                      <div className=\"mt-2 p-2 bg-slate-800 rounded border border-slate-700\">\n                        <p className=\"text-yellow-400 font-medium text-xs uppercase mb-1\">Practice Problem</p>\n                        <p className=\"text-xs\">A bridge rectifier has Vpeak = 10V, Rload = 1kΩ, Si diodes. Calculate: (a) DC output voltage, (b) Total diode power loss, (c) Efficiency.</p>\n                        <p className=\"text-xs text-slate-500 mt-1\">Answers: (a) 5.91V, (b) 16.6mW, (c) ~81%</p>\n                      </div>\n                    </>\n                  )}\n                  {params.material !== 'Si' && (\n                    <p><strong>Material Effect:</strong> {params.material} has Vf ≈ {params.material === 'Ge' ? '0.3V' : '1.2V'}, affecting rectifier efficiency and output voltage.</p>\n                  )}\n                </div>\n              </div>\n            </div>\n          </SimulationStage>\n        </div>\n      </main>\n\n      <footer className=\"border-t border-slate-800 bg-slate-950 py-6\">\n        <div className=\"max-w-6xl mx-auto px-6 flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <p className=\"text-sm text-slate-500\">PN Junction Simulation — Semiconductor Physics Engine</p>\n          <div className=\"flex items-center gap-4 text-sm text-slate-500\">\n            <Link href=\"/simulations\" className=\"hover:text-slate-300 transition-colors\">All Simulations</Link>\n            <Link href=\"/simulations/band-theory\" className=\"hover:text-slate-300 transition-colors\">← Band Theory</Link>\n            <Link href=\"/simulations/bjt-transistor\" className=\"hover:text-slate-300 transition-colors\">BJT →</Link>\n          </div>\n        </div>\n      </footer>\n    </div>\n  );\n}", "src/app/simulations/space/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useEffect, useRef, useState } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { SpaceCanvas, POINT_COLORS, type Activity } from '@/components/simulation/SpaceCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport {\n  type Dim, type P3, type View, DEFAULT_VIEW, JOURNEY_PRESETS, LABELS, MAX_POINTS, P, RANGE, analyseJourney, checkAnswer, clampDim,\n  clampTo, coordText, distanceWorking, fmt, len, octant, quadrant, randomTarget,\n} from '@/lib/physics/space';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = { WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700', IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700', JUPEB: 'bg-purple-100 text-purple-700' };\nconst DIMS: { id: Dim; title: string; icon: string; sub: string }[] = [\n  { id: '1d', title: '1D · Line', icon: '📏', sub: 'One number locates a point: x' },\n  { id: '2d', title: '2D · Plane', icon: '🗺️', sub: 'Two numbers locate a point: (x, y)' },\n  { id: '3d', title: '3D · Space', icon: '🧊', sub: 'Three numbers locate a point: (x, y, z)' },\n];\nconst ACTS: { id: Activity; title: string; icon: string }[] = [\n  { id: 'locate', title: 'Locate a point', icon: '📍' }, { id: 'journey', title: 'Distance & displacement', icon: '🧭' }, { id: 'practice', title: 'Practice', icon: '🎯' },\n];\nconst VIEWS: { label: string; v: View }[] = [\n  { label: 'Default', v: DEFAULT_VIEW }, { label: 'Top (xy)', v: { yaw: 0, pitch: (85 * Math.PI) / 180 } },\n  { label: 'Front (xz)', v: { yaw: -Math.PI / 2, pitch: (6 * Math.PI) / 180 } }, { label: 'Side (yz)', v: { yaw: 0, pitch: (6 * Math.PI) / 180 } },\n];\n\nconst NOTES: Record<Dim, string[]> = {\n  '1d': [\n    'Position is a signed number: its sign tells you the side of the origin, its size tells you how far.',\n    'Always say where the origin is and which way is positive before you calculate anything.',\n    'Distance is a scalar (path length, never negative). Displacement is a vector: Δx = x_final − x_initial, and its sign is its direction.',\n    'Reversing direction adds to the distance but subtracts from the displacement. A round trip has displacement zero.',\n  ],\n  '2d': [\n    'An ordered pair (x, y): x is read first (horizontal), then y (vertical). (3, 4) and (4, 3) are different points.',\n    'The signs of x and y give the quadrant: I (+,+), II (−,+), III (−,−), IV (+,−).',\n    'The distance between two points is Pythagoras on the differences: d = √(Δx² + Δy²). Δx and Δy are the legs of a right triangle.',\n    'Direction: θ is measured counter-clockwise from +x, but exams often use a bearing (clockwise from north). Bearing = 90° − θ (add 360° if negative).',\n  ],\n  '3d': [\n    'Three numbers locate a point in space: walk x along the X axis, then y parallel to Y, then z parallel to Z. The order does not matter.',\n    'The axes are right-handed: point the fingers of your right hand along +X, curl them towards +Y, and your thumb points along +Z.',\n    'A point’s distance from a coordinate plane is the absolute value of the one coordinate that plane does not contain: |z| from the xy-plane, |x| from the yz-plane, |y| from the xz-plane.',\n    'The distance between two points extends Pythagoras to three terms: d = √(Δx² + Δy² + Δz²). Rotate the view to see the right triangles inside the box.',\n  ],\n};\nconst EXERCISES: Record<Dim, { q: string; a: string }[]> = {\n  '1d': [\n    { q: 'A runner starts at x = 2 m, runs to x = 9 m, then back to x = 4 m. Find the distance and the displacement.', a: 'Distance = 7 + 5 = 12 m. Displacement = 4 − 2 = +2 m (2 m in the +x direction).' },\n    { q: 'A lift starts at +15 m (5th floor) and stops at −6 m (basement), with the upward direction positive. Find the distance and displacement.', a: 'Distance = 21 m. Displacement = −6 − 15 = −21 m, i.e. 21 m downward.' },\n    { q: 'Can the distance travelled ever be less than the magnitude of the displacement?', a: 'No. Distance ≥ |displacement|, with equality only for motion in a straight line without reversing.' },\n  ],\n  '2d': [\n    { q: 'A walks from (1, 2) to (4, 6). Find the distance and the direction of the displacement.', a: 'Δ = (3, 4), so d = √(9 + 16) = 5. Direction: tan⁻¹(4/3) = 53.1° north of east (θ = 53.1°, bearing 036.9°).' },\n    { q: 'A student walks 3 m east, 4 m north, then 3 m west. Find the distance and the displacement.', a: 'Distance = 3 + 4 + 3 = 10 m. Displacement = (0, 4): 4 m due north.' },\n    { q: 'Point P is at (−3, −4). Which quadrant is it in, how far is it from the origin, and what is the bearing of P from the origin?', a: 'Quadrant III. Distance = √(9 + 16) = 5. θ = 233.1° from +x, so the bearing is 90° − 233.1° + 360° = 216.9° (53.1° south of west).' },\n  ],\n  '3d': [\n    { q: 'P is at (2, 3, 6). Find its distance from the origin, and from each coordinate plane.', a: 'OP = √(4 + 9 + 36) = 7. From the xy-plane: |z| = 6. From the yz-plane: |x| = 2. From the xz-plane: |y| = 3.' },\n    { q: 'A = (1, −2, 0) and B = (3, 1, 6). Find the distance AB.', a: 'Δ = (2, 3, 6), so AB = √(4 + 9 + 36) = 7.' },\n    { q: 'A drone flies from the origin 2 m along x, then 3 m along y, then 6 m up z. Find the distance flown and the displacement magnitude.', a: 'Distance = 2 + 3 + 6 = 11 m. Displacement = (2, 3, 6), magnitude √49 = 7 m.' },\n  ],\n};\n\nconst initialLocate: Record<Dim, P3> = { '1d': P(3), '2d': P(3, 4), '3d': P(3, 2, 4) };\nconst initialJourney = (): Record<Dim, P3[]> => ({ '1d': JOURNEY_PRESETS['1d'][0].points, '2d': JOURNEY_PRESETS['2d'][0].points, '3d': JOURNEY_PRESETS['3d'][0].points });\n\nfunction NumField({ label, value, onCommit, min, max, color }: { label: string; value: number; onCommit: (v: number) => void; min: number; max: number; color: string }) {\n  const [text, setText] = useState<string | null>(null);\n  return (\n    <label className=\"flex flex-1 items-center gap-1.5 text-xs\">\n      <span className=\"font-semibold\" style={{ color }}>{label}</span>\n      <input type=\"number\" inputMode=\"decimal\" step=\"any\" min={min} max={max} aria-label={label}\n        value={text ?? String(value)}\n        onChange={e => { setText(e.target.value); const v = Number(e.target.value); if (e.target.value !== '' && e.target.value !== '-' && Number.isFinite(v)) onCommit(clampTo(v, max)); }}\n        onBlur={() => setText(null)}\n        className=\"h-8 w-full min-w-0 rounded-md border border-gray-200 bg-white px-2 text-sm tabular-nums\" />\n    </label>\n  );\n}\n\nconst Stat = ({ k, v, c = 'text-gray-900' }: { k: string; v: React.ReactNode; c?: string }) => (\n  <div className=\"flex items-center justify-between gap-3 rounded-lg bg-gray-50 px-3 py-2\"><span className=\"text-xs text-gray-500\">{k}</span><span className={`text-right text-sm font-semibold tabular-nums ${c}`}>{v}</span></div>\n);\nconst Toggle = ({ label, on, set }: { label: string; on: boolean; set: (v: boolean) => void }) => (\n  <label className=\"flex items-center gap-1.5 text-xs text-gray-600\"><input type=\"checkbox\" checked={on} onChange={e => set(e.target.checked)} />{label}</label>\n);\n\nfunction walkText(step: number, p: P3, dim: Dim): string {\n  const dir = (v: number, axis: string) => `${fmt(Math.abs(v))} unit${Math.abs(v) === 1 ? '' : 's'} ${v >= 0 ? 'along +' : 'along −'}${axis}`;\n  if (step === 0) return 'Start at the origin O, where every coordinate is 0. Press Step to walk to the point.';\n  if (step === 1) return `Step 1 — move ${dir(p.x, 'X')} (x = ${fmt(p.x)}). You are now at (${fmt(p.x)}, 0${dim === '3d' ? ', 0' : ''}).`;\n  if (step === 2) return dim === '2d' ? `Step 2 — from there move ${dir(p.y, 'Y')} (y = ${fmt(p.y)}), parallel to the y-axis. You have arrived at ${coordText(p, dim)}.` : `Step 2 — now move ${dir(p.y, 'Y')} (y = ${fmt(p.y)}), parallel to the Y axis. You are at (${fmt(p.x)}, ${fmt(p.y)}, 0), directly ${p.z >= 0 ? 'below' : 'above'} the point.`;\n  return `Step 3 — finally move ${dir(p.z, 'Z')} (z = ${fmt(p.z)}), parallel to the Z axis. You have arrived at ${coordText(p, dim)}.`;\n}\n\nexport default function SpacePage() {\n  const [dim, setDim] = useState<Dim>('3d');\n  const [act, setAct] = useState<Activity>('locate');\n  const [locate, setLocate] = useState<Record<Dim, P3>>(initialLocate);\n  const [journey, setJourney] = useState<Record<Dim, P3[]>>(initialJourney);\n  const [sel, setSel] = useState(0);\n  const [snap, setSnap] = useState(1);\n  const [view, setView] = useState<View>(DEFAULT_VIEW);\n  const [dragAxis, setDragAxis] = useState<'floor' | 'height'>('floor');\n  const [planes, setPlanes] = useState(true); const [grid, setGrid] = useState(true); const [guides, setGuides] = useState(true); const [comps, setComps] = useState(true);\n  const [walk, setWalk] = useState<number | undefined>(undefined);\n  const [playing, setPlaying] = useState(false);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [curr, setCurr] = useState(['WAEC', 'IGCSE', 'SAT']);\n  // practice\n  const [pKind, setPKind] = useState<'place' | 'read'>('place');\n  const [target, setTarget] = useState<P3 | null>(null);\n  const [place, setPlace] = useState<Record<Dim, P3>>({ '1d': P(0), '2d': P(0, 0), '3d': P(0, 0, 0) });\n  const [typed, setTyped] = useState({ x: '', y: '', z: '' });\n  const [result, setResult] = useState<{ correct: boolean; hints: string[] } | null>(null);\n  const [score, setScore] = useState({ right: 0, tries: 0 });\n\n  const boxRef = useRef<HTMLDivElement>(null);\n  const size = useResponsiveCanvasSize(boxRef, 660, dim === '3d' ? 440 : 400, 900);\n  // Narrow screens: a wide, short canvas would shrink the 2D/3D figures and clip the planes, so make them near-square.\n  const compact = size.width < 560;\n  const canvasH = compact ? Math.round(size.width * (dim === '1d' ? 0.62 : 1.0)) : size.height;\n  const R = RANGE[dim];\n  const readMode = act === 'practice' && pKind === 'read';\n\n  // Auto-play for the guided walk: each tick is a timeout scheduled from the current step.\n  useEffect(() => {\n    if (!playing) return;\n    const max = dim === '3d' ? 3 : 2, w = walk ?? 0;\n    const id = setTimeout(() => { if (w >= max) setPlaying(false); else setWalk(w + 1); }, w >= max ? 0 : 1100);\n    return () => clearTimeout(id);\n  }, [playing, walk, dim]);\n\n  const newChallenge = (kind = pKind, d = dim) => { setTarget(randomTarget(d)); setTyped({ x: '', y: '', z: '' }); setResult(null); setPlace(p => ({ ...p, [d]: P(0, 0, 0) })); setPKind(kind); };\n  const changeDim = (d: Dim) => { setDim(d); setSel(0); setWalk(undefined); setPlaying(false); setResult(null); if (act === 'practice') newChallenge(pKind, d); };\n  const changeAct = (a: Activity) => { setAct(a); setSel(0); setWalk(undefined); setPlaying(false); setResult(null); if (a === 'practice' && !target) newChallenge(pKind, dim); };\n\n  const shown: P3[] = act === 'locate' ? [locate[dim]] : act === 'journey' ? journey[dim] : readMode ? [target ?? P()] : [place[dim]];\n  const moveShown = (i: number, p: P3) => {\n    if (act === 'locate') setLocate(s => ({ ...s, [dim]: p }));\n    else if (act === 'journey') setJourney(s => ({ ...s, [dim]: s[dim].map((q, k) => (k === i ? p : q)) }));\n    else if (!readMode) setPlace(s => ({ ...s, [dim]: p }));\n    setWalk(undefined); setResult(null);\n  };\n  const J = analyseJourney(journey[dim], dim);\n  const p = locate[dim];\n  const first = journey[dim][0], last = journey[dim][journey[dim].length - 1];\n\n  const check = () => {\n    if (!target) return;\n    const ans = pKind === 'place' ? clampDim(place[dim], dim) : clampDim(P(Number(typed.x), Number(typed.y || 0), Number(typed.z || 0)), dim);\n    const bad = pKind === 'read' && [typed.x, dim !== '1d' ? typed.y : '0', dim === '3d' ? typed.z : '0'].some(v => v === '' || !Number.isFinite(Number(v)));\n    if (bad) { setResult({ correct: false, hints: ['Fill in every coordinate first.'] }); return; }\n    const r = checkAnswer(target, ans, dim, 0.01);\n    setResult(r); setScore(s => ({ right: s.right + (r.correct ? 1 : 0), tries: s.tries + 1 }));\n  };\n\n  const dimMeta = DIMS.find(d => d.id === dim)!;\n  const fields: ('x' | 'y' | 'z')[] = dim === '1d' ? ['x'] : dim === '2d' ? ['x', 'y'] : ['x', 'y', 'z'];\n  const axisColor = { x: '#dc2626', y: '#16a34a', z: '#2563eb' };\n  const walkMax = dim === '3d' ? 3 : 2;\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 py-4 sm:px-6\">\n            <div className=\"flex flex-col justify-between gap-3 sm:flex-row sm:items-center\">\n              <div><p className=\"mb-0.5 text-xs text-gray-400\">Space and time</p><h1 className=\"text-lg font-semibold text-gray-900\">Space: position, distance &amp; displacement</h1></div>\n              <div className=\"flex flex-wrap gap-1.5\">\n                {CURRICULA.map(c => <button key={c} onClick={() => setCurr(s => (s.includes(c) ? s.filter(x => x !== c) : [...s, c]))} className={`rounded-full border px-2.5 py-2 text-xs font-medium transition ${curr.includes(c) ? CC[c] + ' border-transparent' : 'border-gray-200 bg-white text-gray-400'}`}>{c}</button>)}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] space-y-4 px-4 py-4 sm:px-6\">\n          <div className=\"flex gap-1 overflow-x-auto rounded-xl bg-gray-100 p-1\" role=\"tablist\" aria-label=\"Number of dimensions\">\n            {DIMS.map(d => <button key={d.id} role=\"tab\" aria-selected={dim === d.id} onClick={() => changeDim(d.id)} className={`flex shrink-0 items-center gap-1.5 rounded-lg px-3 py-2 text-xs font-medium transition ${dim === d.id ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}><span>{d.icon}</span>{d.title}</button>)}\n          </div>\n          <div className=\"flex flex-wrap items-center gap-2\">\n            <div className=\"flex gap-1 overflow-x-auto\" role=\"tablist\" aria-label=\"Activity\">\n              {ACTS.map(a => <button key={a.id} role=\"tab\" aria-selected={act === a.id} onClick={() => changeAct(a.id)} className={`shrink-0 rounded-full border px-3 py-1.5 text-xs font-medium transition ${act === a.id ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 bg-white text-gray-600 hover:border-indigo-300'}`}>{a.icon} {a.title}</button>)}\n            </div>\n            <span className=\"text-xs text-gray-500\">{dimMeta.sub}</span>\n            {act === 'journey' && <span className=\"rounded-lg border border-gray-200 bg-white px-2.5 py-2 font-mono text-xs text-gray-700\">{dim === '1d' ? 'Δx = x₂ − x₁' : dim === '2d' ? 'd = √(Δx² + Δy²)' : 'd = √(Δx² + Δy² + Δz²)'}</span>}\n          </div>\n\n          <div className=\"grid grid-cols-1 gap-4 lg:grid-cols-[minmax(0,1fr)_300px] xl:grid-cols-[minmax(0,1fr)_300px_280px]\">\n            {/* Canvas + controls */}\n            <SimulationStage className=\"min-w-0 space-y-3\">\n              <div data-stage-role=\"canvas\" ref={boxRef} className=\"overflow-hidden rounded-2xl border border-gray-200 bg-white p-2 shadow-sm\">\n                <SpaceCanvas\n                  dim={dim} activity={act} width={size.width} height={canvasH}\n                  points={shown} labels={readMode ? ['P'] : act === 'practice' ? ['P'] : act === 'locate' ? ['P'] : LABELS}\n                  selected={Math.min(sel, shown.length - 1)} onMove={moveShown} onSelect={setSel} snap={snap} view={view} onView={setView} dragAxis={dragAxis}\n                  showPlanes={planes} showGrid={grid} showGuides={guides} showComponents={comps}\n                  readOnly={readMode} hideCoords={readMode} walk={act === 'locate' && dim !== '1d' ? walk : undefined}\n                />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"flex flex-wrap items-center gap-x-4 gap-y-2 rounded-xl border border-gray-200 bg-white px-3 py-2.5\">\n                <label className=\"flex items-center gap-1.5 text-xs text-gray-600\">Snap\n                  <select value={snap} onChange={e => setSnap(Number(e.target.value))} className=\"h-7 rounded-md border border-gray-200 bg-white px-1.5 text-xs\">\n                    <option value={1}>whole numbers</option><option value={0.5}>0.5</option><option value={0}>0.1 (free)</option>\n                  </select>\n                </label>\n                {dim === '3d' && <>\n                  <div className=\"flex items-center gap-1.5 text-xs text-gray-600\">Drag point\n                    <div className=\"flex overflow-hidden rounded-md border border-gray-200\">\n                      {(['floor', 'height'] as const).map(m => <button key={m} onClick={() => setDragAxis(m)} aria-pressed={dragAxis === m} className={`px-2 py-1 text-xs ${dragAxis === m ? 'bg-indigo-600 text-white' : 'bg-white text-gray-600'}`}>{m === 'floor' ? 'across floor (x, y)' : 'up / down (z)'}</button>)}\n                    </div>\n                  </div>\n                  <Toggle label=\"Planes\" on={planes} set={setPlanes} />\n                  <Toggle label=\"Floor grid\" on={grid} set={setGrid} />\n                </>}\n                {dim === '2d' && <Toggle label=\"Grid\" on={grid} set={setGrid} />}\n                {act === 'locate' && <Toggle label={dim === '3d' ? 'Box & projection lines' : 'Guide lines'} on={guides} set={setGuides} />}\n                {act === 'journey' && <><Toggle label=\"Components\" on={comps} set={setComps} />{dim === '3d' && <Toggle label=\"Drop lines\" on={guides} set={setGuides} />}</>}\n                <div className=\"ml-auto\"><EmbedButton path=\"/embed/space\" title=\"Space — A-Factor STEM Studio\" params={{ dim, act: act === 'journey' ? 'journey' : 'locate', pts: (act === 'journey' ? journey[dim] : [locate[dim]]).map(q => `${q.x},${q.y},${q.z}`).join(';') }} /></div>\n              </div>\n              <div data-stage-role=\"parameters\">{dim === '3d' && (\n                <div className=\"flex flex-wrap items-center gap-1.5\">\n                  <span className=\"text-xs text-gray-500\">View</span>\n                  {VIEWS.map(v => <button key={v.label} onClick={() => setView(v.v)} className=\"rounded-md border border-gray-200 bg-white px-2.5 py-1 text-xs text-gray-600 hover:border-indigo-300 hover:text-indigo-700\">{v.label}</button>)}\n                  <span className=\"text-[11px] text-gray-400\">Drag empty space to rotate · drag a point to move it · arrow keys and Page Up/Down also work</span>\n                </div>\n              )}</div>\n              <div data-stage-role=\"extra\">{dim !== '3d' && <p className=\"text-[11px] text-gray-400\">Drag a point to move it, or select it and use the arrow keys. Axes run from −{R} to +{R}.</p>}</div>\n            </SimulationStage>\n\n            {/* Parameters + readouts */}\n            <div className=\"space-y-3\">\n              {act === 'locate' && (\n                <>\n                  <div className=\"space-y-3 rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                    <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Point P</p>\n                    <div className=\"flex gap-2\">{fields.map(k => <NumField key={k} label={k} value={p[k]} min={-R} max={R} color={axisColor[k]} onCommit={v => { setLocate(s => ({ ...s, [dim]: { ...s[dim], [k]: v } })); setWalk(undefined); }} />)}</div>\n                    {fields.map(k => (\n                      <input key={k} type=\"range\" min={-R} max={R} step={snap || 0.1} value={p[k]} aria-label={`${k} slider`} onChange={e => { setLocate(s => ({ ...s, [dim]: { ...s[dim], [k]: Number(e.target.value) } })); setWalk(undefined); }} className=\"w-full\" style={{ accentColor: axisColor[k] }} />\n                    ))}\n                  </div>\n                  <div className=\"space-y-2 rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                    <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Where is it?</p>\n                    <Stat k=\"Position\" v={coordText(p, dim)} c=\"text-red-600\" />\n                    {dim === '1d' && <Stat k=\"Side of origin\" v={p.x === 0 ? 'at O' : p.x > 0 ? 'right (+x)' : 'left (−x)'} />}\n                    {dim === '1d' && <Stat k=\"Distance from O\" v={`${fmt(Math.abs(p.x))}`} c=\"text-indigo-600\" />}\n                    {dim === '2d' && <><Stat k=\"Quadrant\" v={quadrant(p)} /><Stat k=\"Distance from O\" v={fmt(len(p))} c=\"text-indigo-600\" /><Stat k=\"Foot on x-axis\" v={`(${fmt(p.x)}, 0)`} /><Stat k=\"Foot on y-axis\" v={`(0, ${fmt(p.y)})`} /></>}\n                    {dim === '3d' && <><Stat k=\"Signs\" v={octant(p).replace('signs (x, y, z) = ', '')} /><Stat k=\"Distance from O\" v={fmt(len(p))} c=\"text-indigo-600\" /><Stat k=\"From xy-plane (|z|)\" v={fmt(Math.abs(p.z))} /><Stat k=\"From yz-plane (|x|)\" v={fmt(Math.abs(p.x))} /><Stat k=\"From xz-plane (|y|)\" v={fmt(Math.abs(p.y))} /><Stat k=\"Foot on xy-plane\" v={`(${fmt(p.x)}, ${fmt(p.y)}, 0)`} /></>}\n                  </div>\n                  {dim !== '1d' && (\n                    <div className=\"rounded-2xl border border-indigo-100 bg-indigo-50 p-4\">\n                      <p className=\"mb-2 text-xs font-medium uppercase tracking-wide text-indigo-400\">Walk to the point</p>\n                      <p className=\"mb-3 min-h-[3.5rem] text-xs leading-relaxed text-indigo-900\" aria-live=\"polite\">{walk === undefined ? 'Press Step to follow the route from the origin, one axis at a time.' : walkText(walk, p, dim)}</p>\n                      <div className=\"flex flex-wrap gap-2\">\n                        <button onClick={() => { setPlaying(false); setWalk(w => (w === undefined ? 1 : w >= walkMax ? 0 : w + 1)); }} className=\"rounded-lg bg-indigo-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-indigo-700\">{walk !== undefined && walk >= walkMax ? 'Restart' : 'Step ▸'}</button>\n                        <button onClick={() => { setWalk(0); setPlaying(true); }} className=\"rounded-lg border border-indigo-200 bg-white px-3 py-1.5 text-xs font-medium text-indigo-700\">Play</button>\n                        <button onClick={() => { setPlaying(false); setWalk(undefined); }} className=\"rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-xs text-gray-600\">Show all</button>\n                      </div>\n                    </div>\n                  )}\n                </>\n              )}\n\n              {act === 'journey' && (\n                <>\n                  <div className=\"space-y-3 rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                    <div className=\"flex items-center justify-between\"><p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Journey points</p><span className=\"text-[11px] text-gray-400\">A → … → {LABELS[journey[dim].length - 1]}</span></div>\n                    {journey[dim].map((q, i) => (\n                      <div key={i} onClick={() => setSel(i)} className={`rounded-xl border p-2 ${sel === i ? 'border-indigo-300 bg-indigo-50/40' : 'border-gray-100'}`}>\n                        <div className=\"mb-1.5 flex items-center justify-between\"><span className=\"text-xs font-semibold\" style={{ color: POINT_COLORS[i % 5] }}>{LABELS[i]}{i === 0 ? ' (start)' : i === journey[dim].length - 1 ? ' (end)' : ''}</span>\n                          {journey[dim].length > 2 && <button onClick={e => { e.stopPropagation(); setJourney(s => ({ ...s, [dim]: s[dim].filter((_, k) => k !== i) })); setSel(0); }} className=\"text-[11px] text-gray-400 hover:text-red-600\" aria-label={`Remove point ${LABELS[i]}`}>Remove</button>}</div>\n                        <div className=\"flex gap-1.5\">{fields.map(k => <NumField key={k} label={k} value={q[k]} min={-R} max={R} color={axisColor[k]} onCommit={v => setJourney(s => ({ ...s, [dim]: s[dim].map((pp, kk) => (kk === i ? { ...pp, [k]: v } : pp)) }))} />)}</div>\n                      </div>\n                    ))}\n                    <div className=\"flex flex-wrap gap-2\">\n                      <button disabled={journey[dim].length >= MAX_POINTS} onClick={() => setJourney(s => { const l = s[dim][s[dim].length - 1]; return { ...s, [dim]: [...s[dim], clampDim(P(clampTo(l.x + 2, R), clampTo(l.y + 1, R), clampTo(l.z + 1, R)), dim)] }; })} className=\"rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-xs text-gray-700 enabled:hover:border-indigo-300 disabled:opacity-40\">+ Add point</button>\n                    </div>\n                    <div className=\"flex flex-wrap gap-1.5\">{JOURNEY_PRESETS[dim].map(pr => <button key={pr.label} onClick={() => { setJourney(s => ({ ...s, [dim]: pr.points })); setSel(0); }} title={pr.note} className=\"rounded-full border border-gray-200 bg-white px-2.5 py-1 text-[11px] text-gray-700 hover:border-indigo-300 hover:text-indigo-700\">{pr.label}</button>)}</div>\n                  </div>\n\n                  <div className=\"space-y-2 rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                    <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Results</p>\n                    <Stat k=\"Distance (path length)\" v={`${fmt(J.distance)}`} c=\"text-indigo-600\" />\n                    <Stat k=\"Displacement\" v={dim === '1d' ? `${J.displacement.x >= 0 ? '+' : '−'}${fmt(Math.abs(J.displacement.x))}` : coordText(J.displacement, dim).replace('x = ', '')} c=\"text-rose-600\" />\n                    <Stat k=\"|Displacement|\" v={fmt(J.magnitude)} c=\"text-rose-600\" />\n                    <div className=\"rounded-lg bg-rose-50 px-3 py-2 text-xs leading-relaxed text-rose-900\"><span className=\"font-medium\">Direction: </span>{J.direction.text}{J.direction.bearing !== undefined && <> · bearing {fmt(J.direction.bearing, 1)}°</>}{J.direction.axisAngles && <> · angles with x, y, z axes: {fmt(J.direction.axisAngles.x, 1)}°, {fmt(J.direction.axisAngles.y, 1)}°, {fmt(J.direction.axisAngles.z, 1)}°</>}</div>\n                    <div className={`rounded-lg px-3 py-2 text-xs leading-relaxed ${J.straight ? 'bg-emerald-50 text-emerald-900' : 'bg-amber-50 text-amber-900'}`}>\n                      {J.straight ? 'Distance equals the magnitude of the displacement: the path is a straight line with no reversal.' : `The path is ${fmt(J.distance - J.magnitude)} longer than the straight-line displacement. Distance ≥ |displacement| always.`}\n                    </div>\n                  </div>\n\n                  <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                    <p className=\"mb-2 text-xs font-medium uppercase tracking-wide text-gray-400\">Working: {LABELS[0]} → {LABELS[journey[dim].length - 1]}</p>\n                    <p className=\"font-mono text-[11px] leading-relaxed text-gray-700\">{distanceWorking(first, last, dim)}</p>\n                    <div className=\"mt-3 overflow-x-auto\"><table className=\"w-full min-w-[220px] text-left text-xs\">\n                      <thead className=\"text-[10px] uppercase tracking-wide text-gray-400\"><tr><th className=\"py-1 font-medium\">Leg</th><th className=\"font-medium\">Δ</th><th className=\"text-right font-medium\">Length</th></tr></thead>\n                      <tbody>{J.legs.map((l, i) => <tr key={i} className=\"border-t border-gray-100\"><td className=\"py-1.5 font-semibold\" style={{ color: POINT_COLORS[(i + 1) % 5] }}>{LABELS[i]}→{LABELS[i + 1]}</td><td className=\"tabular-nums text-gray-700\">{dim === '1d' ? `${l.delta.x >= 0 ? '+' : '−'}${fmt(Math.abs(l.delta.x))}` : coordText(l.delta, dim)}</td><td className=\"text-right tabular-nums text-gray-900\">{fmt(l.length)}</td></tr>)}\n                        <tr className=\"border-t-2 border-gray-200 font-semibold\"><td className=\"py-1.5\">Total</td><td /><td className=\"text-right tabular-nums text-indigo-600\">{fmt(J.distance)}</td></tr></tbody>\n                    </table></div>\n                  </div>\n                </>\n              )}\n\n              {act === 'practice' && (\n                <div className=\"space-y-3 rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                  <div className=\"flex items-center justify-between\"><p className=\"text-xs font-medium uppercase tracking-wide text-gray-400\">Practice</p><span className=\"rounded-full bg-gray-100 px-2.5 py-1 text-[11px] font-medium text-gray-600\">Score {score.right} / {score.tries}</span></div>\n                  <div className=\"flex gap-1.5\">\n                    {([['place', 'Place the point'], ['read', 'Read the coordinates']] as const).map(([k, l]) => <button key={k} onClick={() => newChallenge(k)} aria-pressed={pKind === k} className={`flex-1 rounded-lg border px-2 py-2 text-xs font-medium ${pKind === k ? 'border-indigo-600 bg-indigo-600 text-white' : 'border-gray-200 bg-white text-gray-600'}`}>{l}</button>)}\n                  </div>\n                  {target && pKind === 'place' && <p className=\"rounded-lg bg-indigo-50 px-3 py-2 text-sm text-indigo-900\">Move point P to <span className=\"font-semibold\">{coordText(target, dim)}</span>, then press Check.</p>}\n                  {target && pKind === 'read' && (\n                    <div className=\"space-y-2\">\n                      <p className=\"rounded-lg bg-indigo-50 px-3 py-2 text-sm text-indigo-900\">Read the coordinates of the red point P from the axes, then type them in.</p>\n                      <div className=\"flex gap-2\">{fields.map(k => <label key={k} className=\"flex flex-1 items-center gap-1.5 text-xs\"><span className=\"font-semibold\" style={{ color: axisColor[k] }}>{k}</span><input type=\"number\" inputMode=\"decimal\" value={typed[k]} aria-label={`Your ${k} value`} onChange={e => { setTyped(t => ({ ...t, [k]: e.target.value })); setResult(null); }} className=\"h-8 w-full min-w-0 rounded-md border border-gray-200 px-2 text-sm\" /></label>)}</div>\n                    </div>\n                  )}\n                  {pKind === 'place' && <p className=\"text-xs text-gray-500\">P is now at <span className=\"font-medium text-gray-800\">{coordText(place[dim], dim)}</span></p>}\n                  <div className=\"flex gap-2\">\n                    <button onClick={check} disabled={!target} className=\"rounded-lg bg-indigo-600 px-4 py-2 text-xs font-medium text-white enabled:hover:bg-indigo-700 disabled:opacity-40\">Check</button>\n                    <button onClick={() => newChallenge()} className=\"rounded-lg border border-gray-200 bg-white px-4 py-2 text-xs text-gray-700 hover:border-indigo-300\">New point</button>\n                    {pKind === 'read' && <button onClick={() => setResult({ correct: false, hints: [`The answer is ${target ? coordText(target, dim) : ''}.`] })} className=\"rounded-lg border border-gray-200 bg-white px-3 py-2 text-xs text-gray-500\">Reveal</button>}\n                  </div>\n                  {result && <p aria-live=\"polite\" className={`rounded-lg px-3 py-2 text-xs leading-relaxed ${result.correct ? 'bg-emerald-50 text-emerald-900' : 'bg-amber-50 text-amber-900'}`}>{result.correct ? '✓ Correct! That is exactly the point.' : result.hints.join(' · ')}</p>}\n                  {pKind === 'read' && dim === '3d' && <p className=\"text-[11px] text-gray-400\">Tip: rotate the view and switch to the Top, Front and Side views to read each coordinate against its axis.</p>}\n                </div>\n              )}\n            </div>\n\n            {/* Teacher notes + exercises */}\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-amber-700\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">{NOTES[dim].map((n, i) => <li key={i} className=\"flex gap-2 text-xs leading-relaxed text-amber-900\"><span className=\"mt-0.5 shrink-0 text-amber-400\">•</span>{n}</li>)}</ul>\n              </div>\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"mb-3 text-xs font-medium uppercase tracking-wide text-gray-500\">✏️ Exercises</p>\n                <div className=\"space-y-2\">{EXERCISES[dim].map((ex, i) => (\n                  <div key={i} className=\"overflow-hidden rounded-xl border border-gray-100\">\n                    <button onClick={() => setOpenEx(openEx === i ? null : i)} aria-expanded={openEx === i} className=\"flex w-full justify-between gap-2 px-3 py-2.5 text-left text-xs leading-relaxed text-gray-700 transition hover:bg-gray-50\"><span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span><span className=\"shrink-0 text-sm text-gray-300\">{openEx === i ? '▲' : '▼'}</span></button>\n                    {openEx === i && <div className=\"border-t border-gray-100 bg-emerald-50 px-3 py-2.5 text-xs leading-relaxed text-emerald-800\"><span className=\"font-medium\">Answer: </span>{ex.a}</div>}\n                  </div>))}</div>\n              </div>\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\"><p className=\"mb-2 text-xs text-gray-400\">Curriculum</p><div className=\"flex flex-wrap gap-1.5\">{CURRICULA.map(c => <span key={c} className={`rounded-full px-2 py-0.5 text-xs font-medium ${curr.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'}`}>{c}</span>)}</div></div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/waves/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { WaveCanvas, WaveMode } from '@/components/simulation/WaveCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { waveSpeed, angularFreq, waveNumber, period } from '@/lib/physics/waves';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst MODE_META: Record<WaveMode, { title: string; icon: string; sub: string; eq: string }> = {\n  transverse:    { title: 'Transverse',     icon: '🌊', sub: 'Particles ⊥ to travel',       eq: 'y = A sin(kx − ωt)' },\n  longitudinal:  { title: 'Longitudinal',   icon: '🔊', sub: 'Particles ∥ to travel',        eq: 'compressions & rarefactions' },\n  superposition: { title: 'Superposition',  icon: '➕', sub: 'Two waves on one string',      eq: 'y = y₁ + y₂' },\n  standing:      { title: 'Standing wave',  icon: '🎻', sub: 'Two opposite travelling waves', eq: 'y = 2A sin(kx)cos(ωt)' },\n};\n\nconst TEACHER_NOTES: Record<WaveMode, string[]> = {\n  transverse: [\n    'Watch the red particle: it only moves UP and DOWN while the wave pattern moves RIGHT — the wave transports energy, not matter.',\n    'v = fλ is the single most examined wave equation. The green bracket marks one wavelength.',\n    'Doubling frequency at fixed speed halves the wavelength — try it with the sliders.',\n    'Examples: water surface waves, waves on a string, ALL electromagnetic waves.',\n    'The particle completes one full oscillation in exactly one period T = 1/f.',\n  ],\n  longitudinal: [\n    'Particles vibrate ALONG the direction of travel — regions bunch up (compressions) and spread out (rarefactions).',\n    'Sound is the classic longitudinal wave; it cannot travel through a vacuum because it needs particles.',\n    'Wavelength = distance between successive compressions (or rarefactions).',\n    'The same v = fλ applies — only the direction of particle vibration differs from transverse.',\n    'Seismic P-waves are longitudinal; S-waves are transverse (and cannot pass the liquid outer core).',\n  ],\n  superposition: [\n    'When two waves meet, displacements simply ADD: y = y₁ + y₂ — the principle of superposition.',\n    'Same frequency, 0° phase → constructive interference (double amplitude). 180° → destructive (cancellation).',\n    'Slightly different frequencies produce BEATS — watch the resultant swell and fade.',\n    'The two component waves pass through each other unchanged after overlapping.',\n    'This is the foundation of interference, diffraction patterns, and noise-cancelling headphones.',\n  ],\n  standing: [\n    'Two identical waves travelling in OPPOSITE directions superpose into a standing wave: y = 2A sin(kx)cos(ωt).',\n    'Nodes (red dots) never move — they are spaced λ/2 apart. Antinodes oscillate with amplitude 2A.',\n    'A standing wave transports NO energy — energy is trapped between nodes.',\n    'Stringed instruments work on standing waves: fixed ends must be nodes, so only certain λ fit.',\n    'Fundamental frequency of a string of length L: λ = 2L, f₁ = v/2L.',\n  ],\n};\n\nconst EXERCISES: Record<WaveMode, { q: string; a: string }[]> = {\n  transverse: [\n    { q: 'A wave has frequency 50Hz and wavelength 6.8m. Find its speed and period.', a: 'v=fλ=50×6.8=340 m/s. T=1/f=0.02s.' },\n    { q: 'Radio waves (v=3×10⁸ m/s) at 100MHz — find the wavelength.', a: 'λ=v/f=3×10⁸/10⁸=3m.' },\n    { q: 'A wave crest travels 15m in 3s while a particle completes 6 full oscillations. Find λ.', a: 'v=15/3=5 m/s. f=6/3=2Hz. λ=v/f=2.5m.' },\n  ],\n  longitudinal: [\n    { q: 'Sound travels 660m in 2s. Adjacent compressions are 1.1m apart. Find the frequency.', a: 'v=660/2=330 m/s. λ=1.1m. f=v/λ=300Hz.' },\n    { q: 'Why can light reach us from the Sun but sound cannot?', a: 'Light (transverse EM wave) needs no medium; sound (longitudinal mechanical) needs particles to compress — space is a vacuum.' },\n    { q: 'An echo returns 0.6s after a clap, with v=340 m/s. How far is the wall?', a: 'Total path=340×0.6=204m. Distance=204/2=102m.' },\n  ],\n  superposition: [\n    { q: 'Two waves of amplitude 3cm meet in phase. What is the resultant amplitude? And at 180°?', a: 'In phase: 3+3=6cm (constructive). Antiphase: 3−3=0 (destructive).' },\n    { q: 'Two tuning forks of 256Hz and 260Hz sound together. What beat frequency is heard?', a: 'f_beat=|f₁−f₂|=4Hz — 4 loud-soft cycles per second.' },\n    { q: 'State the principle of superposition.', a: 'When two or more waves meet at a point, the resultant displacement equals the vector sum of the individual displacements.' },\n  ],\n  standing: [\n    { q: 'Adjacent nodes of a standing wave are 0.4m apart. Find the wavelength.', a: 'Node spacing=λ/2 → λ=0.8m.' },\n    { q: 'A 0.6m string fixed at both ends vibrates in its fundamental mode with v=120 m/s. Find f₁.', a: 'λ=2L=1.2m. f₁=v/λ=120/1.2=100Hz.' },\n    { q: 'How is a standing wave different from a travelling wave?', a: 'Standing: fixed nodes/antinodes, no energy transport, amplitude varies with position. Travelling: pattern moves, transports energy, every point oscillates with the same amplitude.' },\n  ],\n};\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function WavesPage() {\n  const [mode, setMode] = useState<WaveMode>('transverse');\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'SAT']);\n\n  const [A, setA] = useState(1);\n  const [f, setF] = useState(0.5);\n  const [lambda, setLambda] = useState(2);\n  const [A2, setA2] = useState(0.7);\n  const [f2, setF2] = useState(0.5);\n  const [phase2, setPhase2] = useState(0);\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false); setResetKey(k => k + 1);\n  }, []);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [mode, A, f, lambda, A2, f2, phase2, reset]);\n\n  const v = waveSpeed(f, lambda);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 660, 300, 980);\n\n  useTopicPreset(\"simulations-waves\", { \"A\": setA,\n    \"f\": setF,\n    \"lambda\": setLambda,\n    \"A2\": setA2,\n    \"f2\": setF2,\n    \"phase2\": setPhase2 }, { \"mode\": (value: string) => setMode(value as typeof mode) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Waves</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Wave motion</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(MODE_META) as WaveMode[]).map(m => (\n              <button key={m} onClick={() => { setMode(m); setOpenEx(null); }}\n                className={`shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium transition ${\n                  mode === m ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>\n                <span>{MODE_META[m].icon}</span><span>{MODE_META[m].title}</span>\n              </button>\n            ))}\n          </div>\n\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">{MODE_META[mode].sub}</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">{MODE_META[mode].eq}</span>\n            <span className=\"text-xs text-gray-400 ml-2\">v = fλ</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <WaveCanvas key={resetKey} mode={mode}\n                  amplitude={A} frequency={f} wavelength={lambda}\n                  amplitude2={A2} frequency2={f2} phase2={phase2}\n                  isRunning={isRunning} isPaused={isPaused}\n                  width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/waves\"\n                  title={`${MODE_META[mode].title} wave — A-Factor STEM Studio`}\n                  params={{ mode, A, f, lambda, A2, f2, phase2 }} />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <Slider label=\"Amplitude\" unit=\"m\" value={A} min={0.2} max={1.5} step={0.1} set={setA} color=\"#6366f1\" />\n                <Slider label=\"Frequency\" unit=\"Hz\" value={f} min={0.1} max={2} step={0.05} set={setF} color=\"#f59e0b\" note=\"Slow enough to follow by eye\" />\n                <Slider label=\"Wavelength\" unit=\"m\" value={lambda} min={0.5} max={4} step={0.1} set={setLambda} color=\"#10b981\" />\n                {mode === 'superposition' && <>\n                  <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide pt-1\">Second wave</p>\n                  <Slider label=\"Amplitude A₂\" unit=\"m\" value={A2} min={0.1} max={1.5} step={0.1} set={setA2} color=\"#8b5cf6\" />\n                  <Slider label=\"Frequency f₂\" unit=\"Hz\" value={f2} min={0.1} max={2} step={0.05} set={setF2} color=\"#ef4444\" note=\"Set slightly different from f for beats\" />\n                  <Slider label=\"Phase difference\" unit=\"°\" value={phase2} min={0} max={360} step={5} set={setPhase2} color=\"#0ea5e9\" note=\"0° constructive · 180° destructive\" />\n                </>}\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"Wave speed v\" value={v.toFixed(2)} unit=\"m/s\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Period T\" value={period(f).toFixed(2)} unit=\"s\" color=\"text-emerald-600\" />\n                  <StatRow label=\"Angular freq ω\" value={angularFreq(f).toFixed(3)} unit=\"rad/s\" color=\"text-amber-600\" />\n                  <StatRow label=\"Wave number k\" value={waveNumber(lambda).toFixed(3)} unit=\"rad/m\" color=\"text-rose-500\" />\n                  {mode === 'superposition' && <>\n                    <StatRow label=\"Beat frequency\" value={Math.abs(f - f2).toFixed(2)} unit=\"Hz\" color=\"text-purple-600\" />\n                    <StatRow label=\"Max resultant\" value={(A + A2).toFixed(2)} unit=\"m\" color=\"text-gray-600\" />\n                  </>}\n                  {mode === 'standing' && <>\n                    <StatRow label=\"Node spacing\" value={(lambda / 2).toFixed(2)} unit=\"m\" color=\"text-purple-600\" />\n                    <StatRow label=\"Antinode amp.\" value={(2 * A).toFixed(2)} unit=\"m\" color=\"text-gray-600\" />\n                  </>}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[mode].map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[mode].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/gas-laws/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { BoylesCanvas } from '@/components/simulation/BoylesCanvas';\nimport { CharlesCanvas } from '@/components/simulation/CharlesCanvas';\nimport { PressureLawCanvas } from '@/components/simulation/PressureLawCanvas';\nimport { IdealGasCanvas } from '@/components/simulation/IdealGasCanvas';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { GasLawGraph } from '@/components/simulation/GasLawGraph';\nimport {\n  idealGasPressure, idealGasVolume, idealGasMoles, idealGasTemperature,\n  charlesNewVolume, pressureLawNewPressure, VAN_DER_WAALS,\n} from '@/lib/physics/gas-laws';\n\ntype Law = 'boyle' | 'charles' | 'pressure' | 'ideal' | 'real';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CURRICULUM_COLORS: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst LAW_META: Record<Law, { title: string; equation: string; condition: string; graphLabel: string; graphDesc: string }> = {\n  boyle:    { title: \"Boyle's Law\",    equation: 'P₁V₁ = P₂V₂',   condition: 'constant T, n',            graphLabel: 'P–V graph',           graphDesc: 'Hyperbolic isotherm. Yellow dot = current state.' },\n  charles:  { title: \"Charles' Law\",   equation: 'V₁/T₁ = V₂/T₂', condition: 'constant P, n — T in K',  graphLabel: 'V–T graph',           graphDesc: 'Straight line → 0 K. Yellow dot = current state.' },\n  pressure: { title: 'Pressure Law',   equation: 'P₁/T₁ = P₂/T₂', condition: 'constant V, n — T in K',  graphLabel: 'P–T graph',           graphDesc: 'Straight line → 0 K. Pressure rises with temperature.' },\n  ideal:    { title: 'Ideal Gas Law',  equation: 'PV = nRT',        condition: 'R = 8.314 J mol⁻¹ K⁻¹', graphLabel: 'P–V isotherms',       graphDesc: 'Three isotherms at different mole counts. All obey PV = nRT.' },\n  real:     { title: 'Real Gases',     equation: '(P + an²/V²)(V − nb) = nRT', condition: 'Van der Waals equation', graphLabel: 'Compressibility (Z vs P)', graphDesc: 'Z = PV/nRT. Ideal gas Z = 1 always. Real gases deviate at high pressure.' },\n};\n\nconst TEACHER_NOTES: Record<Law, string[]> = {\n  boyle: [\n    \"Boyle's Law: at constant T, pressure and volume are inversely proportional — P₁V₁ = P₂V₂.\",\n    \"The P–V graph is a hyperbola. Each curve (isotherm) represents a different temperature.\",\n    \"Higher temperature isotherms sit above lower ones — more energy means higher pressure at same volume.\",\n    \"Real gases deviate from this at very high pressures or near condensation.\",\n    \"Ask: what happens to particles when volume decreases? Why does pressure increase?\",\n  ],\n  charles: [\n    \"Charles' Law: at constant P, volume is proportional to absolute temperature — V₁/T₁ = V₂/T₂.\",\n    \"Temperature MUST be in Kelvin. 0°C is not zero molecular motion — 0 K is.\",\n    \"Extended to 0 K, the V–T graph passes through the origin — this is how absolute zero was estimated.\",\n    \"A gas at 0 K would have zero volume — impossible for real gases (they liquefy first).\",\n    \"Ask: why do hot air balloons rise? Why do car tyres stiffen in cold weather?\",\n  ],\n  pressure: [\n    \"Pressure Law (Gay-Lussac): at constant V, pressure is proportional to T — P₁/T₁ = P₂/T₂.\",\n    \"This is what happens in rigid sealed containers like pressure cookers and aerosol cans.\",\n    \"NEVER heat a sealed rigid container — pressure rises until it ruptures.\",\n    \"The P–T graph is a straight line through 0 K, just like Charles' Law.\",\n    \"Combined with Boyle's and Charles' Law, this gives the ideal gas law: PV = nRT.\",\n  ],\n  ideal: [\n    \"The ideal gas law PV = nRT unifies Boyle's, Charles', and the Pressure Law into one equation.\",\n    \"R = 8.314 J mol⁻¹ K⁻¹ is the universal gas constant — the same for every gas.\",\n    \"An ideal gas has no intermolecular forces and particles occupy zero volume.\",\n    \"Use the calculator: input any 3 of P, V, n, T and solve for the 4th.\",\n    \"At standard conditions (STP: 0°C, 100 kPa), 1 mol of ideal gas occupies 22.4 L.\",\n  ],\n  real: [\n    \"Real gases deviate from ideal behaviour due to: (1) intermolecular attractions and (2) finite particle volume.\",\n    \"The Van der Waals equation corrects for both: (P + an²/V²)(V − nb) = nRT. 'a' corrects for attractions; 'b' for particle volume.\",\n    \"Z = PV/nRT is the compressibility factor. For ideal gas Z = 1. Real gases: Z < 1 at moderate P (attractions dominate), Z > 1 at high P (volume dominates).\",\n    \"CO₂ and NH₃ show strong deviation (large 'a') — they have strong intermolecular forces.\",\n    \"Helium and H₂ are nearly ideal — small, non-polar molecules with weak forces.\",\n  ],\n};\n\nconst EXERCISES: Record<Law, { q: string; a: string }[]> = {\n  boyle: [\n    { q: \"A gas at 200 kPa occupies 4 L. Find the volume at 400 kPa (constant T).\", a: \"V₂ = P₁V₁/P₂ = (200×4)/400 = 2 L\" },\n    { q: \"A gas at 100 kPa occupies 8 L. Find the pressure at 2 L.\", a: \"P₂ = P₁V₁/V₂ = (100×8)/2 = 400 kPa\" },\n    { q: \"Why is the P–V graph a hyperbola and not a straight line?\", a: \"P and V are inversely proportional (PV = constant), so plotting one against the other gives a rectangular hyperbola.\" },\n  ],\n  charles: [\n    { q: \"A gas occupies 3 L at 300 K. Find its volume at 600 K (constant P).\", a: \"V₂ = V₁T₂/T₁ = (3×600)/300 = 6 L\" },\n    { q: \"A balloon is 2 L at 27°C. Find volume at 127°C.\", a: \"T₁=300K, T₂=400K → V₂ = (2×400)/300 = 2.67 L\" },\n    { q: \"Why must temperature be in Kelvin for gas law calculations?\", a: \"Kelvin measures absolute thermal energy starting from 0 K (zero molecular motion). Celsius 0 is arbitrary — ratios in Celsius give wrong answers.\" },\n  ],\n  pressure: [\n    { q: \"Gas in a rigid container: 150 kPa at 300 K. Find pressure at 600 K.\", a: \"P₂ = P₁T₂/T₁ = (150×600)/300 = 300 kPa\" },\n    { q: \"An aerosol can: 250 kPa at 20°C. Find pressure at 60°C.\", a: \"T₁=293K, T₂=333K → P₂ = (250×333)/293 ≈ 284 kPa\" },\n    { q: \"Why is it dangerous to throw an aerosol can into a fire?\", a: \"Fixed volume means rising temperature causes pressure to rise proportionally — eventually exceeding the can's rated limit, causing explosion.\" },\n  ],\n  ideal: [\n    { q: \"Calculate the volume of 2 mol of ideal gas at 300 K and 100 kPa.\", a: \"V = nRT/P = (2 × 8.314 × 300) / (100×1000) = 0.0499 m³ = 49.9 L\" },\n    { q: \"What pressure does 0.5 mol of gas exert in a 10 L container at 27°C?\", a: \"T=300K, V=0.01m³ → P = nRT/V = (0.5×8.314×300)/0.01 = 124,710 Pa ≈ 125 kPa\" },\n    { q: \"At STP (0°C, 100 kPa), what volume does 1 mol of ideal gas occupy?\", a: \"V = nRT/P = (1×8.314×273)/(100,000) = 0.0227 m³ = 22.7 L (≈ 22.4 L)\" },\n  ],\n  real: [\n    { q: \"Why does CO₂ deviate more from ideal behaviour than helium?\", a: \"CO₂ has stronger intermolecular attractions (large 'a' = 3.64) and larger molecular volume (larger 'b'). Helium has a = 0.034 — nearly ideal.\" },\n    { q: \"At what conditions do real gases behave most like ideal gases?\", a: \"High temperature and low pressure — high T means thermal energy dominates over attractions; low P means molecules are far apart and volume is negligible.\" },\n    { q: \"What does Z < 1 tell us about a real gas?\", a: \"Intermolecular attractions are dominant — the gas is more compressed than an ideal gas at the same conditions. Common at moderate pressures.\" },\n  ],\n};\n\nconst REAL_WORLD: Record<Law, { icon: string; text: string }[]> = {\n  boyle:    [{ icon: '🤿', text: 'Scuba — gas in lungs expands as diver ascends.' }, { icon: '🩺', text: 'Breathing — diaphragm lowers volume to draw air in.' }, { icon: '💉', text: 'Syringes — reduced pressure draws in fluid.' }],\n  charles:  [{ icon: '🎈', text: 'Hot air balloons — heat expands gas, reducing density.' }, { icon: '🚗', text: 'Car tyres stiffen in cold — volume decreases.' }, { icon: '🍞', text: 'Bread rising — CO₂ expands in oven heat.' }],\n  pressure: [{ icon: '🥘', text: 'Pressure cooker — sealed volume means pressure rises with T.' }, { icon: '💣', text: 'Aerosol cans — never incinerate, pressure rises rapidly.' }, { icon: '🌡️', text: 'Gas thermometers measure T by pressure change at fixed V.' }],\n  ideal:    [{ icon: '🏭', text: 'Industrial gas storage — engineers use PV = nRT to size tanks.' }, { icon: '🚀', text: 'Rocket propellant — gas behaviour at extreme T and P.' }, { icon: '⚗️', text: 'Lab calculations — molar volume, stoichiometry of gases.' }],\n  real:     [{ icon: '❄️', text: 'Refrigerants — real gas properties essential for cooling cycles.' }, { icon: '🏗️', text: 'High-pressure pipelines — Van der Waals correction at 200+ atm.' }, { icon: '🌊', text: 'Deep-sea gas pockets — extreme P makes gas behaviour non-ideal.' }],\n};\n\ntype SolveFor = 'P' | 'V' | 'n' | 'T';\n\nexport default function GasLawsPage() {\n  const [law, setLaw] = useState<Law>('boyle');\n  const [volume, setVolume] = useState(4);\n  const [temperature, setTemperature] = useState(300);\n  const [pressure, setPressure] = useState(200);\n  const [moles, setMoles] = useState(0.1);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE']);\n  const [selectedGas, setSelectedGas] = useState('CO2');\n  const [solveFor, setSolveFor] = useState<SolveFor>('P');\n\n  // Derived values\n  const derivedP_boyle  = idealGasPressure(moles, temperature, volume) / 1000;\n  const derivedV_charles = charlesNewVolume(3, 300, temperature);\n  const derivedP_pressure = pressureLawNewPressure(200, 300, temperature);\n\n  // Ideal gas solver\n  const solvedValue = (() => {\n    if (solveFor === 'P') return { label: 'P', value: (idealGasPressure(moles, temperature, volume) / 1000).toFixed(2), unit: 'kPa' };\n    if (solveFor === 'V') return { label: 'V', value: idealGasVolume(moles, temperature, pressure).toFixed(3), unit: 'L' };\n    if (solveFor === 'n') return { label: 'n', value: idealGasMoles(pressure, volume, temperature).toFixed(4), unit: 'mol' };\n    return { label: 'T', value: idealGasTemperature(pressure, volume, moles).toFixed(1), unit: 'K' };\n  })();\n\n  const toggleC = (c: string) =>\n    setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c]);\n\n  const meta = LAW_META[law];\n\n  // This card sits in a narrower grid column (alongside a graph/stats\n  // column), so it gets a smaller cap than the full-width single-canvas\n  // sims elsewhere in the app.\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 280, 240, 460);\n\n  useTopicPreset(\"simulations-gas-laws\", { \"pressure\": setPressure,\n    \"volume\": setVolume,\n    \"moles\": setMoles,\n    \"temperature\": setTemperature }, { \"law\": (value: string) => setLaw(value as typeof law) });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-5\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-1\">Thermal physics</p>\n                <h1 className=\"text-lg sm:text-xl font-semibold text-gray-900\">Gas laws</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c} onClick={() => toggleC(c)}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CURRICULUM_COLORS[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-5 space-y-4\">\n\n          {/* Tabs */}\n          <div className=\"flex gap-1 bg-gray-100 p-1 rounded-xl overflow-x-auto\">\n            {(Object.keys(LAW_META) as Law[]).map(l => (\n              <button key={l} onClick={() => { setLaw(l); setOpenEx(null); }}\n                className={`shrink-0 px-3 sm:px-4 py-2 rounded-lg text-xs font-medium transition ${\n                  law === l ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'\n                }`}>{LAW_META[l].title}</button>\n            ))}\n          </div>\n\n          {/* Equation banner */}\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Equation</span>\n            <span className=\"text-sm font-semibold text-gray-900 font-mono\">{meta.equation}</span>\n            <span className=\"text-xs text-gray-400\">{meta.condition}</span>\n          </div>\n\n          {/* Main grid */}\n          <div className=\"grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4\">\n\n            {/* Left: canvas / calculator */}\n            <SimulationStage className=\"space-y-3\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">\n                  {law === 'boyle' ? 'Compression (constant T)' :\n                   law === 'charles' ? 'Expansion (constant P)' :\n                   law === 'pressure' ? 'Rigid container (constant V)' :\n                   law === 'ideal' ? 'Ideal gas container' :\n                   'Real vs ideal gas'}\n                </p>\n\n                {law === 'boyle'    && <BoylesCanvas volume={volume} temperature={temperature} moles={moles} width={canvasSize.width} height={canvasSize.height} />}\n                {law === 'charles'  && <CharlesCanvas temperature={temperature} pressure={pressure} moles={moles} width={canvasSize.width} height={canvasSize.height} />}\n                {law === 'pressure' && <PressureLawCanvas temperature={temperature} volume={volume} moles={moles} width={canvasSize.width} height={canvasSize.height} />}\n                {law === 'ideal'    && <IdealGasCanvas pressure={pressure} volume={volume} temperature={temperature} moles={moles} solveFor={solveFor} width={canvasSize.width} height={canvasSize.height} />}\n                {law === 'real'     && (\n                  <div className=\"space-y-3\">\n                    <div className=\"rounded-xl border border-gray-100 bg-gray-50 p-3\">\n                      <p className=\"text-xs text-gray-400 mb-2\">Select gas</p>\n                      <div className=\"grid grid-cols-2 gap-1.5\">\n                        {Object.entries(VAN_DER_WAALS).filter(([k]) => k !== 'ideal').map(([key, g]) => (\n                          <button key={key} onClick={() => setSelectedGas(key)}\n                            className={`text-xs px-2 py-2 rounded-lg border font-medium transition text-left ${\n                              selectedGas === key ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300'\n                            }`}>\n                            <span className=\"font-mono\">{g.formula}</span>\n                            <span className=\"text-[10px] block opacity-70\">{g.name}</span>\n                          </button>\n                        ))}\n                      </div>\n                    </div>\n                    <div className=\"rounded-xl border border-gray-100 bg-gray-50 p-3 text-xs space-y-1.5\">\n                      <p className=\"font-medium text-gray-600\">Van der Waals constants</p>\n                      <div className=\"flex gap-4\">\n                        <span className=\"text-gray-500\">a = <span className=\"font-mono font-medium text-gray-800\">{VAN_DER_WAALS[selectedGas].a}</span> Pa·m⁶/mol²</span>\n                        <span className=\"text-gray-500\">b = <span className=\"font-mono font-medium text-gray-800\">{VAN_DER_WAALS[selectedGas].b}</span> m³/mol</span>\n                      </div>\n                      <p className=\"text-gray-400 text-[10px]\">a = intermolecular attractions · b = particle volume</p>\n                    </div>\n                  </div>\n                )}\n              </div>\n\n              {/* Sliders / calculator */}\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">\n                  {law === 'ideal' ? 'PV = nRT calculator' : 'Adjust parameters'}\n                </p>\n\n                {law === 'ideal' && (\n                  <>\n                    <div className=\"grid grid-cols-4 gap-1 bg-gray-100 p-1 rounded-xl\">\n                      {(['P', 'V', 'n', 'T'] as SolveFor[]).map(s => (\n                        <button key={s} onClick={() => setSolveFor(s)}\n                          className={`py-2 rounded-lg text-xs font-medium transition ${\n                            solveFor === s ? 'bg-white text-indigo-700 shadow-sm' : 'text-gray-500'\n                          }`}>Solve {s}</button>\n                      ))}\n                    </div>\n                    {solveFor !== 'P' && (\n                      <div className=\"space-y-1.5\">\n                        <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Pressure</span><span className=\"font-medium tabular-nums\">{pressure} kPa</span></div>\n                        <input type=\"range\" min=\"10\" max=\"1000\" step=\"10\" value={pressure} onChange={e => setPressure(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#6366f1' }} />\n                      </div>\n                    )}\n                    {solveFor !== 'V' && (\n                      <div className=\"space-y-1.5\">\n                        <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Volume</span><span className=\"font-medium tabular-nums\">{volume.toFixed(1)} L</span></div>\n                        <input type=\"range\" min=\"0.5\" max=\"20\" step=\"0.1\" value={volume} onChange={e => setVolume(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#10b981' }} />\n                      </div>\n                    )}\n                    {solveFor !== 'n' && (\n                      <div className=\"space-y-1.5\">\n                        <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Moles</span><span className=\"font-medium tabular-nums\">{moles.toFixed(2)} mol</span></div>\n                        <input type=\"range\" min=\"0.01\" max=\"1\" step=\"0.01\" value={moles} onChange={e => setMoles(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#f59e0b' }} />\n                      </div>\n                    )}\n                    {solveFor !== 'T' && (\n                      <div className=\"space-y-1.5\">\n                        <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Temperature</span><span className=\"font-medium tabular-nums\">{temperature} K</span></div>\n                        <input type=\"range\" min=\"100\" max=\"1000\" step=\"10\" value={temperature} onChange={e => setTemperature(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#ef4444' }} />\n                      </div>\n                    )}\n                    <div className=\"rounded-xl bg-indigo-50 px-4 py-3 text-center\">\n                      <p className=\"text-xs text-indigo-400 mb-1\">Solving for {solveFor}</p>\n                      <p className=\"text-xl font-bold text-indigo-700 font-mono\">{solvedValue.value} <span className=\"text-sm font-normal\">{solvedValue.unit}</span></p>\n                    </div>\n                  </>\n                )}\n\n                {law === 'boyle' && (\n                  <>\n                    <div className=\"space-y-1.5\">\n                      <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Volume</span><span className=\"font-medium tabular-nums\">{volume.toFixed(1)} L</span></div>\n                      <input type=\"range\" min=\"0.5\" max=\"10\" step=\"0.1\" value={volume} onChange={e => setVolume(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#6366f1' }} />\n                    </div>\n                    <div className=\"space-y-1.5\">\n                      <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Temperature (constant)</span><span className=\"font-medium tabular-nums\">{temperature} K</span></div>\n                      <input type=\"range\" min=\"200\" max=\"600\" step=\"10\" value={temperature} onChange={e => setTemperature(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#f59e0b' }} />\n                    </div>\n                    <div className=\"rounded-xl bg-indigo-50 px-3 py-2.5\">\n                      <span className=\"text-sm font-medium text-indigo-700\">P = {derivedP_boyle.toFixed(1)} kPa</span>\n                    </div>\n                  </>\n                )}\n\n                {law === 'charles' && (\n                  <>\n                    <div className=\"space-y-1.5\">\n                      <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Temperature</span><span className=\"font-medium tabular-nums\">{temperature} K ({temperature - 273}°C)</span></div>\n                      <input type=\"range\" min=\"100\" max=\"600\" step=\"10\" value={temperature} onChange={e => setTemperature(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#f59e0b' }} />\n                    </div>\n                    <div className=\"space-y-1.5\">\n                      <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Pressure (constant)</span><span className=\"font-medium tabular-nums\">{pressure} kPa</span></div>\n                      <input type=\"range\" min=\"50\" max=\"500\" step=\"10\" value={pressure} onChange={e => setPressure(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#10b981' }} />\n                    </div>\n                    <div className=\"rounded-xl bg-emerald-50 px-3 py-2.5\">\n                      <span className=\"text-sm font-medium text-emerald-700\">V = {derivedV_charles.toFixed(2)} L</span>\n                    </div>\n                  </>\n                )}\n\n                {law === 'pressure' && (\n                  <>\n                    <div className=\"space-y-1.5\">\n                      <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Temperature</span><span className=\"font-medium tabular-nums\">{temperature} K ({temperature - 273}°C)</span></div>\n                      <input type=\"range\" min=\"100\" max=\"600\" step=\"10\" value={temperature} onChange={e => setTemperature(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#f59e0b' }} />\n                    </div>\n                    <div className=\"space-y-1.5\">\n                      <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Volume (constant)</span><span className=\"font-medium tabular-nums\">{volume.toFixed(1)} L</span></div>\n                      <input type=\"range\" min=\"0.5\" max=\"10\" step=\"0.1\" value={volume} onChange={e => setVolume(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#6366f1' }} />\n                    </div>\n                    <div className=\"rounded-xl bg-red-50 px-3 py-2.5\">\n                      <span className=\"text-sm font-medium text-red-700\">P = {derivedP_pressure.toFixed(1)} kPa</span>\n                    </div>\n                  </>\n                )}\n\n                {law === 'real' && (\n                  <>\n                    <div className=\"space-y-1.5\">\n                      <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Temperature</span><span className=\"font-medium tabular-nums\">{temperature} K</span></div>\n                      <input type=\"range\" min=\"200\" max=\"800\" step=\"10\" value={temperature} onChange={e => setTemperature(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#f59e0b' }} />\n                    </div>\n                    <div className=\"space-y-1.5\">\n                      <div className=\"flex justify-between text-xs\"><span className=\"text-gray-500\">Moles</span><span className=\"font-medium tabular-nums\">{moles.toFixed(2)} mol</span></div>\n                      <input type=\"range\" min=\"0.01\" max=\"1\" step=\"0.01\" value={moles} onChange={e => setMoles(Number(e.target.value))} className=\"w-full\" style={{ accentColor: '#6366f1' }} />\n                    </div>\n                    <p className=\"text-xs text-gray-400\">Lower T and higher P = more deviation from ideal. Try CO₂ vs He.</p>\n                  </>\n                )}\n              </div>\n            </SimulationStage>\n\n            {/* Graph */}\n            <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n              <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-1\">{meta.graphLabel}</p>\n              <p className=\"text-xs text-gray-400 mb-4\">{meta.graphDesc}</p>\n              <GasLawGraph\n                law={law}\n                currentV={volume}\n                currentP={law === 'boyle' ? derivedP_boyle : law === 'pressure' ? derivedP_pressure : pressure}\n                currentT={temperature}\n                moles={moles}\n                selectedGas={selectedGas}\n              />\n              <div className=\"mt-4 rounded-xl border border-indigo-100 bg-indigo-50 p-3\">\n                <p className=\"text-xs font-medium text-indigo-600 mb-2\">Real world</p>\n                <ul className=\"space-y-1.5\">\n                  {REAL_WORLD[law].map((r, i) => (\n                    <li key={i} className=\"text-xs text-indigo-800 flex gap-2 leading-relaxed\">\n                      <span className=\"shrink-0\">{r.icon}</span>{r.text}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <div className=\"mt-3\">\n                <p className=\"text-xs text-gray-400 mb-1.5\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CURRICULUM_COLORS[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            {/* Teacher notes + exercises */}\n            <div className=\"space-y-3 md:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES[law].map((note, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{note}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES[law].map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-base leading-none\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/radioactive-decay/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef } from 'react';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { DecayCanvas, DecayGraph } from '@/components/simulation/DecayCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { decayConstant, activity, remaining } from '@/lib/physics/decay';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TEACHER_NOTES = [\n  'Decay is RANDOM for one nucleus but statistically predictable for many — the red measured dot scatters around the smooth blue theory curve, and the scatter shrinks as N₀ grows.',\n  'After each half-life exactly half of what remains decays: N₀ → N₀/2 → N₀/4 → N₀/8 … the dashed gridlines mark 1T½, 2T½, 3T½.',\n  'The decay constant λ = ln2/T½ is the probability per second that any one nucleus decays. Activity A = λN falls with the same half-life as N.',\n  'Nothing changes the half-life — not temperature, pressure, or chemistry. It is a nuclear property.',\n  'Carbon-14 dating: living things maintain constant C-14; after death it halves every 5730 years. Measuring the remaining fraction gives the age.',\n];\n\nconst EXERCISES = [\n  { q: 'A sample has half-life 8s and starts with 640 nuclei. How many remain after 24s?', a: '24s = 3 half-lives. 640 → 320 → 160 → 80 nuclei.' },\n  { q: 'The activity of a source falls from 1200Bq to 150Bq in 36 minutes. Find the half-life.', a: '1200→600→300→150 is 3 halvings, so T½ = 36/3 = 12 minutes.' },\n  { q: 'A sample of half-life 5730 years retains 25% of its C-14. How old is it?', a: '25% = (1/2)² → 2 half-lives → 2 × 5730 = 11460 years.' },\n  { q: 'Find the decay constant of a nuclide with T½ = 10s, and the activity of 400 nuclei.', a: 'λ = ln2/10 = 0.0693 s⁻¹. A = λN = 0.0693 × 400 ≈ 27.7 decays/s.' },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\nexport default function RadioactiveDecayPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [resetKey, setResetKey] = useState(0);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'JUPEB']);\n\n  const [n0, setN0] = useState(400);\n  const [halfLife, setHalfLife] = useState(5);\n  const [live, setLive] = useState({ t: 0, n: 400 });\n\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const reset = useCallback(() => {\n    setIsRunning(false); setIsPaused(false);\n    setResetKey(k => k + 1); setLive({ t: 0, n: n0 });\n  }, [n0]);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [n0, halfLife, reset]);\n\n  // Throttle graph updates (same pattern as SHM) — canvas has its own rAF loop.\n  const lastTickRef = useRef(0);\n  const handleTick = useCallback((t: number, n: number) => {\n    const now = performance.now();\n    if (now - lastTickRef.current > 40) {\n      lastTickRef.current = now;\n      setLive({ t, n });\n    }\n  }, []);\n\n  const lam = decayConstant(halfLife);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 300, 980);\n\n  useTopicPreset(\"simulations-radioactive-decay\", { \"n0\": setN0,\n    \"halfLife\": setHalfLife }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Modern physics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Radioactive decay</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Random decay, predictable statistics</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">N = N₀ · 2^(−t/T½)</span>\n            <span className=\"text-xs text-gray-400 ml-2\">λ = ln2/T½ &nbsp;|&nbsp; A = λN</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <DecayCanvas n0={n0} halfLife={halfLife} resetKey={resetKey}\n                  isRunning={isRunning} isPaused={isPaused}\n                  onTick={handleTick} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/decay\"\n                  title=\"Radioactive decay — A-Factor STEM Studio\"\n                  params={{ n0, hl: halfLife }} />\n              </div>\n\n              <div data-stage-role=\"extra\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">Decay curve N–t</p>\n                <DecayGraph n0={n0} halfLife={halfLife} currentT={live.t} currentN={live.n} />\n                <p className=\"text-[10px] text-gray-400 mt-2 text-center\">\n                  Blue dot: theory N₀·2^(−t/T½) — Red dot: your random sample. They agree better with larger N₀.\n                </p>\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <Slider label=\"Initial nuclei N₀\" unit=\"\" value={n0} min={50} max={900} step={50} set={setN0} color=\"#6366f1\"\n                  note=\"Larger samples follow the theory curve more closely\" />\n                <Slider label=\"Half-life T½\" unit=\"s\" value={halfLife} min={1} max={20} step={0.5} set={setHalfLife} color=\"#f59e0b\" />\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"Decay constant λ\" value={lam.toFixed(4)} unit=\"s⁻¹\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Initial activity\" value={activity(n0, halfLife).toFixed(1)} unit=\"Bq\" color=\"text-emerald-600\" />\n                  <StatRow label=\"N after 1 T½\" value={(n0 / 2).toFixed(0)} unit=\"\" color=\"text-amber-600\" />\n                  <StatRow label=\"N after 2 T½\" value={(n0 / 4).toFixed(0)} unit=\"\" color=\"text-rose-500\" />\n                  <StatRow label=\"N after 3 T½\" value={(n0 / 8).toFixed(0)} unit=\"\" color=\"text-purple-600\" />\n                  {live.t > 0 && (\n                    <StatRow label={`Theory at t=${live.t.toFixed(1)}s`} value={remaining(n0, halfLife, live.t).toFixed(0)} unit=\"\" color=\"text-gray-600\" />\n                  )}\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/simulations/photoelectric-effect/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\n\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useCallback, useEffect, useRef, useMemo } from 'react';\nimport { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Label, ReferenceDot, ReferenceLine } from 'recharts';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { PhotoelectricCanvas } from '@/components/simulation/PhotoelectricCanvas';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { METALS, keMaxEV, thresholdF14, stoppingPotential, photonEnergyEV, wavelengthNm, keLine } from '@/lib/physics/photoelectric';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\n\nconst CURRICULA = ['WAEC', 'NECO', 'IGCSE', 'SAT', 'JUPEB'];\nconst CC: Record<string, string> = {\n  WAEC: 'bg-indigo-100 text-indigo-700', NECO: 'bg-pink-100 text-pink-700',\n  IGCSE: 'bg-emerald-100 text-emerald-700', SAT: 'bg-orange-100 text-orange-700',\n  JUPEB: 'bg-purple-100 text-purple-700',\n};\n\nconst TEACHER_NOTES = [\n  'The killer observation classical physics could NOT explain: below the threshold frequency f₀ = φ/h, NO electrons are emitted no matter how intense the light. Try it — set red light on zinc and crank the intensity.',\n  'Light arrives as PHOTONS of energy E = hf. One photon frees at most one electron: hf = φ + KEmax (Einstein, Nobel Prize 1921).',\n  'Intensity controls the NUMBER of photons → the photocurrent. Frequency controls the ENERGY of each electron. Watch: more intensity = more electrons, not faster ones.',\n  'The KEmax–f graph is a straight line with slope h/e (the same for every metal!) and x-intercept f₀. Different metals shift the line, never tilt it.',\n  'Stopping potential Vs: the reverse voltage that just stops the fastest electrons — eVs = KEmax, so Vs in volts equals KEmax in eV.',\n];\n\nconst EXERCISES = [\n  { q: 'Light of frequency 7×10¹⁴ Hz falls on sodium (φ = 2.28 eV). Find the photon energy and KEmax. (h = 6.63×10⁻³⁴ Js, e = 1.6×10⁻¹⁹ C)', a: 'E = hf = 6.63e-34 × 7e14 = 4.64e-19 J = 2.90 eV. KEmax = 2.90 − 2.28 = 0.62 eV ≈ 1.0×10⁻¹⁹ J.' },\n  { q: 'The threshold wavelength of a metal is 500 nm. Find its work function in eV.', a: 'φ = hc/λ₀ = (6.63e-34 × 3e8)/5e-7 = 3.98e-19 J ≈ 2.48 eV.' },\n  { q: 'Doubling the intensity of light on a photocell does what to (a) the current, (b) the KEmax?', a: '(a) Current doubles — twice as many photons free twice as many electrons. (b) KEmax is unchanged — each photon still carries the same energy hf.' },\n  { q: 'For caesium (φ = 2.1 eV) lit at f = 8×10¹⁴ Hz, find the stopping potential.', a: 'E = hf = 3.31 eV. KEmax = 3.31 − 2.1 = 1.21 eV, so Vs = 1.21 V.' },\n];\n\nfunction Slider({ label, unit, value, min, max, step, set, color, note }: {\n  label: string; unit: string; value: number; min: number; max: number;\n  step: number; set: (v: number) => void; color: string; note?: string;\n}) {\n  return (\n    <div className=\"space-y-1.5\">\n      <div className=\"flex justify-between text-xs\">\n        <span className=\"text-gray-500\">{label}</span>\n        <span className=\"font-medium tabular-nums text-gray-800\">{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n      </div>\n      <input type=\"range\" min={min} max={max} step={step} value={value}\n        onChange={e => set(Number(e.target.value))} className=\"w-full\" style={{ accentColor: color }} />\n      {note && <p className=\"text-[10px] text-gray-400\">{note}</p>}\n    </div>\n  );\n}\n\nfunction StatRow({ label, value, unit, color }: { label: string; value: string; unit: string; color: string }) {\n  return (\n    <div className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n      <span className=\"text-xs text-gray-500\">{label}</span>\n      <span className={`text-xs font-semibold tabular-nums ${color}`}>{value} <span className=\"text-gray-400 font-normal\">{unit}</span></span>\n    </div>\n  );\n}\n\n// KEmax vs f graph: straight line of universal slope h/e, x-intercept f₀.\nfunction KEGraph({ phiEV, f14 }: { phiEV: number; f14: number }) {\n  const fMax = 14;\n  const data = useMemo(() => keLine(phiEV, fMax), [phiEV]);\n  const f0 = thresholdF14(phiEV);\n  const ke = keMaxEV(f14, phiEV);\n  return (\n    <ResponsiveContainer width=\"100%\" height={200}>\n      <LineChart data={data} margin={{ top: 8, right: 16, left: 10, bottom: 28 }}>\n        <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n        <XAxis dataKey=\"f\" type=\"number\" tick={{ fontSize: 10 }} domain={[0, fMax]}>\n          <Label value=\"Frequency f (×10¹⁴ Hz)\" position=\"insideBottom\" offset={-16} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </XAxis>\n        <YAxis tick={{ fontSize: 10 }}>\n          <Label value=\"KEmax (eV)\" angle={-90} position=\"insideLeft\" offset={12} style={{ fontSize: 10, fill: '#94a3b8' }} />\n        </YAxis>\n        <Tooltip formatter={(v: unknown) => [Number(v).toFixed(2) + ' eV', 'KEmax']} labelFormatter={f => `f = ${f}×10¹⁴ Hz`} />\n        <Line type=\"linear\" dataKey=\"ke\" stroke=\"#6366f1\" strokeWidth={2} dot={false} isAnimationActive={false} />\n        <ReferenceLine x={f0} stroke=\"#f59e0b\" strokeDasharray=\"4 4\"\n          label={{ value: 'f₀', position: 'top', fontSize: 10, fill: '#d97706' }} />\n        <ReferenceDot x={Math.min(f14, fMax)} y={ke} r={6} fill=\"#ef4444\" stroke=\"#fff\" strokeWidth={2} />\n      </LineChart>\n    </ResponsiveContainer>\n  );\n}\n\nexport default function PhotoelectricPage() {\n  const [isRunning, setIsRunning] = useState(false);\n  const [isPaused, setIsPaused] = useState(false);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const [activeCurricula, setActiveCurricula] = useState(['WAEC', 'IGCSE', 'JUPEB']);\n\n  const [metalIdx, setMetalIdx] = useState(0);\n  const [f14, setF14] = useState(6.0);\n  const [intensity, setIntensity] = useState(5);\n\n  const metal = METALS[metalIdx];\n  const reset = useCallback(() => { setIsRunning(false); setIsPaused(false); }, []);\n  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  useEffect(() => {\n    if (resetTimer.current) clearTimeout(resetTimer.current);\n    resetTimer.current = setTimeout(reset, 80);\n  }, [metalIdx, f14, intensity, reset]);\n\n  const ke = keMaxEV(f14, metal.phi);\n  const f0 = thresholdF14(metal.phi);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 640, 300, 980);\n\n  useTopicPreset(\"simulations-photoelectric-effect\", { \"f14\": setF14,\n    \"intensity\": setIntensity }, {  });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">Modern physics</p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Photoelectric effect</h1>\n              </div>\n              <div className=\"flex gap-1.5 flex-wrap\">\n                {CURRICULA.map(c => (\n                  <button key={c}\n                    onClick={() => setActiveCurricula(p => p.includes(c) ? p.filter(x => x !== c) : [...p, c])}\n                    className={`text-xs px-2.5 py-2 rounded-full border font-medium transition ${\n                      activeCurricula.includes(c) ? CC[c] + ' border-transparent' : 'bg-white text-gray-400 border-gray-200'\n                    }`}>{c}</button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"flex flex-wrap items-center gap-3 rounded-xl border border-gray-200 bg-white px-4 py-2.5\">\n            <span className=\"text-xs text-gray-400\">Einstein&apos;s photoelectric equation</span>\n            <span className=\"text-sm font-semibold font-mono text-gray-900\">hf = φ + KEmax</span>\n            <span className=\"text-xs text-gray-400 ml-2\">f₀ = φ/h &nbsp;|&nbsp; eVs = KEmax</span>\n          </div>\n\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_220px] xl:grid-cols-[minmax(0,1fr)_220px_260px] gap-4\">\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <PhotoelectricCanvas f14={f14} intensity={intensity} phiEV={metal.phi} metalName={metal.name}\n                  isRunning={isRunning} isPaused={isPaused} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center justify-between gap-2\">\n                <SimulationControls isRunning={isRunning} isPaused={isPaused}\n                  onRun={() => { setIsRunning(true); setIsPaused(false); }}\n                  onPause={() => setIsPaused(p => !p)} onReset={reset} />\n                <EmbedButton path=\"/embed/photoelectric\"\n                  title=\"Photoelectric effect — A-Factor STEM Studio\"\n                  params={{ metal: metalIdx, f: f14, i: intensity }} />\n              </div>\n\n              <div data-stage-role=\"extra\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-2\">KEmax against frequency</p>\n                <KEGraph phiEV={metal.phi} f14={f14} />\n                <p className=\"text-[10px] text-gray-400 mt-2 text-center\">\n                  Slope = h/e for EVERY metal · x-intercept = threshold f₀ · red dot = your current light\n                </p>\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm space-y-4\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Parameters</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {METALS.map((m, i) => (\n                    <button key={m.name} onClick={() => setMetalIdx(i)}\n                      className={`rounded-full border px-2.5 py-2 text-[11px] font-medium transition ${\n                        metalIdx === i ? 'border-indigo-300 bg-indigo-50 text-indigo-700' : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-200'\n                      }`}>{m.name} ({m.phi} eV)</button>\n                  ))}\n                </div>\n                <Slider label=\"Light frequency\" unit=\"×10¹⁴ Hz\" value={f14} min={2} max={14} step={0.1} set={setF14} color=\"#6366f1\"\n                  note={`Threshold for ${metal.name}: f₀ = ${f0.toFixed(2)}×10¹⁴ Hz — drop below it and emission stops`} />\n                <Slider label=\"Intensity\" unit=\"\" value={intensity} min={1} max={10} step={1} set={setIntensity} color=\"#f59e0b\"\n                  note=\"Changes how MANY electrons per second — never their energy\" />\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Calculated</p>\n                <div className=\"space-y-2\">\n                  <StatRow label=\"Photon energy hf\" value={photonEnergyEV(f14).toFixed(2)} unit=\"eV\" color=\"text-indigo-600\" />\n                  <StatRow label=\"Wavelength λ\" value={wavelengthNm(f14).toFixed(0)} unit=\"nm\" color=\"text-emerald-600\" />\n                  <StatRow label=\"Work function φ\" value={metal.phi.toFixed(2)} unit=\"eV\" color=\"text-amber-600\" />\n                  <StatRow label=\"Threshold f₀\" value={f0.toFixed(2)} unit=\"×10¹⁴ Hz\" color=\"text-rose-500\" />\n                  <StatRow label=\"KEmax\" value={ke.toFixed(2)} unit=\"eV\" color=\"text-purple-600\" />\n                  <StatRow label=\"Stopping potential\" value={stoppingPotential(f14, metal.phi).toFixed(2)} unit=\"V\" color=\"text-gray-600\" />\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4\">\n                <p className=\"text-xs text-gray-400 mb-2\">Curriculum</p>\n                <div className=\"flex flex-wrap gap-1.5\">\n                  {CURRICULA.map(c => (\n                    <span key={c} className={`text-xs font-medium px-2 py-0.5 rounded-full ${\n                      activeCurricula.includes(c) ? CC[c] : 'bg-gray-100 text-gray-400'\n                    }`}>{c}</span>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/mathematics/unit-circle/page.tsx": "'use client';\nimport { SimulationStage } from '@/components/simulation/SimulationStage';\nimport { useTopicPreset } from '@/lib/explorer/use-topic-preset';\n\nimport { useState, useRef, useCallback, useEffect } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { SimulationControls } from '@/components/simulation/SimulationControls';\nimport { EmbedButton } from '@/components/ui/EmbedButton';\nimport { UnitCircleCanvas } from '@/components/simulation/UnitCircleCanvas';\nimport { UnitCircleGraph } from '@/components/simulation/UnitCircleGraph';\nimport { useResponsiveCanvasSize } from '@/hooks/useResponsiveCanvasSize';\nimport { deg2rad, rad2deg, quadrantOf, QUADRANT_SIGNS } from '@/lib/physics/unitCircle';\n\nconst TEACHER_NOTES = [\n  \"Every point on the unit circle is (cos θ, sin θ) — that's not a coincidence to memorise, it's the actual definition. Drag the point and watch both coordinates update together.\",\n  \"The yellow line is always the point's x-coordinate (cos θ); the red line is always its y-coordinate (sin θ) — the 'projection' picture is the fastest way to see why sin and cos are just shifted copies of each other (90° out of phase).\",\n  \"The sign of sin θ and cos θ in each quadrant follows directly from which coordinates are positive/negative there — no need to memorise 'CAST' or similar mnemonics if students can see why it's true here.\",\n  \"Degrees and radians are just two different rulers measuring the same rotation — 360° and 2π radians are the same full turn. The toggle lets students build intuition for both before an exam forces a quick conversion.\",\n  \"The two graphs below are literally 'unroll the circle onto a line' — dragging the point around the circle traces out exactly the sine and cosine curves, in real time.\",\n];\n\nconst EXERCISES: { q: string; a: string }[] = [\n  { q: 'Convert 150° to radians, giving your answer as a fraction of π.', a: '150° = 150×(π/180) = 5π/6.' },\n  { q: 'Convert 7π/4 radians to degrees.', a: '7π/4 × (180/π) = 315°.' },\n  { q: 'Which quadrant is 210° in, and what are the signs of sin and cos there?', a: 'Quadrant III (180°–270°): both sin and cos are negative.' },\n  { q: 'Using the unit circle, state sin(60°) and cos(60°) exactly (as surds/fractions, not decimals).', a: 'sin(60°) = √3/2, cos(60°) = 1/2.' },\n  { q: 'Explain why sin(150°) = sin(30°), using the unit circle picture.', a: '150° and 30° are reflections of each other across the vertical axis — same height (y-coordinate), so the same sine value. Their cosines are opposite in sign instead.' },\n  { q: 'A point on the unit circle has cos θ = −0.5 and sin θ is positive. Which quadrant is θ in, and what is θ in degrees?', a: 'Quadrant II (cos negative, sin positive) — θ = 120°.' },\n];\n\nexport default function UnitCirclePage() {\n  const [angleDeg, setAngleDeg] = useState(105.86);\n  const [unit, setUnit] = useState<'deg' | 'rad'>('deg');\n  const [animating, setAnimating] = useState(false);\n  const [openEx, setOpenEx] = useState<number | null>(null);\n  const animRef = useRef<number>(0);\n  const lastTsRef = useRef<number | null>(null);\n\n  const canvasBoxRef = useRef<HTMLDivElement>(null);\n  const canvasSize = useResponsiveCanvasSize(canvasBoxRef, 440, 440, 480);\n\n  const toggleAnimate = useCallback(() => {\n    if (animating) {\n      cancelAnimationFrame(animRef.current);\n      setAnimating(false);\n      lastTsRef.current = null;\n      return;\n    }\n    setAnimating(true);\n    const step = (ts: number) => {\n      if (lastTsRef.current !== null) {\n        const dt = (ts - lastTsRef.current) / 1000;\n        setAngleDeg(prev => (prev + dt * 60) % 360); // 60°/s — one full turn every 6s\n      }\n      lastTsRef.current = ts;\n      animRef.current = requestAnimationFrame(step);\n    };\n    animRef.current = requestAnimationFrame(step);\n  }, [animating]);\n\n  useEffect(() => () => cancelAnimationFrame(animRef.current), []);\n\n  const rad = deg2rad(angleDeg);\n  const sinVal = Math.sin(rad), cosVal = Math.cos(rad);\n  const quadrant = quadrantOf(angleDeg);\n  const signs = QUADRANT_SIGNS[quadrant];\n\n  const displayValue = unit === 'deg' ? angleDeg.toFixed(2) : rad2deg(angleDeg) === 0 ? '0' : (rad).toFixed(3);\n  const sliderMax = unit === 'deg' ? 360 : Math.PI * 2;\n  const sliderValue = unit === 'deg' ? angleDeg : rad;\n  const handleSliderChange = (v: number) => {\n    setAngleDeg(unit === 'deg' ? v : rad2deg(v));\n  };\n\n  useTopicPreset(\"mathematics-unit-circle\", { angleDeg: setAngleDeg });\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4\">\n            <div className=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n              <div>\n                <p className=\"text-xs text-gray-400 mb-0.5\">\n                  <Link href=\"/mathematics\" className=\"hover:text-indigo-600 transition\">Mathematics</Link> — Trigonometry\n                </p>\n                <h1 className=\"text-lg font-semibold text-gray-900\">Unit Circle Explorer</h1>\n              </div>\n              <div className=\"flex gap-2\">\n                <span className=\"text-xs px-3 py-1.5 rounded-full font-medium bg-indigo-100 text-indigo-700\">\n                  θ = {angleDeg.toFixed(2)}°\n                </span>\n                <span className=\"text-xs px-3 py-1.5 rounded-full font-medium bg-purple-100 text-purple-700\">\n                  {rad.toFixed(3)} rad\n                </span>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 py-4 space-y-4\">\n          <div className=\"grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_260px] xl:grid-cols-[minmax(0,1fr)_260px_300px] gap-4\">\n\n            <SimulationStage className=\"space-y-3 min-w-0\">\n              <div data-stage-role=\"canvas\" ref={canvasBoxRef} className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm flex justify-center\">\n                <UnitCircleCanvas angleDeg={angleDeg} onAngleChange={setAngleDeg} width={canvasSize.width} height={canvasSize.height} />\n              </div>\n\n              <div data-stage-role=\"playback\" className=\"flex flex-wrap items-center gap-3 rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <SimulationControls\n                  isRunning={animating} isPaused={false}\n                  onRun={toggleAnimate}\n                  onPause={toggleAnimate}\n                  onReset={() => { cancelAnimationFrame(animRef.current); setAnimating(false); lastTsRef.current = null; setAngleDeg(0); }}\n                />\n                <div className=\"flex rounded-lg border border-gray-200 overflow-hidden text-xs\">\n                  <button onClick={() => setUnit('deg')}\n                    className={`px-3 py-1.5 font-medium transition ${unit === 'deg' ? 'bg-indigo-600 text-white' : 'bg-white text-gray-500'}`}>\n                    Degrees\n                  </button>\n                  <button onClick={() => setUnit('rad')}\n                    className={`px-3 py-1.5 font-medium transition ${unit === 'rad' ? 'bg-indigo-600 text-white' : 'bg-white text-gray-500'}`}>\n                    Radians\n                  </button>\n                </div>\n                <EmbedButton path=\"/embed/unit-circle\" params={{ angleDeg }} title=\"Unit Circle Explorer\" />\n              </div>\n\n              <div data-stage-role=\"parameters\" className=\"rounded-2xl border border-gray-200 bg-white p-3 shadow-sm\">\n                <div className=\"flex items-center gap-3\">\n                  <span className=\"text-xs text-gray-500 shrink-0 w-14\">θ ({unit === 'deg' ? '°' : 'rad'})</span>\n                  <input type=\"range\" min={0} max={sliderMax} step={sliderMax / 720} value={sliderValue}\n                    onChange={e => handleSliderChange(Number(e.target.value))}\n                    className=\"flex-1\" style={{ accentColor: '#6366f1' }} />\n                  <span className=\"text-xs font-mono text-gray-500 w-16 text-right\">{displayValue}{unit === 'deg' ? '°' : ''}</span>\n                </div>\n              </div>\n\n              <div data-stage-role=\"extra\" className=\"rounded-2xl border border-gray-200 bg-white p-4 shadow-sm\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-2\">sin θ and cos θ vs angle</p>\n                <UnitCircleGraph angleDeg={angleDeg} />\n              </div>\n            </SimulationStage>\n\n            <div className=\"space-y-3\">\n              <div className=\"rounded-2xl border border-gray-100 bg-white p-4 space-y-2\">\n                <p className=\"text-xs font-medium uppercase tracking-wide text-gray-400 mb-2\">Live readout</p>\n                {[\n                  { l: 'θ (degrees)', v: `${angleDeg.toFixed(2)}°`, c: 'text-indigo-600' },\n                  { l: 'θ (radians)', v: `${rad.toFixed(3)} rad`, c: 'text-purple-600' },\n                  { l: 'sin θ', v: sinVal.toFixed(3), c: 'text-rose-600' },\n                  { l: 'cos θ', v: cosVal.toFixed(3), c: 'text-amber-600' },\n                  { l: 'Quadrant', v: `${['', 'I', 'II', 'III', 'IV'][quadrant]}`, c: 'text-gray-700' },\n                  { l: 'Signs (sin, cos)', v: `(${signs.sin}, ${signs.cos})`, c: 'text-gray-700' },\n                ].map(r => (\n                  <div key={r.l} className=\"flex justify-between items-center rounded-lg bg-gray-50 px-3 py-2\">\n                    <span className=\"text-xs text-gray-500\">{r.l}</span>\n                    <span className={`text-xs font-semibold tabular-nums ${r.c}`}>{r.v}</span>\n                  </div>\n                ))}\n              </div>\n              <p className=\"text-[11px] text-gray-400 px-1\">Drag the point around the circle, or use the slider — try Animate for a continuous sweep.</p>\n            </div>\n\n            <div className=\"space-y-3 lg:col-span-2 xl:col-span-1\">\n              <div className=\"rounded-2xl border border-amber-100 bg-amber-50 p-4\">\n                <p className=\"text-xs font-medium text-amber-700 uppercase tracking-wide mb-3\">📋 Teacher notes</p>\n                <ul className=\"space-y-2\">\n                  {TEACHER_NOTES.map((n, i) => (\n                    <li key={i} className=\"text-xs text-amber-900 leading-relaxed flex gap-2\">\n                      <span className=\"text-amber-400 shrink-0 mt-0.5\">•</span>{n}\n                    </li>\n                  ))}\n                </ul>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-4\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">✏️ Exercises</p>\n                <div className=\"space-y-2\">\n                  {EXERCISES.map((ex, i) => (\n                    <div key={i} className=\"rounded-xl border border-gray-100 overflow-hidden\">\n                      <button onClick={() => setOpenEx(openEx === i ? null : i)}\n                        className=\"w-full text-left px-3 py-2.5 text-xs text-gray-700 leading-relaxed hover:bg-gray-50 transition flex justify-between gap-2\">\n                        <span><span className=\"font-medium text-indigo-600\">Q{i + 1}.</span> {ex.q}</span>\n                        <span className=\"text-gray-300 shrink-0 text-sm\">{openEx === i ? '▲' : '▼'}</span>\n                      </button>\n                      {openEx === i && (\n                        <div className=\"px-3 py-2.5 bg-emerald-50 border-t border-gray-100 text-xs text-emerald-800 leading-relaxed\">\n                          <span className=\"font-medium\">Answer: </span>{ex.a}\n                        </div>\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/components/simulation/simulation-stage.css": ".af-simulation-stage { min-width: 0; max-width: 100%; }\n.af-simulation-stage > * { min-width: 0; }\n.af-stage-body, .af-stage-main, .af-stage-parameters { display: contents; }\n.af-stage-toolbar { display: flex; grid-column: 1 / -1; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .4rem; color: #475569; font-size: .75rem; }\n.af-stage-toolbar button { min-height: 44px; padding: .5rem .75rem; border: 1px solid #cbd5e1; border-radius: .65rem; background: white; color: #3730a3; font-weight: 600; cursor: pointer; }\n.af-stage-toolbar button:focus-visible { outline: 3px solid #f59e0b; outline-offset: 2px; }\n.af-rotate-hint { display: none; font-size: 10px; }\n.af-simulation-stage[data-expanded=\"true\"] { position: fixed; inset: 0; z-index: 1000; display: flex; flex-direction: column; gap: .5rem; width: 100%; max-width: none; height: 100dvh; margin: 0; overflow: hidden; overscroll-behavior: contain; padding: max(.5rem, env(safe-area-inset-top)) max(.5rem, env(safe-area-inset-right)) max(.5rem, env(safe-area-inset-bottom)) max(.5rem, env(safe-area-inset-left)); background: #f8fafc; color: #111827; color-scheme: light; }\n.af-simulation-stage[data-expanded=\"true\"] > .af-stage-toolbar { flex: 0 0 auto; margin: 0; padding-bottom: .25rem; border-bottom: 1px solid #cbd5e1; }\n.af-simulation-stage[data-expanded=\"true\"] .af-stage-body { display: grid; flex: 1 1 0; min-height: 0; min-width: 0; grid-template-columns: minmax(0, 1fr); gap: .75rem; }\n.af-simulation-stage[data-expanded=\"true\"][data-has-parameters=\"true\"] .af-stage-body { grid-template-columns: minmax(0,1fr) clamp(230px, 27vw, 350px); }\n.af-simulation-stage[data-expanded=\"true\"] .af-stage-main { display: flex; flex-direction: column; gap: .5rem; min-height: 0; min-width: 0; overflow: auto; }\n.af-simulation-stage[data-expanded=\"true\"] .af-stage-main > * { margin: 0; min-width: 0; }\n.af-simulation-stage[data-expanded=\"true\"] .af-stage-parameters { display: block; min-height: 0; min-width: 0; overflow: auto; overscroll-behavior: contain; border-left: 1px solid #cbd5e1; padding-left: .75rem; }\n.af-simulation-stage[data-expanded=\"true\"] .af-stage-parameters > * { margin-bottom: .75rem; }\n.af-simulation-stage[data-expanded=\"true\"] [data-stage-role=\"extra\"] { display: none; }\n.af-simulation-stage[data-expanded=\"true\"] [data-stage-role=\"canvas\"] { flex: 1 1 0; min-height: 0; overflow: auto; }\n.af-simulation-stage[data-expanded=\"true\"] [data-stage-role=\"playback\"] { flex: 0 0 auto; }\n.af-simulation-stage[data-expanded=\"true\"] canvas { display: block; width: auto !important; height: auto !important; max-width: 100%; max-height: calc(100dvh - 130px); margin-inline: auto; }\n.af-simulation-stage[data-expanded=\"true\"] [data-embed-button] { display: none; }\n.af-simulation-stage[data-expanded=\"true\"] iframe { width: 100%; height: 100%; min-height: 0; border: 0; }\n.af-simulation-stage:fullscreen { background: #f8fafc; }\n.af-stage-dark[data-expanded=\"true\"], .af-stage-dark[data-expanded=\"true\"] > .af-stage-toolbar { background: #020617; color: #e2e8f0; }\n@media (max-width: 600px) and (orientation: portrait) {\n .af-simulation-stage[data-expanded=\"true\"][data-has-parameters=\"true\"] .af-stage-body { grid-template-columns: minmax(0,1fr); grid-template-rows: minmax(0, 1fr) minmax(130px, 33%); }\n .af-simulation-stage[data-expanded=\"true\"] .af-stage-parameters { border-left: 0; border-top: 1px solid #cbd5e1; padding: .5rem 0 0; }\n .af-simulation-stage[data-expanded=\"true\"] canvas { max-height: 42dvh; }\n .af-rotate-hint { display: inline; }\n}\n@media (orientation: landscape) and (max-height: 600px) {\n .af-simulation-stage[data-expanded=\"true\"] { gap: .25rem; padding: .25rem; }\n .af-simulation-stage[data-expanded=\"true\"][data-has-parameters=\"true\"] .af-stage-body { grid-template-columns: minmax(0,1fr) clamp(200px, 29vw, 270px); gap: .5rem; }\n .af-stage-toolbar button { min-height: 36px; padding: .25rem .5rem; }\n .af-simulation-stage[data-expanded=\"true\"] canvas { max-height: calc(100dvh - 110px); }\n .af-simulation-stage[data-expanded=\"true\"] .af-stage-parameters :is(input,select) { max-width: 100%; }\n}\n.af-simulation-stage[data-expanded=\"true\"] [data-stage-role]:empty { display: none; }\n.af-simulation-stage:not([data-expanded=\"true\"])[class*=\"space-y\"] .af-stage-main > *, .af-simulation-stage:not([data-expanded=\"true\"])[class*=\"space-y\"] .af-stage-parameters > * { margin-top: .75rem; }\n.af-simulation-stage[data-expanded=\"true\"] .af-stage-parameters > .hidden { display: block; }\n.af-geophysics-stage { height: 100%; display: flex; flex-direction: column; gap: .4rem; }\n.af-geophysics-stage [data-stage-role=\"canvas\"] { flex: 1; min-height: 0; }\n.af-geophysics-stage:not([data-expanded=\"true\"]) [data-stage-role=\"canvas\"] iframe { width: 100%; height: 100%; border: 0; }\n.af-simulation-stage[data-expanded=\"true\"] [data-stage-role=\"canvas\"]:has(> [data-stage-role=\"canvas\"]) { display: flex; flex-direction: column; gap: .5rem; }\n.af-simulation-stage[data-expanded=\"true\"] .af-stage-parameters .lg\\:grid-cols-3 { grid-template-columns: minmax(0, 1fr); }\n.af-simulation-stage[data-expanded=\"true\"] .af-stage-parameters .lg\\:sticky { position: static; }\n", "src/components/simulation/SimulationStage.tsx": "'use client';\nimport { Children, isValidElement, useEffect, useRef, useState, type ReactNode } from 'react';\nimport './simulation-stage.css';\n\n/** Keeps the existing simulation mounted while expanding it with its controls. */\nexport function SimulationStage({ children, className = '' }: { children: ReactNode; className?: string }) {\n  const [expanded, setExpanded] = useState(false);\n  const root = useRef<HTMLDivElement>(null);\n  const toggle = useRef<HTMLButtonElement>(null);\n  const previousFocus = useRef<HTMLElement | null>(null);\n  const orientationLocked = useRef(false);\n  const active = useRef(false);\n  const items = Children.toArray(children);\n  const role = (item: ReactNode) => isValidElement<{'data-stage-role'?: string}>(item) ? item.props['data-stage-role'] : undefined;\n  const parameters = items.filter(item => role(item) === 'parameters');\n  const scene = items.filter(item => role(item) !== 'parameters');\n  function unlock() { if (orientationLocked.current) { try { screen.orientation?.unlock(); } catch {} orientationLocked.current = false; } }\n  function close() {\n    active.current = false;\n    unlock();\n    if (document.fullscreenElement === root.current) void document.exitFullscreen().catch(() => {});\n    setExpanded(false);\n  }\n  function open() {\n    active.current = true;\n    previousFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;\n    setExpanded(true);\n    // Request landscape only after native fullscreen succeeds; physical rotation remains available.\n    try {\n      const request = root.current?.requestFullscreen?.();\n      if (request) void request.then(async () => {\n        if (!active.current) { if (document.fullscreenElement === root.current) void document.exitFullscreen().catch(() => {}); return; }\n        if (!window.matchMedia('(pointer: coarse)').matches) return;\n        const orientation = screen.orientation as ScreenOrientation & { lock?: (mode: string) => Promise<void> };\n        try { await orientation.lock?.('landscape'); orientationLocked.current = !!orientation.lock; if (!active.current) unlock(); } catch {}\n      }).catch(() => {});\n    } catch {}\n  }\n  useEffect(() => {\n    if (!expanded) return;\n    const old = document.body.style.overflow;\n    document.body.style.overflow = 'hidden';\n    toggle.current?.focus();\n    const escape = (e: KeyboardEvent) => { if (e.key === 'Escape') { e.preventDefault(); close(); } };\n    const fullscreen = () => { if (!document.fullscreenElement) { active.current = false; unlock(); setExpanded(false); } };\n    document.addEventListener('keydown', escape);\n    document.addEventListener('fullscreenchange', fullscreen);\n    return () => {\n      active.current = false;\n      unlock();\n      document.body.style.overflow = old;\n      document.removeEventListener('keydown', escape);\n      document.removeEventListener('fullscreenchange', fullscreen);\n      previousFocus.current?.focus();\n    };\n  }, [expanded]);\n  return <div ref={root} data-simulation-stage data-expanded={expanded} className={`af-simulation-stage ${className}`} data-has-parameters={parameters.length > 0}\n    role={expanded ? 'dialog' : undefined} aria-modal={expanded || undefined} aria-label={expanded ? 'Classroom simulation view' : undefined}\n    onKeyDown={e => {\n      if (!expanded || e.key !== 'Tab') return;\n      const elements = Array.from(root.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href],iframe,[tabindex=\"0\"]') || []).filter(el => el.getClientRects().length);\n      const first = elements[0], last = elements[elements.length - 1];\n      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); }\n      if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); }\n    }}>\n    <div className=\"af-stage-toolbar\"><span>{expanded ? 'Classroom view' : 'Simulation'}{expanded && <small className=\"af-rotate-hint\"> · Rotate your phone for side-by-side controls</small>}</span>\n      <button ref={toggle} type=\"button\" onClick={expanded ? close : open} aria-expanded={expanded}>{expanded ? 'Exit classroom view ✕' : '⛶ Expand simulation'}</button>\n    </div>\n    <div className=\"af-stage-body\">\n      <div className=\"af-stage-main\">{scene}</div>\n      {parameters.length > 0 && <aside className=\"af-stage-parameters\" aria-label=\"Simulation parameters\">{parameters}</aside>}\n    </div>\n  </div>;\n}\n", "src/components/ai/PromptBar.tsx": "'use client';\nimport { TopicPicker } from '@/components/explorer/TopicPicker';\nimport { SpeechInput } from '@/components/accessibility/SpeechInput';\n\nimport { useEffect, useRef, useState } from 'react';\nimport type { AIPromptResponse } from '@/types/ai';\nimport { getTopic, isLanguage, topics, type Language } from '@/lib/explorer/catalog';\nimport { languageNames, ui } from '@/lib/explorer/locales';\nimport type { ExplorerResult } from '@/lib/explorer/prepare';\nimport { ResultCard } from '@/components/explorer/ResultCard';\ninterface Props { onResult?:(result:AIPromptResponse)=>void; className?:string; }\nexport function PromptBar({onResult,className}:Props) {\n const [language,setLanguage]=useState<Language>('en'),[topicId,setTopicId]=useState(''),[prompt,setPrompt]=useState('');\n const [numbers,setNumbers]=useState<Record<string,string>>({}),[modes,setModes]=useState<Record<string,string>>({});\n const [result,setResult]=useState<ExplorerResult|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);\n const pending=useRef<AbortController|null>(null);const s=ui[language],topic=getTopic(topicId);\n useEffect(()=>{const q=new URLSearchParams(window.location.search),id=q.get('topic'),lang=q.get('lang');if(id&&getTopic(id))setTopicId(id);try{const saved=lang||localStorage.getItem('afactor-simulation-language-v1');if(isLanguage(saved))setLanguage(saved);}catch{}return()=>pending.current?.abort();},[]);\n function reset(){pending.current?.abort();pending.current=null;setBusy(false);setError('');setResult(null);}\n function changeTopic(id:string){reset();setTopicId(id);setNumbers({});setModes({});}\n function changeLanguage(value:Language){reset();setLanguage(value);try{localStorage.setItem('afactor-simulation-language-v1',value);}catch{}}\n async function submit(text=prompt){if(busy||(!text.trim()&&!topicId))return;const controller=new AbortController();pending.current=controller;setBusy(true);setError('');setResult(null);const timer=setTimeout(()=>controller.abort(),15000);\n try {const params:Record<string,number>={};for(const [k,v] of Object.entries(numbers))if(v.trim())params[k]=Number(v);const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({prompt:text,topicId:topicId||undefined,language,params,modes})});const data=await r.json();if(!r.ok)throw Error(data.error||s.error);if(pending.current!==controller)return;setResult(data);\n // Preserve the homepage's existing projectile preview for the compatible standard case.\n if(onResult&&window.location.pathname==='/'&&data.topicId==='simulations-projectile-motion'&&data.modes.mode==='standard'&&data.params.h0===0)onResult({simulationType:'projectile_motion',title:data.title,description:data.explanation,explanation:data.explanation,params:{initialVelocity:data.params.v0,angle:data.params.angle,gravity:data.params.g,mass:1},suggestedFollowUps:[]});\n }catch(e){if(pending.current===controller)setError(e instanceof Error?e.message:s.error);}finally{clearTimeout(timer);if(pending.current===controller){pending.current=null;setBusy(false);}}}\n const sample=topic?`${topic.title}${topic.parameters.length?' '+topic.parameters[0].key+'='+topic.parameters[0].default:''}`:'';\n return <div className={`af-explorer min-w-0 max-w-full ${className || ''}`} style={{colorScheme:'light'}}><div className=\"grid gap-3 md:grid-cols-[minmax(0,1fr)_180px]\">\n  <TopicPicker value={topicId} onChange={changeTopic} label={s.topic} automatic={s.automatic}/>\n  <label className=\"min-w-0 text-xs font-semibold text-gray-800\">{s.language}<select value={language} onChange={e=>changeLanguage(e.target.value as Language)} className=\"mt-1 min-h-11 min-w-0 max-w-full w-full rounded-xl border border-gray-300 bg-white p-3 text-sm text-gray-900\">{Object.entries(languageNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>\n </div><p className=\"my-3 text-xs leading-6 text-emerald-900\">{s.free}</p><SpeechInput language={language} onTranscript={text=>setPrompt(current=>(current+' '+text).trim().slice(0,1200))}/><form onSubmit={e=>{e.preventDefault();void submit();}} className=\"flex flex-col gap-2 sm:flex-row\"><label className=\"sr-only\" htmlFor=\"all-topic-prompt\">{s.prompt}</label><input id=\"all-topic-prompt\" value={prompt} maxLength={1200} onChange={e=>setPrompt(e.target.value)} placeholder={s.prompt} className=\"min-h-11 min-w-0 flex-1 rounded-xl border border-gray-300 bg-white px-4 py-3 text-sm text-gray-900 placeholder:text-gray-600\" /><button disabled={busy||(!prompt.trim()&&!topicId)} className=\"min-h-11 rounded-xl bg-indigo-700 px-5 py-3 text-sm font-semibold text-white disabled:opacity-50\">{busy?'…':s.apply}</button></form>\n {topic&&<details className=\"mt-3 rounded-xl border border-gray-200 bg-white p-4\"><summary className=\"min-h-11 cursor-pointer py-2 text-sm font-medium text-gray-800\">{s.settings} · {topic.parameters.length}</summary><p className=\"my-3 text-xs leading-6 text-gray-700\">{s.omitted} {s.manual}</p><div className=\"grid gap-3 sm:grid-cols-2 lg:grid-cols-3\">{topic.modes.map(m=><label key={m.key} className=\"min-w-0 text-xs text-gray-800\">{s.modes}: {m.key}<select value={modes[m.key]||m.default} onChange={e=>{setResult(null);setModes(old=>({...old,[m.key]:e.target.value}));}} className=\"mt-1 min-h-11 min-w-0 max-w-full w-full rounded-lg border border-gray-300 bg-white p-2\">{m.options.map(v=><option key={v}>{v}</option>)}</select></label>)}{topic.parameters.map(p=><label key={p.key} className=\"min-w-0 text-xs text-gray-800\">{p.label} <code>({p.key})</code><input type=\"number\" step=\"any\" min={p.min} max={p.max} value={numbers[p.key]??''} placeholder={String(p.default)} onChange={e=>{setResult(null);setNumbers(old=>({...old,[p.key]:e.target.value}));}} className=\"mt-1 min-h-11 min-w-0 max-w-full w-full rounded-lg border border-gray-300 bg-white p-2 text-gray-900\" /><span className=\"mt-1 block text-gray-600\">{p.min}–{p.max} {p.unit}</span></label>)}</div></details>}\n <div className=\"mt-3 flex flex-wrap gap-2\">{(topic?[sample]:['Ohm 12 V 6 ohm',\"Newton second law 10 kg 50 N friction2=0\",'Waves f=1 lambda=2','Projectile 30 m/s 45°']).map(text=><button key={text} onClick={()=>{setPrompt(text);void submit(text);}} disabled={busy} className=\"min-h-11 max-w-full rounded-xl border border-gray-300 bg-white px-3 py-2 text-left text-xs leading-5 text-gray-800\">{text}</button>)}</div>\n {error&&<p role=\"alert\" className=\"mt-3 rounded-xl bg-red-50 p-3 text-sm text-red-900\">{error}</p>}{result&&<ResultCard result={result}/>}<p className=\"mt-4 text-xs leading-6 text-gray-600\">{s.notes}</p></div>;\n}\n", "src/components/geophysics/GeophysicsFrame.tsx": "import { SimulationStage } from '@/components/simulation/SimulationStage';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\n\ntype ModuleName = 'lab' | 'earth' | 'solar' | 'tectonics';\n\nconst MODULES: { id: ModuleName; label: string; href: string }[] = [\n  { id: 'lab', label: 'Geophysics lab', href: '/geophysics/lab' },\n  { id: 'earth', label: 'Earth Explorer', href: '/geophysics/earth' },\n  { id: 'solar', label: 'Solar System', href: '/geophysics/solar' },\n  { id: 'tectonics', label: 'Tectonics & Earth’s shape', href: '/geophysics/tectonics' },\n];\n\nexport function GeophysicsFrame({ active, src, title }: {\n  active: ModuleName;\n  src: string;\n  title: string;\n}) {\n  return (\n    <div style={{ height: '100dvh', minHeight: '28rem', display: 'flex', flexDirection: 'column', backgroundColor: '#f4f5f0', colorScheme: 'light', }}>\n      <div className=\"shrink-0\"><AppHeader /></div>\n      <nav aria-label=\"Geophysics modules\" className=\"shrink-0 border-b border-gray-200 bg-white\">\n        <div className=\"mx-auto flex max-w-7xl items-center gap-1 overflow-x-auto px-4 py-2 sm:px-6\">\n          {MODULES.map(module => (\n            <Link key={module.id} href={module.href}\n              aria-current={active === module.id ? 'page' : undefined}\n              className={`whitespace-nowrap rounded-lg px-3 py-2 text-xs font-medium transition focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600 ${active === module.id\n                  ? 'bg-indigo-50 text-indigo-700'\n                  : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900'\n                }`}>\n              {module.label}\n            </Link>\n          ))}\n        </div>\n      </nav>\n      <main aria-label={title} style={{ flex: '1 1 0%', minHeight: 0 }}>\n        <SimulationStage className=\"af-geophysics-stage\">\n        <div data-stage-role=\"canvas\"><iframe allowFullScreen allow=\"fullscreen\" key={src} src={src} title={title}\n          style={{\n            display: 'block', width: '100%', height: '100%', border: 0, backgroundColor: '#f4f5f0',\n            colorScheme: 'light',\n          }} /></div>\n        </SimulationStage>\n      </main>\n    </div>\n  );\n}\n", "src/components/explorer/TopicPicker.tsx": "'use client';\nimport { useEffect, useId, useRef, useState } from 'react';\nimport { topics, getTopic } from '@/lib/explorer/catalog';\n\ntype Props = { value: string; onChange: (id: string) => void; label: string; automatic: string };\nexport function TopicPicker({ value, onChange, label, automatic }: Props) {\n const [open, setOpen] = useState(false), [query, setQuery] = useState('');\n const dialog = useRef<HTMLDialogElement>(null), search = useRef<HTMLInputElement>(null), trigger = useRef<HTMLButtonElement>(null);\n const titleId = useId();\n const selected = getTopic(value);\n const filtered = topics.filter(t => `${t.title} ${t.subject}`.toLowerCase().includes(query.trim().toLowerCase()));\n const colours = { color: '#111827', backgroundColor: '#fff', colorScheme: 'light' as const };\n useEffect(() => {\n  const el = dialog.current; if (!el) return;\n  if (open) { if (!el.open) el.showModal(); search.current?.focus(); }\n  else if (el.open) el.close();\n }, [open]);\n function close() { setOpen(false); trigger.current?.focus(); }\n function choose(id: string) { onChange(id); close(); }\n return <div className=\"min-w-0 text-xs font-semibold text-gray-800\" style={colours}>\n  <span>{label}</span>\n  <button ref={trigger} type=\"button\" aria-haspopup=\"dialog\" aria-expanded={open} onClick={() => { setQuery(''); setOpen(true); }}\n   className=\"mt-1 flex min-h-11 w-full items-center justify-between gap-3 rounded-xl border border-gray-300 p-3 text-left text-sm\" style={colours}>\n   <span>{selected?.title || automatic}</span><span aria-hidden=\"true\">▾</span>\n  </button>\n  <dialog ref={dialog} aria-labelledby={titleId} onCancel={e => { e.preventDefault(); close(); }} onClose={close}\n   onClick={e => { if (e.target === e.currentTarget) { const rect = e.currentTarget.getBoundingClientRect(); if (e.clientX < rect.left || e.clientX > rect.right || e.clientY < rect.top || e.clientY > rect.bottom) close(); } }}\n   className=\"af-topic-picker\" style={colours}>\n   <div className=\"flex items-center justify-between gap-3 border-b border-gray-200 p-3\">\n    <h2 id={titleId} className=\"text-base font-semibold\" style={{color:'#111827'}}>{label}</h2>\n    <button type=\"button\" onClick={close} aria-label=\"Close topic picker\" className=\"min-h-11 rounded-lg border border-gray-300 px-3\" style={colours}>✕</button>\n   </div>\n   <div className=\"p-3\"><label className=\"sr-only\" htmlFor={`${titleId}-search`}>Search topics</label>\n    <input ref={search} id={`${titleId}-search`} type=\"search\" value={query} onChange={e => setQuery(e.target.value)} placeholder=\"Search topics or subjects…\" className=\"min-h-11 w-full rounded-lg border border-gray-300 px-3 text-base font-normal\" style={colours}/>\n    <p role=\"status\" className=\"mt-2 text-xs font-normal\" style={{color:'#475569'}}>{filtered.length} topics</p>\n   </div>\n   <div className=\"af-topic-picker-list\">\n    <button type=\"button\" onClick={() => choose('')} className=\"af-topic-choice\" style={colours}>{automatic}{!value && ' ✓'}</button>\n    {['Physics','Chemistry','Mathematics','Geophysics'].map(subject => {\n     const group = filtered.filter(t => t.subject === subject); if (!group.length) return null;\n     return <section key={subject} aria-label={subject}><h3 style={{color:'#3730a3',background:'#eef2ff',padding:'.6rem .75rem',fontSize:'.8rem'}}>{subject}</h3>\n      {group.map(t => <button key={t.id} type=\"button\" className=\"af-topic-choice\" style={colours} onClick={() => choose(t.id)} aria-pressed={value===t.id}>{t.title}{value === t.id && ' ✓'}</button>)}\n     </section>;\n    })}\n    {!filtered.length && <p className=\"p-4 text-sm font-normal\" style={{color:'#475569'}}>No topics match this search.</p>}\n   </div>\n  </dialog>\n </div>;\n}\n", "src/components/explorer/explorer-mobile.css": "/* Scoped layout rules: keep the explorer inside its container without hiding overflow. */\n.af-explorer, .af-tutor { min-width: 0; max-width: 100%; }\n.af-explorer *, .af-tutor * { box-sizing: border-box; }\n.af-explorer :is(p,h1,h2,h3,h4,summary,button,a,label,code,th,td),\n.af-tutor :is(p,h1,h2,h3,h4,summary,button,a,label,code) {\n  overflow-wrap: anywhere;\n}\n.af-explorer :is(input,select,textarea), .af-tutor :is(input,select,textarea) {\n  max-width: 100%;\n}\n.af-explorer :is(section,article,fieldset,details),\n.af-tutor :is(section,article,fieldset,aside) { min-width: 0; }\n@media (max-width: 767px) {\n  /* 16px fields avoid automatic zoom on mobile Safari. */\n  .af-explorer :is(input,select,textarea), .af-tutor :is(input,select,textarea) { font-size: 16px; }\n  .af-explorer summary { line-height: 1.6; }\n  .af-explorer :is(th,td) { overflow-wrap: anywhere; }\n  .af-device > header > div { height: auto; min-height: 4rem; flex-wrap: wrap; gap: .75rem; padding-block: .75rem; }\n  .af-device > header > div > div { min-width: 0; max-width: 100%; flex-wrap: wrap; gap: .5rem; }\n  .af-device > header h1 { font-size: 1rem; line-height: 1.5; overflow-wrap: anywhere; }\n  .af-device > main { padding: .75rem; }\n}\n\n/* Native modal goes in the browser top layer; no page-layout space is reserved. */\ndialog.af-explainer-modal {\n  width: min(64rem, calc(100vw - 2rem));\n  max-width: none;\n  max-height: calc(100dvh - 2rem);\n  margin: auto;\n  padding: 0;\n  border: 0;\n  border-radius: 1rem;\n  overflow: hidden;\n  box-shadow: 0 24px 80px rgb(15 23 42 / .3);\n}\ndialog.af-explainer-modal::backdrop {\n  background: rgb(15 23 42 / .58);\n  backdrop-filter: blur(3px);\n}\n.af-explainer-shell { max-height: min(90dvh, 54rem); }\n@media (max-width: 639px) {\n  dialog.af-explainer-modal { width: calc(100vw - 1rem); max-height: calc(100dvh - 1rem); border-radius: .75rem; }\n  .af-explainer-shell { max-height: calc(100dvh - 1rem); }\n}\n\n/* Explicit native popup colours, including in OS dark mode. */\n.af-explorer select, .af-explorer select option, .af-explorer select optgroup {\n  color: #111827; background-color: #ffffff; color-scheme: light;\n}\n\n/* The topic list is app-rendered rather than an OS select popup. */\ndialog.af-topic-picker { width: min(38rem, calc(100vw - 1rem)); max-width: none; max-height: calc(100dvh - 1rem); margin: auto; padding: 0; border: 1px solid #cbd5e1; border-radius: 1rem; overflow: hidden; box-shadow: 0 24px 80px #0f172a55; }\ndialog.af-topic-picker::backdrop { background: #0f172a99; }\n.af-topic-picker-list { max-height: min(58dvh, 34rem); overflow: auto; overscroll-behavior: contain; }\n.af-topic-choice { display: block; width: 100%; min-height: 44px; padding: .65rem .75rem; text-align: left; font-size: .9rem; font-weight: 400; border-bottom: 1px solid #e2e8f0; cursor: pointer; }\n.af-topic-choice:hover, .af-topic-choice:focus-visible { background: #eef2ff !important; outline: 2px solid #4f46e5; outline-offset: -2px; }\n.af-topic-choice[aria-pressed=\"true\"] { background: #e0e7ff !important; color: #312e81 !important; font-weight: 600; }\n", "checks/classroom-controls.cjs": "const fs=require('fs'),path=require('path'),vm=require('vm'),ts=require('typescript'),assert=require('assert'),React=require('react'),{renderToStaticMarkup}=require('react-dom/server');\nlet initial=[];const cache=new Map();\nfunction load(file){file=path.resolve(file);if(file.endsWith('.json'))return JSON.parse(fs.readFileSync(file,'utf8'));if(cache.has(file))return cache.get(file).exports;\n const module={exports:{}};cache.set(file,module);\n const requireFile=id=>{if(id==='react'){let i=0;return {...React,useState:v=>[initial[i++]??v,()=>{}],useRef:v=>({current:v}),useEffect:()=>{},useId:()=> 'topic-test'};}if(id.startsWith('@/')){const base='src/'+id.slice(2);return load(fs.existsSync(base+'.ts')?base+'.ts':base+'.tsx');}if(id.endsWith('.css'))return {};if(id.startsWith('.')){let p=path.resolve(path.dirname(file),id);if(!path.extname(p))p+='.ts';return load(p);}return require(id);};\n const code=ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,jsx:ts.JsxEmit.ReactJSX,esModuleInterop:true}}).outputText;\n vm.runInNewContext(code,{module,exports:module.exports,require:requireFile,console});return module.exports;\n}\nconst catalog=JSON.parse(fs.readFileSync('src/lib/explorer/topics-data.json','utf8'));\nfor(const topic of catalog){const s=fs.readFileSync('src/app'+topic.route+'/page.tsx','utf8');assert(s.includes('SimulationStage')||s.includes('GeophysicsFrame'),'fullscreen missing at '+topic.route);}\nfunction nodes(tree){let out=[];function visit(n){if(!React.isValidElement(n))return;out.push(n);React.Children.forEach(n.props.children,visit);}visit(tree);return out;}\ninitial=[false,''];const picker=load('src/components/explorer/TopicPicker.tsx');let chosen;\nlet tree=picker.TopicPicker({value:'',label:'Topic',automatic:'Automatic',onChange:id=>chosen=id});let buttons=nodes(tree).filter(n=>n.type==='button'&&n.props.className==='af-topic-choice');assert.equal(buttons.length,catalog.length+1);for(const b of buttons){assert.equal(b.props.style.color,'#111827');assert.equal(b.props.style.backgroundColor,'#fff');}\nbuttons[1].props.onClick();assert.equal(chosen,catalog.filter(t=>t.subject==='Physics')[0].id);\ninitial=[false,'pendulum'];cache.delete(path.resolve('src/components/explorer/TopicPicker.tsx'));tree=load('src/components/explorer/TopicPicker.tsx').TopicPicker({value:'',label:'Topic',automatic:'Automatic',onChange:()=>{}});buttons=nodes(tree).filter(n=>n.type==='button'&&n.props.className==='af-topic-choice');assert(buttons.length>1&&buttons.length<catalog.length);assert(!nodes(tree).some(n=>n.type==='select'));\nconst canvas=React.createElement('div',{'data-stage-role':'canvas',key:'canvas'},'Canvas');const controls=React.createElement('div',{'data-stage-role':'parameters',key:'parameters'},'Parameters');\nfor(const expanded of [false,true]){initial=[expanded];cache.delete(path.resolve('src/components/simulation/SimulationStage.tsx'));const stage=load('src/components/simulation/SimulationStage.tsx').SimulationStage({children:[canvas,controls]});const list=nodes(stage);assert(list.find(n=>n.props.className==='af-stage-main').props.children[0].props.children==='Canvas');assert(list.find(n=>n.type==='aside').props.children[0].props.children==='Parameters');assert.equal(stage.props['data-expanded'],expanded);assert(renderToStaticMarkup(stage).includes('Simulation parameters'));}\nconsole.log(`PASS: all ${catalog.length} catalogue activities have fullscreen; picker lists/searches/selects topics with explicit contrast; scene/sidebar structure remains stable across expansion.`);\n"},expected={"src/app/chemistry/nuclear/page.tsx": "ad1ab9cc95ea90ba56c5d4108c248298825ff0ff9e8477d50291be8d55d5b513", "src/app/chemistry/periodic-table/page.tsx": "c198597e728ee16ac4c45fafaa3e731ad852e6553b4a29048ba1912710c300cf", "src/app/chemistry/crystal-builder/page.tsx": "f5019cd9e4032237fd31ad04f2a9244bd2f32ee6e9328cf148c2c323ad386ea6", "src/app/chemistry/perovskite-lab/page.tsx": "38b1c75258b867990cbf5772eca20759035a7c888271b6c8416f7852da3f300c", "src/app/chemistry/organic/page.tsx"